    def __init__(
        self,
        chosen_class=PlayerClass.THE_SILENT,
        goal_mode="UNLOCK",
        macro_advisor=None,
    ):
        self.game = Game()
        self.errors = 0
        self.choose_good_card = False
        self.skipped_cards = False
        self.skipped_card_reward_key = None
        self.skipped_card_rewards_remaining = 0
        self.visited_shop = False
        self.shop_visit_key = None
        self.shop_completed_visit_key = None
        self.shop_entry_card_ids = set()
        self.shop_entry_relic_ids = set()
        self.shop_entry_potion_counts = {}
        self.shop_cards_bought = 0
        self.shop_relics_bought = 0
        self.shop_potions_bought = 0
        self.map_route = []
        self.elite_visits_by_act = {}
        self.chosen_class = chosen_class
        self.goal_mode = str(goal_mode or "UNLOCK").upper()
        if self.goal_mode not in {"UNLOCK", "HEART"}:
            raise ValueError(f"unsupported goal mode: {goal_mode}")
        self.priorities = Priority()
        self.combat_planner = FastCombatPlanner(self.priorities)
        self.potions_used_this_turn = {}
        # Keep a second, potion-kind-aware ledger.  The aggregate count is
        # still useful for defensive combinations, but a random potion must
        # not be followed by another unproven random potion merely because a
        # transient frame reported a different turn key.
        self.unproven_potions_used_this_turn = {}
        self._pending_potion_use = None
        self.pending_selection_context = None
        self.pending_hand_selection = None
        self.pending_potion_hand_filter = None
        self._combat_epoch = 0
        self._combat_was_active = False
        # A shop potion replacement is a two-command transaction: first open
        # a belt slot, then buy the exact potion whose value justified that
        # discard.  Keep it separate from GRID/combat selection state so a
        # fresh shop frame cannot silently re-plan to a different bottle.
        self.pending_shop_potion_purchase = None
        self.last_noncombat_decision = {}
        self.macro_advisor = macro_advisor
        self.macro_protocol_context = {}
        self._pending_macro_advice = None
        self.model_run_plan = None
        self._model_run_plan_key = None
        self._model_run_plan_updates = 0
        self._pending_run_plan_advice = None
        self.match_game_first_choice = None
        self.match_game_first_label = None
        self.match_game_waiting_for_resolution = False
        self.match_game_last_signature = None
        self.match_game_last_action_index = None
        self.change_class(chosen_class)

    def change_class(self, new_class):
        self.chosen_class = new_class
        if self.chosen_class == PlayerClass.THE_SILENT:
            self.priorities = SilentPriority()
        elif self.chosen_class == PlayerClass.IRONCLAD:
            self.priorities = IroncladPriority()
        elif self.chosen_class == PlayerClass.DEFECT:
            self.priorities = DefectPowerPriority()
        else:
            self.priorities = random.choice(list(PlayerClass))
        self.combat_planner.set_priorities(self.priorities)

    def set_macro_protocol_context(self, context):
        """Bind adviser output to the same authoritative frame as the action."""

        self.macro_protocol_context = dict(context or {})

    @staticmethod
    def _enum_name(value):
        return getattr(value, "name", str(value) if value is not None else None)

    @staticmethod
    def _macro_description(value):
        text = str(value or "").replace(" NL ", " ").replace("NL", " ")
        text = re.sub(r"#[rgbyp]", "", text, flags=re.IGNORECASE)
        return " ".join(text.split())[:600]

    @staticmethod
    def _macro_resolved_number(card, current_field, base_field=None):
        """Resolve CommunicationMod's negative non-combat sentinels."""

        for field in (current_field, base_field):
            if not field:
                continue
            value = getattr(card, field, None)
            if isinstance(value, bool):
                continue
            try:
                value = int(value)
            except (TypeError, ValueError, OverflowError):
                continue
            if value >= 0:
                return value
        return None

    @staticmethod
    def _macro_counter(value):
        try:
            value = int(value)
        except (TypeError, ValueError, OverflowError):
            return None
        return value if value >= 0 else None

    def _macro_card_facts(self, card):
        damage = self._macro_resolved_number(card, "damage", "base_damage")
        block = self._macro_resolved_number(card, "block", "base_block")
        base_damage = self._macro_resolved_number(card, "base_damage")
        base_block = self._macro_resolved_number(card, "base_block")
        magic_number = self._macro_resolved_number(card, "magic_number")
        try:
            cost = int(getattr(card, "cost", 0) or 0)
        except (TypeError, ValueError, OverflowError):
            cost = None
        cost_kind = (
            "X" if cost == -1
            else "UNPLAYABLE" if cost == -2
            else "ENERGY" if cost is not None and cost >= 0
            else "UNKNOWN"
        )
        description = self._macro_description(
            getattr(card, "description", "")
        )
        for marker, value in (
            ("!D!", damage), ("!B!", block), ("!M!", magic_number)
        ):
            if value is not None:
                description = description.replace(marker, str(value))
        return {
            "instance_id": getattr(card, "uuid", None),
            "card_id": getattr(card, "card_id", None),
            "name": getattr(card, "name", None),
            "type": self._enum_name(getattr(card, "type", None)),
            "rarity": self._enum_name(getattr(card, "rarity", None)),
            "upgrades": int(getattr(card, "upgrades", 0) or 0),
            "cost": cost,
            "cost_kind": cost_kind,
            "damage": damage,
            "base_damage": base_damage,
            "block": block,
            "base_block": base_block,
            "magic_number": magic_number,
            "misc": int(getattr(card, "misc", 0) or 0),
            "exhausts": bool(getattr(card, "exhausts", False)),
            "ethereal": bool(getattr(card, "ethereal", False)),
            "has_target": bool(getattr(card, "has_target", False)),
            "description": description,
            "tags": sorted(self._card_build_tags(card)),
        }

    def _audit_card_instance_facts(self, card, *, include_price=False):
        """Mirror the typed protocol card surface used by the audit join.

        This is deliberately separate from ``_macro_card_facts``: macro
        facts contain derived strategy features, while this object is only
        the stable, protocol-visible card identity/effect target.
        """

        value = {
            "id": getattr(card, "card_id", None),
            "name": getattr(card, "name", None),
            "type": self._enum_name(getattr(card, "type", None)),
            "rarity": self._enum_name(getattr(card, "rarity", None)),
            "upgrades": int(getattr(card, "upgrades", 0) or 0),
            "card_instance_id": getattr(card, "uuid", None),
            "cost": int(getattr(card, "cost", 0) or 0),
            "is_playable": bool(getattr(card, "is_playable", False)),
            "has_target": bool(getattr(card, "has_target", False)),
            "damage": int(getattr(card, "damage", 0) or 0),
            "base_damage": getattr(card, "base_damage", None),
            "block": int(getattr(card, "block", 0) or 0),
            "base_block": getattr(card, "base_block", None),
            "magic_number": int(getattr(card, "magic_number", 0) or 0),
            "exhausts": bool(getattr(card, "exhausts", False)),
            "in_bottle_flame": bool(
                getattr(card, "in_bottle_flame", False)
            ),
            "in_bottle_lightning": bool(
                getattr(card, "in_bottle_lightning", False)
            ),
            "in_bottle_tornado": bool(
                getattr(card, "in_bottle_tornado", False)
            ),
        }
        if include_price:
            value["price"] = int(getattr(card, "price", 0) or 0)
        return value

    @staticmethod
    def _audit_relic_listing_facts(relic):
        return {
            "id": getattr(relic, "relic_id", None),
            "name": getattr(relic, "name", None),
            "counter": int(getattr(relic, "counter", 0) or 0),
            "price": int(getattr(relic, "price", 0) or 0),
        }

    @staticmethod
    def _audit_potion_listing_facts(potion):
        return {
            "id": getattr(potion, "potion_id", None),
            "name": getattr(potion, "name", None),
            "can_use": bool(getattr(potion, "can_use", False)),
            "can_discard": bool(getattr(potion, "can_discard", False)),
            "requires_target": bool(
                getattr(potion, "requires_target", False)
            ),
            "price": int(getattr(potion, "price", 0) or 0),
        }

    def _combat_potion_operation_candidates(self, held_potions):
        """Expose every authoritative held-potion operation."""

        rows = []
        for slot, potion in enumerate(held_potions):
            potion_id = getattr(potion, "potion_id", None)
            potion_token = self._token(potion_id)
            instance_id = self._audit_potion_instance_id(potion, slot)
            for operation, available in (
                ("use", bool(getattr(potion, "can_use", False))),
                ("discard", bool(getattr(potion, "can_discard", False))),
            ):
                if not available:
                    continue
                veto_reason = None
                choice_id = f"potion:{operation}:{slot}:{potion_id}"
                rows.append({
                    "id": choice_id,
                    "choice_id": choice_id,
                    "choice_index": slot,
                    "action": "potion",
                    "operation": operation,
                    "semantic_id": (
                        f"potion-{operation}:{instance_id}:{slot}"
                    ),
                    "label": (
                        f"{operation.title()} "
                        f"{getattr(potion, 'name', potion_id)}"
                    ),
                    "legal": True,
                    "visible": True,
                    "selection_eligible": veto_reason is None,
                    "veto_reason": veto_reason,
                    "reason": (
                        veto_reason
                        or "visible_held_potion_operation"
                    ),
                    "consequences": {
                        "operation": f"{operation}_held_potion",
                        "potion_id": potion_id,
                        "potion_instance_id": instance_id,
                        "potion_slot": slot,
                    },
                })
        return rows

    def _macro_model_run_plan(self):
        """Expose only grounded plan state, never old free-form rationale.

        Feeding a previous model rationale back into later calls amplified a
        bad premise (for example, an Act 1 boss being described as having
        minions).  The selected direction remains useful, but its prose is
        audit output rather than authoritative game state.
        """

        if not isinstance(self.model_run_plan, dict):
            return None
        current_act = int(getattr(self.game, "act", 0) or 0)
        current_boss = str(getattr(self.game, "act_boss", None) or "")
        if (
            int(self.model_run_plan.get("act", -1) or -1) != current_act
            or str(self.model_run_plan.get("boss") or "") != current_boss
        ):
            return None
        return {
            key: self.model_run_plan.get(key)
            for key in (
                "primary", "confidence", "act", "boss", "needs",
                "model_margin",
            )
            if key in self.model_run_plan
        }

    def _potion_slot_capacity(self):
        """Return authoritative potion capacity without assuming three slots."""

        serialized = list(getattr(self.game, "potions", []) or [])
        if serialized:
            # CommunicationMod includes empty ``Potion Slot`` placeholders.
            return len(serialized)
        # Synthetic/legacy frames may omit the entire list.  Infer only in
        # that compatibility case; never override an explicit A11 two-slot
        # list or an explicit Potion Belt five-slot list.
        return (
            2
            if int(getattr(self.game, "ascension_level", 0) or 0) >= 11
            else 3
        ) + (2 if self._has_relic("Potion Belt") else 0)

    def _macro_card_candidate_facts(self, card, profile=None):
        """Add compact, factual deck support to one offered/purchasable card."""

        profile = profile or self._deck_profile()
        facts = self._macro_card_facts(card)
        tags = set(facts.get("tags") or [])
        plan = self._deck_plan_summary(profile)
        role_for_tag = {
            "damage": "frontload",
            "block": "block",
            "draw": "draw",
            "aoe": "aoe",
            "scaling": "scaling",
            "energy": "energy",
        }
        fills_general = sorted({
            role_for_tag[tag]
            for tag in tags
            if tag in role_for_tag
            and role_for_tag[tag] in set(plan.get("needs") or [])
        })
        boss_gaps = set(
            (plan.get("need_horizons") or {}).get("act_boss") or []
        )
        fills_boss = sorted({
            role_for_tag[tag]
            for tag in tags
            if tag in role_for_tag and role_for_tag[tag] in boss_gaps
        })
        unsupported_payoffs = []
        source_only = []
        for archetype, state in (profile.get("archetypes") or {}).items():
            if f"{archetype}:payoff" in tags and (
                self._archetype_source_support(state) < 0.75
            ):
                unsupported_payoffs.append(archetype)
            if (
                f"{archetype}:source" in tags
                and int(state.get("payoffs", 0) or 0) <= 0
            ):
                source_only.append(archetype)
        card_id = getattr(card, "card_id", None)
        facts["deck_context"] = {
            "copies_owned": sum(
                getattr(owned, "card_id", None) == card_id
                for owned in list(getattr(self.game, "deck", []) or [])
            ),
            "fills_general_needs": fills_general,
            "fills_current_boss_gaps": fills_boss,
            "unsupported_payoffs": sorted(unsupported_payoffs),
            "sources_without_current_payoff": sorted(source_only),
        }
        return facts

    def _macro_state(self):
        game = self.game
        profile = self._deck_profile()
        deck_plan = self._deck_plan_summary(profile)
        deck = list(getattr(game, "deck", []) or [])
        card_facts = [
            self._macro_card_facts(card)
            for card in deck
        ]
        deck_card_facts, deck_references = encode_deck(card_facts)
        relics = [
            {
                "id": getattr(relic, "relic_id", None),
                "name": getattr(relic, "name", None),
                "counter": self._macro_counter(
                    getattr(relic, "counter", None)
                ),
                "description": self._macro_description(
                    getattr(relic, "description", "")
                ),
            }
            for relic in list(getattr(game, "relics", []) or [])
        ]
        potions = [
            {
                "id": getattr(potion, "potion_id", None),
                "name": getattr(potion, "name", None),
                "description": self._macro_description(
                    getattr(potion, "description", "")
                ),
                "can_use": bool(getattr(potion, "can_use", False)),
                "can_discard": bool(
                    getattr(potion, "can_discard", False)
                ),
                "requires_target": bool(
                    getattr(potion, "requires_target", False)
                ),
            }
            for potion in list(getattr(game, "potions", []) or [])
        ]
        heart_snapshot = HeartPlan.from_game(
            game, self.goal_mode
        ).snapshot()
        heart_plan = dict(heart_snapshot)
        heart_plan_runtime = {
            "floor_in_act": heart_plan.pop("floor_in_act", 0),
        }
        floor = int(getattr(game, "floor", 0) or 0)
        floor_in_act = max(0, floor % 17)
        costs = [
            int(getattr(card, "cost", 0) or 0)
            for card in deck
            if int(getattr(card, "cost", 0) or 0) >= 0
        ]
        cost_curve = {
            "0": sum(cost == 0 for cost in costs),
            "1": sum(cost == 1 for cost in costs),
            "2": sum(cost == 2 for cost in costs),
            "3_plus": sum(cost >= 3 for cost in costs),
            "X": sum(int(getattr(card, "cost", 0) or 0) == -1 for card in deck),
        }
        try:
            real_potions = list(game.get_real_potions())
        except (AttributeError, TypeError):
            real_potions = [
                potion for potion in list(getattr(game, "potions", []) or [])
                if self._token(getattr(potion, "potion_id", ""))
                not in {"", "potionslot"}
            ]
        potion_capacity = self._potion_slot_capacity()
        sustain_ids = {
            "blackblood", "bloodvial", "bloodyidol", "burningblood",
            "mealticket", "meatonthebone", "pantograph", "selfrepair",
            "toyornithopter",
        }
        sustain_relics = [
            getattr(relic, "relic_id", None)
            for relic in list(getattr(game, "relics", []) or [])
            if self._token(getattr(relic, "relic_id", "")) in sustain_ids
        ]
        screen_type = self._enum_name(getattr(game, "screen_type", None))
        room_phase = self._enum_name(getattr(game, "room_phase", None))
        boss_reward_screen = screen_type == "BOSS_REWARD"
        return {
            # Insertion order is part of the provider-cache layout. Keep slow
            # run facts ahead of HP/floor/decision context so nearby macro
            # decisions with the same deck share the longest useful prefix.
            "ascension": int(getattr(game, "ascension_level", 0) or 0),
            "act": int(getattr(game, "act", 0) or 0),
            "boss": getattr(game, "act_boss", None),
            "keys": {
                "ruby": bool(getattr(game, "has_ruby_key", False)),
                "emerald": bool(getattr(game, "has_emerald_key", False)),
                "sapphire": bool(getattr(game, "has_sapphire_key", False)),
            },
            "deck_card_facts": deck_card_facts,
            "deck": deck_references,
            "deck_plan": deck_plan,
            "relic_catalog": encode_rows(relics, RELIC_CATALOG_COLUMNS),
            "model_run_plan": self._macro_model_run_plan(),
            "heart_plan": heart_plan,
            "potions": encode_rows(potions, POTION_COLUMNS),
            "relic_runtime": encode_rows(relics, RELIC_RUNTIME_COLUMNS),
            "heart_plan_runtime": heart_plan_runtime,
            "run_position": {
                "room_type": str(getattr(game, "room_type", "") or ""),
                "room_phase": room_phase,
                "screen_type": screen_type,
                "floor_in_act": floor_in_act,
                # At the boss-relic screen floor % 17 has wrapped to zero,
                # but the named act boss has already been defeated.  State
                # this explicitly instead of telling the adviser that the old
                # boss is sixteen floors away.
                "act_boss_defeated": boss_reward_screen,
                "floors_to_act_boss": (
                    0 if boss_reward_screen else max(0, 16 - floor_in_act)
                ),
            },
            "resource_summary": {
                "deck_size": len(deck),
                "average_printed_cost": round(
                    sum(costs) / max(1, len(costs)), 3
                ),
                "cost_curve": cost_curve,
                "upgraded_cards": int(profile.get("upgraded", 0) or 0),
                "starter_cards": int(profile.get("starters", 0) or 0),
                "curses": int(profile.get("curses", 0) or 0),
                "energy_relic_support": float(
                    profile.get("energy_relic_support", 0.0) or 0.0
                ),
                "energy_relic_ids": list(
                    profile.get("energy_relic_ids") or []
                ),
                "estimated_energy_each_turn": 3 + sum(
                    1
                    for relic_id in profile.get("energy_relic_ids") or []
                    if self._token(relic_id)
                    not in {
                        "slaverscollar", "nuclearbattery", "hoveringkite",
                    }
                ),
                "conditional_energy_relic_ids": [
                    relic_id
                    for relic_id in profile.get("energy_relic_ids") or []
                    if self._token(relic_id)
                    in {
                        "slaverscollar", "nuclearbattery", "hoveringkite",
                    }
                ],
                "potion_slots": potion_capacity,
                "potions_filled": len(real_potions),
                "healing_blocked": self._has_relic("Mark of the Bloom"),
                "sustain_relic_ids": sustain_relics,
            },
            "gold": int(getattr(game, "gold", 0) or 0),
            "hp": {
                "maximum": int(getattr(game, "max_hp", 0) or 0),
                "current": int(getattr(game, "current_hp", 0) or 0),
            },
            "floor": floor,
        }

    @staticmethod
    def _compact_macro_candidate(candidate):
        """Remove only facts exactly duplicated by the candidate binding."""

        candidate = dict(candidate)
        facts = candidate.get("facts")
        if not isinstance(facts, dict):
            return candidate
        facts = dict(facts)
        candidate_id = str(candidate.get("candidate_id") or "")
        instance_id = facts.get("instance_id")
        if instance_id is not None:
            instance_id = str(instance_id)
            if candidate_id in {
                instance_id,
                f"card:{instance_id}",
                f"grid:{instance_id}",
            }:
                facts.pop("instance_id", None)
        if (
            candidate.get("label") is not None
            and facts.get("name") == candidate.get("label")
        ):
            facts.pop("name", None)
        candidate["facts"] = facts
        return candidate

    def _macro_rank(
        self,
        decision_type,
        candidates,
        rule_choice_ids,
        *,
        count=1,
        hard_constraints=None,
        state_details=None,
    ):
        """Return a bounded adviser reranking of already-legal candidates."""

        if isinstance(rule_choice_ids, str):
            rule_choice_ids = [rule_choice_ids]
        rule_choice_ids = [str(item) for item in rule_choice_ids]
        candidates = [
            self._compact_macro_candidate(item)
            for item in candidates
        ]
        local_scores = {}
        sanitized = []
        for candidate in candidates:
            candidate_id = str(candidate.get("candidate_id"))
            score = candidate.get("local_score")
            if (
                candidate_id in local_scores
                or isinstance(score, bool)
                or not isinstance(score, (int, float))
                or not math.isfinite(float(score))
            ):
                continue
            local_scores[candidate_id] = float(score)
            candidate["candidate_id"] = candidate_id
            candidate["local_score"] = round(float(score), 4)
            sanitized.append(candidate)
        if (
            self.macro_advisor is None
            or not sanitized
            or any(item not in local_scores for item in rule_choice_ids)
        ):
            return rule_choice_ids[:count]

        self._refresh_model_run_plan()
        binding_before = dict(self.macro_protocol_context)
        state = self._macro_state()
        if state_details:
            state["decision_context"] = state_details
        try:
            result = self.macro_advisor.advise(
                decision_type=decision_type,
                character=self._enum_name(self.chosen_class),
                state=state,
                candidates=sanitized,
                rule_choice_id=rule_choice_ids[0],
                hard_constraints=list(hard_constraints or []),
                binding=binding_before,
            )
            advice = result.as_dict()
        except Exception:
            # The model adviser is optional and externally backed. Any client,
            # cache, or response-object failure must fail closed to the proven
            # deterministic choice without leaking provider details to traces.
            self._pending_macro_advice = {
                "status": "fallback",
                "rule_choice_id": rule_choice_ids[0],
                "model_choice_id": None,
                "error_class": "advisor_exception",
                "final_choice_ids": list(rule_choice_ids[:count]),
                "applied": False,
                "latency_ms": 0,
                "usage": {},
            }
            return rule_choice_ids[:count]
        advice["final_choice_ids"] = list(rule_choice_ids[:count])
        advice["applied"] = False
        advice["decision_type"] = str(decision_type)
        advice["replay"] = {
            "state": state,
            "candidates": sanitized,
            "rule_choice_ids": list(rule_choice_ids),
            "selection_count": int(count),
            "hard_constraints": list(hard_constraints or []),
        }
        if self._pending_run_plan_advice is not None:
            advice["run_plan_update"] = self._pending_run_plan_advice
            self._pending_run_plan_advice = None
        advice["active_run_plan"] = self.model_run_plan

        if (
            result.status == "recommended"
            and self.macro_advisor.config.mode == "assist"
        ):
            policy = self.macro_advisor.config.decision_policy(decision_type)
            if binding_before != self.macro_protocol_context:
                advice["status"] = "stale"
                advice["error_class"] = "stale_binding"
            else:
                model_scores = {
                    item["candidate_id"]: float(item["score"])
                    for item in result.rankings
                }
                ordered_model_scores = sorted(
                    model_scores.values(), reverse=True
                )
                model_low = min(ordered_model_scores)
                model_high = max(ordered_model_scores)
                model_span = model_high - model_low
                model_margin = (
                    model_high - ordered_model_scores[1]
                    if len(ordered_model_scores) > 1 else 100.0
                )
                rule_id = rule_choice_ids[0]
                model_choice_id = result.model_choice_id
                model_vs_rule_gap = (
                    model_scores.get(model_choice_id, model_low)
                    - model_scores.get(rule_id, model_low)
                )
                confidence = float(result.confidence or 0.0)
                rank_bonus = {
                    candidate_id: (
                        0.0 if model_span <= 0.0 else
                        policy.bonus_cap * confidence
                        * (score - model_low) / model_span
                    )
                    for candidate_id, score in model_scores.items()
                }
                fusion_rows = []
                for candidate in sanitized:
                    candidate_id = candidate["candidate_id"]
                    local_score = local_scores[candidate_id]
                    bonus = rank_bonus.get(candidate_id, 0.0)
                    fusion_rows.append({
                        "candidate_id": candidate_id,
                        "local_score": round(local_score, 4),
                        "model_score": round(
                            model_scores.get(candidate_id, model_low), 4
                        ),
                        "model_bonus": round(bonus, 4),
                        "adjusted_score": round(local_score + bonus, 4),
                    })
                advice["fusion"] = {
                    "model_margin": round(model_margin, 4),
                    "model_vs_rule_gap": round(model_vs_rule_gap, 4),
                    "model_span": round(model_span, 4),
                    "candidates": fusion_rows,
                }
                adjusted = sorted(
                    sanitized,
                    key=lambda item: (
                        local_scores[item["candidate_id"]]
                        + rank_bonus.get(item["candidate_id"], 0.0),
                        local_scores[item["candidate_id"]],
                        item["candidate_id"],
                    ),
                    reverse=True,
                )
                if count == 1:
                    # A single-choice adviser recommends exactly one
                    # alternative.  Do not let the model's global top-two
                    # margin authorize an unrelated third candidate whose
                    # local score happens to win after a small rank bonus.
                    # This occurred in a live shop: the model strongly chose
                    # Lee's Waffle, while fusion bought Skill Potion over the
                    # locally selected Energy Potion even though both potions
                    # received the same low model score.  Compare only the
                    # local rule and the model top, and preserve the rule on
                    # an adjusted-score tie.
                    proposed = [rule_id]
                    if (
                        model_choice_id in local_scores
                        and model_choice_id != rule_id
                        and (
                            local_scores[model_choice_id]
                            + rank_bonus.get(model_choice_id, 0.0)
                        ) > (
                            local_scores[rule_id]
                            + rank_bonus.get(rule_id, 0.0)
                        )
                    ):
                        proposed = [model_choice_id]
                else:
                    proposed = [
                        item["candidate_id"] for item in adjusted[:count]
                    ]
                local_order = sorted(
                    local_scores,
                    key=lambda item: (local_scores[item], item),
                    reverse=True,
                )
                local_cutoff = local_scores[
                    local_order[min(count, len(local_order)) - 1]
                ]
                local_regret = max(
                    0.0,
                    local_cutoff - local_scores.get(
                        model_choice_id, local_cutoff
                    ),
                )
                advice["fusion"]["local_regret"] = round(
                    local_regret, 4
                )
                strong_direct = (
                    count == 1
                    and model_choice_id in local_scores
                    and model_choice_id != rule_id
                    and confidence >= policy.direct_confidence
                    and model_margin >= policy.direct_model_margin
                    and model_vs_rule_gap >= policy.direct_model_margin
                    and local_regret <= policy.regret_cap
                )
                if strong_direct:
                    proposed = [model_choice_id]
                # Adding a permanent card is irreversible while Skip/Bowl is
                # an explicit local abstention backed by the deck-size and
                # marginal-value model.  A medium-confidence rank bonus must
                # not silently turn that abstention into filler.  The adviser
                # can still correct a genuinely missed premium card through
                # the stricter direct-override gate above.
                abstention_guard = bool(
                    decision_type == "CARD_REWARD"
                    and rule_id in {"skip", "bowl"}
                    and proposed
                    and proposed[0] not in {"skip", "bowl"}
                    and not strong_direct
                )
                excessive_regret = any(
                    local_cutoff - local_scores[item] > policy.regret_cap
                    for item in proposed
                )
                if model_choice_id == rule_id:
                    advice["status"] = "agreed"
                elif result.confidence is None or confidence < policy.confidence:
                    advice["status"] = "low_confidence"
                elif model_span <= 0.0 or model_margin < policy.min_model_margin:
                    advice["status"] = "insufficient_model_margin"
                elif decision_type == "GRID" and count > 1:
                    advice["status"] = "multi_select_local_only"
                elif abstention_guard:
                    advice["status"] = "abstention_guard"
                elif excessive_regret:
                    advice["status"] = "regret_cap"
                elif proposed == rule_choice_ids[:count]:
                    advice["status"] = "no_change"
                else:
                    rule_choice_ids = proposed
                    advice["status"] = "applied"
                    advice["applied"] = True
                    advice["final_choice_ids"] = list(proposed)
        self._pending_macro_advice = advice
        return rule_choice_ids[:count]

    def _refresh_model_run_plan(self):
        """Refresh a soft, persistent deck direction at real milestones.

        This is advisory metadata rather than a game action.  It may add a
        small marginal-value bonus later, but it can never make an illegal
        card, relic, route, or purchase eligible.
        """

        act = int(getattr(self.game, "act", 0) or 0)
        boss = getattr(self.game, "act_boss", None)
        if (
            isinstance(self.model_run_plan, dict)
            and (
                int(self.model_run_plan.get("act", -1) or -1) != act
                or str(self.model_run_plan.get("boss") or "")
                != str(boss or "")
            )
        ):
            # Expiry is a state-integrity operation, not a provider call. It
            # must run even after the four-call planning budget is exhausted.
            self.model_run_plan = None
            self._model_run_plan_key = None

        advisor = self.macro_advisor
        if advisor is None:
            return
        config = getattr(advisor, "config", None)
        if (
            config is None
            or config.mode == "off"
            or "RUN_PLAN" not in set(config.assist_scopes)
        ):
            return
        local_plan = self._deck_plan_summary()
        if isinstance(self.model_run_plan, dict):
            # Needs are derived from the current deck, not immutable model
            # output. Keep them fresh even when no further provider update is
            # available in this act.
            self.model_run_plan["needs"] = list(
                local_plan.get("needs") or []
            )
        if self._model_run_plan_updates >= 4:
            return
        local_primary = str(local_plan.get("primary") or "balanced")
        archetypes = local_plan.get("archetypes") or {}
        top_name, top_state = max(
            archetypes.items(),
            key=lambda item: float((item[1] or {}).get("signal", 0.0) or 0.0),
            default=("none", {}),
        )
        top_sources = float((top_state or {}).get("source_reliability", 0.0) or 0.0)
        top_payoffs = int((top_state or {}).get("payoffs", 0) or 0)
        support_stage = (
            "paired" if top_sources >= 0.75 and top_payoffs > 0
            else "source_only" if top_sources >= 0.75
            else "payoff_only" if top_payoffs > 0
            else "none"
        )
        key = (
            act,
            str(boss or ""),
            local_primary,
            tuple(sorted(str(item) for item in local_plan.get("needs") or [])),
            tuple(sorted(
                (
                    str(role),
                    int(float(gap or 0.0) * 10),
                )
                for role, gap in (
                    (local_plan.get("readiness") or {}).get("gaps") or {}
                ).items()
            )),
            str((local_plan.get("commitment") or {}).get("phase") or "explore"),
            top_name,
            support_stage,
            int(float((top_state or {}).get("signal", 0.0) or 0.0) // 2),
        )
        if key == self._model_run_plan_key:
            return
        self._model_run_plan_key = key
        definitions = self.ARCHETYPE_DEFINITIONS.get(
            self.chosen_class, {}
        )
        candidates = [{
            "candidate_id": "plan:balanced",
            "kind": "run_plan",
            "label": "balanced",
            "local_score": 2.0,
            "facts": {
                "needs": list(local_plan.get("needs") or []),
                "need_horizons": dict(
                    local_plan.get("need_horizons") or {}
                ),
                "roles": dict(local_plan.get("roles") or {}),
                "boss_readiness": dict(
                    local_plan.get("boss_readiness") or {}
                ),
            },
        }]
        for name in sorted(definitions):
            state = archetypes.get(name) or {}
            candidates.append({
                "candidate_id": f"plan:{name}",
                "kind": "run_plan",
                "label": name,
                "local_score": float(state.get("signal", 0.0) or 0.0),
                "facts": {
                    "sources": int(state.get("sources", 0) or 0),
                    "source_reliability": float(
                        state.get("source_reliability", 0.0) or 0.0
                    ),
                    "payoffs": int(state.get("payoffs", 0) or 0),
                    "relic_support": float(
                        state.get("relic_support", 0.0) or 0.0
                    ),
                    "needs": list(local_plan.get("needs") or []),
                    "support_stage": (
                        "paired"
                        if float(state.get("source_reliability", 0.0) or 0.0) >= 0.75
                        and int(state.get("payoffs", 0) or 0) > 0
                        else "source_only"
                        if float(state.get("source_reliability", 0.0) or 0.0) >= 0.75
                        else "payoff_only"
                        if int(state.get("payoffs", 0) or 0) > 0
                        else "none"
                    ),
                },
            })
        rule_id = f"plan:{local_plan.get('primary', 'balanced')}"
        if rule_id not in {item["candidate_id"] for item in candidates}:
            rule_id = "plan:balanced"
        state = self._macro_state()
        state["decision_context"] = {
            "purpose": "persistent_soft_deck_direction",
            "maximum_updates_per_run": 4,
            "updates_used": self._model_run_plan_updates,
        }
        try:
            result = advisor.advise(
                decision_type="RUN_PLAN",
                character=self._enum_name(self.chosen_class),
                state=state,
                candidates=candidates,
                rule_choice_id=rule_id,
                hard_constraints=[
                    "ADVISORY_PLAN_ONLY",
                    "DO_NOT_ASSUME_UNOFFERED_CARDS_OR_RELICS",
                    "BALANCED_IS_VALID_WHEN_ENGINE_SUPPORT_IS_WEAK",
                ],
                binding=dict(self.macro_protocol_context),
            )
            self._pending_run_plan_advice = result.as_dict()
        except Exception:
            self._pending_run_plan_advice = {
                "status": "fallback",
                "error_class": "advisor_exception",
            }
            return
        if result.status != "recommended":
            return
        policy = config.decision_policy("RUN_PLAN")
        rankings = sorted(
            result.rankings,
            key=lambda item: float(item.get("score", 0.0)),
            reverse=True,
        )
        margin = (
            float(rankings[0]["score"]) - float(rankings[1]["score"])
            if len(rankings) > 1 else 100.0
        )
        if (
            float(result.confidence or 0.0) < policy.confidence
            or margin < policy.min_model_margin
        ):
            return
        chosen = str(result.model_choice_id or rule_id)
        candidates_by_id = {
            item["candidate_id"]: item for item in candidates
        }
        if chosen not in candidates_by_id:
            return
        chosen_facts = candidates_by_id[chosen].get("facts") or {}
        if (
            chosen != "plan:balanced"
            and chosen_facts.get("support_stage") != "paired"
        ):
            # A persistent direction needs both a reliable engine source and
            # an observed payoff.  One speculative payoff/source (or a relic
            # with no cards to use it) may still affect marginal card scores,
            # but cannot lock the whole run into an archetype.
            return
        # Only a recommendation that passes provider, confidence, margin,
        # identity, and structural-support validation consumes one of the
        # four useful planning milestones.
        self._model_run_plan_updates += 1
        self.model_run_plan = {
            "primary": chosen.split(":", 1)[-1],
            "confidence": round(float(result.confidence or 0.0), 3),
            "reason_codes": list(result.reason_codes or []),
            "rationale": str(result.rationale or "")[:400],
            "act": act,
            "boss": boss,
            "needs": list(local_plan.get("needs") or []),
            "model_margin": round(margin, 3),
        }

    def handle_error(self, error):
        raise Exception(error)

    def _authoritative_hand_replan_before_potions(
        self, planned_action, planned_loss
    ):
        """Return evidence when a safe card should reveal the hand first.

        Potion scoring sees the current authoritative hand, while a bounded
        plan may include a later draw/discard/exhaust action whose concrete
        result is deliberately deferred to the next frame. If the current
        no-potion line is already nonlethal, spending any bottle against that
        pre-reveal loss can be pure waste (notably Block Potion immediately
        before Battle Trance reveals a Slime Boss split). Execute one planned
        card, then price every potion again from the refreshed state.
        """

        if (
            not isinstance(planned_action, PlayCardAction)
            or planned_loss is None
        ):
            return None
        usable_potion_ids = [
            getattr(potion, "potion_id", None)
            for potion in list(self.game.get_real_potions() or [])
            if bool(getattr(potion, "can_use", False))
        ]
        if not usable_potion_ids:
            return None
        hp = max(
            1, int(getattr(self.game.player, "current_hp", 1) or 1)
        )
        if int(planned_loss) >= hp:
            # A genuinely lethal line must retain immediate access to every
            # proven rescue; never postpone a potion across even one card.
            return None

        decision = self.combat_planner.last_decision or {}
        search = decision.get("search") or {}
        time_warp_remaining = self.combat_planner._time_warp_remaining(
            self.game
        )
        # The search already resolves Echo Form, Burst, Double Tap, and
        # Duplication Power into this exact count. Reuse that evidence rather
        # than reconstructing only one of the copy mechanisms here.
        first_resolutions = max(
            1, int(search.get("first_action_resolution_count", 1) or 1)
        )
        if (
            time_warp_remaining is not None
            and time_warp_remaining <= first_resolutions
        ):
            # Time Warp would end the turn before the promised reframe could
            # still use a defensive potion.
            return None

        hand = list(getattr(self.game, "hand", []) or [])
        cards_by_uuid = {
            getattr(card, "uuid", None): card
            for card in hand
            if getattr(card, "uuid", None)
        }
        planned_sequence = [
            item
            for item in (
                decision.get("planned_sequence")
                or []
            )
            if isinstance(item, dict)
        ]
        hand_replan_ids = (
            FastCombatPlanner.TERMINAL_PLAN_UNSAFE_HAND_CARDS
            - {"amplify", "bouncingflask", "burst"}
        )
        heatsinks = combat_predictor.power_amount(
            self.game.player, "Heatsinks", "HeatsinksPower"
        )
        for index, item in enumerate(planned_sequence):
            card_uuid = item.get("card_uuid")
            card = cards_by_uuid.get(card_uuid)
            if card is None:
                continue
            card_id = self._token(getattr(card, "card_id", ""))
            draw_count = self.combat_planner._card_draw_count(
                card,
                self.game,
                hand_size_before_play=len(hand),
            )
            if (
                card_id in hand_replan_ids
                or draw_count > 0
                or (
                    heatsinks > 0
                    and getattr(card, "type", None)
                    == spirecomm.spire.card.CardType.POWER
                )
            ):
                return {
                    "trigger_card_id": getattr(card, "card_id", None),
                    "trigger_card_uuid": card_uuid,
                    "trigger_sequence_index": int(index),
                    "trigger_draw_count": int(draw_count),
                    "planned_loss": int(planned_loss),
                    "player_hp": int(hp),
                    "time_warp_remaining": time_warp_remaining,
                    "deferred_potion_ids": usable_potion_ids,
                }
        return None

    def get_next_action_in_game(self, game_state):
        in_combat = bool(getattr(game_state, "in_combat", False))
        new_combat = in_combat and not self._combat_was_active
        if new_combat:
            self._combat_epoch += 1
            self.pending_potion_hand_filter = None
            # FastCombatPlanner's legacy combat key is only act/floor/room.
            # Chained event fights can share all three, so explicitly reset
            # the two pieces of per-combat memory at the observed boundary.
            self.combat_planner.focus_key = None
            self.combat_planner.combat_key = None
            self.combat_planner._reactive_progress_pending = None
            self.combat_planner._card_play_turn_key = None
            self.combat_planner._confirmed_cards_played = 0
            self.combat_planner._confirmed_card_resolutions = 0
            self.combat_planner._card_play_pending_uuid = None
            self.combat_planner._card_play_pending_resolutions = 1
            self.combat_planner._clear_terminal_plan()
        self._combat_was_active = in_combat
        self.game = game_state
        self._expire_bottled_relic_reward_grid_context()
        self.last_noncombat_decision = {}
        self._pending_macro_advice = None
        #time.sleep(0.07)
        # An exhausted shop advertises only CANCEL, so the generic command
        # fallback below would leave without recording that this visit was
        # completed.  The following SHOP_ROOM frame would then reopen the
        # merchant forever.  Always route shop screens through the dedicated
        # policy, even when no purchase choice is currently legal.
        if self.game.screen_type == ScreenType.SHOP_SCREEN:
            return self.choose_shop_action()
        if self.game.choice_available:
            return self.handle_screen()
        if self.game.proceed_available:
            return ProceedAction()
        if self.game.play_available:
            duplication_action = self._bound_duplication_card_action()
            if duplication_action is not None:
                self.combat_planner.last_decision = (
                    self._bound_duplication_card_decision(duplication_action)
                )
                return duplication_action
            incoming = self.get_incoming_damage()
            # Plan the authoritative hand before spending a defensive potion.
            # Scoring a potion against a naked END can otherwise consume it
            # even when the exact ordered card line already ends the combat or
            # prevents every point of loss. The plan is read-only and can be
            # returned directly when no potion is warranted.
            planned_action = self.get_play_card_action()
            planned_loss = self._planned_turn_hp_loss(
                planned_action, self.combat_planner.last_decision
            )
            if isinstance(planned_action, PlayCardAction) and planned_loss is None:
                # Every supported planner play path carries terminal search
                # metadata. If a future path does not, preserve the card plan
                # rather than comparing any potion with a naked END state.
                return planned_action
            search = self.combat_planner.last_decision.get("search") or {}
            combat_ends = (
                bool(search.get("true_combat_end"))
            ) or (
                self.combat_planner.last_decision.get("reason")
                == "all_enemies_passively_doomed"
            )
            if (
                planned_loss == 0
                and combat_ends
            ):
                return planned_action
            hand_replan = self._authoritative_hand_replan_before_potions(
                planned_action, planned_loss
            )
            planned_decision = copy.deepcopy(
                self.combat_planner.last_decision or {}
            )
            prior_pending_potion_use = self._pending_potion_use
            prior_selection_context = self.pending_selection_context
            potion_action = self.use_best_potion(
                incoming,
                planned_turn_loss=planned_loss,
                planned_action=planned_action,
                planned_combat_end=combat_ends,
            )
            if potion_action is not None:
                potion_id = self._token(
                    getattr(potion_action.potion, "potion_id", "")
                )
                if (
                    hand_replan is not None
                    and potion_id
                    in self.AUTHORITATIVE_HAND_REPLAN_DEFER_POTION_IDS
                ):
                    # use_best_potion records a pending transaction before
                    # returning. No potion was actually sent, so roll those
                    # transient bindings back and keep the card plan.
                    potion_decision = dict(
                        self.combat_planner.last_decision or {}
                    )
                    self._pending_potion_use = prior_pending_potion_use
                    self.pending_selection_context = (
                        prior_selection_context
                    )
                    decision = planned_decision
                    decision.update({
                        "reason": (
                            "defer_potion_until_authoritative_hand_replan"
                        ),
                        "potion_evaluation_deferred": True,
                        "potion_deferred_id": getattr(
                            potion_action.potion, "potion_id", None
                        ),
                        "potion_deferred_score": potion_decision.get(
                            "potion_score"
                        ),
                        "potion_deferred_original_reason": (
                            potion_decision.get("reason")
                        ),
                        "potion_defer_trigger_card_id": hand_replan[
                            "trigger_card_id"
                        ],
                        "potion_defer_trigger_card_uuid": hand_replan[
                            "trigger_card_uuid"
                        ],
                        "potion_defer_trigger_sequence_index": hand_replan[
                            "trigger_sequence_index"
                        ],
                        "potion_defer_trigger_draw_count": hand_replan[
                            "trigger_draw_count"
                        ],
                        "planned_turn_hp_loss": hand_replan[
                            "planned_loss"
                        ],
                        "potion_defer_player_hp": hand_replan["player_hp"],
                        "potion_defer_time_warp_remaining": hand_replan[
                            "time_warp_remaining"
                        ],
                        "potion_available_ids": list(
                            hand_replan["deferred_potion_ids"]
                        ),
                        "potion_operation_candidates": list(
                            potion_decision.get(
                                "potion_operation_candidates"
                            )
                            or []
                        ),
                    })
                    self.combat_planner.last_decision = decision
                    return planned_action
                return potion_action
            return planned_action
        if self.game.end_available:
            end_search = self.combat_planner.project_end_turn(self.game)
            attack_loss = int(
                end_search.get("projected_attack_hp_loss", 0) or 0
            )
            end_turn_loss = int(
                end_search.get("projected_end_turn_hp_loss", 0) or 0
            )
            next_turn_start_loss = int(
                end_search.get(
                    "projected_next_turn_start_hp_loss", 0
                ) or 0
            )
            total_loss = int(
                end_search.get(
                    "actual_loss",
                    attack_loss + end_turn_loss + next_turn_start_loss,
                ) or 0
            )
            end_action = EndTurnAction()
            self.combat_planner.last_decision = {
                "reason": "play_phase_exhausted",
                "projected_attack_hp_loss": attack_loss,
                "projected_end_turn_hp_loss": end_turn_loss,
                "projected_next_turn_start_hp_loss": next_turn_start_loss,
                "projected_hp_loss": total_loss,
                "search": end_search,
            }
            potion_action = self.use_best_potion(
                self.get_incoming_damage(),
                planned_turn_loss=total_loss,
                planned_action=end_action,
                planned_combat_end=bool(
                    end_search.get("true_combat_end")
                ),
            )
            if potion_action is not None:
                return potion_action
            return end_action
        if self.game.cancel_available:
            return CancelAction()

    def get_next_action_out_of_game(self):
        return StartGameAction(self.chosen_class)

    def is_monster_attacking(self):
        for monster in combat_predictor.active_monsters(self.game):
            if monster.intent.is_attack() or monster.intent == Intent.NONE:
                return True
        return False

    def get_incoming_damage(self):
        return combat_predictor.incoming_damage(self.game)

    def get_low_hp_target(self):
        return combat_predictor.choose_attack_target(self.game)

    def get_high_hp_target(self):
        available_monsters = combat_predictor.active_monsters(self.game)
        if not available_monsters:
            available_monsters = combat_predictor.living_monsters(self.game)
        best_monster = max(available_monsters, key=lambda x: x.current_hp)
        return best_monster

    def many_monsters_alive(self):
        available_monsters = combat_predictor.active_monsters(self.game)
        return len(available_monsters) > 1

    def get_play_card_action(self):
        action = self.combat_planner.choose_card_action(self.game)
        decision = self.combat_planner.last_decision
        if decision:
            decision["_combat_context"] = self._combat_plan_context()
        return action

    def legacy_get_play_card_action(self):
        playable_cards = [card for card in self.game.hand if card.is_playable]
        all_living_monsters = combat_predictor.living_monsters(self.game)
        living_monsters = combat_predictor.active_monsters(self.game)
        if not living_monsters and all_living_monsters and combat_predictor.safe_to_wait_for_passive_kills(self.game):
            return EndTurnAction()
        if not living_monsters:
            living_monsters = all_living_monsters
        if len(playable_cards) == 0 or len(living_monsters) == 0:
            return EndTurnAction()

        incoming = self.get_incoming_damage()
        uncovered = max(0, incoming - combat_predictor.projected_player_block(self.game))
        act_budget = {1: 8, 2: 4, 3: 2, 4: 0}.get(self.game.act, 2)
        risk_budget = min(act_budget, max(0, self.game.player.current_hp // 8))

        def effective_damage(card):
            return combat_predictor.card_attack_profile(self.game, card)[0]

        attack_cards = [
            card for card in playable_cards
            if card.type == spirecomm.spire.card.CardType.ATTACK and effective_damage(card) > 0
        ]
        energy = self.game.player.energy
        lethal_sets = []
        for target in living_monsters:
            for mask in range(1, 1 << len(attack_cards)):
                chosen = [attack_cards[index] for index in range(len(attack_cards)) if mask & (1 << index)]
                cost = sum(combat_predictor.card_energy_cost(self.game, card) for card in chosen)
                damage = sum(effective_damage(card) for card in chosen)
                hits = sum(combat_predictor.card_attack_profile(self.game, card)[1] for card in chosen)
                hp_loss = combat_predictor.attack_hp_loss(
                    target,
                    damage,
                    hits=hits,
                    **combat_predictor.attack_relic_modifiers(self.game),
                )
                if cost <= energy and hp_loss >= target.current_hp:
                    lethal_sets.append((
                        -combat_predictor.monster_threat(target),
                        len(chosen),
                        cost,
                        -damage,
                        target,
                        chosen,
                    ))
        if lethal_sets:
            _, _, _, _, target, chosen = min(lethal_sets, key=lambda item: item[:4])
            card_to_play = max(chosen, key=lambda card: effective_damage(card))
            if card_to_play.has_target:
                return PlayCardAction(card=card_to_play, target_monster=target)
            return PlayCardAction(card=card_to_play)

        lethal_attacks = [
            card for card in playable_cards
            if card.type == spirecomm.spire.card.CardType.ATTACK
            and effective_damage(card) > 0
            and any(
                combat_predictor.attack_hp_loss(
                    monster,
                    effective_damage(card),
                    **combat_predictor.attack_relic_modifiers(self.game),
                ) >= monster.current_hp
                for monster in living_monsters
            )
        ]
        if lethal_attacks:
            card_to_play = max(lethal_attacks, key=lambda card: (effective_damage(card), -max(card.cost, 0)))
            if not card_to_play.has_target:
                return PlayCardAction(card=card_to_play)
            killable = [
                monster for monster in living_monsters
                if combat_predictor.attack_hp_loss(
                    monster,
                    effective_damage(card_to_play),
                    **combat_predictor.attack_relic_modifiers(self.game),
                ) >= monster.current_hp
            ]
            return PlayCardAction(
                card=card_to_play,
                target_monster=max(killable, key=combat_predictor.monster_threat),
            )

        def normalized_monster_id(monster):
            return "".join(
                character
                for character in str(getattr(monster, "monster_id", "")).lower()
                if character.isalnum()
            )

        nob = next(
            (monster for monster in living_monsters if normalized_monster_id(monster) == "gremlinnob"),
            None,
        )
        if nob is not None and self.game.turn > 1:
            neutralize = next((card for card in playable_cards if card.card_id == "Neutralize"), None)
            if neutralize is not None:
                return PlayCardAction(card=neutralize, target_monster=nob)
            attacks = [card for card in playable_cards if card.type == spirecomm.spire.card.CardType.ATTACK]
            if attacks:
                card_to_play = max(attacks, key=lambda card: (getattr(card, "damage", 0), -max(card.cost, 0)))
                if card_to_play.has_target:
                    return PlayCardAction(card=card_to_play, target_monster=nob)
                return PlayCardAction(card=card_to_play)

        orb_walkers = [
            monster for monster in living_monsters
            if normalized_monster_id(monster) == "orbwalker"
        ]
        focused_orb_walker = min(
            orb_walkers,
            key=lambda monster: (
                monster.current_hp + getattr(monster, "block", 0),
                getattr(monster, "monster_index", 0),
            ),
        ) if orb_walkers else None

        if uncovered > risk_budget:
            strongest = max(living_monsters, key=combat_predictor.monster_threat)

            def mitigation(card):
                value = getattr(card, "block", 0)
                hits = sum(monster.move_hits for monster in living_monsters if monster.intent.is_attack())
                if card.card_id in ["PiercingWail", "Dark Shackles"]:
                    value += max(0, card.magic_number) * hits
                if card.card_id in ["Neutralize", "Leg Sweep", "Sucker Punch", "Go for the Eyes"] and strongest.intent.is_attack():
                    value += max(1, strongest.move_adjusted_damage * strongest.move_hits // 4)
                return value

            defensive = [card for card in playable_cards if mitigation(card) > 0]
            if defensive:
                card_to_play = max(
                    defensive,
                    key=lambda card: (mitigation(card) / max(card.cost, 1), mitigation(card), -card.cost),
                )
                if card_to_play.has_target:
                    return PlayCardAction(card=card_to_play, target_monster=strongest)
                return PlayCardAction(card=card_to_play)

        zero_cost_cards = [card for card in playable_cards if card.cost == 0]
        zero_cost_attacks = [card for card in zero_cost_cards if card.type == spirecomm.spire.card.CardType.ATTACK]
        zero_cost_non_attacks = [card for card in zero_cost_cards if card.type != spirecomm.spire.card.CardType.ATTACK]
        nonzero_cost_cards = [card for card in playable_cards if card.cost != 0]
        aoe_cards = [card for card in playable_cards if self.priorities.is_card_aoe(card)]
        if combat_predictor.projected_player_block(self.game) > self.get_incoming_damage() - (self.game.act + 4):
            offensive_cards = [card for card in nonzero_cost_cards if not self.priorities.is_card_defensive(card)]
            if len(offensive_cards) > 0:
                nonzero_cost_cards = offensive_cards
            else:
                nonzero_cost_cards = [card for card in nonzero_cost_cards if not card.exhausts]
        if len(zero_cost_non_attacks) > 0:
            card_to_play = self.priorities.get_best_card_to_play(zero_cost_non_attacks)
        elif len(nonzero_cost_cards) > 0:
            card_to_play = self.priorities.get_best_card_to_play(nonzero_cost_cards)
            if len(aoe_cards) > 0 and self.many_monsters_alive() and card_to_play.type == spirecomm.spire.card.CardType.ATTACK:
                card_to_play = self.priorities.get_best_card_to_play(aoe_cards)
        elif len(zero_cost_attacks) > 0:
            card_to_play = self.priorities.get_best_card_to_play(zero_cost_attacks)
        else:
            return EndTurnAction()
        if card_to_play.has_target:
            available_monsters = combat_predictor.active_monsters(self.game)
            if not available_monsters:
                available_monsters = combat_predictor.living_monsters(self.game)
            if len(available_monsters) == 0:
                return EndTurnAction()
            if card_to_play.type == spirecomm.spire.card.CardType.ATTACK:
                target = focused_orb_walker or self.get_low_hp_target()
            else:
                target = self.get_high_hp_target()
            return PlayCardAction(card=card_to_play, target_monster=target)
        return PlayCardAction(card=card_to_play)

    @staticmethod
    def _token(value):
        return "".join(character for character in str(value or "").lower() if character.isalnum())

    @classmethod
    def _canonical_boss_id(cls, value):
        """Normalize display names and CommunicationMod boss identifiers.

        Boss-aware policy used to repeat slightly different alias sets at
        each call site.  A canonical id keeps route, campfire, deck-readiness,
        and reward logic on the same encounter even when the protocol emits a
        display name such as ``The Collector`` or ``Bronze Automaton``.
        """

        token = cls._token(value)
        return {
            "thecollector": "collector",
            "thechamp": "champ",
            "bronzeautomaton": "automaton",
            "theguardian": "guardian",
            "donudeca": "donuanddeca",
            "theheart": "heart",
            "corruptheart": "heart",
        }.get(token, token)

    def _boss_id(self):
        return self._canonical_boss_id(
            getattr(self.game, "act_boss", "")
        )

    @staticmethod
    def _card_cost(card):
        value = getattr(card, "cost", -1)
        return -1 if value is None else int(value)

    def _x_cost_card_count(self, cards=None):
        cards = (
            getattr(self.game, "deck", []) or []
            if cards is None
            else cards
        )
        return sum(
            1 for card in cards
            if getattr(card, "cost", None) == -1
        )

    def _has_relic(self, relic_id):
        wanted = self._token(relic_id)
        wanted_ids = {wanted}
        if wanted in {"papercrane", "paperkrane"}:
            # The base game ID is Paper Crane while the English display name
            # is Paper Krane; CommunicationMod histories contain both.
            wanted_ids.update({"papercrane", "paperkrane"})
        return any(
            self._token(getattr(relic, "relic_id", "")) in wanted_ids
            for relic in getattr(self.game, "relics", []) or []
        )

    def _relic_count(self, relic_id, game=None):
        """Count exact normalized relic IDs on one authoritative frame."""

        game = self.game if game is None else game
        wanted = self._token(relic_id)
        return sum(
            self._token(getattr(relic, "relic_id", "")) == wanted
            for relic in getattr(game, "relics", []) or []
        )

    def _has_active_lizard_tail(self):
        """Return whether Lizard Tail can still revive the player.

        CommunicationMod keeps an already-consumed Lizard Tail in the relic
        list and serializes its counter as ``-2``.  Presence-only checks turn
        that spent relic into a fictitious survival outlet, which is
        especially dangerous in optional-fight event scoring.
        """

        return any(
            self._token(getattr(relic, "relic_id", "")) == "lizardtail"
            and int(getattr(relic, "counter", -1) or -1) != -2
            for relic in getattr(self.game, "relics", []) or []
        )

    def _counterfactual_combat_planner(self, game=None):
        """Create a clean search planner without losing this turn's facts.

        Potion counterfactuals must not inherit a pending card or terminal
        promise from the baseline line.  They *must*, however, retain the
        authoritative count of card resolutions already completed this turn:
        Normality has no serialized counter, and Echo Form's private use count
        likewise cannot be reconstructed from the public Power amount.
        """

        target_game = self.game if game is None else game
        planner = FastCombatPlanner(self.priorities)
        source = self.combat_planner
        # Bring a previously selected card into the confirmed counters from
        # the real authoritative hand before forking.  Never synchronize
        # against a hypothetical hand whose potion/card edits could make the
        # pending UUID disappear artificially.
        source._sync_confirmed_card_plays(self.game)
        target_turn_key = planner._combat_turn_key(target_game)
        if (
            getattr(source, "_card_play_turn_key", None)
            == target_turn_key
        ):
            planner._card_play_turn_key = target_turn_key
            planner._confirmed_cards_played = max(
                0, int(getattr(source, "_confirmed_cards_played", 0) or 0)
            )
            planner._confirmed_card_resolutions = max(
                0,
                int(
                    getattr(source, "_confirmed_card_resolutions", 0) or 0
                ),
            )
        return planner

    def _block_potion_amount(self):
        return 24 if self._has_relic("Sacred Bark") else 12

    def _healing_potion_post_state(self, potion_ids):
        """Resolve ordered Blood/Fruit healing and return ``(hp, max_hp)``.

        The game resolves each potion body before relic ``onUsePotion``
        hooks.  Fruit Juice therefore raises max HP and heals first; Toy
        Ornithopter queues its own five-point healing packet afterward.
        Magic Flower rounds every positive packet independently, while Mark
        of the Bloom blocks current-HP healing but not Fruit's max-HP gain.
        """

        potion_ids = (
            (self._token(potion_ids),)
            if isinstance(potion_ids, str)
            else tuple(self._token(item) for item in potion_ids)
        )
        if not potion_ids:
            return None
        multiplier = 2 if self._has_relic("Sacred Bark") else 1
        magic_flower = self._has_relic("Magic Flower")
        healing_blocked = self._has_relic("Mark of the Bloom")
        toy = self._has_relic("Toy Ornithopter")
        player = self.game.player
        current_hp = max(0, int(getattr(player, "current_hp", 0) or 0))
        max_hp = max(current_hp, int(getattr(player, "max_hp", current_hp) or current_hp))

        def heal(amount):
            nonlocal current_hp
            if healing_blocked:
                return
            amount = max(0, int(amount))
            # MagicFlower.onPlayerHeal uses libGDX MathUtils.round rather
            # than Java/Python truncation.  For the positive integer healing
            # packets here, (3*n + 1)//2 is the exact 1.5x round-to-nearest
            # result (for example Blood 9 -> 14 and Toy/Fruit 5 -> 8).
            modified = (
                (amount * 3 + 1) // 2
                if magic_flower
                else amount
            )
            current_hp = min(max_hp, current_hp + modified)

        for potion_id in potion_ids:
            if potion_id == "bloodpotion":
                heal(int(max_hp * 0.20 * multiplier))
            elif potion_id == "fruitjuice":
                # increaseMaxHp raises the cap first, then calls heal with
                # the same potency; Mark of the Bloom only cancels the heal.
                fruit_gain = 5 * multiplier
                max_hp += fruit_gain
                heal(fruit_gain)
            if toy:
                heal(5)
        return current_hp, max_hp

    def _immediate_potion_hp_gain(self, potion_id):
        """Guaranteed current-HP gain before the next card/end action."""

        state = self._healing_potion_post_state((potion_id,))
        if state is None:
            return 0
        current_hp, _ = state
        original_hp = max(
            0, int(getattr(self.game.player, "current_hp", 0) or 0)
        )
        return max(0, current_hp - original_hp)

    def _potion_changes_red_skull_state(self, potion_ids):
        """Whether potion/Toy healing crosses Red Skull's half-HP line."""

        if not self._has_relic("Red Skull"):
            return False
        post_state = self._healing_potion_post_state(potion_ids)
        if post_state is None:
            return False
        player = self.game.player
        current_hp = max(0, int(getattr(player, "current_hp", 0) or 0))
        max_hp = max(
            current_hp,
            int(getattr(player, "max_hp", current_hp) or current_hp),
        )
        post_hp, post_max_hp = post_state
        return (current_hp * 2 <= max_hp) != (
            post_hp * 2 <= post_max_hp
        )

    def _hypothetical_healing_potion_analysis(self, potion_id):
        """Re-plan after deterministic immediate healing changes risk tiers.

        A healing potion is not merely extra HP applied to the card line that
        was optimal while the player was dying.  Raising current HP can move
        the combat search out of its terminal emergency tier, where a block
        line becomes preferable to a desperate damage line.  Model that
        ordering exactly: apply the guaranteed HP gain, then run a fresh
        authoritative hand search from the post-potion state.
        """

        potion_ids = (
            (self._token(potion_id),)
            if isinstance(potion_id, str)
            else tuple(self._token(item) for item in potion_id)
        )
        if any(
            item not in {"bloodpotion", "fruitjuice"}
            for item in potion_ids
        ):
            return None
        post_state = self._healing_potion_post_state(potion_ids)
        if post_state is None:
            return None

        player = getattr(self.game, "player", None)
        if player is None:
            return None
        current_hp = max(0, int(getattr(player, "current_hp", 0) or 0))
        current_max_hp = max(
            current_hp,
            int(getattr(player, "max_hp", current_hp) or current_hp),
        )
        post_potion_hp, post_potion_max_hp = post_state
        hp_gain = max(0, post_potion_hp - current_hp)
        if hp_gain <= 0:
            return None

        # Red Skull's +3 Strength is reflected in every live card's resolved
        # damage.  Crossing above half HP removes it immediately, but the
        # generic card payload is insufficient to reverse Weak, multi-hit,
        # Heavy Blade, and other rounding exactly.  Fail closed instead of
        # carrying the pre-heal damage into a fabricated lethal line.
        if self._potion_changes_red_skull_state(potion_ids):
            return {
                "blocked": True,
                "blocked_reason": "red_skull_threshold_transition",
                "hp_gain": int(hp_gain),
                "post_potion_hp": int(post_potion_hp),
                "post_potion_max_hp": int(post_potion_max_hp),
                "loss": None,
                "survives": False,
                "potion_sequence": list(potion_ids),
            }

        hypothetical = copy.copy(self.game)
        hypothetical.player = copy.copy(player)
        hypothetical.player.max_hp = post_potion_max_hp
        hypothetical.player.current_hp = post_potion_hp
        # Game mirrors these fields outside Player in protocol payloads and a
        # few planner helpers read the mirror.  Keep the counterfactual
        # internally consistent instead of relying on one representation.
        hypothetical.current_hp = hypothetical.player.current_hp
        hypothetical.max_hp = hypothetical.player.max_hp

        planner = self._counterfactual_combat_planner(hypothetical)
        action = planner.choose_card_action(hypothetical)
        decision = dict(planner.last_decision or {})
        loss = self._planned_turn_hp_loss(action, decision)
        search = dict(decision.get("search") or {})
        post_potion_hp = int(hypothetical.player.current_hp)
        return {
            "hp_gain": int(hp_gain),
            "post_potion_hp": post_potion_hp,
            "post_potion_max_hp": int(hypothetical.player.max_hp),
            "loss": None if loss is None else max(0, int(loss)),
            "survives": bool(loss is not None and int(loss) < post_potion_hp),
            "true_combat_end": bool(search.get("true_combat_end")),
            "final_enemy_hp": list(search.get("final_enemy_hp") or []),
            "planned_card_ids": [
                item.get("card_id")
                for item in decision.get("planned_sequence") or []
                if isinstance(item, dict) and item.get("card_id")
            ],
            "first_card_id": getattr(getattr(action, "card", None), "card_id", None),
            "first_card_uuid": getattr(getattr(action, "card", None), "uuid", None),
            "search_tier": search.get("tier"),
            "potion_sequence": list(potion_ids),
        }

    def _potion_immediately_ends_combat(self, potion_id, target):
        """Conservatively recognize deterministic Fire/Explosive kills."""

        living = combat_predictor.living_monsters(self.game)
        if not living:
            return True
        if any(
            self._token(getattr(monster, "monster_id", ""))
            == "awakenedone"
            and combat_predictor.has_power(
                monster, "Unawakened", "Curiosity", "CuriosityPower"
            )
            for monster in living
        ):
            return False
        multiplier = 2 if self._has_relic("Sacred Bark") else 1
        if potion_id == "firepotion":
            if len(living) != 1 or target is not living[0]:
                return False
            monster = living[0]
            if combat_predictor.has_unresolved_damage_cap(monster):
                return False
            dealt = combat_predictor.attack_hp_loss(
                monster,
                20 * multiplier,
                hits=1,
                vulnerable_eligible=False,
            )
            return dealt >= int(getattr(monster, "current_hp", 0) or 0)
        if potion_id == "explosivepotion":
            for monster in living:
                if combat_predictor.has_unresolved_damage_cap(monster):
                    return False
                dealt = combat_predictor.attack_hp_loss(
                    monster,
                    10 * multiplier,
                    hits=1,
                    vulnerable_eligible=False,
                )
                if dealt < int(getattr(monster, "current_hp", 0) or 0):
                    return False
            return True
        return False

    def _direct_damage_potion_hp_loss(self, potion_id, target):
        """Return exact immediate HP loss for deterministic damage potions."""

        potion_id = self._token(potion_id)
        living = combat_predictor.living_monsters(self.game)
        if not living:
            return 0
        multiplier = 2 if self._has_relic("Sacred Bark") else 1
        if potion_id == "firepotion":
            if target not in living or combat_predictor.has_unresolved_damage_cap(
                target
            ):
                return None
            return combat_predictor.attack_hp_loss(
                target, 20 * multiplier, hits=1, vulnerable_eligible=False,
            )
        if potion_id == "explosivepotion":
            if any(
                combat_predictor.has_unresolved_damage_cap(monster)
                for monster in living
            ):
                return None
            return sum(
                combat_predictor.attack_hp_loss(
                    monster, 10 * multiplier, hits=1,
                    vulnerable_eligible=False,
                )
                for monster in living
            )
        return None

    def _hypothetical_shifting_potion_analysis(self, potion_id, target):
        """Re-plan the known nonlethal damage -> Shifting reaction.

        Killing, splitting and unrelated on-damage reactions retain their
        existing evaluators; this proof only models surviving Shifting targets.
        """
        potion_id = self._token(potion_id)
        if potion_id not in {"firepotion", "explosivepotion"}:
            return None
        living = combat_predictor.living_monsters(self.game)
        affected = [target] if potion_id == "firepotion" else living
        if not affected or any(
            monster not in living
            or not combat_predictor.has_power(monster, "Shifting", "ShiftingPower")
            or combat_predictor.has_unresolved_damage_cap(monster)
            or combat_predictor.has_power(monster, "Compulsive", "Mode Shift", "Split")
            for monster in affected
        ) or self._potion_changes_red_skull_state((potion_id,)):
            return None
        hypothetical = copy.deepcopy(self.game)
        multiplier = 2 if self._has_relic("Sacred Bark") else 1
        packet = (20 if potion_id == "firepotion" else 10) * multiplier
        reactions = []
        for monster in affected:
            damage = combat_predictor.attack_hp_loss(
                monster, packet, hits=1, vulnerable_eligible=False,
            )
            if damage <= 0 or damage >= monster.current_hp:
                return None
            index = list(self.game.monsters).index(monster)
            changed = hypothetical.monsters[index]
            delta = self.combat_planner._branch_enemy_attack_damage_delta(
                self.game, monster, strength_reduction=damage,
                weak_amount=combat_predictor.power_amount(monster, "Weak", "Weakened"),
            )
            changed.current_hp -= damage
            changed.block = max(0, int(monster.block) - packet)
            changed.move_adjusted_damage = max(0, monster.move_adjusted_damage + delta)
            for power_id, amount in (("Strength", -damage), ("Shackled", damage)):
                power = next((p for p in changed.powers if p.power_id == power_id), None)
                if power is None:
                    changed.powers.append(SimpleNamespace(
                        power_id=power_id, power_name=power_id, amount=amount,
                    ))
                else:
                    power.amount += amount
            reactions.append({"enemy_index": index, "hp_loss": damage,
                              "attack_delta_per_hit": delta})
        hp_gain = self._immediate_potion_hp_gain(potion_id)
        hypothetical.player.current_hp = min(
            hypothetical.player.max_hp, hypothetical.player.current_hp + hp_gain,
        )
        hypothetical.current_hp = hypothetical.player.current_hp
        planner = self._counterfactual_combat_planner(hypothetical)
        action = planner.choose_card_action(hypothetical)
        loss = self._planned_turn_hp_loss(action, planner.last_decision)
        return {
            "loss": loss, "reactions": reactions,
            "post_potion_hp": hypothetical.player.current_hp,
            "survives": loss is not None and loss < hypothetical.player.current_hp,
            "semantics": "damage_shifting_then_authoritative_hand_replan",
        }

    def _direct_damage_potion_hp_loss_bounds(self, potion_id, target):
        """Return truthful immediate-loss bounds when a turn cap is hidden."""

        exact = self._direct_damage_potion_hp_loss(potion_id, target)
        if exact is not None:
            return {"minimum": int(exact), "maximum": int(exact)}
        potion_id = self._token(potion_id)
        living = combat_predictor.living_monsters(self.game)
        multiplier = 2 if self._has_relic("Sacred Bark") else 1
        if potion_id == "firepotion":
            targets = [target] if target in living else []
            raw_damage = 20 * multiplier
        elif potion_id == "explosivepotion":
            targets = living
            raw_damage = 10 * multiplier
        else:
            return None
        if not targets:
            return {"minimum": 0, "maximum": 0}
        minimum = 0
        maximum = 0
        for monster in targets:
            loss = combat_predictor.attack_hp_loss(
                monster,
                raw_damage,
                hits=1,
                vulnerable_eligible=False,
            )
            loss = min(
                loss, max(0, int(getattr(monster, "current_hp", 0) or 0))
            )
            maximum += loss
            if not combat_predictor.has_unresolved_damage_cap(monster):
                minimum += loss
        return {"minimum": int(minimum), "maximum": int(maximum)}

    def _neow_lament_charges(self):
        """Return authoritative remaining one-HP combats, if any."""

        for relic in getattr(self.game, "relics", []) or []:
            relic_id = self._token(getattr(relic, "relic_id", ""))
            if relic_id in {"neowsblessing", "neowslament"}:
                return max(0, int(getattr(relic, "counter", 0) or 0))
        return 0

    def _neow_lament_elite_route(
        self, entrance, charges, emerald_pending=False
    ):
        """Find the best connected route whose elite still has one HP.

        Room-depth lookahead is the wrong bound for Neow's Lament: a route
        may cross shops, events, rests, and the chest before its third combat.
        Search the connected act map by remaining combat charges instead, so
        a distant third-combat elite cannot lose its strategic value merely
        because it is beyond the compact eight-room audit summary.
        """

        charges = max(0, int(charges or 0))
        if charges <= 0 or entrance is None:
            return None
        frontier = [(entrance, charges, bool(emerald_pending), [])]
        seen = {}
        matches = []
        while frontier:
            node, remaining, pending_emerald, prefix = frontier.pop()
            coord = (int(node.x), int(node.y))
            state_key = (coord, remaining, pending_emerald)
            if seen.get(state_key, math.inf) <= len(prefix):
                continue
            seen[state_key] = len(prefix)
            full_node = self.game.map.get_node(*coord) or node
            symbol = str(getattr(full_node, "symbol", "?"))
            is_lament_combat = symbol in {"M", "E"} and remaining > 0
            path = prefix + [f"{symbol}@{coord[0]},{coord[1]}"]
            if symbol == "E" and is_lament_combat:
                matches.append({
                    "elite_combat_number": charges - remaining + 1,
                    "rooms_before_elite": len(path) - 1,
                    "remaining_charges_at_elite": remaining,
                    "route": path,
                })
                continue
            next_remaining = remaining - 1 if is_lament_combat else remaining
            children, next_emerald_pending = (
                self._emerald_constrained_children(
                    full_node, pending_emerald
                )
            )
            frontier.extend(
                (child, next_remaining, next_emerald_pending, path)
                for child in children
            )
        if not matches:
            return None
        return min(
            matches,
            key=lambda item: (
                item["elite_combat_number"],
                item["rooms_before_elite"],
                tuple(item["route"]),
            ),
        )

    def _is_scaling_combat_threat(self, active=None):
        """Use the same growth evidence as ordered combat planning."""
        return self.combat_planner.combat_threat_profile(
            self.game, active
        )["has_scaling_threat"]

    @staticmethod
    def _linear_score_contract(rule_id, inputs, terms):
        """Describe a local score as independently replayable linear terms."""

        normalized_inputs = {
            str(name): float(value) for name, value in inputs.items()
        }
        components = []
        for name, input_name, coefficient in terms:
            coefficient = float(coefficient)
            components.append({
                "name": str(name),
                "input": str(input_name),
                "coefficient": coefficient,
                "value": normalized_inputs[str(input_name)] * coefficient,
            })
        return {
            "score_rule_id": str(rule_id),
            "score_formula": {"kind": "sum_components_v1"},
            "score_inputs": normalized_inputs,
            "score_components": components,
        }

    def _record_noncombat_decision(
        self,
        reason,
        candidates=None,
        candidate_contract=None,
        **details,
    ):
        self.last_noncombat_decision = {
            "reason": reason,
            "goal_mode": self.goal_mode,
            **details,
        }
        if candidates is not None:
            normalized = []
            for candidate in candidates:
                if isinstance(candidate, dict):
                    row = dict(candidate)
                    candidate_id = row.get(
                        "id", row.get("candidate_id", row.get("choice_id"))
                    )
                    row["id"] = str(candidate_id)
                    # ``id`` remains the backwards-compatible local/model
                    # identity. ``choice_id`` is the stable protocol-facing
                    # identity used by DecisionCases and the independent
                    # oracle.  Callers may intentionally use a different
                    # choice_id for semantic abstentions such as Skip/Leave,
                    # which both bind to the protocol ``return`` command.
                    row["choice_id"] = str(
                        row.get("choice_id", candidate_id)
                    )
                    row.pop("candidate_id", None)
                    score = row.get("score")
                    if score is None:
                        score = row.get("local_score")
                    row["score"] = (
                        float(score)
                        if isinstance(score, (int, float))
                        and not isinstance(score, bool)
                        else None
                    )
                    row.pop("local_score", None)
                    row.setdefault("legal", True)
                    row.setdefault("visible", True)
                    row.setdefault("selection_eligible", True)
                    row.setdefault("operation", None)
                    row.setdefault("local_reason", row.get("reason"))
                    if "reason_codes" not in row:
                        local_reason = row.get("local_reason")
                        row["reason_codes"] = (
                            [str(local_reason)] if local_reason else []
                        )
                    facts = row.get("facts")
                    if "consequences" not in row and isinstance(facts, dict):
                        row["consequences"] = dict(
                            facts.get("consequences") or {}
                        )
                    row.setdefault("consequences", {})
                    # Persist an explicit scoring-evidence envelope for every
                    # candidate.  Call sites with a mechanically recomputable
                    # rule provide the four fields below.  Missing evidence is
                    # classified as unverified instead of silently treating a
                    # numeric producer score as an independently auditable
                    # fact.
                    row.setdefault("score_rule_id", "unclassified")
                    row.setdefault("score_formula", {
                        "kind": "unclassified",
                        "reason": "producer_did_not_supply_recomputable_score_rule",
                    })
                    row.setdefault("score_inputs", {})
                    row.setdefault("score_components", [])
                else:
                    candidate_id, score = candidate
                    row = {
                        "id": str(candidate_id),
                        "choice_id": str(candidate_id),
                        "score": float(score),
                        "legal": True,
                        "visible": True,
                        "selection_eligible": True,
                        "operation": None,
                        "local_reason": None,
                        "reason_codes": [],
                        "consequences": {},
                        "score_rule_id": "unclassified",
                        "score_formula": {
                            "kind": "unclassified",
                            "reason": (
                                "tuple_candidate_has_no_recomputable_score_rule"
                            ),
                        },
                        "score_inputs": {},
                        "score_components": [],
                    }
                normalized.append(row)
            self.last_noncombat_decision["candidates"] = normalized
            if candidate_contract is None:
                all_scored = bool(normalized) and all(
                    isinstance(row.get("score"), (int, float))
                    and not isinstance(row.get("score"), bool)
                    for row in normalized
                )
                candidate_contract = {
                    "contract_schema_version": 1,
                    "score_source": (
                        "unverified_candidate_subset"
                        if all_scored
                        else "incomplete_candidate_evidence"
                    ),
                    # Numeric rows alone do not prove that every visible
                    # option was included.  Only a caller that owns the
                    # authoritative option list may attest completeness.
                    "strategy_quality_auditable": False,
                    "all_visible_options_scored": False,
                    "incomplete_reason": (
                        "producer_did_not_attest_visible_candidate_completeness"
                        if all_scored
                        else "one_or_more_candidates_missing_numeric_score"
                    ),
                }
        if candidate_contract is not None:
            self.last_noncombat_decision["candidate_contract"] = {
                "contract_schema_version": 1,
                **dict(candidate_contract),
            }
        if self._pending_macro_advice is not None:
            self.last_noncombat_decision["model_advice"] = dict(
                self._pending_macro_advice
            )
            self._pending_macro_advice = None
        else:
            self.last_noncombat_decision["model_advice"] = {
                "status": "not_consulted",
                "applied": False,
                "confidence": None,
                "final_choice_ids": [],
                "reason": "no_remote_macro_advice_for_this_decision",
                "consultation_outcome": "not_consulted",
                "semantic_choice_change": False,
                "protocol_confirmation": False,
            }

        # Keep remote confirmation separate from a real semantic reroute.
        # Navigation commands such as action:return are useful protocol
        # evidence, but counting their agreement as model adoption makes a
        # high-frequency menu close look like a strategy improvement.
        advice = self.last_noncombat_decision.get("model_advice")
        if isinstance(advice, dict) and advice.get("consultation_outcome") is None:
            rule_id = str(advice.get("rule_choice_id") or "")
            model_id = str(advice.get("model_choice_id") or "")
            final_ids = [
                str(value) for value in advice.get("final_choice_ids") or []
                if value is not None
            ]
            observed = details.get("selected_choice_ids")
            if not isinstance(observed, (list, tuple)):
                observed = details.get("final_choice_ids")
            if not isinstance(observed, (list, tuple)):
                chosen_id = details.get("chosen_id")
                observed = [chosen_id] if chosen_id is not None else []
            observed = [str(value) for value in observed if value is not None]
            effective_ids = observed or final_ids

            def protocol_choice(value):
                token = str(value or "").strip().casefold()
                return token.startswith("action:") or token in {
                    "return", "leave", "cancel", "proceed", "confirm",
                }

            status = str(advice.get("status") or "").casefold()
            applied = advice.get("applied") is True
            changed = bool(
                applied
                and model_id
                and model_id != rule_id
                and effective_ids
                and effective_ids != [rule_id]
            )
            semantic_surface = (
                not protocol_choice(rule_id)
                or not all(protocol_choice(value) for value in effective_ids)
            )
            protocol_equivalent = (
                bool(effective_ids)
                and protocol_choice(rule_id)
                and all(protocol_choice(value) for value in effective_ids)
            )
            if changed and semantic_surface:
                outcome = "choice_change"
            elif changed:
                outcome = "protocol_transition_change"
            elif (
                status == "agreed"
                and model_id == rule_id
                and (
                    not effective_ids
                    or effective_ids == [rule_id]
                    or protocol_equivalent
                )
            ):
                outcome = (
                    "protocol_confirmation"
                    if protocol_choice(rule_id)
                    else "local_confirmation"
                )
            elif status in {
                "skipped", "fallback", "shadow_queued", "not_consulted",
            }:
                outcome = "consultation_suppressed"
            elif model_id or advice.get("advice_id"):
                outcome = "review_no_choice_change"
            else:
                outcome = "not_classified"
            advice["consultation_outcome"] = outcome
            advice["semantic_choice_change"] = outcome == "choice_change"
            advice["protocol_confirmation"] = (
                outcome == "protocol_confirmation"
            )
            advice["local_confirmation"] = outcome == "local_confirmation"

    @staticmethod
    def _planned_turn_hp_loss(action, decision):
        """Return an exact bounded-plan loss when the planner exposes one."""

        decision = decision if isinstance(decision, dict) else {}
        search = decision.get("search")
        if isinstance(search, dict):
            actual_loss = search.get("actual_loss")
            if isinstance(actual_loss, int) and not isinstance(actual_loss, bool):
                return max(0, actual_loss)
        if isinstance(action, EndTurnAction):
            projected = decision.get("projected_hp_loss")
            if isinstance(projected, int) and not isinstance(projected, bool):
                return max(0, projected)
        return None

    def _potion_loss_opportunity(self, baseline_loss, candidate_loss=None):
        """Price measured HP mitigation against the cost of keeping a potion.

        Literal lethal is too late for many deterministic potions.  In
        particular, Weak can save several HP on each of multiple boss turns
        while neither a single turn nor the post-turn HP has yet crossed the
        old low-reserve trigger.  Treat a quantified large loss as a combat
        commitment point, but require a correspondingly material *measured*
        reduction.  This deliberately returns no value on zero/small-loss
        turns and therefore cannot justify speculative potion use.
        """

        hp = max(1, int(getattr(self.game.player, "current_hp", 1) or 1))
        max_hp = max(
            hp,
            int(getattr(self.game.player, "max_hp", hp) or hp),
        )
        loss = max(0, int(baseline_loss or 0))
        reserve = FastCombatPlanner._reactive_safety_reserve(self.game, hp)
        reserve_breaking = loss > 0 and hp - loss < reserve
        severe_threshold = min(
            max(12, (max_hp + 4) // 5),
            max(10, (hp * 35 + 99) // 100),
        )
        lethal = loss >= hp
        severe = bool(
            loss > 0
            and (lethal or reserve_breaking or loss >= severe_threshold)
        )
        result = {
            "hp": hp,
            "max_hp": max_hp,
            "loss": loss,
            "reserve": reserve,
            "reserve_breaking": reserve_breaking,
            "severe": severe,
            "lethal": lethal,
            "severe_threshold": severe_threshold,
            "candidate_loss": None,
            "mitigation": 0,
            "material_mitigation": max(3, (loss * 18 + 99) // 100),
            "score": None,
        }
        if candidate_loss is None:
            return result
        candidate = max(0, int(candidate_loss or 0))
        mitigation = max(0, loss - candidate)
        result.update({
            "candidate_loss": candidate,
            "mitigation": mitigation,
        })
        if lethal:
            if candidate < hp:
                result["score"] = 110.0
            return result
        if not severe or mitigation < result["material_mitigation"]:
            return result
        restored_reserve = (
            hp - loss < reserve <= hp - candidate
        )
        result["score"] = (
            12.0
            + mitigation * 1.5
            + (4.0 if reserve_breaking else 0.0)
            + (3.0 if restored_reserve else 0.0)
        )
        return result

    def _defect_orb_potion_setup_score(self, potion_id, hard_fight):
        """Value deterministic combat-long orb setup from grounded state.

        Capacity and Essence of Darkness previously fell through to the
        generic unknown-potion score.  Use only in a durable hard fight with
        actual orb support/slot pressure (Capacity), or while a Dark orb has
        enough fight left to grow (Essence).  Exact current-turn replanning
        can still override this setup score when it proves survival or a
        material kill.
        """

        intrinsic_hard_fight = (
            self.game.room_type in {"MonsterRoomElite", "MonsterRoomBoss"}
            or self._is_scaling_combat_threat(
                combat_predictor.active_monsters(self.game)
            )
        )
        if (
            self.chosen_class != PlayerClass.DEFECT
            or not hard_fight
            or not intrinsic_hard_fight
        ):
            return -100.0
        active = combat_predictor.active_monsters(self.game)
        if not active:
            return -100.0
        turn = max(0, int(getattr(self.game, "turn", 0) or 0))
        total_enemy_hp = sum(
            max(0, int(getattr(monster, "current_hp", 0) or 0))
            for monster in active
        )
        durable = total_enemy_hp >= max(45, 24 * len(active))
        if not durable:
            return -100.0

        cards = list(getattr(self.game, "deck", []) or [])
        if not cards:
            cards = list(getattr(self.game, "hand", []) or [])
        card_ids = [
            self._token(getattr(card, "card_id", "")) for card in cards
        ]
        hand_ids = [
            self._token(getattr(card, "card_id", ""))
            for card in getattr(self.game, "hand", []) or []
            if getattr(card, "is_playable", False)
        ]
        channel_ids = {
            "balllightning", "chill", "coldsnap", "coolheaded",
            "doomandgloom", "fusion", "glacier", "rainbow", "tempest",
            "zap",
        }
        payoff_ids = {
            "barrage", "consume", "dualcast", "fission", "loop",
            "multicast", "recursion",
        }
        generators = sum(card_id in channel_ids for card_id in card_ids)
        hand_generators = sum(card_id in channel_ids for card_id in hand_ids)
        payoffs = sum(card_id in payoff_ids for card_id in card_ids)
        serialized = list(getattr(self.game.player, "orbs", []) or [])
        occupied = sum(
            self._token(getattr(orb, "orb_id", "")) not in {"", "empty"}
            for orb in serialized
        )
        # The orb list is the authoritative slot list, including Empty slots.
        # Consume can reduce it below the normal three-slot baseline.
        slots = len(serialized) if serialized else max(3, occupied)
        focus = combat_predictor.signed_power_amount(
            self.game.player, "Focus"
        )

        if potion_id == "potionofcapacity":
            pressure = bool(
                occupied >= max(1, slots - 1)
                or hand_generators >= max(1, slots - occupied)
                or "consume" in card_ids
            )
            engine = generators >= 3 or generators >= 2 and payoffs > 0
            if turn > 3 or not engine or not pressure:
                return -100.0
            return float(
                17
                + min(5, max(0, generators - 2))
                + min(3, payoffs)
            )

        if potion_id == "essenceofdarkness":
            # A fresh Dark orb gains damage every end step; consuming it late
            # in a nearly finished fight is wasteful, while turn 1/2 of a
            # durable elite/boss is the deterministic high-value window.
            if turn > 2:
                return -100.0
            dark_payoffs = sum(
                card_id in {"dualcast", "fission", "loop", "multicast", "recursion"}
                for card_id in card_ids
            )
            return float(
                17
                + min(4, dark_payoffs * 2)
                + min(3, max(0, focus))
            )
        return -100.0

    def _liquid_memories_analysis(self, planned_turn_loss=None, cards=None):
        """Measure Liquid Memories against the already-computed turn plan.

        The potion is useful only if the retrieved zero-cost card improves the
        exact terminal plan.  Raw printed damage/block badly overvalues cards
        that the planner never plays and was the reason old runs repeatedly
        spent this premium potion to retrieve a basic Strike at zero loss.
        """

        candidates = list(
            getattr(self.game, "discard_pile", []) or []
            if cards is None else cards
        )
        if not candidates:
            return None

        if self._potion_changes_red_skull_state(("liquidmemories",)):
            return None
        baseline_decision = self.combat_planner.last_decision or {}
        baseline_search = baseline_decision.get("search") or {}
        baseline_loss = (
            combat_predictor.projected_turn_hp_loss(self.game)
            if planned_turn_loss is None
            else max(0, int(planned_turn_loss))
        )
        baseline_dead = int(baseline_search.get("enemies_dead", 0) or 0)
        baseline_score = float(baseline_decision.get("plan_score", 0.0) or 0.0)
        incoming = combat_predictor.projected_turn_hp_loss(self.game)

        def tactical_prior(card):
            block = max(0, int(getattr(card, "block", 0) or 0))
            damage, hits = combat_predictor.card_attack_profile(self.game, card)
            card_id = self._token(getattr(card, "card_id", ""))
            draw = int(FastCombatPlanner.DRAW_COUNTS.get(card_id, 0) or 0)
            return (
                min(incoming, block) * 3.0
                + damage
                + max(0, hits - 1) * 2.0
                + draw * 4.0
                + (
                    16.0
                    if getattr(card, "type", None)
                    == spirecomm.spire.card.CardType.POWER
                    else 0.0
                )
                + (
                    10.0
                    if card_id
                    in self.SCALING_CARD_IDS.get(self.chosen_class, set())
                    else 0.0
                )
            )

        # A discard pile can be large.  Eight semantic candidates retain the
        # useful defensive, lethal, draw and scaling options without turning
        # one potion decision into dozens of full beam searches.
        shortlist = sorted(
            candidates, key=tactical_prior, reverse=True
        )[:8]
        active = combat_predictor.active_monsters(self.game)
        hard_fight = (
            self.game.room_type in {"MonsterRoomElite", "MonsterRoomBoss"}
            or self._is_scaling_combat_threat(active)
        )
        results = []
        for card in shortlist:
            hypothetical = copy.copy(self.game)
            hypothetical.player = copy.copy(self.game.player)
            retrieved = copy.copy(card)
            retrieved.cost = 0
            retrieved.is_playable = True
            hypothetical.hand = list(getattr(self.game, "hand", []) or []) + [
                retrieved
            ]
            hypothetical.discard_pile = [
                item
                for item in getattr(self.game, "discard_pile", []) or []
                if getattr(item, "uuid", None) != getattr(card, "uuid", None)
            ]
            planner = self._counterfactual_combat_planner(hypothetical)
            action = planner.choose_card_action(hypothetical)
            decision = planner.last_decision or {}
            candidate_loss = self._planned_turn_hp_loss(action, decision)
            if candidate_loss is None:
                continue
            search = decision.get("search") or {}
            sequence = decision.get("planned_sequence") or []
            retrieved_used = any(
                entry.get("card_uuid") == getattr(retrieved, "uuid", None)
                for entry in sequence
                if isinstance(entry, dict)
            )
            if not sequence and isinstance(action, PlayCardAction):
                retrieved_used = getattr(action.card, "uuid", None) == getattr(
                    retrieved, "uuid", None
                )
            if not retrieved_used:
                continue
            card_id = self._token(getattr(card, "card_id", ""))
            dead = int(search.get("enemies_dead", 0) or 0)
            marginal_kills = max(0, dead - baseline_dead)
            loss_reduction = max(0, baseline_loss - candidate_loss)
            critical_setup = bool(
                hard_fight
                and int(getattr(self.game, "turn", 0) or 0) <= 3
                and (
                    card_id in self.SCALING_CARD_IDS.get(self.chosen_class, set())
                    or getattr(card, "type", None)
                    == spirecomm.spire.card.CardType.POWER
                )
            )
            plan_score = float(decision.get("plan_score", 0.0) or 0.0)
            results.append({
                "card": card,
                "candidate_loss": candidate_loss,
                "loss_reduction": loss_reduction,
                "marginal_kills": marginal_kills,
                "critical_setup": critical_setup,
                "plan_score_gain": plan_score - baseline_score,
                "planned_sequence": sequence,
            })

        if not results:
            return None
        best = max(
            results,
            key=lambda item: (
                item["candidate_loss"] < max(
                    1, int(getattr(self.game.player, "current_hp", 1) or 1)
                ),
                -item["candidate_loss"],
                item["marginal_kills"],
                item["critical_setup"],
                item["plan_score_gain"],
                tactical_prior(item["card"]),
            ),
        )
        worthwhile = (
            best["marginal_kills"] > 0
            or best["critical_setup"]
            or best["loss_reduction"] > 0
        )
        if baseline_loss == 0:
            worthwhile = best["marginal_kills"] > 0 or best["critical_setup"]
        value = (
            best["loss_reduction"] * 3.2
            + best["marginal_kills"] * 18.0
            + (16.0 if best["critical_setup"] else 0.0)
        )
        if (
            baseline_loss >= int(getattr(self.game.player, "current_hp", 1) or 1)
            and best["candidate_loss"]
            < int(getattr(self.game.player, "current_hp", 1) or 1)
        ):
            value = max(110.0, value)
        best["worthwhile"] = worthwhile
        best["value"] = value if worthwhile else -100.0
        best["baseline_loss"] = baseline_loss
        return best

    def _hypothetical_speed_potion_loss(self):
        """Re-plan the hand with Speed Potion's real temporary Dexterity.

        CommunicationMod serializes each block card after current Dexterity
        and Frail have already been applied.  Rebuild the displayed amount
        from ``base_block`` so the new Dexterity is added before Frail's 0.75
        multiplier; adding five directly to an already-Frail value can invent
        a point of block and a false lethal escape.
        """

        if self._potion_changes_red_skull_state(("speedpotion",)):
            return None
        potion_dexterity = 10 if self._has_relic("Sacred Bark") else 5
        current_dexterity = combat_predictor.signed_power_amount(
            self.game.player, "Dexterity", "DexterityPower"
        )
        frail = combat_predictor.has_power(
            self.game.player, "Frail", "FrailPower"
        )
        hypothetical = copy.copy(self.game)
        hypothetical.player = copy.copy(self.game.player)
        hypothetical.hand = []
        for original in getattr(self.game, "hand", []) or []:
            card = copy.copy(original)
            base_block = getattr(card, "base_block", None)
            grants_block = (
                int(base_block or 0) > 0
                or (base_block is None and int(getattr(card, "block", 0) or 0) > 0)
            )
            if grants_block:
                if base_block is not None:
                    rebuilt = max(
                        0,
                        int(base_block or 0)
                        + current_dexterity
                        + potion_dexterity,
                    )
                    card.block = int(rebuilt * 0.75) if frail else rebuilt
                else:
                    # Protocol-v2 cards carry base_block.  Keep a conservative
                    # fallback for older/modded payloads where reversing Frail
                    # exactly is impossible from the displayed integer alone.
                    incremental = (
                        int(potion_dexterity * 0.75)
                        if frail
                        else potion_dexterity
                    )
                    card.block = (
                        max(0, int(getattr(card, "block", 0) or 0))
                        + incremental
                    )
            hypothetical.hand.append(card)
        planner = self._counterfactual_combat_planner(hypothetical)
        action = planner.choose_card_action(hypothetical)
        return self._planned_turn_hp_loss(action, planner.last_decision)

    def _hypothetical_known_draw_potion_analysis(self, potion_id):
        """Re-plan a potion whose entire draw is authoritative and known.

        Swift Potion was treated as stochastic even when CommunicationMod
        exposed every card it would draw.  On a lethal turn that made a
        random Colorless card outrank an exact Survivor/Neutralize/Dash line.
        Only claim a rescue when the visible suffix fully supplies the draw;
        reshuffles, hand-dependent cards, No Draw, and Evolve chains remain
        unproven and fall back to the one-shot stochastic policy.
        """

        potion_id = self._token(potion_id)
        if potion_id != "swiftpotion":
            return None
        if self._potion_changes_red_skull_state((potion_id,)):
            return None
        player = getattr(self.game, "player", None)
        if player is None or combat_predictor.has_power(
            player, "No Draw", "NoDrawPower"
        ):
            return None
        hand = list(getattr(self.game, "hand", []) or [])
        hand_space = max(0, 10 - len(hand))
        requested_draw = 3 * (2 if self._has_relic("Sacred Bark") else 1)
        draw_count = min(requested_draw, hand_space)
        draw_pile = list(getattr(self.game, "draw_pile", []) or [])
        if draw_count <= 0 or len(draw_pile) < draw_count:
            return None
        if getattr(self.game, "draw_pile_order_known", True) is not True:
            return None
        drawn_source = list(reversed(draw_pile[-draw_count:]))
        conditional_ids = {
            "clash", "concentrate", "grandfinale", "normality",
            "reflex", "signaturemove", "stormofsteel", "tactician",
            "void",
        }
        if any(
            self._token(getattr(card, "card_id", "")) in conditional_ids
            for card in drawn_source
        ):
            return None
        if combat_predictor.has_power(
            player, "Evolve", "EvolvePower"
        ) and any(
            getattr(card, "type", None)
            == spirecomm.spire.card.CardType.STATUS
            for card in drawn_source
        ):
            return None

        hypothetical = copy.copy(self.game)
        hypothetical.player = copy.copy(player)
        hypothetical.hand = [copy.copy(card) for card in hand]
        copied_drawn = [copy.copy(card) for card in drawn_source]
        energy = max(0, int(getattr(player, "energy", 0) or 0))
        entangled = combat_predictor.has_power(player, "Entangled")
        for card in copied_drawn:
            card_type = getattr(card, "type", None)
            cost = int(getattr(card, "cost", 0) or 0)
            card.is_playable = bool(
                card_type in {
                    spirecomm.spire.card.CardType.ATTACK,
                    spirecomm.spire.card.CardType.SKILL,
                    spirecomm.spire.card.CardType.POWER,
                }
                and (cost == -1 or cost <= energy)
                and not (
                    entangled
                    and card_type == spirecomm.spire.card.CardType.ATTACK
                )
            )
        hypothetical.hand.extend(copied_drawn)
        hypothetical.draw_pile = list(draw_pile[:-draw_count])
        hypothetical.current_action = None

        planner = self._counterfactual_combat_planner(hypothetical)
        action = planner.choose_card_action(hypothetical)
        decision = dict(planner.last_decision or {})
        loss = self._planned_turn_hp_loss(action, decision)
        if loss is None:
            return None
        search = dict(decision.get("search") or {})
        return {
            "loss": max(0, int(loss)),
            "draw_count": draw_count,
            "drawn_card_ids": [
                getattr(card, "card_id", None) for card in drawn_source
            ],
            "planned_card_ids": [
                item.get("card_id")
                for item in decision.get("planned_sequence") or []
                if isinstance(item, dict) and item.get("card_id")
            ],
            "true_combat_end": bool(search.get("true_combat_end")),
        }

    def _hypothetical_cunning_potion_analysis(self):
        """Re-plan the exact Shiv hand created by Cunning Potion.

        The old fixed score could never cross the ordinary-combat lethal-use
        threshold, even when three Shivs deterministically triggered After
        Image and Ornamental Fan for enough Block to survive. Generated-card
        capacity and card-play reactions are order-sensitive, so prove the
        complete line with the normal planner instead of assigning those
        synergies a scalar bonus.
        """

        potion_id = "cunningpotion"
        player = getattr(self.game, "player", None)
        if player is None or combat_predictor.has_power(
            player, "Confusion", "ConfusionPower"
        ):
            # Confusion randomizes the generated cards' costs as they enter
            # the hand, so a zero-cost exact line would be fabricated.
            return None
        if self._potion_changes_red_skull_state((potion_id,)):
            return None

        hand = list(getattr(self.game, "hand", []) or [])
        shiv_count = min(
            3 * (2 if self._has_relic("Sacred Bark") else 1),
            max(0, 10 - len(hand)),
        )
        if shiv_count <= 0:
            return None

        post_state = self._healing_potion_post_state((potion_id,))
        if post_state is None:
            return None
        post_potion_hp, post_potion_max_hp = post_state

        hypothetical = copy.copy(self.game)
        hypothetical.player = copy.copy(player)
        hypothetical.player.current_hp = int(post_potion_hp)
        hypothetical.player.max_hp = int(post_potion_max_hp)
        hypothetical.current_hp = int(post_potion_hp)
        hypothetical.max_hp = int(post_potion_max_hp)
        hypothetical.hand = [copy.copy(card) for card in hand]

        strength = combat_predictor.signed_power_amount(
            player, "Strength", "StrengthPower"
        )
        accuracy = combat_predictor.power_amount(
            player, "Accuracy", "AccuracyPower"
        )
        wrist_blade = 4 if self._has_relic("Wrist Blade") else 0
        shiv_damage = max(
            0, 4 + strength + accuracy + wrist_blade
        )
        if combat_predictor.has_power(player, "Weak", "Weakened"):
            shiv_damage = int(shiv_damage * 0.75)
        entangled = combat_predictor.has_power(player, "Entangled")
        generated_uuids = set()
        for index in range(shiv_count):
            uuid = f"cunning-potion-shiv:{index}"
            generated_uuids.add(uuid)
            hypothetical.hand.append(spirecomm.spire.card.Card(
                "Shiv",
                "Shiv",
                spirecomm.spire.card.CardType.ATTACK,
                spirecomm.spire.card.CardRarity.SPECIAL,
                cost=0,
                uuid=uuid,
                has_target=True,
                is_playable=not entangled,
                exhausts=True,
                damage=shiv_damage,
                base_damage=4,
            ))
        hypothetical.current_action = None

        planner = self._counterfactual_combat_planner(hypothetical)
        action = planner.choose_card_action(hypothetical)
        decision = dict(planner.last_decision or {})
        loss = self._planned_turn_hp_loss(action, decision)
        if loss is None:
            return None
        loss = max(0, int(loss))
        search = dict(decision.get("search") or {})
        planned_sequence = [
            item for item in decision.get("planned_sequence") or []
            if isinstance(item, dict)
        ]
        reserve = FastCombatPlanner._reactive_safety_reserve(
            hypothetical, int(post_potion_hp)
        )
        post_turn_hp = int(post_potion_hp) - loss
        return {
            "loss": loss,
            "survives": post_turn_hp > 0,
            "post_potion_hp": int(post_potion_hp),
            "post_potion_max_hp": int(post_potion_max_hp),
            "post_turn_hp": int(post_turn_hp),
            "safety_reserve": int(reserve),
            "preserves_reserve": post_turn_hp >= reserve,
            "true_combat_end": bool(search.get("true_combat_end")),
            "final_enemy_hp": list(search.get("final_enemy_hp") or []),
            "final_player_block": search.get("final_player_block"),
            "search_tier": search.get("tier"),
            "generated_shiv_count": int(shiv_count),
            "generated_shiv_plays": sum(
                item.get("card_uuid") in generated_uuids
                for item in planned_sequence
            ),
            "planned_card_ids": [
                item.get("card_id")
                for item in planned_sequence
                if item.get("card_id")
            ],
            "planned_card_uuids": [
                item.get("card_uuid")
                for item in planned_sequence
                if item.get("card_uuid")
            ],
        }

    def _hypothetical_poison_potion_analysis(self, target):
        """Use the same ordered search for a deterministic Poison application."""
        if (
            target not in combat_predictor.active_monsters(self.game)
            or combat_predictor.power_amount(target, "Artifact") > 0
            or self._potion_changes_red_skull_state(("poisonpotion",))
        ):
            return None
        index = list(self.game.monsters).index(target)
        hypothetical = copy.deepcopy(self.game)
        affected = hypothetical.monsters[index]
        amount = 12 if self._has_relic("Sacred Bark") else 6
        existing = next((
            power for power in affected.powers
            if self._token(getattr(power, "power_id", "")) == "poison"
        ), None)
        if existing is not None:
            existing.amount += amount
        else:
            affected.powers.append(SimpleNamespace(
                power_id="Poison", power_name="Poison", amount=amount,
            ))
        planner = self._counterfactual_combat_planner(hypothetical)
        action = planner.choose_card_action(hypothetical)
        decision = planner.last_decision or {}
        search = decision.get("search") or {}
        return {
            "loss": self._planned_turn_hp_loss(action, decision),
            "true_combat_end": bool(search.get("true_combat_end")),
            "final_enemy_hp": list(search.get("final_enemy_hp") or []),
            "planned_card_ids": [
                entry.get("card_id") for entry in decision.get("planned_sequence") or []
                if isinstance(entry, dict)
            ],
            "potion_sequence": ["poisonpotion"],
        }

    def _hypothetical_stat_potion_analysis(self, potion_id):
        """Re-plan deterministic stat, energy, and Defect orb potion effects."""

        potion_ids = (
            (self._token(potion_id),)
            if isinstance(potion_id, str)
            else tuple(self._token(item) for item in potion_id)
        )
        supported = {
            "dexteritypotion", "strengthpotion", "energypotion",
            "essenceofdarkness", "potionofcapacity",
        }
        if not potion_ids or any(item not in supported for item in potion_ids):
            return None
        if self._potion_changes_red_skull_state(potion_ids):
            return None
        multiplier = 2 if self._has_relic("Sacred Bark") else 1
        hypothetical = copy.copy(self.game)
        hypothetical.player = copy.copy(self.game.player)
        hypothetical.monsters = []
        for original in getattr(self.game, "monsters", []) or []:
            monster = copy.copy(original)
            monster.powers = [
                copy.copy(power)
                for power in getattr(original, "powers", []) or []
            ]
            hypothetical.monsters.append(monster)
        hypothetical.hand = []
        dexterity = 2 * multiplier * potion_ids.count("dexteritypotion")
        strength = 2 * multiplier * potion_ids.count("strengthpotion")
        current_dexterity = combat_predictor.signed_power_amount(
            self.game.player, "Dexterity", "DexterityPower"
        )
        frail = combat_predictor.has_power(
            self.game.player, "Frail", "FrailPower"
        )
        weak = combat_predictor.has_power(
            self.game.player, "Weak", "Weakened"
        )
        for original in getattr(self.game, "hand", []) or []:
            card = copy.copy(original)
            base_block = getattr(card, "base_block", None)
            grants_block = (
                int(base_block or 0) > 0
                or (
                    base_block is None
                    and int(getattr(card, "block", 0) or 0) > 0
                )
            )
            if dexterity and grants_block:
                if base_block is not None:
                    rebuilt = max(
                        0,
                        int(base_block or 0)
                        + current_dexterity
                        + dexterity,
                    )
                    card.block = int(rebuilt * 0.75) if frail else rebuilt
                else:
                    increment = int(dexterity * 0.75) if frail else dexterity
                    card.block = max(
                        0, int(getattr(card, "block", 0) or 0)
                    ) + increment
            if strength and getattr(card, "type", None) == spirecomm.spire.card.CardType.ATTACK:
                per_hit = strength
                if self._token(getattr(card, "card_id", "")) == "heavyblade":
                    per_hit *= max(
                        3, int(getattr(card, "magic_number", 0) or 0)
                    )
                if weak:
                    per_hit = int(per_hit * 0.75)
                card.damage = max(
                    0, int(getattr(card, "damage", 0) or 0)
                ) + per_hit
            hypothetical.hand.append(card)
        if "energypotion" in potion_ids:
            hypothetical.player.energy = max(
                0, int(getattr(self.game.player, "energy", 0) or 0)
            ) + 2 * multiplier * potion_ids.count("energypotion")

        # New CommunicationMod frames expose max_orbs directly. Occupied orb
        # rows alone cannot reveal capacity after Consume, because empty
        # slots are not serialized. Older/test payloads retain the base-3
        # compatibility fallback. Resolve each potion in caller order.
        # Capacity + Essence is order-sensitive:
        # Capacity first makes Essence channel into every enlarged slot;
        # Essence first fills only the old slots and Capacity adds empties.
        serialized_orbs = [
            copy.copy(orb)
            for orb in getattr(self.game.player, "orbs", []) or []
        ]
        occupied_orbs = [
            orb for orb in serialized_orbs
            if self._token(getattr(orb, "orb_id", ""))
            not in {"", "empty"}
        ]
        authoritative_orb_slots = getattr(
            self.game.player, "max_orbs", None
        )
        orb_slots_before = (
            max(
                len(occupied_orbs),
                max(0, int(authoritative_orb_slots or 0)),
            )
            if authoritative_orb_slots is not None
            else max(
                len(occupied_orbs),
                len(serialized_orbs) if serialized_orbs else 3,
            )
        )
        orb_slots_after = orb_slots_before
        occupied_orbs_before = len(occupied_orbs)
        focus = combat_predictor.signed_power_amount(
            self.game.player, "Focus"
        )
        resolution_planner = FastCombatPlanner(self.priorities)
        monsters = list(hypothetical.monsters)
        monster_hp = [
            max(0, int(getattr(monster, "current_hp", 0) or 0))
            for monster in monsters
        ]
        monster_block = [
            max(0, int(getattr(monster, "block", 0) or 0))
            for monster in monsters
        ]
        damage_value = [0.0 for _ in monsters]
        mode_shift_remaining = [
            combat_predictor.power_amount(
                monster, "Mode Shift", "ModeShift", "ModeShiftPower"
            )
            for monster in monsters
        ]
        neutralized = set()
        electrodynamics = combat_predictor.has_power(
            hypothetical.player, "Electrodynamics", "ElectrodynamicsPower"
        )
        orb_channels = 0
        orb_overflow_evokes = 0
        frost_evoke_block = 0
        plasma_evoke_energy = 0
        dark_evoke_damage = 0
        lightning_evoke_damage = 0
        unmodeled_lightning_evokes = 0

        def alive_indexes():
            return [
                index for index, monster in enumerate(monsters)
                if monster_hp[index] > 0
                and not bool(getattr(monster, "half_dead", False))
                and not bool(getattr(monster, "is_gone", False))
            ]

        def apply_orb_damage(index, amount):
            before = monster_hp[index]
            dealt = resolution_planner._apply_enemy_damage_packet(
                monsters[index],
                index,
                monster_hp,
                monster_block,
                damage_value,
                mode_shift_remaining,
                neutralized,
                amount,
                blockable=True,
            )
            if (
                monster_hp[index] <= 0
                and not resolution_planner._is_true_death_at_hp(
                    monsters[index], monster_hp[index], monsters, monster_hp
                )
            ):
                # Rebirth/Darkling states are not a proven potion kill in the
                # current serialized phase.  Cap at one HP rather than letting
                # the counterfactual invent combat completion.
                corrected = max(0, before - 1)
                overclaim = max(0, int(dealt) - corrected)
                monster_hp[index] = 1
                damage_value[index] = max(
                    0.0, float(damage_value[index]) - overclaim
                )
                dealt = corrected
            return max(0, int(dealt or 0))

        def resolve_damage_orb(evoked):
            nonlocal unmodeled_lightning_evokes
            evoked_id = self._token(getattr(evoked, "orb_id", ""))
            amount = max(
                0, int(getattr(evoked, "evoke_amount", 0) or 0)
            )
            living = alive_indexes()
            if amount <= 0 or not living:
                return 0
            if evoked_id == "dark":
                targets = [
                    min(living, key=lambda index: (monster_hp[index], index))
                ]
            elif evoked_id == "lightning" and electrodynamics:
                targets = list(living)
            elif evoked_id == "lightning" and len(living) == 1:
                targets = [living[0]]
            else:
                # Ordinary multi-enemy Lightning is random.  Leaving it out
                # is conservative and, unlike Dark, cannot fabricate a rescue
                # by assigning the packet to a convenient attacker.
                if evoked_id == "lightning":
                    unmodeled_lightning_evokes += 1
                return 0
            return sum(apply_orb_damage(index, amount) for index in targets)

        # Essence of Darkness channels one Dark *per current Orb Slot*;
        # Sacred Bark doubles that per-slot channel count.  Resolving every
        # channel in order is essential: a full three-slot row evokes all
        # three old orbs, and Bark then starts evoking newly channelled Darks.
        for potion_item in potion_ids:
            if potion_item == "potionofcapacity":
                orb_slots_after += 2 * multiplier
                continue
            if potion_item != "essenceofdarkness":
                continue
            channels = orb_slots_after * multiplier
            orb_channels += channels
            for _ in range(channels):
                if len(occupied_orbs) >= orb_slots_after:
                    evoked = occupied_orbs.pop(0)
                    orb_overflow_evokes += 1
                    evoked_id = self._token(
                        getattr(evoked, "orb_id", "")
                    )
                    evoked_amount = max(
                        0, int(getattr(evoked, "evoke_amount", 0) or 0)
                    )
                    if evoked_id == "frost":
                        frost_evoke_block += evoked_amount
                        hypothetical.player.block = max(
                            0,
                            int(
                                getattr(hypothetical.player, "block", 0)
                                or 0
                            ),
                        ) + evoked_amount
                    elif evoked_id == "plasma":
                        plasma_evoke_energy += evoked_amount
                        hypothetical.player.energy = max(
                            0,
                            int(
                                getattr(hypothetical.player, "energy", 0)
                                or 0
                            ),
                        ) + evoked_amount
                    elif evoked_id == "dark":
                        dark_evoke_damage += resolve_damage_orb(evoked)
                    elif evoked_id == "lightning":
                        lightning_evoke_damage += resolve_damage_orb(evoked)
                dark_amount = max(0, 6 + focus)
                occupied_orbs.append(Orb(
                    "Dark", "Dark", dark_amount, dark_amount
                ))

        for index, monster in enumerate(monsters):
            monster.current_hp = max(0, int(monster_hp[index]))
            monster.block = max(0, int(monster_block[index]))
            for power in getattr(monster, "powers", []) or []:
                if self._token(
                    getattr(power, "power_id", getattr(power, "name", ""))
                ) in {"modeshift", "modeshiftpower"}:
                    power.amount = max(0, int(mode_shift_remaining[index]))
            if index in neutralized:
                monster.move_adjusted_damage = 0
                monster.move_hits = 0
        hypothetical.player.orbs = list(occupied_orbs) + [
            Orb("Empty", "Empty", 0, 0)
            for _ in range(max(0, orb_slots_after - len(occupied_orbs)))
        ]
        planner = self._counterfactual_combat_planner(hypothetical)
        action = planner.choose_card_action(hypothetical)
        decision = dict(planner.last_decision or {})
        loss = self._planned_turn_hp_loss(action, decision)
        search = dict(decision.get("search") or {})
        return {
            "loss": None if loss is None else max(0, int(loss)),
            "true_combat_end": bool(search.get("true_combat_end")),
            "final_enemy_hp": list(search.get("final_enemy_hp") or []),
            "planned_card_ids": [
                item.get("card_id")
                for item in decision.get("planned_sequence") or []
                if isinstance(item, dict) and item.get("card_id")
            ],
            "orb_slots_before": orb_slots_before,
            "orb_slots_after": orb_slots_after,
            "occupied_orbs_before": occupied_orbs_before,
            "occupied_orbs_after": len(occupied_orbs),
            "orb_ids_after": [
                self._token(getattr(orb, "orb_id", ""))
                for orb in occupied_orbs
            ],
            "orb_channels": orb_channels,
            "orb_overflow_evokes": orb_overflow_evokes,
            "frost_evoke_block": frost_evoke_block,
            "plasma_evoke_energy": plasma_evoke_energy,
            "dark_evoke_damage": dark_evoke_damage,
            "lightning_evoke_damage": lightning_evoke_damage,
            "unmodeled_lightning_evokes": unmodeled_lightning_evokes,
            "potion_sequence": list(potion_ids),
            "post_potion_enemy_hp": [
                max(0, int(value)) for value in monster_hp
            ],
            "post_potion_enemy_block": [
                max(0, int(value)) for value in monster_block
            ],
        }

    def _duplication_potion_analysis(
        self, planned_turn_loss=None, planned_action=None
    ):
        """Find a genuinely high-margin next card for Duplication Potion.

        Each candidate is evaluated by a fresh planner with a zero-energy
        duplicate beside the real card.  A result is accepted only when the
        simulated line actually starts with both copies (or the planner's
        exact single-target lethal-combo proof does).  This prevents a weak
        Cold Snap/Defend from inheriting value created by some later card.
        """

        if self._potion_changes_red_skull_state(("duplicationpotion",)):
            return None
        baseline_decision = self.combat_planner.last_decision or {}
        baseline_loss = planned_turn_loss
        if baseline_loss is None:
            baseline_planner = self._counterfactual_combat_planner(self.game)
            planned_action = baseline_planner.choose_card_action(self.game)
            baseline_decision = baseline_planner.last_decision or {}
            baseline_loss = self._planned_turn_hp_loss(
                planned_action, baseline_decision
            )
        if baseline_loss is None:
            return None
        baseline_loss = max(0, int(baseline_loss))
        baseline_search = baseline_decision.get("search") or {}
        baseline_dead = int(baseline_search.get("enemies_dead", 0) or 0)
        baseline_score = float(baseline_decision.get("plan_score", 0.0) or 0.0)
        active = combat_predictor.active_monsters(self.game)
        hard_fight = (
            self.game.room_type in {"MonsterRoomElite", "MonsterRoomBoss"}
            or self._is_scaling_combat_threat(active)
        )
        results = []
        for card_index, original in enumerate(getattr(self.game, "hand", []) or []):
            if not getattr(original, "is_playable", False):
                continue
            if getattr(original, "type", None) in {
                spirecomm.spire.card.CardType.CURSE,
                spirecomm.spire.card.CardType.STATUS,
            }:
                continue
            original_uuid = getattr(original, "uuid", None)
            if not original_uuid:
                continue

            hypothetical = copy.copy(self.game)
            hypothetical.player = copy.copy(self.game.player)
            hypothetical.hand = [
                copy.copy(card)
                for card in getattr(self.game, "hand", []) or []
            ]
            simulated_original = hypothetical.hand[card_index]
            duplicate = copy.copy(simulated_original)
            duplicate.uuid = f"{original_uuid}::duplication-potion"
            duplicate.cost = 0
            duplicate.is_playable = True
            hypothetical.hand.insert(card_index + 1, duplicate)

            planner = self._counterfactual_combat_planner(hypothetical)
            action = planner.choose_card_action(hypothetical)
            decision = planner.last_decision or {}
            candidate_loss = self._planned_turn_hp_loss(action, decision)
            if candidate_loss is None:
                continue
            sequence = decision.get("planned_sequence") or []
            pair_uuids = {original_uuid, duplicate.uuid}
            starts_with_exact_pair = (
                len(sequence) >= 2
                and {
                    sequence[0].get("card_uuid"),
                    sequence[1].get("card_uuid"),
                }
                == pair_uuids
                and sequence[0].get("target_key")
                == sequence[1].get("target_key")
            )
            exact_single_target_lethal = (
                not sequence
                and len(active) == 1
                and decision.get("reason") == "guaranteed_attack_combo_lethal"
                and int(decision.get("combo_cards", 0) or 0) >= 2
                and getattr(getattr(action, "card", None), "uuid", None)
                in pair_uuids
            )
            if not (starts_with_exact_pair or exact_single_target_lethal):
                continue

            search = decision.get("search") or {}
            candidate_dead = int(search.get("enemies_dead", 0) or 0)
            marginal_kills = max(0, candidate_dead - baseline_dead)
            loss_reduction = max(0, baseline_loss - int(candidate_loss))
            plan_score = float(decision.get("plan_score", 0.0) or 0.0)
            plan_score_gain = plan_score - baseline_score
            card_id = self._token(getattr(original, "card_id", ""))
            premium_setup = bool(
                hard_fight
                and (
                    getattr(original, "type", None)
                    == spirecomm.spire.card.CardType.POWER
                    or card_id
                    in self.SCALING_CARD_IDS.get(self.chosen_class, set())
                )
                and plan_score_gain >= 18.0
            )
            prevents_lethal = (
                baseline_loss
                >= int(getattr(self.game.player, "current_hp", 1) or 1)
                and int(candidate_loss)
                < int(getattr(self.game.player, "current_hp", 1) or 1)
            )
            worthwhile = (
                prevents_lethal
                or loss_reduction >= 4
                or marginal_kills > 0
                or premium_setup
            )
            value = (
                loss_reduction * 3.2
                + marginal_kills * 24.0
                + (18.0 if premium_setup else 0.0)
            )
            if prevents_lethal:
                value = max(110.0, value)
            target = getattr(action, "target_monster", None)
            results.append({
                "card": original,
                "card_uuid": original_uuid,
                "candidate_loss": int(candidate_loss),
                "baseline_loss": baseline_loss,
                "loss_reduction": loss_reduction,
                "marginal_kills": marginal_kills,
                "plan_score_gain": plan_score_gain,
                "premium_setup": premium_setup,
                "prevents_lethal": prevents_lethal,
                "worthwhile": worthwhile,
                "value": value if worthwhile else -100.0,
                "target_index": getattr(target, "monster_index", None),
            })

        if not results:
            return None
        return max(
            results,
            key=lambda item: (
                item["worthwhile"],
                item["value"],
                -item["candidate_loss"],
                item["marginal_kills"],
            ),
        )

    def _combat_identity(self, game=None):
        """Return a controller-local identity for the current combat.

        Act/floor/turn are not sufficient for chained event fights such as
        Colosseum.  The local epoch distinguishes successive combats even
        when their enemy groups happen to match, while the enemy signature
        fails closed if a transition was not observed between two groups.
        """

        game = self.game if game is None else game
        enemies = tuple(
            (
                self._token(
                    getattr(monster, "monster_id", "")
                    or getattr(monster, "name", "")
                ),
                int(getattr(monster, "monster_index", index) or index),
                int(getattr(monster, "max_hp", 0) or 0),
            )
            for index, monster in enumerate(getattr(game, "monsters", []) or [])
        )
        return (
            int(self._combat_epoch),
            int(getattr(game, "act", 0) or 0),
            int(getattr(game, "floor", 0) or 0),
            str(getattr(game, "room_type", "") or ""),
            enemies,
        )

    @staticmethod
    def _selection_context_matches_game(context, game):
        if (
            context.get("act") != int(getattr(game, "act", 0) or 0)
            or context.get("floor") != int(getattr(game, "floor", 0) or 0)
        ):
            return False
        if "turn" in context and context.get("turn") != int(
            getattr(game, "turn", 0) or 0
        ):
            return False
        return True

    def confirm_card_selection(self, game, card_uuid):
        """Consume a bound GRID context after authoritative verification."""

        context = self.pending_selection_context or {}
        if context.get("kind") not in {
            "positive_card", "liquid_memories", "destructive_card",
        }:
            return
        if not self._selection_context_matches_game(context, game):
            return
        expected = list(context.get("card_uuids") or [])
        if not expected and context.get("card_uuid"):
            expected = [context.get("card_uuid")]
        if card_uuid not in expected:
            return
        confirmed = list(context.get("confirmed_card_uuids") or [])
        if card_uuid not in confirmed:
            confirmed.append(card_uuid)
        if expected and all(item in confirmed for item in expected):
            self.pending_selection_context = None
        else:
            context["confirmed_card_uuids"] = confirmed

    def _bind_bottled_relic_reward_grid(self, reward):
        """Bind a bottled relic's immediate typed GRID before it opens.

        CommunicationMod does not serialize ``current_action`` or a parent
        choice on the GRID opened by a relic reward.  The reward itself is
        therefore the last authoritative frame which identifies the
        operation.  Keep this binding scoped to the same act/floor and let
        ``choose_grid_action`` additionally verify the exact type-only surface
        before using it.
        """

        relic = getattr(reward, "relic", None)
        relic_token = self._token(getattr(relic, "relic_id", ""))
        bottle = {
            "bottledflame": ("ATTACK", "bottle_attack"),
            "bottledlightning": ("SKILL", "bottle_skill"),
            "bottledtornado": ("POWER", "bottle_power"),
        }.get(relic_token)
        if getattr(reward, "reward_type", None) != RewardType.RELIC or not bottle:
            return
        expected_card_type, operation = bottle
        source = {
            "bottledflame": "bottled_flame",
            "bottledlightning": "bottled_lightning",
            "bottledtornado": "bottled_tornado",
        }[relic_token]
        self.pending_selection_context = {
            "kind": "positive_card",
            "source": source,
            "operation": operation,
            "expected_card_type": expected_card_type,
            "relic_count_before": self._relic_count(
                getattr(relic, "relic_id", "")
            ),
            "act": int(self.game.act),
            "floor": int(self.game.floor),
        }

    def _expire_bottled_relic_reward_grid_context(self):
        """Keep a bottle binding only for its reward retry or immediate GRID."""

        context = self.pending_selection_context or {}
        if not (
            context.get("kind") == "positive_card"
            and context.get("source") in {
                "bottled_flame", "bottled_lightning", "bottled_tornado",
            }
        ):
            return
        same_location = (
            context.get("act") == int(getattr(self.game, "act", 0) or 0)
            and context.get("floor")
            == int(getattr(self.game, "floor", 0) or 0)
        )
        if same_location and self.game.screen_type == ScreenType.GRID:
            return
        if same_location and self.game.screen_type == ScreenType.COMBAT_REWARD:
            baseline = context.get("relic_count_before")
            reward_still_visible = any(
                getattr(reward, "reward_type", None) == RewardType.RELIC
                and self._token(
                    getattr(getattr(reward, "relic", None), "relic_id", "")
                ) == self._token(context.get("source"))
                for reward in getattr(self.game.screen, "rewards", []) or []
            )
            if (
                type(baseline) is int
                and self._relic_count(context.get("source")) == baseline
                and reward_still_visible
            ):
                # The exact pre-click frame can be retried after a stale or
                # rejected receipt.  Any other strategic screen ends this
                # one-transition binding.
                return
        self.pending_selection_context = None

    def confirm_card_play(self, game, card_uuid):
        """Consume Duplication Potion's next-card binding after a real play."""

        context = self.pending_selection_context or {}
        if context.get("kind") != "duplication_potion" or not context.get(
            "confirmed"
        ):
            return
        if not self._selection_context_matches_game(context, game):
            return
        if context.get("combat_identity") != self._combat_identity(game):
            return
        if context.get("card_uuid") != card_uuid:
            return
        self.pending_selection_context = None

    def _bound_duplication_card_action(self):
        """Return the UUID-bound card after confirmed Duplication Potion use."""

        context = self.pending_selection_context or {}
        if context.get("kind") != "duplication_potion" or not context.get("confirmed"):
            return None
        turn_key = (
            int(getattr(self.game, "act", 0) or 0),
            int(getattr(self.game, "floor", 0) or 0),
            int(getattr(self.game, "turn", 0) or 0),
        )
        context_key = (
            context.get("act"), context.get("floor"), context.get("turn")
        )
        if context_key != turn_key:
            self.pending_selection_context = None
            return None
        if context.get("combat_identity") != self._combat_identity():
            self.pending_selection_context = None
            return None
        wanted_uuid = context.get("card_uuid")
        card = next(
            (
                item for item in getattr(self.game, "hand", []) or []
                if wanted_uuid
                and getattr(item, "uuid", None) == wanted_uuid
                and getattr(item, "is_playable", False)
            ),
            None,
        )
        if card is None:
            self.pending_selection_context = None
            return None
        if getattr(card, "has_target", False):
            target_index = context.get("target_index")
            target = next(
                (
                    monster
                    for monster in combat_predictor.active_monsters(self.game)
                    if getattr(monster, "monster_index", None) == target_index
                ),
                None,
            )
            if target is None:
                self.pending_selection_context = None
                return None
            return PlayCardAction(card=card, target_monster=target)
        return PlayCardAction(card=card)

    def _bound_duplication_card_decision(self, bound_action):
        """Attach ordered copy evidence to a bound Duplication-Potion play.

        The potion analysis binds the exact next card before the potion is
        submitted.  Once the authoritative follow-up frame exposes
        ``DuplicationPower``, re-run the ordinary planner read-only and retain
        its damage/state transition only when it independently chooses that
        same UUID and target.  This gives telemetry the real sequential copy
        result without allowing a different plan to justify the bound play.
        """

        card = getattr(bound_action, "card", None)
        target = getattr(bound_action, "target_monster", None)
        card_uuid = getattr(card, "uuid", None)
        target_index = getattr(target, "monster_index", None)
        fallback = {
            "reason": "duplication_potion_bound_next_card",
            "card_id": getattr(card, "card_id", None),
            "card_uuid": card_uuid,
            "target_index": target_index,
            "ordered_copy_evidence": "unavailable",
        }
        planner = self._counterfactual_combat_planner(self.game)
        planned_action = planner.choose_card_action(self.game)
        if not isinstance(planned_action, PlayCardAction):
            return fallback
        planned_card = getattr(planned_action, "card", None)
        planned_target = getattr(planned_action, "target_monster", None)
        if (
            getattr(planned_card, "uuid", None) != card_uuid
            or getattr(planned_target, "monster_index", None) != target_index
        ):
            return fallback
        decision = copy.deepcopy(planner.last_decision or {})
        search = decision.get("search") or {}
        resolution_count = search.get("first_action_resolution_count")
        if (
            not isinstance(resolution_count, int)
            or isinstance(resolution_count, bool)
            or resolution_count <= 1
        ):
            return fallback
        planned_reason = decision.get("reason")
        decision.update(fallback)
        decision.update({
            "reason": "duplication_potion_bound_next_card",
            "bound_plan_reason": planned_reason,
            "ordered_copy_evidence": "bound_fresh_turn_search",
        })
        return decision

    def _regen_potion_projection(self, planned_combat_end=False):
        """Bound Regen Potion value to end-turn ticks this fight can realize.

        ``_expected_remaining_turns`` includes the eventual terminal player
        turn, but enemy death closes combat before that turn's Regeneration
        hook. A non-terminal current plan therefore guarantees at least this
        turn's tick and can realize at most ``remaining_turns - 1`` ticks.
        This is a cheap horizon estimate over the already serialized combat
        state; it does not invoke a second card search.
        """

        hp = max(
            0, int(getattr(self.game.player, "current_hp", 0) or 0)
        )
        max_hp = max(
            hp, int(getattr(self.game.player, "max_hp", hp) or hp)
        )
        missing_hp = max(0, max_hp - hp)
        potency = 5 * (2 if self._has_relic("Sacred Bark") else 1)
        healing_blocked = self._has_relic("Mark of the Bloom")
        active = combat_predictor.active_monsters(self.game)
        if not active:
            active = combat_predictor.living_monsters(self.game)

        expected_remaining_turns = 0
        cashable_turn_ends = 0
        if active and not planned_combat_end and not healing_blocked:
            expected_remaining_turns = max(
                1,
                int(
                    self.combat_planner._expected_remaining_turns(self.game)
                    or 0
                ),
            )
            cashable_turn_ends = min(
                potency, max(1, expected_remaining_turns - 1)
            )

        magic_flower = self._has_relic("Magic Flower")

        def modified_heal(amount):
            amount = max(0, int(amount))
            return (3 * amount + 1) // 2 if magic_flower else amount

        regen_healing = sum(
            modified_heal(potency - tick)
            for tick in range(cashable_turn_ends)
        )
        # Toy Ornithopter is genuinely immediate even though Regen itself is
        # delayed. Keep that packet in the projection, but never use it to
        # bypass the terminal-combat hard reserve below.
        immediate_healing = self._immediate_potion_hp_gain("regenpotion")
        projected_healing = min(
            missing_hp, max(0, immediate_healing + regen_healing)
        )
        first_turn_healing = min(
            missing_hp,
            max(
                0,
                immediate_healing
                + (
                    modified_heal(potency)
                    if cashable_turn_ends > 0
                    else 0
                ),
            ),
        )
        return {
            "planned_combat_end": bool(planned_combat_end),
            "healing_blocked": bool(healing_blocked),
            "potency": int(potency),
            "expected_remaining_turns": int(expected_remaining_turns),
            "cashable_turn_ends": int(cashable_turn_ends),
            "immediate_healing": int(immediate_healing),
            "projected_healing": int(projected_healing),
            "first_turn_healing": int(first_turn_healing),
        }

    def _hand_filter_potion_analysis(
        self, potion_id, planned_combat_end=False
    ):
        """Price Elixir/Gambler from the hand they can actually improve.

        These potions used to share the generic random-potion score.  That
        missed their defining value: removing persistent curse/status clog, or
        exchanging a provably weak subset for known/expected redraws.  Keep the
        estimate deliberately bounded.  It protects the ordered card plan,
        ignores cards which will clear themselves for free, and refuses to
        spend into a terminal combat or an equally bad redraw pool.
        """

        potion_id = self._token(potion_id)
        if potion_id not in {"elixir", "elixirpotion", "gamblersbrew"}:
            return None

        hand = list(getattr(self.game, "hand", []) or [])
        if not hand or planned_combat_end:
            return {
                "worthwhile": False,
                "score": -1000.0,
                "reason": "combat_end_or_empty_hand",
                "target_card_ids": [],
            }

        room_type = str(getattr(self.game, "room_type", "") or "")
        hard_fight = room_type in {"MonsterRoomElite", "MonsterRoomBoss"}
        boss = room_type == "MonsterRoomBoss"
        try:
            horizon = int(
                self.combat_planner._expected_remaining_turns(self.game)
            )
        except (AttributeError, TypeError, ValueError):
            horizon = 2 if hard_fight else 1

        planned_sequence = list(
            (self.combat_planner.last_decision or {}).get(
                "planned_sequence", []
            )
            or []
        )
        planned_uuids = {
            entry.get("card_uuid")
            for entry in planned_sequence
            if isinstance(entry, dict) and entry.get("card_uuid")
        }
        # A context-bound ordered line is authoritative.  Some direct unit
        # callers do not carry _combat_context, so retain the UUIDs recorded by
        # that line as a conservative fallback.
        planned_uuids.update(self._planned_hand_keep_uuids(hand))

        player = getattr(self.game, "player", None)
        rows = []
        # Keep strategic hand-quality value separate from HP loss that the
        # potion is guaranteed to prevent this turn.  Normality/Doubt/Shame
        # can be extremely harmful without being literal current-turn damage;
        # treating that value as HP used to let Elixir masquerade as a lethal
        # rescue and beat a genuinely lifesaving Block/Ghost potion.
        normality_count = 0
        pain_count = 0
        for card in hand:
            card_id = self._token(getattr(card, "card_id", ""))
            card_type = getattr(card, "type", None)
            rarity = getattr(card, "rarity", None)
            is_curse = (
                card_type == spirecomm.spire.card.CardType.CURSE
                or rarity == spirecomm.spire.card.CardRarity.CURSE
            )
            is_status = card_type == spirecomm.spire.card.CardType.STATUS
            ethereal = bool(getattr(card, "ethereal", False))
            cost = int(getattr(card, "cost", -1) or 0)
            free_self_clear = bool(
                is_status
                and getattr(card, "is_playable", False)
                and getattr(card, "exhausts", False)
                and cost <= 0
            )
            returns_when_exhausted = card_id == "necronomicurse"
            persistent_clog = bool(
                (is_curse or is_status)
                and not ethereal
                and not free_self_clear
                and not returns_when_exhausted
            )
            keep_score = float(self._hand_card_keep_score(card))
            protected = getattr(card, "uuid", None) in planned_uuids

            quality_value = 0.0
            direct_current_turn_hp_loss_prevented = 0
            if card_id == "normality":
                normality_count += 1
                # Normality is especially damaging when the exact plan has
                # enough playable resolutions to cross its three-card cap.
                quality_value = 12.0 if len(planned_sequence) >= 3 else 7.0
            elif card_id == "pain":
                pain_count += 1
                # Removing Pain can prevent one HP per later card play, but
                # the current ordered line is allowed to change after the
                # selection overlay.  Retain its quality value without
                # claiming an exact lethal reduction.
                quality_value = min(
                    8.0, max(2.0, len(planned_sequence) * 1.5)
                )
            elif card_id == "regret":
                # Regret depends on the eventual end-of-turn hand size.  The
                # present hand is not a proof of that size.
                quality_value = min(
                    10.0, max(3.0, len(hand) - len(planned_sequence))
                )
            elif card_id in {"decay", "burn"}:
                # These non-ethereal status/curse cards deal a fixed amount
                # at end of turn when left in hand.  Exhausting the exact card
                # is therefore a strict current-turn lower bound.
                direct_current_turn_hp_loss_prevented = (
                    4 if int(getattr(card, "upgrades", 0) or 0) else 2
                )
                quality_value = float(
                    direct_current_turn_hp_loss_prevented
                )
            elif card_id in {"doubt", "shame"}:
                # Their debuffs begin at end of turn and affect later state;
                # they do not subtract from the current incoming attack.
                quality_value = 4.0
            rows.append({
                "card": card,
                "card_id": getattr(card, "card_id", None),
                "score": keep_score,
                "is_curse": bool(is_curse),
                "is_status": bool(is_status),
                "persistent_clog": persistent_clog,
                "ethereal": ethereal,
                "free_self_clear": free_self_clear,
                "returns_when_exhausted": returns_when_exhausted,
                "protected": protected,
                "quality_value": quality_value,
                "direct_current_turn_hp_loss_prevented": (
                    direct_current_turn_hp_loss_prevented
                ),
            })

        available = [row for row in rows if not row["protected"]]
        highest = max((row["score"] for row in available), default=0.0)
        weak_cutoff = min(8.0, highest - 4.0)
        low_quality = [
            row for row in available
            if row["is_curse"]
            or row["is_status"]
            or row["score"] <= weak_cutoff
        ]

        if potion_id in {"elixir", "elixirpotion"}:
            # Elixir is a permanent combat-cycle cleanup.  Ethereal/free
            # self-clearing cards need no bottle, and Necronomicurse returns
            # immediately after exhaust.  In a long boss fight it may also
            # thin several genuinely weak ordinary cards, but never a planned
            # card or a lone mediocre starter.
            targets = [
                row for row in available if row["persistent_clog"]
            ]
            if hard_fight and horizon >= 4:
                targets.extend(
                    row for row in low_quality
                    if not row["is_curse"]
                    and not row["is_status"]
                    and row["score"] <= 2.0
                    and row not in targets
                )

            persistent = sum(row["persistent_clog"] for row in targets)
            ordinary_weak = sum(
                not row["is_curse"] and not row["is_status"]
                for row in targets
            )
            draw_pile_size = len(getattr(self.game, "draw_pile", []) or [])
            turns_until_recycle = max(1, (draw_pile_size + 4) // 5)
            recycle_reachable = horizon > turns_until_recycle
            target_quality_value = sum(
                float(row["quality_value"]) for row in targets
            )
            direct_current_turn_hp_loss_prevented = sum(
                int(row["direct_current_turn_hp_loss_prevented"])
                for row in targets
            )
            if (
                persistent
                and not recycle_reachable
                and target_quality_value <= 0
            ):
                score = 4.0
            else:
                status_payoff = bool(
                    combat_predictor.has_power(
                        player, "Evolve", "EvolvePower",
                    )
                    or combat_predictor.has_power(
                        player, "Fire Breathing", "FireBreathingPower",
                    )
                )
                clog_weight = 3.25 if status_payoff else 5.0
                score = (
                    3.0
                    + persistent * clog_weight
                    + min(3, ordinary_weak) * 1.5
                    + target_quality_value
                )
                if boss and (
                    persistent >= 2
                    or ordinary_weak >= 3
                    or target_quality_value
                ):
                    score += 4.0
                elif hard_fight and (
                    persistent >= 2 or target_quality_value
                ):
                    score += 2.0
                if self._has_relic("Runic Pyramid") and targets:
                    score += 4.0

            worthwhile = bool(
                targets
                and (
                    persistent >= 2
                    or ordinary_weak >= 3
                    or target_quality_value >= 5.0
                )
                and score >= 13.0
            )
            return {
                "worthwhile": worthwhile,
                "score": round(score if worthwhile else min(score, 11.0), 3),
                "reason": "persistent_hand_cleanup",
                "target_card_ids": [row["card_id"] for row in targets],
                "target_card_uuids": [
                    getattr(row["card"], "uuid", None)
                    for row in targets
                    if getattr(row["card"], "uuid", None)
                ],
                "target_count": len(targets),
                "persistent_clog_count": int(persistent),
                "ordinary_weak_count": int(ordinary_weak),
                "hand_filter_quality_value": round(
                    target_quality_value, 3
                ),
                "direct_current_turn_hp_loss_prevented": int(
                    direct_current_turn_hp_loss_prevented
                ),
                "normality_count": int(normality_count),
                "pain_count": int(pain_count),
                "horizon": int(horizon),
                "turns_until_recycle": int(turns_until_recycle),
                "recycle_reachable": bool(recycle_reachable),
            }

        # Gambler's Brew needs an immediate redraw improvement, not merely bad
        # cards in hand.  Match the optional-selection cutoff, then compare the
        # discarded subset with the known top of draw pile or a bounded
        # reshuffle expectation.  This prevents drinking into another hand of
        # Wounds while still exploiting a curse/status-clogged boss turn.
        if combat_predictor.has_power(
            player, "No Draw", "NoDrawPower"
        ):
            return {
                "worthwhile": False,
                "score": -1000.0,
                "reason": "no_draw_blocks_gamblers_brew",
                "target_card_ids": [],
                "target_card_uuids": [],
                "target_count": 0,
                "clog_count": 0,
                "harmful_count": 0,
                "discarded_quality": 0.0,
                "expected_draw_quality": 0.0,
                "expected_redraw_gain": 0.0,
                "draw_mode": "blocked_by_no_draw",
                "horizon": int(horizon),
            }
        targets = low_quality
        redraw_count = len(targets)
        draw_pile = list(getattr(self.game, "draw_pile", []) or [])
        discard_pile = list(getattr(self.game, "discard_pile", []) or [])
        draw_mode = "none"
        expected_draw_quality = 0.0
        if (redraw_count and len(draw_pile) >= redraw_count
                and getattr(self.game, "draw_pile_order_known", True) is True):
            known_draws = list(reversed(draw_pile[-redraw_count:]))
            expected_draw_quality = sum(
                self._hand_card_keep_score(card) for card in known_draws
            )
            draw_mode = "known_top"
        elif redraw_count:
            reshuffles = len(draw_pile) < redraw_count
            reshuffle_pool = list(draw_pile)
            # Unknown order alone does not cause a shuffle. Discarded cards
            # enter the possible draw pool only when this pile is exhausted.
            if reshuffles:
                reshuffle_pool.extend(discard_pile)
                reshuffle_pool.extend(row["card"] for row in targets)
            if reshuffle_pool:
                average = sum(
                    self._hand_card_keep_score(card)
                    for card in reshuffle_pool
                ) / len(reshuffle_pool)
                expected_draw_quality = average * redraw_count
                draw_mode = (
                    "reshuffle_expectation" if reshuffles
                    else "unknown_draw_expectation"
                )

        discarded_quality = sum(row["score"] for row in targets)
        expected_gain = max(0.0, expected_draw_quality - discarded_quality)
        clog_count = sum(
            row["is_curse"] or row["is_status"] for row in targets
        )
        harmful_count = sum(row["quality_value"] > 0 for row in targets)
        material = bool(
            redraw_count
            and expected_gain >= 12.0
            and (
                redraw_count >= 2
                or harmful_count > 0
            )
            and (hard_fight or redraw_count >= 3)
        )
        score = (
            6.0
            + min(18.0, expected_gain * 0.22)
            + min(6.0, redraw_count * 2.0)
            + (4.0 if boss and material else 2.0 if hard_fight and material else 0.0)
        )
        return {
            "worthwhile": material,
            "score": round(score if material else min(score, 11.0), 3),
            "reason": "material_redraw_gain",
            "target_card_ids": [row["card_id"] for row in targets],
            "target_card_uuids": [
                getattr(row["card"], "uuid", None)
                for row in targets
                if getattr(row["card"], "uuid", None)
            ],
            "target_count": int(redraw_count),
            "clog_count": int(clog_count),
            "harmful_count": int(harmful_count),
            "discarded_quality": round(discarded_quality, 3),
            "expected_draw_quality": round(expected_draw_quality, 3),
            "expected_redraw_gain": round(expected_gain, 3),
            "draw_mode": draw_mode,
            "horizon": int(horizon),
        }

    def _potion_score(
        self,
        potion,
        incoming,
        target,
        planned_turn_loss=None,
        protected_planned_loss=None,
        unquantified_play_plan=False,
        liquid_memories_analysis=None,
        duplication_potion_analysis=None,
        regen_potion_projection=None,
        hand_filter_analysis=None,
        planned_combat_end=False,
    ):
        potion_id = self._token(getattr(potion, "potion_id", ""))
        turn_outcome = combat_predictor.projected_turn_outcome(self.game)
        attack_loss = turn_outcome.attack_hp_loss
        total_loss = turn_outcome.total_hp_loss
        hp = max(1, int(getattr(self.game.player, "current_hp", 1) or 1))
        elite_or_boss = self.game.room_type in {"MonsterRoomElite", "MonsterRoomBoss"}
        active = combat_predictor.active_monsters(self.game)
        trivial_fight = bool(active) and all(
            int(getattr(monster, "current_hp", 0) or 0) <= 1 for monster in active
        )
        hard_fight = (
            elite_or_boss or self._is_scaling_combat_threat(active)
        ) and not trivial_fight
        early_hard_fight = hard_fight and int(getattr(self.game, "turn", 0) or 0) <= 2
        target_hp = int(getattr(target, "current_hp", 0) or 0) if target is not None else 0
        comparison_loss = (
            total_loss
            if planned_turn_loss is None
            else max(0, int(planned_turn_loss))
        )
        safety_reserve = FastCombatPlanner._reactive_safety_reserve(
            self.game, hp
        )
        # A line need not be literally lethal to be an emergency: ending
        # below the dynamic reserve leaves no margin for the next intent and
        # is how multi-enemy turns snowball into a death. Keep this trigger
        # bounded to a positive, quantified current-turn loss so zero-loss
        # plans still preserve stochastic potions.
        reserve_breaking_crisis = (
            comparison_loss > 0
            and hp - comparison_loss < safety_reserve
        )
        lethal = comparison_loss >= hp
        max_hp = max(
            hp,
            int(getattr(self.game.player, "max_hp", hp) or hp),
        )
        low_hp_dangerous = (
            total_loss >= max(10, hp // 3)
            and hp * 2 <= max_hp
        )
        hard_fight = hard_fight or low_hp_dangerous
        early_hard_fight = (
            hard_fight and int(getattr(self.game, "turn", 0) or 0) <= 2
        )

        material_hand_filter = bool(
            potion_id == "gamblersbrew"
            and hand_filter_analysis
            and hand_filter_analysis.get("worthwhile")
        )
        if (
            planned_turn_loss == 0
            and potion_id in self.ZERO_LOSS_UNPROVEN_POTION_IDS
            and not material_hand_filter
        ):
            return -1000
        if potion_id in {"potionslot", "fairypotion"}:
            return -1000
        if self._has_relic("Mark of the Bloom"):
            if potion_id in {"bloodpotion", "regenpotion"}:
                return -1000
            if potion_id == "fruitjuice" and lethal:
                return -1000
        if trivial_fight:
            # Neow's Lament and equivalent deterministic one-HP encounters do
            # not justify consuming any combat potion, regardless of room type.
            return -1000
        if potion_id == "ancientpotion":
            player = getattr(self.game, "player", None)
            if combat_predictor.power_amount(player, "Artifact") > 0:
                return -1000
            incoming_debuff = any(
                "DEBUFF" in str(getattr(getattr(monster, "intent", None), "name", getattr(monster, "intent", ""))).upper()
                for monster in combat_predictor.active_monsters(self.game)
            )
            # Artifact does not stop Sentry Dazed cards or ordinary damage.
            return 20 if incoming_debuff and lethal else 14 if incoming_debuff else -100
        if potion_id == "blockpotion":
            if unquantified_play_plan:
                return 0
            protected = combat_predictor.projected_turn_outcome(
                self.game, extra_block=self._block_potion_amount()
            )
            protected_loss = protected.total_hp_loss
            if planned_turn_loss is not None and protected_planned_loss is None:
                # A card plan may already spend the same block. Without an
                # exact hypothetical search, the naked-END benefit is only an
                # upper bound and cannot justify consuming the potion.
                return 0
            if protected_planned_loss is None:
                mitigation = max(0, total_loss - protected_loss)
                final_comparison_loss = protected_loss
            else:
                final_comparison_loss = max(0, int(protected_planned_loss))
                mitigation = max(0, comparison_loss - final_comparison_loss)
            prevents_lethal = (
                comparison_loss >= hp
                and final_comparison_loss < hp
            )
            score = mitigation * (3.0 if prevents_lethal else 1.35)
            opportunity = self._potion_loss_opportunity(
                comparison_loss, final_comparison_loss
            )
            if opportunity.get("score") is not None:
                score = max(score, float(opportunity["score"]))
            # Saving the run is categorical; a two-damage Burn at two HP is
            # no less lethal than a twenty-damage attack and must clear the
            # ordinary potion threshold.
            return max(110.0, score) if prevents_lethal else score
        if potion_id == "ghostinajar":
            if unquantified_play_plan:
                return 0
            protected = combat_predictor.projected_turn_outcome(
                self.game, force_intangible=True
            )
            protected_loss = protected.total_hp_loss
            if planned_turn_loss is not None and protected_planned_loss is None:
                return 0
            if protected_planned_loss is None:
                mitigation = max(0, total_loss - protected_loss)
                final_comparison_loss = protected_loss
            else:
                final_comparison_loss = max(0, int(protected_planned_loss))
                mitigation = max(0, comparison_loss - final_comparison_loss)
            prevents_lethal = (
                comparison_loss >= hp
                and final_comparison_loss < hp
            )
            score = mitigation * (2.5 if prevents_lethal else 1.1)
            opportunity = self._potion_loss_opportunity(
                comparison_loss, final_comparison_loss
            )
            if opportunity.get("score") is not None:
                score = max(score, float(opportunity["score"]))
            return max(110.0, score) if prevents_lethal else score
        if potion_id == "speedpotion":
            if unquantified_play_plan:
                return -100
            if protected_planned_loss is None:
                protected_planned_loss = self._hypothetical_speed_potion_loss()
            if protected_planned_loss is None:
                return -100
            final_comparison_loss = max(0, int(protected_planned_loss))
            mitigation = max(0, comparison_loss - final_comparison_loss)
            # Speed expires at end of turn.  If the current ordered card plan
            # already loses zero HP, its +5 Dexterity has no survival margin
            # and must not be consumed as a generic elite-fight buff.
            if mitigation <= 0:
                return -100
            prevents_lethal = (
                comparison_loss >= hp and final_comparison_loss < hp
            )
            score = mitigation * (3.0 if prevents_lethal else 1.5)
            opportunity = self._potion_loss_opportunity(
                comparison_loss, final_comparison_loss
            )
            if opportunity.get("score") is not None:
                score = max(score, float(opportunity["score"]))
            return max(110.0, score) if prevents_lethal else score
        if potion_id == "weakpotion":
            if unquantified_play_plan or protected_planned_loss is None:
                return -100
            final_comparison_loss = max(0, int(protected_planned_loss))
            mitigation = max(0, comparison_loss - final_comparison_loss)
            if mitigation <= 0:
                return -100
            prevents_lethal = (
                comparison_loss >= hp and final_comparison_loss < hp
            )
            if lethal and not prevents_lethal:
                # Do not label a deterministic reduction as a rescue when
                # the complete post-Weak card plan is still dead.  If a draw
                # or another potion can change that result, use/reveal that
                # action first and evaluate Weak again from the new frame.
                return -100
            max_hp = max(
                1,
                int(
                    getattr(self.game.player, "max_hp", 0)
                    or getattr(self.game, "max_hp", 1)
                    or 1
                ),
            )
            hp_after_baseline = hp - comparison_loss
            critical_reserve = max(12, (max_hp * 40 + 99) // 100)
            low_reserve = hard_fight and hp_after_baseline <= critical_reserve
            # Weak lasts for several enemy turns, but only the current
            # serialized intent is deterministic.  Spend it before crisis
            # when its exact current reduction keeps a hard fight above the
            # run's HP reserve; do not invent future damage to justify it.
            multiplier = 3.0 if prevents_lethal else 2.2 if low_reserve else 1.4
            score = mitigation * multiplier
            opportunity = self._potion_loss_opportunity(
                comparison_loss, final_comparison_loss
            )
            if opportunity.get("score") is not None:
                score = max(score, float(opportunity["score"]))
            return max(110.0, score) if prevents_lethal else score
        if potion_id in {"firepotion", "explosivepotion"}:
            reaction = self._hypothetical_shifting_potion_analysis(potion_id, target)
            if reaction is not None and reaction["loss"] is not None:
                reduction = max(0, comparison_loss - reaction["loss"])
                if comparison_loss >= hp and reaction["survives"]:
                    return max(110.0, reduction * 3.0)
                if reduction > 0:
                    return max(0.0, reduction * 2.2)
        if potion_id == "firepotion":
            return 35 if 0 < target_hp <= 20 else (14 if elite_or_boss else 5)
        if potion_id == "explosivepotion":
            active = combat_predictor.active_monsters(self.game)
            kills = sum(1 for monster in active if int(getattr(monster, "current_hp", 0) or 0) <= 10)
            return len(active) * 7 + kills * 12
        if potion_id == "poisonpotion":
            if planned_combat_end or lethal or unquantified_play_plan:
                # Only the exact hypothetical plan below can certify rescue.
                return -100.0
            if target is None:
                return -1000.0
            baseline_hp = (self.combat_planner.last_decision.get("search") or {}).get(
                "final_enemy_hp", []
            )
            monsters = list(getattr(self.game, "monsters", []) or [])
            if len(baseline_hp) == len(monsters) and target in monsters:
                if baseline_hp[monsters.index(target)] <= 0:
                    return -1000.0
            projection = self.combat_planner.delayed_damage_projection(
                self.game, target, 12 if self._has_relic("Sacred Bark") else 6
            )
            damage = projection["marginal_damage"]
            if damage <= 0:
                return -1000.0
            low_reserve = hp * 2 <= max_hp and projection["ticks"] >= 2
            return damage * (0.9 if hard_fight else 0.65) + (4.0 if low_reserve else 0.0)
        if potion_id == "fearpotion":
            if target is None or combat_predictor.power_amount(target, "Vulnerable") > 0:
                return -100
            attack_damage = sum(
                combat_predictor.card_attack_profile(self.game, card)[0]
                for card in getattr(self.game, "hand", []) or []
                if getattr(card, "is_playable", False)
            )
            immediate_value = attack_damage * 0.5
            return min(34, immediate_value + (12 if elite_or_boss and target_hp >= 25 else 3))
        if potion_id == "steroidpotion":
            attack_hits = sum(
                combat_predictor.card_attack_profile(self.game, card)[1]
                for card in getattr(self.game, "hand", []) or []
                if getattr(card, "is_playable", False)
                and getattr(card, "type", None) == spirecomm.spire.card.CardType.ATTACK
            )
            added_damage = attack_hits * 5
            return min(34, added_damage + (8 if lethal else 4 if elite_or_boss else 0))
        if potion_id == "blessingoftheforge":
            playable = [
                card for card in getattr(self.game, "hand", []) or []
                if getattr(card, "is_playable", False)
                and int(getattr(card, "upgrades", 0) or 0) == 0
            ]
            attack_hits = sum(
                combat_predictor.card_attack_profile(self.game, card)[1]
                for card in playable
                if getattr(card, "type", None) == spirecomm.spire.card.CardType.ATTACK
            )
            block_cards = sum(
                1 for card in playable
                if max(0, int(getattr(card, "block", 0) or 0)) > 0
            )
            return min(30, attack_hits * 3 + block_cards * 3 + (8 if lethal else 4 if elite_or_boss else 0))
        if potion_id == "liquidmemories":
            analysis = liquid_memories_analysis
            if analysis is None:
                analysis = self._liquid_memories_analysis(planned_turn_loss)
            return -100 if analysis is None else float(analysis["value"])
        if potion_id == "sneckooil":
            hand = list(getattr(self.game, "hand", []) or [])
            playable = sum(1 for card in hand if getattr(card, "is_playable", False))
            # Use the draw/randomize effect as an emergency refill, not as a
            # generic boss-turn buff when the current hand is already good.
            poor_hand = playable <= 1 or len(hand) <= 3
            return 24 if lethal and poor_hand else 15 if elite_or_boss and poor_hand and total_loss >= 8 else 3
        if potion_id in {"elixir", "elixirpotion", "gamblersbrew"}:
            if (
                potion_id == "gamblersbrew"
                and combat_predictor.has_power(
                    getattr(self.game, "player", None),
                    "No Draw", "NoDrawPower",
                )
            ):
                return -1000
            analysis = hand_filter_analysis or self._hand_filter_potion_analysis(
                potion_id
            )
            if not analysis or not analysis.get("worthwhile"):
                if potion_id == "gamblersbrew" and (
                    lethal or reserve_breaking_crisis
                ):
                    # Preserve the existing one-bottle emergency escape when
                    # the current serialized zones cannot prove a redraw.  The
                    # confirmed-use guard still prevents draining a second
                    # stochastic potion before an authoritative reframe.
                    return 20
                return -100
            score = float(analysis.get("score") or -100.0)
            if potion_id in {"elixir", "elixirpotion"} and lethal:
                # Elixir does not redraw.  Strategic unlock value from
                # Normality, Doubt, Shame, Pain, or an estimated Regret hand
                # is not HP.  Only a fixed, currently present Burn/Decay (or
                # a future exact counterfactual) may claim a lethal rescue.
                direct_prevented = int(
                    analysis.get(
                        "direct_current_turn_hp_loss_prevented"
                    )
                    or 0
                )
                if direct_prevented <= 0:
                    return -100
                if comparison_loss - direct_prevented < hp:
                    return max(110.0, score)
            return score
        if potion_id == "cunningpotion":
            if len(getattr(self.game, "hand", []) or []) >= 10:
                return -100
            shiv_bonus = 4 if any(
                self._token(card.card_id) in {"accuracy", "finisher", "athousandcuts"}
                for card in getattr(self.game, "deck", []) or []
            ) else 0
            return 16 + shiv_bonus if elite_or_boss and target_hp >= 20 else 9
        if potion_id == "duplicationpotion":
            analysis = duplication_potion_analysis
            if analysis is None:
                analysis = self._duplication_potion_analysis(
                    planned_turn_loss=planned_turn_loss
                )
            return -100 if analysis is None else float(analysis["value"])
        if potion_id == "distilledchaos":
            return 19 if elite_or_boss and (self.game.turn >= 2 or lethal) else 8
        if potion_id in {"essenceofsteel", "heartofiron"}:
            # Heart of Iron is a fight-long defensive setup, not a six-block
            # potion.  The old score admitted it only when the current frame
            # immediately prevented enough HP loss to cross the ordinary
            # potion threshold.  A recent Collector loss consequently kept
            # the bottle through fifteen turns, including a measured 5 -> 0
            # loss reduction, and died with it still held.  Price a bounded
            # remaining-fight horizon in hard combats while retaining the
            # exact one-turn counterfactual for immediate mitigation.
            persistent_setup_score = None
            if (
                potion_id == "heartofiron"
                and hard_fight
                and not planned_combat_end
                and active
            ):
                remaining_enemy_hp = sum(
                    max(0, int(getattr(monster, "current_hp", 0) or 0))
                    for monster in active
                )
                long_boss_remainder = (
                    self.game.room_type == "MonsterRoomBoss"
                    and remaining_enemy_hp >= max(40, hp * 2)
                )
                if early_hard_fight or long_boss_remainder:
                    horizon = 4 if early_hard_fight else 3
                    metallicize = 6 * (
                        2 if self._has_relic("Sacred Bark") else 1
                    )
                    persistent_setup_score = 14.0 + min(
                        12.0,
                        metallicize * max(1, horizon - 1) * 0.55,
                    )
            if unquantified_play_plan:
                return -100
            if protected_planned_loss is None:
                return (
                    persistent_setup_score
                    if persistent_setup_score is not None
                    else -100
                )
            final_comparison_loss = max(0, int(protected_planned_loss))
            mitigation = max(0, comparison_loss - final_comparison_loss)
            if mitigation <= 0:
                return (
                    persistent_setup_score
                    if persistent_setup_score is not None
                    else -100
                )
            prevents_lethal = (
                comparison_loss >= hp and final_comparison_loss < hp
            )
            score = mitigation * (3.0 if prevents_lethal else 1.4)
            opportunity = self._potion_loss_opportunity(
                comparison_loss, final_comparison_loss
            )
            if opportunity.get("score") is not None:
                score = max(score, float(opportunity["score"]))
            if persistent_setup_score is not None:
                score = max(score, persistent_setup_score)
            return max(110.0, score) if prevents_lethal else score
        if potion_id == "liquidbronze":
            attack_hits = sum(
                max(1, int(getattr(monster, "move_hits", 0) or 0))
                for monster in active
                if getattr(monster, "intent", None).is_attack()
            )
            if early_hard_fight:
                return 18 + min(10, max(1, attack_hits) * 2)
            return 14 + min(10, attack_hits * 2) if elite_or_boss else 6
        if potion_id == "smokebomb":
            # Smoke Bomb can escape ordinary and Elite encounters.  The old
            # exact ``MonsterRoom`` comparison silently disabled the potion
            # in the room where preserving the run is often most valuable.
            # Boss rooms remain excluded by the base-game rule rather than by
            # a generic non-boss shortcut, so an unknown room type cannot be
            # mistaken for a legal escape.
            escapable_room = self.game.room_type in {
                "MonsterRoom", "MonsterRoomElite",
            }
            return 100 if lethal and escapable_room else -1000
        if potion_id == "regenpotion":
            projection = (
                regen_potion_projection
                or self._regen_potion_projection()
            )
            # Regeneration has no payout after a terminal card sequence: the
            # combat closes before the player's next end-of-turn power tick.
            # This must remain a hard guard even when missing HP would make
            # the old generic healing score cross the use threshold.
            if projection["planned_combat_end"]:
                return -1000
            projected_healing = int(projection["projected_healing"])
            if projected_healing <= 0:
                return -1000
            first_turn_healing = int(projection["first_turn_healing"])
            if (
                lethal
                and first_turn_healing > 0
                and comparison_loss < hp + first_turn_healing
            ):
                # Unlike Blood/Fruit, this healing is not immediate, but the
                # first Regeneration tick occurs before the monster takes its
                # turn. Preserve the existing emergency behavior only when
                # that actually crosses the measured survival boundary.
                return 115.0
            return projected_healing * (
                1.5 if hp * 2 < max_hp else 0.45
            )
        if potion_id in {"bloodpotion", "fruitjuice"}:
            missing = max(0, int(getattr(self.game.player, "max_hp", hp) or hp) - hp)
            return missing * (1.5 if hp * 2 < int(getattr(self.game.player, "max_hp", hp) or hp) else 0.45)
        if potion_id == "powerpotion":
            if lethal:
                return 20
            if early_hard_fight:
                return 18
            max_hp = max(1, int(getattr(self.game.player, "max_hp", hp) or hp))
            # Generating a random power is worthwhile when a long fight is
            # genuinely dangerous, not merely because turn two of an elite
            # has arrived.  The selected power is scored tactically below.
            if elite_or_boss and (total_loss >= 10 or hp * 2 <= max_hp):
                return 15
            return 6
        if potion_id in {"essenceofdarkness", "potionofcapacity"}:
            return self._defect_orb_potion_setup_score(
                potion_id, hard_fight
            )
        if potion_id in {
            "attackpotion", "colorlesspotion", "cultistpotion",
            "dexteritypotion", "energypotion", "entropicbrew", "focuspotion",
            "gamblersbrew", "skillpotion",
            "strengthpotion", "swiftpotion",
        }:
            if reserve_breaking_crisis and potion_id in {
                "attackpotion", "colorlesspotion", "energypotion",
                "entropicbrew", "gamblersbrew", "skillpotion",
                "sneckooil", "swiftpotion",
            }:
                # These potions can reveal extra cards/energy or a lethal
                # attack line. In a reserve-breaking turn, one measured
                # stochastic rescue is preferable to knowingly ending on a
                # dangerously low HP total; the next authoritative frame
                # re-plans before any second potion is considered.
                return 20
            if lethal:
                emergency = {
                    "attackpotion", "colorlesspotion", "dexteritypotion",
                    "energypotion", "entropicbrew", "gamblersbrew",
                    "powerpotion", "skillpotion", "strengthpotion",
                    "swiftpotion",
                }
                return 20 if potion_id in emergency else 11
            if early_hard_fight and potion_id in {
                "cultistpotion", "dexteritypotion", "focuspotion", "strengthpotion",
            }:
                return {
                    "cultistpotion": 24,
                    "focuspotion": 21,
                    "dexteritypotion": 19,
                    "strengthpotion": 19,
                }[potion_id]
            return 15 if elite_or_boss and (self.game.turn >= 2 or incoming >= 12) else 5
        return 8 if elite_or_boss and total_loss >= max(10, hp // 3) else 0

    def _potion_keep_score(self, potion):
        """Estimate the run-level value of occupying one potion slot.

        Combat-use scores answer "should I spend this now?" and are purposely
        very state dependent.  Reward/shop replacement needs a different,
        persistent value so a full belt can trade a weak potion for a premium
        defensive one without throwing away Fairy/Ghost for short-term damage.
        """
        potion_id = self._token(getattr(potion, "potion_id", ""))
        base = {
            "potionslot": -1000,
            "ghostinajar": 50,
            "fairypotion": 48,
            "fruitjuice": 38,
            "liquidmemories": 35,
            "gamblersbrew": 33,
            "elixir": 28,
            "elixirpotion": 28,
            "duplicationpotion": 32,
            "entropicbrew": 31,
            "cultistpotion": 30,
            "blockpotion": 29,
            "focuspotion": 28,
            "dexteritypotion": 27,
            "strengthpotion": 27,
            "powerpotion": 27,
            "heartofiron": 26,
            "energypotion": 25,
            "essenceofdarkness": 25,
            "potionofcapacity": 25,
            "swiftpotion": 25,
            "colorlesspotion": 24,
            "skillpotion": 24,
            "attackpotion": 23,
            "speedpotion": 23,
            "essenceofsteel": 23,
            "liquidbronze": 22,
            "cunningpotion": 21,
            "fearpotion": 20,
            "bloodpotion": 20,
            "regenpotion": 20,
            "steroidpotion": 20,
            "poisonpotion": 18,
            "weakpotion": 18,
            "ancientpotion": 18,
            "firepotion": 17,
            "explosivepotion": 17,
            "smokebomb": 12,
        }.get(potion_id, 15)

        hp_ratio = self.game.current_hp / max(1, self.game.max_hp)
        if potion_id in {"ghostinajar", "fairypotion", "blockpotion"}:
            base += 6 if hp_ratio < 0.45 else 2 if hp_ratio < 0.7 else 0
        if potion_id in {"bloodpotion", "regenpotion"} and hp_ratio < 0.6:
            base += 6
        if self.chosen_class == PlayerClass.THE_SILENT:
            if potion_id in {"dexteritypotion", "cunningpotion", "poisonpotion"}:
                base += 5
        elif self.chosen_class == PlayerClass.IRONCLAD:
            if potion_id in {"strengthpotion", "heartofiron", "bloodpotion"}:
                base += 5
        elif self.chosen_class == PlayerClass.DEFECT:
            if potion_id in {
                "focuspotion", "essenceofdarkness",
                "potionofcapacity", "essenceofsteel",
            }:
                base += 7
        return base

    def _potion_replacement_options(self, candidates):
        """Return non-dominated safe (action, old, new, gain) swaps."""

        if self._has_relic("Sozu"):
            return []
        if not getattr(self.game, "potion_available", False):
            return []
        if not self.game.are_potions_full():
            return []
        owned = [
            potion for potion in self.game.get_real_potions()
            if getattr(potion, "can_discard", False)
        ]
        candidates = [potion for potion in candidates if potion is not None]
        if not owned or not candidates:
            return []

        options = []
        for old in owned:
            old_score = float(self._potion_keep_score(old))
            old_id = self._token(getattr(old, "potion_id", ""))
            beneficial_use = (
                getattr(old, "can_use", False)
                and not getattr(old, "requires_target", False)
                and (
                    old_id == "fruitjuice"
                    or (
                        old_id == "bloodpotion"
                        and self.game.current_hp < self.game.max_hp
                    )
                )
            )
            for new in candidates:
                new_score = float(self._potion_keep_score(new))
                improvement = new_score - old_score
                if improvement < 10:
                    continue
                options.append((
                    PotionAction(beneficial_use, potion=old),
                    old,
                    new,
                    improvement,
                    old_score,
                    new_score,
                    int(getattr(new, "price", 0) or 0),
                ))

        # Keep every swap that is not strictly worse on all relevant axes:
        # lower old keep-value, higher new keep-value/improvement, and lower
        # price.  A full belt normally yields only a handful of rows, so this
        # remains cheap while allowing the adviser to correct which bottle to
        # discard and which listing to buy.
        non_dominated = []
        for option in options:
            _, _, _, gain, old_value, new_value, price = option
            dominated = any(
                other is not option
                and other[3] >= gain
                and other[4] <= old_value
                and other[5] >= new_value
                and other[6] <= price
                and (
                    other[3] > gain
                    or other[4] < old_value
                    or other[5] > new_value
                    or other[6] < price
                )
                for other in options
            )
            if not dominated:
                non_dominated.append(option[:4])
        non_dominated.sort(
            key=lambda row: (
                -float(row[3]),
                int(getattr(row[2], "price", 0) or 0),
                self._token(getattr(row[1], "potion_id", "")),
                self._token(getattr(row[2], "potion_id", "")),
            )
        )
        return non_dominated

    def _potion_replacement(self, candidates):
        """Return the best safe swap for legacy single-choice callers."""

        options = self._potion_replacement_options(candidates)
        return options[0] if options else None

    @staticmethod
    def _audit_potion_instance_id(potion, slot):
        """Mirror bridge's immutable held-potion identity contract."""

        material = {
            "slot": int(slot),
            "id": getattr(potion, "potion_id", None),
            "name": getattr(potion, "name", None),
        }
        encoded = json.dumps(
            material, ensure_ascii=True, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
        return "potion:" + hashlib.sha256(encoded).hexdigest()[:20]

    def _potion_resource_preparation_candidates(
        self, held_potions, new_potion, selected_action, selected_old,
        *, parent_operation, parent_binding=None,
    ):
        """Return the complete typed use/discard surface for freeing a slot."""

        new_value = float(self._potion_keep_score(new_potion))
        candidates = []
        selected_id = None
        for slot, held in enumerate(held_potions):
            held_id = getattr(held, "potion_id", None)
            instance_id = self._audit_potion_instance_id(held, slot)
            held_value = float(self._potion_keep_score(held))
            held_token = self._token(held_id)
            beneficial_use = bool(
                getattr(held, "can_use", False)
                and not getattr(held, "requires_target", False)
                and (
                    held_token == "fruitjuice"
                    or (
                        held_token == "bloodpotion"
                        and self.game.current_hp < self.game.max_hp
                    )
                )
            )
            operations = []
            if getattr(held, "can_discard", False):
                operations.append(("discard", True, None, 0.0))
            if (
                getattr(held, "can_use", False)
                and not getattr(held, "requires_target", False)
            ):
                operations.append((
                    "use",
                    beneficial_use,
                    None if beneficial_use
                    else "use_has_no_verified_preparation_value",
                    1.0 if beneficial_use else 0.0,
                ))
            for operation, eligible, veto_reason, use_bonus in operations:
                choice_id = f"potion:{operation}:{slot}:{held_id}"
                semantic_id = (
                    f"potion-{operation}:{instance_id}:{slot}"
                )
                score = new_value - held_value + use_bonus
                is_selected = bool(
                    held is selected_old
                    and operation == (
                        "use" if selected_action.use else "discard"
                    )
                )
                if is_selected:
                    selected_id = choice_id
                parent_claim = dict(parent_binding or {})
                candidates.append({
                    "id": choice_id,
                    "choice_id": choice_id,
                    "choice_index": slot,
                    "action": "potion",
                    "operation": operation,
                    "semantic_id": semantic_id,
                    "score": score,
                    "score_rule_id": "potion_resource_preparation_net_v1",
                    "score_formula": {"kind": "sum_components_v1"},
                    "score_inputs": {
                        "new_keep_value": new_value,
                        "held_keep_value": held_value,
                        "verified_use_bonus": use_bonus,
                    },
                    "score_components": [
                        {
                            "name": "new_keep_value",
                            "input": "new_keep_value",
                            "coefficient": 1.0,
                            "value": new_value,
                        },
                        {
                            "name": "held_keep_cost",
                            "input": "held_keep_value",
                            "coefficient": -1.0,
                            "value": -held_value,
                        },
                        {
                            "name": "verified_use_bonus",
                            "input": "verified_use_bonus",
                            "coefficient": 1.0,
                            "value": use_bonus,
                        },
                    ],
                    "label": f"{operation.title()} {getattr(held, 'name', held_id)}",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": bool(eligible),
                    "veto_reason": veto_reason,
                    "reason": (
                        "selected_resource_preparation_operation"
                        if is_selected
                        else veto_reason or "visible_resource_preparation_alternative"
                    ),
                    "consequences": {
                        "operation": f"{operation}_held_potion_for_{parent_operation}",
                        "potion_id": held_id,
                        "potion_instance_id": instance_id,
                        "potion_slot": slot,
                        "bound_new_potion_id": getattr(
                            new_potion, "potion_id", None
                        ),
                        **parent_claim,
                    },
                })
        if selected_id is None:
            raise ValueError("selected potion preparation operation is absent")
        return candidates, selected_id

    def _boss_encounter_imminent(self):
        # Act 4 is a short, fixed route: shop, Shield/Spear, then Heart.
        # Its floor numbers do not share the seventeen-floor act cadence.
        return int(getattr(self.game, "act", 0) or 0) == 4 or self.game.floor % 17 >= 13

    def _shop_potion_value(self, potion):
        premium_potions = {
            "blockpotion", "cultistpotion", "dexteritypotion", "duplicationpotion",
            "entropicbrew", "fairypotion", "focuspotion", "gamblersbrew",
            "ghostinajar", "liquidmemories", "powerpotion", "speedpotion",
        }
        hp_ratio = self.game.current_hp / max(1, self.game.max_hp)
        boss_soon = self._boss_encounter_imminent()
        potion_id = self._token(potion.potion_id)
        value = 12 + (11 if potion_id in premium_potions else 0)
        value += 8 if boss_soon else 0
        value += 7 if hp_ratio < 0.55 else 0
        value -= potion.price / 11.0
        value -= self.shop_potions_bought * 4.0
        return value

    def _shop_potion_purchase_allowed(self, potion, value, gold=None):
        """Allow a modest potion purchase when gold is otherwise idle.

        The ordinary shop floor is eight points.  That floor is appropriate
        for cards/relics, but it made low-tier potions (for example a roughly
        7.3-point potion with 40+ gold left afterward) disappear whenever the
        model/rule macro preferred Leave.  Potions are consumable emergency
        resources, so a smaller deterministic floor is safe when a reserve
        remains, HP is low, or a boss is close.
        """

        if potion is None or value < 6.5:
            return False
        gold = self.game.gold if gold is None else gold
        price = max(0, int(getattr(potion, "price", 0) or 0))
        if price > gold:
            return False
        hp_ratio = self.game.current_hp / max(1, self.game.max_hp)
        boss_soon = self._boss_encounter_imminent()
        reserve_after_purchase = gold - price
        return (
            reserve_after_purchase >= 40
            or boss_soon
            or hp_ratio < 0.60
        )

    def _shop_purge_purchase_allowed(self, action, value, gold=None):
        """Allow a useful affordable removal below the generic shop floor.

        Purge is a permanent deck improvement, not a discretionary listing
        like a weak card.  The old global ``value >= 8`` gate discarded even
        a 7.75-point removal with plenty of gold, leaving curses/starters in
        the deck and making consecutive shop visits look like no-ops.
        """

        if self._token(getattr(action, "name", "")) != "purge" or value < 5.5:
            return False
        gold = self.game.gold if gold is None else gold
        cost = max(
            0,
            int(getattr(getattr(self.game, "screen", None), "purge_cost", 0) or 0),
        )
        if cost > gold:
            return False
        deck = list(getattr(self.game, "deck", []) or [])
        if not deck:
            return False
        curses = sum(
            1
            for card in deck
            if getattr(card, "rarity", None) == spirecomm.spire.card.CardRarity.CURSE
        )
        starters = sum(
            1
            for card in deck
            if self._token(getattr(card, "card_id", ""))[:6]
            in {"strike", "defend"}
        )
        hp_ratio = self.game.current_hp / max(1, self.game.max_hp)
        reserve_after = gold - cost
        return bool(
            curses > 0
            or starters >= 7
            or len(deck) >= 10
            or reserve_after >= 40
            or hp_ratio < 0.60
        )

    def _shop_relic_purchase_allowed(self, relic, value, gold=None):
        """Spend surplus gold on a useful relic just below the leave floor.

        A fixed eight-point Leave score made a 7.87-point Torii lose by a
        fraction of a point while the run had 618 otherwise-idle gold and
        only 13 HP. Preserve the ordinary value floor for weak listings, but
        allow a positive near-floor relic when survival is already critical
        or the purchase still leaves a large reserve.
        """

        if (
            relic is None
            or value < 6.5
            or self.shop_relics_bought > 0
        ):
            return False
        gold = self.game.gold if gold is None else gold
        price = max(0, int(getattr(relic, "price", 0) or 0))
        if price > gold:
            return False
        hp_ratio = self.game.current_hp / max(1, self.game.max_hp)
        reserve_after = gold - price
        return hp_ratio < 0.35 or reserve_after >= 250

    def _shop_action_above_floor(self, action, value, gold=None):
        """Whether a selected shop action may beat the Leave floor."""

        if value >= 8.0:
            return True
        if isinstance(action, BuyPotionAction):
            return self._shop_potion_purchase_allowed(
                getattr(action, "potion", None), value, gold=gold
            )
        if isinstance(action, BuyRelicAction):
            return self._shop_relic_purchase_allowed(
                getattr(action, "relic", None), value, gold=gold
            )
        if isinstance(action, ChooseAction):
            return self._shop_purge_purchase_allowed(action, value, gold=gold)
        return False

    def _hypothetical_defensive_potion_loss(
        self, potion_ids, weak_target=None
    ):
        """Re-plan after an exact deterministic defensive potion subset.

        Weak changes one target, while Block, Ghost, Essence of Steel, and
        Heart of Iron change the player.  Keeping them in one counterfactual
        is important because two individually insufficient bottles can form
        the only surviving line.
        """

        if isinstance(potion_ids, str):
            potion_ids = (potion_ids,)
        potion_ids = tuple(potion_ids)
        if self._potion_changes_red_skull_state(potion_ids):
            return None
        if "weakpotion" in potion_ids and weak_target is None:
            losses = [
                self._hypothetical_defensive_potion_loss(
                    potion_ids, weak_target=target
                )
                for target in self._weak_potion_candidates()
            ]
            losses = [loss for loss in losses if loss is not None]
            return min(losses) if losses else None
        hypothetical = copy.copy(self.game)
        hypothetical.player = copy.copy(self.game.player)
        hypothetical.player.powers = list(
            getattr(self.game.player, "powers", []) or []
        )
        block_count = potion_ids.count("blockpotion")
        if block_count:
            hypothetical.player.block = max(
                0, int(getattr(self.game.player, "block", 0) or 0)
            ) + block_count * self._block_potion_amount()
        if "ghostinajar" in potion_ids:
            hypothetical.player.powers = list(
                getattr(self.game.player, "powers", []) or []
            ) + [
                SimpleNamespace(
                    power_id="IntangiblePlayer",
                    power_name="Intangible",
                    amount=1,
                )
            ]
        sacred_bark_multiplier = 2 if self._has_relic("Sacred Bark") else 1
        plated_armor = (
            potion_ids.count("essenceofsteel")
            * 4 * sacred_bark_multiplier
        )
        if plated_armor:
            hypothetical.player.powers.append(SimpleNamespace(
                power_id="PlatedArmor",
                power_name="Plated Armor",
                amount=plated_armor,
            ))
        metallicize = (
            potion_ids.count("heartofiron")
            * 6 * sacred_bark_multiplier
        )
        if metallicize:
            hypothetical.player.powers.append(SimpleNamespace(
                power_id="Metallicize",
                power_name="Metallicize",
                amount=metallicize,
            ))
        if "weakpotion" in potion_ids:
            hypothetical.monsters = []
            selected = None
            target_index = getattr(weak_target, "monster_index", None)
            for original in getattr(self.game, "monsters", []) or []:
                clone = copy.copy(original)
                clone.powers = list(getattr(original, "powers", []) or [])
                hypothetical.monsters.append(clone)
                if original is weak_target or (
                    target_index is not None
                    and getattr(original, "monster_index", None)
                    == target_index
                ):
                    selected = clone
            if selected is None:
                return None
            damage = max(
                0,
                int(getattr(selected, "move_adjusted_damage", 0) or 0),
            )
            numerator, denominator = (
                (3, 5) if self._has_relic("Paper Krane") else (3, 4)
            )
            selected.move_adjusted_damage = (
                damage * numerator // denominator
            )
            duration = 6 if self._has_relic("Sacred Bark") else 3
            selected.powers.append(SimpleNamespace(
                power_id="Weakened",
                power_name="Weak",
                amount=duration,
            ))
        if not any(potion_id in {
            "blockpotion", "ghostinajar", "essenceofsteel",
            "heartofiron", "weakpotion",
        } for potion_id in potion_ids):
            return None
        planner = self._counterfactual_combat_planner(hypothetical)
        action = planner.choose_card_action(hypothetical)
        return self._planned_turn_hp_loss(action, planner.last_decision)

    def _weak_potion_candidates(self):
        return [
            monster
            for monster in combat_predictor.active_monsters(self.game)
            if combat_predictor.power_amount(
                monster, "Weak", "Weakened"
            ) <= 0
            and combat_predictor.power_amount(monster, "Artifact") <= 0
        ]

    def _weak_potion_analysis(self):
        """Enumerate each legal target and keep the best complete turn."""

        results = []
        for target in self._weak_potion_candidates():
            protected_loss = self._hypothetical_weak_potion_loss(target)
            if protected_loss is None:
                continue
            results.append((
                max(0, int(protected_loss)),
                -combat_predictor.monster_threat(target),
                -int(getattr(target, "current_hp", 0) or 0),
                int(getattr(target, "monster_index", 0) or 0),
                target,
            ))
        if not results:
            return None
        protected_loss, _, _, _, target = min(results)
        return {"target": target, "protected_loss": protected_loss}

    def _hypothetical_weak_potion_loss(self, target):
        """Re-plan after Weak changes the selected monster's actual intent.

        The previous policy scored the target's raw threat and never checked
        how much HP the potion saved after the chosen card sequence.  Clone
        the authoritative frame, weaken one exact target, then run the same
        ordered planner used for the baseline.
        """

        if target is None or (
            combat_predictor.power_amount(target, "Weak", "Weakened") > 0
            or combat_predictor.power_amount(target, "Artifact") > 0
        ):
            return None
        return self._hypothetical_defensive_potion_loss(
            ("weakpotion",), weak_target=target
        )

    def _defensive_potion_end_loss(self, potion_ids):
        potion_ids = tuple(potion_ids)
        outcome = combat_predictor.projected_turn_outcome(
            self.game,
            extra_block=(
                potion_ids.count("blockpotion")
                * self._block_potion_amount()
            ),
            force_intangible="ghostinajar" in potion_ids,
        )
        return outcome.total_hp_loss

    def use_best_potion(
        self,
        incoming,
        planned_turn_loss=None,
        planned_action=None,
        planned_combat_end=None,
    ):
        held_potions = list(self.game.get_real_potions() or [])
        potion_operation_candidates = (
            self._combat_potion_operation_candidates(held_potions)
        )
        baseline_decision = dict(self.combat_planner.last_decision or {})
        baseline_decision["potion_operation_candidates"] = (
            potion_operation_candidates
        )
        self.combat_planner.last_decision = baseline_decision

        potions = [
            potion for potion in held_potions
            if bool(getattr(potion, "can_use", False))
        ]
        if not potions:
            return None
        red_skull_transition_potions = {
            id(potion)
            for potion in potions
            if self._potion_changes_red_skull_state((
                self._token(getattr(potion, "potion_id", "")),
            ))
        }

        exact_replan_ids = {
            "poisonpotion",
            "speedpotion", "weakpotion", "duplicationpotion",
            "dexteritypotion", "strengthpotion", "energypotion",
            "essenceofdarkness", "potionofcapacity",
            "essenceofsteel", "heartofiron", "cunningpotion",
        }
        if (
            planned_turn_loss is None
            and planned_action is None
            and any(
                self._token(getattr(potion, "potion_id", ""))
                in exact_replan_ids
                for potion in potions
            )
        ):
            baseline_planner = self._counterfactual_combat_planner(self.game)
            planned_action = baseline_planner.choose_card_action(self.game)
            exact_loss = self._planned_turn_hp_loss(
                planned_action, baseline_planner.last_decision
            )
            if exact_loss is not None:
                planned_turn_loss = exact_loss
                # Duplication analysis compares its hypothetical line with
                # this exact baseline search, not a naked END projection.
                self.combat_planner.last_decision = {
                    **dict(baseline_planner.last_decision or {}),
                    "potion_operation_candidates": (
                        potion_operation_candidates
                    ),
                }

        if planned_combat_end is None:
            baseline_decision = self.combat_planner.last_decision or {}
            baseline_search = baseline_decision.get("search") or {}
            planned_combat_end = (
                bool(baseline_search.get("true_combat_end"))
                or baseline_decision.get("reason")
                == "all_enemies_passively_doomed"
            )
        else:
            planned_combat_end = bool(planned_combat_end)

        regen_potion_projection = None
        if any(
            self._token(getattr(potion, "potion_id", ""))
            == "regenpotion"
            for potion in potions
        ):
            regen_potion_projection = self._regen_potion_projection(
                planned_combat_end=planned_combat_end
            )
        hand_filter_analyses = {}
        for potion in potions:
            potion_id = self._token(getattr(potion, "potion_id", ""))
            if potion_id in {"elixir", "elixirpotion", "gamblersbrew"}:
                hand_filter_analyses[id(potion)] = (
                    self._hand_filter_potion_analysis(
                        potion_id,
                        planned_combat_end=planned_combat_end,
                    )
                )

        turn_key = (int(self.game.act), int(self.game.floor), int(self.game.turn))
        used = self.potions_used_this_turn.get(turn_key, 0)
        unproven_used = bool(
            self.unproven_potions_used_this_turn.get(turn_key)
        )
        turn_outcome = combat_predictor.projected_turn_outcome(self.game)
        attack_loss = turn_outcome.attack_hp_loss
        end_turn_loss = turn_outcome.end_turn_hp_loss
        next_turn_start_loss = turn_outcome.next_turn_start_hp_loss
        total_loss = turn_outcome.total_hp_loss
        comparison_loss = (
            total_loss
            if planned_turn_loss is None
            else max(0, int(planned_turn_loss))
        )
        hp = int(getattr(self.game.player, "current_hp", 1) or 1)
        safety_reserve = FastCombatPlanner._reactive_safety_reserve(
            self.game, hp
        )
        reserve_breaking_crisis = (
            comparison_loss > 0
            and hp - comparison_loss < safety_reserve
        )
        lethal = comparison_loss >= hp
        if not lethal and used >= 1:
            return None

        # A previously confirmed random potion can leave a fresh lethal frame
        # with no executable cards in hand.  Snecko Oil is a real second-chance
        # action in that narrow state: it redraws five cards, so suppressing it
        # under the generic "one stochastic potion per turn" guard would turn a
        # guaranteed death into an avoidable one.  Require an authoritative
        # draw/discard source and no currently playable card so this exception
        # cannot become a generic second random-potion spend.
        snecko_followup_rescue = False
        if lethal and (used >= 1 or unproven_used):
            hand = list(getattr(self.game, "hand", []) or [])
            draw_pile = list(getattr(self.game, "draw_pile", []) or [])
            discard_pile = list(getattr(self.game, "discard_pile", []) or [])
            snecko_followup_rescue = bool(
                not any(
                    bool(getattr(card, "is_playable", False))
                    for card in hand
                )
                and (draw_pile or discard_pile)
            )

        known_draw_potion_analyses = {}
        if lethal:
            for potion in potions:
                potion_id = self._token(
                    getattr(potion, "potion_id", "")
                )
                if potion_id == "swiftpotion":
                    analysis = self._hypothetical_known_draw_potion_analysis(
                        potion_id
                    )
                    if analysis is not None:
                        known_draw_potion_analyses[id(potion)] = analysis

        target = self.combat_planner.choose_target(self.game)
        has_weak_potion = any(
            self._token(getattr(potion, "potion_id", "")) == "weakpotion"
            for potion in potions
        )
        weak_analysis = (
            self._weak_potion_analysis()
            if has_weak_potion and planned_turn_loss != 0
            else None
        )
        weak_target = (
            weak_analysis.get("target") if weak_analysis is not None else None
        )
        weak_protected_loss = (
            weak_analysis.get("protected_loss")
            if weak_analysis is not None
            else None
        )
        protected_losses = {}
        unquantified_play_plan = (
            isinstance(planned_action, PlayCardAction)
            and planned_turn_loss is None
        )
        if planned_turn_loss is not None and isinstance(planned_action, EndTurnAction):
            for potion in potions:
                potion_id = self._token(getattr(potion, "potion_id", ""))
                if potion_id in {
                    "blockpotion", "ghostinajar", "essenceofsteel",
                    "heartofiron",
                }:
                    protected_losses[id(potion)] = (
                        self._hypothetical_defensive_potion_loss((potion_id,))
                    )
                    continue
                elif potion_id == "speedpotion":
                    protected_losses[id(potion)] = (
                        self._hypothetical_speed_potion_loss()
                    )
                    continue
                elif potion_id == "weakpotion":
                    protected_losses[id(potion)] = weak_protected_loss
                    continue
                else:
                    continue
        elif (
            planned_turn_loss is not None
            and isinstance(planned_action, PlayCardAction)
            and planned_turn_loss > 0
        ):
            for potion in potions:
                potion_id = self._token(getattr(potion, "potion_id", ""))
                if potion_id in {
                    "blockpotion", "ghostinajar", "speedpotion",
                    "weakpotion", "essenceofsteel", "heartofiron",
                }:
                    protected_losses[id(potion)] = (
                        self._hypothetical_speed_potion_loss()
                        if potion_id == "speedpotion"
                        else weak_protected_loss
                        if potion_id == "weakpotion"
                        else self._hypothetical_defensive_potion_loss((potion_id,))
                    )
        liquid_memories_analysis = None
        if any(
            self._token(getattr(potion, "potion_id", "")) == "liquidmemories"
            for potion in potions
        ):
            liquid_memories_analysis = self._liquid_memories_analysis(
                planned_turn_loss
            )
        duplication_potion_analysis = None
        if any(
            self._token(getattr(potion, "potion_id", ""))
            == "duplicationpotion"
            for potion in potions
        ):
            duplication_potion_analysis = self._duplication_potion_analysis(
                planned_turn_loss=planned_turn_loss,
                planned_action=planned_action,
            )
        healing_potion_analyses = {}
        # The ordinary missing-HP score is sufficient outside a lethal turn.
        # Pay for a second bounded hand search only when it can prove a run
        # save that the baseline scalar comparison cannot see.
        if lethal:
            for potion in potions:
                potion_id = self._token(getattr(potion, "potion_id", ""))
                if potion_id in {"bloodpotion", "fruitjuice"}:
                    analysis = self._hypothetical_healing_potion_analysis(
                        potion_id
                    )
                    if analysis is not None:
                        healing_potion_analyses[id(potion)] = analysis
        stat_potion_analyses = {}
        baseline_decision = dict(self.combat_planner.last_decision or {})
        baseline_search = dict(baseline_decision.get("search") or {})
        baseline_enemy_hp = list(
            baseline_search.get("final_enemy_hp") or []
        )
        baseline_sequence = {
            self._token(item.get("card_id"))
            for item in baseline_decision.get("planned_sequence") or []
            if isinstance(item, dict)
        }
        critical_setup_ids = {
            "barricade", "biasedcognition", "corruption", "darkembrace",
            "defragment", "demonform", "echoform", "feelno pain",
            "feelnopain", "footwork", "noxiousfumes",
        }
        for potion in potions:
            potion_id = self._token(getattr(potion, "potion_id", ""))
            if potion_id in {
                "dexteritypotion", "strengthpotion", "energypotion",
                "essenceofdarkness", "potionofcapacity", "poisonpotion",
            }:
                analysis = (
                    self._hypothetical_poison_potion_analysis(target)
                    if potion_id == "poisonpotion"
                    else self._hypothetical_stat_potion_analysis(potion_id)
                )
                if analysis is not None:
                    candidate_enemy_hp = list(
                        analysis.get("final_enemy_hp") or []
                    )
                    offense_gain = None
                    marginal_kills = 0
                    if (
                        baseline_enemy_hp
                        and len(baseline_enemy_hp)
                        == len(candidate_enemy_hp)
                    ):
                        offense_gain = sum(
                            max(0, int(before) - int(after))
                            for before, after in zip(
                                baseline_enemy_hp, candidate_enemy_hp
                            )
                        )
                        marginal_kills = sum(
                            int(before) > 0 and int(after) <= 0
                            for before, after in zip(
                                baseline_enemy_hp, candidate_enemy_hp
                            )
                        )
                    candidate_sequence = {
                        self._token(card_id)
                        for card_id in analysis.get("planned_card_ids") or []
                    }
                    analysis.update({
                        "baseline_enemy_hp": baseline_enemy_hp,
                        "offense_gain": offense_gain,
                        "marginal_kills": marginal_kills,
                        "critical_setup": bool(
                            (candidate_sequence - baseline_sequence)
                            & critical_setup_ids
                        ),
                    })
                    stat_potion_analyses[id(potion)] = analysis
        cunning_potion_analyses = {}
        if lethal or reserve_breaking_crisis:
            for potion in potions:
                if self._token(
                    getattr(potion, "potion_id", "")
                ) != "cunningpotion":
                    continue
                analysis = self._hypothetical_cunning_potion_analysis()
                if analysis is not None:
                    cunning_potion_analyses[id(potion)] = analysis
        scored = [
            (
                self._potion_score(
                    potion,
                    incoming,
                    weak_target
                    if self._token(getattr(potion, "potion_id", ""))
                    == "weakpotion"
                    else target,
                    planned_turn_loss=planned_turn_loss,
                    protected_planned_loss=protected_losses.get(id(potion)),
                    unquantified_play_plan=unquantified_play_plan,
                    liquid_memories_analysis=liquid_memories_analysis,
                    duplication_potion_analysis=duplication_potion_analysis,
                    regen_potion_projection=regen_potion_projection,
                    hand_filter_analysis=hand_filter_analyses.get(id(potion)),
                    planned_combat_end=planned_combat_end,
                ),
                potion,
            )
            for potion in potions
        ]
        outcome_scored = []
        stat_single_lifesavers = set()
        known_draw_single_lifesavers = set()
        cunning_single_lifesavers = set()
        cunning_reserve_restorers = set()
        unproven_emergency_ids = {
            "attackpotion", "colorlesspotion", "entropicbrew",
            "gamblersbrew", "powerpotion", "skillpotion", "sneckooil",
            "swiftpotion", "distilledchaos",
        }
        for score, potion in scored:
            potion_id = self._token(getattr(potion, "potion_id", ""))
            analysis = stat_potion_analyses.get(id(potion))
            known_draw_analysis = known_draw_potion_analyses.get(id(potion))
            cunning_analysis = cunning_potion_analyses.get(id(potion))
            if (
                potion_id == "cunningpotion"
                and (lethal or reserve_breaking_crisis)
                and cunning_analysis is None
            ):
                # Hand capacity, Confusion, or a Red Skull transition can
                # make the generated line unknowable. The old fixed boss
                # score must not bypass the exact emergency proof.
                score = -100.0
            elif (
                cunning_analysis is not None
                and cunning_analysis.get("loss") is not None
            ):
                candidate_loss = int(cunning_analysis["loss"])
                if lethal:
                    if cunning_analysis.get("survives"):
                        score = max(
                            score,
                            122.0
                            if cunning_analysis.get("true_combat_end")
                            else 112.0,
                        )
                        cunning_single_lifesavers.add(id(potion))
                    else:
                        score = -100.0
                elif reserve_breaking_crisis:
                    if (
                        candidate_loss < comparison_loss
                        and cunning_analysis.get("preserves_reserve")
                    ):
                        opportunity = self._potion_loss_opportunity(
                            comparison_loss, candidate_loss
                        )
                        score = max(
                            score,
                            (comparison_loss - candidate_loss) * 2.0,
                            float(opportunity.get("score") or -100.0),
                        )
                        cunning_reserve_restorers.add(id(potion))
                    else:
                        score = -100.0
            elif (
                known_draw_analysis is not None
                and known_draw_analysis.get("loss") is not None
            ):
                candidate_loss = int(known_draw_analysis["loss"])
                prevents_lethal = lethal and candidate_loss < hp
                if prevents_lethal:
                    score = max(
                        score,
                        122.0
                        if known_draw_analysis.get("true_combat_end")
                        else 112.0,
                    )
                    known_draw_single_lifesavers.add(id(potion))
                elif lethal:
                    # The visible top cards prove this Swift does not save
                    # the turn; do not mislabel it as a stochastic escape.
                    score = -100.0
            elif analysis is not None and analysis.get("loss") is not None:
                candidate_loss = int(analysis["loss"])
                prevents_lethal = lethal and candidate_loss < hp
                proves_kill = (
                    bool(analysis.get("true_combat_end"))
                    and candidate_loss < hp
                )
                if prevents_lethal:
                    score = max(score, 110.0)
                    stat_single_lifesavers.add(id(potion))
                    if proves_kill:
                        score = max(score, 120.0)
                elif lethal:
                    score = -100.0
                elif candidate_loss < comparison_loss:
                    opportunity = self._potion_loss_opportunity(
                        comparison_loss, candidate_loss
                    )
                    score = max(
                        score,
                        (comparison_loss - candidate_loss) * 2.0,
                        float(opportunity.get("score") or -100.0),
                    )
                elif potion_id == "energypotion":
                    # Energy Potion is a one-turn resource, unlike persistent
                    # Strength/Dexterity. Do not spend it merely because a
                    # boss/elite grants a generic early-fight bonus. The
                    # exact re-plan must show substantial immediate damage,
                    # a new kill, or a critical setup card made reachable.
                    risk = self._potion_loss_opportunity(comparison_loss)
                    # A serious turn lowers the ordinary 20-damage bar, but
                    # twelve points of boss chip is still not enough when the
                    # extra energy neither prevents damage nor makes a kill.
                    offense_floor = 16 if risk["severe"] else 20
                    survival_neutral_crisis = bool(
                        risk["severe"]
                        and candidate_loss >= comparison_loss
                        and int(analysis.get("marginal_kills") or 0) <= 0
                        and not bool(analysis.get("critical_setup"))
                        and not bool(analysis.get("true_combat_end"))
                    )
                    material_offense = comparison_loss > 0 and (
                        int(analysis.get("offense_gain") or 0)
                        >= offense_floor
                        or int(analysis.get("marginal_kills") or 0) > 0
                        or bool(analysis.get("critical_setup"))
                    )
                    # When the player is already taking severe damage, pure
                    # nonlethal chip is not an emergency benefit. Preserve the
                    # bottle for a later hand unless it reduces current loss,
                    # removes an enemy, ends combat, or deploys a critical
                    # scaling card. Replay 499776 spent two energy for eighteen
                    # damage while leaving the same eighteen HP loss, then died
                    # two turns later without the potion.
                    if survival_neutral_crisis or not material_offense:
                        score = -100.0
                    else:
                        score = max(
                            score,
                            14.0
                            + min(
                                12.0,
                                int(analysis.get("offense_gain") or 0)
                                * 0.35,
                            )
                            + 8.0
                            * int(analysis.get("marginal_kills") or 0),
                        )
            elif (
                lethal
                and (used >= 1 or unproven_used)
                and potion_id in unproven_emergency_ids
                and not (
                    potion_id == "sneckooil"
                    and snecko_followup_rescue
                )
            ):
                # One stochastic emergency action can reveal a recoverable
                # line.  If the fresh authoritative frame is still lethal,
                # do not drain every remaining random potion on the same
                # unverified fixed score.
                score = -100.0
            outcome_scored.append((score, potion))
        scored = outcome_scored
        healing_single_lifesavers = set()
        single_lifesaver = bool(
            stat_single_lifesavers
            or known_draw_single_lifesavers
            or cunning_single_lifesavers
        )
        if lethal:
            adjusted_scores = []
            for score, potion in scored:
                potion_id = self._token(getattr(potion, "potion_id", ""))
                exact_score = score
                exact_cunning = cunning_potion_analyses.get(id(potion))
                if (
                    potion_id == "cunningpotion"
                    and exact_cunning is not None
                ):
                    # The generated hand plus any Toy Ornithopter healing was
                    # already resolved by one complete exact re-plan. Never
                    # let the generic immediate-heal shortcut overwrite a
                    # failed Cunning survival proof.
                    exact_score = score
                elif potion_id == "regenpotion" and planned_combat_end:
                    # Do not let generic lethal/Toy-Ornithopter rescue
                    # scoring overwrite the terminal-line hard reserve.
                    exact_score = -1000.0
                elif (
                    potion_id in {"firepotion", "explosivepotion"}
                    and (reaction := self._hypothetical_shifting_potion_analysis(potion_id, target))
                    and reaction["survives"]
                ):
                    exact_score = max(exact_score, 110.0)
                    single_lifesaver = True
                elif self._potion_immediately_ends_combat(potion_id, target):
                    exact_score = max(exact_score, 120.0)
                    single_lifesaver = True
                else:
                    healing_analysis = healing_potion_analyses.get(id(potion))
                    if (
                        healing_analysis is not None
                        and healing_analysis.get("survives")
                    ):
                        exact_score = max(exact_score, 115.0)
                        single_lifesaver = True
                        healing_single_lifesavers.add(id(potion))
                    elif (
                        healing_analysis is None
                        and id(potion) not in red_skull_transition_potions
                    ):
                        hp_gain = self._immediate_potion_hp_gain(potion_id)
                        if hp_gain > 0 and comparison_loss < hp + hp_gain:
                            exact_score = max(exact_score, 115.0)
                            single_lifesaver = True
                        elif potion_id == "smokebomb" and score >= 100:
                            exact_score = max(exact_score, 105.0)
                            single_lifesaver = True
                        elif (
                            potion_id in {
                                "blockpotion", "ghostinajar",
                                "essenceofsteel", "heartofiron",
                                "weakpotion",
                            }
                            and not unquantified_play_plan
                        ):
                            single_loss = protected_losses.get(id(potion))
                            if single_loss is None:
                                single_loss = (
                                    self._hypothetical_defensive_potion_loss(
                                        (potion_id,)
                                    )
                                )
                            if single_loss is not None and single_loss < hp:
                                exact_score = max(exact_score, 110.0)
                                single_lifesaver = True
                adjusted_scores.append((exact_score, potion))
            scored = adjusted_scores
        # Distilled Chaos is stochastic, so it must not outrank a proven
        # single-bottle rescue.  Once those deterministic lines are absent,
        # however, retaining it at HP=1 against a lethal ordinary encounter
        # is not a defensible fail-closed policy: any nonzero useful card
        # sequence is a strictly better survival chance than guaranteed death.
        # Give it one bounded emergency attempt, and never repeat it after a
        # confirmed random-potion use in the same authoritative turn.
        distilled_emergency = False
        if (
            lethal
            and not single_lifesaver
            and not unquantified_play_plan
            and not (used >= 1 or unproven_used)
        ):
            boosted = []
            for score, potion in scored:
                potion_id = self._token(getattr(potion, "potion_id", ""))
                if potion_id == "distilledchaos":
                    score = max(float(score), 20.0)
                    distilled_emergency = True
                boosted.append((score, potion))
            scored = boosted
        # Blood Potion and Fruit Juice can be jointly lifesaving even when
        # neither bottle crosses the survival boundary alone.  Order is
        # material because Fruit changes the max HP used by a later Blood,
        # and every potion independently triggers Toy Ornithopter.  Prove an
        # ordered sequence, consume only its first bottle, then re-evaluate
        # the remainder from the next authoritative frame.
        if lethal and not single_lifesaver:
            healing = [
                potion for potion in potions
                if self._token(getattr(potion, "potion_id", ""))
                in {"bloodpotion", "fruitjuice"}
            ]
            healing_lifesaving_sequences = []
            for size in range(2, len(healing) + 1):
                seen_sequence_ids = set()
                for sequence in permutations(healing, size):
                    sequence_ids = tuple(
                        self._token(getattr(item, "potion_id", ""))
                        for item in sequence
                    )
                    if sequence_ids in seen_sequence_ids:
                        continue
                    seen_sequence_ids.add(sequence_ids)
                    analysis = self._hypothetical_healing_potion_analysis(
                        sequence_ids
                    )
                    if analysis is not None and analysis.get("survives"):
                        healing_lifesaving_sequences.append(
                            (int(analysis["loss"]), sequence, analysis)
                        )
                if healing_lifesaving_sequences:
                    break
            if healing_lifesaving_sequences:
                combo_loss, sequence, analysis = min(
                    healing_lifesaving_sequences,
                    key=lambda item: (
                        len(item[1]),
                        sum(
                            self._potion_keep_score(potion)
                            for potion in item[1]
                        ),
                        item[0],
                        tuple(
                            self._token(getattr(potion, "potion_id", ""))
                            for potion in item[1]
                        ),
                    ),
                )
                potion = sequence[0]
                self.combat_planner.last_decision = {
                    "potion_operation_candidates": potion_operation_candidates,
                    "reason": "potion_healing_combo_survival",
                    "potion_id": potion.potion_id,
                    "potion_score": 115.0,
                    "potion_combo": [item.potion_id for item in sequence],
                    "planned_turn_hp_loss": planned_turn_loss,
                    "protected_combo_hp_loss": combo_loss,
                    "potion_post_heal_hp": analysis.get("post_potion_hp"),
                    "potion_post_heal_max_hp": analysis.get(
                        "post_potion_max_hp"
                    ),
                    "potion_post_heal_planned_card_ids": list(
                        analysis.get("planned_card_ids") or []
                    ),
                    "projected_attack_hp_loss": attack_loss,
                    "projected_end_turn_hp_loss": end_turn_loss,
                    "projected_next_turn_start_hp_loss": next_turn_start_loss,
                    "projected_hp_loss": total_loss,
                }
                self._pending_potion_use = {
                    "turn_key": turn_key,
                    "potion_id": self._token(
                        getattr(potion, "potion_id", "")
                    ),
                }
                return PotionAction(True, potion=potion)
        # Strength, Dexterity, and Energy change the ordered card line rather
        # than merely adding a fixed amount of block.  When no one bottle is
        # enough, re-plan each small deterministic subset and accept only a
        # line whose projected loss is strictly below current HP.  Return one
        # member now; the next authoritative frame evaluates the remainder.
        # Capacity + Essence is intentionally absent from this subset search:
        # it is order-dependent, while nonlethal policy already permits only
        # one bottle before an authoritative reframe.  Single-bottle orb
        # analyses are exact; no unordered combo is allowed to invent a save.
        if lethal and not single_lifesaver:
            deterministic = [
                potion for potion in potions
                if self._token(getattr(potion, "potion_id", ""))
                in {"dexteritypotion", "strengthpotion", "energypotion"}
            ]
            stat_lifesaving_combos = []
            for size in range(2, len(deterministic) + 1):
                for combo in combinations(deterministic, size):
                    combo_ids = tuple(
                        self._token(getattr(item, "potion_id", ""))
                        for item in combo
                    )
                    analysis = self._hypothetical_stat_potion_analysis(
                        combo_ids
                    )
                    combo_loss = (
                        analysis.get("loss") if analysis is not None else None
                    )
                    if combo_loss is not None and int(combo_loss) < hp:
                        stat_lifesaving_combos.append(
                            (int(combo_loss), combo, analysis)
                        )
            if stat_lifesaving_combos:
                combo_loss, combo, analysis = min(
                    stat_lifesaving_combos,
                    key=lambda item: (
                        len(item[1]),
                        sum(
                            self._potion_keep_score(potion)
                            for potion in item[1]
                        ),
                        item[0],
                    ),
                )
                potion = min(combo, key=self._potion_keep_score)
                self.combat_planner.last_decision = {
                    "potion_operation_candidates": potion_operation_candidates,
                    "reason": "potion_stat_combo_survival",
                    "potion_id": potion.potion_id,
                    "potion_score": 110.0,
                    "potion_combo": [item.potion_id for item in combo],
                    "planned_turn_hp_loss": planned_turn_loss,
                    "protected_combo_hp_loss": combo_loss,
                    "potion_candidate_combat_end": bool(
                        analysis.get("true_combat_end")
                    ),
                    "potion_candidate_enemy_hp": list(
                        analysis.get("final_enemy_hp") or []
                    ),
                    "projected_attack_hp_loss": attack_loss,
                    "projected_end_turn_hp_loss": end_turn_loss,
                    "projected_next_turn_start_hp_loss": next_turn_start_loss,
                    "projected_hp_loss": total_loss,
                }
                self._pending_potion_use = {
                    "turn_key": turn_key,
                    "potion_id": self._token(
                        getattr(potion, "potion_id", "")
                    ),
                }
                return PotionAction(True, potion=potion)
        # A run can be recoverable only by a combination even when no single
        # potion crosses the threshold. Enumerate every subset of the tiny
        # defensive belt (at most 31 with Potion Belt), then spend the least
        # valuable member first. The next authoritative frame re-plans before
        # consuming another bottle.
        if (
            lethal
            and not unquantified_play_plan
            and not single_lifesaver
        ):
            defensive = [
                potion for potion in potions
                if self._token(getattr(potion, "potion_id", ""))
                in {
                    "blockpotion", "ghostinajar", "essenceofsteel",
                    "heartofiron", "weakpotion",
                }
            ]
            lifesaving_combos = []
            for size in range(2, len(defensive) + 1):
                for combo in combinations(defensive, size):
                    combo_ids = tuple(
                        self._token(getattr(item, "potion_id", ""))
                        for item in combo
                    )
                    combo_loss = self._hypothetical_defensive_potion_loss(
                        combo_ids
                    )
                    if combo_loss is not None and combo_loss < hp:
                        lifesaving_combos.append((combo_loss, combo))
            if lifesaving_combos:
                combo_loss, combo = min(
                    lifesaving_combos,
                    key=lambda item: (
                        len(item[1]),
                        sum(
                            self._potion_keep_score(potion)
                            for potion in item[1]
                        ),
                        item[0],
                    ),
                )
                potion = min(combo, key=self._potion_keep_score)
                reason = (
                    "potion_pair_survival"
                    if len(combo) == 2
                    else "potion_combo_survival"
                )
                self.combat_planner.last_decision = {
                    "potion_operation_candidates": potion_operation_candidates,
                    "reason": reason,
                    "potion_id": potion.potion_id,
                    "potion_score": 100.0,
                    "potion_pair": [item.potion_id for item in combo]
                    if len(combo) == 2 else None,
                    "potion_combo": [item.potion_id for item in combo],
                    "planned_turn_hp_loss": planned_turn_loss,
                    "protected_pair_hp_loss": combo_loss,
                    "protected_combo_hp_loss": combo_loss,
                    "projected_attack_hp_loss": attack_loss,
                    "projected_end_turn_hp_loss": end_turn_loss,
                    "projected_next_turn_start_hp_loss": next_turn_start_loss,
                    "projected_hp_loss": total_loss,
                }
                self._pending_potion_use = {
                    "turn_key": turn_key,
                    "potion_id": self._token(
                        getattr(potion, "potion_id", "")
                    ),
                }
                if bool(getattr(potion, "requires_target", False)):
                    combo_target = (
                        weak_target
                        if self._token(
                            getattr(potion, "potion_id", "")
                        ) == "weakpotion"
                        else target
                    )
                    if combo_target is None:
                        return None
                    return PotionAction(
                        True, potion=potion,
                        target_monster=combo_target,
                    )
                return PotionAction(True, potion=potion)
        # When two consumables solve the same immediate problem, spend the
        # lower long-term-value slot first (for example Block before Ghost).
        score, potion = max(
            scored,
            key=lambda item: (item[0], -self._potion_keep_score(item[1])),
        )
        keep_score = self._potion_keep_score(potion)
        threshold = (
            10
            if lethal
            else 12 + max(0.0, keep_score - 20.0) * 0.25
        )
        potion_evaluation = {
            "threat": self.combat_planner.combat_threat_profile(self.game),
            "baseline_loss": planned_turn_loss,
            "threshold": threshold,
            "selected_potion_id": getattr(potion, "potion_id", None),
            "selected_score": score,
            "accepted": score >= threshold,
            "candidates": [
                {
                    "potion_id": getattr(item, "potion_id", None),
                    "score": value,
                    "protected_loss": protected_losses.get(id(item)),
                    "damage_reaction": self._hypothetical_shifting_potion_analysis(
                        getattr(item, "potion_id", ""), target,
                    ),
                }
                for value, item in scored
            ],
        }
        self.combat_planner.last_decision["potion_evaluation"] = (
            potion_evaluation
        )
        if score < threshold:
            return None

        healing_analysis = healing_potion_analyses.get(id(potion))
        decision = {
            "potion_operation_candidates": potion_operation_candidates,
            "potion_evaluation": potion_evaluation,
            "reason": (
                "potion_snecko_oil_emergency_replan"
                if snecko_followup_rescue
                and self._token(getattr(potion, "potion_id", ""))
                == "sneckooil"
                else
                "potion_healing_replan_survival"
                if id(potion) in healing_single_lifesavers
                else "potion_cunning_replan_survival"
                if id(potion) in cunning_single_lifesavers
                else "potion_cunning_replan_reserve"
                if id(potion) in cunning_reserve_restorers
                else "potion_known_draw_survival"
                if id(potion) in known_draw_single_lifesavers
                else "potion_stochastic_emergency"
                if distilled_emergency
                and self._token(getattr(potion, "potion_id", ""))
                == "distilledchaos"
                else "potion_value_threshold"
            ),
            "potion_id": potion.potion_id,
            "potion_score": round(score, 3),
            "potion_keep_score": round(float(keep_score), 3),
            "potion_use_threshold": round(float(threshold), 3),
            "incoming": incoming,
            "projected_attack_hp_loss": attack_loss,
            "projected_end_turn_hp_loss": end_turn_loss,
            "projected_next_turn_start_hp_loss": next_turn_start_loss,
            "projected_hp_loss": total_loss,
            "potion_safety_reserve": int(safety_reserve),
            "potion_reserve_breaking_crisis": bool(reserve_breaking_crisis),
            "potion_severe_loss": bool(
                self._potion_loss_opportunity(comparison_loss)["severe"]
            ),
            "potion_severe_loss_threshold": int(
                self._potion_loss_opportunity(comparison_loss)[
                    "severe_threshold"
                ]
            ),
                "planned_turn_hp_loss": planned_turn_loss,
                "potion_turn_use_count": used,
                "unproven_potion_turn_use_count": len(
                    self.unproven_potions_used_this_turn.get(turn_key, set())
                ),
            }
        if self._token(getattr(potion, "potion_id", "")) == "poisonpotion":
            decision["potion_delayed_damage_projection"] = (
                self.combat_planner.delayed_damage_projection(
                    self.game, target, 12 if self._has_relic("Sacred Bark") else 6
                )
            )
        direct_damage = self._direct_damage_potion_hp_loss(
            getattr(potion, "potion_id", None), target
        )
        if direct_damage is not None:
            decision["potion_immediate_enemy_hp_loss"] = int(direct_damage)
        else:
            direct_damage_bounds = self._direct_damage_potion_hp_loss_bounds(
                getattr(potion, "potion_id", None), target
            )
            if direct_damage_bounds is not None:
                decision["potion_immediate_enemy_hp_loss_bounds"] = (
                    direct_damage_bounds
                )
        if (
            self._token(getattr(potion, "potion_id", ""))
            == "regenpotion"
            and regen_potion_projection is not None
        ):
            decision.update({
                "potion_regen_potency": int(
                    regen_potion_projection["potency"]
                ),
                "potion_regen_expected_remaining_turns": int(
                    regen_potion_projection["expected_remaining_turns"]
                ),
                "potion_regen_cashable_turn_ends": int(
                    regen_potion_projection["cashable_turn_ends"]
                ),
                "potion_regen_immediate_healing": int(
                    regen_potion_projection["immediate_healing"]
                ),
                "potion_regen_projected_healing": int(
                    regen_potion_projection["projected_healing"]
                ),
                "potion_regen_healing_blocked": bool(
                    regen_potion_projection["healing_blocked"]
                ),
                "potion_planned_combat_end": bool(planned_combat_end),
            })
        protected_loss = protected_losses.get(id(potion))
        if protected_loss is not None:
            decision.update({
                "potion_protected_hp_loss": int(protected_loss),
                "potion_loss_reduction": max(
                    0, comparison_loss - int(protected_loss)
                ),
            })
        known_draw_analysis = known_draw_potion_analyses.get(id(potion))
        if known_draw_analysis is not None:
            decision.update({
                "potion_known_draw_count": int(
                    known_draw_analysis.get("draw_count") or 0
                ),
                "potion_known_draw_card_ids": list(
                    known_draw_analysis.get("drawn_card_ids") or []
                ),
                "potion_known_draw_planned_loss": int(
                    known_draw_analysis.get("loss") or 0
                ),
                "potion_known_draw_planned_card_ids": list(
                    known_draw_analysis.get("planned_card_ids") or []
                ),
                "potion_candidate_combat_end": bool(
                    known_draw_analysis.get("true_combat_end")
                ),
            })
        cunning_analysis = cunning_potion_analyses.get(id(potion))
        if cunning_analysis is not None:
            decision.update({
                "potion_cunning_generated_shiv_count": int(
                    cunning_analysis.get("generated_shiv_count") or 0
                ),
                "potion_cunning_generated_shiv_plays": int(
                    cunning_analysis.get("generated_shiv_plays") or 0
                ),
                "potion_candidate_hp_loss": cunning_analysis.get("loss"),
                "potion_cunning_post_potion_hp": int(
                    cunning_analysis.get("post_potion_hp") or hp
                ),
                "potion_cunning_post_turn_hp": int(
                    cunning_analysis.get("post_turn_hp") or 0
                ),
                "potion_cunning_safety_reserve": int(
                    cunning_analysis.get("safety_reserve") or 0
                ),
                "potion_cunning_survives": bool(
                    cunning_analysis.get("survives")
                ),
                "potion_cunning_preserves_reserve": bool(
                    cunning_analysis.get("preserves_reserve")
                ),
                "potion_cunning_planned_card_ids": list(
                    cunning_analysis.get("planned_card_ids") or []
                ),
                "potion_cunning_hypothetical_card_uuids": list(
                    cunning_analysis.get("planned_card_uuids") or []
                ),
                "potion_cunning_search_tier": cunning_analysis.get(
                    "search_tier"
                ),
                "potion_cunning_final_player_block": (
                    cunning_analysis.get("final_player_block")
                ),
                "potion_candidate_combat_end": bool(
                    cunning_analysis.get("true_combat_end")
                ),
                "potion_candidate_enemy_hp": list(
                    cunning_analysis.get("final_enemy_hp") or []
                ),
                "potion_loss_reduction": max(
                    0,
                    comparison_loss
                    - int(cunning_analysis.get("loss") or 0),
                ),
            })
        if healing_analysis is not None:
            decision.update({
                "potion_healing_hp_gain": int(
                    healing_analysis.get("hp_gain") or 0
                ),
                "potion_post_heal_hp": int(
                    healing_analysis.get("post_potion_hp") or hp
                ),
                "potion_post_heal_max_hp": int(
                    healing_analysis.get("post_potion_max_hp") or hp
                ),
                "potion_post_heal_planned_loss": healing_analysis.get(
                    "loss"
                ),
                "potion_post_heal_survives": bool(
                    healing_analysis.get("survives")
                ),
                "potion_post_heal_first_card_id": healing_analysis.get(
                    "first_card_id"
                ),
                "potion_post_heal_first_card_uuid": healing_analysis.get(
                    "first_card_uuid"
                ),
                "potion_post_heal_planned_card_ids": list(
                    healing_analysis.get("planned_card_ids") or []
                ),
                "potion_post_heal_search_tier": healing_analysis.get(
                    "search_tier"
                ),
                "potion_candidate_combat_end": bool(
                    healing_analysis.get("true_combat_end")
                ),
                "potion_candidate_enemy_hp": list(
                    healing_analysis.get("final_enemy_hp") or []
                ),
            })
        hand_filter_analysis = hand_filter_analyses.get(id(potion))
        self.pending_potion_hand_filter = None
        if hand_filter_analysis is not None:
            decision.update({
                "potion_hand_filter_reason": hand_filter_analysis.get(
                    "reason"
                ),
                "potion_hand_filter_worthwhile": bool(
                    hand_filter_analysis.get("worthwhile")
                ),
                "potion_hand_filter_targets": list(
                    hand_filter_analysis.get("target_card_ids") or []
                ),
                "potion_hand_filter_target_uuids": list(
                    hand_filter_analysis.get("target_card_uuids") or []
                ),
                "potion_hand_filter_target_count": int(
                    hand_filter_analysis.get("target_count") or 0
                ),
                "potion_hand_filter_persistent_clog_count": int(
                    hand_filter_analysis.get("persistent_clog_count") or 0
                ),
                "potion_hand_filter_expected_redraw_gain": (
                    hand_filter_analysis.get("expected_redraw_gain")
                ),
                "potion_hand_filter_draw_mode": hand_filter_analysis.get(
                    "draw_mode"
                ),
                "potion_hand_filter_horizon": int(
                    hand_filter_analysis.get("horizon") or 0
                ),
                "potion_hand_filter_direct_current_turn_hp_loss_prevented": int(
                    hand_filter_analysis.get(
                        "direct_current_turn_hp_loss_prevented"
                    )
                    or 0
                ),
            })
            # The following HAND_SELECT overlay is part of this potion
            # transaction.  Preserve the already-proven ordered card line so
            # the generic optional exhaust/discard selector cannot remove a
            # low-scoring card that the planner intended to play after the
            # potion.  This is trace context only; no terminal promise is
            # carried across the authoritative reframe.
            if hand_filter_analysis.get("worthwhile"):
                selection_context = list(self._combat_plan_context())
                decision["potion_hand_filter_selection_context"] = (
                    selection_context
                )
                # Potion confirmation can refresh
                # ``combat_planner.last_decision`` before HAND_SELECT is
                # dispatched.  Keep the exact UUID filter as transaction
                # state so that refresh cannot silently broaden the discard
                # plan or invalidate its candidate scores.
                self.pending_potion_hand_filter = {
                    "potion_id": getattr(potion, "potion_id", None),
                    "potion_hand_filter_selection_context": (
                        selection_context
                    ),
                    "potion_hand_filter_target_uuids": list(
                        hand_filter_analysis.get("target_card_uuids") or []
                    ),
                    "potion_hand_filter_expected_redraw_gain": (
                        hand_filter_analysis.get("expected_redraw_gain")
                    ),
                    "potion_hand_filter_draw_mode": (
                        hand_filter_analysis.get("draw_mode")
                    ),
                }
                if baseline_decision.get("planned_sequence"):
                    decision["planned_sequence"] = list(
                        baseline_decision["planned_sequence"]
                    )
                if baseline_decision.get("_combat_context") is not None:
                    decision["_combat_context"] = baseline_decision[
                        "_combat_context"
                    ]
        stat_analysis = stat_potion_analyses.get(id(potion))
        if stat_analysis is not None:
            decision.update({
                "potion_candidate_hp_loss": stat_analysis.get("loss"),
                "potion_candidate_combat_end": bool(
                    stat_analysis.get("true_combat_end")
                ),
                "potion_candidate_enemy_hp": list(
                    stat_analysis.get("final_enemy_hp") or []
                ),
                "potion_baseline_enemy_hp": list(
                    stat_analysis.get("baseline_enemy_hp") or []
                ),
                "potion_marginal_damage": stat_analysis.get(
                    "offense_gain"
                ),
                "potion_marginal_kills": int(
                    stat_analysis.get("marginal_kills") or 0
                ),
                "potion_candidate_critical_setup": bool(
                    stat_analysis.get("critical_setup")
                ),
                "potion_orb_slots_before": stat_analysis.get(
                    "orb_slots_before"
                ),
                "potion_orb_slots_after": stat_analysis.get(
                    "orb_slots_after"
                ),
                "potion_occupied_orbs_before": stat_analysis.get(
                    "occupied_orbs_before"
                ),
                "potion_occupied_orbs_after": stat_analysis.get(
                    "occupied_orbs_after"
                ),
                "potion_orb_ids_after": list(
                    stat_analysis.get("orb_ids_after") or []
                ),
                "potion_orb_channels": int(
                    stat_analysis.get("orb_channels") or 0
                ),
                "potion_orb_overflow_evokes": int(
                    stat_analysis.get("orb_overflow_evokes") or 0
                ),
                "potion_dark_evoke_damage": int(
                    stat_analysis.get("dark_evoke_damage") or 0
                ),
                "potion_unmodeled_lightning_evokes": int(
                    stat_analysis.get("unmodeled_lightning_evokes") or 0
                ),
                "potion_sequence": list(
                    stat_analysis.get("potion_sequence") or []
                ),
                "potion_post_effect_enemy_hp": list(
                    stat_analysis.get("post_potion_enemy_hp") or []
                ),
                "potion_post_effect_enemy_block": list(
                    stat_analysis.get("post_potion_enemy_block") or []
                ),
                "potion_loss_reduction": max(
                    0,
                    comparison_loss
                    - int(stat_analysis.get("loss") or 0),
                ),
            })
        if (
            self._token(getattr(potion, "potion_id", ""))
            == "liquidmemories"
            and liquid_memories_analysis is not None
        ):
            selected = liquid_memories_analysis["card"]
            decision.update({
                "liquid_memories_card_id": getattr(selected, "card_id", None),
                "liquid_memories_card_uuid": getattr(selected, "uuid", None),
                "liquid_memories_baseline_loss": liquid_memories_analysis[
                    "baseline_loss"
                ],
                "liquid_memories_candidate_loss": liquid_memories_analysis[
                    "candidate_loss"
                ],
                "liquid_memories_loss_reduction": liquid_memories_analysis[
                    "loss_reduction"
                ],
                "liquid_memories_marginal_kills": liquid_memories_analysis[
                    "marginal_kills"
                ],
                "liquid_memories_critical_setup": liquid_memories_analysis[
                    "critical_setup"
                ],
            })
            self.pending_selection_context = {
                "kind": "liquid_memories",
                "act": int(self.game.act),
                "floor": int(self.game.floor),
                "turn": int(self.game.turn),
                "card_id": getattr(selected, "card_id", None),
                "card_uuid": getattr(selected, "uuid", None),
                "analysis": {
                    key: value
                    for key, value in liquid_memories_analysis.items()
                    if key not in {"card", "planned_sequence"}
                },
            }
        if (
            self._token(getattr(potion, "potion_id", ""))
            == "duplicationpotion"
            and duplication_potion_analysis is not None
            and duplication_potion_analysis.get("worthwhile")
        ):
            selected = duplication_potion_analysis["card"]
            decision.update({
                "duplication_card_id": getattr(selected, "card_id", None),
                "duplication_card_uuid": duplication_potion_analysis[
                    "card_uuid"
                ],
                "duplication_baseline_loss": duplication_potion_analysis[
                    "baseline_loss"
                ],
                "duplication_candidate_loss": duplication_potion_analysis[
                    "candidate_loss"
                ],
                "duplication_loss_reduction": duplication_potion_analysis[
                    "loss_reduction"
                ],
                "duplication_marginal_kills": duplication_potion_analysis[
                    "marginal_kills"
                ],
            })
            self.pending_selection_context = {
                "kind": "duplication_potion",
                "act": int(self.game.act),
                "floor": int(self.game.floor),
                "turn": int(self.game.turn),
                "combat_identity": self._combat_identity(),
                "card_id": getattr(selected, "card_id", None),
                "card_uuid": duplication_potion_analysis["card_uuid"],
                "target_index": duplication_potion_analysis[
                    "target_index"
                ],
                "confirmed": False,
            }
        self.combat_planner.last_decision = decision
        self._pending_potion_use = {
            "turn_key": turn_key,
            "potion_id": self._token(getattr(potion, "potion_id", "")),
        }
        if potion.requires_target:
            if (
                self._token(getattr(potion, "potion_id", ""))
                == "weakpotion"
            ):
                target = weak_target
            if target is None:
                return None
            return PotionAction(True, potion=potion, target_monster=target)
        return PotionAction(True, potion=potion)

    def confirm_potion_use(self, game):
        """Count a use only after the controller verifies authoritative removal."""

        pending = self._pending_potion_use or {}
        turn_key = pending.get("turn_key") or (
            int(game.act), int(game.floor), int(game.turn)
        )
        potion_id = pending.get("potion_id")
        self.potions_used_this_turn = {
            key: count for key, count in self.potions_used_this_turn.items()
            if key[0] == turn_key[0] and key[1] == turn_key[1]
        }
        self.potions_used_this_turn[turn_key] = (
            self.potions_used_this_turn.get(turn_key, 0) + 1
        )
        self.unproven_potions_used_this_turn = {
            key: values
            for key, values in self.unproven_potions_used_this_turn.items()
            if key[0] == turn_key[0] and key[1] == turn_key[1]
        }
        if potion_id in {
            *self.ZERO_LOSS_UNPROVEN_POTION_IDS,
            "powerpotion",
        }:
            self.unproven_potions_used_this_turn.setdefault(
                turn_key, set()
            ).add(potion_id)
        self._pending_potion_use = None
        context = self.pending_selection_context or {}
        if (
            context.get("kind") == "duplication_potion"
            and (
                context.get("act"),
                context.get("floor"),
                context.get("turn"),
            )
            == turn_key
        ):
            context["confirmed"] = True

    def _boss_reward_transition_context(self):
        """Observed/derived HP state after the automatic act transition."""

        current_hp = max(0, int(getattr(self.game, "current_hp", 0) or 0))
        max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
        healing_blocked = self._has_relic("Mark of the Bloom")
        heal_fraction = (
            0.75
            if int(getattr(self.game, "ascension_level", 0) or 0) >= 5
            else 1.0
        )
        recovered = (
            0
            if healing_blocked
            else int(max(0, max_hp - current_hp) * heal_fraction)
        )
        next_act_hp = min(max_hp, current_hp + recovered)
        return {
            "current_hp_before_transition": current_hp,
            "max_hp": max_hp,
            "automatic_heal_fraction": heal_fraction,
            "healing_blocked": healing_blocked,
            "automatic_heal_amount": recovered,
            "projected_next_act_hp": next_act_hp,
            "projected_next_act_hp_ratio": round(
                next_act_hp / max_hp, 3
            ),
        }

    def _boss_energy_marginal_profile(self, relic_id, profile=None):
        """Price a boss relic's energy by the deck's *next* energy point.

        The priority list already gives energy relics a useful base prior, but
        previously valued the sixth permanent energy almost like the fourth.
        Keep this compact and deck-derived: it is used both by the local score
        and as an explicitly labelled estimate in the model's volatile tail.
        """

        relic_id = self._token(relic_id)
        stable_energy_relics = {
            "bustedcrown", "coffeedripper", "cursedkey", "ectoplasm",
            "fusionhammer", "markofpain", "philosophersstone",
            "runicdome", "sozu", "velvetchoker",
        }
        conditional_energy_relics = {
            "hoveringkite", "nuclearbattery", "slaverscollar",
        }
        candidate_adds_energy = relic_id in stable_energy_relics
        profile = profile or self._deck_profile()
        deck = list(getattr(self.game, "deck", []) or [])
        owned_tokens = {
            self._token(getattr(relic, "relic_id", ""))
            for relic in getattr(self.game, "relics", []) or []
        }
        owned_stable = sorted(owned_tokens & stable_energy_relics)
        owned_conditional = sorted(owned_tokens & conditional_energy_relics)
        current_energy = 3 + len(owned_stable)
        projected_energy = current_energy + int(candidate_adds_energy)
        average_cost = float(profile.get("average_cost", 0.0) or 0.0)
        expensive = int(profile.get("expensive", 0) or 0)
        draw_role = float(
            (profile.get("roles") or {}).get("draw", 0.0) or 0.0
        )
        zero_cost = sum(self._card_cost(card) == 0 for card in deck)
        x_cost = self._x_cost_card_count(deck)
        mummified_discount = float(
            self._has_relic("Mummified Hand")
            and float((profile.get("roles") or {}).get("power", 0) or 0)
            > 0
        )
        spend_pressure = max(
            0.0,
            min(
                1.0,
                0.35 * min(1.0, expensive / 5.0)
                + 0.25 * min(1.0, draw_role / 2.0)
                + 0.25 * max(0.0, min(1.0, (average_cost - 1.0) / 0.6))
                + 0.15 * min(1.0, float(x_cost))
                - 0.10 * min(1.0, zero_cost / 3.0)
                - 0.10 * mummified_discount,
            ),
        )
        # Distribution of printed hand costs, sampled without replacement.
        # This estimates whether another energy can be spent, not whether a
        # hypothetical hand wins. Unplayable curses/statuses contribute zero.
        hand_size = min(5, len(deck))
        cost_counts = {(0, 0): 1}
        for card in deck:
            cost = self._card_cost(card)
            playable_cost = (
                current_energy + 1 if cost == -1
                else max(0, cost) if cost >= 0 else 0
            )
            updated = dict(cost_counts)
            for (count, total), ways in cost_counts.items():
                if count < hand_size:
                    state = (count + 1, min(current_energy + 1, total + playable_cost))
                    updated[state] = updated.get(state, 0) + ways
            cost_counts = updated
        total_hands = sum(
            ways for (count, _), ways in cost_counts.items()
            if count == hand_size
        )
        spendable_extra = sum(
            ways for (count, total), ways in cost_counts.items()
            if count == hand_size and total > current_energy
        ) / max(1, total_hands)
        # Existing recurring energy and power discounts reduce this estimate.
        support_discount = min(
            0.75,
            0.2 * float((profile.get("roles") or {}).get("energy", 0) or 0)
            + 0.25 * mummified_discount,
        )
        fourth_energy_credit = 18.0 * spendable_extra * (1.0 - support_discount)
        if relic_id == "slaverscollar" and current_energy <= 3:
            # Guaranteed in elites/bosses, absent in ordinary rooms.
            adjustment = fourth_energy_credit * 0.8
        elif not candidate_adds_energy:
            adjustment = 0.0
        elif current_energy <= 3:
            # A fixed prior cannot distinguish an unusable fourth energy
            # from one which enables an attack after paying for defense.
            # Keep every relic-specific drawback in the final score.
            adjustment = fourth_energy_credit
        elif current_energy == 4:
            adjustment = -6.0 * (1.0 - spend_pressure)
        else:
            adjustment = (
                -12.0
                - 4.0 * max(0, current_energy - 5)
                + 8.0 * spend_pressure
            )
        return {
            "candidate_adds_energy": candidate_adds_energy,
            "current_permanent_energy": current_energy,
            "projected_permanent_energy": projected_energy,
            "current_energy_relic_ids": owned_stable,
            "conditional_energy_relic_ids": owned_conditional,
            "candidate_energy_delta": int(candidate_adds_energy),
            "deck_energy_demand": round(spend_pressure, 3),
            "existing_energy_support": round(
                float((profile.get("roles") or {}).get("energy", 0.0) or 0.0),
                3,
            ),
            "average_cost": round(average_cost, 3),
            "expensive_count": expensive,
            "draw_role": round(draw_role, 3),
            "zero_cost_count": zero_cost,
            "x_cost_count": x_cost,
            "mummified_hand_power_discount_active": bool(mummified_discount),
            "spend_pressure_estimate": round(spend_pressure, 3),
            "extra_energy_spendable_hand_fraction": round(spendable_extra, 3),
            "fourth_energy_credit": round(fourth_energy_credit, 3),
            "energy_estimate_basis": "five_card_cost_distribution_not_combat_simulation",
            "local_marginal_adjustment": round(adjustment, 3),
        }

    def _velvet_choker_profile(self, profile=None):
        """Estimate how much a deck depends on playing beyond six cards.

        Counting only zero-cost density misses Defect chains where draw,
        energy generation, and created cards repeatedly refill the hand.
        Include only currently owned relics and visible card upgrades; later
        acquisitions are not evidence available at this choice.
        """

        profile = profile or self._deck_profile()
        deck = list(getattr(self.game, "deck", []) or [])
        draw_volume = sum(
            int(FastCombatPlanner.DRAW_COUNTS.get(
                self._token(getattr(card, "card_id", "")), 0
            ) or 0)
            + (
                int(FastCombatPlanner.UPGRADED_DRAW_BONUSES.get(
                    self._token(getattr(card, "card_id", "")), 0
                ) or 0)
                if int(getattr(card, "upgrades", 0) or 0) > 0
                else 0
            )
            for card in deck
        )
        energy_output = sum(
            int(FastCombatPlanner.ENERGY_VALUES.get(
                self._token(getattr(card, "card_id", "")), 0
            ) or 0)
            + (
                int(getattr(card, "upgrades", 0) or 0)
                if self._token(getattr(card, "card_id", "")) in {
                    "adrenaline", "bloodletting", "tactician", "turbo",
                } else 0
            )
            for card in deck
        )
        opening_draw = (
            2 * self._has_relic("Ring of the Snake")
            + 2 * self._has_relic("Bag of Preparation")
            + self._has_relic("Ring of the Serpent")
        )
        opening_energy = (
            self._has_relic("Lantern")
            + 2 * self._has_relic("Nuclear Battery")
        )
        generated_card_values = {
            "bladedance": 3.0,
            "cloakanddagger": 1.0,
            "creativeai": 1.0,
            "discovery": 1.0,
            "distraction": 1.0,
            "helloworld": 1.0,
            "infernalblade": 1.0,
            "stormofsteel": 2.0,
            "whitenoise": 1.0,
        }
        generated_volume = sum(
            generated_card_values.get(
                self._token(getattr(card, "card_id", "")), 0.0
            )
            for card in deck
        )
        branch_generation = 0.0
        if self._has_relic("Dead Branch"):
            exhaust_sources = sum(
                bool(getattr(card, "exhausts", False)) for card in deck
            )
            # Generated Shivs also exhaust. Count one replacement layer,
            # not an assumed infinite chain or an unknown future acquisition.
            generated_shivs = sum(
                generated_card_values.get(self._token(card.card_id), 0.0)
                for card in deck
                if self._token(card.card_id) in {
                    "bladedance", "cloakanddagger", "stormofsteel",
                }
            )
            branch_generation = min(6.0, exhaust_sources + generated_shivs)
            generated_volume += branch_generation
        costs = [self._card_cost(card) for card in deck]
        positive_costs = [cost for cost in costs if cost > 0]
        average_positive_cost = (
            sum(positive_costs) / max(1, len(positive_costs))
        )
        zero_density = sum(cost == 0 for cost in costs) / max(1, len(deck))
        cards_seen = min(10.0, 5.0 + opening_draw + draw_volume * 0.5)
        expected_plays = min(
            cards_seen,
            (4.0 + opening_energy) / max(0.75, average_positive_cost)
            + cards_seen * zero_density,
        )
        visible_cap_pressure = max(0.0, expected_plays - 5.5)
        chain_units = (
            (draw_volume + opening_draw) * 0.55
            + (energy_output + opening_energy) * 0.75
            + generated_volume * 0.75
        )
        deck_cycle_scale = min(1.0, 20.0 / max(1, len(deck)))
        chain_pressure = max(
            0.0, chain_units * deck_cycle_scale - 3.0
        )
        total_pressure = visible_cap_pressure + chain_pressure
        score_adjustment = (
            12.0
            if total_pressure <= 0
            else -min(48.0, total_pressure * 12.0)
        )
        return {
            "draw_volume": draw_volume,
            "energy_output": energy_output,
            "generated_card_volume": round(generated_volume, 3),
            "dead_branch_replacement_volume": round(branch_generation, 3),
            "opening_draw_from_relics": opening_draw,
            "opening_energy_from_relics": opening_energy,
            "expected_cards_played": round(expected_plays, 3),
            "visible_cap_pressure": round(visible_cap_pressure, 3),
            "chain_pressure": round(chain_pressure, 3),
            "total_pressure": round(total_pressure, 3),
            "score_adjustment": round(score_adjustment, 3),
        }

    def _defect_reprogram_conflict_profile(self, deck=None):
        """Measure how much Reprogram would undermine an existing orb plan."""

        cards = list(
            deck if deck is not None else getattr(self.game, "deck", []) or []
        )
        if self.chosen_class != PlayerClass.DEFECT:
            return {
                "orb_source_count": 0,
                "orb_engine_count": 0,
                "orb_relic_count": 0,
                "orb_investment": 0.0,
                "conflict_penalty": 0.0,
            }
        definitions = self.ARCHETYPE_DEFINITIONS[PlayerClass.DEFECT]
        orb_sources = set().union(*(
            definitions[name]["sources"]
            for name in ("frost", "lightning", "dark")
        ))
        engine_ids = {
            "biasedcognition", "capacitor", "consume", "defragment", "loop",
        }
        card_ids = [
            self._token(getattr(card, "card_id", "")) for card in cards
        ]
        orb_source_count = sum(
            card_id in orb_sources for card_id in card_ids
        )
        orb_engine_count = sum(
            card_id in engine_ids for card_id in card_ids
        )
        orb_relic_ids = {
            "crackedcore", "frozencore", "goldplatedcables", "inserter",
            "runiccapacitor", "symbioticvirus",
        }
        orb_relic_count = sum(
            self._token(getattr(relic, "relic_id", "")) in orb_relic_ids
            for relic in getattr(self.game, "relics", []) or []
        )
        orb_investment = (
            float(orb_source_count)
            + 1.5 * float(orb_engine_count)
            + 1.5 * float(orb_relic_count)
        )
        conflict_penalty = min(
            40.0, max(0.0, orb_investment - 3.0) * 5.0
        )
        return {
            "orb_source_count": orb_source_count,
            "orb_engine_count": orb_engine_count,
            "orb_relic_count": orb_relic_count,
            "orb_investment": round(orb_investment, 3),
            "conflict_penalty": round(conflict_penalty, 3),
        }

    def _hovering_kite_profile(self, profile=None):
        """Estimate whether the first-discard energy is actually reachable."""

        profile = profile or self._deck_profile()
        deck = list(getattr(self.game, "deck", []) or [])
        discard_state = (profile.get("archetypes") or {}).get(
            "discard", {}
        )
        reliable_sources = max(
            0.0,
            float(
                discard_state.get(
                    "source_reliability", discard_state.get("sources", 0)
                )
                or 0.0
            ),
        )
        cards_seen = min(
            9.0,
            5.0
            + 0.5
            * max(
                0.0,
                float((profile.get("roles") or {}).get("draw", 0.0) or 0.0),
            ),
        )
        activation = min(
            1.0,
            cards_seen * reliable_sources / max(1, len(deck)),
        )
        return {
            "reliable_discard_sources": round(reliable_sources, 3),
            "estimated_cards_seen_per_turn": round(cards_seen, 3),
            "estimated_trigger_probability": round(activation, 3),
            # The generic boss-relic order assumes a usable energy relic.
            # Correct that prior sharply when the deck has only Survivor or
            # another single low-density source, while allowing a real
            # discard package to recover the full value.
            "local_reliability_adjustment": round(
                -24.0 + 30.0 * activation, 3
            ),
        }

    def _coffee_dripper_profile(self, profile=None):
        """Describe repeatable sustain that remains usable without REST."""

        profile = profile or self._deck_profile()
        if self._has_relic("Mark of the Bloom"):
            sustain = []
            credit = 0.0
        else:
            relic_credit = {
                "blackblood": 3.0,
                "meatonthebone": 2.0,
                "eternalfeather": 2.0,
                "burningblood": 1.5,
                "pantograph": 1.5,
                "bloodvial": 1.0,
                "bloodyidol": 1.0,
                "mealticket": 1.0,
                "toyornithopter": 0.75,
            }
            sustain = []
            credit = 0.0
            for relic in getattr(self.game, "relics", []) or []:
                token = self._token(getattr(relic, "relic_id", ""))
                value = relic_credit.get(token, 0.0)
                if value > 0:
                    sustain.append(getattr(relic, "relic_id", None) or token)
                    credit += value
            card_credit = {
                "selfrepair": 1.5,
                "reaper": 1.25,
                "bite": 0.45,
                "bandageup": 0.75,
            }
            for card in getattr(self.game, "deck", []) or []:
                token = self._token(getattr(card, "card_id", ""))
                value = card_credit.get(token, 0.0)
                if value > 0:
                    sustain.append(getattr(card, "card_id", None) or token)
                    credit += value
        readiness = self._deck_readiness(profile)
        gaps = readiness.get("gaps") or {}
        readiness_score = float(readiness.get("score", 0.0) or 0.0)
        consistency = float(readiness.get("consistency", 0.0) or 0.0)
        development_shortfall = max(0.0, 0.60 - readiness_score)
        consistency_shortfall = max(0.0, 0.60 - consistency)
        sustain_shortfall = max(0.0, 2.0 - credit)
        rest_lock_risk_penalty = min(
            20.0,
            28.0 * development_shortfall
            + 16.0 * consistency_shortfall
            + 3.0 * sustain_shortfall,
        )
        disabled = [
            name for name in ("Regal Pillow", "Dream Catcher")
            if self._has_relic(name)
        ]
        return {
            "rest_disabled": True,
            "non_rest_sustain_sources": sustain,
            "sustain_credit_estimate": round(credit, 3),
            "deck_readiness_score": round(readiness_score, 3),
            "deck_consistency": round(consistency, 3),
            "development_shortfall": round(development_shortfall, 3),
            "consistency_shortfall": round(consistency_shortfall, 3),
            "sustain_shortfall": round(sustain_shortfall, 3),
            "rest_lock_risk_penalty": round(rest_lock_risk_penalty, 3),
            "block_gap": round(float(gaps.get("block", 0.0) or 0.0), 3),
            "draw_gap": round(float(gaps.get("draw", 0.0) or 0.0), 3),
            "healing_blocked": self._has_relic("Mark of the Bloom"),
            "disabled_relic_synergies": disabled,
        }

    def _mark_of_pain_profile(self, profile=None):
        """Separate status sources from actual Wound payoff and cleanup."""

        profile = profile or self._deck_profile()
        deck = list(getattr(self.game, "deck", []) or [])
        source_ids = {
            "immolate", "powerthrough", "recklesscharge", "wildstrike",
        }
        payoff_values = {"evolve": 4.0, "firebreathing": 3.0}
        cleanup_values = {
            "secondwind": 2.5,
            "fiendfire": 2.0,
            "seversoul": 1.5,
            "burningpact": 1.0,
            "purity": 2.0,
        }
        sources = []
        payoffs = []
        cleanup = []
        mitigation = 0.0
        for card in deck:
            token = self._token(getattr(card, "card_id", ""))
            card_id = getattr(card, "card_id", None) or token
            if token in source_ids:
                sources.append(card_id)
            if token in payoff_values:
                payoffs.append(card_id)
                mitigation += payoff_values[token]
            value = cleanup_values.get(token, 0.0)
            if token == "truegrit" and int(getattr(card, "upgrades", 0) or 0) > 0:
                value = 1.0
            if value > 0:
                cleanup.append(card_id)
                mitigation += value
        if self._has_relic("Medical Kit"):
            cleanup.append("Medical Kit")
            mitigation += 4.0
        penalty = 8.0
        if not payoffs and not cleanup:
            penalty += 4.0
            if sources:
                penalty += min(4.0, 2.0 * len(sources))
        wound_penalty = max(2.0, penalty - min(10.0, mitigation))
        deck_size = int(profile.get("size", len(deck)) or len(deck))
        return {
            "wounds_added_each_combat": 2,
            "effective_combat_deck_size": deck_size + 2,
            "opening_cycle_dead_draw_fraction": round(
                2.0 / max(1, deck_size + 2), 3
            ),
            "existing_status_sources": sources,
            "observed_status_payoffs": payoffs,
            "observed_status_cleanup": cleanup,
            "unmitigated_wounds": not bool(payoffs or cleanup),
            "wound_penalty_estimate": round(wound_penalty, 3),
        }

    def _tiny_house_post_state(self):
        """Resolve Tiny House's effective, not advertised, post-state."""

        current_hp = max(0, int(getattr(self.game, "current_hp", 0) or 0))
        old_max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
        new_max_hp = old_max_hp + 5
        healing_blocked = self._has_relic("Mark of the Bloom")
        immediate_heal = 0 if healing_blocked else min(5, new_max_hp - current_hp)
        post_relic_hp = min(new_max_hp, current_hp + immediate_heal)
        heal_fraction = (
            0.75
            if int(getattr(self.game, "ascension_level", 0) or 0) >= 5
            else 1.0
        )
        transition_heal = (
            0
            if healing_blocked
            else int(max(0, new_max_hp - post_relic_hp) * heal_fraction)
        )
        next_act_hp = min(new_max_hp, post_relic_hp + transition_heal)
        baseline = self._boss_reward_transition_context()
        ectoplasm = self._has_relic("Ectoplasm")
        try:
            potion_full = bool(self.game.are_potions_full())
        except (AttributeError, TypeError):
            real_count = sum(
                self._token(getattr(potion, "potion_id", ""))
                not in {"", "potionslot"}
                for potion in getattr(self.game, "potions", []) or []
            )
            potion_full = real_count >= self._potion_slot_capacity()
        upgradeable = sum(
            int(getattr(card, "upgrades", 0) or 0) <= 0
            and getattr(card, "type", None)
            not in {
                spirecomm.spire.card.CardType.CURSE,
                spirecomm.spire.card.CardType.STATUS,
            }
            for card in getattr(self.game, "deck", []) or []
        )
        return {
            "max_hp_delta": 5,
            "raw_heal": 5,
            "effective_immediate_heal": immediate_heal,
            "baseline_next_act_hp": baseline["projected_next_act_hp"],
            "projected_next_act_hp": next_act_hp,
            "net_next_act_hp_delta": (
                next_act_hp - int(baseline["projected_next_act_hp"])
            ),
            "raw_gold_gain": 50,
            "effective_gold_gain": 0 if ectoplasm else 50,
            "gold_blocked_by": "Ectoplasm" if ectoplasm else None,
            "potion_slot_available": not potion_full,
            "upgradeable_card_count": upgradeable,
            "card_reward_available": True,
            "healing_blocked": healing_blocked,
        }

    def _boss_relic_score(self, relic):
        relic_id = self._token(relic.relic_id)
        rank = self.priorities.BOSS_RELIC_PRIORITIES.get(relic.relic_id)
        score = 30 - rank if rank is not None else 0
        deck = list(getattr(self.game, "deck", []) or [])
        hp_ratio = self.game.current_hp / max(1, self.game.max_hp)
        # Boss relics are selected after the act boss, immediately before the
        # normal full-heal transition.  Current combat HP is therefore the
        # wrong recovery basis for Coffee Dripper (except Mark of the Bloom,
        # which blocks that heal).
        transition = self._boss_reward_transition_context()
        next_act_hp_ratio = float(
            transition["projected_next_act_hp_ratio"]
        )
        costs = [max(0, card.cost) for card in deck if card.cost >= 0]
        average_cost = sum(costs) / max(1, len(costs))
        cheap_cards = sum(1 for card in deck if 0 <= card.cost <= 1)
        zero_cards = sum(1 for card in deck if card.cost == 0)
        curse_count = sum(1 for card in deck if card.rarity == spirecomm.spire.card.CardRarity.CURSE)
        deck_profile = self._deck_profile(deck)
        energy_profile = self._boss_energy_marginal_profile(
            relic_id, deck_profile
        )
        score += float(energy_profile["local_marginal_adjustment"])

        if relic_id == "runicdome":
            return -1000
        if relic_id == "sozu":
            score -= 55
        elif relic_id == "bustedcrown":
            score -= 35
        elif relic_id == "philosophersstone":
            score -= 16
        elif relic_id == "ectoplasm":
            score -= 22 if self.game.act <= 1 else 8
        elif relic_id == "markofpain":
            score -= float(
                self._mark_of_pain_profile(deck_profile)[
                    "wound_penalty_estimate"
                ]
            )
        elif relic_id == "sneckoeye":
            # Snecko Eye is not a generic draw relic.  Its random costs are
            # only favourable when the deck has enough expensive cards to
            # discount and enough draw to exploit the larger hand.  A small
            # starter/one-cost deck otherwise turns every predictable turn
            # into a high-variance loss, and the remote adviser must not be
            # able to override that local safety floor with a small bonus.
            high_cost = sum(1 for card in deck if card.cost >= 2)
            draw_count = int(deck_profile["roles"].get("draw", 0) or 0)
            low_cost_density = sum(
                1 for card in deck if 0 <= card.cost <= 1
            ) / max(1, len(deck))
            if (
                high_cost >= 5
                or (
                    high_cost >= 4
                    and average_cost >= 1.35
                    and draw_count >= 2
                )
            ):
                score += 24
            elif high_cost <= 2 and average_cost < 1.30 and low_cost_density >= 0.60:
                score -= 80
            else:
                score -= 36
        elif relic_id == "velvetchoker":
            score += float(
                self._velvet_choker_profile(deck_profile)[
                    "score_adjustment"
                ]
            )
        elif relic_id == "slaverscollar":
            # Conditional energy is concentrated in the elite and boss fights
            # that determine whether a run advances, without capping ordinary
            # draw/zero-cost turns.
            score += 20.0
        elif relic_id == "wristblade":
            shiv_output = sum(
                {
                    "bladedance": 3,
                    "cloakanddagger": 1,
                    "infiniteblades": 1,
                    "stormofsteel": 2,
                }.get(self._token(card.card_id), 0)
                for card in deck
            )
            zero_cost_attacks = sum(
                1
                for card in deck
                if getattr(card, "type", None)
                == spirecomm.spire.card.CardType.ATTACK
                and self._card_cost(card) == 0
            )
            wrist_support = shiv_output + zero_cost_attacks
            score += (
                min(22.0, wrist_support * 4.0)
                if wrist_support >= 3
                else -20.0 + wrist_support * 3.0
            )
        elif relic_id == "runicpyramid":
            # Pyramid is only strong when retained cards can be converted into
            # useful future hands. One Survivor must not cancel five basic
            # Defends, so estimate practical hand-control capacity instead of
            # merely counting outlet cards.
            control_capacity = {
                "acrobatics": 1.0,
                "burningpact": 1.0,
                "calculatedgamble": 4.0,
                "concentrate": 2.0,
                "daggerthrow": 1.0,
                "fiendfire": 4.0,
                "prepared": 2.0,
                "recycle": 2.0,
                "secondwind": 3.0,
                "survivor": 1.0,
                "truegrit": 1.0,
            }
            hand_control = sum(
                control_capacity.get(self._token(card.card_id), 0.0)
                for card in deck
            )
            status_count = sum(
                1 for card in deck
                if card.type == spirecomm.spire.card.CardType.STATUS
            )
            basic_defends = sum(
                1 for card in deck
                if card.rarity == spirecomm.spire.card.CardRarity.BASIC
                and self._token(card.card_id).startswith("defend")
            )
            high_cost = sum(1 for card in deck if card.cost >= 2)
            retained_junk = basic_defends + curse_count * 2 + status_count * 1.5
            unmanaged_junk = max(0.0, retained_junk - 2.0 - hand_control * 0.75)
            clog = (
                curse_count * 10
                + status_count * 7
                + basic_defends * 2.5
                + unmanaged_junk * 4
                + max(0.0, high_cost - hand_control - 4) * 2
                + max(0, len(deck) - 20) * 1.5
            )
            score += (
                8 + min(12, hand_control * 2.5) - clog
                if average_cost <= 1.25 and curse_count == 0
                else -18 - clog
            )
        elif relic_id == "coffeedripper":
            coffee_profile = self._coffee_dripper_profile(deck_profile)
            sustain_credit = float(
                coffee_profile["sustain_credit_estimate"]
            )
            # A small heal after each fight is useful, but it does not make a
            # developing deck safe without campfire recovery.  Price the
            # irreversible rest lock separately from the immediate act
            # transition heal: weak/inconsistent decks are precisely the ones
            # that need to convert a bad Act 2 fight into a large REST heal.
            score -= float(coffee_profile["rest_lock_risk_penalty"])
            score += 8 if next_act_hp_ratio >= 0.85 else -28
            if sustain_credit <= 0:
                score -= (
                    2.0
                    if int(energy_profile["current_permanent_energy"]) <= 3
                    else 8.0
                )
                score -= min(
                    6.0,
                    4.0 * float(coffee_profile["block_gap"])
                    + 2.0 * float(coffee_profile["draw_gap"]),
                )
            else:
                score += min(8.0, sustain_credit * 2.0)
        elif relic_id == "fusionhammer":
            score += 8 if hp_ratio < 0.8 else -4
        elif relic_id == "cursedkey":
            score += 20
        elif relic_id == "hoveringkite":
            score += float(
                self._hovering_kite_profile(deck_profile)[
                    "local_reliability_adjustment"
                ]
            )
        elif relic_id == "emptycage":
            score += 12 + curse_count * 8
        elif relic_id in {"astrolabe", "pandorasbox"}:
            starters = sum(1 for card in deck if card.card_id in {"Strike_R", "Strike_G", "Strike_B", "Defend_R", "Defend_G", "Defend_B"})
            score += min(18, starters * 2)
        elif relic_id == "nuclearbattery" and self.chosen_class == PlayerClass.DEFECT:
            score += 24
        elif relic_id == "inserter" and self.chosen_class == PlayerClass.DEFECT:
            score += 14
        elif relic_id == "tinyhouse":
            tiny = self._tiny_house_post_state()
            score -= 3.0 if tiny["effective_gold_gain"] == 0 else 0.0
            score -= 2.0 if not tiny["potion_slot_available"] else 0.0
            score -= 2.0 if tiny["upgradeable_card_count"] <= 0 else 0.0
            score -= 4.0 if tiny["healing_blocked"] else 0.0
        score += self._relic_build_adjustment(relic, deck_profile)
        return score

    def _boss_relic_candidate_facts(self, relic, profile=None):
        """Return compact post-choice facts without a local recommendation."""

        profile = profile or self._deck_profile()
        relic_id = self._token(getattr(relic, "relic_id", ""))
        facts = {
            "counter": self._macro_counter(getattr(relic, "counter", None)),
            "description": self._macro_description(
                getattr(relic, "description", "")
            ),
        }
        energy = self._boss_energy_marginal_profile(relic_id, profile)
        if energy["candidate_adds_energy"]:
            facts["energy_marginal"] = {
                key: value for key, value in energy.items()
                if key != "local_marginal_adjustment"
            }
        if relic_id == "coffeedripper":
            coffee = self._coffee_dripper_profile(profile)
            coffee["projected_next_act_hp_ratio"] = (
                self._boss_reward_transition_context()[
                    "projected_next_act_hp_ratio"
                ]
            )
            facts["coffee_dripper_consequence"] = coffee
        elif relic_id == "markofpain":
            mark = self._mark_of_pain_profile(profile)
            mark.pop("wound_penalty_estimate", None)
            facts["mark_of_pain_consequence"] = mark
        elif relic_id == "bustedcrown":
            facts["busted_crown_override_profile"] = (
                self._busted_crown_model_override_profile(profile)
            )
        elif relic_id == "tinyhouse":
            facts["tiny_house_post_state"] = self._tiny_house_post_state()
        elif relic_id == "hoveringkite":
            facts["hovering_kite_reliability"] = (
                self._hovering_kite_profile(profile)
            )
        elif relic_id == "velvetchoker":
            facts["velvet_choker_constraint"] = (
                self._velvet_choker_profile(profile)
            )
        if relic_id == "sneckoeye":
            snecko = self._snecko_eye_profile()
            facts.update({
                "snecko_profile": snecko,
                "snecko_guard": (
                    "strong_expensive_draw_support"
                    if snecko["recommended"]
                    else "low_cost_variance_trap"
                ),
            })
        return facts

    @staticmethod
    def _boss_relic_candidate_consequences(relic):
        """Describe deterministic follow-up screens for boss relic choices."""

        relic_id = getattr(relic, "relic_id", None)
        token = SimpleAgent._token(relic_id)
        consequences = {
            "operation": "gain_boss_relic",
            "relic_id": relic_id,
        }
        if token == "astrolabe":
            consequences.update({
                "future_costs": [{
                    "kind": "astrolabe_grid_selection",
                    "operation": "transform_and_upgrade",
                    "select_count": 3,
                    "domain": "current_deck",
                    "selection_mode": "player_choice",
                    "timing": "after_relic_pickup",
                }],
                "uncertainty": [
                    "the three transformed card UUIDs settle on the "
                    "following GRID surface"
                ],
                "uncertainty_classification": {
                    "status": "classified_future",
                    "authority": "base_game_relic_mechanics",
                    "reason": (
                        "Astrolabe opens an exact three-card "
                        "transform-and-upgrade GRID"
                    ),
                },
            })
        elif token == "emptycage":
            consequences.update({
                "future_costs": [{
                    "kind": "relic_grid_selection",
                    "relic_id": "Empty Cage",
                    "domain": "current_deck",
                    "operation": "remove",
                    "select_count": 2,
                    "selection_mode": "player_choice",
                    "timing": "after_relic_pickup",
                }],
                "uncertainty": [
                    "the two removed card UUIDs settle on the following "
                    "GRID surface"
                ],
                "uncertainty_classification": {
                    "status": "classified_future",
                    "authority": "base_game_relic_mechanics",
                    "reason": (
                        "Empty Cage opens an exact two-card removal GRID"
                    ),
                },
            })
        return consequences

    def _busted_crown_model_override_profile(self, deck_profile=None):
        """Prove when a remote override may accept lost reward diversity.

        Busted Crown removes two of the three normal card-reward choices for
        every remaining act.  A model may override the deterministic choice
        only after the current deck is already large, consistent, has its
        scaling bottleneck covered, and can independently use the extra
        energy.  The local scorer remains free to pick Crown when all visible
        alternatives are even worse; this gate only prevents an unsupported
        remote override of an irreversible long-horizon cost.
        """

        profile = deck_profile or self._deck_profile()
        readiness = profile.get("readiness") or {}
        coverage = readiness.get("coverage") or {}
        energy = self._boss_energy_marginal_profile(
            "bustedcrown", profile
        )
        deck_size = len(list(getattr(self.game, "deck", []) or []))
        readiness_score = float(readiness.get("score", 0.0) or 0.0)
        consistency = float(readiness.get("consistency", 0.0) or 0.0)
        scaling_coverage = float(coverage.get("scaling", 0.0) or 0.0)
        energy_demand = float(energy.get("deck_energy_demand", 0.0) or 0.0)
        override_eligible = bool(
            deck_size >= 18
            and readiness_score >= 0.72
            and consistency >= 0.75
            and scaling_coverage >= 0.75
            and energy_demand >= 0.65
        )
        return {
            "override_eligible": override_eligible,
            "deck_size": deck_size,
            "readiness_score": round(readiness_score, 3),
            "consistency": round(consistency, 3),
            "scaling_coverage": round(scaling_coverage, 3),
            "energy_demand": round(energy_demand, 3),
            "required": {
                "deck_size": 18,
                "readiness_score": 0.72,
                "consistency": 0.75,
                "scaling_coverage": 0.75,
                "energy_demand": 0.65,
            },
        }

    def _boss_relic_model_override_eligible(self, relic, profile=None):
        relic_id = self._token(getattr(relic, "relic_id", ""))
        if relic_id == "runicdome":
            return False
        if relic_id == "bustedcrown":
            return self._busted_crown_model_override_profile(
                profile
            )["override_eligible"]
        return True

    def choose_boss_relic(self, relics):
        scored = [(self._boss_relic_score(relic), relic) for relic in relics]
        score, chosen = max(scored, key=lambda item: (item[0], -getattr(item[1], "price", 0)))
        can_return = bool(getattr(self.game, "cancel_available", False))
        relic_by_id = {
            f"relic:{getattr(relic, 'relic_id', '')}:{index}": relic
            for index, (_, relic) in enumerate(scored)
        }
        chosen_id = next(
            candidate_id
            for candidate_id, relic in relic_by_id.items()
            if relic is chosen
        )
        deck_profile = self._deck_profile()
        eligible = [
            {
                "candidate_id": candidate_id,
                "kind": "boss_relic",
                "label": getattr(relic, "name", None),
                "relic_id": getattr(relic, "relic_id", None),
                "local_score": relic_score,
                "facts": self._boss_relic_candidate_facts(
                    relic, deck_profile
                ),
            }
            for candidate_id, (relic_score, relic) in zip(
                relic_by_id, scored
            )
            if (
                relic_score > -900
                and self._boss_relic_model_override_eligible(
                    relic, deck_profile
                )
            )
        ]
        selected_ids = self._macro_rank(
            "BOSS_RELIC",
            eligible,
            chosen_id,
            hard_constraints=[
                "RUNIC_DOME_IS_FORBIDDEN",
                "BUSTED_CROWN_REQUIRES_MATURE_SCALING_AND_ENERGY_DEMAND",
                "SNECKO_EYE_REQUIRES_HIGH_COST_OR_DRAW_SUPPORT",
                "ONLY_LISTED_RELICS",
            ],
            state_details={
                "boss_reward_transition": (
                    self._boss_reward_transition_context()
                ),
            },
        )
        chosen_id = selected_ids[0]
        chosen = relic_by_id.get(chosen_id)
        boss_relic_audit_candidates = [
            {
                "id": f"relic:{getattr(relic, 'relic_id', '')}:{index}",
                "choice_id": (
                    f"relic:{getattr(relic, 'relic_id', '')}:{index}"
                ),
                "choice_index": index,
                "action": "choose",
                "semantic_id": (
                    f"relic:{getattr(relic, 'relic_id', '')}:{index}"
                ),
                "score": relic_score,
                "label": getattr(relic, "name", None),
                "legal": True,
                "visible": True,
                "selection_eligible": relic_score > -900,
                "veto_reason": (
                    None if relic_score > -900 else "boss_relic_hard_veto"
                ),
                "reason": (
                    "selected_boss_relic"
                    if relic is chosen else "visible_unchosen_boss_relic"
                ),
                "consequences": (
                    self._boss_relic_candidate_consequences(relic)
                ),
                **self._linear_score_contract(
                    "boss_relic_context_utility_v1",
                    {"context_utility": relic_score},
                    (("context_utility", "context_utility", 1.0),),
                ),
            }
            for index, (relic_score, relic) in enumerate(scored)
        ]
        if can_return:
            boss_relic_audit_candidates.append({
                "id": "action:return",
                "choice_id": "action:return",
                "choice_index": None,
                "action": "return",
                "operation": None,
                "semantic_id": "return",
                "score": 0.0,
                "label": "Skip boss relic",
                "legal": True,
                "visible": True,
                # CommunicationMod exposes RETURN on this screen, but in the
                # base game it is a no-op navigation control rather than a
                # strategic alternative to taking the mandatory boss relic.
                # Preserve it as visible protocol evidence while keeping it
                # out of both the local and remote selection surfaces.
                "selection_eligible": False,
                "veto_reason": "boss_relic_return_is_noop",
                "reason": "visible_noop_return",
                "consequences": {
                    "operation": "return",
                    "relic_changes": {
                        "gain": [], "remove": [], "counter": [],
                    },
                },
                **self._linear_score_contract(
                    "boss_relic_skip_v1",
                    {"skip_value": 0.0},
                    (("skip_value", "skip_value", 1.0),),
                ),
            })
        self._record_noncombat_decision(
            "boss_relic_context_score",
            boss_relic_audit_candidates,
            candidate_contract={
                "score_source": "boss_relic_context_utility",
                "strategy_quality_auditable": True,
                "all_visible_options_scored": True,
                "visible_option_count": len(relics) + int(can_return),
                "filtered_options_retained": True,
                "return_command_included": can_return,
                "identity_source": "protocol_choice_index_and_relic_id",
            },
            chosen=chosen.relic_id,
            chosen_id=chosen_id,
            deck_plan=self._deck_plan_summary(),
        )
        return chosen

    def _snecko_eye_profile(self, deck=None):
        """Expose the deterministic Snecko suitability check to the trace."""

        deck = list(
            getattr(self.game, "deck", []) or []
            if deck is None else deck
        )
        costs = [
            max(0, int(getattr(card, "cost", 0) or 0))
            for card in deck
            if int(getattr(card, "cost", 0) or 0) >= 0
        ]
        high_cost = sum(
            int(getattr(card, "cost", 0) or 0) >= 2 for card in deck
        )
        low_cost = sum(
            0 <= int(getattr(card, "cost", 0) or 0) <= 1 for card in deck
        )
        average_cost = sum(costs) / max(1, len(costs))
        draw_count = int(
            (self._deck_profile(deck).get("roles") or {}).get("draw", 0)
            or 0
        )
        recommended = bool(
            high_cost >= 5
            or (high_cost >= 4 and average_cost >= 1.35 and draw_count >= 2)
        )
        return {
            "deck_size": len(deck),
            "high_cost_cards": high_cost,
            "low_cost_cards": low_cost,
            "average_cost": round(average_cost, 3),
            "draw_cards": draw_count,
            "recommended": recommended,
        }

    def _is_early_act1_building_reward(self):
        room_type = str(getattr(self.game, "room_type", "") or "").lower()
        return (
            int(getattr(self.game, "act", 0) or 0) == 1
            and int(getattr(self.game, "floor", 0) or 0) < 16
            and not bool(getattr(self.game, "in_combat", False))
            and "boss" not in room_type
        )

    @staticmethod
    def _card_number(card, field, base_field=None):
        value = int(getattr(card, field, 0) or 0)
        if value >= 0:
            return value
        return max(0, int(getattr(card, base_field or field, 0) or 0))

    def _card_build_tags(self, card):
        card_id = self._token(getattr(card, "card_id", ""))
        tags = set()
        damage = self._card_number(card, "damage", "base_damage")
        block = self._card_number(card, "block", "base_block")
        if (
            getattr(card, "type", None) == spirecomm.spire.card.CardType.ATTACK
            and damage > 0
        ) or card_id in {"bladedance", "cloakanddagger", "stormofsteel"}:
            # These skills produce attacks in the same hand. A zero printed
            # damage field does not make their generated Shivs non-offensive.
            tags.add("damage")
        if self.priorities.is_card_defensive(card) or block > 0:
            tags.add("block")
        if card_id in FastCombatPlanner.DRAW_COUNTS:
            tags.add("draw")
        if card_id in FastCombatPlanner.ENERGY_VALUES:
            tags.add("energy")
        if card_id in FastCombatPlanner.NEXT_TURN_ENERGY_VALUES:
            tags.add("next_turn_energy")
            tags.add("energy")
        if (
            self.priorities.is_card_aoe(card)
            or card_id in self.GENERIC_AOE_IDS
            or card_id == "combust"
        ):
            tags.add("aoe")
        if card_id in FastCombatPlanner.AOE_WEAK_CARDS:
            tags.add("aoe")
        if card_id in FastCombatPlanner.WEAK_CARDS:
            tags.add("weak")
        if card_id in FastCombatPlanner.VULNERABLE_CARDS:
            tags.add("vulnerable")
        if card_id in FastCombatPlanner.POISON_CARDS:
            tags.add("poison")
        if card_id in FastCombatPlanner.STRENGTH_DOWN_CARDS:
            tags.add("strength_down")
        if card_id in FastCombatPlanner.INTANGIBLE_CARDS:
            tags.add("intangible")
        if card_id in self.SCALING_CARD_IDS.get(self.chosen_class, set()):
            tags.add("scaling")
        if getattr(card, "type", None) == spirecomm.spire.card.CardType.POWER:
            tags.add("power")
        if self._card_cost(card) == 0:
            tags.add("zero_cost")
        if bool(getattr(card, "exhausts", False)):
            tags.add("exhausts")
        for archetype, definition in self.ARCHETYPE_DEFINITIONS.get(
            self.chosen_class, {}
        ).items():
            if card_id in definition["sources"]:
                tags.add(f"{archetype}:source")
            if card_id in definition["payoffs"]:
                tags.add(f"{archetype}:payoff")
        return tags

    def _card_block_reliability(self, card):
        """Return the deck-level reliability of a card's block role."""

        block = self._card_number(card, "block", "base_block")
        if block > 0:
            return 1.0
        return float(
            self.CONDITIONAL_BLOCK_RELIABILITY.get(
                self._token(getattr(card, "card_id", "")),
                0.0,
            )
        )

    def _archetype_source_reliability(self, card, archetype, deck=None):
        """Return how reliably one source card enables its archetype."""

        card_id = self._token(getattr(card, "card_id", ""))
        if self.chosen_class == PlayerClass.DEFECT and archetype == "powers":
            # These cards are not equivalent engine sources. Creative AI is
            # random and its generated powers are not searched exactly;
            # Heat Sinks/Storm need other Powers before they do anything.
            return {
                "creativeai": 0.25,
                "heatsinks": 0.35,
                "storm": 0.50,
            }.get(card_id, 1.0)
        if (
            self.chosen_class != PlayerClass.IRONCLAD
            or archetype != "strength"
        ):
            return 1.0
        reliability = self.IRONCLAD_STRENGTH_SOURCE_RELIABILITY.get(
            card_id, 1.0
        )
        upgrades = max(0, int(getattr(card, "upgrades", 0) or 0))
        if card_id == "flex":
            # Flex+ is a stronger burst, but remains temporary and still
            # requires a payoff in the same hand.
            return min(0.3, reliability + upgrades * 0.05)
        if card_id == "rupture":
            deck_cards = list(
                deck
                if deck is not None
                else getattr(self.game, "deck", []) or []
            )
            enablers = sum(
                1
                for deck_card in deck_cards
                if self._token(getattr(deck_card, "card_id", ""))
                in self.IRONCLAD_RUPTURE_ENABLERS
            )
            return min(
                1.1,
                reliability + enablers * 0.25 + upgrades * 0.1,
            )
        return min(1.3, reliability + upgrades * 0.05)

    @staticmethod
    def _archetype_source_support(state):
        return max(
            0.0,
            float(
                state.get(
                    "source_reliability", state.get("sources", 0)
                )
                or 0.0
            )
            + float(state.get("relic_support", 0.0) or 0.0),
        )

    def _draw_plan_value(self, card):
        """Return deck-building draw value, not the raw cards-drawn text.

        A one-card cantrip improves cycling but does not create hand
        advantage. Prepared also discards, so an unupgraded copy is only a
        small filter unless discard payoffs already exist.
        """

        card_id = self._token(getattr(card, "card_id", ""))
        draw = int(FastCombatPlanner.DRAW_COUNTS.get(card_id, 0) or 0)
        upgrades = int(getattr(card, "upgrades", 0) or 0)
        if card_id == "prepared":
            return 0.25 + upgrades * 0.5
        if draw <= 0:
            return 0.0
        if draw == 1:
            return 0.4
        return min(2.0, 0.55 + draw * 0.35)

    def _defense_access_profile(self, cards, roles, energy_relic_support):
        """Estimate drawable/payable defense, not an exact combat forecast.

        Evaluate only the supplied permanent deck so rewards, removals and
        upgrades share the same counterfactual. Reserve one energy for damage
        or setup; do not spend the entire hand's energy on every block card.
        Persistent defenses get bounded first-cycle deployment credit.
        """
        size = max(1, len(cards))
        seen = min(float(size), 5.0 + min(4.0, roles["draw"] * 0.75))
        fraction = seen / size
        energy = 3.0 + max(0.0, energy_relic_support)
        defense_budget = max(1.0, energy - 1.0)
        paid_block = free_block = paid_cost = paid_plays = free_plays = 0.0
        dexterity = 1.0 if self._has_relic("Oddly Smooth Stone") else 0.0
        after_image = frost_channels = focus = conditional_block = 0.0
        deployment = min(1.0, 2.0 * fraction)
        free_seen = fraction * roles["zero_cost"]
        positive_costs = [
            self._card_cost(card) for card in cards if self._card_cost(card) > 0
        ]
        average_paid_cost = sum(positive_costs) / max(1, len(positive_costs))
        plays = min(seen, 6.0, free_seen + energy / max(1.0, average_paid_cost))

        for card in cards:
            card_id = self._token(getattr(card, "card_id", ""))
            cost = self._card_cost(card)
            if cost < 0 or cost > energy:
                # X-cost and otherwise unpayable cards need their explicit
                # mitigation mechanism; never invent a zero-cost block play.
                continue
            setup_access = deployment * min(1.0, defense_budget / max(1, cost))
            if card_id == "footwork":
                dexterity += (2 + int(bool(getattr(card, "upgrades", 0)))) * setup_access
            elif card_id == "afterimage":
                after_image += setup_access * plays
            elif card_id == "defragment":
                focus += (1 + int(bool(getattr(card, "upgrades", 0)))) * setup_access
            # Reuse the combat model's channel semantics, including Glacier's
            # two orbs. Unsupported Focus/slot powers alone produce no Frost.
            channels = self.combat_planner._card_channels(self.game, card, 1)
            frost_channels += channels.count("frost") * setup_access
            base_block = getattr(card, "base_block", None)
            block = (
                max(0, int(base_block))
                if base_block is not None and int(base_block) >= 0
                else self._card_number(card, "block", "base_block")
            )
            if block <= 0:
                conditional_block += (
                    self._card_block_reliability(card) * 8.0 * fraction
                    * min(1.0, defense_budget / max(1, cost))
                )
                continue
            if cost == 0:
                free_block += block * fraction
                free_plays += fraction
            else:
                paid_block += block * fraction
                paid_cost += cost * fraction
                paid_plays += fraction

        pay_fraction = min(1.0, defense_budget / max(0.001, paid_cost))
        direct = free_block + paid_block * pay_fraction
        # Dexterity needs actual block draws; owning Footwork without them
        # cannot certify a defense engine. Discount paid plays consistently.
        dex_block = dexterity * (free_plays + paid_plays * pay_fraction)
        frost_block = min(3.0, frost_channels) * (2.0 + focus)
        persistent = dex_block + after_image + frost_block
        burst_pay_fraction = min(1.0, energy / max(0.001, paid_cost))
        burst = (
            free_block + paid_block * burst_pay_fraction
            + dexterity * (free_plays + paid_plays * burst_pay_fraction)
            + after_image + frost_block + conditional_block
        )
        return {
            "cards_seen_per_turn": round(seen, 3),
            "draw_fraction": round(fraction, 4),
            "available_energy": round(energy, 3),
            "defense_energy_budget": round(defense_budget, 3),
            "drawn_defense_energy": round(paid_cost, 3),
            "pay_fraction": round(pay_fraction, 3),
            "direct_block_per_turn": round(direct, 3),
            "burst_block_per_turn": round(burst, 3),
            "persistent_block_per_turn": round(persistent, 3),
            "dexterity_block": round(dex_block, 3),
            "after_image_block": round(after_image, 3),
            "frost_block": round(frost_block, 3),
            "block_per_turn": round(direct + persistent + conditional_block, 3),
            "semantics": "bounded_draw_and_energy_defense_estimate",
        }

    def _sustained_damage_profile(self, cards, roles, energy_relic_support):
        """Separate recurring output from finite payloads and payoff affinity."""
        recurring = basic = finite = 0.0
        poison_sources = poison_finite = 0.0
        poison_ids = self.ARCHETYPE_DEFINITIONS.get(
            self.chosen_class, {},
        ).get("poison", {}).get("sources", set())
        for card in cards:
            token = self._token(getattr(card, "card_id", ""))
            exhausts = bool(getattr(card, "exhausts", False))
            if "damage" in self._card_build_tags(card):
                if exhausts:
                    finite += 1.0
                elif getattr(card, "rarity", None) == spirecomm.spire.card.CardRarity.BASIC:
                    basic += 1.0
                else:
                    recurring += 1.0
            if token in poison_ids:
                if exhausts:
                    poison_finite += 1.0
                else:
                    poison_sources += 1.0
        defense = self._defense_access_profile(cards, roles, energy_relic_support)
        # Body Slam needs the payoff in hand on the same turn as paid block.
        # Block sources alone say nothing about how often it deals damage.
        slam_access = sum(
            min(1.0, max(0.0, defense["available_energy"]
                         - min(defense["defense_energy_budget"],
                               defense["drawn_defense_energy"]))
                / max(1, self._card_cost(card)))
            for card in cards if self._token(getattr(card, "card_id", "")) == "bodyslam"
        ) * defense["draw_fraction"]
        slam_damage = defense["block_per_turn"] * min(1.0, slam_access)
        counts = {self._token(getattr(card, "card_id", "")) for card in cards}
        retaining_growth = (
            ("barricade" in counts or self._has_relic("Calipers"))
            and "entrench" in counts
        )
        return {
            "repeatable_damage_roles": recurring + basic * 0.25,
            "finite_damage_roles": finite,
            "recurring_poison_sources": poison_sources,
            "finite_poison_sources": poison_finite,
            # A finite poison packet can persist, but Catalyst alone cannot
            # make its source renewable after cleanse or natural decay.
            "poison_scaling_ceiling": min(1.0, poison_sources + poison_finite * 0.35),
            "body_slam_damage_per_turn": round(slam_damage, 3),
            "body_slam_scaling_ceiling": (
                1.0 if retaining_growth else min(1.0, slam_damage / 18.0)
            ),
            "semantics": "finite_payload_and_drawable_payoff_limits",
        }

    def _deck_profile(self, deck=None):
        cards = list(deck if deck is not None else getattr(self.game, "deck", []) or [])
        card_counts = {}
        archetypes = {
            name: {
                "sources": 0,
                "source_reliability": 0.0,
                "payoffs": 0,
                "relic_support": 0.0,
            }
            for name in self.ARCHETYPE_DEFINITIONS.get(self.chosen_class, {})
        }
        roles = {
            "damage": 0,
            "block": 0,
            "draw": 0,
            "energy": 0,
            "aoe": 0,
            "scaling": 0,
            "power": 0,
            "zero_cost": 0,
            "nonbasic_damage": 0,
            "nonbasic_block": 0,
        }
        costs = []
        expensive = 0
        starters = 0
        curses = 0
        upgraded = 0
        for card in cards:
            card_id = self._token(getattr(card, "card_id", ""))
            card_counts[card_id] = card_counts.get(card_id, 0) + 1
            tags = self._card_build_tags(card)
            for role in ("damage", "block", "energy", "aoe", "scaling", "power", "zero_cost"):
                if role in tags:
                    roles[role] += (
                        self._card_block_reliability(card)
                        if role == "block"
                        else 1
                    )
            roles["draw"] += self._draw_plan_value(card)
            if getattr(card, "rarity", None) != spirecomm.spire.card.CardRarity.BASIC:
                roles["nonbasic_damage"] += int("damage" in tags)
                roles["nonbasic_block"] += (
                    self._card_block_reliability(card)
                    if "block" in tags
                    else 0
                )
            for archetype in archetypes:
                is_source = f"{archetype}:source" in tags
                archetypes[archetype]["sources"] += int(is_source)
                if is_source:
                    archetypes[archetype]["source_reliability"] += (
                        self._archetype_source_reliability(
                            card, archetype, cards
                        )
                    )
                archetypes[archetype]["payoffs"] += int(f"{archetype}:payoff" in tags)
            cost = self._card_cost(card)
            if cost >= 0:
                costs.append(cost)
                expensive += int(cost >= 2)
            starters += int(card_id.startswith("strike") or card_id.startswith("defend"))
            curses += int(
                getattr(card, "type", None) == spirecomm.spire.card.CardType.CURSE
                or getattr(card, "rarity", None) == spirecomm.spire.card.CardRarity.CURSE
            )
            upgraded += int(int(getattr(card, "upgrades", 0) or 0) > 0)
        energy_relic_ids = []
        energy_relic_support = 0.0
        for relic in getattr(self.game, "relics", []) or []:
            relic_id = self._token(getattr(relic, "relic_id", ""))
            if relic_id == "hoveringkite":
                reliable_sources = max(
                    0.0,
                    float(
                        archetypes.get("discard", {}).get(
                            "source_reliability", 0.0
                        )
                        or 0.0
                    ),
                )
                cards_seen = min(9.0, 5.0 + 0.5 * roles["draw"])
                relic_energy = 0.9 * min(
                    1.0,
                    cards_seen * reliable_sources / max(1, len(cards)),
                )
            else:
                relic_energy = float(
                    self.ENERGY_RELIC_SUPPORT.get(relic_id, 0.0) or 0.0
                )
            if relic_energy > 0:
                energy_relic_ids.append(
                    getattr(relic, "relic_id", None) or relic_id
                )
                energy_relic_support += relic_energy
            affinity = self.RELIC_ARCHETYPE_AFFINITY.get(
                self.chosen_class, {}
            ).get(relic_id)
            if affinity is not None and affinity[0] in archetypes:
                archetypes[affinity[0]]["relic_support"] += affinity[1] / 6.0
        roles["energy"] += energy_relic_support
        for state in archetypes.values():
            reliable_sources = max(
                0.0, float(state["source_reliability"] or 0.0)
            )
            paired_support = reliable_sources + state["relic_support"]
            state["signal"] = (
                reliable_sources
                + state["payoffs"] * 1.2
                + min(paired_support, state["payoffs"]) * 1.8
                + state["relic_support"] * 1.25
            )
        return {
            "size": len(cards),
            "roles": roles,
            "archetypes": archetypes,
            "early_offense_readiness": round(
                self._act1_elite_readiness(cards), 3
            ),
            "average_cost": sum(costs) / max(1, len(costs)),
            "expensive": expensive,
            "starters": starters,
            "curses": curses,
            "upgraded": upgraded,
            "energy_relic_support": round(energy_relic_support, 3),
            "energy_relic_ids": energy_relic_ids,
            "damage_engine_access": self._damage_engine_access(cards, roles, energy_relic_support),
            "sustained_damage": self._sustained_damage_profile(cards, roles, energy_relic_support),
            "card_counts": card_counts,
            "strength_capacity": (self._strength_capacity(cards)
                                  if self.chosen_class == PlayerClass.IRONCLAD else None),
            "defense_access": self._defense_access_profile(
                cards, roles, energy_relic_support
            ),
        }

    def _damage_engine_access(self, cards, roles, energy_relic_support):
        """Estimate early source access, not future draw order or win odds.

        The three-turn window measures how long a source is online during
        setup. Draw counts are estimates; sampling within those counts is
        without replacement. Reserve one energy for defense when installing
        a Power, as the defense model reserves one for offense/setup.
        """
        size = len(cards)
        if not size:
            return {}
        seen_per_turn = 5.0 + min(4.0, max(0.0, roles["draw"]) * 0.75)
        energy = 3.0 + max(0.0, energy_relic_support)
        opening_bonus = 2 * int(self._has_relic("Bag of Preparation"))
        opening_bonus += 2 * int(self._has_relic("Ring of the Snake"))
        definitions = self.ARCHETYPE_DEFINITIONS.get(self.chosen_class, {})
        groups = {}
        delayed = {"demonform", "echoform", "noxiousfumes", "infiniteblades"}
        strength = self._strength_capacity(cards) if self.chosen_class == PlayerClass.IRONCLAD else {}

        for card in cards:
            card_id = self._token(getattr(card, "card_id", ""))
            cost = self._card_cost(card)
            # Unknown/X costs have no guaranteed setup payment.
            payable = 0.0 if cost < 0 or cost > energy else 1.0
            if getattr(card, "type", None) == spirecomm.spire.card.CardType.POWER:
                payable *= min(1.0, max(0.0, energy - 1.0) / max(1, cost))
            bottled = any(getattr(card, key, False) for key in (
                "in_bottle_flame", "in_bottle_lightning", "in_bottle_tornado",
            ))
            entry = (payable, card_id in delayed, bottled)
            if card_id in {"demonform", "echoform", "inflame", "spotweakness", "noxiousfumes"}:
                groups.setdefault(card_id, []).append(entry)
            for name, definition in definitions.items():
                if card_id not in definition["sources"] or card_id == "flex":
                    continue
                if card_id == "rupture" and not any(
                    self._token(getattr(other, "card_id", "")) in self.IRONCLAD_RUPTURE_ENABLERS
                    for other in cards
                ):
                    continue
                groups.setdefault("engine:" + name, []).append(entry)
            if card_id == "limitbreak" and strength.get("repeatable_multiplier") and int(getattr(card, "upgrades", 0) or 0):
                groups.setdefault("engine:strength", []).append(entry)

        def miss(population, excluded, draws):
            if draws > population - excluded:
                return 0.0
            return math.comb(population - excluded, draws) / math.comb(population, draws)

        result = {}
        for name, entries in groups.items():
            levels = sorted({quality for quality, _, _ in entries if quality > 0})
            by_turn = []
            for turn in (1, 2, 3):
                current = min(size, int(opening_bonus + seen_per_turn * turn))
                previous = min(size, int(opening_bonus + seen_per_turn * (turn - 1))) if turn > 1 else 0
                value = last = 0.0
                for quality in levels:
                    eligible = [e for e in entries if e[0] >= quality]
                    if any(bottled and (not delay or turn > 1) for _, delay, bottled in eligible):
                        probability = 1.0
                    else:
                        immediate = sum(not delay for _, delay, _ in eligible)
                        late = sum(delay for _, delay, _ in eligible)
                        # No immediate source in the current prefix, and no
                        # delayed source in its previous-turn sub-prefix.
                        probability = 1.0 - (
                            miss(size, immediate, current)
                            * miss(size - immediate, late, min(previous, size - immediate))
                        )
                    value += (quality - last) * probability
                    last = quality
                by_turn.append(round(value, 4))
            result[name] = {
                "online_by_turn": by_turn,
                "early_online_fraction": round(sum(by_turn) / 3.0, 4),
                "source_copies": len(entries),
                "available_energy": round(energy, 3),
                "cards_seen_per_turn": round(seen_per_turn, 3),
                "semantics": "estimated_three_turn_source_access_with_setup_reserve",
            }
        return result

    def _strength_capacity(self, cards):
        """Keep archetype affinity separate from sustained damage evidence."""
        sources = self.ARCHETYPE_DEFINITIONS[PlayerClass.IRONCLAD]["strength"]["sources"]
        persistent = sum(
            self._archetype_source_reliability(card, "strength", cards)
            for card in cards
            if self._token(getattr(card, "card_id", "")) in sources - {"flex"}
            and (
                self._token(getattr(card, "card_id", "")) != "rupture"
                or any(self._token(getattr(other, "card_id", ""))
                       in self.IRONCLAD_RUPTURE_ENABLERS for other in cards)
            )
        )
        relics = {self._token(getattr(relic, "relic_id", "")): relic
                  for relic in getattr(self.game, "relics", []) or []}
        hp = getattr(self.game, "current_hp", 0) or 0
        max_hp = getattr(self.game, "max_hp", 0) or 0
        fixed = int("vajra" in relics)
        skull_active = "redskull" in relics and max_hp > 0 and hp <= max_hp / 2
        fixed += 3 * int(skull_active)
        if "girya" in relics:
            fixed += max(0, int(getattr(relics["girya"], "counter", 0) or 0))
        # Limit Break+ turns a permanent seed into repeatable growth; Flex
        # alone still requires a same-hand combo and cannot supply that seed.
        repeatable_multiplier = fixed > 0 and any(
            self._token(getattr(card, "card_id", "")) == "limitbreak"
            and int(getattr(card, "upgrades", 0) or 0) > 0
            for card in cards
        )
        # Fixed Strength helps ordinary damage but must not satisfy a full
        # growth requirement by crossing an archetype-affinity threshold.
        coverage = max(min(1.0, persistent / 0.85),
                       min(0.4, fixed * 0.1), float(repeatable_multiplier))
        return {
            "coverage": round(coverage, 3),
            "persistent_source_support": round(persistent, 3),
            "fixed_strength": fixed,
            "red_skull_active": skull_active,
            "repeatable_multiplier": repeatable_multiplier,
        }

    def _scaling_mechanism_support(self, profile):
        """Require a real engine behind a generic ``scaling`` card tag.

        A payoff is not an engine by itself: Heavy Blade without Strength and
        Capacitor/Loop without a repeatable orb source must not satisfy a boss
        scaling check. Conversely, genuinely self-contained powers such as
        Demon Form or Noxious Fumes retain bounded standalone credit. This is
        intentionally a deck-level gate, not a second combat simulator.
        """

        roles = profile.get("roles") or {}
        raw = max(0.0, float(roles.get("scaling", 0.0) or 0.0))
        archetypes = profile.get("archetypes")
        if not isinstance(archetypes, dict):
            # Synthetic/legacy profiles used by diagnostics predate engine
            # facts. Preserve their explicit scaling input, but identify the
            # fallback so live model context never mistakes it for evidence.
            return {
                "coverage": min(1.0, raw),
                "raw_tag_count": round(raw, 3),
                "evidence": "legacy_role_fallback",
                "paired_engines": {},
                "standalone": {},
            }

        counts = profile.get("card_counts") or {}
        paired = {}
        intrinsic_damage_sources = {}
        for name, state in archetypes.items():
            source_support = self._archetype_source_support(state)
            payoffs = max(0.0, float(state.get("payoffs", 0.0) or 0.0))
            if self.chosen_class == PlayerClass.IRONCLAD and name == "strength":
                # Permanent/repeatable Strength improves every ordinary
                # Attack, so it does not require a named multi-hit payoff.
                strength_source = (
                    min(1.0, source_support / 0.85)
                    if source_support >= 0.85
                    else 0.0
                )
                payoff_bonus = (
                    min(0.15, payoffs * 0.05)
                    if strength_source > 0
                    else 0.0
                )
                capacity = profile.get("strength_capacity")
                value = (
                    float(capacity["coverage"])
                    if isinstance(capacity, dict)
                    else min(1.0, strength_source + payoff_bonus)
                )
            else:
                # One starter Zap plus one Capacitor is not a stable orb
                # engine. Dark is less source-hungry because one Dark orb can
                # be deliberately grown and evoked; other engines need more
                # than a single weak source before their payoff is reliable.
                source_targets = {
                    PlayerClass.IRONCLAD: {
                        "exhaust": 1.0,
                        "block": 1.5,
                        "status": 1.5,
                    },
                    PlayerClass.THE_SILENT: {
                        "poison": 1.0,
                        "shiv": 1.0,
                        "discard": 1.5,
                    },
                    PlayerClass.DEFECT: {
                        "frost": 1.5,
                        "lightning": 1.5,
                        "dark": 1.0,
                        "zero_cost": 1.5,
                        "powers": 1.0,
                    },
                }
                source_target = source_targets.get(
                    self.chosen_class, {}
                ).get(name, 1.5)
                source_ready = source_support >= source_target
                if self.chosen_class == PlayerClass.DEFECT and name == "powers":
                    # Expensive generation is discounted by source reliability,
                    # but a real generator can still support a partial engine.
                    source_ready = source_support > 0.0
                if (
                    self.chosen_class == PlayerClass.DEFECT
                    and name in {"frost", "lightning"}
                ):
                    actual_sources = max(
                        0.0,
                        float(state.get("source_reliability", 0.0) or 0.0),
                    )
                    focus_support = any(
                        int(counts.get(card_id, 0) or 0) > 0
                        for card_id in (
                            "defragment", "consume", "biasedcognition"
                        )
                    )
                    # Cracked Core plus the starter Zap is opening state, not
                    # a repeatable channel engine. Require either two real
                    # sources or Focus paired with at least one real source.
                    source_ready = (
                        actual_sources >= 1.5
                        or (actual_sources >= 1.0 and focus_support)
                    )
                value = (
                    min(1.0, source_support / source_target, payoffs)
                    if source_ready and payoffs >= 1.0
                    else 0.0
                )
                if name == "poison" and float(
                    state.get("source_reliability", 0.0) or 0.0
                ) > 0:
                    intrinsic_damage_sources[name] = min(0.6, source_support * 0.45)
                    value = max(value, intrinsic_damage_sources[name])
                elif name == "dark" and source_ready and any(
                    counts.get(card_id, 0) for card_id in
                    ("dualcast", "multicast", "recursion")
                ):
                    # Starter Dualcast can cash out a grown Dark orb; a
                    # special payoff is helpful but is not a prerequisite.
                    intrinsic_damage_sources[name] = 0.5
                    value = max(value, intrinsic_damage_sources[name])
            if "card_counts" in profile:
                definition = self.ARCHETYPE_DEFINITIONS.get(
                    self.chosen_class, {}
                ).get(name, {})
                engine_cards = (
                    set(definition.get("sources", ()))
                    | set(definition.get("payoffs", ()))
                )
                scaling_cards = self.SCALING_CARD_IDS.get(self.chosen_class, set())
                # A scaling tag belongs to its own mechanism, not whichever
                # unrelated source/payoff pair happens to be present.
                engine_scaling = sum(
                    int(counts.get(card_id, 0) or 0)
                    for card_id in engine_cards & scaling_cards
                )
                value = min(value, float(engine_scaling))
            else:
                value = min(value, raw)
            if value > 0:
                paired[name] = round(value, 3)

        standalone = {}

        def grant(card_id, value):
            if int(counts.get(card_id, 0) or 0) > 0:
                standalone[card_id] = max(
                    float(standalone.get(card_id, 0.0) or 0.0), value
                )

        if self.chosen_class == PlayerClass.IRONCLAD:
            grant("demonform", 1.0)
            grant("inflame", 0.8)
            grant("spotweakness", 0.75)
            # Barricade needs actual block production; the block archetype
            # pair above owns that evidence rather than the card name alone.
        elif self.chosen_class == PlayerClass.THE_SILENT:
            grant("noxiousfumes", 0.9)
            grant("footwork", 0.75)
            grant("wraithformv2", 0.85)
            grant("wraithform", 0.85)
        elif self.chosen_class == PlayerClass.DEFECT:
            grant("echoform", 1.0)
            # Biased Cognition needs at least one real orb family. Artifact
            # improves duration but is not required for short boss windows.
            if any(
                self._archetype_source_support(archetypes.get(name, {})) >= 1.0
                for name in ("frost", "lightning", "dark")
            ):
                grant("biasedcognition", 0.8)

        mechanism = max(
            [0.0, *paired.values(), *standalone.values()]
        )
        return {
            # Attribute coverage to the actual mechanism. A generic scaling
            # tag must not switch an unrelated, already-present engine on.
            "coverage": round(min(1.0, max(
                [mechanism, *intrinsic_damage_sources.values()]
            )), 3),
            "raw_tag_count": round(raw, 3),
            "evidence": "mechanism_chain",
            "intrinsic_damage_sources": intrinsic_damage_sources,
            "paired_engines": paired,
            "standalone": {
                key: round(value, 3) for key, value in standalone.items()
            },
        }

    def _defense_mechanism_support(self, profile):
        """Return non-Block mitigation as explicit defensive capacity.

        Intangible, Buffer and Strength-down are not fixed Block numbers, so
        they stay visible as mechanism evidence. Readiness converts them only
        into a bounded equivalent alongside real non-basic Block; combat
        simulation remains authoritative for exact mitigation.
        """

        counts = profile.get("card_counts") or {}
        weights = {
            "wraithform": 1.8,
            "wraithformv2": 1.8,
            "apparition": 0.8,
            # CommunicationMod serializes the live event card as Ghostly,
            # while fixtures and historical traces may use Apparition.
            "ghostly": 0.8,
            "buffer": 0.8,
            "piercingwail": 0.7,
            "malaise": 0.75,
            "disarm": 0.7,
            "shockwave": 0.45,
        }
        evidence = {
            card_id: {
                "copies": int(counts.get(card_id, 0) or 0),
                "equivalent_per_copy": weight,
            }
            for card_id, weight in weights.items()
            if int(counts.get(card_id, 0) or 0) > 0
        }
        equivalent = sum(
            item["copies"] * item["equivalent_per_copy"]
            for item in evidence.values()
        )
        return {
            "equivalent_block_roles": round(min(2.5, equivalent), 3),
            "evidence": evidence,
            "semantics": "bounded_non_block_mitigation_estimate",
        }

    def _damage_scaling_support(self, profile):
        """Do not mistake defensive scaling for an engine that ends fights."""
        mechanism = self._scaling_mechanism_support(profile)
        if mechanism.get("evidence") == "legacy_role_fallback":
            return float(mechanism["coverage"])
        counts = profile.get("card_counts") or {}
        paired = dict(mechanism.get("paired_engines") or {})
        sustained = profile.get("sustained_damage") or {}
        if "poison_scaling_ceiling" in sustained:
            paired["poison"] = min(
                paired.get("poison", 0.0), sustained["poison_scaling_ceiling"],
            )
        access = profile.get("damage_engine_access") or {}

        def accessible(name, value):
            detail = access.get(name)
            return value * float(detail["early_online_fraction"]) if detail else value

        sources = [accessible("engine:" + name, paired.get(name, 0.0)) for name in (
            "strength", "poison", "shiv", "lightning", "dark",
        )]
        capacity = profile.get("strength_capacity") or {}
        # A relic's fixed Strength is available without drawing a setup card.
        sources.append(min(0.4, float(capacity.get("fixed_strength", 0)) * 0.1))
        standalone = mechanism.get("standalone") or {}
        sources.extend(accessible(name, standalone.get(name, 0.0)) for name in (
            "demonform", "inflame", "spotweakness", "noxiousfumes",
        ))
        for card_id, engine in (
            ("firebreathing", "status"), ("bodyslam", "block"),
            ("claw", "zero_cost"),
        ):
            if counts.get(card_id):
                value = paired.get(engine, 0.0)
                if card_id == "bodyslam" and "body_slam_scaling_ceiling" in sustained:
                    value = min(value, sustained["body_slam_scaling_ceiling"])
                sources.append(accessible("engine:" + engine, value))
        damage_support = max([0.0, *sources])
        if counts.get("echoform") and damage_support > 0:
            damage_support = min(1.0, damage_support + accessible("echoform", 0.15))
        return min(1.0, damage_support)

    def _long_fight_kill_clock(self, profile, *, scaling_coverage=None):
        """Estimate whether defense is backed by repeatable fight progress.

        Defense and Intangible can make a deck look complete even when it has
        no way to end an attrition fight before enemy scaling overtakes it.
        Exact combat search remains responsible for individual turns.
        """

        roles = profile.get("roles") or {}
        deck_size = max(1, int(profile.get("size", 0) or 0))
        # Generic readiness coverage is an upper bound, not evidence that
        # Frost/Footwork/Wraith Form provide recurring damage.
        damage_scaling = self._damage_scaling_support(profile)
        scaling_coverage = (
            damage_scaling if scaling_coverage is None
            else min(float(scaling_coverage), damage_scaling)
        )
        scaling_coverage = max(
            0.0, min(1.0, float(scaling_coverage or 0.0))
        )
        nonbasic_damage = max(
            0.0, float(roles.get("nonbasic_damage", 0.0) or 0.0)
        )
        all_damage = max(
            nonbasic_damage,
            float(roles.get("damage", nonbasic_damage) or 0.0),
        )
        repeatable_damage_roles = (
            nonbasic_damage + 0.25 * max(0.0, all_damage - nonbasic_damage)
        )
        sustained = profile.get("sustained_damage") or {}
        repeatable_damage_roles = float(sustained.get(
            "repeatable_damage_roles", repeatable_damage_roles,
        ))
        repeatable_target = max(2.5, deck_size * 0.18)
        repeatable_coverage = min(
            1.0, repeatable_damage_roles / repeatable_target
        )
        draw_support = max(
            0.0, float(roles.get("draw", 0.0) or 0.0)
        )
        cards_seen_per_turn = 5.0 + min(4.0, draw_support * 0.75)
        cycle_turns = deck_size / max(1.0, cards_seen_per_turn)
        access_coverage = min(1.0, 2.25 / max(1.0, cycle_turns))
        score = (
            0.62 * scaling_coverage
            + 0.23 * repeatable_coverage
            + 0.15 * access_coverage
        )
        return {
            "score": round(max(0.0, min(1.0, score)), 3),
            "engine_access": profile.get("damage_engine_access", {}),
            "sustained_damage": sustained,
            "scaling_coverage": round(scaling_coverage, 3),
            "repeatable_damage_coverage": round(
                repeatable_coverage, 3
            ),
            "access_coverage": round(access_coverage, 3),
            "estimated_cycle_turns": round(cycle_turns, 3),
            "semantics": "repeatable_progress_before_enemy_scaling",
        }

    def _deck_plan_summary(self, profile=None):
        profile = profile or self._deck_profile()
        ranked = sorted(
            profile["archetypes"].items(),
            key=lambda item: item[1]["signal"],
            reverse=True,
        )
        primary_name = "balanced"
        confidence = 0.0
        supported = [
            item
            for item in ranked
            if item[1]["signal"] >= 3.0
            and self._archetype_source_support(item[1]) >= 0.75
        ]
        if supported:
            primary_name = supported[0][0]
            confidence = min(1.0, supported[0][1]["signal"] / 8.0)

        primary_state = profile["archetypes"].get(primary_name, {})
        primary_support = self._archetype_source_support(primary_state)
        second_signal = (
            ranked[1][1]["signal"]
            if len(ranked) > 1 and primary_name != "balanced"
            else 0.0
        )
        signal_margin = max(
            0.0,
            float(primary_state.get("signal", 0.0) or 0.0)
            - float(second_signal or 0.0),
        )
        payoff_count = int(primary_state.get("payoffs", 0) or 0)
        if (
            primary_name == "balanced"
            or confidence <= 0.0
            or primary_support < 0.75
        ):
            commitment_phase = "explore"
            commitment_level = self.ARCHETYPE_COMMITMENT_LEVELS["explore"]
        elif (
            payoff_count >= 1
            and primary_support >= 1.5
            and signal_margin >= 1.0
            and float(primary_state.get("signal", 0.0) or 0.0) >= 5.5
        ):
            commitment_phase = "firm"
            commitment_level = self.ARCHETYPE_COMMITMENT_LEVELS["firm"]
        else:
            # A source-only plan remains intentionally soft: it can guide
            # card selection, but it must not reject a better universal answer
            # or force a speculative payoff.
            commitment_phase = "soft"
            commitment_level = self.ARCHETYPE_COMMITMENT_LEVELS["soft"]

        roles = profile["roles"]
        act = int(getattr(self.game, "act", 0) or 0)
        floor = int(getattr(self.game, "floor", 0) or 0)
        readiness = self._deck_readiness(profile)
        readiness_coverage = readiness.get("coverage") or {}
        needs = []
        if roles["nonbasic_damage"] < 2:
            needs.append("frontload")
        if float(readiness_coverage.get("block", 0.0) or 0.0) < 1.0:
            needs.append("block")
        if roles["draw"] < 1.5:
            needs.append("draw")
        if roles["aoe"] < 1 and act <= 2:
            needs.append("aoe")
        if (
            float(readiness_coverage.get("scaling", 0.0) or 0.0) < 1.0
            and (act >= 2 or floor >= 7)
        ):
            needs.append("scaling")
        if profile["expensive"] >= 3 and roles["energy"] < 1:
            needs.append("energy")
        if profile["size"] >= 24:
            needs.append("trim")
        boss_readiness = self._boss_entry_readiness(profile)
        boss_needs = [
            role
            for role, gap in (boss_readiness.get("gaps") or {}).items()
            if float(gap or 0.0) > 0.05
        ]
        return {
            "primary": primary_name,
            "confidence": round(confidence, 3),
            "commitment": {
                "phase": commitment_phase,
                "level": commitment_level,
                "signal_margin": round(signal_margin, 3),
                "source_support": round(primary_support, 3),
            },
            "needs": needs,
            # Keep general act coverage separate from the immediate boss
            # check.  A generic Act 1 AOE gap must not become the false claim
            # that single-target Hexaghost or Guardian has minions.
            "need_horizons": {
                "general_act": list(needs),
                "act_boss": boss_needs,
            },
            "demand": self._deck_demand_vector(profile),
            "readiness": readiness,
            "boss_readiness": boss_readiness,
            "roles": dict(roles),
            "archetypes": {
                name: {
                    "sources": state["sources"],
                    "source_reliability": round(
                        state["source_reliability"], 3
                    ),
                    "payoffs": state["payoffs"],
                    "relic_support": round(state["relic_support"], 3),
                    "signal": round(state["signal"], 3),
                }
                for name, state in ranked
                if state["sources"] or state["payoffs"] or state["relic_support"]
            },
        }

    def _deck_readiness(self, profile=None):
        """Return a bounded, counterfactual-friendly deck readiness vector.

        Raw card counts are useful diagnostics but are not enough to predict
        Act 2/3 survival.  This vector keeps the evaluator cheap while
        measuring the universal resources that every committed archetype still
        needs: front-loaded damage, block, draw, scaling, energy and AOE.
        """

        profile = profile or self._deck_profile()
        roles = profile["roles"]
        act = max(1, int(getattr(self.game, "act", 1) or 1))
        floor = int(getattr(self.game, "floor", 0) or 0)
        boss_id = self._boss_id()

        targets = {
            "frontload": 2.0 if act == 1 else 2.5,
            "block": 2.0 + min(1.0, (act - 1) * 0.5),
            "draw": 1.5,
            "scaling": 0.5 if act == 1 and floor < 7 else 1.0,
            "energy": 1.0 if profile["expensive"] >= 3 else 0.0,
            "aoe": 1.0 if act <= 2 else 0.8,
        }
        weights = {
            "frontload": 1.15,
            "block": 1.25,
            "draw": 1.15,
            "scaling": 1.15 if act >= 2 else 0.75,
            "energy": 0.9,
            "aoe": 0.8,
        }
        if boss_id in {
            "champ", "automaton", "collector", "donuanddeca",
            "timeeater", "awakenedone",
        }:
            weights["block"] += 0.15
            weights["scaling"] += 0.15
        if boss_id == "slimeboss":
            weights["frontload"] += 0.25
            weights["aoe"] += 0.15

        coverage = {}
        gaps = {}
        weighted_gap = 0.0
        total_weight = 0.0
        scaling_mechanism = self._scaling_mechanism_support(profile)
        defense_mechanism = self._defense_mechanism_support(profile)
        kill_clock = self._long_fight_kill_clock(
            profile, scaling_coverage=scaling_mechanism["coverage"]
        )
        role_values = {
            "frontload": roles["nonbasic_damage"],
            "block": (
                roles["nonbasic_block"]
                + defense_mechanism["equivalent_block_roles"]
            ),
            "draw": roles["draw"],
            "scaling": scaling_mechanism["coverage"],
            "energy": roles["energy"],
            "aoe": roles["aoe"],
        }
        defense_access = profile.get("defense_access")
        defense_coverage_limit = 1.0
        if isinstance(defense_access, dict):
            # Preserve legacy synthetic profiles while applying the measured
            # ceiling to real decks. Three nominal block cards in a thick deck
            # must not erase the marginal value of a drawable defense reward.
            block_target = 12.0 + 6.0 * min(3, act - 1)
            mechanism_coverage = (
                defense_mechanism["equivalent_block_roles"] / targets["block"]
                * min(1.0, 2.0 * defense_access["draw_fraction"])
            )
            defense_coverage_limit = min(
                1.0, defense_access["block_per_turn"] / block_target
                + mechanism_coverage,
            )
            role_values["block"] += defense_access["persistent_block_per_turn"] / 8.0
        for role, target in targets.items():
            weight = weights[role]
            total_weight += weight
            if target <= 0:
                coverage[role] = 1.0
                gaps[role] = 0.0
                continue
            value = max(0.0, float(role_values[role] or 0.0))
            covered = max(0.0, min(1.0, value / target))
            if role == "block":
                covered = min(covered, defense_coverage_limit)
            coverage[role] = round(covered, 3)
            gaps[role] = round(max(0.0, 1.0 - covered), 3)
            weighted_gap += (1.0 - covered) * weight
        score = 1.0 - weighted_gap / max(0.001, total_weight)
        raw_score = max(0.0, min(1.0, score))
        deck_size = max(1, int(profile.get("size", 0) or 0))
        # Counts alone saturate quickly.  Estimate how many turns are needed
        # to see the deck, then discount large/basic-heavy/energy-strained
        # decks whose nominal answers are not consistently drawable.  This
        # is deliberately bounded: it calibrates readiness and route greed,
        # without pretending to replace combat simulation.
        effective_cards_seen = 5.0 + min(
            4.0, max(0.0, float(roles.get("draw", 0.0) or 0.0)) * 0.75
        )
        cycle_turns = deck_size / max(1.0, effective_cards_seen)
        access_score = min(1.0, 2.25 / max(1.0, cycle_turns))
        starter_drag = min(
            0.30,
            (
                max(0, int(profile.get("starters", 0) or 0))
                + 2 * max(0, int(profile.get("curses", 0) or 0))
            )
            / deck_size
            * 0.45,
        )
        upgrade_support = min(
            0.12,
            max(0, int(profile.get("upgraded", 0) or 0))
            / deck_size
            * 0.25,
        )
        uncovered_expensive = max(
            0.0,
            float(profile.get("expensive", 0) or 0)
            - 3.0
            - 2.0 * float(profile.get("energy_relic_support", 0.0) or 0.0),
        )
        energy_strain = min(0.18, uncovered_expensive / deck_size * 0.9)
        consistency = max(
            0.25,
            min(
                1.0,
                access_score - starter_drag + upgrade_support - energy_strain,
            ),
        )
        required_coverages = {
            role: float(coverage.get(role, 0.0) or 0.0)
            for role, target in targets.items()
            if float(target or 0.0) > 0.0
        }
        bottleneck_role, bottleneck_coverage = min(
            required_coverages.items(),
            key=lambda item: (item[1], item[0]),
            default=(None, 1.0),
        )
        # A weighted average can call a deck "ready" while one universal
        # requirement is still absent.  Historical losing decks saturated
        # the old count score with several engine cards even though their
        # block/draw throughput was a single-card bottleneck.  Calibrate with
        # both access consistency and the weakest required role; retain a
        # bounded floor because this is route guidance, not a combat oracle.
        calibration = (
            0.45
            + 0.30 * consistency
            + 0.25 * bottleneck_coverage
        )
        kill_clock_factor = (
            1.0
            if act == 1
            else 0.72 + 0.28 * float(kill_clock["score"])
        )
        calibrated_score = raw_score * calibration * kill_clock_factor
        return {
            "score": round(max(0.0, min(1.0, calibrated_score)), 3),
            "raw_role_score": round(raw_score, 3),
            "consistency": round(consistency, 3),
            "bottleneck_role": bottleneck_role,
            "bottleneck_coverage": round(bottleneck_coverage, 3),
            "estimated_cycle_turns": round(cycle_turns, 3),
            "starter_curse_drag": round(starter_drag, 3),
            "energy_strain": round(energy_strain, 3),
            "kill_clock_factor": round(kill_clock_factor, 3),
            "kill_clock": kill_clock,
            "scaling_mechanism": scaling_mechanism,
            "defense_mechanism": defense_mechanism,
            "defense_access": defense_access,
            "defense_coverage_limit": round(defense_coverage_limit, 3),
            "coverage": coverage,
            "gaps": gaps,
            "targets": targets,
        }

    def _boss_entry_readiness(self, profile=None, projected_hp=None):
        """Project whether the current deck can meet this act boss's checks.

        Route scoring used to treat every Act 2/3 elite and boss as a generic
        HP tax.  The same HP can be perfectly healthy for Slime Boss but leave
        a low-scaling deck unable to survive Time Eater or Awakened One.  Keep
        this projection small and deterministic so it can be used by both map
        search and campfire scoring without a model request.
        """

        profile_was_supplied = profile is not None
        profile = profile or self._deck_profile()
        readiness = self._deck_readiness(profile)
        coverage = readiness.get("coverage", {})
        consistency = max(
            0.25,
            min(1.0, float(readiness.get("consistency", 1.0) or 0.0)),
        )
        boss_id = self._boss_id()
        split_clock = None
        early_offense = None
        requirements = {
            "frontload": 0.45,
            "block": 0.50,
            "scaling": 0.40,
        }
        if boss_id == "slimeboss":
            # Slime Boss is a three-turn split race, not a long-fight engine
            # check.  Generic scaling let Barricade/Evolve/After Image-like
            # setup saturate this requirement even when the deck could not
            # push a useful split.  Combine the existing quality-weighted
            # Act-1 offense measure with draw consistency so neither raw
            # attack count nor a slow engine can hide the short clock.
            requirements.pop("scaling", None)
            profile_early_offense = profile.get("early_offense_readiness")
            if isinstance(profile_early_offense, (int, float)):
                early_offense = max(
                    0.0, min(1.0, float(profile_early_offense))
                )
            elif profile_was_supplied:
                # A projected/synthetic profile without this card-derived
                # field cannot borrow the live deck's short-clock value.
                early_offense = 0.0
            else:
                early_offense = self._act1_elite_readiness()
            split_clock = math.sqrt(early_offense * consistency)
            requirements.update({
                "frontload": 0.68,
                "aoe": 0.35,
                "block": 0.35,
                "split_clock": 1.0,
            })
        elif boss_id == "hexaghost":
            requirements.update({
                "frontload": 0.50,
                "block": 0.58,
                "scaling": 0.30,
            })
        elif boss_id in {
            "champ", "collector", "automaton", "donuanddeca",
            "timeeater", "awakenedone",
        }:
            requirements.update({
                "frontload": 0.50,
                "block": 0.62,
                "draw": 0.38,
                "scaling": 0.58,
                "kill_clock": 0.62,
            })
        elif boss_id == "heart":
            # Multi-hit attacks and Beat of Death demand repeatable defense.
            # The damage cap also makes a sustained kill clock essential:
            # merely surviving setup or owning one burst is not readiness.
            requirements.update({
                "block": 0.75,
                "draw": 0.50,
                "scaling": 0.70,
                "kill_clock": 0.70,
            })
        # Act 1 is allowed to enter a boss with a still-developing plan.  The
        # projection remains visible for diagnostics, but the hard route gate
        # only starts at Act 2.
        weighted = 0.0
        total_weight = 0.0
        gaps = {}
        requirement_ratios = {}
        for role, required in requirements.items():
            actual_value = (
                (readiness.get("kill_clock") or {}).get("score", 0.0)
                if role == "kill_clock"
                else split_clock
                if role == "split_clock"
                else coverage.get(role, 0.0)
            )
            actual = max(0.0, min(1.0, float(actual_value or 0.0)))
            gap = max(0.0, required - actual)
            requirement_ratios[role] = min(
                1.0, actual / max(required, 0.01)
            )
            weight = (
                1.35
                if role in {
                    "block", "scaling", "kill_clock", "split_clock",
                }
                else 1.0
            )
            weighted += max(0.0, 1.0 - gap / max(required, 0.01)) * weight
            total_weight += weight
            gaps[role] = round(gap, 3)
        role_score = weighted / max(total_weight, 0.001)
        bottleneck_role, bottleneck_ratio = min(
            requirement_ratios.items(),
            key=lambda item: (item[1], item[0]),
            default=(None, 1.0),
        )
        # The geometric term prevents a high average from hiding one missing
        # boss answer and also prices how often the answers can be drawn.
        player = getattr(self.game, "player", None)
        hp_source = (
            projected_hp
            if projected_hp is not None
            else (
                getattr(self.game, "current_hp", 0)
                or getattr(player, "current_hp", 0)
                or 0
            )
        )
        hp = max(0, int(hp_source or 0))
        max_hp = max(
            1,
            int(
                getattr(self.game, "max_hp", 0)
                or getattr(player, "max_hp", 0)
                or max(1, hp)
            ),
        )
        hp_ratio = min(1.0, hp / max_hp)
        act = max(1, int(getattr(self.game, "act", 1) or 1))
        hp_target = 0.50 if act == 1 else 0.60 if act == 2 else 0.68
        if boss_id == "hexaghost":
            # Resting higher can increase Divider, but entering at critically
            # low absolute health is still not boss-ready.
            hp_target = 0.45
        elif boss_id in {"timeeater", "awakenedone"}:
            hp_target = 0.70
        elif boss_id == "heart":
            hp_target = 0.80
        try:
            real_potions = list(self.game.get_real_potions())
        except (AttributeError, TypeError):
            real_potions = [
                item
                for item in getattr(self.game, "potions", []) or []
                if self._token(getattr(item, "potion_id", ""))
                not in {"", "potion slot", "potionslot"}
            ]
        potion_count = len(real_potions)
        potion_credit_rows = []
        for potion in real_potions:
            potion_id = self._token(getattr(potion, "potion_id", ""))
            if potion_id in {
                "fairyinabottle", "fairypotion", "fairy", "ghostinajar",
            }:
                credit = 0.08
            elif potion_id in {
                "blockpotion", "dexteritypotion", "weakpotion",
                "speedpotion", "essenceofsteel",
            }:
                credit = 0.05
            elif potion_id in {
                "energypotion", "ancientpotion", "focuspotion",
                "potionofcapacity", "essenceofdarkness",
                "bloodpotion", "regenpotion",
            }:
                credit = 0.035
            elif potion_id in {
                "gamblersbrew", "distilledchaos", "skillpotion",
                "attackpotion", "powerpotion", "colorlesspotion",
                "entropicbrew",
            }:
                credit = 0.02
            elif potion_id in {"smokebomb", "elixir"}:
                credit = 0.0
            else:
                # Pure damage/stat potions can shorten a fight but are not
                # interchangeable with direct survival or revival.
                credit = 0.015
            potion_credit_rows.append({
                "potion_id": potion_id,
                "survival_credit": round(credit, 3),
            })
        potion_credit = min(
            0.12,
            sum(row["survival_credit"] for row in potion_credit_rows),
        )
        survival_ratio = min(
            1.0, (hp_ratio + potion_credit) / max(0.01, hp_target)
        )

        boss_factor = 1.0
        boss_constraints = {}
        if split_clock is not None:
            boss_constraints["split_clock"] = {
                "early_offense": round(early_offense, 3),
                "consistency": round(consistency, 3),
                "score": round(split_clock, 3),
            }
        power_count = max(
            0.0, float((profile.get("roles") or {}).get("power", 0.0) or 0.0)
        )
        if boss_id == "awakenedone":
            initial_powers = min(3.0, power_count)
            excess_powers = max(0.0, power_count - 3.0)
            power_factor = max(
                0.55,
                1.0 - initial_powers * 0.04 - excess_powers * 0.08,
            )
            boss_factor *= power_factor
            boss_constraints["power_density"] = {
                "power_cards": round(power_count, 3),
                "accelerated_after": 3,
                "factor": round(power_factor, 3),
            }
        elif boss_id == "timeeater":
            zero_cost = max(
                0.0,
                float((profile.get("roles") or {}).get("zero_cost", 0.0) or 0.0),
            )
            shiv_sources = float(
                ((profile.get("archetypes") or {}).get("shiv") or {}).get(
                    "source_reliability", 0.0
                )
                or 0.0
            )
            spam_pressure = max(0.0, zero_cost - 3.0) + shiv_sources * 0.35
            time_factor = max(0.65, 1.0 - spam_pressure * 0.06)
            boss_factor *= time_factor
            boss_constraints["card_count_pressure"] = {
                "zero_cost_cards": round(zero_cost, 3),
                "shiv_source_support": round(shiv_sources, 3),
                "factor": round(time_factor, 3),
            }

        # Slime's split_clock already combines access consistency with early
        # offense.  Do not multiply the same consistency a second time in
        # the outer geometric penalty; other bosses retain the general deck
        # access term unchanged.
        outer_consistency = 1.0 if split_clock is not None else consistency
        score = (
            role_score
            * math.sqrt(outer_consistency * bottleneck_ratio)
            * math.sqrt(max(0.20, survival_ratio))
            * boss_factor
        )
        progress_score = (
            role_score
            * math.sqrt(
                outer_consistency * (0.20 + 0.80 * bottleneck_ratio)
            )
            * math.sqrt(max(0.20, survival_ratio))
            * boss_factor
        )
        return {
            "boss_id": boss_id,
            "score": round(max(0.0, min(1.0, score)), 3),
            "progress_score": round(
                max(0.0, min(1.0, progress_score)), 3
            ),
            "ready": bool(
                score >= 0.65
                and bottleneck_ratio >= 0.90
                and survival_ratio >= 0.80
                and boss_factor >= 0.72
            ),
            "role_score": round(role_score, 3),
            "consistency": round(consistency, 3),
            "bottleneck_role": bottleneck_role,
            "bottleneck_ratio": round(bottleneck_ratio, 3),
            "survival": {
                "hp": hp,
                "max_hp": max_hp,
                "hp_ratio": round(hp_ratio, 3),
                "target_hp_ratio": round(hp_target, 3),
                "combat_potions": int(potion_count),
                "potion_credit": round(potion_credit, 3),
                "potion_credit_details": potion_credit_rows,
                "ratio": round(survival_ratio, 3),
            },
            "boss_specific_factor": round(boss_factor, 3),
            "boss_constraints": boss_constraints,
            "requirements": requirements,
            "gaps": gaps,
            "requirement_ratios": {
                role: round(ratio, 3)
                for role, ratio in requirement_ratios.items()
            },
            "coverage": {
                role: round(float(
                    (readiness.get("kill_clock") or {}).get("score", 0.0)
                    if role == "kill_clock"
                    else split_clock
                    if role == "split_clock"
                    else coverage.get(role, 0.0)
                ), 3)
                for role in requirements
            },
        }

    def _is_universal_plan_candidate(self, card, tags, profile=None):
        """Whether a card is allowed to cross a firm archetype boundary."""

        profile = profile or self._deck_profile()
        if tags & self.UNIVERSAL_PLAN_TAGS:
            return True
        # Early Act 1 still needs a damage floor.  Do not let a premature
        # source commitment reject a genuinely strong front-loaded attack.
        demand = self._deck_demand_vector(profile)
        if (
            "damage" in tags
            and demand.get("frontload", 0.0) >= 0.35
            and int(getattr(self.game, "act", 1) or 1) <= 2
        ):
            return True
        if "scaling" in tags and int(getattr(self.game, "act", 1) or 1) >= 2:
            return True
        # Boss answers are universal in the sense that their value is tied to
        # the encounter, not to the deck's primary engine.
        card_id = self._token(getattr(card, "card_id", ""))
        boss_id = self._boss_id()
        boss_answers = {
            "timeeater": {"wraithformv2", "footwork", "glacier", "catalyst", "bouncingflask"},
            "awakenedone": {"wraithformv2", "malaise", "piercingwail", "buffer", "impervious"},
            "automaton": {"buffer", "impervious", "ghostly", "wraithformv2"},
            "collector": {
                "alloutattack", "buffer", "cleave", "combust",
                "corpseexplosion", "daggerspray", "disarm",
                "doomandgloom", "electrodynamics", "glacier",
                "immolate", "impervious", "malaise", "piercingwail",
                "sweepingbeam", "whirlwind",
            },
        }
        return card_id in boss_answers.get(boss_id, set())

    def _deck_demand_vector(self, profile=None):
        """Return normalized marginal demand for the deck's universal roles."""

        profile = profile or self._deck_profile()
        roles = profile["roles"]
        act = max(1, int(getattr(self.game, "act", 1) or 1))
        floor = int(getattr(self.game, "floor", 0) or 0)
        coverage = self._deck_readiness(profile).get("coverage") or {}

        def missing(current, target):
            if target <= 0:
                return 0.0
            return round(max(0.0, min(1.0, (target - current) / target)), 3)

        return {
            "frontload": missing(roles["nonbasic_damage"], 2.0 if act == 1 else 2.5),
            "block": round(
                max(0.0, 1.0 - float(coverage.get("block", 0.0) or 0.0)),
                3,
            ),
            "draw": missing(roles["draw"], 1.5),
            # Reptomancer and Act 4 Shield/Spear keep AoE relevant after Act
            # 2; demand tapers, but never silently disappears.
            "aoe": missing(roles["aoe"], 1.0) * (1.0 if act <= 2 else 0.55),
            "scaling": (
                round(
                    max(
                        0.0,
                        1.0 - float(coverage.get("scaling", 0.0) or 0.0),
                    ),
                    3,
                )
                if act >= 2 or floor >= 7
                else 0.25
            ),
            "energy": (
                missing(roles["energy"], 1.0)
                if profile["expensive"] >= 3
                else 0.0
            ),
            "trim": round(max(0.0, min(1.0, (profile["size"] - 20) / 8.0)), 3),
        }

    def _deck_plan_adjustment(self, card, profile=None):
        profile = profile or self._deck_profile()
        tags = self._card_build_tags(card)
        adjustment = 0.0
        primary = self._deck_plan_summary(profile)
        card_id = self._token(getattr(card, "card_id", ""))
        cost = self._card_cost(card)
        effective_cost = max(0.75, float(cost if cost >= 0 else 1))
        damage = self._card_number(card, "damage", "base_damage")
        block = self._card_number(card, "block", "base_block")
        if damage > 0:
            adjustment += min(7.0, max(0.0, damage / effective_cost - 6.0) * 0.75)
        if block > 0:
            adjustment += min(5.0, max(0.0, block / effective_cost - 5.0) * 0.55)

        # Once a plan has enough evidence, keep ordinary filler from pulling
        # the deck back into a second, unsupported archetype.  This is a soft
        # hysteresis term: universal resources (draw/block/energy/AOE), an
        # early front-loaded attack, scaling, and known boss answers remain
        # eligible through _is_universal_plan_candidate().
        primary_name = str(primary.get("primary") or "balanced")
        commitment = primary.get("commitment") or {}
        commitment_level = max(
            0.0, min(1.0, float(commitment.get("level", 0.0) or 0.0))
        )
        primary_tags = {
            f"{primary_name}:source",
            f"{primary_name}:payoff",
        }
        if (
            primary_name != "balanced"
            and commitment_level > 0.0
            and not tags & primary_tags
            and not self._is_universal_plan_candidate(card, tags, profile)
        ):
            adjustment -= 2.5 * commitment_level
            if commitment.get("phase") == "firm":
                adjustment -= 2.0

        # Score the marginal improvement in the universal readiness vector as
        # a counterfactual.  This catches the common failure where a card fits
        # the named build but leaves the deck with no block, draw, or scaling
        # for the next act.  Keep the term bounded so card quality and combat
        # safety remain authoritative.
        deck_cards = list(getattr(self.game, "deck", []) or [])
        candidate_profile = self._deck_profile(deck_cards + [card])
        readiness_before_detail = self._deck_readiness(profile) or {}
        readiness_after_detail = self._deck_readiness(candidate_profile) or {}
        readiness_before = float(
            readiness_before_detail.get("score", 0.0) or 0.0
        )
        readiness_after = float(
            readiness_after_detail.get("score", 0.0) or 0.0
        )
        readiness_delta = readiness_after - readiness_before
        adjustment += max(-3.0, min(7.0, readiness_delta * 16.0))

        for archetype, state in profile["archetypes"].items():
            is_source = f"{archetype}:source" in tags
            is_payoff = f"{archetype}:payoff" in tags
            source_support = self._archetype_source_support(state)
            candidate_source_reliability = (
                self._archetype_source_reliability(
                    card,
                    archetype,
                    getattr(self.game, "deck", []) or [],
                )
                if is_source
                else 0.0
            )
            if is_source:
                source_value = min(
                    11.0,
                    state["payoffs"] * 4.5
                    + float(state["source_reliability"] or 0.0) * 1.25
                    + state["relic_support"] * 3.0,
                )
                adjustment += source_value * min(
                    1.25, candidate_source_reliability
                )
                if source_support >= 3 and state["payoffs"] == 0:
                    adjustment -= 4.0
            if is_payoff:
                if source_support <= 0:
                    adjustment -= 14.0
                else:
                    adjustment += min(
                        15.0,
                        4.0 + source_support * 4.0 + state["payoffs"],
                    )
                if (
                    archetype == "strength"
                    and card_id == "limitbreak"
                    and 0 < source_support < 0.75
                ):
                    # Limit Break needs Strength on the exact turn it is
                    # drawn. One Flex is useful burst support for attacks,
                    # but is not a reliable engine for a dead-on-draw skill.
                    adjustment -= 20.0 * (
                        (0.75 - source_support) / 0.75
                    )
            if (
                primary["primary"] == archetype
                and (is_source or is_payoff)
            ):
                adjustment += 2.0 + primary["confidence"] * 4.0

        # The remote plan is deliberately a small soft prior.  Exact card
        # quality, missing universal roles, copy saturation and skip remain
        # authoritative, so one stale or overconfident plan cannot force a
        # narrow archetype.
        model_primary = str(
            (self.model_run_plan or {}).get("primary") or "balanced"
        )
        if model_primary != "balanced" and tags & {
            f"{model_primary}:source", f"{model_primary}:payoff"
        }:
            model_confidence = float(
                (self.model_run_plan or {}).get("confidence", 0.0) or 0.0
            )
            adjustment += min(3.5, 1.5 + model_confidence * 2.0)

        discard_state = profile["archetypes"].get("discard", {})
        if (
            card_id == "prepared"
            and int(getattr(card, "upgrades", 0) or 0) == 0
            and discard_state.get("payoffs", 0) == 0
        ):
            # Prepared- draws one and discards one: without a discard payoff it
            # is a filter that enlarges the deck, not a missing draw solution.
            adjustment -= 6.0

        roles = profile["roles"]
        demand = self._deck_demand_vector(profile)
        if "damage" in tags:
            adjustment += demand["frontload"] * 10.0
        if "block" in tags:
            block_relief = 1.0
            if profile.get("defense_access") is not None:
                # Scarcity alone must not reward more of an already saturated
                # resource. Another cheap block/draw card may add no playable
                # defense when the existing hand already exhausts its budget.
                block_relief = min(1.0, max(
                    0.0,
                    readiness_after_detail["coverage"]["block"]
                    - readiness_before_detail["coverage"]["block"],
                ) / 0.05)
            adjustment += demand["block"] * 8.0 * block_relief
        draw_value = self._draw_plan_value(card)
        if "draw" in tags and demand["draw"] > 0:
            adjustment += min(7.0, draw_value * 5.0) * demand["draw"]
        elif (
            "draw" in tags
            and "energy" not in tags
            and roles["draw"] >= 3.5
            and roles["energy"] == 0
        ):
            adjustment -= 5.0
        if "aoe" in tags:
            adjustment += demand["aoe"] * 9.0
        if "scaling" in tags and card_id != "limitbreak":
            scaling_reliability = 1.0
            if "strength:source" in tags:
                scaling_reliability = min(
                    1.0,
                    self._archetype_source_reliability(
                        card,
                        "strength",
                        getattr(self.game, "deck", []) or [],
                    ),
                )
            adjustment += (
                demand["scaling"] * 12.0 * scaling_reliability
            )
            # The ordinary demand term values every useful scaling card, but
            # did not distinguish the first reliable engine from redundant
            # follow-up copies.  That made a historical floor-7 Ironclad deck
            # acknowledge a Hexaghost scaling gap, then take Shrug It Off over
            # Demon Form and spend the rest of the run accumulating block
            # without a kill clock.  Price only the independently measured
            # boss-gap closure, and only while the deck has no scaling
            # mechanism yet.  Slime Boss exposes no scaling requirement, so
            # its short split clock cannot receive this long-fight bonus.
            scaling_before = float(
                (readiness_before_detail.get("coverage") or {}).get(
                    "scaling", 0.0
                ) or 0.0
            )
            scaling_after = float(
                (readiness_after_detail.get("coverage") or {}).get(
                    "scaling", 0.0
                ) or 0.0
            )
            if (
                self._boss_id()
                and demand["scaling"] > 0.0
                and scaling_before < 0.25
                and scaling_after > scaling_before
            ):
                boss_before = self._boss_entry_readiness(profile) or {}
                boss_after = self._boss_entry_readiness(
                    candidate_profile
                ) or {}
                gap_before = float(
                    (boss_before.get("gaps") or {}).get("scaling", 0.0)
                    or 0.0
                )
                gap_after = float(
                    (boss_after.get("gaps") or {}).get("scaling", 0.0)
                    or 0.0
                )
                gap_closed = max(0.0, gap_before - gap_after)
                adjustment += min(8.0, gap_closed * 24.0)
        if "energy" in tags:
            adjustment += demand["energy"] * 10.0

        deck_size = max(1, profile["size"])
        if "block" in tags and roles["block"] / deck_size > 0.48:
            adjustment -= 7.0
        if (
            "damage" in tags
            and roles["damage"] / deck_size > 0.55
            and roles["nonbasic_damage"] >= 2
        ):
            adjustment -= 4.0
        if demand["trim"] > 0 and not tags & {"scaling", "energy", "aoe"}:
            adjustment -= demand["trim"] * 9.0
        if cost >= 2 and profile["average_cost"] >= 1.35:
            adjustment -= 3.0 + max(0, profile["expensive"] - 3) * 1.5
        return adjustment

    def _copy_saturation_penalty(
        self, card, copies, plan_adjustment, profile=None
    ):
        """Soft marginal penalty for redundant copies.

        MAX_COPIES is now a saturation point rather than a universal ban. A
        second exceptional engine card can still win on marginal value, while
        ordinary filler quickly falls below Skip.
        """

        card_id = self._token(getattr(card, "card_id", ""))
        if card_id == "limitbreak" and copies >= 1:
            profile = profile or self._deck_profile()
            strength = profile["archetypes"].get("strength", {})
            source_support = self._archetype_source_support(strength)
            draw_support = float(
                profile["roles"].get("draw", 0.0) or 0.0
            )
            overage = copies
            base = 40.0 + max(0, overage - 1) * 30.0
            relief = 0.0
            if source_support >= 1.5 and draw_support >= 1.5:
                relief = min(
                    14.0,
                    (source_support - 1.5) * 6.0
                    + (draw_support - 1.5) * 3.0,
                )
            # A second copy is only defensible in a mature, well-cycling
            # strength engine; a third copy is effectively saturated.
            return max(16.0, base - relief)

        limit = max(1, int(self.priorities.MAX_COPIES.get(card.card_id, 1) or 1))
        if limit >= 99 or copies < limit:
            return 0.0
        overage = copies - limit + 1
        rarity = getattr(card, "rarity", None)
        base = 36.0 + (overage - 1) * 14.0
        if rarity == spirecomm.spire.card.CardRarity.RARE:
            base -= 6.0
        if getattr(card, "type", None) == spirecomm.spire.card.CardType.POWER:
            base += 4.0
        # A nominal one-copy cap is not evidence that the deck's need is met.
        # Permit the second copy to compete on its ordinary card value only
        # when its counterfactual closes a material readiness gap without
        # trading away another role or access consistency. The per-copy drag
        # in _card_reward_score still applies, as does the Skip hurdle.
        if copies == 1 and overage == 1 and profile is not None:
            before = self._deck_readiness(profile)
            after = self._deck_readiness(self._deck_profile(
                list(getattr(self.game, "deck", []) or []) + [card]
            ))
            old_coverage = before.get("coverage", {})
            new_coverage = after.get("coverage", {})
            roles = ("frontload", "block", "draw", "scaling", "energy", "aoe")
            material_repair = any(
                float(old_coverage.get(role, 1.0)) < 0.85
                and float(new_coverage.get(role, 0.0))
                - float(old_coverage.get(role, 0.0)) >= 0.10 - 1e-9
                for role in roles
            )
            preserves_roles = all(
                float(new_coverage.get(role, 0.0))
                >= float(old_coverage.get(role, 0.0)) - 0.05 - 1e-9
                for role in roles
            )
            preserves_access = (
                float(after.get("consistency", 0.0))
                >= float(before.get("consistency", 0.0)) - 0.05 - 1e-9
            )
            if material_repair and preserves_roles and preserves_access:
                return 0.0
        # Strong contextual fit can otherwise soften, but not erase, saturation.
        contextual_relief = min(16.0, max(0.0, plan_adjustment - 7.0) * 0.8)
        return max(14.0, base - contextual_relief)

    def _relic_build_adjustment(self, relic, profile=None):
        profile = profile or self._deck_profile()
        deck = list(getattr(self.game, "deck", []) or [])
        relic_id = self._token(getattr(relic, "relic_id", ""))
        affinity = self.RELIC_ARCHETYPE_AFFINITY.get(
            self.chosen_class, {}
        ).get(relic_id)
        adjustment = 0.0
        if affinity is not None:
            archetype, weight = affinity
            state = profile["archetypes"].get(archetype, {"sources": 0, "payoffs": 0})
            support = state["sources"] + state["payoffs"]
            if support == 0:
                adjustment -= min(5.0, weight * 0.6)
            else:
                adjustment += min(
                    weight * 2.2,
                    weight * 0.55 * support
                    + min(state["sources"], state["payoffs"]) * 3.0,
                )

        roles = profile["roles"]
        role_affinity = self.RELIC_ROLE_AFFINITY.get(relic_id)
        if role_affinity is not None:
            role, weight, cap = role_affinity
            support = float(roles.get(role, 0.0) or 0.0)
            adjustment += min(float(cap), max(0.0, support) * float(weight))
        if relic_id == "mummifiedhand":
            adjustment += min(18.0, roles["power"] * 4.0)
        elif relic_id == "letteropener":
            adjustment += min(10.0, max(0, profile["size"] - roles["damage"]) * 0.45)
        elif relic_id == "pennib":
            adjustment += min(8.0, roles["damage"] * 0.8)
        elif relic_id == "sundial":
            adjustment += min(8.0, roles["draw"] * 1.5)
        elif relic_id == "icecream":
            # Retained energy is intrinsically premium and becomes more
            # reliable payoff when any class can bank it into X-cost cards.
            # Bind the synergy to the protocol cost marker rather than a
            # hard-coded card list, and cap duplicate density.
            adjustment += min(
                18.0,
                6.0 * self._x_cost_card_count(),
            )
        elif relic_id in {"paperfrog", "paperphrog"}:
            # Paper Frog is a damage multiplier, not just a generic relic:
            # its value is realized only when the deck can apply Vulnerable
            # (Bash, Neutralize, Terror, Trip, Sucker Punch, etc.).
            vulnerable_sources = sum(
                1
                for card in deck
                if self._token(getattr(card, "card_id", ""))
                in {"bash", "neutralize", "terror", "trip", "suckerpunch"}
            )
            adjustment += min(14.0, vulnerable_sources * 3.5)
        elif relic_id in {"boot", "theboot"}:
            # The Boot is a reliable Act 1/2 floor for low-damage Attacks and
            # Shiv/Slice packages, but its marginal value falls in a heavy
            # high-damage deck.
            low_attack_count = sum(
                1
                for card in deck
                if getattr(card, "type", None)
                == spirecomm.spire.card.CardType.ATTACK
                and 0 < int(getattr(card, "damage", 0) or 0) <= 4
            )
            adjustment += min(10.0, low_attack_count * 1.5)
        elif relic_id == "bronzescales":
            # Reactive damage is especially valuable when the route contains
            # multi-hit elites/bosses; keep a modest unconditional floor so a
            # shop purchase is not discarded as an unknown relic.
            adjustment += 4.0
        return adjustment

    def _card_boss_gap_relief(self, card, profile):
        """Value progress on an unmet requirement, not a card-name override.

        Aggregate readiness can stay at zero while a candidate repairs one
        of several missing roles. Measure the requirement it actually repairs
        without counting surplus coverage or adding multiple role bonuses.
        """
        if getattr(self.game, "in_combat", False) or not self._boss_id():
            return 0.0
        before = self._boss_entry_readiness(profile)
        after = self._boss_entry_readiness(self._deck_profile(
            list(getattr(self.game, "deck", []) or []) + [card]
        ))
        relief = [
            max(0.0, gap - float(after["gaps"].get(role, 0.0)))
            / max(0.01, float(before["requirements"].get(role, 1.0)))
            for role, gap in before["gaps"].items()
        ]
        return 12.0 * min(1.0, max([0.0, *relief]))

    def _card_access_cost_adjustment(self, card, deck):
        """Do not assume a high-cost reward's missing enablers will arrive."""
        cost = self._card_cost(card)
        if cost <= 3:
            return 0.0
        relics = {
            self._token(getattr(relic, "relic_id", ""))
            for relic in getattr(self.game, "relics", []) or []
        }
        if "sneckoeye" in relics:
            return 0.0
        if self._token(card.card_id) == "forcefield":
            # Each actual Power lowers future cost by one; this is optimistic
            # about drawing/playing them, but never credits hypothetical Powers.
            cost -= sum(
                known.type == spirecomm.spire.card.CardType.POWER
                for known in deck
            )
        energy = self._boss_energy_marginal_profile(
            "", self._deck_profile(deck),
        )["current_permanent_energy"]
        # Transient energy is possible support, not a guaranteed opening hand.
        support = max((
            max(0, FastCombatPlanner.ENERGY_VALUES.get(self._token(c.card_id), 0))
            for c in deck
        ), default=0)
        deficit = max(0.0, cost - energy)
        return -18.0 * max(0.0, deficit - min(deficit * 0.5, support * 0.5))

    def _card_reward_score(self, card):
        if card.rarity == spirecomm.spire.card.CardRarity.CURSE:
            self._remember_card_reward_score_contract(
                card,
                {"curse_rejection": -1000.0},
            )
            return -1000
        rank = self.priorities.CARD_PRIORITIES.get(card.card_id)
        skip_rank = self.priorities.CARD_PRIORITIES.get("Skip", 0)
        if rank is None:
            # Unknown cards remain a cautious negative prior, but their
            # serialized output and deck-plan contribution may rescue them.
            # The old -26 behaved like an undocumented hard ban.
            score = -16.0
        else:
            # Static priority is only a prior.  Keeping it bounded prevents a
            # long table from overwhelming deck, boss and energy context.
            score = max(-18.0, min(28.0, float(skip_rank - rank) * 0.38))
        score_parts = {"bounded_static_priority": float(score)}
        upgrade_bonus = int(getattr(card, "upgrades", 0) or 0) * 4
        score += upgrade_bonus
        score_parts["upgrade_bonus"] = float(upgrade_bonus)

        deck = list(getattr(self.game, "deck", []) or [])
        deck_profile = self._deck_profile(deck)
        copies = self.count_copies_in_deck(card)
        card_id = self._token(card.card_id)
        copy_limit = max(
            1,
            int(self.priorities.MAX_COPIES.get(card.card_id, 1) or 1),
        )
        self_replacing_accelerator = bool(
            self._card_cost(card) == 0
            and int(FastCombatPlanner.DRAW_COUNTS.get(card_id, 0) or 0) > 0
            and int(FastCombatPlanner.ENERGY_VALUES.get(card_id, 0) or 0) > 0
        )
        intrinsic_self_damage = int(
            FastCombatPlanner.INTRINSIC_SELF_DAMAGE.get(card_id, 0) or 0
        )
        current_hp = max(
            0, int(getattr(self.game, "current_hp", 0) or 0)
        )
        safety_reserve = FastCombatPlanner._reactive_safety_reserve(
            self.game, current_hp
        )
        accelerator_safe = bool(
            intrinsic_self_damage <= 0
            or current_hp - intrinsic_self_damage >= safety_reserve
        )
        accelerator_unsaturated = bool(
            copy_limit >= 99 or copies < copy_limit
        )
        acceleration_floor_eligible = bool(
            self_replacing_accelerator
            and accelerator_safe
            and accelerator_unsaturated
        )
        if not acceleration_floor_eligible:
            score -= max(0, len(deck) - 18) * 0.85

        deck_ids = {self._token(deck_card.card_id) for deck_card in deck}
        defensive_count = sum(1 for deck_card in deck if self.priorities.is_card_defensive(deck_card))
        if self.priorities.is_card_defensive(card) and defensive_count < 5 + self.game.act:
            score += 8

        draw_ids = set(FastCombatPlanner.DRAW_COUNTS)
        draw_count = sum(1 for deck_card in deck if self._token(deck_card.card_id) in draw_ids)
        demand = self._deck_demand_vector(deck_profile)
        if card_id in draw_ids and draw_count < 3:
            # Early draw is useful only while the deck still has an access
            # gap. A flat bonus for the third draw card inflated resource
            # density even when the deck still lacked a way to close fights.
            score += 7 * demand["draw"]

        expensive_cards = sum(
            1 for deck_card in deck if self._card_cost(deck_card) >= 2
        )
        if self._card_cost(card) >= 2:
            score -= max(0, expensive_cards - 2) * 4

        plan_adjustment = self._deck_plan_adjustment(card, deck_profile)
        score += plan_adjustment
        if card_id in draw_ids:
            # Draw is an engine resource, not generic deck filler.  Let a
            # measured draw deficit overcome an overly pessimistic static
            # table entry (Skim was repeatedly skipped in draw-starved Defect
            # decks despite exposing three real cards).
            score += demand["draw"] * min(
                12.0,
                max(1, int(FastCombatPlanner.DRAW_COUNTS.get(card_id, 1) or 1))
                * 4.0,
            )

        candidate_offense = self._early_offense_card_value(card)
        existing_offense = sum(
            self._early_offense_card_value(deck_card) for deck_card in deck
        )
        if self._is_early_act1_building_reward() and existing_offense < 2.0 and candidate_offense > 0:
            score += 18 * min(1.0, candidate_offense)

        score_parts["general_deck_context"] = float(
            score
            - score_parts["bounded_static_priority"]
            - score_parts["upgrade_bonus"]
        )
        class_context_start = score
        defect_orb_reprogram_conflict = 0.0
        structural_dependency_adjustment = 0.0

        if self.chosen_class == PlayerClass.THE_SILENT:
            poison_sources = {"bouncingflask", "corpseexplosion", "cripplingpoison", "deadlypoison", "noxiousfumes", "poisonedstab"}
            if deck_ids & poison_sources and card_id in poison_sources | {"catalyst"}:
                score += 11
            if card_id == "catalyst" and not deck_ids & poison_sources:
                score -= 22
            discard_sources = {"acrobatics", "calculatedgamble", "daggerthrow", "prepared", "survivor"}
            if deck_ids & discard_sources and card_id in discard_sources | {"eviscerate", "reflex", "tactician"}:
                score += 7
            shiv_sources = {"bladedance", "cloakanddagger", "infiniteblades", "stormofsteel"}
            if deck_ids & shiv_sources and card_id == "accuracy":
                score += 24
            if sum(1 for deck_card in deck if self._token(deck_card.card_id) in shiv_sources) >= 2:
                if card_id in {"finisher", "afterimage"}:
                    score += 12
            if card_id == "wraithformv2":
                # Intangible is one of Silent's few answers to Act 2/3 burst
                # and Act 4.  The old static list placed it below Skip.
                score += 62 + 6 * max(0, self.game.act - 1)
            elif card_id == "athousandcuts":
                shivs = sum(1 for deck_card in deck if self._token(deck_card.card_id) in shiv_sources)
                cheap_draw = sum(
                    1 for deck_card in deck
                    if self._card_cost(deck_card) <= 1
                    and self._token(deck_card.card_id) in draw_ids
                )
                score += min(12, shivs * 4 + cheap_draw * 2)
                if shivs == 0:
                    score -= 18
            elif card_id == "afterimage":
                score += 18
        elif self.chosen_class == PlayerClass.IRONCLAD:
            exhaust_core = {"corruption", "darkembrace", "feelnopain"}
            if deck_ids & exhaust_core and card_id in exhaust_core | {"burningpact", "fiendfire", "secondwind", "truegrit"}:
                score += 11
            strength_core = {"demonform", "inflame", "spotweakness"}
            strength_payoffs = {
                "heavyblade", "limitbreak", "pummel", "reaper",
                "swordboomerang", "twinstrike",
            }
            if (
                deck_ids & strength_core
                and card_id in strength_core | strength_payoffs
            ) or (
                deck_ids & strength_payoffs
                and card_id in strength_core
            ):
                # Synergy is bidirectional: a reliable Strength source makes
                # a payoff better, and an existing payoff makes its first
                # reliable source equally valuable.
                score += 9
            if card_id == "reaper":
                strength_sources = sum(
                    1
                    for deck_card in deck
                    if self._token(deck_card.card_id) in strength_core | {"flex"}
                )
                score += min(18.0, strength_sources * 5.0)
            if card_id == "armaments":
                unupgraded = sum(
                    1
                    for deck_card in deck
                    if int(getattr(deck_card, "upgrades", 0) or 0) == 0
                    and getattr(deck_card, "rarity", None)
                    != spirecomm.spire.card.CardRarity.CURSE
                )
                score += min(12.0, max(0, unupgraded - 3) * 1.25)
            if card_id == "perfectedstrike":
                # Perfected Strike is a two-energy package payoff, not an
                # independently efficient attack.  The static table used to
                # select it even after every Strike had been removed.  Count
                # the exact permanent deck support before allowing its prior
                # to compete with Skip.
                strike_support = sum(
                    1
                    for deck_card in deck
                    if "strike" in self._token(
                        getattr(deck_card, "card_id", "")
                    )
                )
                dependency_penalty = (
                    -18.0
                    if strike_support == 0
                    else -12.0
                    if strike_support == 1
                    else -6.0
                    if strike_support == 2
                    else 0.0
                )
                score += dependency_penalty
                structural_dependency_adjustment += dependency_penalty
            if card_id == "clash":
                # Clash is playable only when every other card in hand is an
                # Attack.  Estimate its first-cycle availability directly
                # from the deck instead of treating "zero cost" as unconditional.
                attack_count = sum(
                    1
                    for deck_card in deck
                    if getattr(deck_card, "type", None)
                    == spirecomm.spire.card.CardType.ATTACK
                )
                pool = max(1, len(deck))
                draws_beside_clash = min(4, pool)
                availability = 1.0
                for offset in range(draws_beside_clash):
                    availability *= max(0, attack_count - offset) / max(
                        1, pool - offset
                    )
                score -= (1.0 - availability) * 30.0
                if self._has_relic("Runic Pyramid"):
                    score -= 12.0
                if "corruption" in deck_ids:
                    score += 7.0
        elif self.chosen_class == PlayerClass.DEFECT:
            orb_core = {"biasedcognition", "capacitor", "consume", "defragment", "glacier"}
            if deck_ids & orb_core and card_id in orb_core | {"coolheaded", "electrodynamics", "loop"}:
                score += 11
            if card_id in {"biasedcognition", "defragment", "electrodynamics", "glacier"}:
                score += 10
            artifact_cards = {"coresurge", "panacea"}
            artifact_relics = {"clockworksouvenir"}
            relic_ids = {
                self._token(getattr(relic, "relic_id", ""))
                for relic in getattr(self.game, "relics", []) or []
            }
            has_artifact_source = bool(deck_ids & artifact_cards or relic_ids & artifact_relics)
            if card_id == "biasedcognition" and has_artifact_source:
                score += 20
            if card_id in artifact_cards and "biasedcognition" in deck_ids:
                score += 18
            if card_id == "fission":
                orb_sources = set().union(*(
                    definition["sources"]
                    for name, definition in self.ARCHETYPE_DEFINITIONS[PlayerClass.DEFECT].items()
                    if name in {"frost", "lightning", "dark"}
                ))
                orb_density = sum(
                    1
                    for deck_card in deck
                    if self._token(deck_card.card_id) in orb_sources
                )
                score += (24 if int(getattr(card, "upgrades", 0) or 0) > 0 else 7)
                score += min(10, orb_density * 2)
            if card_id == "seek":
                high_impact = deck_profile["roles"]["scaling"] + deck_profile["roles"]["energy"]
                score += 18 + min(10, high_impact * 3)
            if card_id == "capacitor":
                # Extra slots only matter when the deck can repeatedly fill
                # and cycle them.  Starter Zap plus one early channel card is
                # not a complete orb engine and must not outrank an
                # unconditional consistency card such as Seek.
                repeatable_orb_sources = {
                    "balllightning", "chaos", "chill", "coldsnap",
                    "coolheaded", "darkness", "doomandgloom",
                    "electrodynamics", "fusion", "glacier",
                    "meteorstrike", "rainbow", "recursion",
                    "staticdischarge", "tempest", "zap",
                }
                orb_source_count = sum(
                    1
                    for deck_card in deck
                    if self._token(getattr(deck_card, "card_id", ""))
                    in repeatable_orb_sources
                )
                has_focus_engine = bool(
                    deck_ids
                    & {"biasedcognition", "consume", "defragment"}
                )
                dependency_penalty = (
                    -24.0
                    if orb_source_count < 2
                    else -18.0
                    if orb_source_count < 3 and not has_focus_engine
                    else -8.0
                    if orb_source_count < 3
                    else 0.0
                )
                score += dependency_penalty
                structural_dependency_adjustment += dependency_penalty
            if card_id == "storm":
                # Storm pays off only through Powers drawn after it.  One
                # early Capacitor is not enough density; Creative AI is
                # counted as a durable generator rather than one Power.
                downstream_power_count = sum(
                    1
                    for deck_card in deck
                    if getattr(deck_card, "type", None)
                    == spirecomm.spire.card.CardType.POWER
                    and self._token(getattr(deck_card, "card_id", ""))
                    != "storm"
                )
                if "creativeai" in deck_ids:
                    downstream_power_count += 3
                dependency_penalty = (
                    -30.0
                    if downstream_power_count == 0
                    else -24.0
                    if downstream_power_count == 1
                    else -10.0
                    if downstream_power_count == 2
                    else 0.0
                )
                score += dependency_penalty
                structural_dependency_adjustment += dependency_penalty
            if card_id == "reprogram":
                conflict = self._defect_reprogram_conflict_profile(deck)
                defect_orb_reprogram_conflict = -float(
                    conflict["conflict_penalty"]
                )
                score += defect_orb_reprogram_conflict

        if self.chosen_class == PlayerClass.THE_SILENT:
            relic_ids = {
                self._token(getattr(relic, "relic_id", ""))
                for relic in getattr(self.game, "relics", []) or []
            }
            if "wristblade" in relic_ids and card_id in {
                "bladedance", "cloakanddagger", "infiniteblades",
                "stormofsteel",
            }:
                score += 16.0
            if card_id == "eviscerate":
                repeatable_discard = sum(
                    1
                    for deck_card in deck
                    if self._token(deck_card.card_id) in {
                        "acrobatics", "calculatedgamble", "daggerthrow",
                        "prepared", "toolsofthetrade",
                    }
                )
                if repeatable_discard == 0:
                    score -= 20.0
                else:
                    score += min(12.0, repeatable_discard * 4.0)

        class_and_relic_context = float(score - class_context_start)
        score_parts["class_and_relic_context"] = (
            class_and_relic_context
            - defect_orb_reprogram_conflict
            - structural_dependency_adjustment
        )
        if structural_dependency_adjustment:
            score_parts["structural_dependency_adjustment"] = (
                structural_dependency_adjustment
            )
        if defect_orb_reprogram_conflict:
            score_parts["defect_orb_reprogram_conflict"] = (
                defect_orb_reprogram_conflict
            )
        boss_context_start = score

        boss_id = (
            self._boss_id()
            if "boss" not in str(getattr(self.game, "room_type", "") or "").lower()
            else ""
        )
        boss_answers = {
            "hexaghost": {
                "bouncingflask", "catalyst", "demonform", "deadlypoison",
                "defragment", "inflame", "noxiousfumes", "spotweakness",
            },
            "slimeboss": {
                "alloutattack", "cleave", "daggerspray", "electrodynamics",
                "evolve", "immolate", "sweepingbeam", "whirlwind",
            },
            "champ": {
                "afterimage", "catalyst", "demonform", "disarm", "footwork", "malaise",
                "wraithformv2", "buffer", "glacier",
            },
            "automaton": {"buffer", "impervious", "wraithformv2", "ghostly"},
            # Three of the fixed-hash six-run cohort died to Collector.  The
            # old table gave every Act 2 reward zero matchup context, so AoE,
            # minion control and durable mitigation were valued exactly as if
            # the upcoming boss were a single target.  Keep this a narrow
            # encounter answer set instead of globally inflating those cards.
            "collector": {
                "alloutattack", "buffer", "cleave", "combust",
                "corpseexplosion", "daggerspray", "disarm",
                "doomandgloom", "electrodynamics", "glacier",
                "immolate", "impervious", "malaise", "piercingwail",
                "sweepingbeam", "whirlwind",
            },
            "timeeater": {
                "bouncingflask", "catalyst", "demonform", "echoform",
                "footwork", "glacier", "noxiousfumes", "wraithformv2",
            },
            "awakenedone": {"malaise", "piercingwail", "wraithformv2", "impervious", "buffer"},
        }
        if card_id in boss_answers.get(boss_id, set()):
            score += 10
        if boss_id == "slimeboss" and card_id == "evolve":
            # Goop Spray guarantees three Slimed cards before the first Slam.
            # Evolve converts each later status draw back into a real card, so
            # it is a direct encounter answer rather than speculative status
            # synergy that requires another deck source.
            score += 20
        if boss_id == "awakenedone" and card.type == spirecomm.spire.card.CardType.POWER:
            if card_id not in {"afterimage", "wraithformv2", "buffer"}:
                score -= 10

        score_parts["boss_matchup_context"] = float(
            score - boss_context_start
        )
        gap_relief = self._card_boss_gap_relief(card, deck_profile)
        score += gap_relief
        score_parts["unmet_boss_requirement_relief"] = gap_relief
        # A strong, measured repair can soften a negative static prior. Keep
        # the relief small and retain every cost/dependency/copy penalty.
        prior_relief = min(
            6.0,
            max(0.0, -score_parts["bounded_static_priority"])
            * (gap_relief / 12.0) * 0.5,
        )
        score += prior_relief
        score_parts["unmet_boss_requirement_prior_relief"] = prior_relief

        redundancy_penalty = self._copy_saturation_penalty(
            card, copies, plan_adjustment, deck_profile
        )
        score -= redundancy_penalty
        if copies > 0:
            redundancy_penalty += copies * (
                7
                if card.type == spirecomm.spire.card.CardType.POWER
                else 3
            )
            score -= copies * (7 if card.type == spirecomm.spire.card.CardType.POWER else 3)
        score_parts["redundancy_penalty"] = -float(redundancy_penalty)
        if acceleration_floor_eligible:
            acceleration_floor = (
                max(8.0, self._permanent_card_pick_hurdle()) + 1.0
            )
            floor_bonus = max(0.0, acceleration_floor - score)
            score += floor_bonus
            score_parts["self_replacing_acceleration_floor"] = floor_bonus
        access_adjustment = self._card_access_cost_adjustment(card, deck)
        score += access_adjustment
        score_parts["unsupported_energy_cost"] = access_adjustment
        self._remember_card_reward_score_contract(card, score_parts)
        return score

    def _remember_card_reward_score_contract(self, card, score_parts):
        """Retain the pre-selection score decomposition for audit emission."""

        inputs = {
            str(name): float(value) for name, value in score_parts.items()
        }
        cache = getattr(self, "_card_reward_score_contracts", None)
        if not isinstance(cache, dict):
            cache = {}
            self._card_reward_score_contracts = cache
        cache[id(card)] = self._linear_score_contract(
            "card_reward_context_components_v1",
            inputs,
            tuple((name, name, 1.0) for name in inputs),
        )

    def _shop_relic_downside_context(self, relic, profile):
        """Price relic liabilities against the known boss and live deck.

        Positive archetype affinity is already handled by
        ``_relic_build_adjustment``.  Relics with symmetric or explicit
        downsides need a separate, auditable term so a cheap shop price cannot
        hide the encounter cost.  This starts with Brimstone, whose enemy
        Strength is especially sensitive to multi-hit bosses.
        """

        relic_id = self._token(getattr(relic, "relic_id", ""))
        if relic_id != "brimstone":
            return {
                "effect": None,
                "evaluated": False,
                "boss_id": self._boss_id(),
                "downside_score": 0.0,
            }

        boss_id = self._boss_id()
        if not boss_id:
            return {
                "effect": "symmetric_strength_growth",
                "evaluated": False,
                "boss_id": "",
                "downside_score": 0.0,
            }

        # Maximum recurring packet exposure, not a fabricated fixed intent.
        # Brimstone adds Strength to every hit, so multi-hit encounters carry
        # proportionally more downside even when their current move is hidden.
        boss_hit_exposure = {
            "slimeboss": 2.0,
            "guardian": 4.0,
            "hexaghost": 6.0,
            "champ": 2.0,
            "collector": 2.0,
            "automaton": 2.0,
            "donuanddeca": 2.0,
            "timeeater": 3.0,
            "awakenedone": 4.0,
            "corruptheart": 15.0,
            "theheart": 15.0,
        }.get(boss_id, 1.0)
        readiness = self._deck_readiness(profile)
        boss_readiness = self._boss_entry_readiness(profile)
        consistency = max(
            0.0, min(1.0, float(readiness.get("consistency", 0.0) or 0.0))
        )
        block_gap = max(
            0.0,
            float((boss_readiness.get("gaps") or {}).get("block", 0.0) or 0.0),
        )
        hp = max(0, int(getattr(self.game, "current_hp", 0) or 0))
        max_hp = max(1, int(getattr(self.game, "max_hp", hp) or hp or 1))
        hp_ratio = min(1.0, hp / max_hp)
        downside = boss_hit_exposure * (
            1.35
            + (1.0 - consistency) * 1.10
            + block_gap * 1.35
        )
        downside += max(0.0, 0.70 - hp_ratio) * 12.0
        downside = min(28.0, max(0.0, downside))
        return {
            "effect": "symmetric_strength_growth",
            "evaluated": True,
            "boss_id": boss_id,
            "enemy_hit_exposure": round(boss_hit_exposure, 3),
            "deck_consistency": round(consistency, 3),
            "boss_block_gap": round(block_gap, 3),
            "hp_ratio": round(hp_ratio, 3),
            "downside_score": round(downside, 3),
        }

    def _shop_relic_score(self, relic):
        relic_id = self._token(relic.relic_id)
        premium = {
            "bagofpreparation", "clockworksouvenir", "gamblingchip", "incenseburner",
            "ice cream", "kunai", "meatonthebone", "mummifiedhand", "ornamental fan",
            "preservedinsect", "shuriken", "toxic egg", "toxic egg 2",
            "tungstenrod",
        }
        solid = {
            "anchor", "ancient tea set", "art of war", "bag of marbles",
            "blood vial", "bronze scales", "boot", "akabeko",
            "calipers", "centennial puzzle", "charon's ashes", "frozen egg 2",
            "happy flower", "horn cleat", "ink bottle", "lantern", "letter opener",
            "meal ticket", "mercury hourglass", "molten egg 2", "nunchaku",
            "odd mushroom", "oddly smooth stone", "orichalcum", "pen nib", "potion belt",
            "red mask", "regal pillow", "singing bowl", "sundial", "thread and needle", "torii", "vajra",
            "mutagenicstrength",
            "white beast statue", "toy ornithopter",
        }
        # An unmodelled relic is not automatically worth a shop purchase.  In
        # particular, relics whose value depends on information or mechanics
        # the agent does not use must not inherit the old universal 25-point
        # prior.  Explicit scores also make chest/key opportunity cost use the
        # same conservative model as the shop.
        explicit_base = {
            "prismaticshard": -24,
            "frozeneye": -10,
            "juzubracelet": 4,
            "handdrill": 2,
            # CommunicationMod has emitted both spellings.  Paper Crane is a
            # premium Silent survival relic under either identifier.
            "papercrane": 34,
            "paperkrane": 34,
            # Both Paper Frog spellings are target-damage multipliers.  Keep
            # them explicit so a reward/shop id cannot fall through to the
            # unknown-relic prior.
            "paperfrog": 34,
            "paperphrog": 34,
        }
        class_bonus = {
            PlayerClass.THE_SILENT: {
                "papercrane", "paperkrane", "twistedfunnel", "wristblade",
            },
            PlayerClass.IRONCLAD: {
                "brimstone", "championbelt", "charonsashes",
                "paperfrog", "paperphrog",
            },
            PlayerClass.DEFECT: {
                "data disk", "emotionchip", "cables",
                "goldplatedcables", "runiccapacitor",
            },
        }.get(self.chosen_class, set())
        premium_ids = {self._token(value) for value in premium}
        solid_ids = {self._token(value) for value in solid}
        score = explicit_base.get(relic_id, 28 if relic_id in solid_ids else 10)
        if relic_id in premium_ids:
            score = max(score, 43)
        score += 12 if relic_id in {self._token(value) for value in class_bonus} else 0
        deck = list(getattr(self.game, "deck", []) or [])
        deck_profile = self._deck_profile(deck)
        score += self._relic_build_adjustment(relic, deck_profile)
        if relic_id == "preservedinsect" and self.game.act <= 2:
            score += 12
        if relic_id in {"toxicegg2", "frozenegg2", "moltonegg2"} and self.game.act <= 2:
            score += 9
        if relic_id == "meal ticket" or relic_id == "mealticket":
            score += 8 if self.game.current_hp < self.game.max_hp else 3
        if relic_id in {"waffle", "leeswaffle"}:
            missing_hp = max(0, self.game.max_hp - self.game.current_hp)
            score += 32 + missing_hp * 2
            if self.game.current_hp < max(40, int(self.game.max_hp * 0.65)):
                score += 25
        if relic_id == "toyornithopter":
            missing_hp = max(0, self.game.max_hp - self.game.current_hp)
            score += min(10.0, missing_hp / 7.0)
            if self._has_relic("White Beast Statue"):
                score += 8.0
            elif self._has_relic("Potion Belt"):
                score += 4.0

        act = max(1, int(getattr(self.game, "act", 1) or 1))
        floor = max(0, int(getattr(self.game, "floor", 0) or 0))
        if act == 1:
            stage_discount = 0
        elif act == 2:
            stage_discount = 2
        elif act == 3:
            floor_in_act = floor % 17
            stage_discount = 5
            if floor_in_act >= 9:
                stage_discount += 3
            if floor_in_act >= 13:
                stage_discount += 3
        else:
            stage_discount = 12
        score -= stage_discount
        positive_score = float(score)
        downside_context = self._shop_relic_downside_context(
            relic, deck_profile
        )
        downside_score = float(
            downside_context.get("downside_score", 0.0) or 0.0
        )
        contexts = getattr(self, "_shop_relic_score_contexts", None)
        if not isinstance(contexts, dict):
            contexts = {}
            self._shop_relic_score_contexts = contexts
        contexts[id(relic)] = {
            **downside_context,
            "positive_score": round(positive_score, 3),
            "risk_adjusted_score": round(
                positive_score - downside_score, 3
            ),
        }
        return positive_score - downside_score

    def _relic_keep_score(self, relic):
        relic_id = self._token(relic.relic_id)
        score = self._shop_relic_score(relic)
        if relic_id in {
            "astrolabe", "callingbell", "emptycage", "mango", "oldcoin",
            "pandorasbox", "pear", "strawberry", "tinyhouse", "warpaint",
            "whetstone",
        }:
            score -= 24
        if relic_id in {
            "burningblood", "crackedcore", "ringofthesnake",
            "cursedkey", "ectoplasm", "fusionhammer", "hoveringkite",
            "nuclearbattery", "philosophersstone", "velvetchoker",
        }:
            score += 24
        if (
            relic_id in {"neowsblessing", "neowslament"}
            and int(getattr(relic, "counter", 0) or 0) <= 0
        ):
            score -= 20
        return score

    def _relic_acquisition_score(self, relic):
        """Value a chest relic before its one-time effect has fired."""

        relic_id = self._token(relic.relic_id)
        if relic_id in {"warpaint", "whetstone"}:
            wanted_type = (
                spirecomm.spire.card.CardType.SKILL
                if relic_id == "warpaint"
                else spirecomm.spire.card.CardType.ATTACK
            )
            eligible_scores = [
                float(self._upgrade_score(card))
                for card in getattr(self.game, "deck", []) or []
                if getattr(card, "type", None) == wanted_type
                and int(getattr(card, "upgrades", 0) or 0) == 0
            ]
            if not eligible_scores:
                return 0.0
            if len(eligible_scores) <= 2:
                return sum(eligible_scores)
            # Both relics randomly upgrade two eligible cards.  Every card has
            # probability 2 / n of being selected, so the expected one-shot
            # value is twice the eligible pool's average upgrade value.
            return 2.0 * sum(eligible_scores) / len(eligible_scores)

        score = self._shop_relic_score(relic)
        score += {
            "astrolabe": 20,
            "emptycage": 20,
            "mango": 22,
            "oldcoin": 18,
            "pandorasbox": 28,
            "pear": 15,
            "strawberry": 9,
            "tinyhouse": 10,
        }.get(relic_id, 0)
        return score

    def _shop_discount_relic_factor(self, relic):
        """Return the price multiplier unlocked by a shop discount relic."""

        relic_id = self._token(getattr(relic, "relic_id", ""))
        return {
            "membershipcard": 0.50,
            "thecourier": 0.80,
        }.get(relic_id)

    def _shop_expected_future_discount_value(self, relic):
        """Conservative value of discounts after the current shop."""

        factor = self._shop_discount_relic_factor(relic)
        if factor is None:
            return {
                "future_shop_opportunities": 0.0,
                "expected_future_spend": 0.0,
                "expected_future_savings": 0.0,
                "restock_option_value": 0.0,
            }
        act = max(1, int(getattr(self.game, "act", 1) or 1))
        floor = max(0, int(getattr(self.game, "floor", 0) or 0))
        if act >= 4:
            opportunities = 0.0
        else:
            floor_in_act = floor % 17
            current_act_opportunity = (
                0.75 if floor_in_act <= 8
                else 0.40 if floor_in_act <= 11
                else 0.15 if floor_in_act <= 13
                else 0.0
            )
            opportunities = max(0, 3 - act) + current_act_opportunity
        expected_spend = opportunities * 120.0
        savings = expected_spend * (1.0 - factor)
        restock_value = (
            opportunities * 2.5
            if self._token(getattr(relic, "relic_id", "")) == "thecourier"
            else 0.0
        )
        return {
            "future_shop_opportunities": round(opportunities, 3),
            "expected_future_spend": round(expected_spend, 3),
            "expected_future_savings": round(savings, 3),
            "restock_option_value": round(restock_value, 3),
        }

    def _shop_optimal_basket(self, listings, gold, *, discount_factor=1.0):
        """Optimize a bounded visible shopping basket under one gold budget."""

        candidates = []
        for listing in listings:
            if not listing.get("selection_eligible"):
                continue
            if listing.get("action_object") is None:
                continue
            item = listing.get("item")
            if (
                listing.get("kind") == "relic"
                and self._shop_discount_relic_factor(item) is not None
            ):
                continue
            kind = str(listing.get("kind") or "")
            price = max(0, int(listing.get("price", 0) or 0))
            discounted_price = max(
                0, int(math.floor(price * float(discount_factor)))
            )
            coefficient = {
                "card": 1.0 / 18.0,
                "relic": 1.0 / 16.0,
                "potion": 1.0 / 11.0,
                "purge": 1.0 / 12.0,
            }.get(kind, 0.0)
            adjusted_score = float(listing.get("score", 0.0) or 0.0)
            adjusted_score += (price - discounted_price) * coefficient
            floor = {
                "potion": 6.5,
                "purge": 5.5,
                "relic": 6.5,
            }.get(kind, 8.0)
            if adjusted_score < floor:
                continue
            candidates.append({
                "choice_id": listing["choice_id"],
                "kind": kind,
                "price": discounted_price,
                "original_price": price,
                "score": adjusted_score,
            })
        candidates.sort(
            key=lambda row: (-row["score"], row["price"], row["choice_id"])
        )
        candidates = candidates[:16]
        real_potions = len(self.game.get_real_potions() or [])
        free_potion_slots = max(0, self._potion_slot_capacity() - real_potions)
        if free_potion_slots == 0 and any(
            row["kind"] == "potion" for row in candidates
        ):
            free_potion_slots = 1

        memo = {}

        def best(index, budget, cards, relics, potions):
            key = (index, budget, cards, relics, potions)
            if key in memo:
                return memo[key]
            if index >= len(candidates):
                return (0.0, 0, ())
            skip = best(index + 1, budget, cards, relics, potions)
            row = candidates[index]
            take = None
            if row["price"] <= budget:
                next_cards = cards
                next_relics = relics
                next_potions = potions
                repeat_penalty = 0.0
                if row["kind"] == "card":
                    repeat_penalty = cards * 12.0
                    next_cards += 1
                elif row["kind"] == "relic":
                    repeat_penalty = relics * 12.0
                    next_relics += 1
                elif row["kind"] == "potion":
                    if potions >= free_potion_slots:
                        memo[key] = skip
                        return skip
                    next_potions += 1
                tail = best(
                    index + 1,
                    budget - row["price"],
                    next_cards,
                    next_relics,
                    next_potions,
                )
                take = (
                    row["score"] - repeat_penalty + tail[0],
                    row["price"] + tail[1],
                    (row["choice_id"],) + tail[2],
                )
            result = skip
            if take is not None and (
                take[0], -take[1], take[2]
            ) > (
                skip[0], -skip[1], skip[2]
            ):
                result = take
            memo[key] = result
            return result

        score, spend, choice_ids = best(
            0, max(0, int(gold)), 0, 0, 0
        )
        return {
            "score": round(float(score), 3),
            "spend": int(spend),
            "choice_ids": list(choice_ids),
        }

    def _shop_discount_relic_plan(self, listing, listings, gold):
        """Compare shopping now with buying one discount relic first."""

        relic = listing.get("item")
        factor = self._shop_discount_relic_factor(relic)
        price = max(0, int(listing.get("price", 0) or 0))
        if factor is None or price > gold:
            return None
        baseline = self._shop_optimal_basket(listings, gold)
        discounted = self._shop_optimal_basket(
            listings,
            max(0, int(gold) - price),
            discount_factor=factor,
        )
        future = self._shop_expected_future_discount_value(relic)
        discounted_total = (
            float(discounted["score"])
            + float(future["expected_future_savings"]) / 16.0
            + float(future["restock_option_value"])
            - price / 16.0
        )
        advantage = discounted_total - float(baseline["score"])
        return {
            "relic_id": getattr(relic, "relic_id", None),
            "discount_factor": factor,
            "relic_price": price,
            "baseline_basket": baseline,
            "discounted_basket": discounted,
            **future,
            "discounted_total_score": round(discounted_total, 3),
            "basket_advantage": round(advantage, 3),
            "should_buy_first": bool(
                discounted["choice_ids"] and advantage >= 0.25
            ),
        }

    def choose_shop_action(self):
        choices = []
        gold = self.game.gold
        shop_profile = self._deck_profile()
        purge_target = max(
            list(getattr(self.game, "deck", []) or []),
            key=self._removal_score,
            default=None,
        )
        visit_key = (int(self.game.act), int(self.game.floor))
        if self.shop_visit_key != visit_key:
            self.shop_visit_key = visit_key
            self.shop_completed_visit_key = None
            self.pending_shop_potion_purchase = None
            self.shop_entry_card_ids = {
                getattr(card, "uuid", None) for card in self.game.screen.cards
            }
            self.shop_entry_relic_ids = {
                self._token(getattr(relic, "relic_id", ""))
                for relic in self.game.screen.relics
            }
            self.shop_entry_potion_counts = {}
            for potion in self.game.screen.potions:
                potion_id = self._token(
                    getattr(potion, "potion_id", "")
                )
                self.shop_entry_potion_counts[potion_id] = (
                    self.shop_entry_potion_counts.get(potion_id, 0) + 1
                )
        current_shop_card_ids = {
            getattr(card, "uuid", None) for card in self.game.screen.cards
        }
        self.shop_cards_bought = len(
            self.shop_entry_card_ids - current_shop_card_ids
        )
        current_shop_relic_ids = {
            self._token(getattr(relic, "relic_id", ""))
            for relic in self.game.screen.relics
        }
        self.shop_relics_bought = len(
            self.shop_entry_relic_ids - current_shop_relic_ids
        )
        current_shop_potion_counts = {}
        for potion in self.game.screen.potions:
            potion_id = self._token(getattr(potion, "potion_id", ""))
            current_shop_potion_counts[potion_id] = (
                current_shop_potion_counts.get(potion_id, 0) + 1
            )
        self.shop_potions_bought = sum(
            max(
                0,
                entry_count
                - current_shop_potion_counts.get(potion_id, 0),
            )
            for potion_id, entry_count
            in self.shop_entry_potion_counts.items()
        )
        pending_potion = self.pending_shop_potion_purchase or {}
        if (
            pending_potion.get("visit_key") == visit_key
            and gold < int(pending_potion.get("gold_before", gold) or 0)
        ):
            # Gold only changes after the bound BUY, not after DISCARD.
            self.pending_shop_potion_purchase = None
            pending_potion = {}
        pending_exact_potion = None
        pending_bound_unavailable = False
        if (
            pending_potion.get("visit_key") == visit_key
            and not self.game.are_potions_full()
        ):
            equivalent_potions = [
                potion
                for potion in self.game.screen.potions
                if self._token(getattr(potion, "potion_id", ""))
                == pending_potion.get("potion_id")
                and getattr(potion, "name", None)
                == pending_potion.get("name")
            ]
            occurrence = max(
                0, int(pending_potion.get("occurrence", 0) or 0)
            )
            exact_potion = (
                equivalent_potions[occurrence]
                if occurrence < len(equivalent_potions)
                else equivalent_potions[0]
                if equivalent_potions
                else None
            )
            if (
                exact_potion is not None
                and exact_potion.price <= gold
            ):
                pending_exact_potion = exact_potion
            else:
                # The desired listing disappeared or became unaffordable.
                # Preserve the complete visible surface below, but make every
                # substitute ineligible and leave rather than silently buying
                # a different listing in the bound transaction frame.
                pending_bound_unavailable = True
        visible_shop_candidates = []
        protocol_choice_index = 0
        # The audit surface follows the bridge listing order and retains every
        # protocol-visible listing.  Affordability and policy vetoes control
        # ``selection_eligible``; they must never delete a visible candidate.
        purge_visible = bool(self.game.screen.purge_available)
        purge_choice_index = getattr(
            self.game.screen, "protocol_purge_choice_index", None
        )
        # ``purge_available`` describes the underlying shop service, not the
        # current CHOICE surface.  CommunicationMod omits an unaffordable
        # purge from ``choice_list``.  Without an authoritative binding, a
        # local index-zero fallback collides with the first real shop item.
        # Retain the raw availability on the screen for audit, but emit a
        # producer candidate only when the bridge bound the protocol option.
        purge_protocol_bound = bool(
            type(purge_choice_index) is int and purge_choice_index >= 0
        )
        if purge_visible and purge_protocol_bound:
            curses = sum(
                1 for card in self.game.deck
                if card.rarity == spirecomm.spire.card.CardRarity.CURSE
            )
            starters = sum(
                1 for card in self.game.deck
                if card.card_id in {
                    "Strike_R", "Strike_G", "Strike_B",
                    "Defend_R", "Defend_G", "Defend_B",
                }
            )
            purge_value = (
                14 + curses * 26 + max(0, starters - 7) * 3
                - self.game.screen.purge_cost / 12.0
            )
            purge_action = ChooseAction(name="purge")
            purge_eligible = self.game.screen.purge_cost <= gold
            visible_shop_candidates.append({
                "choice_id": "purge",
                "choice_index": purge_choice_index,
                "kind": "purge",
                "item": None,
                "action_object": purge_action,
                "score": purge_value,
                "selection_eligible": purge_eligible,
                "veto_reason": (
                    None if purge_eligible else "insufficient_gold"
                ),
                "price": int(self.game.screen.purge_cost or 0),
                "score_evidence": self._linear_score_contract(
                    "shop_purge_utility_v1",
                    {
                        "base": 1.0,
                        "curse_count": curses,
                        "excess_starters": max(0, starters - 7),
                        "purge_cost": self.game.screen.purge_cost,
                    },
                    (
                        ("base_value", "base", 14.0),
                        ("curse_value", "curse_count", 26.0),
                        ("starter_reduction_value", "excess_starters", 3.0),
                        ("gold_cost_penalty", "purge_cost", -1.0 / 12.0),
                    ),
                ),
            })
            if purge_eligible:
                choices.append((purge_value, purge_action, "purge"))
            protocol_choice_index = max(
                protocol_choice_index, purge_choice_index + 1
            )

        for card in self.game.screen.cards:
            item_choice_index = int(getattr(
                card, "protocol_choice_index", protocol_choice_index
            ))
            card_score = self._card_reward_score(card)
            value = (
                card_score - card.price / 18.0
                - self.shop_cards_bought * 12.0
            )
            card_uuid = getattr(card, "uuid", None)
            choice_id = (
                f"shop:card:{card_uuid}:{item_choice_index}"
                if card_uuid else
                f"shop:card-missing-uuid:{item_choice_index}"
            )
            affordable = card.price <= gold
            within_copy_limit = self._within_copy_limit(card)
            eligible = bool(card_uuid and affordable and within_copy_limit)
            veto_reason = (
                None
                if eligible
                else "card_instance_uuid_missing"
                if not card_uuid
                else "insufficient_gold"
                if not affordable
                else "copy_limit"
            )
            action_object = BuyCardAction(card)
            visible_shop_candidates.append({
                "choice_id": choice_id,
                "choice_index": item_choice_index,
                "kind": "card",
                "item": card,
                "action_object": action_object,
                "score": value,
                "selection_eligible": eligible,
                "veto_reason": veto_reason,
                "price": int(card.price or 0),
                "score_evidence": self._linear_score_contract(
                    "shop_card_utility_v1",
                    {
                        "card_reward_score": card_score,
                        "price": card.price,
                        "prior_card_purchases": self.shop_cards_bought,
                    },
                    (
                        ("card_value", "card_reward_score", 1.0),
                        ("gold_cost_penalty", "price", -1.0 / 18.0),
                        ("repeat_purchase_penalty", "prior_card_purchases", -12.0),
                    ),
                ),
            })
            if eligible:
                choices.append((value, action_object, choice_id))
            protocol_choice_index = max(
                protocol_choice_index, item_choice_index + 1
            )
        relic_evaluations = []
        relic_purchase_floor = 8 if self.shop_relics_bought == 0 else 20
        for relic in self.game.screen.relics:
            item_choice_index = int(getattr(
                relic, "protocol_choice_index", protocol_choice_index
            ))
            relic_context_score = self._shop_relic_score(relic)
            relic_risk_context = dict(
                getattr(self, "_shop_relic_score_contexts", {}).get(
                    id(relic), {}
                )
            )
            value = (
                relic_context_score - relic.price / 16.0
                - self.shop_relics_bought * 12.0
            )
            choice_id = (
                f"shop:relic:{relic.relic_id}:{item_choice_index}"
            )
            action_object = BuyRelicAction(relic)
            affordable = relic.price <= gold
            relic_evaluations.append((
                choice_id, value, relic_purchase_floor,
            ))
            visible_shop_candidates.append({
                "choice_id": choice_id,
                "choice_index": item_choice_index,
                "kind": "relic",
                "item": relic,
                "action_object": action_object,
                "score": value,
                "selection_eligible": affordable,
                "veto_reason": None if affordable else "insufficient_gold",
                "price": int(relic.price or 0),
                "strategic_risk": relic_risk_context,
                "score_evidence": self._linear_score_contract(
                    "shop_relic_utility_v1",
                    {
                        "relic_positive_score": relic_risk_context.get(
                            "positive_score", relic_context_score
                        ),
                        "relic_downside_risk": relic_risk_context.get(
                            "downside_score", 0.0
                        ),
                        "price": relic.price,
                        "prior_relic_purchases": self.shop_relics_bought,
                    },
                    (
                        ("relic_value", "relic_positive_score", 1.0),
                        ("relic_downside_risk", "relic_downside_risk", -1.0),
                        ("gold_cost_penalty", "price", -1.0 / 16.0),
                        ("repeat_purchase_penalty", "prior_relic_purchases", -12.0),
                    ),
                ),
            })
            if affordable:
                choices.append((value, action_object, choice_id))
            protocol_choice_index = max(
                protocol_choice_index, item_choice_index + 1
            )
        affordable_potions = [
            potion for potion in self.game.screen.potions if potion.price <= gold
        ]
        replacement_targets = {}
        replacement_by_listing = {}
        if self.game.are_potions_full() and not self._has_relic("Sozu"):
            for replacement in self._potion_replacement_options(
                affordable_potions
            ):
                action_object, old, new, improvement = replacement
                current = replacement_by_listing.get(id(new))
                if current is None or float(improvement) > float(current[3]):
                    replacement_by_listing[id(new)] = replacement
        for potion in self.game.screen.potions:
            item_choice_index = int(getattr(
                potion, "protocol_choice_index", protocol_choice_index
            ))
            choice_id = (
                f"shop:potion:{potion.potion_id}:{item_choice_index}"
            )
            score = self._shop_potion_value(potion)
            potion_token = self._token(potion.potion_id)
            premium = potion_token in {
                "blockpotion", "cultistpotion", "dexteritypotion",
                "duplicationpotion", "entropicbrew", "fairypotion",
                "focuspotion", "gamblersbrew", "ghostinajar",
                "liquidmemories", "powerpotion", "speedpotion",
            }
            boss_soon = self._boss_encounter_imminent()
            low_hp = self.game.current_hp / max(1, self.game.max_hp) < 0.55
            veto_reason = None
            action_object = None
            affordable = potion.price <= gold
            if not affordable:
                veto_reason = "insufficient_gold"
            elif self._has_relic("Sozu"):
                veto_reason = "sozu_prevents_potion_purchase"
            elif not self.game.are_potions_full():
                action_object = BuyPotionAction(potion)
            else:
                replacement = replacement_by_listing.get(id(potion))
                if replacement is None:
                    veto_reason = "no_beneficial_bound_potion_replacement"
                else:
                    action_object, old, new, _improvement = replacement
                    replacement_targets[choice_id] = (old, new)
            eligible = action_object is not None
            visible_shop_candidates.append({
                "choice_id": choice_id,
                "choice_index": item_choice_index,
                "kind": "potion",
                "item": potion,
                "action_object": action_object,
                "score": score,
                "selection_eligible": eligible,
                "veto_reason": veto_reason,
                "price": int(potion.price or 0),
                "score_evidence": self._linear_score_contract(
                    "shop_potion_utility_v1",
                    {
                        "base": 1.0,
                        "premium": int(premium),
                        "boss_soon": int(boss_soon),
                        "low_hp": int(low_hp),
                        "price": potion.price,
                        "prior_potion_purchases": self.shop_potions_bought,
                    },
                    (
                        ("base_value", "base", 12.0),
                        ("premium_value", "premium", 11.0),
                        ("boss_readiness_value", "boss_soon", 8.0),
                        ("low_hp_value", "low_hp", 7.0),
                        ("gold_cost_penalty", "price", -1.0 / 11.0),
                        (
                            "repeat_purchase_penalty",
                            "prior_potion_purchases",
                            -4.0,
                        ),
                    ),
                ),
            })
            if eligible:
                choices.append((score, action_object, choice_id))
            protocol_choice_index = max(
                protocol_choice_index, item_choice_index + 1
            )

        for potion_listing in visible_shop_candidates:
            if (
                potion_listing.get("kind") != "potion"
                or not potion_listing.get("selection_eligible")
            ):
                continue
            post_purchase_gold = (
                int(gold) - int(potion_listing.get("price", 0) or 0)
            )
            blocked_relics = [
                relic_listing
                for relic_listing in visible_shop_candidates
                if relic_listing.get("kind") == "relic"
                and relic_listing.get("selection_eligible")
                and self._shop_discount_relic_factor(
                    relic_listing.get("item")
                ) is None
                and float(relic_listing.get("score", 0.0) or 0.0) >= 8.0
                and int(relic_listing.get("price", 0) or 0)
                > post_purchase_gold
            ]
            if not blocked_relics:
                continue
            blocked = max(
                blocked_relics,
                key=lambda row: float(row.get("score", 0.0) or 0.0),
            )
            blocked_score = float(blocked.get("score", 0.0) or 0.0)
            opportunity_penalty = min(
                8.0, 4.0 + max(0.0, blocked_score - 8.0) * 0.25
            )
            original_score = float(
                potion_listing.get("score", 0.0) or 0.0
            )
            potion_listing["score"] = original_score - opportunity_penalty
            potion_listing["score_evidence"] = self._linear_score_contract(
                "shop_potion_permanent_purchase_opportunity_v1",
                {
                    "original_potion_score": original_score,
                    "blocked_permanent_purchase_penalty": (
                        opportunity_penalty
                    ),
                },
                (
                    (
                        "original_potion_score",
                        "original_potion_score",
                        1.0,
                    ),
                    (
                        "blocked_permanent_purchase_penalty",
                        "blocked_permanent_purchase_penalty",
                        -1.0,
                    ),
                ),
            )
            potion_listing["strategic_risk"] = {
                "blocked_permanent_purchase": {
                    "choice_id": blocked["choice_id"],
                    "relic_id": getattr(
                        blocked.get("item"), "relic_id", None
                    ),
                    "relic_score": round(blocked_score, 3),
                    "relic_price": int(blocked.get("price", 0) or 0),
                    "post_potion_gold": post_purchase_gold,
                    "opportunity_penalty": round(
                        opportunity_penalty, 3
                    ),
                },
            }

        discount_priority_listing = None
        discount_plan_rows = []
        for listing in visible_shop_candidates:
            if listing.get("kind") != "relic":
                continue
            plan = self._shop_discount_relic_plan(
                listing, visible_shop_candidates, gold
            )
            if plan is None:
                continue
            discount_plan_rows.append((listing, plan))
            listing["strategic_risk"] = {
                **dict(listing.get("strategic_risk") or {}),
                "discount_purchase_order": plan,
            }
        eligible_discount_plans = [
            (listing, plan)
            for listing, plan in discount_plan_rows
            if plan["should_buy_first"]
            and listing.get("selection_eligible")
        ]
        if eligible_discount_plans:
            discount_priority_listing, priority_plan = max(
                eligible_discount_plans,
                key=lambda row: (
                    float(row[1]["basket_advantage"]),
                    -int(row[0]["price"]),
                ),
            )
            original_score = float(
                discount_priority_listing.get("score", 0.0) or 0.0
            )
            best_other_score = max(
                (
                    float(listing.get("score", 0.0) or 0.0)
                    for listing in visible_shop_candidates
                    if listing is not discount_priority_listing
                    and listing.get("selection_eligible")
                ),
                default=8.0,
            )
            order_bonus = max(
                0.0,
                best_other_score
                + max(0.5, float(priority_plan["basket_advantage"]))
                - original_score,
            )
            priority_score = original_score + order_bonus
            discount_priority_listing["score"] = priority_score
            discount_priority_listing["score_evidence"] = (
                self._linear_score_contract(
                    "shop_discount_relic_basket_order_v1",
                    {
                        "original_listing_score": original_score,
                        "basket_order_priority": order_bonus,
                    },
                    (
                        (
                            "original_listing_score",
                            "original_listing_score",
                            1.0,
                        ),
                        (
                            "basket_order_priority",
                            "basket_order_priority",
                            1.0,
                        ),
                    ),
                )
            )

        # Rebuild from the authoritative visible surface after discount-order
        # planning so local comparison, macro advice, and audit rows all see
        # the same adjusted candidate scores.
        choices = [
            (
                float(listing["score"]),
                listing["action_object"],
                listing["choice_id"],
            )
            for listing in visible_shop_candidates
            if listing.get("selection_eligible")
            and listing.get("action_object") is not None
        ]
        relic_evaluations = [
            (
                listing["choice_id"],
                float(listing["score"]),
                relic_purchase_floor,
            )
            for listing in visible_shop_candidates
            if listing.get("kind") == "relic"
        ]

        def shop_audit_rows(
            selected_choice_id,
            leave_score,
            *,
            leave_eligible=True,
            leave_veto_reason=None,
        ):
            rows = []
            for listing in visible_shop_candidates:
                item = listing["item"]
                operation = (
                    "open_card_purge_grid"
                    if listing["kind"] == "purge"
                    else f"buy_{listing['kind']}_then_rerank_shop"
                )
                price = int(listing["price"])
                consequences = {
                    "current_cost": {
                        "gold": price, "hp": 0, "max_hp": 0,
                    },
                    "operation": operation,
                    "probabilistic_outcomes": [],
                }
                if listing["kind"] == "purge":
                    consequences.update({
                        "hp_delta": 0,
                        "max_hp_delta": 0,
                        "gold_delta": 0,
                        "card_changes": {
                            "gain": [], "remove": [],
                            "upgrade": [], "transform": [],
                        },
                        "relic_changes": {
                            "gain": [], "remove": [], "counter": [],
                        },
                        "potion_changes": {
                            "gain": [], "remove": [], "replace": [],
                        },
                        "future_costs": [{
                            "kind": "shop_purge_grid_selection",
                            "operation": "purge",
                            "select_count": 1,
                            "identity_binding": (
                                "subsequent_grid_card_instance_id"
                            ),
                            "commit_timing": "after_grid_confirmation",
                            "gold_cost": price,
                        }],
                    })
                    consequences["current_cost"] = {
                        "gold": 0, "hp": 0, "max_hp": 0,
                    }
                elif listing["kind"] == "card":
                    item_facts = self._audit_card_instance_facts(
                        item, include_price=True
                    )
                    consequences.update({
                        "hp_delta": 0,
                        "max_hp_delta": 0,
                        "gold_delta": (
                            -price + (9 if self._has_relic("CeramicFish") else 0)
                        ),
                        "card_changes": {
                            "gain": [item_facts], "remove": [],
                            "upgrade": [], "transform": [],
                        },
                        "acquired_benefit": {
                            "kind": "card",
                            "id": item_facts.get("id"),
                            "card_id": item_facts.get("id"),
                            "card_instance_id": item_facts.get(
                                "card_instance_id"
                            ),
                        },
                    })
                elif listing["kind"] == "potion":
                    potion_facts = self._audit_potion_listing_facts(item)
                    consequences.update({
                        "hp_delta": 0,
                        "max_hp_delta": 0,
                        "gold_delta": -price,
                        "potion_changes": {
                            "gain": [potion_facts],
                            "remove": [], "replace": [],
                        },
                        "acquired_benefit": {
                            "kind": "potion",
                            "id": potion_facts.get("id"),
                            "potion_id": potion_facts.get("id"),
                        },
                    })
                else:
                    relic_facts = self._audit_relic_listing_facts(item)
                    consequences["relic_changes"] = {
                        "gain": [relic_facts], "remove": [], "counter": [],
                    }
                    consequences["acquired_benefit"] = {
                        "kind": "relic",
                        "id": relic_facts.get("id"),
                        "relic_id": relic_facts.get("id"),
                    }
                    relic_token = self._token(getattr(item, "relic_id", ""))
                    pickup = {
                        "mango": (14, 14, 0),
                        "oldcoin": (0, 0, 300),
                        "pear": (10, 10, 0),
                        "strawberry": (7, 7, 0),
                    }.get(relic_token)
                    if pickup is None and relic_token in {
                        "blackstar", "coffeedripper", "datadisk",
                    }:
                        pickup = (0, 0, 0)
                    if pickup is not None:
                        hp_delta, max_hp_delta, gold_delta = pickup
                        consequences.update({
                            "hp_delta": hp_delta,
                            "max_hp_delta": max_hp_delta,
                            "gold_delta": gold_delta - price,
                        })
                    if relic_token == "orrery":
                        consequences.update({
                            "hp_delta": 0,
                            "max_hp_delta": 0,
                            "gold_delta": -price,
                            "card_changes": {
                                "gain": [], "remove": [],
                                "upgrade": [], "transform": [],
                            },
                            "potion_changes": {
                                "gain": [], "remove": [], "replace": [],
                            },
                            "curse": {
                                "gain": [], "remove": [],
                                "probability": 0.0,
                                "omamori_applicable": False,
                                "omamori_charges_consumed": 0,
                            },
                            "future_costs": [{
                                "kind": "optional_card_reward_sequence",
                                "relic_id": "Orrery",
                                "card_pool": "CHARACTER",
                                "reward_count": 5,
                                "candidates_per_reward": max(
                                    1,
                                    3
                                    + int(self._has_relic("Question Card"))
                                    - 2 * int(
                                        self._has_relic("Busted Crown")
                                    ),
                                ),
                                "select_count_per_reward": 1,
                                "can_skip": True,
                                "timing": "after_relic_purchase",
                            }],
                        })
                rows.append({
                    "id": (
                        "purge"
                        if listing["kind"] == "purge"
                        else getattr(
                            item,
                            "card_id",
                            getattr(
                                item,
                                "relic_id",
                                getattr(item, "potion_id", listing["choice_id"]),
                            ),
                        )
                    ),
                    "choice_id": listing["choice_id"],
                    "choice_index": listing["choice_index"],
                    "action": "choose",
                    "semantic_id": (
                        f"shop:purge:{listing['choice_index']}:"
                        f"{listing['choice_index']}"
                        if listing["kind"] == "purge"
                        else listing["choice_id"]
                    ),
                    "score": float(listing["score"]),
                    "label": getattr(item, "name", listing["kind"]),
                    "legal": True,
                    "visible": True,
                    "selection_eligible": listing[
                        "selection_eligible"
                    ],
                    "veto_reason": listing["veto_reason"],
                    "reason": (
                        "selected_purchase"
                        if listing["choice_id"] == selected_choice_id
                        else listing["veto_reason"]
                        or "visible_unchosen_listing"
                    ),
                    "consequences": consequences,
                    **(
                        {"strategic_risk": listing["strategic_risk"]}
                        if listing.get("strategic_risk") is not None
                        else {}
                    ),
                    **listing["score_evidence"],
                })
            rows.append({
                "id": "leave",
                "choice_id": "action:return",
                "choice_index": None,
                "action": "return",
                "semantic_id": "shop_leave",
                "score": float(leave_score),
                "label": "Leave shop",
                "legal": True,
                "visible": True,
                "selection_eligible": leave_eligible,
                "veto_reason": leave_veto_reason,
                "reason": (
                    "selected_leave"
                    if selected_choice_id == "action:return"
                    else "preserve_gold"
                ),
                "consequences": {
                    "hp_delta": 0,
                    "max_hp_delta": 0,
                    "gold_delta": 0,
                    "card_changes": {
                        "gain": [], "remove": [],
                        "upgrade": [], "transform": [],
                    },
                    "relic_changes": {
                        "gain": [], "remove": [], "counter": [],
                    },
                    "potion_changes": {
                        "gain": [], "remove": [], "replace": [],
                    },
                    "probabilistic_outcomes": [],
                    "current_cost": {"gold": 0, "hp": 0, "max_hp": 0},
                    "future_costs": [],
                    "operation": "return",
                },
                **self._linear_score_contract(
                    "shop_leave_floor_v1",
                    {"leave_floor": leave_score},
                    (("leave_floor", "leave_floor", 1.0),),
                ),
            })
            return rows

        identity_complete = all(
            listing["kind"] != "card"
            or bool(getattr(listing["item"], "uuid", None))
            for listing in visible_shop_candidates
        )
        if pending_exact_potion is not None:
            exact_listing = next(
                (
                    listing for listing in visible_shop_candidates
                    if listing["kind"] == "potion"
                    and listing["item"] is pending_exact_potion
                ),
                None,
            )
            if exact_listing is None:
                pending_bound_unavailable = True
            else:
                for listing in visible_shop_candidates:
                    listing["selection_eligible"] = (
                        listing is exact_listing
                    )
                    listing["veto_reason"] = (
                        None if listing is exact_listing
                        else "pending_bound_potion_transaction"
                    )
                selected_id = exact_listing["choice_id"]
                self._record_noncombat_decision(
                    "shop_bound_potion_replacement_purchase",
                    shop_audit_rows(
                        selected_id,
                        0.0,
                        leave_eligible=False,
                        leave_veto_reason=(
                            "pending_bound_potion_transaction"
                        ),
                    ),
                    candidate_contract={
                        "score_source": "bound_transaction_fail_closed",
                        "strategy_quality_auditable": identity_complete,
                        "all_visible_options_scored": True,
                        "return_command_included": True,
                        "visible_option_count": len(
                            visible_shop_candidates
                        ) + 1,
                        "selection_eligible_count": 1,
                        "filtered_options_retained": True,
                        "identity_source": "protocol_listing_instance",
                    },
                    chosen=pending_exact_potion.potion_id,
                    chosen_id=selected_id,
                    replaced=pending_potion.get("replaced"),
                    visit_key=list(visit_key),
                )
                return BuyPotionAction(pending_exact_potion)
        if pending_bound_unavailable:
            for listing in visible_shop_candidates:
                listing["selection_eligible"] = False
                listing["veto_reason"] = "bound_listing_unavailable"
            self.pending_shop_potion_purchase = None
            self.shop_completed_visit_key = visit_key
            self._record_noncombat_decision(
                "shop_bound_potion_replacement_unavailable",
                shop_audit_rows("action:return", 0.0),
                candidate_contract={
                    "score_source": "bound_transaction_fail_closed",
                    "strategy_quality_auditable": identity_complete,
                    "all_visible_options_scored": True,
                    "return_command_included": True,
                    "visible_option_count": len(
                        visible_shop_candidates
                    ) + 1,
                    "selection_eligible_count": 1,
                    "filtered_options_retained": True,
                    "identity_source": "protocol_listing_instance",
                },
                chosen="cancel",
                chosen_id="action:return",
                requested=pending_potion.get("potion_id"),
                visit_key=list(visit_key),
            )
            return CancelAction()
        if not choices:
            self.shop_completed_visit_key = visit_key
            self._record_noncombat_decision(
                "shop_no_positive_purchase",
                shop_audit_rows("action:return", 0.0),
                candidate_contract={
                    "score_source": "shop_visible_listing_utility",
                    "strategy_quality_auditable": identity_complete,
                    "all_visible_options_scored": True,
                    "return_command_included": True,
                    "visible_option_count": len(
                        visible_shop_candidates
                    ) + 1,
                    "selection_eligible_count": 1,
                    "filtered_options_retained": True,
                    "identity_source": "protocol_listing_instance",
                    "incomplete_reason": (
                        None if identity_complete
                        else "shop_card_instance_uuid_missing"
                    ),
                },
                chosen="leave",
                chosen_id="action:return",
                relic_candidates=[
                    {
                        "id": relic_id,
                        "score": round(float(value), 3),
                        "required": required,
                    }
                    for relic_id, value, required in relic_evaluations
                ],
                shop_relics_bought=self.shop_relics_bought,
            )
            return CancelAction()
        above_floor_choices = [
            item for item in choices
            if self._shop_action_above_floor(
                item[1], item[0], gold=gold
            )
        ]
        value, action, chosen_id = max(
            above_floor_choices or choices,
            key=lambda item: item[0],
        )
        macro_choice_map = {}
        macro_candidates = []
        rule_macro_id = "action:return"
        for index, (candidate_value, candidate_action, item_id) in enumerate(choices):
            # ``item_id`` is already the stable protocol-facing listing id
            # (including its choice index).  Wrapping it a second time made
            # model replay ids diverge from the exact visible candidate ids.
            macro_id = str(item_id)
            macro_choice_map[macro_id] = (
                candidate_value, candidate_action, item_id
            )
            item = getattr(candidate_action, "card", None)
            if item is None:
                item = getattr(candidate_action, "relic", None)
            if item is None:
                item = getattr(candidate_action, "potion", None)
            facts = {
                "price": int(getattr(item, "price", 0) or 0),
                "item_id": item_id,
                "description": self._macro_description(
                    getattr(item, "description", "")
                ),
            }
            facts["post_purchase_gold"] = max(
                0, int(gold) - int(facts["price"])
            )
            if isinstance(candidate_action, BuyCardAction):
                facts["operation"] = "buy_card_then_rerank_shop"
                shop_card_facts = self._macro_card_candidate_facts(
                    candidate_action.card, shop_profile
                )
                # The compact wire format turns nested card facts into one
                # positional row. Keep candidate-specific deck support beside
                # that row so it is not mistaken for a card database field or
                # dropped during compaction.
                facts["deck_context"] = shop_card_facts.pop(
                    "deck_context", {}
                )
                facts["card"] = shop_card_facts
            elif isinstance(candidate_action, BuyRelicAction):
                facts["operation"] = "buy_relic_then_rerank_shop"
                facts["relic_id"] = getattr(
                    candidate_action.relic, "relic_id", None
                )
            elif isinstance(candidate_action, BuyPotionAction):
                facts["operation"] = "buy_potion_then_rerank_shop"
                facts["potion_id"] = getattr(
                    candidate_action.potion, "potion_id", None
                )
            elif item_id in replacement_targets:
                old, new = replacement_targets[item_id]
                new_price = int(getattr(new, "price", 0) or 0)
                facts.update({
                    "operation": "replace_potion_then_buy_exact_listing",
                    "price": new_price,
                    "post_purchase_gold": max(0, int(gold) - new_price),
                    "old_potion": {
                        "id": getattr(old, "potion_id", None),
                        "description": self._macro_description(
                            getattr(old, "description", "")
                        ),
                        "keep_value": round(
                            float(self._potion_keep_score(old)), 3
                        ),
                    },
                    "new_potion": {
                        "id": getattr(new, "potion_id", None),
                        "description": self._macro_description(
                            getattr(new, "description", "")
                        ),
                        "keep_value": round(
                            float(self._potion_keep_score(new)), 3
                        ),
                    },
                    "replacement_improvement": round(
                        float(
                            self._potion_keep_score(new)
                            - self._potion_keep_score(old)
                        ),
                        3,
                    ),
                })
            elif (
                isinstance(candidate_action, ChooseAction)
                and self._token(getattr(candidate_action, "name", ""))
                == "purge"
            ):
                purge_cost = int(
                    getattr(self.game.screen, "purge_cost", 0) or 0
                )
                facts.update({
                    "operation": "purge_one_card_then_rerank_shop",
                    "price": purge_cost,
                    "post_purchase_gold": max(0, int(gold) - purge_cost),
                    "selection_semantics": (
                        "highest removal_value is best to remove"
                    ),
                    "projected_target": (
                        {
                            "removal_value": round(
                                float(self._removal_score(purge_target)), 3
                            ),
                            "card": self._macro_card_facts(purge_target),
                        }
                        if purge_target is not None else None
                    ),
                })
            macro_candidates.append({
                "candidate_id": macro_id,
                "kind": type(candidate_action).__name__,
                "label": getattr(candidate_action, "name", item_id),
                "local_score": candidate_value,
                "facts": facts,
            })
            if candidate_action is action:
                rule_macro_id = macro_id
        leave_score = 8.0
        if (
            isinstance(action, BuyPotionAction)
            and value < 8.0
            and self._shop_action_above_floor(action, value, gold=gold)
        ):
            # Keep a low-floor potion visible to the macro ranker without
            # letting the synthetic Leave candidate win solely because it
            # has the historic fixed score of eight.
            leave_score = 6.0
        elif (
            isinstance(action, ChooseAction)
            and self._token(getattr(action, "name", "")) == "purge"
            and value < 8.0
            and self._shop_action_above_floor(action, value, gold=gold)
        ):
            # Keep a worthwhile removal visible to the macro ranker.  A
            # stale model preference for Leave must not erase a permanent
            # deck improvement simply because its local score is 7.x.
            leave_score = 5.0
        elif (
            isinstance(action, BuyRelicAction)
            and value < 8.0
            and self._shop_action_above_floor(action, value, gold=gold)
        ):
            # A useful near-floor relic should beat preserving hundreds of
            # gold when HP is already critical. Keep the audit/model surface
            # explicit by lowering Leave rather than inflating relic value.
            leave_score = 6.0
        macro_candidates.append({
            "candidate_id": "action:return",
            "kind": "leave",
            "label": "Leave shop",
            "local_score": leave_score,
            "facts": {"gold_preserved": int(gold)},
        })
        if not self._shop_action_above_floor(action, value, gold=gold):
            rule_macro_id = "action:return"
        selected_macro_id = self._macro_rank(
            "SHOP",
            macro_candidates,
            rule_macro_id,
            hard_constraints=[
                "ONLY_AFFORDABLE_LISTED_PURCHASES",
                "POTION_REPLACEMENT_IS_BOUND_TWO_STEP_TRANSACTION",
                "DO_NOT_SPEND_UNAVAILABLE_GOLD",
                "BUY_PROFITABLE_DISCOUNT_RELIC_BEFORE_PLANNED_BASKET",
            ],
            state_details={
                "gold": int(gold),
                "purge_cost": int(
                    getattr(self.game.screen, "purge_cost", 0) or 0
                ),
                "shop_cards_bought": self.shop_cards_bought,
                "shop_relics_bought": self.shop_relics_bought,
                "shop_potions_bought": self.shop_potions_bought,
                "transaction_semantics": (
                    "choose exactly one action, execute it, then rerank the "
                    "remaining shop with updated gold and slots"
                ),
                "potion_slots_full": bool(self.game.are_potions_full()),
                "discount_purchase_order": (
                    (
                        discount_priority_listing.get("strategic_risk") or {}
                    ).get("discount_purchase_order")
                    if discount_priority_listing is not None
                    else None
                ),
            },
        )[0]
        if discount_priority_listing is not None:
            # The basket comparison is a transaction-order constraint.  Model
            # fusion may compare item quality, but it cannot realize the same
            # basket by purchasing a full-price item before the discount.
            selected_macro_id = discount_priority_listing["choice_id"]
        if selected_macro_id == "action:return":
            # If the only sub-eight candidate is a worthwhile affordable
            # potion, do not let a stale Leave floor discard it.  This is a
            # deterministic safety override; model advice remains free to
            # choose among actual purchases.
            if (
                isinstance(action, BuyPotionAction)
                and value < 8.0
                and self._shop_action_above_floor(action, value, gold=gold)
            ):
                selected_macro_id = rule_macro_id
            elif (
                isinstance(action, ChooseAction)
                and self._token(getattr(action, "name", "")) == "purge"
                and value < 8.0
                and self._shop_action_above_floor(action, value, gold=gold)
            ):
                selected_macro_id = rule_macro_id
            elif (
                isinstance(action, BuyRelicAction)
                and value < 8.0
                and self._shop_action_above_floor(action, value, gold=gold)
            ):
                selected_macro_id = rule_macro_id
            else:
                value, action, chosen_id = leave_score, CancelAction(), "leave"
        if selected_macro_id != "action:return":
            value, action, chosen_id = macro_choice_map[selected_macro_id]
        selected_audit_id = (
            "action:return" if chosen_id == "leave" else chosen_id
        )
        shop_audit_candidates = shop_audit_rows(
            selected_audit_id, leave_score
        )
        self._record_noncombat_decision(
            "shop_global_comparison",
            shop_audit_candidates,
            candidate_contract={
                "score_source": "shop_global_net_utility",
                "strategy_quality_auditable": identity_complete,
                "all_visible_options_scored": True,
                "return_command_included": True,
                "visible_option_count": len(visible_shop_candidates) + 1,
                "selection_eligible_count": sum(
                    row["selection_eligible"]
                    for row in visible_shop_candidates
                ) + 1,
                "filtered_options_retained": True,
                "identity_source": "protocol_listing_instance",
                "incomplete_reason": (
                    None if identity_complete
                    else "shop_card_instance_uuid_missing"
                ),
            },
            chosen=chosen_id,
            chosen_id=selected_audit_id,
            gold=gold,
            deck_plan=self._deck_plan_summary(),
            relic_candidates=[
                {
                    "id": relic_id,
                    "score": round(float(candidate_value), 3),
                    "required": required,
                }
                for relic_id, candidate_value, required in relic_evaluations
            ],
            shop_relics_bought=self.shop_relics_bought,
            shop_potions_bought=self.shop_potions_bought,
        )
        if (
            not self._shop_action_above_floor(action, value, gold=gold)
            or chosen_id == "leave"
        ):
            self.shop_completed_visit_key = visit_key
            return CancelAction()
        if chosen_id in replacement_targets:
            old, new = replacement_targets[chosen_id]
            selected_parent_rows = [
                (index, potion)
                for index, potion in enumerate(self.game.screen.potions)
                if potion is new
            ]
            if len(selected_parent_rows) != 1:
                raise ValueError("selected shop potion listing is not unique")
            parent_choice_index = getattr(new, "protocol_choice_index", None)
            parent_listing_id = getattr(new, "protocol_option_id", None)
            parent_item_id = getattr(new, "potion_id", None)
            parent_price = getattr(new, "price", None)
            if (
                type(parent_choice_index) is not int
                or not isinstance(parent_listing_id, str)
                or not parent_listing_id
                or not isinstance(parent_item_id, str)
                or not parent_item_id
                or type(parent_price) is not int
                or parent_price < 0
            ):
                raise ValueError(
                    "selected shop potion lacks an authoritative protocol listing"
                )
            parent_binding = {
                "bound_purchase_listing_id": parent_listing_id,
                "bound_purchase_choice_index": parent_choice_index,
                "bound_purchase_item_id": parent_item_id,
                "bound_purchase_price": parent_price,
            }
            matching_new = [
                potion
                for potion in self.game.screen.potions
                if self._token(getattr(potion, "potion_id", ""))
                == self._token(getattr(new, "potion_id", ""))
                and getattr(potion, "name", None)
                == getattr(new, "name", None)
            ]
            occurrence = next(
                (
                    index
                    for index, potion in enumerate(matching_new)
                    if potion is new
                ),
                0,
            )
            self.pending_shop_potion_purchase = {
                "visit_key": visit_key,
                "potion_id": self._token(getattr(new, "potion_id", "")),
                "name": getattr(new, "name", None),
                "occurrence": occurrence,
                "quoted_price": int(getattr(new, "price", 0) or 0),
                "replaced": getattr(old, "potion_id", None),
                "gold_before": int(gold),
            }
            held_potions = list(self.game.get_real_potions() or [])
            preparation_candidates, selected_preparation_id = (
                self._potion_resource_preparation_candidates(
                    held_potions,
                    new,
                    action,
                    old,
                    parent_operation="bound_purchase",
                    parent_binding=parent_binding,
                )
            )
            self._record_noncombat_decision(
                "shop_potion_replacement_resource_preparation",
                preparation_candidates,
                candidate_contract={
                    "score_source": "bound_potion_replacement_net_gain",
                    "strategy_quality_auditable": True,
                    "all_visible_options_scored": True,
                    "visible_option_count": len(preparation_candidates),
                    "identity_source": (
                        "potion_instance_slot_and_operation"
                    ),
                    "parent_screen_resolution_pending": True,
                },
                chosen=getattr(old, "potion_id", None),
                chosen_id=selected_preparation_id,
                bound_purchase_potion_id=getattr(new, "potion_id", None),
                **parent_binding,
            )
        return action

    def _localized_neow_option_score_is_not_authoritative(self, option):
        """Score Neow rewards by net run value instead of visible order."""

        raw_text = str(
            f"{getattr(option, 'label', '')} {getattr(option, 'text', '')}"
        ).lower()
        text = self._token(raw_text)
        if "bossrelic" in text or "boss遗物" in text:
            return 9.0 if self.chosen_class == PlayerClass.THE_SILENT else 11.0

        if (
            "接下来3场战斗" in text
            or "next3combats" in text
            or "nextthreecombats" in text
        ):
            reward = 21.0
        elif "250金币" in text or "250gold" in text:
            reward = 26.0
        elif "去除2张牌" in text or "移除2张牌" in text or "remove2cards" in text:
            reward = 24.0
        elif "变化2张牌" in text or "transform2cards" in text:
            reward = 22.0
        elif "稀有遗物" in text or "rarerelic" in text:
            reward = 23.0
        elif "最大生命14" in text or "14maxhp" in text:
            reward = 18.0
        elif (
            "稀有无色牌" in text
            or "rarecolorless" in text
            or "选择并获得一张稀有牌" in text
            or "chooseararecard" in text
        ):
            reward = 17.0
        elif "获得100金币" in text or "gain100gold" in text or "100gold" in text:
            reward = 15.0
        elif "从牌组中移除一张牌" in text or "removeacard" in text:
            reward = 14.0
        elif "随机获得一张稀有牌" in text or "randomrarecard" in text:
            reward = 13.0
        elif "升级一张牌" in text or "upgradeacard" in text:
            reward = 12.0
        elif "获得3瓶药水" in text or "gain3potions" in text or "3potions" in text:
            reward = 12.0
        elif "最大生命值7" in text or "7maxhp" in text:
            reward = 10.0
        elif "变化一张牌" in text or "transformacard" in text:
            reward = 11.0
        elif "无色牌" in text or "colorlesscard" in text:
            reward = 7.0
        elif "选择并获得一张牌" in text or "chooseacard" in text:
            reward = 9.0
        else:
            reward = 0.0

        if "诅咒" in text or "curse" in text:
            reward -= 12.0
        if "失去所有金币" in text or "loseallgold" in text:
            reward -= min(16.0, max(8.0, float(getattr(self.game, "gold", 0) or 0) / 8.0))
        damage_values = [
            int(value)
            for value in re.findall(
                r"(?:take|lose|suffer|受到|失去|承受)\s*(\d+)\s*(?:点)?(?:hp|health|damage|生命|伤害)",
                raw_text,
                flags=re.IGNORECASE,
            )
        ]
        max_hp_values = [
            int(value)
            for value in re.findall(
                r"(?:lose|失去|减少)\s*(\d+)\s*(?:点)?(?:max\s*hp|max\s*health|最大生命)",
                raw_text,
                flags=re.IGNORECASE,
            )
        ]
        if max_hp_values:
            reward -= max(max_hp_values) * 1.15
        if damage_values:
            hp_cost = max(damage_values)
            current_hp = max(
                1, int(getattr(self.game, "current_hp", 1) or 1)
            )
            if hp_cost >= current_hp:
                return -1000.0
            hp_ratio_after = (current_hp - hp_cost) / max(
                1,
                int(
                    getattr(self.game, "max_hp", current_hp)
                    or current_hp
                ),
            )
            reward -= hp_cost * (
                0.55 + max(0.0, 0.65 - hp_ratio_after)
            )
        return reward

    _NEOW_REWARD_VALUES = {
        "RANDOM_COLORLESS_2": 17.0,
        "THREE_CARDS": 9.0,
        "ONE_RANDOM_RARE_CARD": 13.0,
        "REMOVE_CARD": 14.0,
        "UPGRADE_CARD": 12.0,
        "RANDOM_COLORLESS": 7.0,
        "TRANSFORM_CARD": 11.0,
        "THREE_SMALL_POTIONS": 12.0,
        "RANDOM_COMMON_RELIC": 16.0,
        "TEN_PERCENT_HP_BONUS": 10.0,
        "HUNDRED_GOLD": 15.0,
        "THREE_ENEMY_KILL": 21.0,
        "REMOVE_TWO": 24.0,
        "TRANSFORM_TWO_CARDS": 22.0,
        "ONE_RARE_RELIC": 23.0,
        "THREE_RARE_CARDS": 17.0,
        "TWO_FIFTY_GOLD": 26.0,
        "TWENTY_PERCENT_HP_BONUS": 18.0,
        "BOSS_RELIC": 11.0,
    }
    _NEOW_DRAWBACKS = {
        "NONE", "TEN_PERCENT_HP_LOSS", "NO_GOLD", "CURSE",
        "PERCENT_DAMAGE",
    }

    @classmethod
    def _typed_neow_contract(cls, option):
        value = getattr(option, "neow_contract", None)
        if not isinstance(value, dict) or value.get("contract_version") != 1:
            return None
        kind = value.get("contract_kind")
        if kind == "NEOW_DIALOG_ADVANCE":
            if (
                set(value) != {
                    "contract_version", "contract_kind", "screen_num",
                    "resource_effect",
                }
                or type(value.get("screen_num")) is not int
                or value.get("screen_num") == 3
                or value.get("resource_effect") != "NONE"
            ):
                return None
            return copy.deepcopy(value)
        if (
            kind != "NEOW_REWARD"
            or set(value) != {
                "contract_version", "contract_kind", "reward_kind",
                "drawback_kind", "parameters",
            }
            or value.get("reward_kind") not in cls._NEOW_REWARD_VALUES
            or value.get("drawback_kind") not in cls._NEOW_DRAWBACKS
        ):
            return None
        parameters = value.get("parameters")
        if (
            isinstance(parameters, dict)
            and value.get("drawback_kind") == "NONE"
            and set(parameters) == {"hp_bonus", "cursed"}
        ):
            # Gson omits null map values on the wire.  CommunicationMod uses a
            # null private drawback definition for the public NONE drawback,
            # so restore exactly that omitted null just as bridge.py does.
            # Without this normalization every free Neow option is rejected
            # while costly options with a non-null drawback remain selectable.
            value = copy.deepcopy(value)
            value["parameters"]["drawback_def_kind"] = None
            parameters = value["parameters"]
        if (
            not isinstance(parameters, dict)
            or set(parameters) != {
                "hp_bonus", "cursed", "drawback_def_kind",
            }
            or type(parameters.get("hp_bonus")) is not int
            or type(parameters.get("cursed")) is not bool
            or (
                parameters.get("drawback_def_kind") is not None
                and parameters.get("drawback_def_kind")
                not in cls._NEOW_DRAWBACKS
            )
            or (
                parameters.get("drawback_def_kind") is not None
                and parameters.get("drawback_def_kind")
                != value.get("drawback_kind")
            )
        ):
            return None
        return copy.deepcopy(value)

    @staticmethod
    def _neow_mechanism_id(contract):
        encoded = json.dumps(
            contract,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
        return "neow-mechanism:" + hashlib.sha256(encoded).hexdigest()[:20]

    def _neow_option_score_parts(self, option):
        """Return typed score components; localized text is display-only."""

        contract = self._typed_neow_contract(option)
        if contract is None:
            return None, None
        if contract["contract_kind"] == "NEOW_DIALOG_ADVANCE":
            return contract, {"dialog_advance_value": 0.0}

        reward_kind = contract["reward_kind"]
        drawback_kind = contract["drawback_kind"]
        reward_value = float(self._NEOW_REWARD_VALUES[reward_kind])
        if reward_kind in {
            "THREE_CARDS", "RANDOM_COLORLESS", "RANDOM_COLORLESS_2",
            "THREE_RARE_CARDS",
        }:
            # These rewards open a skippable three-card screen.  Their value is
            # option value, not a guaranteed card gain.  In particular, do not
            # pay a large Neow HP cost using a fixed rare-card credit and then
            # rationally skip all three cards when the realized offer is weak.
            # Reuse the contextual optional-reward model used by Sensory Stone
            # and adjust only for the pool quality exposed by the typed JAR
            # contract.
            option_profile = self._optional_colorless_reward_profile(1)
            pool_quality = {
                "RANDOM_COLORLESS": 1.0,
                "RANDOM_COLORLESS_2": 1.4,
                "THREE_CARDS": 1.5,
                "THREE_RARE_CARDS": 2.2,
            }[reward_kind]
            reward_value = float(
                option_profile["expected_card_option_value"]
            ) * pool_quality
        if (
            reward_kind == "BOSS_RELIC"
            and self.chosen_class == PlayerClass.THE_SILENT
        ):
            reward_value = 9.0

        current_hp = max(
            1, int(getattr(self.game, "current_hp", 1) or 1)
        )
        max_hp = max(
            1, int(getattr(self.game, "max_hp", current_hp) or current_hp)
        )
        drawback_cost = 0.0
        if drawback_kind == "CURSE":
            drawback_cost = -12.0
        elif drawback_kind == "NO_GOLD":
            drawback_cost = -min(
                16.0,
                max(
                    8.0,
                    float(getattr(self.game, "gold", 0) or 0) / 8.0,
                ),
            )
        elif drawback_kind == "TEN_PERCENT_HP_LOSS":
            max_hp_loss = max(1, int(max_hp * 0.10))
            drawback_cost = -max_hp_loss * 1.15
        elif drawback_kind == "PERCENT_DAMAGE":
            hp_loss = max(1, int(current_hp * 0.30))
            hp_after = current_hp - hp_loss
            if hp_after <= 0:
                drawback_cost = -1000.0
            else:
                drawback_cost = -hp_loss * (
                    0.55 + max(0.0, 0.65 - hp_after / max_hp)
                )
        return contract, {
            "typed_reward_value": reward_value,
            "typed_drawback_cost": drawback_cost,
        }

    def _neow_option_score(self, option):
        _contract, parts = self._neow_option_score_parts(option)
        # Missing typed evidence stays visible, but the emitted unclassified
        # score envelope below keeps replay fail-closed.  Never fall back to
        # localized label/text.
        return sum(parts.values()) if parts is not None else 0.0

    def _neow_typed_consequences(self, contract):
        event_id = getattr(
            getattr(self.game, "screen", None), "event_id", None
        ) or "Neow Event"
        if contract is None:
            return {
                "operation": "unclassified_neow_contract",
                "uncertainty": "authoritative typed Neow contract missing",
            }
        mechanism_id = self._neow_mechanism_id(contract)
        if contract["contract_kind"] == "NEOW_DIALOG_ADVANCE":
            return {
                "operation": "neow_dialog_advance",
                "event_id": event_id,
                "mechanism_id": mechanism_id,
                "neow_contract": contract,
                "reward_kind": None,
                "drawback_kind": "NONE",
                "parameters": {
                    "screen_num": contract["screen_num"],
                    "resource_effect": "NONE",
                },
                "random_effects": [],
                "hp_delta": 0,
                "max_hp_delta": 0,
                "gold_delta": 0,
                "future_costs": [],
            }

        reward = contract["reward_kind"]
        drawback = contract["drawback_kind"]
        parameters = copy.deepcopy(contract["parameters"])
        result = {
            "operation": "neow_reward",
            "event_id": event_id,
            "mechanism_id": mechanism_id,
            "neow_contract": copy.deepcopy(contract),
            "reward_kind": reward,
            "drawback_kind": drawback,
            "parameters": parameters,
            "random_effects": [],
            "hp_delta": 0,
            "max_hp_delta": 0,
            "gold_delta": 0,
            "future_costs": [],
        }
        random_profiles = {
            "ONE_RANDOM_RARE_CARD": (
                "card_gain", "character_cards", ["RARE"]
            ),
            "RANDOM_COMMON_RELIC": (
                "relic_gain", "common_relics", ["COMMON"]
            ),
            "ONE_RARE_RELIC": (
                "relic_gain", "rare_relics", ["RARE"]
            ),
            "BOSS_RELIC": (
                "relic_gain", "boss_relics", ["BOSS"]
            ),
        }
        if reward in random_profiles:
            effect_kind, domain, rarities = random_profiles[reward]
            result["random_effects"].append({
                "kind": effect_kind,
                "domain": domain,
                "rarities": rarities,
                "count": 1,
                "timing": "immediate",
                "selection_mode": "random",
            })
        followups = {
            "THREE_CARDS": {
                "kind": "neow_card_reward", "domain": "character_cards",
                "rarities": ["COMMON", "UNCOMMON", "RARE"],
                "visible_count": 3, "choose_count": 1,
                "selection_mode": "player_choice",
            },
            "RANDOM_COLORLESS": {
                "kind": "neow_card_reward", "domain": "colorless_cards",
                "rarities": ["UNCOMMON", "RARE"], "visible_count": 3,
                "choose_count": 1, "selection_mode": "player_choice",
            },
            "RANDOM_COLORLESS_2": {
                "kind": "neow_card_reward", "domain": "colorless_cards",
                "rarities": ["RARE"], "visible_count": 3,
                "choose_count": 1, "selection_mode": "player_choice",
            },
            "THREE_RARE_CARDS": {
                "kind": "neow_card_reward", "domain": "character_cards",
                "rarities": ["RARE"], "visible_count": 3,
                "choose_count": 1, "selection_mode": "player_choice",
            },
            "REMOVE_CARD": {
                "kind": "neow_grid_selection", "domain": "current_deck",
                "operation": "remove", "select_count": 1,
                "selection_mode": "player_choice",
            },
            "REMOVE_TWO": {
                "kind": "neow_grid_selection", "domain": "current_deck",
                "operation": "remove", "select_count": 2,
                "selection_mode": "player_choice",
            },
            "UPGRADE_CARD": {
                "kind": "neow_grid_selection", "domain": "current_deck",
                "operation": "upgrade", "select_count": 1,
                "selection_mode": "player_choice",
            },
            "TRANSFORM_CARD": {
                "kind": "neow_grid_selection", "domain": "current_deck",
                "operation": "transform", "select_count": 1,
                "selection_mode": "player_choice",
                "result_domain": "character_cards",
                "result_selection_mode": "random",
            },
            "TRANSFORM_TWO_CARDS": {
                "kind": "neow_grid_selection", "domain": "current_deck",
                "operation": "transform", "select_count": 2,
                "selection_mode": "player_choice",
                "result_domain": "character_cards",
                "result_selection_mode": "random",
            },
            "THREE_SMALL_POTIONS": {
                "kind": "neow_potion_rewards", "domain": "potion_pool",
                "reward_count": 3,
                "selection_mode": "claim_visible_rewards",
            },
        }
        if reward in followups:
            result["future_costs"].append(copy.deepcopy(followups[reward]))
        if reward == "HUNDRED_GOLD":
            result["gold_delta"] += 100
        elif reward == "TWO_FIFTY_GOLD":
            result["gold_delta"] += 250
        elif reward in {
            "TEN_PERCENT_HP_BONUS", "TWENTY_PERCENT_HP_BONUS",
        }:
            multiplier = 2 if reward == "TWENTY_PERCENT_HP_BONUS" else 1
            result["max_hp_delta"] += multiplier * int(parameters["hp_bonus"])
            result["hp_delta"] += multiplier * int(parameters["hp_bonus"])
        elif reward == "THREE_ENEMY_KILL":
            result["relic_changes"] = {
                "gain": [{"id": "NeowsBlessing", "counter": 3}],
                "remove": [], "counter": [],
            }

        drawback_gold = 0
        drawback_hp = 0
        drawback_max_hp = 0
        if drawback == "NO_GOLD":
            drawback_gold = int(getattr(self.game, "gold", 0) or 0)
            result["gold_delta"] -= drawback_gold
        elif drawback == "CURSE":
            result["random_effects"].append({
                "kind": "curse_gain", "domain": "curses",
                "rarities": ["CURSE"], "count": 1,
                "timing": "immediate", "selection_mode": "random",
            })
        elif drawback == "TEN_PERCENT_HP_LOSS":
            max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
            current_hp = max(
                0, int(getattr(self.game, "current_hp", max_hp) or 0)
            )
            max_hp_loss = max(1, int(max_hp * 0.10))
            drawback_max_hp = max_hp_loss
            drawback_hp = max(
                0, current_hp - max(0, max_hp - max_hp_loss)
            )
            result["max_hp_delta"] -= max_hp_loss
            result["hp_delta"] -= drawback_hp
        elif drawback == "PERCENT_DAMAGE":
            drawback_hp = (
                max(0, int(getattr(self.game, "current_hp", 0) or 0))
                // 10
            ) * 3
            result["hp_delta"] -= drawback_hp
        result["current_cost"] = {
            "gold": drawback_gold,
            "hp": drawback_hp,
            "max_hp": drawback_max_hp,
        }
        return result

    def _event_card_loss_opportunity_cost(self, card):
        """Estimate the run value destroyed by giving away one exact card.

        Reward value alone is a poor inverse removal score: a starter Strike
        is actively useful to lose, while an established draw/scaling card is
        much more expensive than its raw rarity.  Blend the two existing deck
        models so event choices use the same card evidence as rewards and
        purges without introducing an event-specific card tier list.
        """

        reward_value = float(self._card_reward_score(card))
        removal_value = float(self._removal_score(card))
        opportunity_cost = (
            18.0
            + max(-12.0, min(28.0, reward_value)) * 0.45
            - max(0.0, min(70.0, removal_value)) * 0.28
        )
        return {
            "opportunity_cost": round(
                max(-6.0, min(36.0, opportunity_cost)), 3
            ),
            "reward_value": round(reward_value, 3),
            "removal_value": round(removal_value, 3),
        }

    def _event_omamori_charges(self):
        """Return the authoritative number of curses Omamori can prevent."""

        omamori = next(
            (
                relic
                for relic in list(getattr(self.game, "relics", []) or [])
                if self._token(getattr(relic, "relic_id", ""))
                == "omamori"
            ),
            None,
        )
        return (
            max(0, int(getattr(omamori, "counter", 0) or 0))
            if omamori is not None
            else 0
        )

    def _event_curse_trade_profile(self, consequences):
        """Price one event curse package from the current run state.

        Event code used to reduce every curse to either 18 points, 24 points
        for Normality, or three points when Omamori absorbed it.  That made
        the same option look identical in a twelve-card Pyramid deck and a
        thirty-card deck with Blue Candle and an affordable removal.  Keep a
        single bounded profile in ``consequences`` so deterministic scoring,
        audit logs, and the macro adviser all see the same probability and
        mitigation evidence.

        Credits here are deliberately finite.  Curse payoffs do not turn a
        dead draw into a reward, and having enough gold is only a possible
        shop removal rather than proof that a shop is reachable.
        """

        raw_delta = max(
            0, int(consequences.get("raw_curse_delta", 0) or 0)
        )
        effective_delta = max(
            0, int(consequences.get("effective_curse_delta", 0) or 0)
        )
        probability = max(
            0.0,
            min(
                1.0,
                float(consequences.get("curse_probability", 1.0) or 0.0),
            ),
        )
        expected_effective = max(
            0.0,
            float(
                consequences.get("expected_effective_curse_delta", 0.0)
                or 0.0
            ),
        )
        expected_prevented = max(
            0.0,
            float(
                consequences.get("expected_omamori_charge_use", 0.0)
                or 0.0
            ),
        )
        curse_id = self._token(consequences.get("curse_id", ""))
        base_harm_by_id = {
            # Normality and Pain can invalidate otherwise playable hands;
            # Writhe always taxes the opening hand.  Injury/Decay/Parasite
            # are still dead draws, but do not deserve the same price.
            "normality": 30.0,
            "pain": 27.0,
            "regret": 24.0,
            "writhe": 20.0,
            "doubt": 20.0,
            "shame": 20.0,
            "decay": 18.0,
            "parasite": 18.0,
            "injury": 17.0,
            "curseofthebell": 22.0,
            "necronomicurse": 18.0,
        }
        base_unit_harm = base_harm_by_id.get(curse_id, 19.0)

        deck = list(getattr(self.game, "deck", []) or [])
        deck_size = max(1, len(deck))
        existing_curses = sum(
            getattr(card, "rarity", None)
            == spirecomm.spire.card.CardRarity.CURSE
            or getattr(card, "type", None)
            == spirecomm.spire.card.CardType.CURSE
            for card in deck
        )
        deck_ids = {
            self._token(getattr(card, "card_id", "")) for card in deck
        }
        floor = max(0, int(getattr(self.game, "floor", 0) or 0))
        act = max(1, int(getattr(self.game, "act", 1) or 1))
        remaining_floors = max(0, 55 - floor)

        # Additive adjustments avoid multiplying several weak signals into an
        # extreme price.  A small/fast deck and long remaining run make every
        # dead draw recur more often; a strong deck gets only limited slack.
        cycle_adjustment = max(
            -0.10, min(0.10, (16.0 - deck_size) * 0.0125)
        )
        duration_adjustment = max(
            -0.10, min(0.08, (remaining_floors - 25.0) * 0.003)
        )
        existing_curse_adjustment = min(0.12, existing_curses * 0.03)
        pyramid = self._has_relic("Runic Pyramid")
        pyramid_adjustment = 0.15 if pyramid else 0.0
        try:
            readiness_score = float(
                (self._deck_readiness() or {}).get("score", 0.0) or 0.0
            )
        except (AttributeError, TypeError, ValueError):
            readiness_score = 0.0
        readiness_mitigation = max(
            0.0, min(0.10, (readiness_score - 0.55) * 0.22)
        )
        context_multiplier = max(
            0.78,
            min(
                1.35,
                1.0
                + cycle_adjustment
                + duration_adjustment
                + existing_curse_adjustment
                + pyramid_adjustment
                - readiness_mitigation,
            ),
        )
        gross_unit_harm = base_unit_harm * context_multiplier

        synergy_components = {}
        if self._has_relic("Blue Candle"):
            synergy_components["blue_candle"] = 3.0
        if self._has_relic("Du-Vu Doll"):
            synergy_components["du_vu_doll"] = 3.5
        if self._has_relic("Darkstone Periapt"):
            synergy_components["darkstone_periapt"] = 4.5
        if "firebreathing" in deck_ids:
            synergy_components["fire_breathing"] = 2.5
        if "rupture" in deck_ids and curse_id in {
            "pain", "regret", "decay"
        }:
            synergy_components["rupture_hp_loss"] = 2.5
        synergy_unit_credit = min(
            gross_unit_harm * 0.45, sum(synergy_components.values())
        )

        screen = getattr(self.game, "screen", None)
        explicit_purge_cost = int(
            getattr(screen, "purge_cost", 0)
            or getattr(self.game, "next_shop_purge_cost", 0)
            or getattr(self.game, "purge_cost", 0)
            or 0
        )
        estimated_purge_cost = explicit_purge_cost or 75
        gold = max(0, int(getattr(self.game, "gold", 0) or 0))
        peace_pipe = self._has_relic("Peace Pipe")
        affordable_shop_removal = bool(
            remaining_floors >= 4 and gold >= estimated_purge_cost
        )
        removable = curse_id not in {
            "curseofthebell", "necronomicurse"
        }
        removal_capacity = int(
            removable and (peace_pipe or affordable_shop_removal)
        )
        removal_unit_credit = (
            4.5 if peace_pipe else 2.75 if affordable_shop_removal else 0.0
        )
        expected_removed = (
            probability * min(effective_delta, removal_capacity)
        )

        expected_gross_harm = expected_effective * gross_unit_harm
        expected_synergy_credit = expected_effective * synergy_unit_credit
        expected_removal_credit = expected_removed * removal_unit_credit
        expected_curse_harm = max(
            0.0,
            expected_gross_harm
            - expected_synergy_credit
            - expected_removal_credit,
        )

        # Cursed Key makes a finite Omamori charge materially more valuable
        # while non-boss chests remain.  It is still an opportunity cost, not
        # a reason to pretend the currently protected curse enters the deck.
        floor_in_act = ((max(1, floor) - 1) % 17) + 1
        future_cursed_key_chests = 0
        if self._has_relic("Cursed Key") and act <= 3:
            future_cursed_key_chests = max(0, 3 - act)
            if floor_in_act <= 8:
                future_cursed_key_chests += 1
        omamori_charge_unit_cost = 3.0 + min(
            6.0, future_cursed_key_chests * 3.0
        )
        expected_omamori_cost = (
            expected_prevented * omamori_charge_unit_cost
        )
        total_cost = expected_curse_harm + expected_omamori_cost

        return {
            "curse_id": consequences.get("curse_id"),
            "raw_curse_delta": raw_delta,
            "effective_curse_delta": effective_delta,
            "probability": round(probability, 3),
            "expected_effective_curses": round(expected_effective, 3),
            "base_unit_harm": round(base_unit_harm, 3),
            "context_multiplier": round(context_multiplier, 3),
            "gross_unit_harm": round(gross_unit_harm, 3),
            "deck_size": deck_size,
            "existing_curses": existing_curses,
            "remaining_floors": remaining_floors,
            "deck_readiness": round(readiness_score, 3),
            "runic_pyramid": bool(pyramid),
            "synergy_components": {
                key: round(value, 3)
                for key, value in synergy_components.items()
            },
            "synergy_unit_credit": round(synergy_unit_credit, 3),
            "peace_pipe": bool(peace_pipe),
            "estimated_purge_cost": estimated_purge_cost,
            "gold": gold,
            "affordable_shop_removal": affordable_shop_removal,
            "removal_capacity": removal_capacity,
            "expected_removed_curses": round(expected_removed, 3),
            "expected_removal_credit": round(
                expected_removal_credit, 3
            ),
            "future_cursed_key_chests": future_cursed_key_chests,
            "omamori_charge_unit_cost": round(
                omamori_charge_unit_cost, 3
            ),
            "expected_curse_harm": round(expected_curse_harm, 3),
            "expected_omamori_cost": round(expected_omamori_cost, 3),
            "total_opportunity_cost": round(total_cost, 3),
        }

    def _event_curse_gain_consequences(
        self, raw_curse_delta, *, probability=1.0, curse_id=None
    ):
        """Resolve a curse outcome through Omamori once for every consumer.

        ``raw_curse_delta`` and the conditional post-trigger deltas stay
        integral.  Expected fields carry event randomness (for example The
        Mausoleum's 50% Writhe) so local scoring and the macro adviser never
        disagree about whether a curse actually reaches the deck.
        """

        raw_delta = max(0, int(raw_curse_delta or 0))
        curse_probability = max(0.0, min(1.0, float(probability or 0.0)))
        omamori_before = self._event_omamori_charges()
        prevented_delta = min(raw_delta, omamori_before)
        effective_delta = max(0, raw_delta - prevented_delta)
        expected_prevented = prevented_delta * curse_probability
        expected_effective = effective_delta * curse_probability
        consequences = {
            # Keep the legacy field as the actual delta if the curse branch
            # occurs.  New consumers should use the explicit raw/effective
            # and expected fields below.
            "curse_delta": effective_delta,
            "raw_curse_delta": raw_delta,
            "omamori_prevented_curse_delta": prevented_delta,
            "effective_curse_delta": effective_delta,
            "curse_probability": round(curse_probability, 3),
            "expected_effective_curse_delta": round(
                expected_effective, 3
            ),
            "expected_omamori_charge_use": round(
                expected_prevented, 3
            ),
            "omamori_charges_before": omamori_before,
            "omamori_charges_after_if_triggered": max(
                0, omamori_before - prevented_delta
            ),
            "expected_omamori_charges_after": round(
                omamori_before - expected_prevented, 3
            ),
            "curse_change_kind": "gain",
        }
        if curse_id:
            consequences["curse_id"] = curse_id
        consequences["curse_trade_profile"] = (
            self._event_curse_trade_profile(consequences)
        )
        return consequences

    @staticmethod
    def _event_curse_opportunity_cost(consequences, unit_cost=18.0):
        """Price only curses that bypass Omamori plus consumed charges."""

        profile = consequences.get("curse_trade_profile") or {}
        if "total_opportunity_cost" in profile:
            return float(profile["total_opportunity_cost"] or 0.0)

        expected_curses = float(
            consequences.get("expected_effective_curse_delta", 0.0) or 0.0
        )
        expected_charge_use = float(
            consequences.get("expected_omamori_charge_use", 0.0) or 0.0
        )
        # A protected curse still spends a finite future resource, but that
        # opportunity cost is deliberately far below putting a curse in deck.
        return expected_curses * float(unit_cost) + expected_charge_use * 3.0

    @staticmethod
    def _mausoleum_random_relic_effect():
        return {
            "kind": "random_relic_gain",
            "domain": "base_game_non_boss_relic_pool",
            "excluded_rarities": ["BOSS"],
            "count": 1,
            "timing": "immediate",
            "selection_mode": "random",
        }

    @staticmethod
    def _mausoleum_writhe_card_effect():
        return {
            "id": "Writhe",
            "card_id": "Writhe",
            "type": "CURSE",
            "rarity": "CURSE",
            "count": 1,
        }

    @staticmethod
    def _typed_event_zero_consequence(
        event_id, mechanism_id, operation, event_outcome_id
    ):
        """Return the complete zero-delta event shape used by typed events."""

        return {
            "event_id": event_id,
            "mechanism_id": mechanism_id,
            "operation": operation,
            "event_outcome_id": event_outcome_id,
            "hp_delta": 0,
            "max_hp_delta": 0,
            "gold_delta": 0,
            "card_changes": {
                "gain": [], "remove": [], "upgrade": [], "transform": [],
            },
            "relic_changes": {"gain": [], "remove": [], "counter": []},
            "potion_changes": {"gain": [], "remove": [], "replace": []},
            "curse": {
                "gain": [], "remove": [], "probability": 0.0,
                "omamori_applicable": False,
                "omamori_charges_consumed": 0,
            },
            "probabilistic_outcomes": [],
            "current_cost": {"gold": 0, "hp": 0, "max_hp": 0},
            "future_costs": [],
            "random_effects": [],
            "uncertainty": [],
            "uncertainty_classification": {
                "status": "none",
                "authority": "typed_event_contract",
                "reason": "exact typed event consequence is deterministic",
            },
        }

    @staticmethod
    def _canonical_goop_event_contract(value, original_index):
        """Validate the reflection-backed Goop option and bind its id."""

        required = {
            "contract_version", "contract_kind", "event_id",
            "event_class", "original_button_index", "option_kind",
            "parameters",
        }
        if (
            not isinstance(value, dict)
            or set(value) != required
            or value.get("contract_version") != 1
            or value.get("contract_kind") != "BASE_GAME_EVENT_OPTION"
            or value.get("event_id") != "World of Goop"
            or value.get("event_class") != (
                "com.megacrit.cardcrawl.events.exordium.GoopPuddle"
            )
            or value.get("original_button_index") != original_index
            or not isinstance(value.get("parameters"), dict)
        ):
            return None, None
        kind = value.get("option_kind")
        parameters = value["parameters"]
        expected_fields = {
            (0, "GATHER"): {"gold_gain", "hp_damage"},
            (1, "LEAVE"): {"gold_loss"},
            (0, "CONTINUE"): set(),
        }.get((original_index, kind))
        if (
            expected_fields is None
            or set(parameters) != expected_fields
            or any(
                type(item) is not int or item < 0
                for item in parameters.values()
            )
        ):
            return None, None
        # At A0 these two values are fixed by GoopPuddle.  An unexpected
        # value indicates a modded/stale contract and must not inherit the
        # base-game score formula.
        if kind == "GATHER" and parameters != {
            "gold_gain": 75, "hp_damage": 11,
        }:
            return None, None
        contract = json.loads(json.dumps(
            value, ensure_ascii=True, sort_keys=True,
            separators=(",", ":"),
        ))
        digest = hashlib.sha256(json.dumps(
            contract, ensure_ascii=True, sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")).hexdigest()[:20]
        return contract, f"event-mechanism:{digest}"

    @staticmethod
    def _exact_typed_contract_value(value, expected):
        if type(value) is not type(expected):
            return False
        if isinstance(expected, dict):
            return set(value) == set(expected) and all(
                SimpleAgent._exact_typed_contract_value(
                    value[key], expected[key]
                )
                for key in expected
            )
        if isinstance(expected, list):
            return len(value) == len(expected) and all(
                SimpleAgent._exact_typed_contract_value(item, wanted)
                for item, wanted in zip(value, expected)
            )
        return value == expected

    def _canonical_staged_event_contract(
        self, value, event_id, original_index
    ):
        """Validate one frozen reflection-backed staged event contract."""

        required = {
            "contract_version", "contract_kind", "event_id",
            "event_class", "event_stage", "original_button_index",
            "option_kind", "instance_parameters", "parameters",
        }
        identities = {
            "thecleric": (
                "The Cleric",
                "com.megacrit.cardcrawl.events.exordium.Cleric",
            ),
            "designer": (
                "Designer",
                "com.megacrit.cardcrawl.events.shrines.Designer",
            ),
            "cursedtome": (
                "Cursed Tome",
                "com.megacrit.cardcrawl.events.city.CursedTome",
            ),
            "knowingskull": (
                "Knowing Skull",
                "com.megacrit.cardcrawl.events.city.KnowingSkull",
            ),
            "facetrader": (
                "Face Trader",
                "com.megacrit.cardcrawl.events.shrines.FaceTrader",
            ),
            "duplicator": (
                "Duplicator",
                "com.megacrit.cardcrawl.events.shrines.Duplicator",
            ),
            "bonfireelementals": (
                "Bonfire Elementals",
                "com.megacrit.cardcrawl.events.shrines.Bonfire",
            ),
        }
        identity = identities.get(event_id)
        if (
            identity is None
            or not isinstance(value, dict)
            or set(value) != required
            or value.get("contract_version") != 1
            or value.get("contract_kind") != "BASE_GAME_EVENT_OPTION"
            or value.get("event_id") != identity[0]
            or value.get("event_class") != identity[1]
            or type(value.get("event_stage")) is not str
            or value.get("original_button_index") != original_index
            or type(value.get("option_kind")) is not str
            or not isinstance(value.get("instance_parameters"), dict)
            or not isinstance(value.get("parameters"), dict)
        ):
            return None, None
        stage = value["event_stage"]
        kind = value["option_kind"]
        instance = value["instance_parameters"]
        parameters = value["parameters"]
        key = (stage, original_index, kind)
        expected = None

        if event_id == "thecleric":
            max_hp = getattr(self.game, "max_hp", None)
            if (
                set(instance) != {
                    "heal_amount", "heal_gold_cost", "purify_cost",
                }
                or type(instance.get("heal_amount")) is not int
                or type(max_hp) is not int
                or instance.get("heal_amount") not in {
                    int(max_hp * 0.25),
                    int(math.ceil(max_hp * 0.25)),
                }
                or instance.get("heal_gold_cost") != 35
                or instance.get("purify_cost") != 50
            ):
                return None, None
            if key == ("MAIN", 0, "HEAL"):
                expected = {
                    "gold_cost": 35,
                    "heal_amount": instance["heal_amount"],
                }
            elif key == ("MAIN", 1, "PURIFY"):
                expected = {
                    "gold_cost_if_purgeable": 50,
                    "purge_select_count": 1,
                    "selection_mode": "PLAYER_SELECT",
                }
            elif key in {
                ("MAIN", 2, "LEAVE"),
                ("RESULT", 0, "CONTINUE"),
            }:
                expected = {}

        elif event_id == "designer":
            expected_instance_keys = {
                "adjustment_upgrades_one", "clean_up_removes_cards",
                "adjust_cost", "clean_up_cost", "full_service_cost",
                "hp_loss",
            }
            if (
                set(instance) != expected_instance_keys
                or type(instance.get("adjustment_upgrades_one")) is not bool
                or type(instance.get("clean_up_removes_cards")) is not bool
                or (
                    instance.get("adjust_cost"),
                    instance.get("clean_up_cost"),
                    instance.get("full_service_cost"),
                    instance.get("hp_loss"),
                ) != (40, 60, 90, 3)
            ):
                return None, None
            if key in {
                ("INTRO", 0, "OPEN_SERVICES"),
                ("DONE", 0, "CONTINUE"),
            }:
                expected = {}
            elif stage == "MAIN" and original_index == 0:
                if instance["adjustment_upgrades_one"]:
                    expected_kind = "ADJUSTMENT_GRID_UPGRADE"
                    expected = {
                        "gold_cost": 40,
                        "upgrade_select_count": 1,
                        "selection_mode": "PLAYER_SELECT",
                    }
                else:
                    expected_kind = "ADJUSTMENT_RANDOM_UPGRADE"
                    expected = {
                        "gold_cost": 40,
                        "upgrade_max_count": 2,
                        "selection_mode": "RANDOM_UP_TO_AVAILABLE",
                    }
                if kind != expected_kind:
                    return None, None
            elif stage == "MAIN" and original_index == 1:
                if instance["clean_up_removes_cards"]:
                    expected_kind = "CLEAN_UP_GRID_PURGE"
                    expected = {
                        "gold_cost": 60,
                        "selection_mode": "PLAYER_SELECT",
                        "purge_select_count": 1,
                    }
                else:
                    expected_kind = "CLEAN_UP_GRID_TRANSFORM"
                    expected = {
                        "gold_cost": 60,
                        "selection_mode": "PLAYER_SELECT",
                        "transform_select_count": 2,
                        "transform_result": "RANDOM",
                    }
                if kind != expected_kind:
                    return None, None
            elif key == ("MAIN", 2, "FULL_SERVICE"):
                expected = {
                    "gold_cost": 90,
                    "purge_select_count": 1,
                    "random_upgrade_max_count": 1,
                    "selection_mode": (
                        "PLAYER_SELECT_THEN_RANDOM_UP_TO_AVAILABLE"
                    ),
                }
            elif key == ("MAIN", 3, "PUNCH_AND_LEAVE"):
                expected = {"hp_loss": 3}

        elif event_id == "knowingskull":
            if (
                set(instance) != {
                    "potion_cost", "card_cost", "gold_cost",
                    "leave_cost", "gold_reward",
                }
                or any(
                    type(instance.get(name)) is not int
                    for name in (
                        "potion_cost", "card_cost", "gold_cost",
                        "leave_cost", "gold_reward",
                    )
                )
                or instance.get("leave_cost") != 6
                or any(
                    instance[name] < instance["leave_cost"]
                    for name in (
                        "potion_cost", "card_cost", "gold_cost",
                    )
                )
                or instance.get("gold_reward") != 90
            ):
                return None, None
            if key in {
                ("INTRO_1", 0, "OPEN_QUESTIONS"),
                ("COMPLETE", 0, "CONTINUE"),
            }:
                expected = {}
            elif key == ("ASK", 0, "TAKE_POTION"):
                expected = {
                    "hp_loss": instance["potion_cost"],
                    "reward_count": 1,
                    "reward_kind": "RANDOM_POTION",
                }
            elif key == ("ASK", 1, "TAKE_GOLD"):
                expected = {
                    "hp_loss": instance["gold_cost"],
                    "gold_gain": 90,
                }
            elif key == ("ASK", 2, "TAKE_CARD"):
                expected = {
                    "hp_loss": instance["card_cost"],
                    "reward_count": 1,
                    "reward_color": "COLORLESS",
                    "reward_rarity": "UNCOMMON",
                    "selection_mode": "RANDOM",
                }
            elif key == ("ASK", 3, "LEAVE"):
                expected = {"hp_loss": instance["leave_cost"]}

        elif event_id == "cursedtome":
            book_ids = (
                "Necronomicon", "Enchiridion", "Nilry's Codex",
            )
            owned = {
                getattr(relic, "relic_id", None)
                for relic in list(getattr(self.game, "relics", []) or [])
            }
            expected_pool = [item for item in book_ids if item not in owned]
            expected_pool = expected_pool or ["Circlet"]
            if (
                set(instance) != {
                    "final_hp_loss", "damage_taken", "random_relic_pool",
                }
                or instance.get("final_hp_loss") != 10
                or type(instance.get("damage_taken")) is not int
                or instance.get("random_relic_pool") != expected_pool
            ):
                return None, None
            damage_taken = instance["damage_taken"]
            expected_damage = {
                "INTRO": {0}, "PAGE_1": {0}, "PAGE_2": {1},
                "PAGE_3": {3}, "LAST_PAGE": {6},
                "END": {0, 9, 16},
            }.get(stage)
            if expected_damage is None or damage_taken not in expected_damage:
                return None, None
            if key == ("INTRO", 0, "ENTER_RANDOM_BOOK_CHAIN"):
                expected = {
                    "future_hp_loss_to_complete": 16,
                    "random_relic_count": 1,
                    "reward_surface": "COMBAT_REWARD",
                    "selection_mode": "UNIFORM_MISC_RNG",
                }
            elif key == ("INTRO", 1, "LEAVE"):
                expected = {}
            elif key == ("PAGE_1", 0, "READ_PAGE_1"):
                expected = {"hp_loss": 1}
            elif key == ("PAGE_2", 0, "READ_PAGE_2"):
                expected = {"hp_loss": 2}
            elif key == ("PAGE_3", 0, "READ_PAGE_3"):
                expected = {"hp_loss": 3}
            elif key == ("LAST_PAGE", 0, "COMPLETE_RANDOM_BOOK"):
                expected = {
                    "hp_loss": 10,
                    "random_relic_count": 1,
                    "reward_surface": "COMBAT_REWARD",
                    "selection_mode": "UNIFORM_MISC_RNG",
                }
            elif key == ("LAST_PAGE", 1, "STOP"):
                expected = {"hp_loss": 3}
            elif key == ("END", 0, "PROCEED"):
                expected = {}

        elif event_id == "facetrader":
            max_hp = getattr(self.game, "max_hp", None)
            relics = list(getattr(self.game, "relics", []) or [])
            face_ids = (
                "CultistMask", "FaceOfCleric", "GremlinMask",
                "NlothsMask", "SsserpentHead",
            )
            owned = {
                getattr(relic, "relic_id", None) for relic in relics
            }
            pool = [item for item in face_ids if item not in owned]
            pool = pool or ["Circlet"]
            if (
                type(max_hp) is not int
                or not self._exact_typed_contract_value(instance, {
                    "gold_reward": 75,
                    "damage": max(1, max_hp // 10),
                    "random_face_pool": pool,
                })
            ):
                return None, None
            expected = {
                ("INTRO", 0, "OPEN"): {},
                ("MAIN", 0, "TOUCH"): {
                    "hp_loss": instance["damage"], "gold_gain": 75,
                },
                ("MAIN", 1, "TRADE"): {
                    "random_relic_pool": pool,
                    "random_relic_count": 1,
                    "selection_mode": "UNIFORM_MISC_RNG_SHUFFLE_FIRST",
                },
                ("MAIN", 2, "LEAVE"): {},
                ("RESULT", 0, "CONTINUE"): {},
            }.get(key)

        elif event_id == "duplicator":
            if (
                set(instance) != {"screen_num"}
                or instance.get("screen_num") not in {0, 2}
            ):
                return None, None
            if (
                key == ("MAIN", 0, "DUPLICATE")
                and instance["screen_num"] == 0
            ):
                expected = {
                    "duplicate_select_count": 1,
                    "selection_mode": "PLAYER_SELECT_CURRENT_DECK",
                }
            elif (
                key == ("MAIN", 1, "LEAVE")
                and instance["screen_num"] == 0
            ):
                expected = {}
            elif (
                key == ("RESULT", 0, "CONTINUE")
                and instance["screen_num"] == 2
            ):
                expected = {}

        elif event_id == "bonfireelementals":
            if instance != {"card_select": False}:
                return None, None
            if key in {
                ("INTRO", 0, "CONTINUE"),
                ("COMPLETE", 0, "CONTINUE"),
            }:
                expected = {}
            elif key == ("CHOOSE", 0, "OFFER_CARD"):
                expected = {
                    "offer_select_count": 1,
                    "selection_mode": (
                        "PLAYER_SELECT_PURGEABLE_UNBOTTLED_CURRENT_DECK"
                    ),
                }

        if (
            expected is None
            or not self._exact_typed_contract_value(parameters, expected)
        ):
            return None, None
        contract = json.loads(json.dumps(
            value, ensure_ascii=True, sort_keys=True,
            separators=(",", ":"),
        ))
        digest = hashlib.sha256(json.dumps(
            contract, ensure_ascii=True, sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")).hexdigest()[:20]
        return contract, f"event-mechanism:{digest}"

    def _typed_a0_event_option_consequences(self, option):
        """Type a small base-game A0 event set without localized text.

        CommunicationMod compacts ``choice_index`` whenever a button is
        disabled, while ``original_button_index`` preserves the base-game
        semantic branch.  A reordered container remains valid because both
        identities bind through the exact option object, never list position.

        Every supported branch is proved by a reflection-backed typed event
        contract.  Missing/mixed stage or instance evidence fails closed;
        localized label/text never participates in identity or mechanics.
        """

        screen = getattr(self.game, "screen", None)
        raw_event_id = getattr(screen, "event_id", None)
        event_id = self._token(raw_event_id)
        if event_id not in {
            "thecleric", "designer", "worldofgoop", "cursedtome",
            "knowingskull", "facetrader", "duplicator",
            "bonfireelementals",
        }:
            return None
        mechanism_id = None

        def unclassified(reason, **known):
            return {
                "event_id": raw_event_id,
                "mechanism_id": mechanism_id,
                "operation": f"unclassified_{event_id}_option",
                "uncertainty": [reason],
                "reason_codes": [reason],
                **known,
            }

        ascension = getattr(self.game, "ascension_level", None)
        if type(ascension) is not int or ascension != 0:
            return unclassified("typed_event_requires_exact_a0")
        options = list(getattr(screen, "options", []) or [])
        enabled = []
        for item in options:
            disabled = getattr(item, "disabled", None)
            choice_index = getattr(item, "choice_index", None)
            if type(disabled) is not bool:
                return unclassified("typed_event_disabled_flag_invalid")
            if disabled:
                if choice_index is not None:
                    return unclassified(
                        "typed_event_disabled_option_has_choice_index"
                    )
                continue
            if type(choice_index) is not int:
                return unclassified(
                    "typed_event_enabled_choice_index_missing"
                )
            enabled.append(item)
        index = getattr(option, "choice_index", None)
        matches = [
            item for item in enabled
            if getattr(item, "choice_index", None) == index
        ]
        if (
            type(index) is not int
            or len(matches) != 1
            or matches[0] is not option
        ):
            return unclassified("typed_event_choice_index_binding_mismatch")

        originals = [
            getattr(item, "original_button_index", None)
            for item in options
        ]
        if (
            not all(type(value) is int for value in originals)
            or sorted(originals) != list(range(len(options)))
        ):
            return unclassified(
                "typed_event_original_button_index_surface_invalid"
            )
        if sorted(item.choice_index for item in enabled) != list(
            range(len(enabled))
        ):
            return unclassified(
                "typed_event_compressed_choice_index_surface_invalid"
            )
        original_index = getattr(option, "original_button_index")

        surface_contracts = {}
        surface_mechanisms = {}
        for item in options:
            item_original = getattr(item, "original_button_index")
            if event_id == "worldofgoop":
                contract, contract_mechanism = (
                    self._canonical_goop_event_contract(
                        getattr(item, "event_contract", None),
                        item_original,
                    )
                )
            else:
                contract, contract_mechanism = (
                    self._canonical_staged_event_contract(
                        getattr(item, "event_contract", None),
                        event_id,
                        item_original,
                    )
                )
            if contract is None or item_original in surface_contracts:
                return unclassified(
                    "typed_event_contract_missing_invalid_or_mismatched"
                )
            surface_contracts[item_original] = contract
            surface_mechanisms[item_original] = contract_mechanism

        if event_id == "worldofgoop":
            kinds = {
                item_index: contract.get("option_kind")
                for item_index, contract in surface_contracts.items()
            }
            if kinds not in (
                {0: "GATHER", 1: "LEAVE"}, {0: "CONTINUE"},
            ):
                return unclassified(
                    "typed_event_contract_stage_surface_mismatch"
                )
        else:
            stages = {
                contract["event_stage"]
                for contract in surface_contracts.values()
            }
            instances = {
                json.dumps(
                    contract["instance_parameters"], ensure_ascii=True,
                    sort_keys=True, separators=(",", ":"),
                )
                for contract in surface_contracts.values()
            }
            if len(stages) != 1 or len(instances) != 1:
                return unclassified(
                    "typed_event_contract_stage_or_instance_mismatch"
                )
            stage = next(iter(stages))
            expected_originals = {
                ("thecleric", "MAIN"): {0, 1, 2},
                ("thecleric", "RESULT"): {0},
                ("designer", "INTRO"): {0},
                ("designer", "MAIN"): {0, 1, 2, 3},
                ("designer", "DONE"): {0},
                ("cursedtome", "INTRO"): {0, 1},
                ("cursedtome", "PAGE_1"): {0},
                ("cursedtome", "PAGE_2"): {0},
                ("cursedtome", "PAGE_3"): {0},
                ("cursedtome", "LAST_PAGE"): {0, 1},
                ("cursedtome", "END"): {0},
                ("knowingskull", "INTRO_1"): {0},
                ("knowingskull", "ASK"): {0, 1, 2, 3},
                ("knowingskull", "COMPLETE"): {0},
                ("facetrader", "INTRO"): {0},
                ("facetrader", "MAIN"): {0, 1, 2},
                ("facetrader", "RESULT"): {0},
                ("duplicator", "MAIN"): {0, 1},
                ("duplicator", "RESULT"): {0},
                ("bonfireelementals", "INTRO"): {0},
                ("bonfireelementals", "CHOOSE"): {0},
                ("bonfireelementals", "COMPLETE"): {0},
            }.get((event_id, stage))
            if set(surface_contracts) != expected_originals:
                return unclassified(
                    "typed_event_contract_stage_surface_mismatch"
                )

        selected_contract = surface_contracts[original_index]
        mechanism_id = surface_mechanisms[original_index]
        # Bind the consequence to the runtime ID exposed by the protocol.
        # Reflected contracts use a display name (for example ``Face Trader``)
        # while the live screen can expose ``FaceTrader``; mixing them makes
        # an exact consequence appear to belong to another event.
        canonical_event_id = raw_event_id
        stage = selected_contract.get("event_stage")
        option_kind = selected_contract.get("option_kind")
        parameters = selected_contract["parameters"]

        if option_kind in {
            "CONTINUE", "OPEN", "OPEN_SERVICES", "OPEN_QUESTIONS",
            "PROCEED",
        }:
            operation = {
                "thecleric": "cleric_dialog_advance_noop",
                "designer": "designer_dialog_advance_noop",
                "worldofgoop": "world_of_goop_dialog_advance_noop",
                "cursedtome": "cursed_tome_dialog_advance_noop",
                "knowingskull": "knowing_skull_dialog_advance_noop",
                "facetrader": "face_trader_dialog_advance_noop",
                "duplicator": "duplicator_dialog_advance_noop",
                "bonfireelementals": "bonfire_dialog_advance_noop",
            }[event_id]
            result = self._typed_event_zero_consequence(
                canonical_event_id, mechanism_id, operation,
                "dialog_advance",
            )
            result["original_button_index"] = original_index
            return result

        empty = self._typed_event_zero_consequence(
            canonical_event_id, mechanism_id, "event_noop", "noop"
        )
        empty["original_button_index"] = original_index
        index = original_index
