    def _typed_progress_event_option_consequences(self, option):
        """Type reflected A0 event progress whose buttons reuse index zero.

        These events cannot be identified from a localized label or from the
        button index alone: the same original index advances multiple dialog
        stages.  Bind the exact base-game class, reflected progress value,
        complete original-index surface, and selected option instance before
        claiming any mechanics.
        """

        screen = getattr(self.game, "screen", None)
        raw_event_id = getattr(screen, "event_id", None)
        event_id = self._token(raw_event_id)
        specs = {
            "liarsgame": (
                "com.megacrit.cardcrawl.events.exordium.Sssserpent",
                "event_stage",
            ),
            "vampires": (
                "com.megacrit.cardcrawl.events.city.Vampires",
                "screen_num",
            ),
            "goldenshrine": (
                "com.megacrit.cardcrawl.events.shrines.GoldShrine",
                "event_stage",
            ),
        }
        spec = specs.get(event_id)
        if spec is None:
            return None

        def unclassified(reason):
            return {
                "event_id": raw_event_id,
                "operation": f"unclassified_{event_id}_option",
                "uncertainty": [reason],
                "reason_codes": [reason],
            }

        if getattr(self.game, "ascension_level", None) != 0:
            return None
        expected_class, progress_field = spec
        actual_class = getattr(screen, "event_class", None)
        if actual_class is None:
            # Legacy/replay fixtures predating reflected progress retain the
            # conservative localized model; a contradictory advertised class
            # still fails closed below.
            return None
        if actual_class != expected_class:
            return unclassified("typed_progress_event_class_mismatch")
        progress = getattr(screen, progress_field, None)
        if (
            progress_field == "event_stage"
            and (not isinstance(progress, str) or not progress)
        ) or (
            progress_field == "screen_num"
            and (type(progress) is not int or progress < 0)
        ):
            return unclassified("typed_progress_event_value_missing")

        options = list(getattr(screen, "options", []) or [])
        enabled = [
            item for item in options
            if not bool(getattr(item, "disabled", False))
        ]
        if any(
            type(getattr(item, "original_button_index", None)) is not int
            or type(getattr(item, "choice_index", None)) is not int
            for item in enabled
        ):
            return unclassified("typed_progress_event_index_missing")
        originals = tuple(sorted(
            item.original_button_index for item in enabled
        ))
        if len(originals) != len(set(originals)):
            return unclassified("typed_progress_event_surface_duplicated")
        if tuple(sorted(item.choice_index for item in enabled)) != tuple(
            range(len(enabled))
        ):
            return unclassified(
                "typed_progress_event_compressed_surface_invalid"
            )
        original_index = getattr(option, "original_button_index", None)
        choice_index = getattr(option, "choice_index", None)
        if (
            option not in enabled
            or type(original_index) is not int
            or type(choice_index) is not int
            or sum(item is option for item in enabled) != 1
        ):
            return unclassified("typed_progress_event_option_binding_mismatch")

        has_blood_vial = self._has_relic("Blood Vial")
        expected_surface = {
            "liarsgame": (0, 1) if progress == "INTRO" else (0,),
            "vampires": (
                (0, 1, 2)
                if progress == 0 and has_blood_vial
                else (0, 1) if progress == 0 else (0,)
            ),
            "goldenshrine": (
                (0, 1, 2) if progress == "INTRO" else (0,)
            ),
        }[event_id]
        if originals != expected_surface:
            return unclassified("typed_progress_event_surface_mismatch")

        mechanism_id = f"base_game_{event_id}_a0_progress_v1"
        result = self._typed_event_zero_consequence(
            raw_event_id, mechanism_id, "event_noop", "noop"
        )
        result["original_button_index"] = original_index

        def apply_fixed_curse(card_id):
            charges = self._event_omamori_charges()
            consumed = min(1, charges)
            gained = 1 - consumed
            card = {
                "id": card_id, "card_id": card_id,
                "type": "CURSE", "rarity": "CURSE", "count": gained,
            }
            gains = [card] if gained else []
            result["card_changes"]["gain"] = gains
            result["curse"] = {
                "gain": gains, "remove": [], "probability": 1.0,
                "omamori_applicable": True,
                "omamori_charges_consumed": consumed,
            }
            if consumed:
                result["relic_changes"]["counter"] = [{
                    "id": "Omamori", "delta": -consumed,
                }]
            if gained and self._has_relic("Darkstone Periapt"):
                result["hp_delta"] += 6
                result["max_hp_delta"] += 6
            result.update(self._event_curse_gain_consequences(
                1, curse_id=card_id
            ))

        if event_id == "liarsgame":
            if progress == "INTRO":
                if original_index == 0:
                    gold_gain = 0 if self._has_relic("Ectoplasm") else 175
                    result.update({
                        "operation": "liars_game_prepare_agreement",
                        "event_outcome_id": "accept_gold_and_doubt",
                        "future_costs": [{
                            "kind": "event_deferred_settlement",
                            "event_id": "Liars Game",
                            "event_stage": "AGREE",
                            "gold_delta": gold_gain,
                            "card_gain": {
                                "id": "Doubt", "card_id": "Doubt",
                                "type": "CURSE", "rarity": "CURSE",
                                "count": 1,
                            },
                            "timing": "next_event_confirmation",
                        }],
                        "uncertainty_classification": {
                            "status": "classified_future",
                            "authority": "reflected_event_progress",
                            "reason": "settles on the AGREE confirmation",
                        },
                    })
                else:
                    result.update({
                        "operation": "liars_game_decline",
                        "event_outcome_id": "decline", "leave": True,
                    })
            elif progress == "AGREE":
                result["gold_delta"] = (
                    0 if self._has_relic("Ectoplasm") else 175
                )
                apply_fixed_curse("Doubt")
                result.update({
                    "operation": "liars_game_settle_agreement",
                    "event_outcome_id": "settle_gold_and_doubt",
                })
            elif progress in {"DISAGREE", "COMPLETE"}:
                result.update({
                    "operation": "liars_game_leave",
                    "event_outcome_id": "leave", "leave": True,
                })
            else:
                return unclassified("typed_liars_game_stage_unhandled")
            return result

        if event_id == "goldenshrine":
            if progress == "INTRO":
                if original_index == 0:
                    result.update({
                        "operation": "golden_shrine_pray",
                        "event_outcome_id": "pray",
                        "gold_delta": (
                            0 if self._has_relic("Ectoplasm") else 100
                        ),
                    })
                elif original_index == 1:
                    result["gold_delta"] = (
                        0 if self._has_relic("Ectoplasm") else 275
                    )
                    apply_fixed_curse("Regret")
                    result.update({
                        "operation": "golden_shrine_desecrate",
                        "event_outcome_id": "desecrate",
                    })
                else:
                    result.update({
                        "operation": "golden_shrine_leave",
                        "event_outcome_id": "leave", "leave": True,
                    })
            elif progress == "COMPLETE":
                result.update({
                    "operation": "golden_shrine_leave",
                    "event_outcome_id": "leave", "leave": True,
                })
            else:
                return unclassified("typed_golden_shrine_stage_unhandled")
            return result

        if progress in {1, 2}:
            result.update({
                "operation": "vampires_leave",
                "event_outcome_id": "leave", "leave": True,
            })
            return result
        if progress != 0:
            return unclassified("typed_vampires_screen_unhandled")
        decline_index = 2 if has_blood_vial else 1
        if original_index == decline_index:
            result.update({
                "operation": "vampires_decline",
                "event_outcome_id": "decline", "leave": True,
            })
            return result
        if original_index not in ({0, 1} if has_blood_vial else {0}):
            return unclassified("typed_vampires_branch_unhandled")

        deck = list(getattr(self.game, "deck", []) or [])
        starter_ids = {"striker", "strikeg", "strikeb", "strikep"}
        removed_cards = [
            card for card in deck
            if self._token(getattr(card, "card_id", "")) in starter_ids
        ]

        def compact_card(card):
            return {
                "id": getattr(card, "card_id", None),
                "card_id": getattr(card, "card_id", None),
                "type": self._enum_name(getattr(card, "type", None)),
                "rarity": self._enum_name(getattr(card, "rarity", None)),
                "upgrades": int(getattr(card, "upgrades", 0) or 0),
            }

        trade_vial = bool(has_blood_vial and original_index == 1)
        max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
        current_hp = max(
            0, int(getattr(self.game, "current_hp", max_hp) or 0)
        )
        max_hp_loss = 0 if trade_vial else (max_hp * 3 + 9) // 10
        result["max_hp_delta"] = -max_hp_loss
        result["hp_delta"] = -max(
            0, current_hp - (max_hp - max_hp_loss)
        )
        result["current_cost"]["max_hp"] = max_hp_loss
        result["card_changes"] = {
            "gain": [{
                "id": "Bite", "card_id": "Bite", "type": "ATTACK",
                "rarity": "SPECIAL", "count": 5,
            }],
            "remove": [compact_card(card) for card in removed_cards],
            "upgrade": [], "transform": [],
        }
        if trade_vial:
            result["relic_changes"]["remove"] = [{
                "id": "Blood Vial", "relic_id": "Blood Vial",
            }]
        result.update({
            "operation": (
                "vampires_trade_blood_vial_for_bites"
                if trade_vial else "vampires_trade_max_hp_for_bites"
            ),
            "event_outcome_id": (
                "trade_blood_vial_for_bites"
                if trade_vial else "accept_bites"
            ),
            "acquired_benefit": {
                "kind": "card_package", "id": "Bite",
                "card_id": "Bite", "count": 5,
                "removed_starter_strike_count": len(removed_cards),
            },
        })
        return result

    def _typed_mausoleum_option_consequences(self, option):
        """Project The Mausoleum from typed identity, never display text.

        The initial surface is authoritative only when both enabled option
        indexes and the Writhe preview agree with the base-game contract.
        Later one-button dialogue frames and malformed/modded lookalikes stay
        explicitly unclassified instead of inheriting the index-zero reward.
        """

        screen = getattr(self.game, "screen", None)
        event_id = getattr(screen, "event_id", None)
        if self._token(event_id) != "themausoleum":
            return None

        def unclassified(reason):
            return {
                "event_id": event_id,
                "operation": "unclassified_mausoleum_option",
                "uncertainty": [reason],
                "reason_codes": [reason],
            }

        ascension = getattr(self.game, "ascension_level", None)
        if type(ascension) is not int or ascension < 0:
            return unclassified("mausoleum_ascension_level_missing")
        raw_options = list(getattr(screen, "options", []) or [])
        options = [
            item for item in raw_options
            if not bool(getattr(item, "disabled", False))
            and type(getattr(item, "choice_index", None)) is int
        ]
        index = getattr(option, "choice_index", None)
        if (
            len(raw_options) == 1
            and len(options) == 1
            and index == 0
            and options[0] is option
        ):
            return self._typed_event_zero_consequence(
                event_id,
                "base_game_the_mausoleum_v1",
                "mausoleum_dialog_advance_noop",
                "dialog_advance",
            )
        if (
            len(options) != 2
            or {item.choice_index for item in options} != {0, 1}
        ):
            return unclassified("mausoleum_initial_surface_mismatch")
        by_index = {item.choice_index: item for item in options}
        open_card = getattr(by_index[0], "card", None)
        if (
            open_card is None
            or self._token(getattr(open_card, "card_id", "")) != "writhe"
            or self._enum_name(getattr(open_card, "type", None)) != "CURSE"
            or self._enum_name(getattr(open_card, "rarity", None)) != "CURSE"
            or getattr(by_index[1], "card", None) is not None
        ):
            return unclassified("mausoleum_writhe_preview_mismatch")
        if type(index) is not int or option is not by_index.get(index):
            return unclassified("mausoleum_choice_index_binding_mismatch")

        empty_card_changes = {
            "gain": [], "remove": [], "upgrade": [], "transform": [],
        }
        empty_potion_changes = {
            "gain": [], "remove": [], "replace": [],
        }
        empty_curse = {
            "gain": [], "remove": [], "probability": 0.0,
            "omamori_applicable": False,
            "omamori_charges_consumed": 0,
        }
        if index == 1:
            return {
                "event_id": event_id,
                "mechanism_id": "base_game_the_mausoleum_v1",
                "operation": "mausoleum_leave",
                "event_outcome_id": "leave",
                "hp_delta": 0,
                "max_hp_delta": 0,
                "gold_delta": 0,
                "card_changes": empty_card_changes,
                "relic_changes": {
                    "gain": [], "remove": [], "counter": [],
                },
                "potion_changes": empty_potion_changes,
                "curse": empty_curse,
                "probabilistic_outcomes": [],
                "current_cost": {"gold": 0, "hp": 0, "max_hp": 0},
                "future_costs": [],
                "random_effects": [],
                "leave": True,
            }

        omamori_matches = [
            relic
            for relic in list(getattr(self.game, "relics", []) or [])
            if self._token(getattr(relic, "relic_id", "")) == "omamori"
        ]
        if len(omamori_matches) > 1:
            return unclassified("mausoleum_omamori_identity_ambiguous")
        if omamori_matches:
            counter = getattr(omamori_matches[0], "counter", None)
            if type(counter) is not int or counter < 0:
                return unclassified("mausoleum_omamori_counter_missing")
            omamori_id = (
                getattr(omamori_matches[0], "relic_id", None) or "Omamori"
            )
        else:
            counter = 0
            omamori_id = "Omamori"

        trigger_probability = 1.0 if ascension >= 15 else 0.5
        blocked = counter > 0
        effective_probability = 0.0 if blocked else trigger_probability
        darkstone_gain = (
            6 if not blocked and self._has_relic("Darkstone Periapt") else 0
        )
        random_relic = self._mausoleum_random_relic_effect()
        writhe = self._mausoleum_writhe_card_effect()
        relic_changes = {
            "gain": [],
            "random_gain": [dict(random_relic)],
            "remove": [],
            "counter": [],
        }
        card_changes = dict(empty_card_changes)
        card_changes["conditional_gain"] = ([{
            **dict(writhe),
            "probability": effective_probability,
            "condition": "writhe_branch_not_blocked",
        }] if effective_probability > 0 else [])
        curse = {
            "gain": [],
            "remove": [],
            "conditional_gain": ([dict(writhe)] if not blocked else []),
            "probability": trigger_probability,
            "effective_gain_probability": effective_probability,
            "omamori_applicable": True,
            "omamori_charges_before": counter,
            "omamori_charges_consumed": 1 if blocked else 0,
            "omamori_charge_use_probability": (
                trigger_probability if blocked else 0.0
            ),
            "blocked": blocked,
        }

        def outcome(probability, *, triggered):
            outcome_relics = {
                "gain": [],
                "random_gain": [dict(random_relic)],
                "remove": [],
                "counter": [],
            }
            outcome_cards = dict(empty_card_changes)
            outcome_curse = dict(empty_curse)
            if triggered and blocked:
                outcome_relics["counter"] = [{
                    "id": omamori_id,
                    "before": counter,
                    "after": counter - 1,
                    "delta": -1,
                }]
                outcome_curse.update({
                    "probability": 1.0,
                    "omamori_applicable": True,
                    "omamori_charges_consumed": 1,
                    "blocked": True,
                    "card_id": "Writhe",
                })
                outcome_id = "writhe_blocked_by_omamori"
            elif triggered:
                outcome_cards["gain"] = [dict(writhe)]
                outcome_curse.update({
                    "gain": [dict(writhe)],
                    "probability": 1.0,
                    "omamori_applicable": True,
                    "omamori_charges_consumed": 0,
                    "blocked": False,
                    "card_id": "Writhe",
                })
                outcome_id = "writhe_added"
            else:
                outcome_id = "no_writhe"
            return {
                "id": outcome_id,
                "probability": probability,
                "hp_delta": (
                    darkstone_gain if triggered and not blocked else 0
                ),
                "max_hp_delta": (
                    darkstone_gain if triggered and not blocked else 0
                ),
                "gold_delta": 0,
                "card_changes": outcome_cards,
                "relic_changes": outcome_relics,
                "potion_changes": dict(empty_potion_changes),
                "curse": outcome_curse,
            }

        outcomes = [outcome(trigger_probability, triggered=True)]
        if trigger_probability < 1.0:
            outcomes.append(outcome(
                1.0 - trigger_probability, triggered=False
            ))
        legacy_curse = self._event_curse_gain_consequences(
            1, probability=trigger_probability, curse_id="Writhe"
        )
        return {
            "event_id": event_id,
            "mechanism_id": "base_game_the_mausoleum_v1",
            "operation": "mausoleum_open_coffin",
            "event_outcome_id": "open_coffin",
            "hp_delta": 0,
            "max_hp_delta": 0,
            "gold_delta": 0,
            "card_changes": card_changes,
            "relic_changes": relic_changes,
            "potion_changes": empty_potion_changes,
            "curse": curse,
            "probabilistic_outcomes": outcomes,
            "current_cost": {"gold": 0, "hp": 0, "max_hp": 0},
            "future_costs": [],
            "random_effects": [
                dict(random_relic),
                {
                    "kind": "mausoleum_writhe_branch",
                    "card_id": "Writhe",
                    "probability": trigger_probability,
                    "omamori_blocked": blocked,
                },
            ],
            "strategic_value": {
                "random_relic_value": 16.0,
                "expected_curse_opportunity_cost": round(
                    self._event_curse_opportunity_cost(legacy_curse), 3
                ),
                "expected_effective_curse_delta": effective_probability,
                "expected_omamori_charge_use": (
                    trigger_probability if blocked else 0.0
                ),
            },
        }

    def _optional_colorless_reward_profile(self, count):
        """Value optional three-card colorless reward screens.

        Sensory Stone does not force every advertised card into the deck: each
        reward screen can be skipped.  Model those screens as option value,
        with diminishing returns, instead of claiming a guaranteed card
        delta.  A late or already-complete deck values another roll less, and
        an Act 3 Heart route that still needs the Emerald Key preserves a
        larger HP reserve when already injured.
        """

        count = max(1, min(3, int(count or 1)))
        readiness = float(
            (self._deck_readiness() or {}).get("score", 0.0) or 0.0
        )
        current_hp = max(
            0, int(getattr(self.game, "current_hp", 0) or 0)
        )
        max_hp = max(
            1, int(getattr(self.game, "max_hp", current_hp or 1) or 1)
        )
        hp_ratio = current_hp / max_hp
        remaining_floors = max(
            0, 55 - int(getattr(self.game, "floor", 0) or 0)
        )

        readiness_factor = max(
            0.72, 1.0 - max(0.0, readiness - 0.70) * 0.35
        )
        horizon_factor = max(
            0.72, min(1.0, (remaining_floors + 6.0) / 20.0)
        )
        survival_factor = max(
            0.35, min(1.0, (hp_ratio - 0.30) / 0.45)
        )
        emerald_route_pressure = False
        try:
            heart_plan = HeartPlan.from_game(self.game, self.goal_mode)
            emerald_route_pressure = bool(
                heart_plan.active
                and heart_plan.emerald_missing
                and int(getattr(self.game, "act", 0) or 0) >= 3
            )
        except (AttributeError, TypeError, ValueError):
            # Lightweight replay/test states may omit progression fields.
            emerald_route_pressure = False
        if emerald_route_pressure:
            survival_factor *= max(
                0.55, min(1.0, (hp_ratio - 0.45) / 0.45)
            )

        first_roll_value = (
            6.0 * readiness_factor * horizon_factor * survival_factor
        )
        diminishing = (1.0, 0.92, 0.84)
        marginal_values = [
            first_roll_value * factor for factor in diminishing[:count]
        ]
        return {
            "optional_card_reward_count": count,
            "card_reward_candidates_per_screen": 3,
            "card_reward_pool": "COLORLESS",
            "selection_optional": True,
            "card_delta_min": 0,
            "card_delta_max": count,
            "expected_card_option_value": round(
                sum(marginal_values), 3
            ),
            "marginal_card_option_values": [
                round(value, 3) for value in marginal_values
            ],
            "card_option_value_model": "optional_colorless_three_choice_v1",
            "emerald_route_pressure": emerald_route_pressure,
        }

    def _event_contextualize_known_outcome(self, option, consequences):
        """Fill mechanics hidden behind short/localized event button text.

        These are outcome facts, not fixed choices.  Every option still flows
        through the common scorer and macro candidate list below.  This is
        especially important for multi-screen events: once a reward has been
        taken, a one-button Leave screen must not be mistaken for the initial
        index-zero reward again.
        """

        event_id = self._token(
            getattr(getattr(self.game, "screen", None), "event_id", "")
        )
        raw = str(
            f"{getattr(option, 'label', '')} {getattr(option, 'text', '')}"
        ).lower()
        visible = self._token(raw)
        index = int(getattr(option, "choice_index", 0) or 0)
        options = list(
            getattr(getattr(self.game, "screen", None), "options", []) or []
        )
        is_leave = any(
            marker in visible
            for marker in {
                "leave", "depart", "refuse", "decline", "reject", "oppose",
                "stopreading", "stop", self._token("离开"),
                self._token("反对"), self._token("拒绝"),
            }
            if marker
        )
        is_leave = is_leave or self._token("停止") in visible
        designer_initial_surface = bool(
            event_id == "designer" and len(options) >= 4
        )
        if (
            is_leave
            and event_id != "cursedtome"
            and not designer_initial_surface
        ):
            consequences["leave"] = True
            consequences.setdefault("event_outcome_id", "leave")
            return consequences

        def ensure_curse(count, curse_id, probability=1.0):
            if int(consequences.get("raw_curse_delta", 0) or 0) <= 0:
                consequences.update(
                    self._event_curse_gain_consequences(
                        count,
                        probability=probability,
                        curse_id=curse_id,
                    )
                )
                return
            if curse_id and not consequences.get("curse_id"):
                consequences["curse_id"] = curse_id
            # Rebuild after adding an exact ID so local and model costs do not
            # retain the generic curse price parsed a few lines earlier.
            consequences["curse_trade_profile"] = (
                self._event_curse_trade_profile(consequences)
            )

        current_hp = max(
            0, int(getattr(self.game, "current_hp", 0) or 0)
        )
        max_hp = max(
            1, int(getattr(self.game, "max_hp", current_hp or 1) or 1)
        )
        high_ascension = int(
            getattr(self.game, "ascension_level", 0) or 0
        ) >= 15

        def realized_event_damage(value, *, torii_applies=False):
            damage = max(0, int(value or 0))
            if (
                torii_applies
                and 1 < damage <= 5
                and self._has_relic("Torii")
            ):
                damage = 1
            if damage > 0 and self._has_relic("Tungsten Rod"):
                damage -= 1
            return damage

        if event_id == "bigfish":
            if index == 0:
                # The button advertises one third of max HP, but immediate
                # healing is capped by missing HP.  Replace any text-parsed
                # nominal value so candidate claims match actual settlement.
                consequences["hp_delta"] = min(
                    max_hp - current_hp, max_hp // 3
                )
                consequences["event_outcome_id"] = "banana"
            elif index == 1:
                consequences.setdefault("max_hp_delta", 5)
                consequences["event_outcome_id"] = "donut"
            else:
                consequences["relic_delta"] = 1
                consequences["relic_value"] = 16.0
                consequences["event_outcome_id"] = "box"
                ensure_curse(1, "Regret")

        elif event_id == "goldenidol":
            # Initial screen has Take/Leave.  The three-button trap screen is
            # evaluated separately from its exact post-state.
            if len(options) <= 2 and index == 0:
                consequences["relic_delta"] = 1
                consequences["relic_id"] = "Golden Idol"
                consequences["relic_value"] = 18.0
                consequences["event_outcome_id"] = "take_golden_idol"
                injury = self._event_curse_gain_consequences(
                    1, curse_id="Injury"
                )
                injury_cost = self._event_curse_opportunity_cost(injury)
                damage_amount = max(
                    1,
                    int(max_hp * (0.35 if high_ascension else 0.25)),
                )
                damage_cost = (
                    1_000_000.0
                    if damage_amount >= current_hp
                    else max(3.0, damage_amount * 0.8)
                    * (1.0 + max(0.0, 0.7 - current_hp / max_hp) * 2.4)
                )
                max_hp_loss = max(
                    1,
                    int(max_hp * (0.10 if high_ascension else 0.08)),
                )
                max_hp_cost = 12.0
                consequences["forced_followup_costs"] = {
                    "injury": round(injury_cost, 3),
                    "damage": round(damage_cost, 3),
                    "max_hp": round(max_hp_cost, 3),
                }
                consequences["forced_followup_min_cost"] = round(
                    min(injury_cost, damage_cost, max_hp_cost), 3
                )
            elif len(options) >= 3:
                if index == 0 or "injury" in visible:
                    consequences["event_outcome_id"] = "take_injury"
                    ensure_curse(1, "Injury")
                elif index == 1 or "damage" in visible:
                    consequences.setdefault(
                        "hp_delta",
                        -max(
                            1,
                            int(
                                max_hp
                                * (0.35 if high_ascension else 0.25)
                            ),
                        ),
                    )
                    consequences["event_outcome_id"] = "take_damage"
                else:
                    consequences.setdefault(
                        "max_hp_delta",
                        -max(
                            1,
                            int(
                                max_hp
                                * (0.10 if high_ascension else 0.08)
                            ),
                        ),
                    )
                    post_max_hp = max(
                        1, max_hp + int(consequences["max_hp_delta"])
                    )
                    consequences.setdefault(
                        "hp_delta", -max(0, current_hp - post_max_hp)
                    )
                    consequences["event_outcome_id"] = "lose_max_hp"

        elif event_id in {"liarsgame", "sssserpent", "thesssserpent"}:
            if index == 0:
                consequences["gold_delta"] = (
                    150 if high_ascension else 175
                )
                consequences["event_outcome_id"] = "accept_gold_and_doubt"
                ensure_curse(1, "Doubt")
            else:
                consequences["leave"] = True
                consequences["event_outcome_id"] = "decline"

        elif event_id == "goldenshrine":
            if index == 0:
                consequences["gold_delta"] = (
                    50 if high_ascension else 100
                )
                consequences["event_outcome_id"] = "pray"
            elif index == 1:
                consequences.setdefault("gold_delta", 275)
                consequences["event_outcome_id"] = "desecrate"
                ensure_curse(1, "Regret")
            else:
                consequences["leave"] = True
                consequences["event_outcome_id"] = "leave"

        elif event_id == "shininglight" and len(options) >= 2:
            if index == 0:
                nominal_damage = max(1, max_hp // 5)
                damage = realized_event_damage(
                    nominal_damage, torii_applies=True
                )
                upgradable_count = len(self._event_upgradable_cards())
                upgrade_count = min(2, upgradable_count)
                consequences.update({
                    "hp_delta": -damage,
                    "nominal_hp_loss": nominal_damage,
                    "upgrade_delta": upgrade_count,
                    "random_effects": [{
                        "kind": "random_card_upgrade",
                        "max_count": 2,
                        "available_count": upgradable_count,
                        "effective_count": upgrade_count,
                        "count_semantics": "up_to_available",
                        "domain": "upgradable_deck",
                        "selection_mode": "random",
                    }],
                    "event_outcome_id": "enter_light",
                })
            else:
                consequences["leave"] = True
                consequences["event_outcome_id"] = "leave"

        elif event_id == "accursedblacksmith":
            if index == 0:
                consequences["upgrade_delta"] = 1
                consequences["upgrade_value"] = 11.0
                consequences["event_outcome_id"] = "forge"
            elif index == 1:
                consequences["relic_delta"] = 1
                consequences["relic_id"] = "Warped Tongs"
                consequences["relic_value"] = 19.0
                consequences["event_outcome_id"] = "rummage"
                ensure_curse(1, "Pain")
            else:
                consequences["leave"] = True
                consequences["event_outcome_id"] = "leave"

        elif event_id == "nest" and len(options) >= 2:
            if index == 0:
                consequences["gold_delta"] = 99
                consequences["event_outcome_id"] = "steal_cultist_gold"
            else:
                preview = getattr(option, "card", None)
                card_id = getattr(preview, "card_id", None)
                hp_cost = 8 if high_ascension else 6
                consequences.update({
                    "hp_delta": -hp_cost,
                    "card_delta": 1,
                    "card_id": card_id or "RitualDagger",
                    "event_outcome_id": "join_cult_and_take_ritual_dagger",
                })
                if card_id:
                    consequences["acquired_benefit"] = {
                        "kind": "card_package", "id": card_id,
                        "card_id": card_id, "count": 1,
                    }

        elif event_id in {"transmorgrifier", "transmogrifier"}:
            if index == 0:
                consequences.update({
                    "operation": "transform_card",
                    "card_transform_delta": 1,
                    "event_outcome_id": "open_transform_grid",
                })
            else:
                consequences["leave"] = True
                consequences["event_outcome_id"] = "leave"

        elif event_id == "forgottenaltar":
            has_golden_idol = self._has_relic("Golden Idol")
            if has_golden_idol and index == 0:
                consequences["relic_delta"] = 0
                consequences["lost_relic_id"] = "Golden Idol"
                consequences["relic_id"] = "Bloody Idol"
                consequences["relic_value"] = 15.0
                consequences["event_outcome_id"] = "offer_golden_idol"
            elif index == max(
                int(getattr(item, "choice_index", 0) or 0)
                for item in options or [option]
            ):
                consequences["event_outcome_id"] = "desecrate"
                ensure_curse(1, "Decay")
            else:
                damage_amount = max(
                    1,
                    int(
                        math.floor(
                            max_hp
                            * (0.35 if high_ascension else 0.25)
                            + 0.5
                        )
                    ),
                )
                consequences["max_hp_delta"] = 5
                consequences["hp_gain_before_damage"] = 5
                consequences["damage_amount"] = damage_amount
                consequences["hp_delta"] = 5 - damage_amount
                consequences["event_outcome_id"] = "sacrifice"

        elif designer_initial_surface:
            # The Designer's initial four-button surface is index-stable in
            # the base game.  Its compact button text does not fully describe
            # the two downstream GRID operations, so type those stages here
            # instead of leaving Full Service as a generic gold-only event.
            designer_costs = (
                {0: 50, 1: 75, 2: 110}
                if high_ascension else {0: 40, 1: 60, 2: 90}
            )
            if index in designer_costs:
                gold_cost = designer_costs[index]
                consequences["gold_delta"] = -gold_cost
                consequences["current_cost"] = {
                    "gold": gold_cost, "hp": 0, "max_hp": 0,
                }
            if index == 0:
                consequences["operation"] = "designer_adjustments"
                consequences["event_outcome_id"] = "adjustments"
                consequences["future_costs"] = [{
                    "kind": "designer_grid_selection",
                    "operation": "grid_upgrade",
                    "select_count": 1,
                    "identity_binding": "subsequent_grid_card_instance_id",
                    "commit_timing": "after_grid_confirmation",
                }]
            elif index == 1:
                consequences["operation"] = "designer_clean_up"
                consequences["event_outcome_id"] = "clean_up"
                consequences["future_costs"] = [{
                    "kind": "designer_grid_selection",
                    "operation": "grid_purge",
                    "select_count": 1,
                    "identity_binding": "subsequent_grid_card_instance_id",
                    "commit_timing": "after_grid_confirmation",
                }]
            elif index == 2:
                consequences["operation"] = "designer_full_service"
                consequences["event_outcome_id"] = "full_service"
                consequences["future_costs"] = [
                    {
                        "kind": "designer_grid_selection",
                        "operation": "grid_purge",
                        "select_count": 1,
                        "identity_binding": (
                            "subsequent_grid_card_instance_id"
                        ),
                        "commit_timing": "after_grid_confirmation",
                    },
                    {
                        "kind": "designer_random_card_upgrade",
                        "operation": "random_upgrade",
                        "count": 1,
                        "domain": "post_purge_upgradable_deck",
                        "selection_mode": "random",
                        "commit_timing": "after_grid_confirmation",
                    },
                ]
                consequences["random_effects"] = [{
                    "kind": "random_card_upgrade",
                    "count": 1,
                    "domain": "post_purge_upgradable_deck",
                    "selection_mode": "random",
                }]
            else:
                hp_cost = 5 if high_ascension else 3
                consequences["hp_delta"] = -hp_cost
                consequences["current_cost"] = {
                    "gold": 0, "hp": hp_cost, "max_hp": 0,
                }
                consequences["future_costs"] = []
                consequences["operation"] = "designer_punch_and_leave"
                consequences["event_outcome_id"] = "punch_and_leave"
                consequences["leave"] = True

        elif event_id == "sensorystone" and len(options) >= 3:
            # The original choice indexes are stable even if a protocol
            # client reorders the visible option container.  Every reward is
            # a skippable three-card colorless reward screen, so card gain is
            # bounded rather than guaranteed.
            reward_count = max(1, min(3, index + 1))
            consequences.update(
                self._optional_colorless_reward_profile(reward_count)
            )
            nominal_hp_cost = {1: 0, 2: 5, 3: 10}[reward_count]
            hp_cost = realized_event_damage(nominal_hp_cost)
            consequences["hp_delta"] = -hp_cost
            consequences["nominal_hp_loss"] = nominal_hp_cost
            consequences["hp_change_kind"] = "immediate_hp_loss"
            consequences["event_outcome_id"] = (
                f"recall_{reward_count}_optional_colorless_rewards"
            )

        elif event_id == "cursedtome":
            # The four reading pages cost 1+2+3+10 HP at A0 before yielding
            # one of three strong book relics.  Necronomicon's curse is one
            # branch of that random reward rather than a guaranteed curse.
            allowed_costs = (
                {1, 2, 3, 15} if high_ascension else {1, 2, 3, 10}
            )
            visible_costs = [
                int(value)
                for value in re.findall(r"\d+", raw)
                if int(value) in allowed_costs
            ]
            immediate_cost = max(
                visible_costs,
                default=max(
                    0, -int(consequences.get("hp_delta", 0) or 0)
                ),
            )
            # Choice 1 is Stop/Leave on every page.  It can carry an
            # immediate three-HP cost, but never awards a book or rolls the
            # Necronomicurse branch.
            if index != 0 or is_leave:
                consequences["leave"] = True
                consequences["hp_delta"] = -immediate_cost
                consequences["hp_change_kind"] = "immediate_hp_loss"
                consequences["event_outcome_id"] = "stop_reading"
                return consequences
            if high_ascension:
                remaining_cost = {
                    1: 21,
                    2: 20,
                    3: 18,
                    15: 15,
                }.get(immediate_cost, 21)
            else:
                remaining_cost = {
                    1: 16,
                    2: 15,
                    3: 13,
                    10: 10,
                }.get(immediate_cost, 16)
            consequences["hp_delta"] = -remaining_cost
            consequences["hp_change_kind"] = "staged_total_to_book"
            consequences["relic_delta"] = 1
            consequences["relic_id"] = "Random Book Relic"
            consequences["relic_value"] = 26.0
            consequences["random_book_relic"] = True
            consequences["book_relic_ids"] = [
                "Enchiridion", "Nilry's Codex", "Necronomicon"
            ]
            consequences["event_outcome_id"] = "finish_reading"
            ensure_curse(1, "Necronomicurse", probability=1.0 / 3.0)

        return consequences

    def _event_option_consequences(self, option):
        """Return signed, provider-visible consequences for an event option.

        Visible event text remains authoritative, but direction and exact
        owned resources are resolved once here for both local scoring and the
        macro adviser.  In particular, ``lose card/potion; gain relic`` must
        not become a positive card/potion reward merely because ``gain`` also
        appears later in the sentence.
        """

        typed_event = self._typed_progress_event_option_consequences(option)
        if typed_event is not None:
            return typed_event

        typed_event = self._typed_a0_event_option_consequences(option)
        if typed_event is not None:
            return typed_event

        typed_mausoleum = self._typed_mausoleum_option_consequences(option)
        if typed_mausoleum is not None:
            return typed_mausoleum

        raw = str(
            f"{getattr(option, 'label', '')} {getattr(option, 'text', '')}"
        ).lower()
        text = self._token(raw)

        def contains(*markers):
            return any(self._token(marker) in text for marker in markers)

        def numeric_values(*patterns):
            values = []
            for pattern in patterns:
                values.extend(
                    int(value) for value in re.findall(pattern, raw)
                )
            return values

        # Bind direction at clause/verb-segment granularity.  Whole-option
        # detection is wrong for exchanges such as "Lose 84 gold; gain a
        # card": the later word ``card`` is not the object of ``lose``.
        direction_boundary = re.compile(
            r"(?=(?:\b(?:lose|give|offer|sacrifice|trade\s+away|pay|spend|"
            r"gain|obtain|receive|find|choose|get)\b|"
            r"失去|给他|交出|献出|放弃|支付|花费|获得|得到|发现|选择))",
            flags=re.IGNORECASE,
        )
        loss_start = re.compile(
            r"^(?:lose|give|offer|sacrifice|trade\s+away|pay|spend)\b",
            flags=re.IGNORECASE,
        )
        gain_start = re.compile(
            r"^(?:gain|obtain|receive|find|choose|get)\b",
            flags=re.IGNORECASE,
        )
        loss_segments = []
        gain_segments = []
        for clause in re.split(r"[.;。；\n]+", raw):
            for segment in direction_boundary.split(clause):
                segment = segment.strip(" [](){}:,-")
                if not segment:
                    continue
                if loss_start.match(segment) or segment.startswith(
                    ("失去", "给他", "交出", "献出", "放弃", "支付", "花费")
                ):
                    loss_segments.append(segment)
                elif gain_start.match(segment) or segment.startswith(
                    ("获得", "得到", "发现", "选择")
                ):
                    gain_segments.append(segment)

        def resource_mentioned(segment, english, localized):
            return bool(
                re.search(rf"\b{english}s?\b", segment, flags=re.IGNORECASE)
                or localized in segment
            )

        def exact_owned_match(items, haystack, *fields):
            normalized_haystack = self._token(haystack)
            matches = []
            for item in items:
                markers = {
                    self._token(getattr(item, field, ""))
                    for field in fields
                }
                markers = {
                    marker for marker in markers if len(marker) >= 2
                }
                matched = max(
                    (
                        len(marker)
                        for marker in markers
                        if marker in normalized_haystack
                    ),
                    default=0,
                )
                if matched:
                    matches.append((matched, item))
            return max(matches, key=lambda pair: pair[0])[1] if matches else None

        lost_card = exact_owned_match(
            list(getattr(self.game, "deck", []) or []),
            " ".join(loss_segments),
            "card_id", "name",
        )
        try:
            real_potions = list(self.game.get_real_potions())
        except (AttributeError, TypeError):
            real_potions = [
                potion
                for potion in list(getattr(self.game, "potions", []) or [])
                if self._token(getattr(potion, "potion_id", ""))
                not in {"", "potionslot"}
            ]
        lost_potion = exact_owned_match(
            real_potions, " ".join(loss_segments), "potion_id", "name"
        )

        loses_card = bool(
            lost_card is not None
            or any(
                resource_mentioned(segment, "card", "牌")
                for segment in loss_segments
            )
        )
        loses_potion = bool(
            lost_potion is not None
            or any(
                resource_mentioned(segment, "potion", "药水")
                for segment in loss_segments
            )
        )
        gains_card = bool(
            any(
                resource_mentioned(segment, "card", "牌")
                for segment in gain_segments
            )
        )
        gains_potion = bool(
            any(
                resource_mentioned(segment, "potion", "药水")
                for segment in gain_segments
            )
        )
        gains_relic = bool(
            any(
                resource_mentioned(segment, "relic", "遗物")
                for segment in gain_segments
            )
            or (
                contains("relic", "遗物")
                and not any(
                    resource_mentioned(segment, "relic", "遗物")
                    for segment in loss_segments
                )
            )
        )

        gold_costs = numeric_values(
            r"(?:lose|pay|spend|offer)\s*(\d+)\s*gold",
            r"(?:失去|支付|花费|献出)\s*(\d+)\s*(?:枚)?金币",
        )
        gold_rewards = numeric_values(
            r"(?:gain|receive|obtain|find)\s*(\d+)\s*gold",
            r"(?:获得|得到|发现)\s*(\d+)\s*(?:枚)?金币",
        )
        hp_costs = numeric_values(
            r"(?:lose|take|suffer)\s*(\d+)\s*(?:hp|health|damage)",
            r"(?:失去|受到|承受)\s*(\d+)\s*(?:点)?(?:生命|伤害)",
        )
        heal_values = numeric_values(
            r"(?:heal|recover)\s*(\d+)\s*(?:hp|health)?",
            r"(?:治疗|回复|恢复)\s*(\d+)\s*(?:点)?(?:生命)?",
        )
        max_hp_costs = numeric_values(
            r"(?:lose|reduce)\s*(\d+)\s*(?:max\s*hp|max\s*health)",
            r"(?:失去|减少)\s*(\d+)\s*(?:点)?最大生命",
        )
        max_hp_gains = numeric_values(
            r"(?:gain|increase)\s*(\d+)\s*(?:max\s*hp|max\s*health)",
            r"(?:获得|增加|提升)\s*(\d+)\s*(?:点)?最大生命",
        )

        consequences = {}
        if gains_relic:
            consequences["relic_delta"] = 1
        if loses_card or gains_card:
            consequences["card_delta"] = int(gains_card) - int(loses_card)
            consequences["card_loss"] = loses_card
            consequences["card_gain"] = gains_card
            consequences["card_change_kind"] = (
                "exchange" if loses_card and gains_card
                else "forced_loss" if loses_card else "gain"
            )
        if loses_card:
            if lost_card is not None:
                consequences["lost_card"] = {
                    "card": self._macro_card_facts(lost_card),
                    **self._event_card_loss_opportunity_cost(lost_card),
                }
            else:
                consequences["lost_card"] = {"exact_card_unknown": True}
        if loses_potion or gains_potion:
            consequences["potion_delta"] = (
                int(gains_potion) - int(loses_potion)
            )
            consequences["potion_loss"] = loses_potion
            consequences["potion_gain"] = gains_potion
            consequences["potion_change_kind"] = (
                "exchange" if loses_potion and gains_potion
                else "forced_loss" if loses_potion else "gain"
            )
        if loses_potion:
            if lost_potion is not None:
                keep_value = float(self._potion_keep_score(lost_potion))
                consequences["lost_potion"] = {
                    "id": getattr(lost_potion, "potion_id", None),
                    "name": getattr(lost_potion, "name", None),
                    "description": self._macro_description(
                        getattr(lost_potion, "description", "")
                    ),
                    "keep_value": round(keep_value, 3),
                    "opportunity_cost": round(
                        max(4.0, keep_value * 0.43), 3
                    ),
                }
            else:
                consequences["lost_potion"] = {
                    "exact_potion_unknown": True,
                    "opportunity_cost": 8.0,
                }
        if gold_costs or gold_rewards:
            consequences["gold_delta"] = (
                max(gold_rewards, default=0) - max(gold_costs, default=0)
            )
        if contains(
            "lose half hp", "lose half your hp", "half your health",
            "lose half health", "half current hp", "生命值减半",
            "失去一半生命", "失去一半生命值", "当前生命值减半",
        ):
            consequences["hp_delta"] = -max(
                1, int(getattr(self.game, "current_hp", 1) or 1) // 2
            )
            consequences["hp_change_kind"] = "half_current_hp"
        elif hp_costs or heal_values:
            consequences["hp_delta"] = (
                max(heal_values, default=0) - max(hp_costs, default=0)
            )
        if max_hp_costs or max_hp_gains:
            consequences["max_hp_delta"] = (
                max(max_hp_gains, default=0)
                - max(max_hp_costs, default=0)
            )
        if contains(
            "cannot heal", "cannot recover", "no longer heal",
            "no healing", "healing is disabled", "不再回复生命",
            "无法再回复", "不能治疗", "无法治疗", "停止回复生命",
        ):
            consequences["healing_locked"] = True
        preview_card = getattr(option, "card", None)
        preview_is_curse = bool(
            preview_card is not None
            and (
                getattr(preview_card, "rarity", None)
                == spirecomm.spire.card.CardRarity.CURSE
                or getattr(preview_card, "type", None)
                == spirecomm.spire.card.CardType.CURSE
            )
        )
        mentions_curse = bool(
            contains("curse", "诅咒", "normality")
            or preview_is_curse
        )
        if contains("leave", "depart", "walk away", "refuse", "decline", "离开", "逃离", "拒绝"):
            consequences["leave"] = True
        if contains("fight", "combat", "battle", "战斗", "挑战"):
            consequences["combat_delta"] = 1
        # Direction matters here as much as it does for cards and potions.
        # The broad word check above is a fallback for localized gain text;
        # an explicit remove/purge clause must override it instead of turning
        # "Remove all Curses" into curse_delta=+1.
        owned_curses = sum(
            getattr(card, "rarity", None)
            == spirecomm.spire.card.CardRarity.CURSE
            for card in list(getattr(self.game, "deck", []) or [])
        )
        if contains(
            "remove all curses", "remove every curse", "purge all curses"
        ):
            consequences["curse_delta"] = -owned_curses
            consequences["curse_change_kind"] = "remove_all"
        elif contains(
            "remove a curse", "remove one curse", "purge a curse"
        ):
            consequences["curse_delta"] = -min(1, owned_curses)
            consequences["curse_change_kind"] = "remove_one"
        elif mentions_curse:
            curse_count = 1
            count_match = re.search(
                r"\b(\d+|one|two|three|four|five)\s+"
                r"(?:curse(?:s)?|normalit(?:y|ies))\b",
                raw,
                flags=re.IGNORECASE,
            )
            if count_match:
                count_token = count_match.group(1).lower()
                curse_count = {
                    "one": 1,
                    "two": 2,
                    "three": 3,
                    "four": 4,
                    "five": 5,
                }.get(
                    count_token,
                    int(count_token) if count_token.isdigit() else 1,
                )
            elif contains(
                "two normality", "2 normality", "两个凡庸", "2张凡庸"
            ):
                curse_count = 2
            percentages = re.findall(r"(\d+(?:\.\d+)?)\s*%", raw)
            probability = (
                float(percentages[0]) / 100.0 if percentages else 1.0
            )
            screen = getattr(self.game, "screen", None)
            event_identity = self._token(
                f"{getattr(screen, 'event_id', '')} "
                f"{getattr(screen, 'event_name', '')}"
            )
            if "mausoleum" in event_identity:
                probability = (
                    1.0
                    if int(
                        getattr(self.game, "ascension_level", 0) or 0
                    ) >= 15
                    else 0.5
                )
            curse_id = None
            if preview_is_curse:
                curse_id = getattr(preview_card, "card_id", None)
            elif contains("normality"):
                curse_id = "Normality"
            consequences.update(
                self._event_curse_gain_consequences(
                    curse_count,
                    probability=probability,
                    curse_id=curse_id,
                )
            )
        return self._event_contextualize_known_outcome(
            option, consequences
        )

    def _event_gold_gain_value(self, amount):
        """Value event gold without erasing large curse-trade packages."""

        amount = max(0, int(amount or 0))
        if amount <= 0 or self._has_relic("Ectoplasm"):
            return 0.0
        current_gold = max(0, int(getattr(self.game, "gold", 0) or 0))
        remaining_floors = max(
            0, 55 - int(getattr(self.game, "floor", 0) or 0)
        )
        liquidity = max(
            0.60, 1.0 - max(0, current_gold - 250) / 1000.0
        )
        route_horizon = max(
            0.65, min(1.0, (remaining_floors + 8.0) / 24.0)
        )
        # High enough to distinguish 275 from 100 gold, but bounded so a
        # permanent curse is not hand-waved away as cash.
        return min(42.0, amount / 7.0) * liquidity * route_horizon

    def _event_upgradable_cards(self, deck=None):
        cards = list(
            deck if deck is not None else getattr(self.game, "deck", []) or []
        )
        return [
            card for card in cards
            if bool(getattr(card, "is_upgradable", True))
            and int(getattr(card, "upgrades", 0) or 0) == 0
        ]

    @staticmethod
    def _event_random_upgrade_count(consequences):
        effects = consequences.get("random_effects") or []
        random_effect = next((
            effect for effect in effects
            if isinstance(effect, dict)
            and effect.get("kind") == "random_card_upgrade"
        ), None)
        if random_effect is None:
            return None
        if "upgrade_delta" in consequences:
            return max(0, int(consequences.get("upgrade_delta", 0) or 0))
        return max(0, int(random_effect.get("max_count", 0) or 0))

    def _event_deck_operation_values(self, *, random_upgrade_count=None):
        """Price remove/upgrade/transform operations from the live deck.

        A random k-card upgrade samples without replacement. With additive,
        fixed-state marginal scores, every eligible card has inclusion
        probability k / n, yielding the exact expected total marginal value.
        """

        deck = list(getattr(self.game, "deck", []) or [])
        if len(deck) < 5 and random_upgrade_count is None:
            return {
                "remove": 13.0,
                "upgrade": 11.0,
                "transform": 9.0,
                "best_removal_score": None,
                "best_upgrade_score": None,
                "deck_readiness": None,
                "context_status": "partial_deck_fallback",
            }
        full_deck_context = len(deck) >= 5
        removal_scores = (
            [float(self._removal_score(card)) for card in deck]
            if full_deck_context else []
        )
        default_upgrade_cards = [
            card for card in deck
            if int(getattr(card, "upgrades", 0) or 0) == 0
        ]
        upgrade_cards = (
            self._event_upgradable_cards(deck)
            if random_upgrade_count is not None else default_upgrade_cards
        )
        upgrade_scores = [
            float(self._upgrade_score(card)) for card in upgrade_cards
        ]
        bounded_upgrade_scores = [
            max(0.0, min(30.0, value)) for value in upgrade_scores
        ]
        best_removal = max(removal_scores, default=0.0)
        best_upgrade = max(upgrade_scores, default=0.0)
        readiness = (
            float((self._deck_readiness() or {}).get("score", 0.0) or 0.0)
            if full_deck_context else None
        )
        demand = self._deck_demand_vector() if full_deck_context else {}
        remove_value = (
            max(-8.0, min(30.0, best_removal / 5.0))
            if full_deck_context else 13.0
        )
        upgrade_value = max(bounded_upgrade_scores, default=0.0)
        random_upgrade_evaluation = {}
        if random_upgrade_count is not None:
            requested_count = max(0, int(random_upgrade_count or 0))
            available_count = len(upgrade_cards)
            effective_count = min(requested_count, available_count)
            inclusion_probability = (
                effective_count / available_count if available_count else 0.0
            )
            upgrade_value = (
                sum(bounded_upgrade_scores) * inclusion_probability
            )
            random_upgrade_evaluation = {
                "random_upgrade_sampling": "uniform_without_replacement",
                "typed_upgrade_delta": requested_count,
                "random_upgrade_available_count": available_count,
                "random_upgrade_effective_count": effective_count,
                "random_upgrade_inclusion_probability": round(
                    inclusion_probability, 6
                ),
                "random_upgrade_expected_value": round(upgrade_value, 3),
                "random_upgrade_pool": [
                    {
                        "card_id": getattr(card, "card_id", None),
                        "card_instance_id": getattr(card, "uuid", None),
                        "bounded_marginal_value": round(value, 3),
                    }
                    for card, value in zip(
                        upgrade_cards, bounded_upgrade_scores
                    )
                ],
            }
        # A transform combines removal of the weakest card with an uncertain
        # replacement.  Weak or bloated decks have more upside, while a mature
        # compact deck should not receive the old unconditional nine points.
        transform_value = max(
            -6.0,
            min(
                20.0,
                best_removal * 0.14
                + (1.0 - (readiness or 0.0)) * 4.0
                + float(demand.get("trim", 0.0) or 0.0) * 3.0
                - 3.0,
            ),
        ) if full_deck_context else 9.0
        result = {
            "remove": round(remove_value, 3),
            "upgrade": round(upgrade_value, 3),
            "transform": round(transform_value, 3),
            "best_removal_score": (
                round(best_removal, 3) if full_deck_context else None
            ),
            "best_upgrade_score": round(best_upgrade, 3),
            "deck_readiness": (
                round(readiness, 3) if readiness is not None else None
            ),
        }
        if not full_deck_context:
            result["context_status"] = "partial_deck_random_upgrade"
        result.update(random_upgrade_evaluation)
        return result

    def _event_deck_operation_values_for_option(self, option):
        consequences = self._event_option_consequences(option)
        return self._event_deck_operation_values(
            random_upgrade_count=self._event_random_upgrade_count(consequences)
        )

    def _generic_optional_fight_risk(self):
        """Price an optional unknown event fight against an elite loss budget."""
        options = [option for option in getattr(self.game.screen, "options", [])
                   if not getattr(option, "disabled", False)]
        if len(options) < 2 or not any(
            self._event_option_consequences(option).get("leave") for option in options
        ):
            return None
        readiness = self._optional_event_fight_profile()
        capacity = float(readiness["capacity"])
        ordinary_elite_loss = self._estimated_map_room_cost(
            SimpleNamespace(symbol="E", has_emerald_key=False),
        )
        expected_loss = max(
            6.0, ordinary_elite_loss * (1.6 - 1.2 * capacity)
            - min(8.0, float(readiness["potions"]) * 2.0),
        )
        upper_loss = max(expected_loss, self._estimated_elite_survival_cost())
        hp = max(0, self.game.current_hp)
        risk = max(0.0, min(1.0, (upper_loss - hp) / max(8.0, upper_loss)))
        return {
            "capacity": round(capacity, 3),
            "expected_hp_loss": round(expected_loss, 3),
            "upper_hp_loss": round(upper_loss, 3),
            "risk_index": round(risk, 4),
            "utility_cost": expected_loss * (0.75 + max(
                0.0, 0.70 - hp / max(1, self.game.max_hp),
            )) + risk * 180.0,
            "semantics": "uncalibrated_optional_encounter_budget",
        }

    def _generic_event_option_score(
        self, option, hp_ratio, *, include_components=False
    ):
        """Score an event outcome from visible semantics, independent of index."""

        raw = str(
            f"{getattr(option, 'label', '')} {getattr(option, 'text', '')}"
        ).lower()
        text = self._token(raw)
        score = 0.0
        signals = []
        score_components = []
        consequences = self._event_option_consequences(option)

        def adjust(code, value):
            nonlocal score
            value = float(value)
            score += value
            score_components.append((
                f"{str(code)}_{len(score_components)}", value
            ))

        def contains(*markers):
            return any(self._token(marker) in text for marker in markers)

        def numeric_values(*patterns):
            values = []
            for pattern in patterns:
                values.extend(int(value) for value in re.findall(pattern, raw))
            return values

        hp_costs = numeric_values(
            r"(?:lose|take|suffer)\s*(\d+)\s*(?:hp|health|damage)",
            r"(?:失去|受到|承受)\s*(\d+)\s*(?:点)?(?:生命|伤害)",
        )
        if contains(
            "lose half hp", "lose half your hp", "half your health",
            "lose half health", "half current hp", "生命值减半",
            "失去一半生命", "失去一半生命值", "当前生命值减半",
        ):
            hp_costs.append(
                max(1, int(getattr(self.game, "current_hp", 1) or 1) // 2)
            )
        heal_values = numeric_values(
            r"(?:heal|recover)\s*(\d+)\s*(?:hp|health)?",
            r"(?:治疗|回复|恢复)\s*(\d+)\s*(?:点)?(?:生命)?",
        )
        gold_costs = numeric_values(
            r"(?:lose|pay|spend|offer)\s*(\d+)\s*gold",
            r"(?:失去|支付|花费|献出)\s*(\d+)\s*(?:枚)?金币",
        )
        gold_rewards = numeric_values(
            r"(?:gain|receive|obtain|find)\s*(\d+)\s*gold",
            r"(?:获得|得到|发现)\s*(\d+)\s*(?:枚)?金币",
        )

        signed_hp_delta = int(consequences.get("hp_delta", 0) or 0)
        if signed_hp_delta < 0:
            # A typed consequence is the authoritative post-event HP delta.
            # Do not let display text's gross damage replace that net value:
            # Forgotten Altar, for example, grants 5 current/max HP before
            # dealing its listed damage.  Pricing the gross 20 damage on top
            # of the typed -15 delta made a removable Decay curse look safer
            # than permanent max-HP growth despite two imminent rest sites.
            hp_costs = [-signed_hp_delta]
        elif signed_hp_delta > 0:
            heal_values = [signed_hp_delta]
        signed_gold_delta = int(consequences.get("gold_delta", 0) or 0)
        if signed_gold_delta < 0:
            gold_costs.append(-signed_gold_delta)
        elif signed_gold_delta > 0:
            gold_rewards.append(signed_gold_delta)

        missing_hp = max(0, int(self.game.max_hp) - int(self.game.current_hp))
        if consequences.get("leave", False) or contains(
            "leave", "depart", "walk away", "refuse", "decline",
            "离开", "逃离", "拒绝",
        ):
            adjust("leave", 1.0)
            signals.append("leave")
        if contains("heal", "recover", "banana", "rest", "治疗", "回复", "恢复生命"):
            requested = max(heal_values, default=missing_hp)
            adjust("heal", min(16.0, missing_hp, requested) * 0.7)
            signals.append("heal")
        max_hp_delta = int(consequences.get("max_hp_delta", 0) or 0)
        if max_hp_delta > 0:
            adjust("max_hp", min(14.0, max_hp_delta * 2.0))
            signals.append("max_hp")
        elif max_hp_delta < 0:
            adjust("max_hp_cost", -min(24.0, -max_hp_delta * 1.6))
            signals.append("max_hp_cost")
        elif contains("max hp", "maxhp", "最大生命") and not contains(
            "lose max hp", "losemaxhp", "失去最大生命", "减少最大生命"
        ):
            adjust("max_hp", 10.0)
            signals.append("max_hp")
        gains_relic = contains(
            "gain a relic", "gain relic", "obtain a relic", "receive a relic",
            "find a relic", "获得遗物", "得到遗物", "发现遗物",
        )
        strategic_value = consequences.get("strategic_value")
        strategic_value = (
            strategic_value if isinstance(strategic_value, dict) else {}
        )
        relic_value = consequences.get(
            "relic_value", strategic_value.get("random_relic_value")
        )
        if relic_value is not None or gains_relic or (
            contains("relic", "遗物")
            and not contains("lose relic", "offer relic", "失去遗物", "献出遗物")
        ):
            adjust(
                "relic", float(relic_value if relic_value is not None else 16.0)
            )
            signals.append("relic")
        deck_operation_values = None
        if contains(
            "remove", "purify", "移除", "净化",
            "upgrade", "升级", "transform", "变化", "转化",
        ):
            deck_operation_values = self._event_deck_operation_values(
                random_upgrade_count=self._event_random_upgrade_count(
                    consequences
                )
            )
        if contains("remove", "purify", "移除", "净化"):
            adjust("remove", deck_operation_values["remove"])
            signals.append("remove")
        if contains("upgrade", "升级"):
            adjust("upgrade", deck_operation_values["upgrade"])
            signals.append("upgrade")
        if contains("transform", "变化", "转化"):
            adjust("transform", deck_operation_values["transform"])
            signals.append("transform")
        if (
            consequences.get("upgrade_value") is not None
            and not contains("upgrade")
        ):
            adjust(
                "upgrade", float(consequences.get("upgrade_value") or 0.0)
            )
            signals.append("upgrade")
        if gold_rewards or (
            contains("gain gold", "receive gold", "obtain gold", "获得金币", "得到金币")
            and not gold_costs
        ):
            adjust(
                "gold",
                self._event_gold_gain_value(max(gold_rewards, default=60)),
            )
            signals.append("gold")
        if (
            consequences.get("potion_gain", False)
            and not self._has_relic("Sozu")
        ):
            adjust("potion", 6.0)
            signals.append("potion")
        optional_card_reward_count = int(
            consequences.get("optional_card_reward_count", 0) or 0
        )
        if optional_card_reward_count > 0:
            adjust(
                "optional_card_reward",
                float(
                    consequences.get("expected_card_option_value", 0.0)
                    or 0.0
                ),
            )
            signals.append("optional_card_reward")
        elif consequences.get("card_gain", False):
            adjust("card", 7.0)
            signals.append("card")
        if consequences.get("potion_loss", False):
            potion_cost = float(
                (consequences.get("lost_potion") or {}).get(
                    "opportunity_cost", 8.0
                )
            )
            adjust("potion_cost", -potion_cost)
            signals.append("potion_cost")
        if consequences.get("card_loss", False):
            card_cost = float(
                (consequences.get("lost_card") or {}).get(
                    "opportunity_cost", 14.0
                )
            )
            adjust("card_cost", -card_cost)
            signals.append("card_cost")
        forced_followup_cost = float(
            consequences.get("forced_followup_min_cost", 0.0) or 0.0
        )
        if forced_followup_cost > 0.0:
            adjust("forced_followup_cost", -forced_followup_cost)
            signals.append("forced_followup_cost")
        raw_curse_delta = int(
            consequences.get("raw_curse_delta", 0) or 0
        )
        if raw_curse_delta > 0:
            curse_cost = self._event_curse_opportunity_cost(
                consequences,
                unit_cost=24.0 if contains("normality") else 18.0,
            )
            if float(
                consequences.get("expected_effective_curse_delta", 0.0)
                or 0.0
            ) > 0.0:
                adjust("curse_cost", -curse_cost)
                signals.append("curse_cost")
                if float(consequences.get("curse_probability", 1.0)) < 1.0:
                    signals.append("curse_risk")
            else:
                # The curse cannot enter the deck, but spending an Omamori
                # charge still has a small expected opportunity cost.
                adjust("omamori_charge_cost", -curse_cost)
            if float(
                consequences.get("expected_omamori_charge_use", 0.0)
                or 0.0
            ) > 0.0:
                signals.append("omamori_prevents_curse")
        elif "expected_curse_opportunity_cost" in strategic_value:
            curse_cost = float(
                strategic_value.get("expected_curse_opportunity_cost", 0.0)
                or 0.0
            )
            expected_effective = float(
                strategic_value.get("expected_effective_curse_delta", 0.0)
                or 0.0
            )
            expected_charge = float(
                strategic_value.get("expected_omamori_charge_use", 0.0)
                or 0.0
            )
            if expected_effective > 0.0:
                adjust("curse_cost", -curse_cost)
                signals.extend(["curse_cost", "curse_risk"])
            elif expected_charge > 0.0:
                adjust("omamori_charge_cost", -curse_cost)
                signals.append("omamori_prevents_curse")
        if max_hp_delta == 0 and contains(
            "lose max hp", "losemaxhp", "失去最大生命", "减少最大生命"
        ):
            adjust("max_hp_cost", -12.0)
            signals.append("max_hp_cost")
        if gold_costs or contains("lose gold", "pay gold", "失去金币", "花费金币", "支付金币"):
            adjust(
                "gold_cost",
                -min(24.0, max(gold_costs, default=50) / 6.0),
            )
            signals.append("gold_cost")
        if hp_costs:
            hp_cost = max(hp_costs)
            if hp_cost >= int(self.game.current_hp):
                adjust("lethal_hp_cost", -1000.0)
                signals.append("lethal_hp_cost")
            else:
                risk_multiplier = 1.0 + max(0.0, 0.7 - hp_ratio) * 2.4
                adjust(
                    "hp_cost",
                    -max(3.0, hp_cost * 0.8) * risk_multiplier,
                )
            signals.append("hp_cost")
        elif contains(
            "damage", "lose hp", "suffer damage",
            "受到伤害", "失去生命",
        ):
            adjust(
                "hp_cost",
                -(7.0 + max(0.0, 0.7 - hp_ratio) * 24.0),
            )
            signals.append("hp_cost")
        healing_lock = contains(
            "cannot heal", "cannot recover", "no longer heal",
            "no healing", "healing is disabled", "不再回复生命",
            "无法再回复", "不能治疗", "无法治疗", "停止回复生命",
        )
        if healing_lock:
            # A permanent recovery lock removes campfire, relic and potion
            # outs. At full HP the immediate cost is small; below 92% it
            # must dominate an otherwise attractive reward.
            adjust(
                "healing_lock",
                -(6.0 + max(0.0, 0.92 - hp_ratio) * 85.0),
            )
            signals.append("healing_lock")
            # Permanent recovery lockouts are much riskier for a deck that
            # still lacks universal block/draw/scaling coverage. Keep the
            # reward visible, but make that lost recovery option explicit.
            readiness_score = float(
                (self._deck_readiness() or {}).get("score", 0.0) or 0.0
            )
            if readiness_score < 0.60:
                adjust(
                    "healing_lock_weak_deck_penalty",
                    -(0.60 - readiness_score) * 18.0,
                )
                signals.append("healing_lock_weak_deck_penalty")
        half_hp_option = contains(
            "lose half hp", "lose half your hp", "half your health",
            "lose half health", "half current hp", "生命值减半",
        )
        if half_hp_option:
            readiness_score = float(
                (self._deck_readiness() or {}).get("score", 0.0) or 0.0
            )
            post_ratio = max(0.0, hp_ratio * 0.5)
            if post_ratio < 0.55:
                adjust(
                    "half_hp_low_post_reserve_penalty",
                    -(0.55 - post_ratio) * 55.0,
                )
                signals.append("half_hp_low_post_reserve_penalty")
            if readiness_score < 0.60:
                adjust(
                    "half_hp_weak_deck_penalty",
                    -(0.60 - readiness_score) * 16.0,
                )
                signals.append("half_hp_weak_deck_penalty")
        if consequences.get("combat_delta", 0) > 0 or contains("fight", "combat", "battle", "战斗", "挑战"):
            risk = self._generic_optional_fight_risk()
            if risk is not None:
                adjust("optional_fight_survival_cost", -risk["utility_cost"])
                signals.extend(["combat_cost", "optional_fight_survival_cost"])
            else:
                adjust("combat_cost", -(5.0 + max(0.0, 0.82 - hp_ratio) * 28.0))
                signals.append("combat_cost")

        curse_delta = int(consequences.get("curse_delta", 0) or 0)
        if curse_delta < 0:
            # Removal text is a benefit, not a newly acquired curse merely
            # because it contains that noun.
            adjust("curse_removal", min(24.0, -curse_delta * 6.0))
            signals.append("curse_removal")

        if not signals:
            # Unknown is explicitly uncertain, not silently equivalent to the
            # first button being good. Stable index is only a final tie-break.
            adjust("unknown", -2.0)
            signals.append("unknown")
        result = (score, signals, score_components)
        return result if include_components else result[:2]

    def _optional_event_fight_profile(self):
        """Compact deck/readiness evidence for optional event combats."""

        deck = list(getattr(self.game, "deck", []) or [])
        non_basic = sum(
            getattr(card, "rarity", None)
            not in {
                spirecomm.spire.card.CardRarity.BASIC,
                spirecomm.spire.card.CardRarity.CURSE,
            }
            for card in deck
        )
        offense = 0
        defense = 0
        aoe = 0
        scaling = 0
        for card in deck:
            developed = (
                getattr(card, "rarity", None)
                not in {
                    spirecomm.spire.card.CardRarity.BASIC,
                    spirecomm.spire.card.CardRarity.CURSE,
                }
                or int(getattr(card, "upgrades", 0) or 0) > 0
            ) and getattr(card, "type", None) not in {
                spirecomm.spire.card.CardType.CURSE,
                spirecomm.spire.card.CardType.STATUS,
            }
            if not developed:
                continue
            tags = self._card_build_tags(card)
            if tags & {"damage", "aoe", "poison:source", "lightning:source", "dark:source"}:
                offense += 1
            if "aoe" in tags:
                aoe += 1
            if "block" in tags:
                defense += 1
            if "scaling" in tags:
                scaling += 1
        upgraded = sum(
            int(getattr(card, "upgrades", 0) or 0) > 0 for card in deck
        )
        potions = len(self.game.get_real_potions())
        hp = max(0, int(getattr(self.game, "current_hp", 0) or 0))
        max_hp = max(1, int(getattr(self.game, "max_hp", hp or 1) or 1))
        hp_ratio = hp / max_hp
        healing_outs = sum(
            self._has_relic(relic_id)
            for relic_id in {
                "Burning Blood", "Black Blood", "Meat on the Bone",
                "Bloody Idol", "Meal Ticket", "Pantograph",
                "Toy Ornithopter", "Self Repair",
            }
        )
        boss_id = self._boss_id()
        score = (
            non_basic * 0.35
            + offense * 1.1
            + defense * 1.2
            + scaling * 0.8
            + upgraded * 0.5
            + potions * 2.0
        )
        # Keep count-based context for encounter-specific models, but expose
        # drawable/payable capacity separately for survival decisions.
        shared = self._deck_readiness()
        capacity = max(0.0, min(1.0, float(shared["score"])))
        tag_score = score
        return {
            "score": round(score, 3),
            "tag_score": round(tag_score, 3),
            "capacity": round(capacity, 3),
            "shared_readiness": shared,
            "non_basic": non_basic,
            "offense": offense,
            "defense": defense,
            "aoe": aoe,
            "scaling": scaling,
            "upgraded": upgraded,
            "potions": potions,
            "hp": hp,
            "max_hp": max_hp,
            "hp_ratio": round(hp_ratio, 3),
            "missing_hp": max(0, max_hp - hp),
            "healing_outs": healing_outs,
            "boss_id": boss_id,
            "ready": bool(score >= 14.0 and hp_ratio >= 0.65),
        }

    def _mushrooms_decision_profile(self):
        """Price the three-Fungi-Beast fight against the recovery option.

        The event exposes stable original button indexes, while its localized
        fight label may be unreadable.  Keep the choice state-dependent: AOE,
        frontload, block, potions, current HP and the actual Odd Mushroom
        acquisition value all feed one logged utility.
        """

        optional = self._optional_event_fight_profile()
        readiness = self._deck_readiness()
        coverage = readiness.get("coverage") or {}
        encounter_strength = min(
            1.0,
            0.30 * float(coverage.get("frontload", 0.0) or 0.0)
            + 0.30 * float(coverage.get("aoe", 0.0) or 0.0)
            + 0.25 * float(coverage.get("block", 0.0) or 0.0)
            + 0.10 * float(coverage.get("draw", 0.0) or 0.0)
            + 0.05 * float(coverage.get("scaling", 0.0) or 0.0),
        )
        absolute_strength = min(
            1.0,
            0.10 * float(optional.get("offense", 0) or 0)
            + 0.16 * float(optional.get("defense", 0) or 0)
            + 0.18 * float(optional.get("aoe", 0) or 0)
            + 0.10 * float(optional.get("scaling", 0) or 0),
        )
        combat_strength = max(encounter_strength, absolute_strength)
        developed_strength = min(
            1.0, float(optional.get("score", 0.0) or 0.0) / 18.0
        )
        potion_count = max(0, int(optional.get("potions", 0) or 0))
        expected_loss = max(
            3.0,
            24.0
            - 13.0 * combat_strength
            - 4.0 * developed_strength
            - min(6.0, potion_count * 2.0),
        )
        upper_loss = expected_loss * (
            1.35 + max(0.0, 0.55 - combat_strength) * 0.35
        )
        hp = max(0, int(getattr(self.game, "current_hp", 0) or 0))
        max_hp = max(1, int(getattr(self.game, "max_hp", hp or 1) or 1))
        hp_ratio = min(1.0, hp / max_hp)
        loss_tail_width = max(6.0, upper_loss - expected_loss * 0.55)
        death_risk = max(
            0.0,
            min(
                1.0,
                (upper_loss - max(0.0, hp - 1.0)) / loss_tail_width,
            ),
        )
        try:
            potion_ids = {
                self._token(getattr(potion, "potion_id", ""))
                for potion in self.game.get_real_potions()
            }
        except (AttributeError, TypeError):
            potion_ids = set()
        survival_outs = sorted(
            potion_id for potion_id in potion_ids
            if potion_id in {
                "fairypotion", "fairyinabottle", "smokebomb",
            }
        )
        if self._has_active_lizard_tail():
            survival_outs.append("lizardtail")
        hard_survival_veto = bool(
            death_risk >= 1.0 - 1e-9 and not survival_outs
        )

        odd_mushroom = SimpleNamespace(
            relic_id="Odd Mushroom", name="Odd Mushroom"
        )
        relic_value = float(self._relic_acquisition_score(odd_mushroom))
        hp_loss_weight = 0.75 + max(0.0, 0.70 - hp_ratio)
        expected_hp_loss_cost = expected_loss * hp_loss_weight
        death_risk_cost = death_risk * 180.0
        fight_score = (
            -1_000_000.0
            if hard_survival_veto
            else relic_value - expected_hp_loss_cost - death_risk_cost
        )
        return {
            "optional_fight_readiness": optional,
            "encounter_coverage": round(encounter_strength, 3),
            "absolute_combat_strength": round(absolute_strength, 3),
            "combat_strength": round(combat_strength, 3),
            "developed_strength": round(developed_strength, 3),
            "expected_hp_loss": expected_loss,
            "upper_hp_loss": upper_loss,
            "death_risk": death_risk,
            "survival_outs": survival_outs,
            "hard_survival_veto": hard_survival_veto,
            "odd_mushroom_value": relic_value,
            "hp_loss_weight": hp_loss_weight,
            "expected_hp_loss_cost": expected_hp_loss_cost,
            "death_risk_cost": death_risk_cost,
            "fight_score": fight_score,
        }

    def _masked_bandits_decision_profile(self):
        """Price paying the Masked Bandits against taking their fight.

        The event used to log utility-like candidate scores and then ignore
        them in favour of three unrelated cliffs (78% HP, 45 absolute HP and
        85 gold).  In particular, a full-health Apparitions deck with less
        than 45 max HP was forced to surrender every coin.  Keep this model
        deliberately cheap, but make every input continuous and make the
        returned candidate scores the sole source used by the caller.

        This is an encounter estimate rather than a combat simulation: the
        enemies do not exist in the game state until Fight has been chosen.
        It therefore prices a conservative loss tail, deck coverage for a
        three-enemy front-loaded fight, relevant potions/relics, the Red Mask
        reward and the value of preserving current gold.  A state with no
        way to end the fight, or predicted certain death without a genuine
        escape/revival outlet, is a hard veto; all other survival risk remains
        visible in the same net-utility score.
        """

        hp = max(0, int(getattr(self.game, "current_hp", 0) or 0))
        max_hp = max(1, int(getattr(self.game, "max_hp", hp or 1) or 1))
        hp_ratio = min(1.0, hp / max_hp)
        gold = max(0, int(getattr(self.game, "gold", 0) or 0))
        act = max(1, int(getattr(self.game, "act", 1) or 1))
        floor = max(0, int(getattr(self.game, "floor", 0) or 0))

        optional = self._optional_event_fight_profile()
        deck_profile = self._deck_profile()
        deck_readiness = self._deck_readiness(deck_profile)
        boss_readiness = self._boss_entry_readiness(deck_profile)
        coverage = deck_readiness.get("coverage") or {}
        encounter_coverage = (
            0.32 * float(coverage.get("frontload", 0.0) or 0.0)
            + 0.30 * float(coverage.get("block", 0.0) or 0.0)
            + 0.18 * float(coverage.get("aoe", 0.0) or 0.0)
            + 0.12 * float(coverage.get("draw", 0.0) or 0.0)
            + 0.08 * float(coverage.get("scaling", 0.0) or 0.0)
        )
        developed_strength = min(
            1.0, float(optional.get("score", 0.0) or 0.0) / 24.0
        )
        # Use an absolute, monotone *tactical* measure for the actual
        # encounter strength.  Generic non-basic/upgraded counts are not
        # combat output: a deck of upgraded Setup/Prepared must not look able
        # to defeat three attackers.  Normalized coverage remains a required
        # floor for starter-heavy decks, while real offense/block/scaling can
        # only raise (not dilute) the estimate.
        absolute_tactical_strength = min(
            1.0,
            0.12 * float(optional.get("offense", 0) or 0)
            + 0.14 * float(optional.get("defense", 0) or 0)
            + 0.10 * float(optional.get("scaling", 0) or 0),
        )
        combat_strength = max(
            encounter_coverage, absolute_tactical_strength
        )
        scaling_evidence = (
            deck_readiness.get("scaling_mechanism") or {}
        )
        paired_damage_engines = scaling_evidence.get(
            "paired_engines"
        ) or {}
        standalone_damage_engines = scaling_evidence.get(
            "standalone"
        ) or {}
        indirect_damage_support = sum(
            max(0.0, float(paired_damage_engines.get(name, 0.0) or 0.0))
            for name in ("poison", "lightning", "dark")
        )
        indirect_damage_support += max(
            0.0,
            float(standalone_damage_engines.get("noxiousfumes", 0.0) or 0.0),
        )
        indirect_damage_ids = {
            "athousandcuts", "caltrops", "combust", "firebreathing",
            "juggernaut",
        }
        indirect_damage_support += sum(
            int((deck_profile.get("card_counts") or {}).get(card_id, 0) or 0)
            for card_id in indirect_damage_ids
        )
        indirect_damage_relics = {
            "bronzescales", "charonsashes", "mercuryhourglass",
        }
        indirect_damage_support += sum(
            self._has_relic(relic_id) for relic_id in indirect_damage_relics
        )
        reliable_damage_sources = max(
            0.0,
            float(
                (deck_profile.get("roles") or {}).get("damage", 0.0)
                or 0.0
            ) + indirect_damage_support,
        )

        try:
            potions = list(self.game.get_real_potions())
        except (AttributeError, TypeError):
            potions = []
        potion_credits = {
            "ghostinajar": 1.00,
            "fairypotion": 1.00,
            "fairyinabottle": 1.00,
            "smokebomb": 0.80,
            "blockpotion": 0.70,
            "ancientpotion": 0.60,
            "explosivepotion": 0.60,
            "weakpotion": 0.55,
            "essenceofsteel": 0.55,
            "regenpotion": 0.50,
            "bloodpotion": 0.45,
            "energypotion": 0.45,
            "dexteritypotion": 0.45,
            "focuspotion": 0.45,
            "strengthpotion": 0.45,
            "speedpotion": 0.40,
            "swiftpotion": 0.40,
            "gamblersbrew": 0.40,
            "entropicbrew": 0.40,
            "firepotion": 0.35,
            "attackpotion": 0.30,
            "skillpotion": 0.30,
            "powerpotion": 0.30,
            "colorlesspotion": 0.30,
        }
        potion_rows = []
        for potion in potions:
            potion_id = self._token(getattr(potion, "potion_id", ""))
            credit = float(potion_credits.get(potion_id, 0.0))
            potion_rows.append({
                "potion_id": potion_id,
                "encounter_credit": round(credit, 3),
            })
        potion_support = min(
            1.25,
            sum(row["encounter_credit"] for row in potion_rows),
        )
        emergency_potion_ids = {
            "ghostinajar", "fairypotion", "fairyinabottle", "smokebomb"
        }
        emergency_outs = [
            row["potion_id"]
            for row in potion_rows
            if row["potion_id"] in emergency_potion_ids
        ]

        relic_weights = {
            "fossilizedhelix": 0.24,
            "incenseburner": 0.18,
            "threadandneedle": 0.15,
            "torii": 0.15,
            "anchor": 0.12,
            "horncleat": 0.12,
            "captainswheel": 0.12,
            "orichalcum": 0.10,
            "tungstenrod": 0.10,
            "bronzescales": 0.10,
            "bagofmarbles": 0.10,
            "akabeko": 0.10,
            "bagofpreparation": 0.08,
            "lantern": 0.08,
            "vajra": 0.08,
            "datadisk": 0.08,
        }
        relic_rows = []
        for relic in list(getattr(self.game, "relics", []) or []):
            relic_id = self._token(getattr(relic, "relic_id", ""))
            credit = float(relic_weights.get(relic_id, 0.0))
            if credit > 0.0:
                relic_rows.append({
                    "relic_id": relic_id,
                    "encounter_credit": round(credit, 3),
                })
        relic_support = min(
            0.75,
            sum(row["encounter_credit"] for row in relic_rows),
        )
        revival_relics = (
            ["Lizard Tail"] if self._has_active_lizard_tail() else []
        )
        emergency_outs.extend(self._token(item) for item in revival_relics)
        survival_exit_outs = [
            item
            for item in emergency_outs
            if item in {
                "fairypotion", "fairyinabottle", "smokebomb",
                "lizardtail",
            }
        ]
        mitigation_outs = [
            item for item in emergency_outs
            if item not in set(survival_exit_outs)
        ]

        # Tags saturate before the deck can draw/pay its answers. Calibrate
        # that ceiling with access consistency and actual damage progress.
        consistency = float(deck_readiness.get("consistency", 0.0) or 0.0)
        kill_clock = float((deck_readiness.get("kill_clock") or {}).get("score", 0.0))
        effective_strength = combat_strength * (
            0.30 + 0.35 * consistency + 0.35 * kill_clock
        )
        expected_gross_hp_loss = max(
            8.0,
            50.0
            - 36.0 * effective_strength
            - 9.0 * potion_support
            - 8.0 * relic_support,
        )
        # Only encounter-triggered healing counts. Meal Ticket/Pantograph
        # heal elsewhere; post-victory healing cannot rescue a lethal hit.
        guaranteed_healing = (
            (12 if self._has_relic("Black Blood") else
             6 if self._has_relic("Burning Blood") else 0)
            + (12 if self._has_relic("Meat on the Bone")
               and hp - expected_gross_hp_loss <= max_hp * 0.5 else 0)
            + (5 if self._has_relic("Bloody Idol") else 0)
        )
        healing_credit = min(
            expected_gross_hp_loss * 0.35,
            guaranteed_healing,
        )
        expected_net_hp_loss = max(
            3.0, expected_gross_hp_loss - healing_credit
        )
        upper_loss = expected_gross_hp_loss * (
            1.65
            + 0.25 * (1.0 - consistency)
            - 0.20 * effective_strength
            - 0.08 * min(1.0, potion_support + relic_support)
        )
        # Matching the loss tail leaves no HP for the route or model error.
        # Preserve one small encounter reserve before valuing optional gold.
        # This is an uncalibrated risk index, not a measured death probability.
        survival_reserve = max_hp * 0.10
        reserve_risk = max(
            0.0,
            (upper_loss + survival_reserve - hp) / max(8.0, upper_loss),
        )
        weak_deck_uncertainty = max(
            0.0, 0.30 - combat_strength
        ) * 0.50
        base_death_risk = min(
            1.0, reserve_risk + weak_deck_uncertainty
        )
        death_risk = base_death_risk
        if survival_exit_outs:
            death_risk *= 0.45
        elif mitigation_outs:
            # Intangible can materially improve a normal fight, but it is
            # neither an escape nor a revival and must never turn literal or
            # predicted certain death into a certified survival outlet.
            death_risk *= 0.72

        # Act 2 ends on floor 33.  Preserve more HP close to the boss and
        # when the current deck is not yet boss-ready, without introducing a
        # new floor or readiness cliff.
        floors_to_boss = max(0, 33 - floor) if act == 2 else 0
        boss_proximity = (
            max(0.0, min(1.0, (8.0 - floors_to_boss) / 8.0))
            if act == 2
            else 0.0
        )
        boss_score = max(
            0.0,
            min(1.0, float(boss_readiness.get("score", 0.0) or 0.0)),
        )
        hp_opportunity_rate = (
            0.62
            + 1.25 * (1.0 - hp_ratio)
            + 0.22 * boss_proximity
            + 0.45 * (1.0 - boss_score)
        )
        # Even a nonlethal bad draw consumes the HP needed for the route
        # after this optional fight. Price part of the loss tail, rather than
        # making all uncertainty free whenever current HP exceeds the tail.
        risk_adjusted_hp_loss = expected_net_hp_loss + 0.25 * max(
            0.0, upper_loss - expected_gross_hp_loss
        )
        expected_hp_cost = risk_adjusted_hp_loss * hp_opportunity_rate
        downstream_route_cost = (
            boss_proximity * max(0.0, 0.62 - boss_score) * 15.0
        )

        gold_rate = 0.13
        if self._has_relic("Membership Card"):
            gold_rate *= 1.25
        if self._has_relic("The Courier"):
            gold_rate *= 1.15
        gold_opportunity_value = gold * gold_rate
        red_mask_value = (
            (3.0 if self._has_relic("Red Mask") else 18.0)
            if reliable_damage_sources > 0.0
            else 0.0
        )

        pay_score = round(-gold_opportunity_value, 3)
        raw_fight_score = (
            red_mask_value
            - expected_hp_cost
            - 200.0 * death_risk
            - downstream_route_cost
        )
        predicted_certain_death = base_death_risk >= 1.0 - 1e-9
        has_escape = "smokebomb" in emergency_outs
        no_damage_exit = bool(
            reliable_damage_sources <= 0.0 and not has_escape
        )
        hard_survival_veto = bool(
            not survival_exit_outs
            and (hp <= 1 or predicted_certain_death)
        ) or no_damage_exit
        fight_score = round(
            -1_000_000_000.0 if hard_survival_veto else raw_fight_score,
            3,
        )
        return {
            "scores": {
                "pay": pay_score,
                "fight": fight_score,
            },
            "hard_survival_veto": hard_survival_veto,
            "hard_survival_veto_reason": (
                (
                    "no_reliable_damage_or_escape"
                    if no_damage_exit
                    else (
                        "one_hp_without_revival_or_escape"
                        if hp <= 1
                        else "predicted_certain_death_without_revival_or_escape"
                    )
                )
                if hard_survival_veto
                else None
            ),
            "raw_fight_score_before_veto": round(raw_fight_score, 3),
            "gold": gold,
            "gold_opportunity_value": round(gold_opportunity_value, 3),
            "red_mask_reward_value": round(red_mask_value, 3),
            "hp": hp,
            "max_hp": max_hp,
            "hp_ratio": round(hp_ratio, 3),
            "combat_strength": round(combat_strength, 3),
            "effective_combat_strength": round(effective_strength, 3),
            "developed_strength_diagnostic": round(
                developed_strength, 3
            ),
            "absolute_tactical_strength": round(
                absolute_tactical_strength, 3
            ),
            "encounter_coverage": round(encounter_coverage, 3),
            "reliable_damage_sources": round(
                reliable_damage_sources, 3
            ),
            "indirect_damage_support": round(
                indirect_damage_support, 3
            ),
            "has_escape": has_escape,
            "deck_readiness": deck_readiness,
            "legacy_development_profile": optional,
            "expected_gross_hp_loss": round(expected_gross_hp_loss, 3),
            "expected_post_fight_healing": round(healing_credit, 3),
            "expected_net_hp_loss": round(expected_net_hp_loss, 3),
            "upper_hp_loss_estimate": round(upper_loss, 3),
            "survival_reserve_hp": round(survival_reserve, 3),
            "death_risk_semantics": "uncalibrated_survival_risk_index",
            "death_risk": round(death_risk, 4),
            "base_death_risk_before_emergency_resources": round(
                base_death_risk, 4
            ),
            "expected_hp_opportunity_cost": round(expected_hp_cost, 3),
            "risk_adjusted_hp_loss": round(risk_adjusted_hp_loss, 3),
            "downstream_route_cost": round(downstream_route_cost, 3),
            "act": act,
            "floor": floor,
            "floors_to_boss": floors_to_boss,
            "boss_proximity": round(boss_proximity, 3),
            "boss_readiness": boss_readiness,
            "potion_support": round(potion_support, 3),
            "potion_details": potion_rows,
            "combat_relic_support": round(relic_support, 3),
            "combat_relic_details": relic_rows,
            "emergency_outs": emergency_outs,
            "survival_exit_outs": survival_exit_outs,
            "mitigation_outs": mitigation_outs,
        }

    def _note_for_yourself_card_value(self, option):
        """Return the offered Note card's value from preview or visible name."""

        preview = getattr(option, "card", None)
        if preview is not None:
            return float(self._card_reward_score(preview)), getattr(
                preview, "card_id", None
            )

        visible = self._token(
            f"{getattr(option, 'label', '')} {getattr(option, 'text', '')}"
        )
        if any(marker in visible for marker in {"strike", "defend", "curse"}):
            return -100.0, None

        # Localized/modded event text does not always expose the preview
        # object.  A visible exact card name is still stronger evidence than
        # the option index; use the active character's reward ordering.
        matches = [
            (rank, card_id)
            for card_id, rank in self.priorities.CARD_PRIORITIES.items()
            if self._token(card_id) and self._token(card_id) in visible
        ]
        if not matches:
            return None, None
        rank, card_id = min(matches)
        skip_rank = self.priorities.CARD_PRIORITIES.get("Skip", 30)
        return (24.0 - rank if rank < skip_rank else -20.0), card_id

    def _apparition_event_valuation(
        self, received, apparitions_before, *, upgraded=False,
    ):
        """Price Ghosts from draw access and marginal damage prevention.

        Apparitions are a reusable answer in every later combat, but five
        copies are not five identical fixed-value cards.  A large deck can
        fail to see them before the dangerous turns, an energy-strained deck
        can fail to play every ethereal copy, existing Intangible charges
        reduce marginal coverage, and strong ordinary block reduces the
        damage that Intangible would otherwise prevent.  Keep those facts in
        one signed, replayable profile instead of assigning every copy 12.5.
        """

        received = max(0, int(received or 0))
        apparitions_before = max(0, int(apparitions_before or 0))
        profile = self._deck_profile()
        readiness = self._deck_readiness(profile)
        coverage = readiness.get("coverage") or {}
        roles = profile.get("roles") or {}
        deck_size = max(1, int(profile.get("size", 0) or 0))
        post_deck_size = deck_size + received

        draw_support = max(0.0, float(roles.get("draw", 0.0) or 0.0))
        cards_seen_per_turn = 5.0 + min(4.0, draw_support * 0.75)
        cycle_turns_before = deck_size / max(1.0, cards_seen_per_turn)
        cycle_turns_after = post_deck_size / max(1.0, cards_seen_per_turn)

        act = max(1, int(getattr(self.game, "act", 1) or 1))
        boss_id = self._boss_id()
        frontload_coverage = max(
            0.0, min(1.0, float(coverage.get("frontload", 0.0) or 0.0))
        )
        # Slow decks need protection for more turns, while a known boss makes
        # a long defensive window more relevant than a short hallway fight.
        relevant_turn_horizon = (
            3.25
            + 0.90 * (1.0 - frontload_coverage)
            + (0.35 if act >= 2 else 0.0)
            + (0.35 if boss_id else 0.0)
        )
        access_fraction = max(
            0.0,
            min(1.0, relevant_turn_horizon / max(1.0, cycle_turns_after)),
        )

        average_cost = max(
            0.0, float(profile.get("average_cost", 0.0) or 0.0)
        )
        energy_strain = max(
            0.0, float(readiness.get("energy_strain", 0.0) or 0.0)
        )
        max_energy = max(
            1, int(getattr(self.game, "max_energy", 3) or 3)
        )
        deck_ids = set((profile.get("card_counts") or {}).keys())
        corruption_support = "corruption" in deck_ids
        energy_playability_fraction = (
            0.92
            + 0.04 * max(0, max_energy - 3)
            + (0.10 if corruption_support else 0.0)
            - 0.35 * energy_strain
            - 0.04 * max(0.0, average_cost - 1.10)
        )
        energy_playability_fraction = max(
            0.55, min(0.99, energy_playability_fraction)
        )
        # Unupgraded Apparitions are Ethereal. Drawing one on a quiet turn or
        # beside a more important setup card loses the charge permanently.
        timing_alignment_fraction = (
            1.0
            if upgraded
            else max(
                0.58,
                min(
                    0.78,
                    0.66
                    + 0.05 * int(act >= 2)
                    + 0.04 * int(bool(boss_id))
                    - 0.05 * frontload_coverage,
                ),
            )
        )
        # Velvet Choker leaves at most five ordinary card slots on a turn
        # where an Apparition must be played.  Treat cards seen beyond those
        # five slots as real competition for an Ethereal defensive card.
        # This corrects a recent accepted Ghosts package whose predicted
        # 64.4% playability was followed by only two plays in five observed
        # opportunities.  The factor is derived from visible throughput and
        # remains one for decks that do not pressure the six-card cap.
        choker_slot_fraction = 1.0
        if self._has_relic("Velvet Choker"):
            choker_slot_fraction = max(
                0.55,
                min(1.0, 5.0 / max(1.0, cards_seen_per_turn)),
            )
        playability_fraction = (
            energy_playability_fraction
            * timing_alignment_fraction
            * choker_slot_fraction
        )

        pressure_by_act = {1: 14.0, 2: 22.0, 3: 30.0, 4: 48.0}
        expected_incoming = pressure_by_act.get(act, 30.0)
        expected_incoming += {
            "hexaghost": 2.0,
            "slimeboss": 1.0,
            "champ": 4.0,
            "collector": 3.0,
            "automaton": 5.0,
            "timeeater": 5.0,
            "awakenedone": 5.0,
            "donuanddeca": 5.0,
            "theheart": 9.0,
            "corruptheart": 9.0,
        }.get(boss_id, 0.0)
        block_coverage = max(
            0.0, min(1.0, float(coverage.get("block", 0.0) or 0.0))
        )
        ordinary_block_absorption = expected_incoming * (
            0.12 + 0.38 * block_coverage
        )
        defense_access = profile.get("defense_access") or {}
        # Compare an Intangible charge to the block already available on
        # that dangerous turn. The sustainable readiness budget reserves
        # energy for offense, but it is not a limit on emergency blocking.
        ordinary_block_absorption = max(
            ordinary_block_absorption,
            min(expected_incoming, defense_access.get("burst_block_per_turn", 0.0)),
        )
        expected_hit_residue = {1: 1.3, 2: 1.7, 3: 2.2, 4: 8.0}.get(
            act, 2.2
        )
        prevented_per_charge = max(
            4.0,
            expected_incoming
            - ordinary_block_absorption
            - expected_hit_residue,
        )
        # A permanent card is reused in every remaining combat.  This bounded
        # weight acknowledges that persistence without multiplying by an
        # unknowable route length.
        persistent_answer_weight = 1.12 + 0.06 * max(0, 4 - act)

        marginal_card_values = []
        for offset in range(received):
            saturation_position = apparitions_before + offset
            saturation = 1.0 / (1.0 + 0.14 * saturation_position)
            marginal_card_values.append(
                prevented_per_charge
                * access_fraction
                * playability_fraction
                * persistent_answer_weight
                * saturation
            )
        expected_prevention_value = sum(marginal_card_values)

        scaling_coverage = max(
            0.0, min(1.0, float(coverage.get("scaling", 0.0) or 0.0))
        )
        kill_clock = self._long_fight_kill_clock(
            profile, scaling_coverage=scaling_coverage
        )
        cycle_delay = max(0.0, cycle_turns_after - cycle_turns_before)
        first_cycle_delay_cost = cycle_delay * (
            4.0
            + 2.5 * (1.0 - scaling_coverage)
            + 2.0 * max(0.0, average_cost - 1.0)
        )
        kill_clock_bloat_cost = (
            received
            * (0.55 + 0.95 * (1.0 - float(kill_clock["score"])))
            * (0.80 + 0.20 * access_fraction)
            * (0.35 if upgraded else 1.0)
        )

        max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
        current_hp = max(
            0, int(getattr(self.game, "current_hp", max_hp) or 0)
        )
        max_hp_loss = max_hp // 2
        post_max_hp = max(1, max_hp - max_hp_loss)
        post_current_hp = min(current_hp, post_max_hp)
        sustain_ids = {
            "blackblood", "bloodvial", "bloodyidol", "burningblood",
            "eternalfeather", "mealticket", "meatonthebone",
            "pantograph", "selfrepair", "toyornithopter",
        }
        sustain_relic_ids = [
            getattr(relic, "relic_id", None)
            for relic in list(getattr(self.game, "relics", []) or [])
            if self._token(getattr(relic, "relic_id", "")) in sustain_ids
        ]
        healing_blocked = self._has_relic("Mark of the Bloom")
        max_hp_capacity_weight = (
            0.52
            + 0.08 * int(bool(sustain_relic_ids) and not healing_blocked)
            + 0.05 * int(act <= 2)
            + 0.06 * int(post_max_hp < 45)
        )
        max_hp_capacity_cost = max_hp_loss * max_hp_capacity_weight
        immediate_hp_clamp_cost = max(
            0, current_hp - post_current_hp
        ) * 0.80
        score = (
            expected_prevention_value
            - first_cycle_delay_cost
            - kill_clock_bloat_cost
            - max_hp_capacity_cost
            - immediate_hp_clamp_cost
        )
        score_inputs = {
            "expected_prevention_value": expected_prevention_value,
            "first_cycle_delay_cost": first_cycle_delay_cost,
            "kill_clock_bloat_cost": kill_clock_bloat_cost,
            "max_hp_capacity_cost": max_hp_capacity_cost,
            "immediate_hp_clamp_cost": immediate_hp_clamp_cost,
        }
        return {
            "score": score,
            "score_evidence": self._linear_score_contract(
                "ghosts_contextual_apparition_value_v3",
                score_inputs,
                (
                    (
                        "expected_prevention_value",
                        "expected_prevention_value",
                        1.0,
                    ),
                    (
                        "first_cycle_delay_cost",
                        "first_cycle_delay_cost",
                        -1.0,
                    ),
                    (
                        "kill_clock_bloat_cost",
                        "kill_clock_bloat_cost",
                        -1.0,
                    ),
                    (
                        "max_hp_capacity_cost",
                        "max_hp_capacity_cost",
                        -1.0,
                    ),
                    (
                        "immediate_hp_clamp_cost",
                        "immediate_hp_clamp_cost",
                        -1.0,
                    ),
                ),
            ),
            "received": received,
            "apparitions_before": apparitions_before,
            "upgraded": bool(upgraded),
            "deck_size_before": deck_size,
            "deck_size_after": post_deck_size,
            "cards_seen_per_turn": round(cards_seen_per_turn, 3),
            "cycle_turns_before": round(cycle_turns_before, 3),
            "cycle_turns_after": round(cycle_turns_after, 3),
            "relevant_turn_horizon": round(relevant_turn_horizon, 3),
            "access_fraction": round(access_fraction, 4),
            "energy_playability_fraction": round(
                energy_playability_fraction, 4
            ),
            "timing_alignment_fraction": round(
                timing_alignment_fraction, 4
            ),
            "choker_slot_fraction": round(choker_slot_fraction, 4),
            "playability_fraction": round(playability_fraction, 4),
            "expected_incoming": round(expected_incoming, 3),
            "ordinary_block_absorption": round(
                ordinary_block_absorption, 3
            ),
            "prevented_per_charge": round(prevented_per_charge, 3),
            "persistent_answer_weight": round(
                persistent_answer_weight, 3
            ),
            "marginal_card_values": [
                round(value, 3) for value in marginal_card_values
            ],
            "expected_prevention_value": round(
                expected_prevention_value, 3
            ),
            "first_cycle_delay_cost": round(first_cycle_delay_cost, 3),
            "kill_clock_bloat_cost": round(kill_clock_bloat_cost, 3),
            "max_hp_capacity_cost": round(max_hp_capacity_cost, 3),
            "max_hp_capacity_weight": round(max_hp_capacity_weight, 3),
            "sustain_relic_ids": sustain_relic_ids,
            "healing_blocked": bool(healing_blocked),
            "immediate_hp_clamp_cost": round(
                immediate_hp_clamp_cost, 3
            ),
            "post_current_hp": post_current_hp,
            "post_max_hp": post_max_hp,
            "boss_id": boss_id or None,
            "block_coverage": round(block_coverage, 3),
            "frontload_coverage": round(frontload_coverage, 3),
            "scaling_coverage": round(scaling_coverage, 3),
            "kill_clock": kill_clock,
        }

    def choose_event_action(self, valid_options):
        if not valid_options:
            self._record_noncombat_decision(
                "event_no_visible_choice_proceed",
                [{
                    "id": "action:proceed",
                    "choice_id": "action:proceed",
                    "choice_index": None,
                    "action": "proceed",
                    "semantic_id": "proceed",
                    "score": 1.0,
                    "label": "Proceed",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": True,
                    "reason": "selected_only_protocol_action",
                    "consequences": {"operation": "proceed"},
                }],
                candidate_contract={
                    "score_source": "single_protocol_visible_action",
                    "strategy_quality_auditable": True,
                    "all_visible_options_scored": True,
                    "visible_option_count": 1,
                    "identity_source": "protocol_action",
                },
                chosen="Proceed",
                chosen_id="action:proceed",
            )
            return ProceedAction()
        event_id = self._token(self.game.screen.event_id)
        hp_ratio = self.game.current_hp / max(1, self.game.max_hp)
        by_index = {option.choice_index: option for option in valid_options}

        def bind_positive_grid(source):
            self.pending_selection_context = {
                "kind": "positive_card",
                "source": source,
                "act": int(self.game.act),
                "floor": int(self.game.floor),
            }

        def bind_destructive_grid(source, operation, select_count):
            self.pending_selection_context = {
                "kind": "destructive_card",
                "source": source,
                "operation": operation,
                "select_count": int(select_count),
                "act": int(self.game.act),
                "floor": int(self.game.floor),
            }

        def find_option(markers, fallback):
            return next(
                (
                    option
                    for option in valid_options
                    if any(
                        marker
                        in self._token(
                            f"{getattr(option, 'label', '')} "
                            f"{getattr(option, 'text', '')}"
                        )
                        for marker in markers
                    )
                ),
                fallback,
            )

        def option_has(option, *markers):
            visible = self._token(
                f"{getattr(option, 'label', '')} "
                f"{getattr(option, 'text', '')}"
            )
            return any(
                self._token(marker) in visible
                for marker in markers
                if self._token(marker)
            )

        def option_is_leave(option):
            return option_has(
                option,
                "leave", "depart", "refuse", "decline", "cower",
                "离开", "拒绝", "退缩",
            )

        def choose_index(
            index, reason, candidate_scores=None,
            candidate_contract_override=None, **details
        ):
            option = by_index.get(index)
            if option is None:
                return None
            if candidate_scores is None:
                candidates = [
                    {
                        "id": item.choice_index,
                        "score": None,
                        "label": getattr(item, "label", None),
                        "text": self._macro_description(
                            getattr(item, "text", "")
                        ),
                    }
                    for item in valid_options
                ]
                candidate_contract = {
                    "score_source": "hardcoded_choice",
                    "strategy_quality_auditable": False,
                    "all_visible_options_scored": False,
                }
            else:
                candidates = candidate_scores
                candidate_contract = {
                    "score_source": "explicit_local_utility",
                    "strategy_quality_auditable": True,
                    "all_visible_options_scored": True,
                }
            if isinstance(candidate_contract_override, dict):
                candidate_contract.update(candidate_contract_override)
            normalized_candidates = []
            semantic_prefix = (
                "neow" if event_id in {"neow", "neowevent"} else "event"
            )
            for candidate in candidates:
                if isinstance(candidate, dict):
                    row = dict(candidate)
                    candidate_index = row.get(
                        "choice_index", row.get("id")
                    )
                else:
                    candidate_index, candidate_score = candidate
                    row = {"id": candidate_index, "score": candidate_score}
                try:
                    candidate_index = int(candidate_index)
                except (TypeError, ValueError):
                    candidate_index = None
                row.setdefault("id", candidate_index)
                row.update({
                    "choice_id": f"{semantic_prefix}:{candidate_index}",
                    "choice_index": candidate_index,
                    "action": "choose",
                    "semantic_id": f"{semantic_prefix}:{candidate_index}",
                    "legal": True,
                    "visible": True,
                })
                row.setdefault(
                    "reason",
                    "selected_event_candidate"
                    if candidate_index == int(index)
                    else "visible_unchosen_event_candidate",
                )
                normalized_candidates.append(row)
            self._record_noncombat_decision(
                reason,
                normalized_candidates,
                candidate_contract=candidate_contract,
                event_id=event_id,
                chosen_index=index,
                hp_ratio=round(hp_ratio, 3),
                **details,
            )
            # Bind ordinary event choices semantically.  CommunicationMod's
            # event option index may refer to the original button while the
            # current choice list is filtered/reindexed after disabled
            # options.  Keeping the index is useful for audit/tests; the name
            # lets autoplay resolve the exact visible option safely.
            return ChooseAction(
                choice_index=option.choice_index,
                name=option.label,
            )

        def choose_scored_event(rows, reason, **details):
            """Choose the exact argmax from fully observable event rows."""

            rows = [
                dict(row)
                for row in rows
                if by_index.get(
                    int(getattr(row.get("option"), "choice_index", -1))
                ) is not None
            ]
            if not rows:
                return None
            eligible_rows = [
                row for row in rows
                if row.get("selection_eligible") is not False
            ]
            chosen_row = (
                max(
                    eligible_rows,
                    key=lambda row: (
                        float(row["score"]),
                        float(row.get("tie_priority", 0.0)),
                        -int(row["option"].choice_index),
                    ),
                )
                if eligible_rows else None
            )
            candidates = []
            for row in rows:
                option = row["option"]
                score_contract = self._linear_score_contract(
                    (
                        f"event_{event_id}_{reason}_candidate_utility_v1"
                    ),
                    {"candidate_utility": float(row["score"])},
                    ((
                        "candidate_utility", "candidate_utility", 1.0,
                    ),),
                )
                score_contract.update({
                    field: row[field]
                    for field in (
                        "score_rule_id", "score_formula", "score_inputs",
                        "score_components",
                    )
                    if field in row
                })
                candidate = {
                    "id": option.choice_index,
                    "score": float(row["score"]),
                    "label": getattr(option, "label", None),
                    "text": self._macro_description(
                        getattr(option, "text", "")
                    ),
                    "consequences": dict(
                        row.get("consequences") or {}
                    ),
                    "semantic_kind": row.get("kind"),
                    "selection_eligible": (
                        row.get("selection_eligible") is not False
                    ),
                    "veto_reason": row.get("veto_reason"),
                    "reason_codes": list(row.get("reason_codes") or [
                        reason,
                        str(row.get("kind") or "visible_event_candidate"),
                    ]),
                    "reason": (
                        row.get("reason")
                        or f"{reason}:{row.get('kind') or option.choice_index}"
                    ),
                    **score_contract,
                }
                candidates.append(candidate)
            if chosen_row is None:
                self._record_noncombat_decision(
                    reason,
                    candidates,
                    candidate_contract={
                        "score_source": "explicit_local_utility",
                        "strategy_quality_auditable": True,
                        "all_visible_options_scored": True,
                    },
                    chosen_index=None,
                    chosen_kind=None,
                    fail_closed=True,
                    **details,
                )
                return None
            return choose_index(
                chosen_row["option"].choice_index,
                reason,
                candidates,
                chosen_score=round(float(chosen_row["score"]), 3),
                candidate_argmax_id=str(
                    chosen_row["option"].choice_index
                ),
                chosen_kind=chosen_row.get("kind"),
                **details,
            )

        def choose_signed_irreversible(rows, reason, **state_details):
            """Rank exact post-choice states locally and with one contract.

            Irreversible events used to bypass the adviser through unrelated
            fixed thresholds (Max HP for Apparitions, Strike count for Bites,
            current HP for Mind Bloom).  Keep the deterministic score as the
            safety baseline, but expose the same signed post-state to the
            adviser in the volatile request tail.  This avoids both hidden
            local facts and event-specific prompt prose, while leaving the
            stable cache prefix untouched.
            """

            if not rows:
                return None
            rule = max(
                rows,
                key=lambda row: (
                    float(row["local_score"]),
                    -int(row["option"].choice_index),
                ),
            )
            row_by_id = {
                f"event:{row['option'].choice_index}": row for row in rows
            }
            selected_id = self._macro_rank(
                "EVENT",
                [
                    {
                        "candidate_id": candidate_id,
                        "kind": "irreversible_event_option",
                        "label": getattr(row["option"], "label", None),
                        "local_score": float(row["local_score"]),
                        "facts": {
                            "outcome_id": row["outcome_id"],
                            "visible_index": int(
                                row["option"].choice_index
                            ),
                            "text": self._macro_description(
                                getattr(row["option"], "text", "")
                            ),
                            "semantic_signals": list(
                                row.get("signals") or []
                            ),
                            "consequences": dict(
                                row.get("consequences") or {}
                            ),
                            "post_state": dict(row.get("post_state") or {}),
                        },
                    }
                    for candidate_id, row in row_by_id.items()
                ],
                f"event:{rule['option'].choice_index}",
                hard_constraints=[
                    "ONLY_LISTED_VISIBLE_OPTIONS",
                    "STRUCTURED_POST_STATE_OVERRIDES_MODEL_MEMORY",
                    "EVALUATE_EVERY_SIGNED_GAIN_AND_IRREVERSIBLE_COST",
                    "LOCAL_LETHAL_AND_ILLEGAL_VETOES_REMAIN_AUTHORITATIVE",
                ],
                state_details={
                    "event_id": getattr(
                        self.game.screen, "event_id", None
                    ),
                    "event_name": getattr(
                        self.game.screen, "event_name", None
                    ),
                    "irreversible": True,
                    **state_details,
                },
            )[0]
            chosen = row_by_id[selected_id]
            def signed_candidate(row):
                score = float(row["local_score"])
                # Event producers that have a decomposed score must retain it
                # all the way into the DecisionCase candidate.  Collapsing the
                # result back into one ``signed_post_state_utility`` input made
                # the arithmetic replayable but hid which reward or cost drove
                # the choice, so the strategy auditor could not diagnose a
                # missing relic reward or a duplicated survival penalty.
                score_evidence = row.get("score_evidence")
                if isinstance(score_evidence, dict) and all(
                    key in score_evidence
                    for key in {
                        "score_rule_id", "score_formula", "score_inputs",
                        "score_components",
                    }
                ):
                    contract = copy.deepcopy(score_evidence)
                else:
                    contract = self._linear_score_contract(
                        f"event_{reason}_signed_post_state_utility_v1",
                        {"signed_post_state_utility": score},
                        ((
                            "signed_post_state_utility",
                            "signed_post_state_utility",
                            1.0,
                        ),),
                    )
                return {
                    "id": row["option"].choice_index,
                    "score": score,
                    "label": getattr(row["option"], "label", None),
                    "text": self._macro_description(
                        getattr(row["option"], "text", "")
                    ),
                    "consequences": dict(row.get("consequences") or {}),
                    **contract,
                }
            return choose_index(
                chosen["option"].choice_index,
                reason,
                [signed_candidate(row) for row in rows],
                chosen_outcome=chosen["outcome_id"],
                chosen_score=float(chosen["local_score"]),
                outcome_facts={
                    str(row["option"].choice_index): {
                        "outcome_id": row["outcome_id"],
                        "consequences": row.get("consequences") or {},
                        "post_state": row.get("post_state") or {},
                    }
                    for row in rows
                },
                **state_details,
            )

        def typed_event_row(
            option, kind, score, consequences, inputs, terms, *,
            selection_eligible=True, veto_reason=None, tie_priority=0.0,
            reason_codes=None,
        ):
            row = {
                "kind": kind,
                "option": option,
                "score": float(score),
                "consequences": dict(consequences or {}),
                "selection_eligible": bool(selection_eligible),
                "veto_reason": veto_reason,
                "tie_priority": float(tie_priority),
                "reason_codes": list(reason_codes or []),
            }
            row.update(self._linear_score_contract(
                f"base_game_{event_id}_{kind}_a0_v1",
                inputs,
                terms,
            ))
            return row

        # The Joust's two opening bets are fixed base-game mechanics at A0:
        # pay 50 Gold for a 70%/100 Gold or 30%/250 Gold return.  The prior
        # generic text path gave both branches the same ``unknown`` score and
        # silently chose index zero.  Bind only the authoritative event id
        # and complete original/command index surface here; labels and text
        # remain display-only and an altered/partial surface falls back to
        # the conservative generic handler below.
        if event_id == "thejoust":
            raw_options = list(
                getattr(getattr(self.game, "screen", None), "options", [])
                or []
            )
            current_gold = getattr(self.game, "gold", None)
            by_original = {}
            exact_surface = (
                getattr(self.game, "ascension_level", None) == 0
                and type(current_gold) is int
                and current_gold >= 50
                and len(raw_options) == 2
                and len(valid_options) == 2
            )
            if exact_surface:
                for item in raw_options:
                    original = getattr(item, "original_button_index", None)
                    choice_index = getattr(item, "choice_index", None)
                    if (
                        getattr(item, "disabled", None) is not False
                        or type(original) is not int
                        or type(choice_index) is not int
                        or original != choice_index
                        or original in by_original
                    ):
                        exact_surface = False
                        break
                    by_original[original] = item
                exact_surface = (
                    exact_surface
                    and set(by_original) == {0, 1}
                    and all(item in valid_options for item in by_original.values())
                )
            if exact_surface:
                rows = []
                # The expected deltas include the fixed 50 Gold stake.
                # Pre-computing them keeps the score a replayable linear
                # component rather than hiding a multiplication in a label.
                for original, probability, win_gold in (
                    (0, 0.70, 100.0), (1, 0.30, 250.0),
                ):
                    expected_gold_delta = probability * win_gold - 50.0
                    rows.append(typed_event_row(
                        by_original[original],
                        (
                            "joust_bet_against"
                            if original == 0 else "joust_bet_for"
                        ),
                        expected_gold_delta,
                        {},
                        {
                            "expected_gold_delta": expected_gold_delta,
                        },
                        ((
                            "expected_gold_value",
                            "expected_gold_delta", 1.0,
                        ),),
                        reason_codes=[
                            "exact_base_game_the_joust_a0_expected_gold",
                        ],
                    ))
                return choose_scored_event(
                    rows,
                    "the_joust_a0_expected_gold",
                    protocol_identity=(
                        "exact_event_id_original_button_index_a0"
                    ),
                )

        if event_id in {
            "thecleric", "designer", "worldofgoop", "cursedtome",
            "knowingskull",
        }:
            consequences_by_option = {
                option: self._typed_a0_event_option_consequences(option)
                for option in valid_options
            }
            rows = []
            if event_id == "thecleric":
                removable = list(getattr(self.game, "deck", []) or [])
                best_removal = max(
                    (
                        float(self._removal_score(card))
                        for card in removable
                    ),
                    default=0.0,
                )
                for option in valid_options:
                    consequence = consequences_by_option[option]
                    index = consequence.get("original_button_index")
                    operation = str(consequence.get("operation") or "")
                    classified = not operation.startswith("unclassified_")
                    if index == 0 and operation == "cleric_heal":
                        actual_heal = float(
                            consequence.get("hp_delta", 0) or 0
                        )
                        healing_weight = 0.70 + max(
                            0.0, 0.70 - hp_ratio
                        )
                        inputs = {
                            "actual_heal": actual_heal,
                            "healing_weight": healing_weight,
                            "gold_cost": 35.0,
                        }
                        # Multiplication is reduced to one independently
                        # replayable input before the linear sum envelope.
                        inputs["weighted_heal"] = (
                            actual_heal * healing_weight
                        )
                        score = inputs["weighted_heal"] - 35.0 * 0.13
                        rows.append(typed_event_row(
                            option, "heal", score, consequence, inputs,
                            (
                                ("weighted_heal", "weighted_heal", 1.0),
                                ("gold_cost", "gold_cost", -0.13),
                            ),
                        ))
                    elif index == 1 and operation == "cleric_open_purge_grid":
                        inputs = {
                            "best_removal_value": best_removal,
                            "gold_cost": 50.0,
                        }
                        score = best_removal / 5.0 - 50.0 * 0.13
                        rows.append(typed_event_row(
                            option, "remove_card", score, consequence,
                            inputs,
                            (
                                (
                                    "removal_value",
                                    "best_removal_value", 0.2,
                                ),
                                ("gold_cost", "gold_cost", -0.13),
                            ),
                        ))
                    elif index == 2 and operation == "cleric_leave":
                        rows.append(typed_event_row(
                            option, "leave", 1.0, consequence,
                            {"leave_baseline": 1.0},
                            (("leave", "leave_baseline", 1.0),),
                            tie_priority=1.0,
                        ))
                    elif operation == "cleric_dialog_advance_noop":
                        rows.append(typed_event_row(
                            option, "dialog_advance_noop", 0.0,
                            consequence, {"noop": 0.0},
                            (("noop", "noop", 1.0),),
                        ))
                    else:
                        rows.append(typed_event_row(
                            option, "unclassified", -1000000.0,
                            consequence, {"fail_closed": -1000000.0},
                            (("fail_closed", "fail_closed", 1.0),),
                            selection_eligible=False,
                            veto_reason=(
                                "cleric_original_index_or_surface_unproven"
                            ),
                            reason_codes=list(
                                consequence.get("reason_codes") or []
                            ),
                        ))

            elif event_id == "designer":
                removable = list(getattr(self.game, "deck", []) or [])
                removal_values = sorted(
                    (
                        float(self._removal_score(card))
                        for card in removable
                    ), reverse=True,
                )
                best_removal = removal_values[0] if removal_values else 0.0
                upgrade_values = [
                    float(self._upgrade_score(card))
                    for card in removable
                    if float(self._upgrade_score(card)) > -900.0
                ]
                best_upgrade = max(upgrade_values, default=0.0)
                average_upgrade = (
                    sum(upgrade_values) / len(upgrade_values)
                    if upgrade_values else 0.0
                )
                for option in valid_options:
                    consequence = consequences_by_option[option]
                    operation = str(consequence.get("operation") or "")
                    if operation == "designer_dialog_advance_noop":
                        rows.append(typed_event_row(
                            option, "dialog_advance_noop", 0.0,
                            consequence, {"noop": 0.0},
                            (("noop", "noop", 1.0),),
                        ))
                    elif operation == "designer_adjustment_grid_upgrade":
                        gold_cost = float(
                            -(consequence.get("gold_delta", 0) or 0)
                        )
                        inputs = {
                            "best_upgrade_value": best_upgrade,
                            "gold_cost": gold_cost,
                        }
                        rows.append(typed_event_row(
                            option, "adjustment_grid_upgrade",
                            best_upgrade - gold_cost * 0.13,
                            consequence, inputs,
                            (
                                (
                                    "upgrade_value",
                                    "best_upgrade_value", 1.0,
                                ),
                                ("gold_cost", "gold_cost", -0.13),
                            ),
                        ))
                    elif operation == "designer_adjustment_random_upgrade":
                        gold_cost = float(
                            -(consequence.get("gold_delta", 0) or 0)
                        )
                        max_count = int(
                            (consequence.get("future_costs") or [{}])[0].get(
                                "max_count", 0
                            ) or 0
                        )
                        expected_count = min(max_count, len(upgrade_values))
                        expected_value = average_upgrade * expected_count
                        inputs = {
                            "expected_random_upgrade_value": expected_value,
                            "gold_cost": gold_cost,
                        }
                        rows.append(typed_event_row(
                            option, "adjustment_random_upgrade",
                            expected_value - gold_cost * 0.13,
                            consequence, inputs,
                            (
                                (
                                    "upgrade_value",
                                    "expected_random_upgrade_value", 1.0,
                                ),
                                ("gold_cost", "gold_cost", -0.13),
                            ),
                        ))
                    elif operation == "designer_clean_up_grid_purge":
                        gold_cost = float(
                            -(consequence.get("gold_delta", 0) or 0)
                        )
                        inputs = {
                            "best_removal_value": best_removal,
                            "gold_cost": gold_cost,
                        }
                        rows.append(typed_event_row(
                            option, "clean_up_grid_purge",
                            best_removal * 0.2 - gold_cost * 0.13,
                            consequence, inputs,
                            (
                                (
                                    "removal_value",
                                    "best_removal_value", 0.2,
                                ),
                                ("gold_cost", "gold_cost", -0.13),
                            ),
                        ))
                    elif operation == "designer_clean_up_grid_transform":
                        gold_cost = float(
                            -(consequence.get("gold_delta", 0) or 0)
                        )
                        selected_relief = sum(removal_values[:2]) * 0.1
                        inputs = {
                            "transform_relief_value": selected_relief,
                            "gold_cost": gold_cost,
                        }
                        rows.append(typed_event_row(
                            option, "clean_up_grid_transform",
                            selected_relief - gold_cost * 0.13,
                            consequence, inputs,
                            (
                                (
                                    "transform_relief",
                                    "transform_relief_value", 1.0,
                                ),
                                ("gold_cost", "gold_cost", -0.13),
                            ),
                        ))
                    elif operation == "designer_full_service":
                        gold_cost = float(
                            -(consequence.get("gold_delta", 0) or 0)
                        )
                        random_upgrade_value = average_upgrade * min(
                            1, len(upgrade_values)
                        )
                        inputs = {
                            "best_removal_value": best_removal,
                            "random_upgrade_value": random_upgrade_value,
                            "gold_cost": gold_cost,
                        }
                        score = (
                            best_removal * 0.2 + random_upgrade_value
                            - gold_cost * 0.13
                        )
                        rows.append(typed_event_row(
                            option, "full_service", score, consequence,
                            inputs,
                            (
                                (
                                    "removal_value",
                                    "best_removal_value", 0.2,
                                ),
                                (
                                    "random_upgrade_value",
                                    "random_upgrade_value", 1.0,
                                ),
                                ("gold_cost", "gold_cost", -0.13),
                            ),
                        ))
                    elif operation == "designer_punch_and_leave":
                        hp_cost = 3.0
                        risk_multiplier = 1.0 + max(
                            0.0, 0.7 - hp_ratio
                        ) * 2.4
                        hp_penalty = max(3.0, hp_cost * 0.8) * risk_multiplier
                        survivable = int(self.game.current_hp) > int(hp_cost)
                        inputs = {
                            "leave_baseline": 1.0,
                            "hp_penalty": hp_penalty,
                        }
                        rows.append(typed_event_row(
                            option, "punch_and_leave",
                            1.0 - hp_penalty, consequence, inputs,
                            (
                                ("leave", "leave_baseline", 1.0),
                                ("hp_cost", "hp_penalty", -1.0),
                            ),
                            selection_eligible=survivable,
                            veto_reason=(
                                None if survivable else
                                "event_hp_cost_not_survivable"
                            ),
                        ))
                    else:
                        reason_codes = list(
                            consequence.get("reason_codes") or []
                        )
                        rows.append(typed_event_row(
                            option, "unclassified", -1000000.0,
                            consequence, {"fail_closed": -1000000.0},
                            (("fail_closed", "fail_closed", 1.0),),
                            selection_eligible=False,
                            veto_reason=(
                                reason_codes[0] if reason_codes else
                                "designer_typed_contract_unproven"
                            ),
                            reason_codes=reason_codes,
                        ))

            elif event_id == "worldofgoop":
                for option in valid_options:
                    consequence = consequences_by_option[option]
                    operation = str(consequence.get("operation") or "")
                    if operation == "world_of_goop_dialog_advance_noop":
                        rows.append(typed_event_row(
                            option, "dialog_advance_noop", 0.0,
                            consequence, {"noop": 0.0},
                            (("noop", "noop", 1.0),),
                        ))
                    elif operation == "world_of_goop_gather_gold":
                        hp_cost = float(
                            -(consequence.get("hp_delta", 0) or 0)
                        )
                        gold_value = self._event_gold_gain_value(
                            int(consequence.get("gold_delta", 0) or 0)
                        )
                        risk_multiplier = 1.0 + max(
                            0.0, 0.7 - hp_ratio
                        ) * 2.4
                        hp_penalty = max(3.0, hp_cost * 0.8) * risk_multiplier
                        survivable = int(self.game.current_hp) > int(hp_cost)
                        inputs = {
                            "gold_value": gold_value,
                            "hp_penalty": hp_penalty,
                        }
                        rows.append(typed_event_row(
                            option, "gather_gold",
                            gold_value - hp_penalty, consequence, inputs,
                            (
                                ("gold_value", "gold_value", 1.0),
                                ("hp_cost", "hp_penalty", -1.0),
                            ),
                            selection_eligible=survivable,
                            veto_reason=(
                                None if survivable else
                                "event_hp_cost_not_survivable"
                            ),
                        ))
                    elif operation == "world_of_goop_leave":
                        gold_cost = float(
                            -(consequence.get("gold_delta", 0) or 0)
                        )
                        inputs = {
                            "leave_baseline": 1.0,
                            "gold_cost": gold_cost,
                        }
                        rows.append(typed_event_row(
                            option, "leave_gold", 1.0 - gold_cost / 6.0,
                            consequence, inputs,
                            (
                                ("leave", "leave_baseline", 1.0),
                                ("gold_cost", "gold_cost", -(1.0 / 6.0)),
                            ),
                        ))
                    else:
                        reason_codes = list(
                            consequence.get("reason_codes") or []
                        )
                        rows.append(typed_event_row(
                            option, "unclassified", -1000000.0,
                            consequence, {"fail_closed": -1000000.0},
                            (("fail_closed", "fail_closed", 1.0),),
                            selection_eligible=False,
                            veto_reason=(
                                reason_codes[0] if reason_codes else
                                "world_of_goop_event_contract_unproven"
                            ),
                            reason_codes=reason_codes,
                        ))

            elif event_id == "knowingskull":
                current_hp = max(
                    0, int(getattr(self.game, "current_hp", 0) or 0)
                )
                max_hp = max(
                    1, int(getattr(self.game, "max_hp", 0) or 0)
                )
                act = int(getattr(self.game, "act", 0) or 0)
                floor = max(0, int(getattr(self.game, "floor", 0) or 0))
                floor_in_act = floor % 17
                next_room_is_forced_campfire = bool(
                    act in {1, 2, 3} and floor_in_act == 14
                )
                healing_blocked = self._has_relic("Mark of the Bloom")
                guaranteed_eternal_feather_heal = 0
                guaranteed_pantograph_heal = 0
                if next_room_is_forced_campfire and not healing_blocked:
                    if self._has_relic("Eternal Feather"):
                        guaranteed_eternal_feather_heal = (
                            len(list(getattr(self.game, "deck", []) or []))
                            // 5
                        ) * 3
                    if self._has_relic("Pantograph"):
                        guaranteed_pantograph_heal = 25
                guaranteed_future_healing = (
                    guaranteed_eternal_feather_heal
                    + guaranteed_pantograph_heal
                )
                for option in valid_options:
                    consequence = consequences_by_option[option]
                    operation = str(consequence.get("operation") or "")
                    if operation == "knowing_skull_dialog_advance_noop":
                        rows.append(typed_event_row(
                            option, "dialog_advance_noop", 0.0,
                            consequence, {"noop": 0.0},
                            (("noop", "noop", 1.0),),
                        ))
                        continue
                    if operation == "knowing_skull_leave":
                        hp_cost = float(
                            -(consequence.get("hp_delta", 0) or 0)
                        )
                        risk_multiplier = 1.0 + max(
                            0.0, 0.7 - hp_ratio
                        ) * 2.4
                        hp_penalty = max(
                            3.0, hp_cost * 0.8
                        ) * risk_multiplier
                        survivable = current_hp > int(hp_cost)
                        inputs = {
                            "leave_baseline": 1.0,
                            "hp_penalty": hp_penalty,
                        }
                        rows.append(typed_event_row(
                            option, "leave", 1.0 - hp_penalty,
                            consequence, inputs,
                            (
                                ("leave", "leave_baseline", 1.0),
                                ("hp_cost", "hp_penalty", -1.0),
                            ),
                            # Once an earlier reward made every exit lethal,
                            # choose the typed leave branch as the unique
                            # least-escalating action instead of falling back
                            # to localized generic event text.
                            selection_eligible=True,
                            tie_priority=1.0,
                            reason_codes=(
                                ["knowing_skull_exact_typed_leave"]
                                if survivable else
                                ["knowing_skull_unavoidable_lethal_exit"]
                            ),
                        ))
                        continue

                    potion_gains = (
                        consequence.get("potion_changes") or {}
                    ).get("gain") or []
                    card_gains = (
                        consequence.get("card_changes") or {}
                    ).get("gain") or []
                    reward_values = {
                        "knowing_skull_take_potion": (
                            "take_potion",
                            6.5 if potion_gains else 0.0,
                        ),
                        "knowing_skull_take_gold": (
                            "take_gold",
                            self._event_gold_gain_value(
                                int(consequence.get("gold_delta", 0) or 0)
                            ),
                        ),
                        "knowing_skull_take_card": (
                            "take_card", 8.0 if card_gains else 0.0,
                        ),
                    }
                    reward = reward_values.get(operation)
                    if reward is not None:
                        kind, reward_value = reward
                        hp_cost = float(
                            -(consequence.get("hp_delta", 0) or 0)
                        )
                        future_costs = consequence.get("future_costs") or []
                        reserve = (
                            future_costs[0]
                            if len(future_costs) == 1
                            and isinstance(future_costs[0], dict)
                            else {}
                        )
                        exit_hp_cost = reserve.get("reserved_hp_loss")
                        reserve_proven = (
                            reserve.get("kind")
                            == "knowing_skull_exit_reserve"
                            and type(exit_hp_cost) is int
                            and exit_hp_cost >= 0
                        )
                        can_pay_reward_and_exit = bool(
                            reserve_proven
                            and current_hp
                            > int(hp_cost) + int(exit_hp_cost)
                        )
                        post_exit_hp = (
                            current_hp - int(hp_cost) - int(exit_hp_cost)
                            if reserve_proven else -1
                        )
                        post_exit_survival_floor = max(
                            18,
                            int(math.ceil(
                                max_hp * 0.60
                            )),
                        )
                        post_guaranteed_heal_hp = (
                            min(
                                max_hp,
                                post_exit_hp + guaranteed_future_healing,
                            )
                            if reserve_proven else -1
                        )
                        preserves_survival_floor = bool(
                            can_pay_reward_and_exit
                            and post_guaranteed_heal_hp
                            >= post_exit_survival_floor
                        )
                        risk_multiplier = 1.0 + max(
                            0.0, 0.7 - hp_ratio
                        ) * 2.4
                        action_hp_penalty = max(
                            3.0, hp_cost * 0.8
                        ) * risk_multiplier
                        reserve_hp_penalty = (
                            max(3.0, float(exit_hp_cost) * 0.8)
                            * risk_multiplier
                            if reserve_proven else 1000000.0
                        )
                        survival_veto_adjustment = (
                            0.0 if preserves_survival_floor else -1000000.0
                        )
                        inputs = {
                            "reward_value": float(reward_value),
                            "action_hp_penalty": action_hp_penalty,
                            "reserved_exit_hp_penalty": reserve_hp_penalty,
                            "current_hp": float(current_hp),
                            "action_hp_cost": hp_cost,
                            "reserved_exit_hp_cost": (
                                float(exit_hp_cost)
                                if reserve_proven else -1.0
                            ),
                            "post_exit_hp": float(post_exit_hp),
                            "post_exit_survival_floor": float(
                                post_exit_survival_floor
                            ),
                            "next_room_is_forced_campfire": float(
                                next_room_is_forced_campfire
                            ),
                            "guaranteed_eternal_feather_heal": float(
                                guaranteed_eternal_feather_heal
                            ),
                            "guaranteed_pantograph_heal": float(
                                guaranteed_pantograph_heal
                            ),
                            "guaranteed_future_healing": float(
                                guaranteed_future_healing
                            ),
                            "post_guaranteed_heal_hp": float(
                                post_guaranteed_heal_hp
                            ),
                            "survival_veto_adjustment": (
                                survival_veto_adjustment
                            ),
                        }
                        rows.append(typed_event_row(
                            option, kind,
                            reward_value
                            - action_hp_penalty - reserve_hp_penalty
                            + survival_veto_adjustment,
                            consequence, inputs,
                            (
                                ("reward", "reward_value", 1.0),
                                (
                                    "action_hp_cost",
                                    "action_hp_penalty", -1.0,
                                ),
                                (
                                    "reserved_exit_hp_cost",
                                    "reserved_exit_hp_penalty", -1.0,
                                ),
                                (
                                    "survival_veto",
                                    "survival_veto_adjustment", 1.0,
                                ),
                            ),
                            selection_eligible=preserves_survival_floor,
                            veto_reason=(
                                None
                                if preserves_survival_floor else
                                "knowing_skull_exit_reserve_insufficient"
                                if not can_pay_reward_and_exit else
                                "knowing_skull_post_exit_survival_floor"
                            ),
                            reason_codes=[
                                (
                                    "knowing_skull_reward_preserves_survival_floor"
                                    if preserves_survival_floor else
                                    "knowing_skull_exit_reserve_insufficient"
                                    if not can_pay_reward_and_exit else
                                    "knowing_skull_post_exit_survival_floor"
                                )
                            ],
                        ))
                        continue

                    reason_codes = list(
                        consequence.get("reason_codes") or []
                    )
                    rows.append(typed_event_row(
                        option, "unclassified", -1000000.0,
                        consequence, {"fail_closed": -1000000.0},
                        (("fail_closed", "fail_closed", 1.0),),
                        selection_eligible=False,
                        veto_reason=(
                            reason_codes[0] if reason_codes else
                            "knowing_skull_typed_contract_unproven"
                        ),
                        reason_codes=reason_codes,
                    ))

            else:  # Cursed Tome
                for option in valid_options:
                    consequence = consequences_by_option[option]
                    operation = str(consequence.get("operation") or "")
                    if operation in {
                        "cursed_tome_leave",
                        "cursed_tome_dialog_advance_noop",
                    }:
                        rows.append(typed_event_row(
                            option,
                            "leave" if consequence.get("leave") else
                            "dialog_advance_noop",
                            1.0 if consequence.get("leave") else 0.0,
                            consequence,
                            {
                                "leave_baseline" if consequence.get("leave")
                                else "noop": (
                                    1.0 if consequence.get("leave") else 0.0
                                ),
                            },
                            ((
                                "leave" if consequence.get("leave")
                                else "noop",
                                "leave_baseline" if consequence.get("leave")
                                else "noop",
                                1.0,
                            ),),
                            tie_priority=(
                                1.0 if consequence.get("leave") else 0.0
                            ),
                        ))
                    elif operation in {
                        "cursed_tome_enter_random_book_chain",
                        "cursed_tome_complete_random_book",
                    }:
                        rows.append(typed_event_row(
                            option, "book_chain", -1000000.0,
                            consequence, {"fail_closed": -1000000.0},
                            (("fail_closed", "fail_closed", 1.0),),
                            selection_eligible=False,
                            veto_reason=(
                                "unsupported_necronomicon_activation_state"
                            ),
                            reason_codes=[
                                "unsupported_necronomicon_activation_state"
                            ],
                        ))
                    elif operation.startswith("cursed_tome_read_page_") or (
                        operation == "cursed_tome_stop"
                    ):
                        hp_cost = float(
                            -(consequence.get("hp_delta", 0) or 0)
                        )
                        risk_multiplier = 1.0 + max(
                            0.0, 0.7 - hp_ratio
                        ) * 2.4
                        hp_penalty = max(
                            3.0, hp_cost * 0.8
                        ) * risk_multiplier
                        survivable = int(self.game.current_hp) > int(hp_cost)
                        leave_value = 1.0 if consequence.get("leave") else 0.0
                        inputs = {
                            "leave_baseline": leave_value,
                            "hp_penalty": hp_penalty,
                        }
                        rows.append(typed_event_row(
                            option,
                            "stop" if consequence.get("leave") else
                            "forced_read_page",
                            leave_value - hp_penalty,
                            consequence, inputs,
                            (
                                ("leave", "leave_baseline", 1.0),
                                ("hp_cost", "hp_penalty", -1.0),
                            ),
                            selection_eligible=survivable,
                            veto_reason=(
                                None if survivable else
                                "event_hp_cost_not_survivable"
                            ),
                            tie_priority=(
                                1.0 if consequence.get("leave") else 0.0
                            ),
                        ))
                    else:
                        reason_codes = list(
                            consequence.get("reason_codes") or []
                        )
                        rows.append(typed_event_row(
                            option, "unclassified", -1000000.0,
                            consequence, {"fail_closed": -1000000.0},
                            (("fail_closed", "fail_closed", 1.0),),
                            selection_eligible=False,
                            veto_reason=(
                                reason_codes[0] if reason_codes else
                                "cursed_tome_typed_contract_unproven"
                            ),
                            reason_codes=reason_codes,
                        ))

            return choose_scored_event(
                rows,
                f"{event_id}_typed_a0_resource_trade",
                protocol_identity=(
                    "exact_event_id_original_button_index_a0"
                ),
            )

        if event_id == "themausoleum":
            rows = []
            for option in valid_options:
                consequence = self._typed_mausoleum_option_consequences(
                    option
                )
                operation = str(consequence.get("operation") or "")
                if operation == "mausoleum_open_coffin":
                    strategic = consequence.get("strategic_value") or {}
                    relic_value = float(
                        strategic.get("random_relic_value", 0.0) or 0.0
                    )
                    curse_cost = float(
                        strategic.get(
                            "expected_curse_opportunity_cost", 0.0
                        ) or 0.0
                    )
                    rows.append(typed_event_row(
                        option, "open_coffin", relic_value - curse_cost,
                        consequence,
                        {
                            "random_relic_value": relic_value,
                            "expected_curse_cost": curse_cost,
                        },
                        (
                            (
                                "random_relic_value",
                                "random_relic_value", 1.0,
                            ),
                            (
                                "expected_curse_cost",
                                "expected_curse_cost", -1.0,
                            ),
                        ),
                    ))
                elif operation == "mausoleum_leave":
                    rows.append(typed_event_row(
                        option, "leave", 1.0, consequence,
                        {"leave_baseline": 1.0},
                        (("leave", "leave_baseline", 1.0),),
                        tie_priority=1.0,
                    ))
                elif operation == "mausoleum_dialog_advance_noop":
                    rows.append(typed_event_row(
                        option, "dialog_advance_noop", 0.0, consequence,
                        {"noop": 0.0}, (("noop", "noop", 1.0),),
                    ))
                else:
                    rows.append(typed_event_row(
                        option, "unclassified", -1000000.0, consequence,
                        {"fail_closed": -1000000.0},
                        (("fail_closed", "fail_closed", 1.0),),
                        selection_eligible=False,
                        veto_reason="mausoleum_typed_surface_unproven",
                        reason_codes=list(
                            consequence.get("reason_codes") or []
                        ),
                    ))
            return choose_scored_event(
                rows,
                "mausoleum_typed_resource_trade",
                protocol_identity="exact_event_id_choice_index_a0_or_a15",
            )

        if event_id in {"neow", "neowevent"}:
            # Choice identity is derived from the protocol index, never from
            # container position.  This also makes a reordered option list
            # produce the same semantic decision and prevents the local
            # evidence and model replay from inventing parallel identities
            # (``0`` versus ``neow:0``) for the same button.
            neow_options = sorted(
                valid_options,
                key=lambda candidate: int(candidate.choice_index),
            )
            scored = []
            for item in neow_options:
                contract, score_parts = self._neow_option_score_parts(item)
                item_score = (
                    sum(score_parts.values())
                    if score_parts is not None else 0.0
                )
                scored.append((item_score, item, contract, score_parts))
            eligible_scored = [
                row for row in scored
                if row[2] is not None and row[3] is not None
            ]
            score, option, _contract, _parts = max(
                eligible_scored,
                key=lambda item: (item[0], -item[1].choice_index),
            ) if eligible_scored else (None, None, None, None)
            option_by_id = {
                f"neow:{item.choice_index}": item
                for _, item, _contract, _parts in scored
            }
            typed_complete = all(
                contract is not None and parts is not None
                for _score, _item, contract, parts in scored
            )
            selected_id = (
                f"neow:{option.choice_index}" if option is not None else None
            )
            if typed_complete:
                selected_id = self._macro_rank(
                    "NEOW",
                    [
                        {
                            "candidate_id": f"neow:{item.choice_index}",
                            "kind": "neow_option",
                            "label": getattr(item, "label", None),
                            "local_score": item_score,
                            "facts": {
                                "visible_index": int(item.choice_index),
                                "mechanism_id": self._neow_mechanism_id(
                                    contract
                                ),
                                "neow_contract": contract,
                                "consequences": (
                                    self._neow_typed_consequences(contract)
                                ),
                            },
                        }
                        for item_score, item, contract, _parts in scored
                    ],
                    selected_id,
                    hard_constraints=[
                        "ONLY_LISTED_VISIBLE_OPTIONS",
                        "ONLY_TYPED_NEOW_CONTRACT_IS_AUTHORITATIVE",
                        "EVALUATE_REWARD_AND_DRAWBACK_TOGETHER",
                    ],
                    state_details={
                        "hp_ratio": round(hp_ratio, 3),
                        "stage": "run_start",
                    },
                )[0]
            if selected_id is not None:
                option = option_by_id[selected_id]
                score, _item, _contract, _parts = next(
                    row for row in scored if row[1] is option
                )
            neow_candidates = [
                {
                    "id": f"neow:{item.choice_index}",
                    "choice_id": f"neow:{item.choice_index}",
                    "choice_index": int(item.choice_index),
                    "semantic_id": f"neow:{item.choice_index}",
                    "score": float(item_score),
                    "label": getattr(item, "label", None),
                    "text": self._macro_description(
                        getattr(item, "text", "")
                    ),
                    "reason": "net_visible_reward_and_drawback",
                    "consequences": self._event_option_consequences(item),
                    "uncertainty": (
                        "visible Neow text may describe a random reward"
                        if any(
                            marker in self._token(
                                f"{getattr(item, 'label', '')} "
                                f"{getattr(item, 'text', '')}"
                            )
                            for marker in ("random", "闅忔満")
                        ) else None
                    ),
                }
                for item_score, item, contract, score_parts in scored
            ]
            for row, (item_score, _item, contract, score_parts) in zip(
                neow_candidates, scored
            ):
                row.update({
                    "score": float(item_score),
                    "reason": (
                        "typed_neow_reward_and_drawback"
                        if contract is not None
                        else "typed_neow_contract_missing"
                    ),
                    "selection_eligible": contract is not None,
                    "veto_reason": (
                        None if contract is not None
                        else "typed_neow_contract_missing"
                    ),
                    "consequences": self._neow_typed_consequences(contract),
                    "uncertainty": (
                        "typed Neow contract missing or malformed"
                        if contract is None else None
                    ),
                })
                if score_parts is not None:
                    row.update(self._linear_score_contract(
                        "neow_typed_reward_drawback_v1",
                        score_parts,
                        tuple(
                            (name, name, 1.0) for name in score_parts
                        ),
                    ))
            if option is None:
                # A malformed or missing typed surface must never win merely
                # because its placeholder score is zero.  Record the complete
                # visible surface, then wait fail-closed instead of issuing an
                # irreversible run-start choice without authoritative facts.
                self._record_noncombat_decision(
                    "neow_option_context_score",
                    neow_candidates,
                    candidate_contract={
                        "score_source": (
                            "typed_neow_reward_drawback_contract"
                        ),
                        "strategy_quality_auditable": False,
                        "all_visible_options_scored": False,
                        "visible_option_count": len(neow_candidates),
                        "identity_source": "protocol_choice_index",
                        "mechanism_source": "typed_neow_contract_v1",
                        "typed_contract_complete": False,
                    },
                    event_id=event_id,
                    chosen_index=None,
                    hp_ratio=round(hp_ratio, 3),
                    chosen_id=None,
                    typed_contract_complete=False,
                    fail_closed=True,
                    candidate_consequences={
                        row["id"]: row["consequences"]
                        for row in neow_candidates
                    },
                )
                return None
            action = choose_index(
                option.choice_index,
                "neow_option_context_score",
                neow_candidates,
                candidate_contract_override={
                    "score_source": "typed_neow_reward_drawback_contract",
                    "strategy_quality_auditable": typed_complete,
                    "all_visible_options_scored": typed_complete,
                    "visible_option_count": len(neow_candidates),
                    "identity_source": "protocol_choice_index",
                    "mechanism_source": "typed_neow_contract_v1",
                    "typed_contract_complete": typed_complete,
                },
                chosen_id=f"neow:{option.choice_index}",
                chosen_score=float(score),
                typed_contract_complete=typed_complete,
                candidate_consequences={
                    row["id"]: row["consequences"]
                    for row in neow_candidates
                },
            )
            if action is not None:
                return action

        if event_id == "mindbloom" and len(valid_options) >= 2:
            # Base-game binding is War / Awake / Rich-or-Healthy.  The old
            # policy mislabeled index 1 as Healthy and hard-rejected it below
            # full HP, even though index 1 is always Awake (upgrade every
            # eligible card plus permanent Mark of the Bloom).  Build each
            # actual post-state explicitly so local and model reasoning share
            # one authoritative fact set.
            current_hp = int(getattr(self.game, "current_hp", 0) or 0)
            max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
            floor = int(getattr(self.game, "floor", 0) or 0)
            ascension = int(
                getattr(self.game, "ascension_level", 0) or 0
            )
            deck = list(getattr(self.game, "deck", []) or [])
            fight_readiness = self._optional_event_fight_profile()
            deck_readiness = self._deck_readiness()
            sustain_ids = [
                relic_id
                for relic_id in {
                    "Burning Blood", "Black Blood", "Blood Vial",
                    "Bloody Idol", "Eternal Feather", "Meal Ticket",
                    "Meat on the Bone", "Pantograph", "Toy Ornithopter",
                    "Bird-Faced Urn", "Lizard Tail", "Regal Pillow",
                }
                if self._has_relic(relic_id)
                and (
                    relic_id != "Lizard Tail"
                    or self._has_active_lizard_tail()
                )
            ]
            healing_card_ids = {
                "bandageup", "bite", "feed", "reaper", "selfrepair"
            }
            healing_cards = [
                getattr(card, "card_id", None)
                for card in deck
                if self._token(getattr(card, "card_id", ""))
                in healing_card_ids
            ]
            healing_potion_ids = {
                "bloodpotion", "fairypotion", "fruitjuice", "regenpotion"
            }
            healing_potions = [
                getattr(potion, "potion_id", None)
                for potion in list(self.game.get_real_potions())
                if self._token(getattr(potion, "potion_id", ""))
                in healing_potion_ids
            ]
            upgrade_rows = sorted(
                (
                    (float(self._upgrade_score(card)), card)
                    for card in deck
                    if int(getattr(card, "upgrades", 0) or 0) == 0
                    and getattr(card, "type", None) not in {
                        spirecomm.spire.card.CardType.CURSE,
                        spirecomm.spire.card.CardType.STATUS,
                    }
                ),
                key=lambda item: item[0],
                reverse=True,
            )
            total_upgrade_value = sum(
                max(0.0, value) for value, _ in upgrade_rows
            )
            remaining_floors = max(0, 55 - floor)
            missing_hp = max(0, max_hp - current_hp)
            upgrade_value_groups = {
                "basic": {"count": 0, "priority_signal": 0.0},
                "non_basic": {"count": 0, "priority_signal": 0.0},
            }
            for value, card in upgrade_rows:
                group = (
                    "basic"
                    if getattr(card, "rarity", None)
                    == spirecomm.spire.card.CardRarity.BASIC
                    else "non_basic"
                )
                upgrade_value_groups[group]["count"] += 1
                upgrade_value_groups[group]["priority_signal"] += max(
                    0.0, value
                )

            # Mark of the Bloom removes a stream of future recovery, not one
            # flat bonus per source.  Estimate the remaining trigger surface
            # from the route horizon and value only a conservative fraction
            # of each source's nominal healing so Awake can still win for a
            # sufficiently strong upgrade package.  The full breakdown is
            # persisted in the decision receipt for audit/replay.
            remaining_combats = max(
                1, min(10, int(round(remaining_floors * 0.42)))
            ) if remaining_floors else 0
            remaining_rests = max(
                0, min(3, int(round(remaining_floors / 7.0)))
            )
            remaining_shops = max(
                0, min(3, int(round(remaining_floors / 9.0)))
            )
            remaining_boss_entries = 1 if remaining_floors >= 6 else 0
            future_potion_uses = max(
                1, min(3, int(round(remaining_floors / 8.0)))
            ) if remaining_floors else 0
            sustain_tokens = {self._token(item) for item in sustain_ids}
            expected_disabled_healing = {}

            # A Heart route normally converts the damage taken against the
            # Act 3 boss back into HP before Act 4.  At full HP the previous
            # Mind Bloom score priced that future transition heal at zero,
            # so eleven upgrades narrowly beat War and the run entered
            # Spear/Shield at 24/85 with Mark making the campfire useless.
            # Price only a conservative 35% of max HP here; the shared 0.70
            # realization factor below discounts it again.  Non-Heart runs
            # end after Act 3 and therefore receive no such opportunity cost.
            if self.goal_mode == "HEART" and remaining_boss_entries:
                expected_disabled_healing["act3_to_act4_transition"] = (
                    max_hp * 0.35
                )

            per_combat_relic_heal = {
                "burningblood": 6.0,
                "blackblood": 12.0,
                "bloodvial": 2.0,
            }
            for relic_token, amount in per_combat_relic_heal.items():
                if relic_token in sustain_tokens:
                    expected_disabled_healing[relic_token] = (
                        amount * remaining_combats * 0.38
                    )
            if "bloodyidol" in sustain_tokens:
                expected_disabled_healing["bloodyidol"] = (
                    min(6, remaining_combats + remaining_shops)
                    * 5.0 * 0.32
                )
            if "eternalfeather" in sustain_tokens:
                feather_heal = 3 * (len(deck) // 5)
                expected_disabled_healing["eternalfeather"] = (
                    feather_heal * remaining_rests * 0.55
                )
            if "mealticket" in sustain_tokens:
                expected_disabled_healing["mealticket"] = (
                    15.0 * remaining_shops * 0.55
                )
            if "meatonthebone" in sustain_tokens:
                expected_disabled_healing["meatonthebone"] = (
                    12.0 * remaining_combats * 0.24
                )
            if "pantograph" in sustain_tokens:
                expected_disabled_healing["pantograph"] = (
                    25.0 * remaining_boss_entries * 0.75
                )
            if "toyornithopter" in sustain_tokens:
                expected_disabled_healing["toyornithopter"] = (
                    5.0 * future_potion_uses * 0.65
                )
            if "birdfacedurn" in sustain_tokens:
                power_count = sum(
                    getattr(card, "type", None)
                    == spirecomm.spire.card.CardType.POWER
                    for card in deck
                )
                expected_disabled_healing["birdfacedurn"] = (
                    min(2, power_count) * 2.0
                    * remaining_combats * 0.45
                )
            if "lizardtail" in sustain_tokens:
                expected_disabled_healing["lizardtail"] = max_hp * 0.5
            if "regalpillow" in sustain_tokens:
                expected_disabled_healing["regalpillow"] = (
                    15.0 * remaining_rests * 0.45
                )

            if remaining_rests:
                expected_disabled_healing["campfire_rest"] = (
                    (max_hp * 3 // 10) * remaining_rests * 0.28
                )

            card_heal = {
                "bandageup": 5.0,
                "bite": 4.0,
                "feed": 1.5,
                "reaper": 8.0,
                "selfrepair": 8.0,
            }
            for card_token, amount in card_heal.items():
                count = sum(
                    self._token(getattr(card, "card_id", ""))
                    == card_token
                    for card in deck
                )
                if count:
                    expected_disabled_healing[f"card:{card_token}"] = (
                        count * amount * remaining_combats * 0.34
                    )

            potion_heal = {
                "bloodpotion": max_hp * 0.20,
                "fairypotion": max_hp * 0.30,
                "fruitjuice": 5.0,
                "regenpotion": 15.0,
            }
            for potion_id in healing_potions:
                potion_token = self._token(potion_id)
                if potion_token in potion_heal:
                    key = f"potion:{potion_token}"
                    expected_disabled_healing[key] = (
                        expected_disabled_healing.get(key, 0.0)
                        + potion_heal[potion_token]
                    )

            disabled_healing_capacity = sum(
                expected_disabled_healing.values()
            )
            healing_lock_opportunity_cost = (
                missing_hp * 0.85
                + disabled_healing_capacity * 0.70
                + min(7.0, remaining_floors * 0.28)
                + max(
                    0.0,
                    0.62 - float(deck_readiness.get("score", 0.0))
                ) * 24.0
            )

            # Upgrade priority is not itself realized run value.  Convert the
            # per-card signals with the remaining route horizon and how often
            # this deck is expected to cycle.  This stops a large, slow deck
            # full of low-impact starter upgrades from receiving the same
            # package multiplier as a compact deck with several high-impact
            # upgrades, while keeping every eligible card in the calculation.
            upgrade_horizon_factor = max(
                0.55, min(1.0, (remaining_floors + 6.0) / 20.0)
            )
            estimated_cycle_turns = max(
                1.5,
                float(deck_readiness.get("estimated_cycle_turns", 3.0) or 3.0),
            )
            upgrade_cycle_factor = max(
                0.72, min(1.10, 3.0 / estimated_cycle_turns)
            )
            upgrade_realization_factor = (
                0.52 * upgrade_horizon_factor * upgrade_cycle_factor
            )
            estimated_upgrade_benefit = min(
                62.0,
                total_upgrade_value * upgrade_realization_factor,
            )

            omamori_charges = self._event_omamori_charges()

            rows = []
            for option in valid_options:
                index = int(option.choice_index)
                visible = self._token(
                    f"{getattr(option, 'label', '')} "
                    f"{getattr(option, 'text', '')}"
                )
                if index == 0:
                    combat_gold = 25 if ascension >= 15 else 50
                    rare_relic_expected_value = (
                        float(self._NEOW_REWARD_VALUES["ONE_RARE_RELIC"])
                        * upgrade_horizon_factor
                    )
                    combat_gold_expected_value = self._event_gold_gain_value(
                        combat_gold
                    )
                    fight_readiness_credit = min(
                        8.0, fight_readiness["score"] * 0.35
                    )
                    low_hp_penalty = max(0.0, 0.72 - hp_ratio) * 55.0
                    deck_strength_ready = bool(
                        float(fight_readiness["score"]) >= 14.0
                    )
                    weak_deck_penalty = (
                        0.0 if deck_strength_ready else 12.0
                    )
                    war_score_inputs = {
                        "rare_relic_expected_value": rare_relic_expected_value,
                        "combat_gold_expected_value": combat_gold_expected_value,
                        "fight_readiness_credit": fight_readiness_credit,
                        "low_hp_penalty": low_hp_penalty,
                        "weak_deck_penalty": weak_deck_penalty,
                    }
                    war_score = (
                        rare_relic_expected_value
                        + combat_gold_expected_value
                        + fight_readiness_credit
                        - low_hp_penalty
                        - weak_deck_penalty
                    )
                    rows.append({
                        "option": option,
                        "outcome_id": "war",
                        "local_score": war_score,
                        "score_evidence": self._linear_score_contract(
                            "mind_bloom_war_expected_utility_v2",
                            war_score_inputs,
                            (
                                (
                                    "rare_relic_expected_value",
                                    "rare_relic_expected_value", 1.0,
                                ),
                                (
                                    "combat_gold_expected_value",
                                    "combat_gold_expected_value", 1.0,
                                ),
                                (
                                    "fight_readiness_credit",
                                    "fight_readiness_credit", 1.0,
                                ),
                                (
                                    "low_hp_penalty",
                                    "low_hp_penalty", -1.0,
                                ),
                                (
                                    "weak_deck_penalty",
                                    "weak_deck_penalty", -1.0,
                                ),
                            ),
                        ),
                        "signals": [
                            "act1_boss_combat", "combat_rewards",
                            "rare_relic",
                        ],
                        "consequences": {
                            "operation": "mind_bloom_war_future_combat",
                            "rare_relic_delta": 1,
                            "combat_rewards": True,
                            "future_combat_gold": combat_gold,
                            "random_effects": [{
                                "kind": "relic_gain",
                                "domain": "rare_relics",
                                "rarities": ["RARE"],
                                "count": 1,
                                "timing": "after_optional_boss_combat",
                                "selection_mode": "random",
                            }],
                        },
                        "post_state": {
                            "hp_before_combat": current_hp,
                            "max_hp": max_hp,
                            "fight_readiness": fight_readiness,
                            "deck_strength_ready": deck_strength_ready,
                            "survival_ready": bool(
                                fight_readiness["hp_ratio"] >= 0.65
                            ),
                            "rare_relic_expected_value": round(
                                rare_relic_expected_value, 3
                            ),
                            "rare_relic_value_source": (
                                "typed_random_rare_relic_prior_with_horizon"
                            ),
                            "combat_gold_expected_value": round(
                                combat_gold_expected_value, 3
                            ),
                            "low_hp_penalty": round(low_hp_penalty, 3),
                            "weak_deck_penalty": round(
                                weak_deck_penalty, 3
                            ),
                            "boss_pool": "random_act_1_boss",
                        },
                    })
                elif index == 1:
                    awake_score_inputs = {
                        "estimated_upgrade_benefit": (
                            estimated_upgrade_benefit
                        ),
                        "healing_lock_opportunity_cost": (
                            healing_lock_opportunity_cost
                        ),
                    }
                    awake_score = (
                        estimated_upgrade_benefit
                        - healing_lock_opportunity_cost
                    )
                    rows.append({
                        "option": option,
                        "outcome_id": "awake",
                        "local_score": awake_score,
                        "score_evidence": self._linear_score_contract(
                            "mind_bloom_awake_expected_utility_v2",
                            awake_score_inputs,
                            (
                                (
                                    "estimated_upgrade_benefit",
                                    "estimated_upgrade_benefit", 1.0,
                                ),
                                (
                                    "healing_lock_opportunity_cost",
                                    "healing_lock_opportunity_cost", -1.0,
                                ),
                            ),
                        ),
                        "signals": [
                            "upgrade_all_eligible_cards",
                            "permanent_healing_lock",
                        ],
                        "consequences": {
                            "operation": "mind_bloom_awake",
                            "upgraded_card_delta": len(upgrade_rows),
                            "healing_locked": True,
                            "relic_delta": 1,
                            "relic_id": "Mark of the Bloom",
                        },
                        "post_state": {
                            "current_hp": current_hp,
                            "max_hp": max_hp,
                            "missing_hp_locked_in": missing_hp,
                            "eligible_upgrade_count": len(upgrade_rows),
                            "estimated_total_upgrade_value": round(
                                total_upgrade_value, 3
                            ),
                            "estimated_upgrade_benefit": round(
                                estimated_upgrade_benefit, 3
                            ),
                            "upgrade_realization": {
                                "horizon_factor": round(
                                    upgrade_horizon_factor, 3
                                ),
                                "cycle_factor": round(
                                    upgrade_cycle_factor, 3
                                ),
                                "combined_factor": round(
                                    upgrade_realization_factor, 3
                                ),
                                "estimated_cycle_turns": round(
                                    estimated_cycle_turns, 3
                                ),
                            },
                            "upgrade_value_groups": {
                                key: {
                                    "count": int(value["count"]),
                                    "priority_signal": round(
                                        value["priority_signal"], 3
                                    ),
                                }
                                for key, value in upgrade_value_groups.items()
                            },
                            "top_upgrade_targets": [
                                {
                                    "card": self._macro_card_facts(card),
                                    "upgrade_priority_signal": round(value, 3),
                                    "upgrade_score_parts": (
                                        self._upgrade_score_parts(card)
                                    ),
                                }
                                for value, card in upgrade_rows[:6]
                            ],
                            "sustain_relics_disabled": sustain_ids,
                            "healing_cards_disabled": healing_cards,
                            "healing_potions_disabled": healing_potions,
                            "automatic_act_transition_healing_disabled": True,
                            "remaining_floors_estimate": remaining_floors,
                            "remaining_healing_trigger_estimate": {
                                "combats": remaining_combats,
                                "rests": remaining_rests,
                                "shops": remaining_shops,
                                "boss_entries": remaining_boss_entries,
                                "potion_uses": future_potion_uses,
                            },
                            "disabled_healing_by_source": {
                                key: round(value, 3)
                                for key, value
                                in sorted(expected_disabled_healing.items())
                            },
                            "disabled_healing_capacity_estimate": round(
                                disabled_healing_capacity, 3
                            ),
                            "healing_lock_opportunity_cost": round(
                                healing_lock_opportunity_cost, 3
                            ),
                            "deck_readiness": deck_readiness,
                        },
                    })
                else:
                    # Runtime text wins at the boundary; floor 41+ is the
                    # deterministic fallback when labels are localized.
                    healthy = (
                        any(marker in visible for marker in (
                            "healthy", "heal", "fullhp", "doubt"
                        ))
                        or (
                            not any(marker in visible for marker in (
                                "rich", "999", "normality", "gold"
                            ))
                            and floor >= 41
                        )
                    )
                    if healthy:
                        curse_consequences = (
                            self._event_curse_gain_consequences(
                                1, curse_id="Doubt"
                            )
                        )
                        healthy_curse_cost = (
                            self._event_curse_opportunity_cost(
                                curse_consequences, 18.0
                            )
                        )
                        darkstone_gain = (
                            6
                            if curse_consequences[
                                "effective_curse_delta"
                            ] > 0
                            and self._has_relic("Darkstone Periapt")
                            else 0
                        )
                        total_hp_gain = missing_hp + darkstone_gain
                        darkstone_profile_credit = float(
                            (
                                curse_consequences.get(
                                    "curse_trade_profile"
                                ) or {}
                            ).get("synergy_components", {}).get(
                                "darkstone_periapt", 0.0
                            ) or 0.0
                        )
                        healthy_heal_value = total_hp_gain * 0.72
                        healthy_score = (
                            healthy_heal_value
                            + darkstone_gain * 0.85
                            - healthy_curse_cost
                            - darkstone_profile_credit
                        )
                        rows.append({
                            "option": option,
                            "outcome_id": "healthy",
                            "local_score": healthy_score,
                            "score_evidence": self._linear_score_contract(
                                "mind_bloom_healthy_expected_utility_v2",
                                {
                                    "heal_value": healthy_heal_value,
                                    "darkstone_max_hp_value": (
                                        darkstone_gain * 0.85
                                    ),
                                    "darkstone_profile_credit": (
                                        darkstone_profile_credit
                                    ),
                                    "curse_opportunity_cost": (
                                        healthy_curse_cost
                                    ),
                                },
                                (
                                    ("heal_value", "heal_value", 1.0),
                                    (
                                        "darkstone_max_hp_value",
                                        "darkstone_max_hp_value", 1.0,
                                    ),
                                    (
                                        "darkstone_profile_credit",
                                        "darkstone_profile_credit", -1.0,
                                    ),
                                    (
                                        "curse_opportunity_cost",
                                        "curse_opportunity_cost", -1.0,
                                    ),
                                ),
                            ),
                            "signals": ["heal_to_full", "doubt"],
                            "consequences": {
                                "operation": "mind_bloom_healthy",
                                "hp_delta": total_hp_gain,
                                "max_hp_delta": darkstone_gain,
                                **curse_consequences,
                            },
                            "post_state": {
                                "current_hp": max_hp + darkstone_gain,
                                "max_hp": max_hp + darkstone_gain,
                                "omamori_charges_before": omamori_charges,
                                "omamori_charges_after": (
                                    curse_consequences[
                                        "omamori_charges_after_if_triggered"
                                    ]
                                ),
                            },
                        })
                    else:
                        curse_consequences = (
                            self._event_curse_gain_consequences(
                                2, curse_id="Normality"
                            )
                        )
                        curses_added = curse_consequences[
                            "effective_curse_delta"
                        ]
                        rich_gold_value = self._event_gold_gain_value(999)
                        rich_curse_cost = self._event_curse_opportunity_cost(
                            curse_consequences, 24.0
                        )
                        rich_score = rich_gold_value - rich_curse_cost
                        rows.append({
                            "option": option,
                            "outcome_id": "rich",
                            "local_score": rich_score,
                            "score_evidence": self._linear_score_contract(
                                "mind_bloom_rich_expected_utility_v2",
                                {
                                    "gold_expected_value": rich_gold_value,
                                    "curse_opportunity_cost": rich_curse_cost,
                                },
                                (
                                    (
                                        "gold_expected_value",
                                        "gold_expected_value", 1.0,
                                    ),
                                    (
                                        "curse_opportunity_cost",
                                        "curse_opportunity_cost", -1.0,
                                    ),
                                ),
                            ),
                            "signals": ["gain_999_gold", "normality_x2"],
                            "consequences": {
                                "operation": "mind_bloom_rich",
                                "gold_delta": 999,
                                **curse_consequences,
                            },
                            "post_state": {
                                "gold": int(
                                    getattr(self.game, "gold", 0) or 0
                                ) + 999,
                                "gold_expected_value": round(
                                    rich_gold_value, 3
                                ),
                                "normality_added": curses_added,
                                "omamori_charges_before": omamori_charges,
                                "omamori_charges_after": (
                                    curse_consequences[
                                        "omamori_charges_after_if_triggered"
                                    ]
                                ),
                            },
                        })

            action = choose_signed_irreversible(
                rows,
                "mind_bloom_signed_post_state",
                floor=floor,
                fight_readiness=fight_readiness,
                deck_readiness=deck_readiness,
            )
            if action is not None:
                return action

        if event_id == "tomboflordredmask" and len(valid_options) >= 2:
            already_owned = self._has_relic("Red Mask")
            gold = max(0, int(getattr(self.game, "gold", 0) or 0))
            if already_owned:
                take_score = self._event_gold_gain_value(222)
                take_consequences = {
                    "gold_delta": 222,
                    "red_mask_already_owned": True,
                }
            else:
                take_score = 18.0 - gold * 0.13
                take_consequences = {
                    "gold_delta": -gold,
                    "relic_delta": 1,
                    "relic_id": "Red Mask",
                    "relic_value": 18.0,
                }
            # Bind to semantic text when available and otherwise to the
            # stable original choice_index; never to container order.
            rows = []
            for option in valid_options:
                if (
                    int(option.choice_index) == 0
                    and not option_is_leave(option)
                ):
                    rows.append({
                        "kind": "take_mask",
                        "option": option,
                        "score": take_score,
                        "consequences": take_consequences,
                    })
                else:
                    rows.append({
                        "kind": "leave",
                        "option": option,
                        "score": 1.0,
                        "tie_priority": 1.0,
                        "consequences": {"leave": True},
                    })
            action = choose_scored_event(
                rows,
                "red_mask_gold_opportunity_cost",
                gold=gold,
                already_owned=already_owned,
            )
            if action is not None:
                return action

        if event_id == "thewomaninblue" and len(valid_options) >= 2:
            real_potions = list(self.game.get_real_potions())
            capacity = self._potion_slot_capacity()
            empty_slots = max(0, capacity - len(real_potions))
            costs = {0: 20, 1: 30, 2: 40}
            sozu = self._has_relic("Sozu")
            ascension = int(
                getattr(self.game, "ascension_level", 0) or 0
            )
            max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
            current_hp = max(
                0, int(getattr(self.game, "current_hp", 0) or 0)
            )
            leave_hp_loss = (
                int(math.ceil(max_hp * 0.05)) if ascension >= 15 else 0
            )
            weakest_owned_value = min(
                (
                    float(self._potion_keep_score(potion))
                    for potion in real_potions
                ),
                default=None,
            )
            rows = []
            for option in valid_options:
                choice_index = int(option.choice_index)
                count = choice_index + 1
                cost = costs.get(choice_index)
                if cost is None:
                    lethal_leave = bool(
                        leave_hp_loss > 0 and current_hp <= leave_hp_loss
                    )
                    rows.append({
                        "kind": "leave",
                        "option": option,
                        "score": (
                            -1000.0
                            if lethal_leave
                            else 1.0 - leave_hp_loss
                        ),
                        "tie_priority": 1.0,
                        "consequences": {
                            "leave": True,
                            "hp_delta": -leave_hp_loss,
                            "hp_loss_type": "HP_LOSS",
                            "lethal": lethal_leave,
                        },
                    })
                    continue
                fills = min(count, empty_slots)
                overflow_choices = max(0, count - fills)
                # Potion rewards remain selectable when the belt is full:
                # each extra random bottle is an option to replace the
                # weakest held potion (or to choose the best bottles when the
                # bundle exceeds the remaining slots).  This is an expected
                # option value, not a claim that every random potion is good.
                if overflow_choices <= 0:
                    replacement_value = 0.0
                elif weakest_owned_value is None:
                    replacement_value = 2.0 * min(2, overflow_choices)
                else:
                    expected_upgrade_gap = max(
                        0.0, 24.0 - weakest_owned_value
                    )
                    choice_capture = min(
                        0.75, 0.35 + 0.20 * (overflow_choices - 1)
                    )
                    replacement_value = (
                        expected_upgrade_gap * choice_capture
                    )
                bundle_value = fills * 6.5 + replacement_value
                legal = bool(
                    not sozu
                    and cost <= int(self.game.gold)
                )
                rows.append({
                    "kind": f"buy_{count}_potions",
                    "option": option,
                    "score": (
                        bundle_value - cost * 0.13
                        if legal else -1000.0
                    ),
                    "consequences": {
                        "gold_delta": -cost,
                        "potion_delta": count,
                        "empty_slots_filled": fills,
                        "replacement_choices": overflow_choices,
                        "replacement_option_value": round(
                            replacement_value, 3
                        ),
                        "legal": legal,
                        "sozu_blocks": sozu,
                    },
                })
            action = choose_scored_event(
                rows,
                "woman_in_blue_fill_available_slots",
                gold=int(getattr(self.game, "gold", 0) or 0),
                empty_slots=empty_slots,
                weakest_owned_potion_value=(
                    round(weakest_owned_value, 3)
                    if weakest_owned_value is not None else None
                ),
                ascension=ascension,
                leave_hp_loss=leave_hp_loss,
            )
            if action is not None:
                return action

        if event_id == "ghosts" and len(valid_options) >= 2:
            ascension = int(
                getattr(self.game, "ascension_level", 0) or 0
            )
            apparitions = sum(
                self._token(getattr(card, "card_id", ""))
                in {"apparition", "ghostly"}
                for card in self.game.deck
            )
            received = 3 if ascension >= 15 else 5
            max_hp = max(1, int(self.game.max_hp))
            current_hp = int(self.game.current_hp)
            post_max_hp = max(1, max_hp // 2)
            max_hp_loss = max_hp - post_max_hp
            post_current_hp = min(current_hp, post_max_hp)
            toxic_egg = self._has_relic("Toxic Egg 2") or self._has_relic(
                "Toxic Egg"
            )
            rows = []
            for option in valid_options:
                if (
                    int(option.choice_index) == 0
                    and not option_is_leave(option)
                ):
                    preview = getattr(option, "card", None)
                    preview_card_id = getattr(preview, "card_id", None)
                    card_id = preview_card_id or "Apparition"
                    valuation = self._apparition_event_valuation(
                        received,
                        apparitions,
                        upgraded=bool(toxic_egg),
                    )
                    rows.append({
                        "option": option,
                        "outcome_id": "accept_apparitions",
                        "local_score": valuation["score"],
                        "score_evidence": valuation["score_evidence"],
                        "signals": [
                            "apparition_intangible",
                            "lose_half_max_hp",
                            "contextual_marginal_prevention",
                        ],
                        "consequences": {
                            "operation": "ghosts_accept",
                            "max_hp_delta": -max_hp_loss,
                            "hp_delta": post_current_hp - current_hp,
                            "card_delta": received,
                            "card_id": card_id,
                            **({
                                "acquired_benefit": {
                                    "kind": "card_package",
                                    "id": card_id,
                                    "card_id": card_id,
                                    "count": received,
                                },
                            } if preview_card_id else {}),
                        },
                        "post_state": {
                            "current_hp": post_current_hp,
                            "max_hp": post_max_hp,
                            "apparitions_before": apparitions,
                            "apparitions_added": received,
                            "apparitions_upgraded": bool(toxic_egg),
                            "deck_size": len(self.game.deck) + received,
                            "apparition_valuation": {
                                key: value
                                for key, value in valuation.items()
                                if key not in {"score", "score_evidence"}
                            },
                        },
                    })
                else:
                    rows.append({
                        "option": option,
                        "outcome_id": "decline",
                        "local_score": 0.0,
                        "signals": ["no_change"],
                        "consequences": {"operation": "ghosts_decline"},
                        "post_state": {
                            "current_hp": current_hp,
                            "max_hp": max_hp,
                            "apparitions_before": apparitions,
                        },
                    })
            action = choose_signed_irreversible(
                rows,
                "ghosts_signed_post_state",
                ascension=ascension,
            )
            if action is not None:
                return action

        if event_id == "vampires" and len(valid_options) >= 2:
            strike_count = sum(
                self._token(getattr(card, "card_id", "")).startswith("strike")
                for card in self.game.deck
            )
            has_bites = any(
                self._token(getattr(card, "card_id", "")) == "bite"
                for card in self.game.deck
            )
            max_hp = max(1, int(self.game.max_hp))
            current_hp = int(self.game.current_hp)
            blood_vial = next(
                (
                    relic for relic in getattr(self.game, "relics", []) or []
                    if self._token(getattr(relic, "relic_id", ""))
                    == "bloodvial"
                ),
                None,
            )
            # Base game uses MathUtils.ceil(maxHealth * 0.30F).
            base_max_hp_loss = (max_hp * 3 + 9) // 10
            blood_vial_relic_cost = (
                max(6.0, float(self._relic_keep_score(blood_vial)) * 0.35)
                if blood_vial is not None else 0.0
            )
            deck_delta = 5 - strike_count
            sustain_value = self._bite_sustain_value(
                [card for card in self.game.deck
                 if not self._token(card.card_id).startswith("strike")],
                added_bites=5,
            )
            rows = []
            last_choice_index = max(
                int(option.choice_index) for option in valid_options
            )
            for option in valid_options:
                typed_consequence = (
                    self._typed_progress_event_option_consequences(option)
                )
                typed_operation = str(
                    (typed_consequence or {}).get("operation") or ""
                )
                visible = self._token(
                    f"{getattr(option, 'label', '')} "
                    f"{getattr(option, 'text', '')}"
                )
                typed_classified = not typed_operation.startswith(
                    "unclassified_"
                ) and bool(typed_operation)
                decline = (
                    typed_operation == "vampires_decline"
                    if typed_classified else
                    any(
                        marker in visible
                        for marker in ("refuse", "decline", "leave")
                    ) or (
                        int(option.choice_index) == last_choice_index
                        and not any(
                            marker in visible
                            for marker in (
                                "accept", "bite", "bloodvial",
                                "removeallstrikes",
                            )
                        )
                    )
                )
                trade_blood_vial = (
                    typed_operation
                    == "vampires_trade_blood_vial_for_bites"
                    if typed_classified else bool(
                        blood_vial is not None and "bloodvial" in visible
                    )
                )
                if not decline:
                    max_hp_loss = (
                        0 if trade_blood_vial else base_max_hp_loss
                    )
                    post_max_hp = max(1, max_hp - max_hp_loss)
                    post_current_hp = min(current_hp, post_max_hp)
                    relic_cost = (
                        blood_vial_relic_cost if trade_blood_vial else 0.0
                    )
                    score = (
                        strike_count * 7.0
                        - max(0, deck_delta) * 7.0
                        + sustain_value
                        - max_hp_loss * 0.62
                        - relic_cost
                        - (36.0 if has_bites else 0.0)
                    )
                    legacy_consequence = {
                        "removed_strikes": strike_count,
                        "bites_added": 5,
                        "bite_sustain_value": round(sustain_value, 3),
                        "deck_delta": deck_delta,
                        "max_hp_delta": -max_hp_loss,
                        "hp_delta": post_current_hp - current_hp,
                        "relic_delta": -1 if trade_blood_vial else 0,
                        "removed_relic_id": (
                            "Blood Vial" if trade_blood_vial else None
                        ),
                    }
                    chosen_consequence = (
                        dict(typed_consequence)
                        if typed_consequence else legacy_consequence
                    )
                    if typed_consequence:
                        chosen_consequence["relic_delta"] = (
                            -1 if trade_blood_vial else 0
                        )
                    rows.append({
                        "option": option,
                        "outcome_id": (
                            "trade_blood_vial_for_bites"
                            if trade_blood_vial else "accept_bites"
                        ),
                        "local_score": score,
                        "signals": [
                            "remove_all_strikes", "receive_five_bites",
                            (
                                "lose_blood_vial"
                                if trade_blood_vial
                                else "lose_thirty_percent_max_hp"
                            ),
                        ],
                        "consequences": chosen_consequence,
                        "post_state": {
                            "current_hp": post_current_hp,
                            "max_hp": post_max_hp,
                            "deck_size": len(self.game.deck) + deck_delta,
                            "strike_count": 0,
                            "bite_count_added": 5,
                            "already_had_bites": has_bites,
                        },
                    })
                else:
                    decline_consequence = (
                        dict(typed_consequence)
                        if typed_consequence else {"leave": True}
                    )
                    rows.append({
                        "option": option,
                        "outcome_id": "decline",
                        "local_score": 0.0,
                        "signals": ["no_change"],
                        "consequences": decline_consequence,
                        "post_state": {
                            "current_hp": current_hp,
                            "max_hp": max_hp,
                            "strike_count": strike_count,
                        },
                    })
            action = choose_signed_irreversible(
                rows,
                "vampires_signed_post_state",
                strikes=strike_count,
                has_blood_vial=blood_vial is not None,
            )
            if action is not None:
                return action

        if event_id == "themoaihead" and valid_options:
            max_hp = max(1, int(self.game.max_hp))
            current_hp = int(self.game.current_hp)
            healing_blocked = self._has_relic("Mark of the Bloom")
            golden_idol = next(
                (
                    relic for relic in self.game.relics
                    if self._token(getattr(relic, "relic_id", ""))
                    == "goldenidol"
                ),
                None,
            )
            terminal_dialog = len(valid_options) == 1
            rows = []
            for option in valid_options:
                original_index = int(
                    getattr(option, "original_button_index", 0) or 0
                )
                consequence = self._typed_event_zero_consequence(
                    "The Moai Head", "base_game_themoaihead_a0_v1",
                    "moai_head_leave", "leave",
                )
                if terminal_dialog or original_index == 2:
                    local_score = 0.0
                    signals = ["no_change"]
                    consequence["leave"] = True
                    if terminal_dialog:
                        consequence.update({
                            "operation": (
                                "themoaihead_dialog_advance_noop"
                            ),
                            "event_outcome_id": "dialog_advance",
                        })
                    post_hp = current_hp
                    post_max_hp = max_hp
                elif original_index == 0:
                    max_hp_loss = max(1, (max_hp + 4) // 8)
                    post_max_hp = max(1, max_hp - max_hp_loss)
                    post_hp = (
                        min(current_hp, post_max_hp)
                        if healing_blocked else post_max_hp
                    )
                    hp_delta = post_hp - current_hp
                    consequence.update({
                        "operation": "moai_head_jump_inside",
                        "event_outcome_id": "jump_inside",
                        "hp_delta": hp_delta,
                        "max_hp_delta": -max_hp_loss,
                        "current_cost": {
                            "gold": 0, "hp": 0,
                            "max_hp": max_hp_loss,
                        },
                    })
                    local_score = (
                        max(0, hp_delta) * 0.72
                        - max_hp_loss * 0.85
                    )
                    signals = ["heal_to_full", "max_hp_loss"]
                elif original_index == 1 and golden_idol is not None:
                    gold_gain = (
                        0 if self._has_relic("Ectoplasm") else 333
                    )
                    relic_keep = float(self._relic_keep_score(golden_idol))
                    consequence.update({
                        "operation": "moai_head_offer_golden_idol",
                        "event_outcome_id": "offer_golden_idol",
                        "gold_delta": gold_gain,
                        "relic_changes": {
                            "gain": [],
                            "remove": [{
                                "id": getattr(
                                    golden_idol, "relic_id", "Golden Idol"
                                ),
                            }],
                            "counter": [],
                        },
                    })
                    local_score = gold_gain * 0.12 - relic_keep
                    signals = ["gold_gain", "relic_loss"]
                    post_hp = current_hp
                    post_max_hp = max_hp
                else:
                    continue
                rows.append({
                    "option": option,
                    "outcome_id": consequence["event_outcome_id"],
                    "local_score": local_score,
                    "signals": signals,
                    "consequences": consequence,
                    "post_state": {
                        "current_hp": post_hp,
                        "max_hp": post_max_hp,
                    },
                })
            action = choose_signed_irreversible(
                rows,
                "moai_head_signed_post_state",
                healing_blocked=healing_blocked,
                has_golden_idol=golden_idol is not None,
            )
            if action is not None:
                return action

        if event_id == "windinghalls" and len(valid_options) >= 3:
            ascension = int(
                getattr(self.game, "ascension_level", 0) or 0
            )
            max_hp = max(1, int(self.game.max_hp))
            current_hp = int(self.game.current_hp)
            omamori_charges = self._event_omamori_charges()
            madness_hp_loss = max(
                1,
                int(math.floor(
                    max_hp * (0.18 if ascension >= 15 else 0.125) + 0.5
                )),
            )
            focus_heal = max(
                1,
                int(math.floor(
                    max_hp * (0.20 if ascension >= 15 else 0.25) + 0.5
                )),
            )
            retrace_max_hp_loss = max(
                1, int(math.floor(max_hp * 0.05 + 0.5))
            )
            realized_madness_hp_loss = max(
                0,
                madness_hp_loss
                - (1 if self._has_relic("Tungsten Rod") else 0),
            )
            healing_blocked = self._has_relic("Mark of the Bloom")
            rows = []
            for option in valid_options:
                index = int(option.choice_index)
                if index == 0:
                    post_hp = max(
                        0, current_hp - realized_madness_hp_loss
                    )
                    rows.append({
                        "option": option,
                        "outcome_id": "embrace_madness",
                        # Two extra cards are deck bloat unless the current
                        # deck can exploit permanent cost reduction; do not
                        # value the event as if it simply granted two free
                        # playable cards.
                        "local_score": (
                            2.0 - realized_madness_hp_loss * 0.9
                        ),
                        "signals": ["madness_x2", "current_hp_loss"],
                        "consequences": {
                            "hp_delta": post_hp - current_hp,
                            "nominal_hp_loss": madness_hp_loss,
                            "card_delta": 2,
                            "card_id": "Madness",
                        },
                        "post_state": {
                            "current_hp": post_hp,
                            "max_hp": max_hp,
                            "madness_added": 2,
                            "deck_size": len(self.game.deck) + 2,
                        },
                    })
                elif index == 1:
                    actual_heal = (
                        0 if healing_blocked else
                        min(max_hp - current_hp, focus_heal)
                    )
                    curse_consequences = (
                        self._event_curse_gain_consequences(
                            1, curse_id="Writhe"
                        )
                    )
                    darkstone_gain = (
                        6
                        if curse_consequences["effective_curse_delta"] > 0
                        and self._has_relic("Darkstone Periapt")
                        else 0
                    )
                    total_hp_gain = actual_heal + darkstone_gain
                    curse_cost = self._event_curse_opportunity_cost(
                        curse_consequences, 22.0
                    )
                    darkstone_profile_credit = float(
                        (
                            curse_consequences.get("curse_trade_profile")
                            or {}
                        ).get("synergy_components", {}).get(
                            "darkstone_periapt", 0.0
                        )
                        or 0.0
                    )
                    rows.append({
                        "option": option,
                        "outcome_id": "focus",
                        "local_score": (
                            total_hp_gain * 0.72
                            + darkstone_gain * 0.85
                            - curse_cost
                            - darkstone_profile_credit
                        ),
                        "signals": ["heal", "writhe"],
                        "consequences": {
                            "hp_delta": total_hp_gain,
                            "max_hp_delta": darkstone_gain,
                            **curse_consequences,
                        },
                        "post_state": {
                            "current_hp": current_hp + total_hp_gain,
                            "max_hp": max_hp + darkstone_gain,
                            "omamori_charges_before": omamori_charges,
                            "omamori_charges_after": (
                                curse_consequences[
                                    "omamori_charges_after_if_triggered"
                                ]
                            ),
                        },
                    })
                else:
                    post_max_hp = max(1, max_hp - retrace_max_hp_loss)
                    post_current_hp = min(current_hp, post_max_hp)
                    rows.append({
                        "option": option,
                        "outcome_id": "retrace_steps",
                        "local_score": -retrace_max_hp_loss * 0.85,
                        "signals": ["max_hp_loss"],
                        "consequences": {
                            "max_hp_delta": -retrace_max_hp_loss,
                            "hp_delta": post_current_hp - current_hp,
                        },
                        "post_state": {
                            "current_hp": post_current_hp,
                            "max_hp": post_max_hp,
                        },
                    })
            action = choose_signed_irreversible(
                rows,
                "winding_halls_signed_post_state",
                ascension=ascension,
                omamori_charges=omamori_charges,
            )
            if action is not None:
                return action

        if event_id == "thecleric":
            high_ascension = int(
                getattr(self.game, "ascension_level", 0) or 0
            ) >= 15
            heal_cost = 50 if high_ascension else 35
            removal_cost = 75 if high_ascension else 50
            max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
            current_hp = max(
                0, int(getattr(self.game, "current_hp", 0) or 0)
            )
            actual_heal = min(
                max_hp - current_hp,
                max(1, int(math.ceil(max_hp * 0.25))),
            )
            removable = list(getattr(self.game, "deck", []) or [])
            best_removal = max(
                (float(self._removal_score(card)) for card in removable),
                default=0.0,
            )
            rows = []
            for option in valid_options:
                option_token = self._token(
                    f"{getattr(option, 'label', '')} "
                    f"{getattr(option, 'text', '')}"
                )
                is_heal = any(
                    marker in option_token
                    for marker in {"heal", "healing", "娌荤枟", "鎭㈠"}
                )
                is_remove = any(
                    marker in option_token
                    for marker in {
                        "purify", "remove", "绾寲", "绉婚櫎",
                    }
                )
                is_heal = is_heal or any(
                    self._token(marker) in option_token
                    for marker in ("治疗", "恢复")
                )
                is_remove = is_remove or any(
                    self._token(marker) in option_token
                    for marker in ("净化", "移除")
                )
                is_leave = any(
                    self._token(marker) in option_token
                    for marker in ("leave", "depart", "离开")
                )
                # The Cleric's original ids are Heal=0, Purify=1, Leave=2.
                # Recognized semantics win when disabled buttons compact the
                # visible indices; otherwise stable base-game ids are the
                # fail-closed fallback.
                if is_heal or (
                    not is_remove
                    and not is_leave
                    and int(option.choice_index) == 0
                ):
                    legal = int(self.game.gold) >= heal_cost
                    rows.append({
                        "kind": "heal",
                        "option": option,
                        "score": (
                            actual_heal
                            * (0.70 + max(0.0, 0.70 - hp_ratio))
                            - heal_cost * 0.13
                            if legal else -1000.0
                        ),
                        "consequences": {
                            "gold_delta": -heal_cost,
                            "hp_delta": actual_heal,
                            "legal": legal,
                        },
                    })
                elif is_remove or (
                    not is_leave and int(option.choice_index) == 1
                ):
                    legal = bool(
                        removable and int(self.game.gold) >= removal_cost
                    )
                    rows.append({
                        "kind": "remove_card",
                        "option": option,
                        "score": (
                            best_removal / 5.0 - removal_cost * 0.13
                            if legal else -1000.0
                        ),
                        "consequences": {
                            "gold_delta": -removal_cost,
                            "card_delta": -1,
                            "best_removal_value": round(
                                best_removal, 3
                            ),
                            "legal": legal,
                        },
                    })
                else:
                    rows.append({
                        "kind": "leave",
                        "option": option,
                        "score": 1.0,
                        "tie_priority": 1.0,
                        "consequences": {"leave": True},
                    })
            action = choose_scored_event(
                rows,
                "cleric_signed_resource_trade",
                heal_cost=heal_cost,
                removal_cost=removal_cost,
                best_removal_score=round(best_removal, 3),
            )
            if action is not None:
                return action

        if event_id == "secretportal":
            # The portal removes the remaining upgrade/recovery/reward rooms
            # and cannot improve an autonomous clear's victory condition.
            action = choose_scored_event(
                [
                    {
                        "kind": (
                            "take_portal"
                            if int(option.choice_index) == 0
                            and not option_is_leave(option)
                            else "leave"
                        ),
                        "option": option,
                        "score": (
                            -30.0
                            if int(option.choice_index) == 0
                            and not option_is_leave(option)
                            else 1.0
                        ),
                        "consequences": (
                            {
                                "skip_remaining_act_rooms": True,
                                "route_opportunity_cost": 30.0,
                            }
                            if int(option.choice_index) == 0
                            and not option_is_leave(option)
                            else {"leave": True}
                        ),
                    }
                    for option in valid_options
                ],
                "secret_portal_preserve_survival_route",
                hard_constraint="preserve_remaining_route_resources",
            )
            if action is not None:
                return action

        if event_id in {"deadadventurer", "scrapooze"}:
            repeat_markers = {
                "deadadventurer": {
                    "search", "searchagain", "continue", "inspect",
                    "investigate", "keepsearching", "搜索", "调查",
                    "继续", "寻找", "翻找",
                },
                "scrapooze": {
                    "reachinside", "continue", "keepreaching", "伸手",
                    "继续", "接着", "往里伸", "翻找",
                },
            }[event_id]
            explore = next(
                (
                    option
                    for option in valid_options
                    if any(
                        marker in self._token(
                            f"{getattr(option, 'label', '')} {getattr(option, 'text', '')}"
                        )
                        for marker in repeat_markers
                    )
                ),
                None,
            )
            if explore is not None:
                safe_anchor = (
                    0.86 if event_id == "deadadventurer" else 0.82
                )
                reward_anchor = (
                    15.0 if event_id == "deadadventurer" else 10.0
                )
                rows = []
                for option in valid_options:
                    base_score, _, _ = self._generic_event_option_score(
                        option, hp_ratio, include_components=True
                    )
                    is_explore = option is explore
                    rows.append({
                        "kind": "explore" if is_explore else "leave",
                        "option": option,
                        "score": (
                            base_score
                            + reward_anchor
                            - max(0.0, safe_anchor - hp_ratio) * 45.0
                            if is_explore else base_score
                        ),
                        "consequences": self._event_option_consequences(
                            option
                        ),
                    })
                action = choose_scored_event(
                    rows,
                    "event_repeatable_reward_at_safe_hp",
                    safe_hp_anchor=safe_anchor,
                    reward_anchor=reward_anchor,
                    continuous_survival_scoring=True,
                )
                if action is not None:
                    return action

        if event_id in {"noteforyourself", "anoteforyourself"}:
            offered = [
                (value, card_id, option)
                for option in valid_options
                for value, card_id in [
                    self._note_for_yourself_card_value(option)
                ]
                if value is not None
            ]
            if offered:
                value, card_id, option = max(
                    offered, key=lambda item: item[0]
                )
                offered_by_option = {
                    id(item): (item_value, item_card_id)
                    for item_value, item_card_id, item in offered
                }
                rows = []
                for item in valid_options:
                    item_value, _item_card_id = offered_by_option.get(
                        id(item), (None, None)
                    )
                    is_offer = item_value is not None
                    consequences = self._event_option_consequences(item)
                    consequences = dict(consequences or {})
                    consequences["operation"] = (
                        "note_for_yourself_prepare_exchange"
                        if is_offer else "note_for_yourself_leave"
                    )
                    if not is_offer:
                        consequences["leave"] = True
                    rows.append({
                        "kind": "accept_exchange" if is_offer else "leave",
                        "option": item,
                        "score": float(item_value - 8.0) if is_offer else 0.0,
                        "consequences": consequences,
                        "reason_codes": [
                            "note_for_yourself_card_vs_exchange_cost",
                            (
                                "offered_card_value"
                                if is_offer else "leave_without_exchange"
                            ),
                        ],
                    })
                action = choose_scored_event(
                    rows,
                    (
                        "note_for_yourself_accept_positive_card"
                        if value >= 8.0
                        else "note_for_yourself_reject_low_value_card"
                    ),
                    offered_card=card_id,
                    offered_card_value=round(value, 3),
                    exchange_opportunity_cost=8.0,
                )
                if action is not None:
                    return action

        if event_id == "falling":
            option_types = {
                0: spirecomm.spire.card.CardType.SKILL,
                1: spirecomm.spire.card.CardType.POWER,
                2: spirecomm.spire.card.CardType.ATTACK,
            }
            if len(valid_options) == 1 and getattr(
                valid_options[0], "card", None
            ) is None:
                action = choose_scored_event(
                    [{
                        "kind": "forced_progress",
                        "option": valid_options[0],
                        "score": 0.0,
                        "consequences": {
                            "operation": "falling_forced_progress",
                        },
                        "reason_codes": [
                            "falling_singleton_dialog_progress",
                        ],
                    }],
                    "falling_singleton_dialog_progress",
                )
                if action is not None:
                    return action

            offered_rows = []
            for option in valid_options:
                preview = getattr(option, "card", None)
                original_index = getattr(
                    option, "original_button_index", None
                )
                if type(original_index) is not int:
                    original_index = getattr(option, "choice_index", None)
                expected_type = option_types.get(original_index)
                if preview is None or getattr(
                    preview, "type", None
                ) != expected_type:
                    continue
                score_parts = {
                    key: float(value)
                    for key, value in self._removal_score_parts(
                        preview, self.game.deck
                    ).items()
                }
                score = sum(score_parts.values())
                score_contract = self._linear_score_contract(
                    "falling_exact_offered_card_removal_value_v1",
                    score_parts,
                    tuple(
                        (key, key, 1.0) for key in sorted(score_parts)
                    ),
                )
                offered_rows.append({
                    "kind": "sacrifice_offered_card",
                    "option": option,
                    "score": score,
                    "consequences": {
                        "operation": "falling_sacrifice_offered_card",
                        "card_id": getattr(preview, "card_id", None),
                        "card_instance_id": getattr(preview, "uuid", None),
                    },
                    "reason_codes": [
                        "falling_exact_offered_card_removal_value",
                        f"offered_{getattr(expected_type, 'name', '').lower()}",
                    ],
                    **score_contract,
                })
            if len(offered_rows) == len(valid_options) and offered_rows:
                action = choose_scored_event(
                    offered_rows,
                    "falling_sacrifice_lowest_value_offered_card",
                    exact_offered_card_scoring=True,
                )
                if action is not None:
                    return action

        if event_id == "backtobasics":
            upgradable_basics = [
                card for card in self.game.deck
                if card.card_id in {"Strike_R", "Strike_G", "Strike_B", "Defend_R", "Defend_G", "Defend_B"}
                and int(getattr(card, "upgrades", 0) or 0) == 0
            ]
            upgrade_value = sum(
                max(0.0, float(self._upgrade_score(card)))
                for card in upgradable_basics
            ) * 1.50
            removal_value = max(
                (
                    float(self._removal_score(card)) / 5.0
                    for card in self.game.deck
                ),
                default=-1000.0,
            )
            rows = []
            for option in valid_options:
                if (
                    int(option.choice_index) == 0
                    and not option_is_leave(option)
                ):
                    rows.append({
                        "kind": "remove_card",
                        "option": option,
                        "score": removal_value,
                        "consequences": {
                            "card_delta": -1,
                            "best_removal_value": round(
                                removal_value * 5.0, 3
                            ),
                        },
                    })
                elif int(option.choice_index) == 1:
                    rows.append({
                        "kind": "upgrade_basics",
                        "option": option,
                        "score": upgrade_value,
                        "consequences": {
                            "upgrade_delta": len(upgradable_basics),
                            "upgrade_value": round(upgrade_value, 3),
                        },
                    })
                else:
                    rows.append({
                        "kind": "leave",
                        "option": option,
                        "score": 1.0,
                        "consequences": {"leave": True},
                    })
            action = choose_scored_event(
                rows,
                "back_to_basics_scored_deck_improvement",
                upgradable_basics=len(upgradable_basics),
            )
            if action is not None:
                return action

        if event_id == "nloth" and valid_options:
            if len(valid_options) == 1:
                option = valid_options[0]
                consequence = self._typed_event_zero_consequence(
                    "N'loth", "base_game_nloth_a0_v1",
                    "nloth_leave", "leave",
                )
                consequence["leave"] = True
                action = choose_index(
                    option.choice_index,
                    "nloth_terminal_leave",
                    [{
                        "id": option.choice_index,
                        "score": 0.0,
                        "label": getattr(option, "label", None),
                        "consequences": consequence,
                        "score_rule_id": "nloth_leave_v1",
                        "score_formula": {"kind": "sum_components_v1"},
                        "score_inputs": {"leave_value": 0.0},
                        "score_components": [{
                            "name": "leave_value", "input": "leave_value",
                            "coefficient": 1.0, "value": 0.0,
                        }],
                    }],
                    chosen="Leave",
                )
                if action is not None:
                    return action
            matched = []
            for option in valid_options:
                option_text = self._token(
                    f"{getattr(option, 'label', '')} {getattr(option, 'text', '')}"
                )
                relic = next(
                    (
                        item for item in self.game.relics
                        if self._token(getattr(item, "name", "")) in option_text
                        or self._token(getattr(item, "relic_id", "")) in option_text
                    ),
                    None,
                )
                if relic is not None:
                    matched.append((self._relic_keep_score(relic), option, relic))
            if matched:
                keep_score, option, relic = min(matched, key=lambda item: item[0])
                unmatched = [
                    item
                    for item in valid_options
                    if all(item is not matched_option for _, matched_option, _ in matched)
                ]
                if keep_score > 12 and unmatched:
                    selected_option = unmatched[-1]
                    reason = "nloth_keep_all_valuable_relics"
                else:
                    selected_option = option
                    reason = "nloth_trade_lowest_future_value_relic"
                relic_by_option = {
                    id(item): (score, relic_item)
                    for score, item, relic_item in matched
                }
                candidate_rows = []
                for item in valid_options:
                    matched_relic = relic_by_option.get(id(item))
                    if matched_relic is None:
                        consequence = self._typed_event_zero_consequence(
                            "N'loth", "base_game_nloth_a0_v1",
                            "nloth_leave", "leave",
                        )
                        consequence["leave"] = True
                        candidate_rows.append({
                            "id": item.choice_index,
                            "score": 0.0,
                            "label": getattr(item, "label", None),
                            "consequences": consequence,
                            "score_rule_id": "nloth_leave_v1",
                            "score_formula": {
                                "kind": "sum_components_v1",
                            },
                            "score_inputs": {"leave_value": 0.0},
                            "score_components": [{
                                "name": "leave_value",
                                "input": "leave_value",
                                "coefficient": 1.0,
                                "value": 0.0,
                            }],
                        })
                        continue
                    relic_score, relic_item = matched_relic
                    relic_id = getattr(relic_item, "relic_id", None)
                    consequence = self._typed_event_zero_consequence(
                        "N'loth", "base_game_nloth_a0_v1",
                        "nloth_trade_relic", "trade_relic",
                    )
                    consequence.update({
                        "relic_id": relic_id,
                        "relic_changes": {
                            "gain": [{"id": "Nloth's Gift"}],
                            "remove": [{"id": relic_id}],
                            "counter": [],
                        },
                        "acquired_benefit": {
                            "kind": "relic", "id": "Nloth's Gift",
                        },
                    })
                    candidate_rows.append({
                        "id": item.choice_index,
                        "score": 12.0 - relic_score,
                        "label": getattr(item, "label", None),
                        "consequences": consequence,
                        "score_rule_id": "nloth_trade_value_v1",
                        "score_formula": {"kind": "sum_components_v1"},
                        "score_inputs": {
                            "nloth_gift_value": 12.0,
                            "relic_keep_value": relic_score,
                        },
                        "score_components": [
                            {
                                "name": "nloth_gift_value",
                                "input": "nloth_gift_value",
                                "coefficient": 1.0,
                                "value": 12.0,
                            },
                            {
                                "name": "relic_keep_cost",
                                "input": "relic_keep_value",
                                "coefficient": -1.0,
                                "value": -relic_score,
                            },
                        ],
                    })
                action = choose_index(
                    selected_option.choice_index,
                    reason,
                    candidate_rows,
                    chosen=(
                        "Leave"
                        if selected_option in unmatched else relic.relic_id
                    ),
                    lowest_keep_score=round(keep_score, 3),
                )
                if action is not None:
                    return action

        if event_id in {"purifier", "transmorgrifier", "transmogrifier", "upgradeshrine"}:
            if event_id == "upgradeshrine":
                operation_value = max(
                    (
                        float(self._upgrade_score(card))
                        for card in self.game.deck
                    ),
                    default=-1000.0,
                )
                operation_kind = "upgrade_card"
                consequences = {
                    "upgrade_delta": 1,
                    "best_upgrade_value": round(operation_value, 3),
                }
            else:
                best_removal = max(
                    (
                        float(self._removal_score(card))
                        for card in self.game.deck
                    ),
                    default=-1000.0,
                )
                operation_kind = (
                    "remove_card"
                    if event_id == "purifier" else "transform_card"
                )
                operation_value = (
                    best_removal / 5.0
                    if event_id == "purifier"
                    else best_removal / 7.0 + 4.0
                )
                consequences = {
                    "card_delta": -1 if event_id == "purifier" else 0,
                    "card_transform_delta": (
                        1 if event_id != "purifier" else 0
                    ),
                    "best_removal_value": round(best_removal, 3),
                }
            rows = []
            for option in valid_options:
                if (
                    int(option.choice_index) == 0
                    and not option_is_leave(option)
                ):
                    rows.append({
                        "kind": operation_kind,
                        "option": option,
                        "score": operation_value,
                        "consequences": consequences,
                    })
                else:
                    rows.append({
                        "kind": "leave",
                        "option": option,
                        "score": 1.0,
                        "tie_priority": 1.0,
                        "consequences": {"leave": True},
                    })
            action = choose_scored_event(
                rows,
                "shrine_scored_deck_improvement",
                operation_value=round(operation_value, 3),
            )
            if action is not None:
                return action

        if event_id == "mushrooms" and len(valid_options) == 2:
            # Base-game Mushrooms has an index-stable initial surface:
            # 0 fights three Fungi Beasts for Odd Mushroom; 1 heals 25% Max
            # HP and adds Parasite.  Bind this only when the full original
            # index surface and the Parasite preview agree, so a later dialog
            # frame or modded lookalike still falls through as unclassified.
            by_original_index = {
                int(getattr(option, "original_button_index", -1)): option
                for option in valid_options
                if type(getattr(option, "original_button_index", None)) is int
            }
            recover_preview = getattr(
                by_original_index.get(1), "card", None
            )
            exact_surface = bool(
                set(by_original_index) == {0, 1}
                and getattr(by_original_index[0], "card", None) is None
                and recover_preview is not None
                and self._token(
                    getattr(recover_preview, "card_id", "")
                ) == "parasite"
                and self._enum_name(
                    getattr(recover_preview, "type", None)
                ) == "CURSE"
            )
            if exact_surface:
                profile = self._mushrooms_decision_profile()
                fight = by_original_index[0]
                recover = by_original_index[1]
                current_hp = max(
                    0, int(getattr(self.game, "current_hp", 0) or 0)
                )
                max_hp = max(
                    1,
                    int(
                        getattr(self.game, "max_hp", current_hp or 1)
                        or 1
                    ),
                )
                requested_heal = max(1, max_hp // 4)
                actual_heal = (
                    0 if self._has_relic("Mark of the Bloom") else
                    min(max(0, max_hp - current_hp), requested_heal)
                )
                hp_ratio = min(1.0, current_hp / max_hp)
                heal_weight = 0.70 + max(0.0, 0.72 - hp_ratio)
                heal_value = actual_heal * heal_weight
                parasite = self._event_curse_gain_consequences(
                    1, curse_id="Parasite"
                )
                parasite_cost = self._event_curse_opportunity_cost(
                    parasite
                )
                recover_score = heal_value - parasite_cost

                if profile["hard_survival_veto"]:
                    fight_score_evidence = self._linear_score_contract(
                        "mushrooms_optional_fight_utility_v1",
                        {"hard_survival_veto": -1_000_000.0},
                        ((
                            "hard_survival_veto",
                            "hard_survival_veto",
                            1.0,
                        ),),
                    )
                else:
                    fight_score_evidence = self._linear_score_contract(
                        "mushrooms_optional_fight_utility_v1",
                        {
                            "odd_mushroom_value": profile[
                                "odd_mushroom_value"
                            ],
                            "expected_hp_loss_cost": profile[
                                "expected_hp_loss_cost"
                            ],
                            "death_risk_cost": profile[
                                "death_risk_cost"
                            ],
                        },
                        (
                            (
                                "odd_mushroom_value",
                                "odd_mushroom_value", 1.0,
                            ),
                            (
                                "expected_hp_loss_cost",
                                "expected_hp_loss_cost", -1.0,
                            ),
                            (
                                "death_risk_cost",
                                "death_risk_cost", -1.0,
                            ),
                        ),
                    )
                rows = [
                    {
                        "kind": "fight_for_odd_mushroom",
                        "option": fight,
                        "score": profile["fight_score"],
                        "consequences": {
                            "operation": "mushrooms_prepare_combat",
                            "hp_delta": 0,
                            "max_hp_delta": 0,
                            "gold_delta": 0,
                            "card_changes": {
                                "gain": [], "remove": [],
                                "upgrade": [], "transform": [],
                            },
                            "relic_changes": {
                                "gain": [], "remove": [], "counter": [],
                            },
                            "potion_changes": {
                                "gain": [], "remove": [], "replace": [],
                            },
                            "current_cost": {
                                "gold": 0, "hp": 0, "max_hp": 0,
                            },
                            "probabilistic_outcomes": [],
                            "future_costs": [{
                                "kind": "event_combat_transition",
                                "event_id": "mushrooms",
                                "encounter_id": "The Mushroom Lair",
                                "requires_confirmation": True,
                                "reward": {
                                    "gold_range": [20, 30],
                                    "relic_id": "Odd Mushroom",
                                    "duplicate_relic_id": "Circlet",
                                },
                            }],
                            "relic_value": profile[
                                "odd_mushroom_value"
                            ],
                            "expected_hp_loss": profile[
                                "expected_hp_loss"
                            ],
                            "upper_hp_loss": profile["upper_hp_loss"],
                            "death_risk": profile["death_risk"],
                        },
                        "reason_codes": [
                            "exact_mushrooms_fight_reward",
                            "optional_combat_readiness_priced",
                        ],
                        **fight_score_evidence,
                    },
                    {
                        "kind": "heal_and_take_parasite",
                        "option": recover,
                        "score": recover_score,
                        "consequences": {
                            "operation": "mushrooms_heal_and_take_parasite",
                            "hp_delta": actual_heal,
                            **parasite,
                        },
                        "reason_codes": [
                            "exact_mushrooms_heal",
                            "exact_parasite_opportunity_cost",
                        ],
                        **self._linear_score_contract(
                            "mushrooms_heal_curse_utility_v1",
                            {
                                "actual_heal_value": heal_value,
                                "parasite_opportunity_cost": parasite_cost,
                            },
                            (
                                (
                                    "actual_heal_value",
                                    "actual_heal_value", 1.0,
                                ),
                                (
                                    "parasite_opportunity_cost",
                                    "parasite_opportunity_cost", -1.0,
                                ),
                            ),
                        ),
                    },
                ]
                action = choose_scored_event(
                    rows,
                    "mushrooms_reward_vs_recovery",
                    protocol_identity=(
                        "exact_event_id_original_button_index_parasite_preview"
                    ),
                    mushrooms_profile=profile,
                    requested_heal=requested_heal,
                    actual_heal=actual_heal,
                    heal_weight=heal_weight,
                    parasite_opportunity_cost=parasite_cost,
                )
                if action is not None:
                    return action

        if event_id == "maskedbandits" and len(valid_options) >= 2:
            pay = find_option(
                {"pay", "gold", "loseallgold", "givegold"},
                by_index.get(0, valid_options[0]),
            )
            fight = find_option(
                {"fight", "combat", "battle", "resist"},
                by_index.get(1, valid_options[-1]),
            )
            profile = self._masked_bandits_decision_profile()
            pay_contract = self._linear_score_contract(
                "masked_bandits_pay_gold_utility_v1",
                {
                    "gold_opportunity_value": profile[
                        "gold_opportunity_value"
                    ],
                },
                ((
                    "lost_gold_opportunity",
                    "gold_opportunity_value", -1.0,
                ),),
            )
            fight_inputs = {
                "red_mask_reward_value": profile[
                    "red_mask_reward_value"
                ],
                "expected_hp_opportunity_cost": profile[
                    "expected_hp_opportunity_cost"
                ],
                "death_risk": profile["death_risk"],
                "downstream_route_cost": profile[
                    "downstream_route_cost"
                ],
            }
            reconstructed_fight_score = (
                fight_inputs["red_mask_reward_value"]
                - fight_inputs["expected_hp_opportunity_cost"]
                - 200.0 * fight_inputs["death_risk"]
                - fight_inputs["downstream_route_cost"]
            )
            # Profile evidence is rounded for stable audit receipts.  Keep
            # the tiny residual (and any explicit hard veto) as named terms
            # so the independent oracle can reproduce the exact logged
            # score instead of silently trusting it.
            fight_inputs["profile_rounding_adjustment"] = (
                profile["raw_fight_score_before_veto"]
                - reconstructed_fight_score
            )
            fight_inputs["hard_survival_veto_adjustment"] = (
                profile["scores"]["fight"]
                - profile["raw_fight_score_before_veto"]
            )
            fight_contract = self._linear_score_contract(
                "masked_bandits_fight_net_utility_v1",
                fight_inputs,
                (
                    (
                        "red_mask_reward",
                        "red_mask_reward_value", 1.0,
                    ),
                    (
                        "expected_hp_cost",
                        "expected_hp_opportunity_cost", -1.0,
                    ),
                    ("death_risk_cost", "death_risk", -200.0),
                    (
                        "downstream_route_cost",
                        "downstream_route_cost", -1.0,
                    ),
                    (
                        "profile_rounding_adjustment",
                        "profile_rounding_adjustment", 1.0,
                    ),
                    (
                        "hard_survival_veto_adjustment",
                        "hard_survival_veto_adjustment", 1.0,
                    ),
                ),
            )
            candidate_rows = [
                {
                    "kind": "pay",
                    "option": pay,
                    "score": profile["scores"]["pay"],
                    "score_contract": pay_contract,
                    "consequences": {
                        "gold_delta": -int(profile["gold"]),
                        "leave": True,
                    },
                },
                {
                    "kind": "fight",
                    "option": fight,
                    "score": profile["scores"]["fight"],
                    "score_contract": fight_contract,
                    "consequences": {
                        "combat_delta": 1,
                        "relic_delta": (
                            0 if self._has_relic("Red Mask") else 1
                        ),
                        "expected_hp_loss": profile[
                            "expected_net_hp_loss"
                        ],
                        "death_risk": profile["death_risk"],
                        "future_costs": [{
                            "kind": "event_combat_transition",
                            "event_id": "maskedbandits",
                            "encounter_id": "Masked Bandits",
                            "reward": {
                                "relic_id": "Red Mask",
                                "duplicate_relic_id": "Circlet",
                            },
                            "timing": "after_event_choice",
                        }],
                    },
                },
            ]
            # Candidate ordering is UI-dependent, so the semantic kind is the
            # stable tie-break.  On an exact utility tie, preserve survival by
            # paying; otherwise choose the exact logged argmax.
            chosen_row = max(
                candidate_rows,
                key=lambda row: (
                    float(row["score"]),
                    1 if row["kind"] == "pay" else 0,
                ),
            )
            chosen = chosen_row["option"]
            action = choose_index(
                chosen.choice_index,
                "masked_bandits_gold_vs_combat_readiness",
                [
                    {
                        "id": row["option"].choice_index,
                        "score": row["score"],
                        "label": getattr(row["option"], "label", None),
                        "text": self._macro_description(
                            getattr(row["option"], "text", "")
                        ),
                        "semantic_kind": row["kind"],
                        "consequences": row["consequences"],
                        **row["score_contract"],
                    }
                    for row in candidate_rows
                ],
                chosen_kind=chosen_row["kind"],
                chosen_score=chosen_row["score"],
                candidate_argmax_kind=chosen_row["kind"],
                hard_survival_veto=profile["hard_survival_veto"],
                hard_survival_veto_reason=profile[
                    "hard_survival_veto_reason"
                ],
                decision_model="unified_net_utility_v2",
                masked_bandits_profile=profile,
            )
            if action is not None:
                return action

        if event_id == "colosseum" and len(valid_options) >= 2:
            readiness = self._optional_event_fight_profile()
            cower = next(
                (
                    option for option in valid_options
                    if option_is_leave(option)
                ),
                by_index.get(0),
            )
            fight = next(
                (
                    option for option in valid_options
                    if option_has(
                        option, "fight", "combat", "battle", "challenge"
                    )
                ),
                by_index.get(1),
            )
            hp = max(0, int(getattr(self.game, "current_hp", 0) or 0))
            strength = max(
                0.0,
                float(readiness["capacity"]),
            )
            expected_loss = max(
                6.0,
                46.0
                - 34.0 * strength
                - min(8.0, float(readiness.get("potions", 0)) * 2.0),
            )
            # The same elite-level encounter must not become "safe" merely
            # because it was entered from an event. Reuse the map planner's
            # conservative survival budget, separately from expected attrition.
            elite_survival_loss = self._estimated_elite_survival_cost()
            upper_loss = max(
                expected_loss * (1.45 - 0.20 * strength),
                elite_survival_loss,
            )
            death_risk = max(
                0.0,
                min(1.0, (upper_loss - hp) / max(8.0, upper_loss)),
            )
            emergency_out = bool(
                any(
                    self._token(getattr(potion, "potion_id", ""))
                    in {
                        "fairypotion", "fairyinabottle", "ghostinajar",
                        "smokebomb",
                    }
                    for potion in self.game.get_real_potions()
                )
                or self._has_active_lizard_tail()
            )
            hard_veto = bool(death_risk >= 1.0 - 1e-9 and not emergency_out)
            fight_score = (
                -1000.0
                if hard_veto
                else 38.0
                - expected_loss * (0.75 + max(0.0, 0.70 - hp_ratio))
                - 180.0 * death_risk
            )
            action = choose_scored_event(
                [
                    {
                        "kind": "cower",
                        "option": cower,
                        "score": 1.0,
                        "tie_priority": 1.0,
                        "consequences": {"leave": True},
                    },
                    {
                        "kind": "fight",
                        "option": fight,
                        "score": fight_score,
                        "consequences": {
                            "combat_delta": 1,
                            "reward_value": 38.0,
                            "expected_hp_loss": round(
                                expected_loss, 3
                            ),
                            "death_risk": round(death_risk, 4),
                        },
                    },
                ] if cower is not None and fight is not None else [],
                "colosseum_reward_vs_combat_readiness",
                combat_readiness=readiness,
                expected_hp_loss=round(expected_loss, 3),
                upper_hp_loss=round(upper_loss, 3),
                elite_survival_hp_loss=round(elite_survival_loss, 3),
                death_risk=round(death_risk, 4),
                hard_survival_veto=hard_veto,
            )
            if action is not None:
                return action

        if event_id == "livingwall" and len(valid_options) == 3:
            by_original_index = {
                int(getattr(option, "original_button_index", -1)): option
                for option in valid_options
                if type(getattr(option, "original_button_index", None)) is int
            }
            if set(by_original_index) == {0, 1, 2}:
                best_removal = max(
                    (float(self._removal_score(card)) for card in self.game.deck),
                    default=-1000.0,
                )
                best_upgrade = max(
                    (
                        float(self._upgrade_score(card))
                        for card in self.game.deck
                        if float(self._upgrade_score(card)) > -900.0
                    ),
                    default=-1000.0,
                )
                transform_value = best_removal / 7.0 + 4.0
                values = {0: best_removal, 1: transform_value, 2: best_upgrade}
                operations = {0: "remove", 1: "transform", 2: "upgrade"}
                rows = []
                for index in (0, 1, 2):
                    operation = operations[index]
                    rows.append({
                        "kind": f"living_wall_{operation}",
                        "option": by_original_index[index],
                        "score": values[index],
                        "consequences": {
                            "operation": operation,
                            "future_costs": _indexed_event_grid_effect(
                                "livingwall", operation, 1
                            ),
                        },
                        **self._linear_score_contract(
                            f"living_wall_{operation}_deck_value_v1",
                            {"deck_value": values[index]},
                            (("deck_value", "deck_value", 1.0),),
                        ),
                    })
                action = choose_scored_event(
                    rows,
                    "living_wall_deck_specific_operation_value",
                    best_removal_value=round(best_removal, 3),
                    transform_value=round(transform_value, 3),
                    best_upgrade_value=round(best_upgrade, 3),
                )
                if action is not None:
                    original = next(
                        index for index, option in by_original_index.items()
                        if option.choice_index == action.choice_index
                    )
                    operation = operations[original]
                    if operation == "upgrade":
                        bind_positive_grid("living_wall")
                    else:
                        bind_destructive_grid("living_wall", operation, 1)
                    return action

        if event_id == "goldenwing" and len(valid_options) == 3:
            by_original_index = {
                int(getattr(option, "original_button_index", -1)): option
                for option in valid_options
                if type(getattr(option, "original_button_index", None)) is int
            }
            if set(by_original_index) == {0, 1, 2}:
                best_removal = max(
                    (float(self._removal_score(card)) for card in self.game.deck),
                    default=-1000.0,
                )
                pray_score = best_removal - 7.0 * 2.25
                destroy_score = 65.0 * 0.12
                current_hp = max(0, int(getattr(self.game, "current_hp", 0) or 0))
                pray_eligible = current_hp > 7
                pray_future = _indexed_event_grid_effect(
                    "goldenwing", "remove", 1, dialog_steps=1
                )
                rows = [
                    {
                        "kind": "golden_wing_pray_remove",
                        "option": by_original_index[0],
                        "score": pray_score,
                        "selection_eligible": pray_eligible,
                        "veto_reason": None if pray_eligible else "lethal_hp_cost",
                        "consequences": {
                            "operation": "golden_wing_pray_remove",
                            "hp_delta": -7,
                            "future_costs": pray_future,
                        },
                        **self._linear_score_contract(
                            "golden_wing_pray_deck_value_v1",
                            {"removal_value": best_removal, "hp_cost": 7.0},
                            (
                                ("removal_value", "removal_value", 1.0),
                                ("hp_cost", "hp_cost", -2.25),
                            ),
                        ),
                    },
                    {
                        "kind": "golden_wing_destroy_for_gold",
                        "option": by_original_index[1],
                        "score": destroy_score,
                        "consequences": {
                            "operation": "golden_wing_destroy_for_gold",
                        },
                        **self._linear_score_contract(
                            "golden_wing_expected_gold_value_v1",
                            {"expected_gold": 65.0},
                            (("gold_value", "expected_gold", 0.12),),
                        ),
                    },
                    {
                        "kind": "golden_wing_leave",
                        "option": by_original_index[2],
                        "score": 1.0,
                        "tie_priority": 1.0,
                        "consequences": {
                            "operation": "golden_wing_leave", "leave": True,
                        },
                        **self._linear_score_contract(
                            "golden_wing_leave_v1",
                            {"leave_value": 1.0},
                            (("leave_value", "leave_value", 1.0),),
                        ),
                    },
                ]
                action = choose_scored_event(
                    rows,
                    "golden_wing_deck_value_vs_hp_and_gold",
                    best_removal_value=round(best_removal, 3),
                    expected_destroy_gold=65.0,
                )
                if (
                    action is not None
                    and action.choice_index == by_original_index[0].choice_index
                ):
                    bind_destructive_grid("golden_wing", "remove", 1)
                if action is not None:
                    return action

        if event_id == "drugdealer" and len(valid_options) == 3:
            # Base-game Augmenter/Drug Dealer uses stable original button
            # identities: J.A.X., transform two cards, Mutagenic Strength.
            # Localized labels previously collapsed the latter two into the
            # same generic score and described the transform as a card gain.
            # Require the complete initial surface before using these exact
            # mechanics so later dialogue or modded lookalikes fail closed.
            by_original_index = {
                int(getattr(option, "original_button_index", -1)): option
                for option in valid_options
                if type(getattr(option, "original_button_index", None)) is int
            }
            if set(by_original_index) == {0, 1, 2}:
                jax = spirecomm.spire.card.Card(
                    "J.A.X.", "J.A.X.",
                    spirecomm.spire.card.CardType.SKILL,
                    spirecomm.spire.card.CardRarity.SPECIAL,
                    cost=0,
                )
                jax_value = float(self._card_reward_score(jax))
                max_hp_loss = min(3, max(0, int(self.game.max_hp) - 1))
                jax_score = jax_value - max_hp_loss * 2.25

                removal_scores = sorted(
                    (
                        float(self._removal_score(card))
                        for card in self.game.deck
                    ),
                    reverse=True,
                )
                transform_inputs = removal_scores[:2]
                transform_score = (
                    sum(transform_inputs) / 7.0 + 8.0
                    if len(transform_inputs) == 2 else -1000.0
                )

                mutagenic = SimpleNamespace(
                    relic_id="MutagenicStrength",
                    name="Mutagenic Strength",
                )
                relic_score = float(
                    self._relic_acquisition_score(mutagenic)
                )
                rows = [
                    {
                        "kind": "take_jax",
                        "option": by_original_index[0],
                        "score": jax_score,
                        "consequences": {
                            "operation": "drug_dealer_take_jax",
                            "max_hp_delta": -max_hp_loss,
                            "card_id": "J.A.X.",
                        },
                        **self._linear_score_contract(
                            "drug_dealer_jax_net_value_v1",
                            {
                                "jax_value": jax_value,
                                "max_hp_loss": float(max_hp_loss),
                            },
                            (
                                ("jax_value", "jax_value", 1.0),
                                ("max_hp_cost", "max_hp_loss", -2.25),
                            ),
                        ),
                    },
                    {
                        "kind": "transform_two",
                        "option": by_original_index[1],
                        "score": transform_score,
                        "consequences": {
                            "operation": "drug_dealer_transform_two",
                            "future_costs": _indexed_event_grid_effect(
                                "drugdealer", "transform", 2
                            ),
                        },
                        **self._linear_score_contract(
                            "drug_dealer_transform_two_value_v1",
                            {
                                "removal_value_sum": sum(transform_inputs),
                                "base_transform_value": 8.0,
                            },
                            (
                                (
                                    "removal_value_share",
                                    "removal_value_sum",
                                    1.0 / 7.0,
                                ),
                                (
                                    "base_transform_value",
                                    "base_transform_value",
                                    1.0,
                                ),
                            ),
                        ),
                    },
                    {
                        "kind": "take_mutagenic_strength",
                        "option": by_original_index[2],
                        "score": relic_score,
                        "consequences": {
                            "operation": (
                                "drug_dealer_take_mutagenic_strength"
                            ),
                            "relic_id": "MutagenicStrength",
                        },
                        **self._linear_score_contract(
                            "drug_dealer_mutagenic_relic_value_v1",
                            {"relic_value": relic_score},
                            (("relic_value", "relic_value", 1.0),),
                        ),
                    },
                ]
                action = choose_scored_event(
                    rows,
                    "drug_dealer_exact_outcome_value",
                    jax_value=round(jax_value, 3),
                    max_hp_loss=max_hp_loss,
                    transform_removal_values=[
                        round(value, 3) for value in transform_inputs
                    ],
                    mutagenic_strength_value=round(relic_score, 3),
                )
                if action is not None:
                    if (
                        action.choice_index
                        == by_original_index[1].choice_index
                    ):
                        bind_destructive_grid(
                            "drug_dealer", "transform", 2
                        )
                    return action

        if event_id == "duplicator":
            pray = next(
                (
                    option for option in valid_options
                    if option_has(
                        option, "pray", "duplicate", "copy", "祈祷", "复制"
                    )
                ),
                by_index.get(0),
            )
            if pray is not None and option_is_leave(pray):
                pray = None
            best_copy_value = max(
                (
                    float(self._card_reward_score(card))
                    for card in self.game.deck
                ),
                default=-1000.0,
            )
            rows = []
            for option in valid_options:
                if pray is not None and option.choice_index == pray.choice_index:
                    rows.append({
                        "kind": "duplicate_card",
                        "option": option,
                        "score": best_copy_value,
                        "consequences": self._event_option_consequences(
                            option
                        ),
                    })
                else:
                    rows.append({
                        "kind": "leave",
                        "option": option,
                        "score": 1.0,
                        "tie_priority": 1.0,
                        "consequences": self._event_option_consequences(
                            option
                        ),
                    })
            action = choose_scored_event(
                rows,
                "duplicator_take_free_contextual_copy",
                best_copy_value=round(best_copy_value, 3),
            )
            if action is not None:
                if (
                    pray is not None
                    and action.choice_index == pray.choice_index
                ):
                    bind_positive_grid("duplicator")
                return action

        if event_id == "thelibrary":
            read = next(
                (
                    option for option in valid_options
                    if option_has(option, "read", "book", "阅读", "读书")
                ),
                by_index.get(0),
            )
            sleep = next(
                (
                    option for option in valid_options
                    if option_has(
                        option, "sleep", "rest", "heal", "睡觉", "休息"
                    )
                ),
                by_index.get(1),
            )
            if read is not None and option_is_leave(read):
                read = None
            if sleep is not None and option_is_leave(sleep):
                sleep = None
            max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
            current_hp = max(
                0, int(getattr(self.game, "current_hp", 0) or 0)
            )
            actual_heal = min(
                max_hp - current_hp,
                (max_hp * 33 + 50) // 100,
            )
            if self._has_relic("Mark of the Bloom"):
                actual_heal = 0
            read_value = 14.0 + max(
                0.0,
                0.65
                - float(
                    (self._deck_readiness() or {}).get("score", 0.0)
                    or 0.0
                ),
            ) * 12.0
            sleep_value = actual_heal * (
                0.70 + max(0.0, 0.72 - hp_ratio)
            )
            rows = []
            for option in valid_options:
                if read is not None and option.choice_index == read.choice_index:
                    rows.append({
                        "kind": "read",
                        "option": option,
                        "score": read_value,
                        "consequences": {
                            "operation": "library_prepare_card_choice",
                            "hp_delta": 0,
                            "max_hp_delta": 0,
                            "gold_delta": 0,
                            "card_changes": {
                                "gain": [], "remove": [],
                                "upgrade": [], "transform": [],
                            },
                            "relic_changes": {
                                "gain": [], "remove": [], "counter": [],
                            },
                            "potion_changes": {
                                "gain": [], "remove": [], "replace": [],
                            },
                            "current_cost": {
                                "gold": 0, "hp": 0, "max_hp": 0,
                            },
                            "probabilistic_outcomes": [],
                            "future_costs": [{
                                "kind": "event_grid_selection",
                                "event_id": "The Library",
                                "domain": "library_card_offering",
                                "operation": "gain",
                                "visible_count": 20,
                                "select_count": 1,
                                "selection_mode": "player_choice",
                            }],
                        },
                    })
                elif sleep is not None and option.choice_index == sleep.choice_index:
                    rows.append({
                        "kind": "sleep",
                        "option": option,
                        "score": sleep_value,
                        "consequences": {
                            "operation": "library_sleep",
                            "event_outcome_id": "sleep",
                            "hp_delta": actual_heal,
                            "leave": True,
                        },
                    })
                else:
                    rows.append({
                        "kind": "other",
                        "option": option,
                        "score": -2.0,
                        "consequences": (
                            {
                                "operation": "thelibrary_dialog_advance_noop",
                                "event_outcome_id": "leave",
                                "hp_delta": 0,
                                "max_hp_delta": 0,
                                "gold_delta": 0,
                                "leave": True,
                            }
                            if option_is_leave(option)
                            else {"exact_outcome_unknown": True}
                        ),
                    })
            action = choose_scored_event(
                rows,
                "library_card_value_vs_recovery",
                read_value=round(read_value, 3),
                sleep_value=round(sleep_value, 3),
            )
            if action is not None:
                if (
                    read is not None
                    and action.choice_index == read.choice_index
                ):
                    bind_positive_grid("thelibrary")
                return action
        semantic_scores = [
            (
                self._generic_event_option_score(
                    option, hp_ratio, include_components=True
                ),
                option,
            )
            for option in valid_options
        ]
        (best_score, best_signals, best_components), chosen = max(
            semantic_scores,
            key=lambda item: (
                item[0][0],
                self._token(
                    f"{getattr(item[1], 'label', '')} {getattr(item[1], 'text', '')}"
                ),
            ),
        )
        event_by_id = {
            f"event:{option.choice_index}": option
            for _, option in semantic_scores
        }
        rule_id = f"event:{chosen.choice_index}"
        selected_id = self._macro_rank(
            "EVENT",
            [
                {
                    "candidate_id": f"event:{option.choice_index}",
                    "kind": "event_option",
                    "label": getattr(option, "label", None),
                    "local_score": result[0],
                    "facts": {
                        "choice_index": option.choice_index,
                        "text": str(getattr(option, "text", "") or "")[:500],
                        "semantic_signals": result[1],
                        "consequences": {
                            **self._event_option_consequences(option),
                            **({
                                "score_components": {
                                    "deck_operation_evaluation": (
                                        self._event_deck_operation_values_for_option(
                                            option
                                        )
                                    ),
                                },
                            } if set(result[1]) & {
                                "remove", "upgrade", "transform",
                            } else {}),
                        },
                    },
                }
                for result, option in semantic_scores
                if result[0] > -900
            ],
            rule_id,
            hard_constraints=[
                "KNOWN_EVENTS_ALREADY_HANDLED_DETERMINISTICALLY",
                "DISABLED_AND_LETHAL_OPTIONS_EXCLUDED",
                "ONLY_VISIBLE_OPTION_TEXT_IS_AUTHORITATIVE",
            ],
            state_details={
                "event_id": getattr(self.game.screen, "event_id", None),
                "event_name": getattr(self.game.screen, "event_name", None),
            },
        )[0]
        chosen = event_by_id[selected_id]
        best_score, best_signals, best_components = next(
            result
            for result, option in semantic_scores
            if option is chosen
        )
        action = choose_index(
            chosen.choice_index,
            "event_semantic_outcome_score",
            [
                {
                    "id": option.choice_index,
                    "score": float(result[0]),
                    "label": getattr(option, "label", None),
                    "text": self._macro_description(
                        getattr(option, "text", "")
                    ),
                    "semantic_signals": list(result[1]),
                    "consequences": {
                        **self._event_option_consequences(option),
                        **({
                            "score_components": {
                                "deck_operation_evaluation": (
                                    self._event_deck_operation_values_for_option(
                                        option
                                    )
                                ),
                            },
                        } if set(result[1]) & {
                            "remove", "upgrade", "transform",
                        } else {}),
                    },
                    **self._linear_score_contract(
                        "event_semantic_component_utility_v1",
                        dict(result[2]),
                        tuple(
                            (name, name, 1.0)
                            for name, _value in result[2]
                        ),
                    ),
                }
                for result, option in semantic_scores
            ],
            optional_fight_risk=self._generic_optional_fight_risk(),
            chosen_score=round(best_score, 3),
            chosen_signals=best_signals,
            option_semantics={
                str(option.choice_index): result[1]
                for result, option in semantic_scores
            },
        )
        return action or ProceedAction()

    def _is_match_game_event(self):
        event_id = self._token(getattr(self.game.screen, "event_id", ""))
        return event_id in {"matchandkeep", "gremlinmatchgame", "matchgame"} or (
            "match" in event_id and ("keep" in event_id or "gremlin" in event_id)
        )

    def _reset_match_game(self):
        self.match_game_first_choice = None
        self.match_game_first_label = None
        self.match_game_waiting_for_resolution = False
        self.match_game_last_signature = None
        self.match_game_last_action_index = None

    @staticmethod
    def _match_game_label_is_curse(card_label):
        """Whether a revealed Match and Keep label is a curse card."""

        token = "".join(
            char.lower() for char in str(card_label or "") if char.isalnum()
        )
        return token in {
            "ascendersbane", "clumsy", "curseofthebell", "decay",
            "doubt", "injury", "necronomicurse", "normality", "pain",
            "parasite", "pride", "regret", "shame", "writhe",
        }

    def choose_match_game_action(self, valid_options):
        """Explore unknown cards, remember revealed IDs, and take known pairs."""

        if not valid_options:
            self._reset_match_game()
            return ProceedAction()

        ordered_options = sorted(
            valid_options,
            key=lambda option: (
                int(option.choice_index),
                self._token(
                    getattr(option, "label", "")
                    or getattr(option, "text", "")
                ),
            ),
        )

        def label(option):
            return self._token(
                getattr(option, "label", "")
                or getattr(option, "text", "")
            )

        def unknown(option):
            value = label(option)
            return value.startswith("card") and value[4:].isdigit()

        signature = tuple(
            (
                option.choice_index,
                label(option),
            )
            for option in ordered_options
        )

        def choose_and_record(selected, reason, stage):
            """Bind every visible board position before issuing one flip."""

            selected_index = int(selected.choice_index)
            known_counts = {}
            for item in ordered_options:
                item_label = label(item)
                if not unknown(item) and not self._match_game_label_is_curse(
                    item_label
                ):
                    known_counts[item_label] = known_counts.get(
                        item_label, 0
                    ) + 1
            has_safe_candidate = any(
                unknown(item)
                or not self._match_game_label_is_curse(label(item))
                for item in ordered_options
            )
            rows = []
            for item in ordered_options:
                item_label = label(item)
                is_unknown = unknown(item)
                is_curse = (
                    not is_unknown
                    and self._match_game_label_is_curse(item_label)
                )
                selection_eligible = not (is_curse and has_safe_candidate)
                veto_reason = (
                    "known_curse_card"
                    if not selection_eligible else None
                )
                if is_curse:
                    local_score = -100.0
                elif (
                    self.match_game_first_label
                    and not is_unknown
                    and item_label == self.match_game_first_label
                ):
                    local_score = 90.0
                elif known_counts.get(item_label, 0) >= 2:
                    local_score = 80.0
                elif is_unknown:
                    local_score = 40.0
                else:
                    local_score = 20.0
                # Resolve equal semantic categories with the stable protocol
                # position, never with candidate container order or a
                # post-selection score rewrite.
                local_score -= int(item.choice_index) * 0.001
                score_category = (
                    "known_curse" if is_curse
                    else "remembered_mate"
                    if (
                        self.match_game_first_label
                        and not is_unknown
                        and item_label == self.match_game_first_label
                    )
                    else "known_pair"
                    if known_counts.get(item_label, 0) >= 2
                    else "unknown_position" if is_unknown
                    else "known_single"
                )
                category_inputs = {
                    name: int(name == score_category)
                    for name in (
                        "known_curse", "remembered_mate", "known_pair",
                        "unknown_position", "known_single",
                    )
                }
                category_inputs["choice_index"] = int(item.choice_index)
                rows.append({
                    "id": f"match:{int(item.choice_index)}",
                    "choice_id": f"match:{int(item.choice_index)}",
                    "choice_index": int(item.choice_index),
                    "action": "choose",
                    "semantic_id": (
                        f"match-position:{int(item.choice_index)}"
                    ),
                    "score": local_score,
                    "label": getattr(item, "label", None),
                    "text": self._macro_description(
                        getattr(item, "text", "")
                    ),
                    "legal": True,
                    "visible": True,
                    "selection_eligible": selection_eligible,
                    "veto_reason": veto_reason,
                    "reason": (
                        reason
                        if int(item.choice_index) == selected_index
                        else veto_reason or "visible_unchosen_position"
                    ),
                    "consequences": {
                        "operation": "flip_match_position",
                        "match_stage": stage,
                        "revealed_label": (
                            None if is_unknown else item_label
                        ),
                        "unknown_card": bool(is_unknown),
                        "known_pair_count": int(
                            known_counts.get(item_label, 0)
                        ),
                        "known_curse": bool(is_curse),
                        "card_gain_requires_successful_pair": True,
                    },
                    "uncertainty": (
                        "hidden card identity is not protocol-visible"
                        if is_unknown else None
                    ),
                    **self._linear_score_contract(
                        "match_board_semantic_priority_v1",
                        category_inputs,
                        (
                            ("known_curse", "known_curse", -100.0),
                            ("remembered_mate", "remembered_mate", 90.0),
                            ("known_pair", "known_pair", 80.0),
                            ("unknown_position", "unknown_position", 40.0),
                            ("known_single", "known_single", 20.0),
                            ("stable_position_tiebreak", "choice_index", -0.001),
                        ),
                    ),
                })
            self._record_noncombat_decision(
                reason,
                rows,
                candidate_contract={
                    "score_source": "match_board_semantic_priority",
                    "strategy_quality_auditable": True,
                    "all_visible_options_scored": True,
                    "visible_option_count": len(ordered_options),
                    "identity_source": "protocol_choice_index",
                },
                event_id=self._token(
                    getattr(
                        getattr(getattr(self, "game", None), "screen", None),
                        "event_id",
                        "",
                    )
                ),
                chosen_id=f"match:{selected_index}",
                chosen_index=selected_index,
                match_stage=stage,
            )
            return ChooseAction(selected_index)

        if (
            signature == self.match_game_last_signature
            and self.match_game_last_action_index is not None
        ):
            # Idempotent protocol retry: the same authoritative frame must
            # produce the same flip, not advance local memory or wait forever.
            selected = next(
                (
                    item for item in ordered_options
                    if int(item.choice_index)
                    == int(self.match_game_last_action_index)
                ),
                None,
            )
            if selected is not None:
                return choose_and_record(
                    selected, "match_game_idempotent_retry", "retry"
                )

        # A second flip needs one authoritative update before another pair is
        # attempted. Otherwise a third click can arrive during the previous
        # pair's resolution animation.
        if self.match_game_waiting_for_resolution:
            self._reset_match_game()
            return None

        by_index = {
            option.choice_index: option for option in ordered_options
        }

        if self.match_game_first_choice is not None:
            remembered_label = self.match_game_first_label or ""
            remembered_is_known = not (
                remembered_label.startswith("card")
                and remembered_label[4:].isdigit()
            )
            if remembered_label and remembered_is_known:
                # The face-up first card is omitted from choice_list. Its
                # known mate can compact into the exact numeric index we just
                # clicked, so that index must not be excluded here.
                second = next(
                    (
                        option for option in ordered_options
                        if not unknown(option)
                        and label(option) == remembered_label
                        and not self._match_game_label_is_curse(
                            remembered_label
                        )
                    ),
                    None,
                )
                if second is not None:
                    self.match_game_waiting_for_resolution = True
                    self.match_game_last_signature = signature
                    self.match_game_last_action_index = second.choice_index
                    return choose_and_record(
                        second, "match_game_known_mate", "second_flip"
                    )
            first = by_index.get(self.match_game_first_choice)
            if first is None:
                self.match_game_first_choice = None
            elif unknown(first) and label(first) == self.match_game_first_label:
                # The first flip has not been serialized yet. Wait instead of
                # clicking the same hidden card or guessing a second one.
                return None
            elif unknown(first):
                # Match and Keep temporarily removes the face-up card from
                # choice_list, compacting every later choice index.  A new
                # ``cardN`` at the old index is a different card, not proof
                # that the first click is still pending.
                first = next(
                    (
                        option for option in ordered_options
                        if label(option) == self.match_game_first_label
                    ),
                    None,
                )
                if first is None:
                    second = next(
                        (option for option in ordered_options if unknown(option)),
                        ordered_options[0] if ordered_options else None,
                    )
                    if second is None:
                        self._reset_match_game()
                        return ProceedAction()
                    self.match_game_waiting_for_resolution = True
                    self.match_game_last_signature = signature
                    self.match_game_last_action_index = second.choice_index
                    return choose_and_record(
                        second, "match_game_compacted_unknown", "second_flip"
                    )
            else:
                first_label = label(first)
                known_match = next(
                    (
                        option for option in ordered_options
                        if option.choice_index != first.choice_index
                        and not unknown(option)
                        and label(option) == first_label
                        and not self._match_game_label_is_curse(first_label)
                    ),
                    None,
                )
                second = known_match or next(
                    (
                        option for option in ordered_options
                        if option.choice_index != first.choice_index and unknown(option)
                    ),
                    None,
                )
                if second is None:
                    second = next(
                        (option for option in ordered_options if option.choice_index != first.choice_index),
                        None,
                    )
                if second is None:
                    self._reset_match_game()
                    return ProceedAction()
                self.match_game_waiting_for_resolution = True
                self.match_game_last_signature = signature
                self.match_game_last_action_index = second.choice_index
                return choose_and_record(
                    second,
                    (
                        "match_game_known_mate"
                        if known_match is not None
                        else "match_game_explore_second"
                    ),
                    "second_flip",
                )

        known_by_card = {}
        for option in ordered_options:
            if (
                not unknown(option)
                and not self._match_game_label_is_curse(label(option))
            ):
                known_by_card.setdefault(label(option), []).append(option)
        known_pair = next((
            sorted(known_by_card[card_label], key=lambda item: item.choice_index)
            for card_label in sorted(known_by_card)
            if len(known_by_card[card_label]) >= 2
        ), None)
        if known_pair:
            first = known_pair[0]
        else:
            first = next(
                (option for option in ordered_options if unknown(option)),
                ordered_options[0],
            )
        self.match_game_first_choice = first.choice_index
        self.match_game_first_label = label(first)
        self.match_game_last_signature = signature
        self.match_game_last_action_index = first.choice_index
        return choose_and_record(
            first,
            (
                "match_game_known_pair_first"
                if known_pair else "match_game_explore_unknown"
            ),
            "first_flip",
        )

    def _upgrade_score_parts(self, card):
        card_id = self._token(card.card_id)
        if int(getattr(card, "upgrades", 0) or 0) > 0:
            return {"already_upgraded": -1000.0}
        common_values = {
            "apotheosis": 24, "adrenaline": 18, "offering": 18,
            "neutralize": 11, "survivor": 7,
        }
        class_values = {
            PlayerClass.THE_SILENT: {
                "wraithformv2": 24, "catalyst": 20, "bladedance": 15,
                "footwork": 15, "noxiousfumes": 12, "backstab": 10,
                "piercingwail": 10, "deflect": 9, "backflip": 8,
                "deadlypoison": 8, "corpseexplosion": 7,
            },
            PlayerClass.IRONCLAD: {
                "limitbreak": 22, "corruption": 18, "demonform": 16,
                "immolate": 14, "bash": 12, "uppercut": 12,
                "shockwave": 12, "truesgrit": 10, "truegrit": 10,
                "shrugitoff": 8, "pommelstrike": 8,
            },
            PlayerClass.DEFECT: {
                "defragment": 22, "fission": 20, "biasedcognition": 18,
                "buffer": 16, "electrodynamics": 14, "glacier": 13,
                "zap": 12, "dualcast": 12, "coolheaded": 9,
                "loop": 9, "capacitor": 8,
            },
        }
        if card_id in common_values:
            static_prior = float(common_values[card_id])
        elif card_id in class_values.get(self.chosen_class, {}):
            static_prior = float(
                class_values[self.chosen_class][card_id]
            )
        elif card_id.startswith("defend"):
            static_prior = 4.0
        elif card_id.startswith("strike"):
            static_prior = 2.0
        else:
            static_prior = float({
                spirecomm.spire.card.CardType.POWER: 8,
                spirecomm.spire.card.CardType.SKILL: 7,
                spirecomm.spire.card.CardType.ATTACK: 6,
            }.get(card.type, 1))
            rank = self.priorities.CARD_PRIORITIES.get(card.card_id)
            skip_rank = self.priorities.CARD_PRIORITIES.get("Skip", 0)
            if rank is not None:
                static_prior += max(0, skip_rank - rank) * 0.06

        profile = self._deck_profile()
        tags = self._card_build_tags(card)
        boss_matchup_context = 0.0
        if (
            int(getattr(self.game, "act", 0) or 0) == 1
            and self._boss_id() == "slimeboss"
        ):
            if "aoe" in tags:
                boss_matchup_context += 4.0
            if card_id == "whirlwind":
                # Its +3 damage is paid once per energy and then again across
                # both post-split targets, so the generic AOE tie-breaker
                # understates the marginal upgrade in this exact matchup.
                boss_matchup_context += 2.0
            elif card_id == "evolve":
                boss_matchup_context += 4.0
        # Two-card unit-test and partial-preview decks do not contain enough
        # evidence to declare an engine unsupported.  Real runs begin above
        # this floor; retain the bounded card prior until role counts are
        # representative.
        if int(profile.get("size", 0) or 0) < 5:
            return {
                "bounded_static_upgrade_prior": static_prior,
                "deck_role_demand": 0.0,
                "deck_plan_support": 0.0,
                "engine_support": 0.0,
                "boss_matchup_context": boss_matchup_context,
            }
        armaments_handwide_upgrade_value = 0.0
        if card_id == "armaments":
            deck = list(getattr(self.game, "deck", []) or [])
            other_cards = [
                deck_card for deck_card in deck if deck_card is not card
            ]
            other_upgradable = sum(
                1
                for deck_card in other_cards
                if int(getattr(deck_card, "upgrades", 0) or 0) == 0
                and getattr(deck_card, "rarity", None)
                != spirecomm.spire.card.CardRarity.CURSE
                and getattr(deck_card, "type", None)
                not in {
                    spirecomm.spire.card.CardType.CURSE,
                    spirecomm.spire.card.CardType.STATUS,
                }
            )
            # Armaments+ upgrades every other card currently in hand.  Model
            # the expected four companion cards in a normal five-card draw,
            # scaled by the fraction of the deck that still benefits.  This
            # naturally decays after permanent upgrades accumulate.
            expected_targets = (
                min(4.0, float(len(other_cards)))
                * float(other_upgradable)
                / max(1.0, float(len(other_cards)))
            )
            armaments_handwide_upgrade_value = min(
                8.0, expected_targets * 2.0
            )
        demand = self._deck_demand_vector(profile)
        role_demand = 0.0
        role_demand += demand["frontload"] * 5.0 * int("damage" in tags)
        role_demand += demand["block"] * 7.0 * int("block" in tags)
        role_demand += demand["draw"] * 6.0 * int("draw" in tags)
        role_demand += demand["aoe"] * 5.0 * int("aoe" in tags)
        role_demand += demand["scaling"] * 6.0 * int("scaling" in tags)
        role_demand += demand["energy"] * 5.0 * int("energy" in tags)
        # Starter upgrades are small, but a scarce role can still make one the
        # best available fire.  Use the same cross-character role ledger as
        # removal instead of always ranking Defend=4 and Strike=2.
        starter_context = self._starter_removal_context()
        balance = float(starter_context["role_balance_adjustment"])
        if card_id.startswith("defend"):
            role_demand += max(0.0, balance) * 0.30
        elif card_id.startswith("strike"):
            role_demand += max(0.0, -balance) * 0.30

        # Deck demand describes the value of adding a new role source.  An
        # upgrade only improves an existing source, so applying the whole
        # gap here double-counts the base card and can make a starter Defend
        # look better than a run-defining upgrade.  Keep role context as a
        # bounded tie-breaker proportional to the upgrade's marginal prior.
        role_demand = min(
            role_demand * 0.25,
            max(2.0, static_prior * 0.50),
        )

        plan_adjustment = max(
            -5.0,
            min(6.0, self._deck_plan_adjustment(card, profile) * 0.30),
        )
        support_adjustment = 0.0
        archetypes = profile.get("archetypes") or {}
        if self.chosen_class == PlayerClass.THE_SILENT:
            poison_support = self._archetype_source_support(
                archetypes.get("poison", {})
            )
            shiv_support = self._archetype_source_support(
                archetypes.get("shiv", {})
            )
            discard_support = self._archetype_source_support(
                archetypes.get("discard", {})
            )
            if card_id == "catalyst" and poison_support < 1.0:
                support_adjustment -= 16.0
            if card_id == "accuracy" and shiv_support < 1.0:
                support_adjustment -= 12.0
            if card_id in {"reflex", "tactician"} and discard_support < 1.0:
                support_adjustment -= 10.0
        elif self.chosen_class == PlayerClass.IRONCLAD:
            strength_support = self._archetype_source_support(
                archetypes.get("strength", {})
            )
            if card_id in {"heavyblade", "limitbreak"}:
                if strength_support < 0.85:
                    support_adjustment -= 16.0
        elif self.chosen_class == PlayerClass.DEFECT:
            orb_support = sum(
                self._archetype_source_support(archetypes.get(name, {}))
                for name in ("frost", "lightning", "dark")
            )
            if card_id in {
                "biasedcognition", "consume", "defragment", "fission",
                "loop",
            } and orb_support < 1.5:
                support_adjustment -= 14.0

        return {
            "bounded_static_upgrade_prior": static_prior,
            "deck_role_demand": round(role_demand, 3),
            "deck_plan_support": round(plan_adjustment, 3),
            "engine_support": round(support_adjustment, 3),
            "boss_matchup_context": round(boss_matchup_context, 3),
            "armaments_handwide_upgrade_value": round(
                armaments_handwide_upgrade_value, 3
            ),
        }

    def _upgrade_score(self, card):
        return sum(self._upgrade_score_parts(card).values())

    def _starter_removal_context(self, deck=None):
        """Describe the deck roles that a starter-card purge would disturb.

        A raw ``Strike > Defend`` constant cannot tell whether the deck is
        already short on damage or block, and it is especially misleading for
        Perfected Strike decks.  Keep this context cheap and deterministic so
        GRID candidates can expose the same inputs to the strategy auditor.
        """

        cards = list(
            deck if deck is not None else getattr(self.game, "deck", []) or []
        )
        attack_sources = 0.0
        defense_sources = 0.0
        for deck_card in cards:
            deck_card_id = self._token(
                getattr(deck_card, "card_id", "")
            )
            tags = self._card_build_tags(deck_card)
            if getattr(deck_card, "type", None) == spirecomm.spire.card.CardType.ATTACK:
                attack_sources += 1.0
            defense_value = self._card_block_reliability(deck_card)
            # Some noncombat fixtures and older protocol frames omit dynamic
            # block numbers for starter Defends.  Their role is still exact.
            if deck_card_id.startswith("defend"):
                defense_value = max(defense_value, 1.0)
            if "weak" in tags:
                defense_value = max(defense_value, 0.55)
            if "strength_down" in tags:
                defense_value = max(defense_value, 0.75)
            if "intangible" in tags:
                defense_value = max(defense_value, 1.0)
            defense_sources += defense_value
        role_surplus = attack_sources - defense_sources
        return {
            "deck_size": len(cards),
            "attack_sources": round(attack_sources, 3),
            "defense_sources": round(defense_sources, 3),
            "attack_minus_defense": round(role_surplus, 3),
            "role_balance_adjustment": round(
                max(-18.0, min(18.0, role_surplus * 6.0)), 3
            ),
            "starter_strikes": sum(
                self._token(getattr(deck_card, "card_id", "")).startswith(
                    "strike"
                )
                for deck_card in cards
            ),
            "starter_defends": sum(
                self._token(getattr(deck_card, "card_id", "")).startswith(
                    "defend"
                )
                for deck_card in cards
            ),
            "perfected_strikes": sum(
                self._token(getattr(deck_card, "card_id", ""))
                == "perfectedstrike"
                for deck_card in cards
            ),
            "strike_dummy": self._has_relic("Strike Dummy"),
        }

    def _bite_sustain_value(self, deck=None, *, added_bites=0):
        """Bounded healing access shared by acquiring and removing Bites."""
        cards = list(deck if deck is not None else self.game.deck)
        if self._has_relic("Mark of the Bloom"):
            return 0.0
        bites = [c for c in cards if self._token(c.card_id) == "bite"]
        healing = sum(3 if int(getattr(c, "upgrades", 0) or 0) else 2 for c in bites)
        healing += max(0, added_bites) * 2
        # Five draws per turn, a three-turn access window; extra copies
        # saturate rather than acquiring an automatic duplicate penalty.
        exposure = min(1.0, 15.0 / max(1, len(cards) + added_bites))
        missing = max(0, self.game.max_hp - self.game.current_hp)
        need = 0.5 + min(0.5, missing / max(1, self.game.max_hp))
        if self._has_relic("Coffee Dripper"):
            need = 1.0
        return min(14.0, healing * exposure * need * 2.5)

    def _removal_score_parts(self, card, deck=None):
        card_id = self._token(card.card_id)
        # Coffee Dripper removes campfire recovery; preserve the established
        # conservative protection for its repeatable healing package.
        if card_id == "bite" and self._has_relic("Coffee Dripper"):
            return {"protected_coffee_dripper_bite": -1000.0}
        if card_id in {"apparition", "ghostly"}:
            cards = list(
                deck
                if deck is not None
                else getattr(self.game, "deck", []) or []
            )
            copies = sum(
                self._token(getattr(deck_card, "card_id", ""))
                in {"apparition", "ghostly"}
                for deck_card in cards
            )
            profile = self._deck_profile(cards)
            readiness = self._deck_readiness(profile)
            block_coverage = max(
                0.0,
                min(
                    1.0,
                    float(
                        (readiness.get("coverage") or {}).get("block", 0.0)
                        or 0.0
                    ),
                ),
            )
            upgraded = int(getattr(card, "upgrades", 0) or 0) > 0
            return {
                "apparition_card_base": 24.0,
                "ethereal_timing_liability": 0.0 if upgraded else 8.0,
                "saturated_package_copy": max(0, copies - 3) * 7.0,
                "intangible_retention_value": (
                    -18.0 * (1.0 - 0.45 * block_coverage)
                ),
                "minimum_package_protection": -8.0 if copies <= 3 else 0.0,
                "upgrade_protection": -16.0 if upgraded else 0.0,
            }
        if card.rarity == spirecomm.spire.card.CardRarity.CURSE:
            curse_values = {
                "normality": 130, "pain": 125, "regret": 120,
                "doubt": 112, "shame": 110, "decay": 108,
                "injury": 100, "clumsy": 92,
            }
            return {"curse_removal_value": curse_values.get(card_id, 105)}
        context = self._starter_removal_context(deck)
        upgrade_protection = -12.0 * int(
            getattr(card, "upgrades", 0) or 0
        )
        if card_id.startswith("strike"):
            return {
                "starter_strike_base": 70.0,
                "attack_defense_balance": context[
                    "role_balance_adjustment"
                ],
                "perfected_strike_dependency": (
                    -6.0 * context["perfected_strikes"]
                ),
                "strike_dummy_dependency": (
                    -10.0 if context["strike_dummy"] else 0.0
                ),
                "upgrade_protection": upgrade_protection,
            }
        if card_id.startswith("defend"):
            return {
                "starter_defend_base": 44.0,
                "attack_defense_balance": -context[
                    "role_balance_adjustment"
                ],
                "excess_starter_defends": max(
                    0, context["starter_defends"] - 4
                ) * 8.0,
                "upgrade_protection": upgrade_protection,
            }
        cards = list(
            deck if deck is not None else getattr(self.game, "deck", []) or []
        )
        copies = sum(
            getattr(deck_card, "card_id", None) == getattr(card, "card_id", None)
            for deck_card in cards
        )
        limit = self.priorities.MAX_COPIES.get(card.card_id, 1)
        duplicate_penalty = max(0, copies - limit) * 22
        if card_id == "bite":
            remaining = self._deck_without_exact_card(cards, card)
            lost_sustain = max(
                0.0, self._bite_sustain_value(cards) - self._bite_sustain_value(remaining),
            )
            return {
                "ordinary_card_base": 8.0,
                "excess_copy_value": max(0, copies - 2) * 6.0,
                "lost_sustain_value": -4.0 * lost_sustain,
                "upgrade_protection": upgrade_protection,
            }
        rank = self.priorities.CARD_PRIORITIES.get(card.card_id, len(self.priorities.CARD_PRIORITIES) + 30)
        parts = {
            "ordinary_card_base": 8.0,
            "priority_weakness": rank * 0.08,
            "excess_copy_value": duplicate_penalty,
            "upgrade_protection": upgrade_protection,
        }
        if (
            self.chosen_class == PlayerClass.DEFECT
            and card_id == "reprogram"
        ):
            parts["defect_orb_engine_conflict"] = float(
                self._defect_reprogram_conflict_profile(cards)[
                    "conflict_penalty"
                ]
            )
        return parts

    def _removal_score(self, card, deck=None):
        return sum(self._removal_score_parts(card, deck).values())

    @staticmethod
    def _deck_without_exact_card(deck, selected):
        remaining = list(deck)
        selected_uuid = getattr(selected, "uuid", None)
        for index, deck_card in enumerate(remaining):
            if deck_card is selected or (
                selected_uuid
                and getattr(deck_card, "uuid", None) == selected_uuid
            ):
                del remaining[index]
                return remaining
        for index, deck_card in enumerate(remaining):
            if getattr(deck_card, "card_id", None) == getattr(
                selected, "card_id", None
            ):
                del remaining[index]
                break
        return remaining

    def _transform_score_parts(self, card, deck=None):
        # Transforming a curse draws another curse, not a normal card.
        # There is no net curse removal or guaranteed upgrade to credit.
        if (
            getattr(card, "type", None) == spirecomm.spire.card.CardType.CURSE
            or getattr(card, "rarity", None) == spirecomm.spire.card.CardRarity.CURSE
        ):
            return {"retained_random_curse_pool": -10.0}
        return self._removal_score_parts(card, deck)

    def _removal_batch_plan(self, cards, count, *, for_transform=False):
        """Rank coupled multi-card removals against the evolving deck.

        Transform-two and remove-two grids are one decision.  Scoring every
        copy against the original deck made two identical Strikes win even
        after the first removal had changed both role balance and Perfected
        Strike support.  Evaluate the order-dependent joint value and expose a
        per-instance best-batch inclusion value for ordinary top-N auditing.
        """

        score_parts = (
            self._transform_score_parts if for_transform
            else self._removal_score_parts
        )
        def score_card(card, deck):
            return (
                sum(score_parts(card, deck).values()) if for_transform
                else self._removal_score(card, deck)
            )

        cards = list(cards)
        count = max(0, min(int(count or 0), len(cards)))
        base_deck = list(getattr(self.game, "deck", []) or [])
        if count <= 0:
            return {
                "cards": [], "batch_value": 0.0,
                "inclusion_scores": {}, "steps": [],
            }

        def ordered_value(order):
            remaining = list(base_deck)
            total = 0.0
            steps = []
            for selected in order:
                context = self._starter_removal_context(remaining)
                parts = score_parts(selected, remaining)
                marginal = float(sum(parts.values()))
                total += marginal
                steps.append({
                    "card_id": getattr(selected, "card_id", None),
                    "card_uuid": getattr(selected, "uuid", None),
                    "marginal_value": round(marginal, 3),
                    "role_context": context,
                    "score_parts": {
                        key: round(float(value), 3)
                        for key, value in parts.items()
                    },
                })
                remaining = self._deck_without_exact_card(
                    remaining, selected
                )
            return total, steps

        candidates = []
        if count <= 3 and len(cards) <= 30:
            for batch in combinations(cards, count):
                best_order = None
                best_value = -math.inf
                best_steps = []
                for order in permutations(batch):
                    value, steps = ordered_value(order)
                    if value > best_value + 1e-9:
                        best_order = order
                        best_value = value
                        best_steps = steps
                candidates.append((best_value, best_order, best_steps))
        else:
            remaining_cards = list(cards)
            remaining_deck = list(base_deck)
            chosen = []
            steps = []
            total = 0.0
            while remaining_cards and len(chosen) < count:
                selected = max(
                    remaining_cards,
                    key=lambda candidate: score_card(
                        candidate, remaining_deck
                    ),
                )
                parts = score_parts(selected, remaining_deck)
                marginal = float(sum(parts.values()))
                total += marginal
                steps.append({
                    "card_id": getattr(selected, "card_id", None),
                    "card_uuid": getattr(selected, "uuid", None),
                    "marginal_value": round(marginal, 3),
                    "role_context": self._starter_removal_context(
                        remaining_deck
                    ),
                    "score_parts": {
                        key: round(float(value), 3)
                        for key, value in parts.items()
                    },
                })
                chosen.append(selected)
                remaining_cards.remove(selected)
                remaining_deck = self._deck_without_exact_card(
                    remaining_deck, selected
                )
            candidates.append((total, tuple(chosen), steps))

        best_value, best_order, best_steps = max(
            candidates, key=lambda row: row[0]
        )
        inclusion_scores = {}
        for card in cards:
            values = [
                value for value, order, _ in candidates if card in order
            ]
            inclusion_scores[id(card)] = (
                max(values) if values else score_card(card, base_deck)
            )
        return {
            "cards": list(best_order),
            "batch_value": round(float(best_value), 3),
            "inclusion_scores": inclusion_scores,
            "steps": best_steps,
        }

    def _bottled_lightning_opening_score_parts(self, card):
        """Value guaranteeing one eligible Skill in every opening hand.

        This is intentionally not ``_card_reward_score``.  A bottle GRID
        contains cards already present in the deck, so acquisition scoring
        applies duplicate and deck-size penalties to the very card being
        selected.  Opening value instead rewards deterministic setup,
        multi-enemy mitigation and immediate cycling while retaining a
        bounded static card prior.
        """

        rank = self.priorities.CARD_PRIORITIES.get(card.card_id)
        skip_rank = self.priorities.CARD_PRIORITIES.get("Skip", 0)
        static_priority = (
            -18.0
            if rank is None
            else max(-18.0, min(28.0, float(skip_rank - rank) * 0.38))
        )
        upgrade_value = int(getattr(card, "upgrades", 0) or 0) * 4.0

        card_id = self._token(getattr(card, "card_id", ""))
        tags = self._card_build_tags(card)
        tactical_value = 0.0
        duration = max(
            0, min(6, int(getattr(card, "magic_number", 0) or 0))
        )
        if "weak" in tags:
            tactical_value += 8.0 + duration
        if "vulnerable" in tags:
            tactical_value += 5.0 + min(5, duration)
            if self._has_relic("Champion Belt"):
                tactical_value += 6.0
        if card_id in FastCombatPlanner.AOE_WEAK_CARDS:
            tactical_value += 8.0
        if "strength_down" in tags:
            tactical_value += 12.0
        if "intangible" in tags:
            tactical_value += 20.0

        draw = max(
            0, int(FastCombatPlanner.DRAW_COUNTS.get(card_id, 0) or 0)
        )
        tactical_value += min(10.0, draw * 4.0)
        tactical_value += min(
            7.0,
            self._card_number(card, "block", "base_block") * 0.55,
        )
        cost = self._card_cost(card)
        if cost >= 2:
            tactical_value -= (cost - 1) * 3.0

        profile = self._deck_profile()
        demand = self._deck_demand_vector(profile)
        role_demand = 0.0
        role_demand += demand["block"] * 9.0 * int("block" in tags)
        role_demand += demand["draw"] * 8.0 * int("draw" in tags)
        role_demand += demand["energy"] * 6.0 * int("energy" in tags)
        role_demand += demand["aoe"] * 5.0 * int("aoe" in tags)
        role_demand += demand["scaling"] * 5.0 * int("scaling" in tags)
        role_demand += demand["frontload"] * 3.0 * int("damage" in tags)
        plan_support = max(
            -5.0,
            min(7.0, self._deck_plan_adjustment(card, profile) * 0.35),
        )
        engine_support = float(
            self._upgrade_score_parts(card).get("engine_support", 0.0)
        )
        boss_context = 0.0
        boss_id = self._boss_id()
        if boss_id == "slimeboss" and "aoe" in tags:
            boss_context += 6.0
        if boss_id in {"hexaghost", "champ", "timeeater"} and (
            "scaling" in tags or "strength_down" in tags
        ):
            boss_context += 5.0
        redundant_innate = (
            -100.0 if bool(getattr(card, "is_innate", False)) else 0.0
        )
        return {
            "bounded_static_priority": round(static_priority, 3),
            "upgrade_value": round(upgrade_value, 3),
            "opening_tactical_value": round(tactical_value, 3),
            "deck_role_demand": round(role_demand, 3),
            "deck_plan_support": round(plan_support, 3),
            "engine_support": round(engine_support, 3),
            "boss_context": round(boss_context, 3),
            "redundant_innate": redundant_innate,
        }

    def _bottled_lightning_opening_score(self, card):
        return sum(self._bottled_lightning_opening_score_parts(card).values())

    def choose_grid_action(self):
        cards = list(self.game.screen.cards)
        if not cards:
            return ProceedAction()
        parent_choice_context = getattr(
            self.game.screen, "parent_choice_context", None
        )
        parent_choice_context = (
            parent_choice_context
            if isinstance(parent_choice_context, dict) else {}
        )
        parent_operation = parent_choice_context.get("operation")
        parent_grid_operation = (
            parent_operation
            if parent_choice_context.get("authority")
            == "accepted_protocol_choice"
            and (
                parent_choice_context.get("parent_phase") == "NEOW"
                and parent_operation in {"upgrade", "transform", "remove"}
                or parent_choice_context.get("parent_phase") == "EVENT"
                and (
                    parent_operation == "duplicate"
                    or (
                        parent_operation == "note_exchange"
                        and self._token(
                            parent_choice_context.get("event_id")
                        ) == "noteforyourself"
                        and parent_choice_context.get("original_button_index")
                        == 0
                        and parent_choice_context.get("select_count") == 1
                        and isinstance(
                            parent_choice_context.get("offered_card"), dict
                        )
                    )
                    or (
                        parent_operation == "transform"
                        and self._token(
                            parent_choice_context.get("event_id")
                        ) == "drugdealer"
                        and parent_choice_context.get("original_button_index")
                        == 1
                        and parent_choice_context.get("select_count") == 2
                    )
                    or (
                        parent_operation == "gain"
                        and self._token(
                            parent_choice_context.get("event_id")
                        ) == "thelibrary"
                        and parent_choice_context.get("original_button_index")
                        == 0
                        and parent_choice_context.get("select_count") == 1
                        and parent_choice_context.get("selection_domain")
                        == "library_card_offering"
                    )
                )
                or parent_choice_context.get("parent_phase")
                == "COMBAT_REWARD"
                and parent_operation in {
                    "bottle_attack", "bottle_skill", "bottle_power",
                }
                or parent_choice_context.get("parent_phase")
                == "BOSS_REWARD"
                and parent_operation == "transform"
            )
            else None
        )
        action_id = self._token(getattr(self.game, "current_action", ""))
        selection_context = self.pending_selection_context or {}
        destructive_grid_context = bool(
            selection_context.get("kind") == "destructive_card"
            and selection_context.get("act") == int(self.game.act)
            and selection_context.get("floor") == int(self.game.floor)
            and selection_context.get("operation")
            in {"remove", "transform"}
        )
        destructive_grid_operation = (
            selection_context.get("operation")
            if destructive_grid_context else None
        )
        expected_count = parent_choice_context.get("select_count")
        if type(expected_count) is not int or expected_count < 1:
            expected_count = (
                selection_context.get("select_count")
                if destructive_grid_context else None
            )
        if type(expected_count) is not int or expected_count < 1:
            expected_count = int(self.game.screen.num_cards or 1)
        num_cards = min(expected_count, len(cards))
        liquid_memories_context = bool(
            selection_context.get("kind") == "liquid_memories"
            and selection_context.get("act") == int(self.game.act)
            and selection_context.get("floor") == int(self.game.floor)
            and selection_context.get("turn") == int(self.game.turn)
        )
        positive_grid_context = bool(
            selection_context.get("kind") == "positive_card"
            and selection_context.get("act") == int(self.game.act)
            and selection_context.get("floor") == int(self.game.floor)
        )
        bottled_relic_binding = bool(
            selection_context.get("kind") == "positive_card"
            and selection_context.get("source") in {
                "bottled_flame", "bottled_lightning", "bottled_tornado",
            }
            and selection_context.get("operation") in {
                "bottle_attack", "bottle_skill", "bottle_power",
            }
            and selection_context.get("expected_card_type")
            in {"ATTACK", "SKILL", "POWER"}
            and type(selection_context.get("relic_count_before")) is int
        )
        bottled_relic_pending = bool(
            bottled_relic_binding and positive_grid_context
        )
        bottled_relic_pending_context = bool(
            bottled_relic_pending
            and self._relic_count(selection_context.get("source"))
            > selection_context["relic_count_before"]
            and int(getattr(self.game.screen, "num_cards", 0) or 0) == 1
            and not self.game.screen.for_upgrade
            and not self.game.screen.for_transform
            and not self.game.screen.for_purge
            and all(
                getattr(getattr(card, "type", None), "name", None)
                == selection_context.get("expected_card_type")
                for card in cards
            )
        )
        parent_bottle_type = {
            "bottle_attack": "ATTACK",
            "bottle_skill": "SKILL",
            "bottle_power": "POWER",
        }.get(parent_grid_operation)
        bottled_relic_parent_context = bool(
            parent_bottle_type is not None
            and parent_choice_context.get("card_type") == parent_bottle_type
            and int(getattr(self.game.screen, "num_cards", 0) or 0) == 1
            and not self.game.screen.for_upgrade
            and not self.game.screen.for_transform
            and not self.game.screen.for_purge
            and all(
                getattr(getattr(card, "type", None), "name", None)
                == parent_bottle_type
                for card in cards
            )
        )
        bottled_relic_context = bool(
            bottled_relic_pending_context or bottled_relic_parent_context
        )
        bottle_operation = (
            parent_grid_operation
            if bottled_relic_parent_context
            else selection_context.get("operation")
            if bottled_relic_pending_context
            else None
        )
        if bottled_relic_binding and not bottled_relic_context:
            # A rejected/stale relic click must not turn a later unrelated
            # GRID into a positive selection merely because it shares the
            # same floor.  Fail closed when the exact one-Skill bottle
            # surface is absent.
            self.pending_selection_context = None
            selection_context = {}
            positive_grid_context = False
        destructive_action = any(
            marker in action_id
            for marker in {"bonfire", "falling", "purge", "remove", "transform"}
        )
        removal_scoring = False
        transform_scoring = False
        removal_batch_plan = None
        positive_selection = any(
            marker in action_id
            for marker in {
                "bottle",
                "dolly",
                "duplicate",
                "duplicator",
                "mirror",
            }
        )
        # Headbutt and equivalent effects expose this exact grid action after
        # the card has already resolved.  The selected discard is placed on
        # top of the draw pile, so treating the surface as an unknown
        # sacrifice chooses the weakest card and wastes the deterministic
        # recovery opportunity.
        discard_to_top_selection = "discardpiletotopofdeck" in action_id
        # Hologram/Seek expose a Grid after the producer card resolves.  These
        # surfaces add the selected card to the live hand and therefore need
        # current-turn tactical utility, not permanent-deck removal value.
        discard_to_hand_selection = "discardpiletohand" in action_id
        draw_to_hand_selection = (
            "drawpiletohand" in action_id
            or "skillfromdecktohand" in action_id
        )
        tactical_hand_retrieval = bool(
            discard_to_hand_selection or draw_to_hand_selection
        )
        if (
            liquid_memories_context
            or "liquidmemories" in action_id
            or tactical_hand_retrieval
        ):
            def retrieval_score(card):
                if tactical_hand_retrieval:
                    return self.combat_planner.score_retrieval_card(
                        self.game, card
                    )
                return self.combat_planner.score_temporary_card(
                    self.game, card
                )

            wanted_uuid = selection_context.get("card_uuid")
            wanted_id = selection_context.get("card_id")
            exact = next(
                (
                    card
                    for card in cards
                    if wanted_uuid
                    and getattr(card, "uuid", None) == wanted_uuid
                ),
                None,
            )
            if exact is None and wanted_id:
                exact = next(
                    (
                        card
                        for card in cards
                        if getattr(card, "card_id", None) == wanted_id
                    ),
                    None,
                )
            scored = [
                (
                    retrieval_score(card)
                    + (10000.0 if exact is card else 0.0),
                    card,
                )
                for card in cards
            ]
            reason = (
                "grid_liquid_memories_bound_marginal_plan"
                if exact is not None
                else "grid_combat_discard_to_hand_tactical_value"
                if discard_to_hand_selection
                else "grid_combat_draw_to_hand_tactical_value"
                if draw_to_hand_selection
                else "grid_liquid_memories_tactical_fallback"
            )
        elif self.game.screen.for_upgrade or parent_grid_operation == "upgrade":
            scored = [(self._upgrade_score(card), card) for card in cards]
            reason = "grid_upgrade_marginal_value"
        elif (
            self.game.screen.for_purge
            or self.game.screen.for_transform
            or parent_grid_operation in {
                "remove", "transform", "note_exchange",
            }
            or destructive_grid_operation in {"remove", "transform"}
            or destructive_action
        ):
            transform_scoring = bool(
                self.game.screen.for_transform
                or parent_grid_operation == "transform"
                or destructive_grid_operation == "transform"
            )
            scored = [
                (
                    sum(self._transform_score_parts(card).values())
                    if transform_scoring else self._removal_score(card),
                    card,
                )
                for card in cards
            ]
            removal_scoring = True
            reason = "grid_remove_or_transform_weakest"
        elif bottled_relic_context:
            scored = [
                (self._bottled_lightning_opening_score(card), card)
                for card in cards
            ]
            reason = (
                "grid_bottled_lightning_opening_value"
                if (
                    parent_grid_operation == "bottle_skill"
                    or selection_context.get("operation") == "bottle_skill"
                )
                else "grid_bottled_relic_opening_value"
            )
        elif (
            self.choose_good_card
            or positive_selection
            or positive_grid_context
            or parent_grid_operation == "duplicate"
            or discard_to_top_selection
        ):
            # Bottled relics and other non-destructive grid choices want the
            # strongest contextual card.  Treating every non-upgrade grid as
            # a purge silently bottled the worst eligible card.
            scored = [(self._card_reward_score(card), card) for card in cards]
            reason = (
                "grid_discard_to_top_of_deck_tactical_value"
                if discard_to_top_selection
                else "grid_positive_event_card_value"
                if positive_grid_context
                else "grid_positive_selection_context_value"
            )
        else:
            # Unknown event grids are more often sacrifices/removals than
            # rewards.  Conservatively protect the run-defining card until a
            # structured action or relic identifies a positive selection.
            scored = [(self._removal_score(card), card) for card in cards]
            removal_scoring = True
            reason = "grid_unknown_conservative_weak_card"
        if removal_scoring and num_cards > 1:
            removal_batch_plan = self._removal_batch_plan(
                cards, num_cards, for_transform=transform_scoring
            )
            scored = [
                (
                    removal_batch_plan["inclusion_scores"][id(card)],
                    card,
                )
                for card in cards
            ]
        # A Vampires trade is a package transaction, not five independent
        # duplicate-card removals.  Coffee Dripper removes the only normal
        # campfire-heal outlet, so Bites are the compensation for the max-HP
        # payment and must stay ahead of any ordinary purge candidate.  Keep
        # this guard at the final scoring boundary as well as in
        # ``_removal_score``: producer/retry paths can supply their own score
        # list and previously bypassed that helper entirely.
        if (
            reason in {
                "grid_remove_or_transform_weakest",
                "grid_unknown_conservative_weak_card",
            }
            and self._has_relic("Coffee Dripper")
            and any(self._token(getattr(card, "card_id", "")) != "bite" for card in cards)
        ):
            scored = [
                (
                    -1000000.0
                    if self._token(getattr(card, "card_id", "")) == "bite"
                    else score,
                    card,
                )
                for score, card in scored
            ]
            reason = "grid_remove_or_transform_protect_vampires_bites"
        bound_uuids = list(selection_context.get("card_uuids") or [])
        if not bound_uuids and selection_context.get("card_uuid"):
            bound_uuids = [selection_context.get("card_uuid")]
        if (liquid_memories_context or positive_grid_context) and bound_uuids:
            bound_rank = {
                card_uuid: len(bound_uuids) - index
                for index, card_uuid in enumerate(bound_uuids)
            }
            scored = [
                (
                    score + 10000.0 * bound_rank.get(
                        getattr(card, "uuid", None), 0
                    ),
                    card,
                )
                for score, card in scored
            ]
        locally_ranked = sorted(
            scored, key=lambda item: item[0], reverse=True
        )
        chosen = (
            list(removal_batch_plan["cards"])
            if removal_batch_plan is not None
            else [card for _, card in locally_ranked[:num_cards]]
        )
        macro_grid = bool(
            not getattr(self.game, "in_combat", False)
            and not liquid_memories_context
            and not bound_uuids
            and (
                self.game.screen.for_upgrade
                or self.game.screen.for_purge
                or self.game.screen.for_transform
                or destructive_action
                or positive_selection
                or self.choose_good_card
                or parent_grid_operation is not None
                or destructive_grid_operation is not None
            )
        )
        if macro_grid:
            grid_by_id = {}
            macro_candidates = []
            for index, (score, card) in enumerate(scored):
                candidate_id = f"grid:{getattr(card, 'uuid', '') or index}"
                grid_by_id[candidate_id] = card
                card_facts = self._macro_card_facts(card)
                if (
                    self.game.screen.for_upgrade
                    or parent_grid_operation == "upgrade"
                ):
                    card_facts["selection_effect"] = {
                        "operation": "upgrade_this_exact_card",
                        "value_semantics": (
                            "prefer marginal upgrade gain, not base card value"
                        ),
                        "upgrade_delta_signal": round(float(score), 3),
                        "evaluation": {
                            key: round(float(value), 3)
                            for key, value in self._upgrade_score_parts(
                                card
                            ).items()
                        },
                    }
                elif (
                    self.game.screen.for_purge
                    or self.game.screen.for_transform
                    or parent_grid_operation in {
                        "remove", "transform", "note_exchange",
                    }
                    or destructive_grid_operation in {"remove", "transform"}
                    or destructive_action
                ):
                    card_facts["selection_effect"] = {
                        "operation": "remove_or_transform_this_exact_card",
                        "value_semantics": (
                            "higher removal value means more desirable to remove"
                        ),
                        "removal_value": round(float(score), 3),
                    }
                else:
                    card_facts["selection_effect"] = {
                        "operation": "keep_copy_or_bottle_this_exact_card",
                        "value_semantics": (
                            "prefer the highest future keep value"
                        ),
                    }
                macro_candidates.append({
                    "candidate_id": candidate_id,
                    "kind": "permanent_card_selection",
                    "label": getattr(card, "name", None),
                    "local_score": score,
                    "facts": card_facts,
                })
            rule_ids = [
                next(
                    candidate_id
                    for candidate_id, candidate in grid_by_id.items()
                    if candidate is card
                )
                for card in chosen
            ]
            selected_ids = self._macro_rank(
                "GRID",
                macro_candidates,
                rule_ids,
                count=num_cards,
                hard_constraints=[
                    "ONLY_EXACT_CARD_INSTANCES",
                    "COMBAT_AND_BOUND_MULTI_STEP_SELECTIONS_EXCLUDED",
                    "SELECTION_COUNT_MUST_NOT_CHANGE",
                ],
                state_details={
                    "selection_action": action_id,
                    "selection_semantics": reason,
                    "selection_count": num_cards,
                },
            )
            chosen = [grid_by_id[candidate_id] for candidate_id in selected_ids]
        if (
            liquid_memories_context
            or positive_grid_context
            or destructive_grid_context
        ):
            chosen_uuids = [
                getattr(card, "uuid", None)
                for card in chosen
                if getattr(card, "uuid", None)
            ]
            if not bound_uuids and chosen_uuids:
                selection_context["card_uuid"] = chosen_uuids[0]
                selection_context["card_uuids"] = chosen_uuids
                selection_context["confirmed_card_uuids"] = []
        grid_audit_candidates = []
        for choice_index, (score, card) in enumerate(scored):
            card_uuid = getattr(card, "uuid", None)
            choice_id = f"grid:{card_uuid or choice_index}"
            if self.game.screen.for_upgrade or parent_grid_operation == "upgrade":
                operation = "grid_upgrade"
            elif (
                self.game.screen.for_transform
                or parent_grid_operation == "transform"
                or destructive_grid_operation == "transform"
            ):
                operation = "grid_transform"
            elif (
                self.game.screen.for_purge
                or parent_grid_operation == "remove"
                or destructive_grid_operation == "remove"
            ):
                operation = "grid_purge"
            elif parent_grid_operation == "duplicate":
                operation = "grid_duplicate"
            elif parent_grid_operation == "gain":
                operation = "grid_gain"
            elif parent_grid_operation == "note_exchange":
                operation = "grid_note_exchange"
            elif bottled_relic_context:
                operation = f"grid_{bottle_operation}"
            elif (
                liquid_memories_context
                or "liquidmemories" in action_id
                or discard_to_hand_selection
                or draw_to_hand_selection
            ):
                operation = "grid_combat_discard_to_hand"
                if draw_to_hand_selection:
                    operation = "grid_combat_draw_to_hand"
            elif discard_to_top_selection:
                operation = "grid_combat_discard_to_top"
            else:
                operation = "select_this_exact_card"
            selected_card = self._audit_card_instance_facts(card)
            random_effects = None
            if operation == "grid_transform":
                random_effects = [{
                    "kind": "grid_transform_result",
                    "domain": "game_card_transform_pool",
                    "count": 1,
                    "timing": "after_grid_confirmation",
                    "selection_mode": "random",
                }]
                # The accepted parent operation proves Astrolabe's automatic
                # upgrade. Owning the relic does not upgrade unrelated later
                # transforms, and the replacement card identity stays random.
                if (
                    parent_choice_context.get("authority") == "accepted_protocol_choice"
                    and parent_choice_context.get("parent_phase") == "BOSS_REWARD"
                    and self._token(parent_choice_context.get("relic_id")) == "astrolabe"
                    and parent_choice_context.get("operation") == "transform"
                    and parent_choice_context.get("select_count") == 3
                ):
                    random_effects[0]["result_upgrades"] = 1
            consequences = {
                "operation": operation,
                "selected_card": selected_card,
                "hp_delta": 0,
                "max_hp_delta": 0,
                "gold_delta": 0,
                "card_changes": {
                    "gain": [], "remove": [],
                    "upgrade": [], "transform": [],
                },
                "relic_changes": {
                    "gain": [], "remove": [], "counter": [],
                },
                "potion_changes": {
                    "gain": [], "remove": [], "replace": [],
                },
                "current_cost": {"gold": 0, "hp": 0, "max_hp": 0},
                "probabilistic_outcomes": [],
                "future_costs": ([{
                    "kind": "grid_confirmation_effect",
                    "operation": operation,
                    "selected_card": selected_card,
                    "commit_timing": "after_grid_confirmation",
                }] if operation in {
                    "grid_upgrade", "grid_transform", "grid_purge",
                    "grid_duplicate", "grid_note_exchange",
                    "grid_bottle_attack",
                    "grid_bottle_skill", "grid_bottle_power",
                    "grid_combat_discard_to_hand",
                    "grid_combat_draw_to_hand",
                    "grid_combat_discard_to_top",
                } else []),
            }
            if operation == "grid_gain":
                consequences["card_changes"]["gain"] = [selected_card]
            if random_effects is not None:
                consequences["random_effects"] = random_effects
            if operation == "grid_upgrade":
                consequences.setdefault("score_components", {})[
                    "upgrade_evaluation"
                ] = {
                    "score_parts": {
                        key: round(float(value), 3)
                        for key, value in self._upgrade_score_parts(
                            card
                        ).items()
                    },
                    "marginal_value": round(float(score), 3),
                }
            if bottled_relic_context:
                consequences.setdefault("score_components", {})[
                    "bottled_opening_evaluation"
                ] = {
                    "score_parts": {
                        key: round(float(value), 3)
                        for key, value in (
                            self._bottled_lightning_opening_score_parts(
                                card
                            ).items()
                        )
                    },
                    "opening_value": round(float(score), 3),
                }
            if removal_scoring:
                removal_parts = (
                    self._transform_score_parts(card) if transform_scoring
                    else self._removal_score_parts(card)
                )
                consequences.setdefault("score_components", {})[
                    "removal_evaluation"
                ] = {
                    "role_context": self._starter_removal_context(),
                    "score_parts": {
                        key: round(float(value), 3)
                        for key, value in removal_parts.items()
                    },
                    "initial_marginal_value": round(
                        float(sum(removal_parts.values())), 3
                    ),
                    "batch_inclusion_value": round(float(score), 3),
                    "selection_count": num_cards,
                }
            grid_audit_candidates.append({
                "id": getattr(card, "card_id", choice_id),
                "choice_id": choice_id,
                "choice_index": choice_index,
                "action": "choose",
                "semantic_id": choice_id,
                "score": score,
                "label": getattr(card, "name", None),
                "legal": True,
                "visible": True,
                "selection_eligible": True,
                "reason": (
                    "selected_exact_card_instance"
                    if card in chosen else "visible_unchosen_card_instance"
                ),
                "consequences": consequences,
                **self._linear_score_contract(
                    (
                        "grid_stateful_removal_batch_inclusion_v1"
                        if removal_batch_plan is not None
                        else "grid_exact_instance_marginal_utility_v1"
                    ),
                    {
                        (
                            "batch_inclusion_utility"
                            if removal_batch_plan is not None
                            else "marginal_utility"
                        ): score
                    },
                    ((
                        (
                            "batch_inclusion_utility"
                            if removal_batch_plan is not None
                            else "marginal_utility"
                        ),
                        (
                            "batch_inclusion_utility"
                            if removal_batch_plan is not None
                            else "marginal_utility"
                        ),
                        1.0,
                    ),),
                ),
            })
        visible_grid_ids = {
            id(card): f"grid:{getattr(card, 'uuid', None) or index}"
            for index, card in enumerate(cards)
        }
        chosen_choice_ids = [visible_grid_ids[id(card)] for card in chosen]
        self._record_noncombat_decision(
            reason,
            grid_audit_candidates,
            candidate_contract={
                    "score_source": (
                    "bottled_relic_opening_utility"
                    if bottled_relic_context
                    else "grid_stateful_removal_batch_inclusion_utility"
                    if removal_batch_plan is not None
                    else "grid_exact_instance_local_utility"
                ),
                "strategy_quality_auditable": all(
                    getattr(card, "uuid", None) for card in cards
                ),
                "all_visible_options_scored": True,
                "visible_option_count": len(cards),
                "identity_source": "card_instance_uuid",
                "incomplete_reason": (
                    None
                    if all(getattr(card, "uuid", None) for card in cards)
                    else "protocol_card_instance_uuid_missing"
                ),
            },
            chosen=[card.card_id for card in chosen],
            chosen_ids=chosen_choice_ids,
            selection_context=(
                {
                    key: value
                    for key, value in selection_context.items()
                    if key != "analysis"
                }
                if (
                    liquid_memories_context
                    or positive_grid_context
                    or destructive_grid_context
                )
                else None
            ),
            removal_batch=(
                {
                    "selection_count": num_cards,
                    "batch_value": removal_batch_plan["batch_value"],
                    "chosen_card_ids": [
                        getattr(card, "card_id", None)
                        for card in removal_batch_plan["cards"]
                    ],
                    "chosen_card_uuids": [
                        getattr(card, "uuid", None)
                        for card in removal_batch_plan["cards"]
                    ],
                    "steps": removal_batch_plan["steps"],
                }
                if removal_batch_plan is not None
                else None
            ),
        )
        return CardSelectAction(chosen)

    def _hand_card_keep_score_parts(self, card):
        """Estimate the value of keeping a card through a hand selection.

        Hand-select is shared by opposite effects (discard/exhaust versus
        retain/seek). This score is stateful so defense remains valuable under
        attack, but excess basic Defends are recognized as Pyramid clog once
        the current attack is covered.
        """

        card_type = getattr(card, "type", None)
        rarity = getattr(card, "rarity", None)
        if (
            card_type == spirecomm.spire.card.CardType.CURSE
            or rarity == spirecomm.spire.card.CardRarity.CURSE
        ):
            return {"curse_penalty": -80.0}
        if card_type == spirecomm.spire.card.CardType.STATUS:
            return {"status_penalty": -60.0}

        rank = self.priorities.CARD_PRIORITIES.get(getattr(card, "card_id", ""))
        parts = {
            "bounded_priority": (
                0.0 if rank is None else max(-5.0, 11.0 - rank * 0.18)
            ),
            "upgrade_bonus": (
                int(getattr(card, "upgrades", 0) or 0) * 2.5
            ),
        }
        cost = int(getattr(card, "cost", 0) or 0)
        if cost == 0:
            parts["energy_cost_adjustment"] = 1.5
        elif cost >= 2:
            parts["energy_cost_adjustment"] = -(cost - 1) * 1.5
        else:
            parts["energy_cost_adjustment"] = 0.0

        damage = max(0, int(getattr(card, "damage", 0) or 0))
        block = max(0, int(getattr(card, "block", 0) or 0))
        magic = max(0, int(getattr(card, "magic_number", 0) or 0))
        if card_type == spirecomm.spire.card.CardType.POWER:
            parts["typed_effect_value"] = 12.0
        elif card_type == spirecomm.spire.card.CardType.ATTACK:
            parts["typed_effect_value"] = damage * 0.65
        elif card_type == spirecomm.spire.card.CardType.SKILL:
            parts["typed_effect_value"] = (
                block * 0.35 + min(4, magic) * 0.3
            )
        else:
            parts["typed_effect_value"] = 0.0

        attack_loss = 0
        if getattr(self.game, "in_combat", False):
            attack_loss = combat_predictor.projected_attack_hp_loss(self.game)
        if block > 0:
            if attack_loss > 0:
                parts["incoming_damage_block_value"] = (
                    min(block, attack_loss) * 1.2
                )
            else:
                parts["incoming_damage_block_value"] = -2.0
        else:
            parts["incoming_damage_block_value"] = 0.0

        card_id = self._token(getattr(card, "card_id", ""))
        parts["pyramid_clog_adjustment"] = 0.0
        if self._has_relic("Runic Pyramid") and card_id.startswith("defend"):
            basic_defends = sum(
                1 for deck_card in getattr(self.game, "deck", []) or []
                if getattr(deck_card, "rarity", None) == spirecomm.spire.card.CardRarity.BASIC
                and self._token(getattr(deck_card, "card_id", "")).startswith("defend")
            )
            parts["pyramid_clog_adjustment"] = -(
                4.0 + max(0, basic_defends - 2) * 1.5
            )
        return parts

    def _hand_card_keep_score(self, card):
        return sum(self._hand_card_keep_score_parts(card).values())

    def _combat_plan_context(self, game=None):
        """Return the short-lived context used to bind a combat card line."""
        game = self.game if game is None else game
        return (
            int(self._combat_epoch),
            int(getattr(game, "act", 0) or 0),
            int(getattr(game, "floor", 0) or 0),
            int(getattr(game, "turn", 0) or 0),
        )

    def _planned_hand_keep_evidence(self, cards):
        """Return a bound, replayable reason to preserve planned hand cards.

        A HAND_SELECT overlay can be raised while the first card of a
        multi-card combat line is resolving (for example True Grit).  The
        following card must not be discarded merely because its standalone
        keep/remove score is lower.  This helper records the *source* planner
        line and its exact combat context; the trace auditor independently
        matches it to the immediately preceding card action before accepting
        the resulting candidate veto.
        """
        if not getattr(self.game, "in_combat", False):
            return None
        decision = self.combat_planner.last_decision or {}
        context = decision.get("_combat_context")
        if context is None:
            return None
        try:
            if tuple(context) != self._combat_plan_context():
                return None
        except (TypeError, ValueError):
            return None
        if (
            not isinstance(context, (list, tuple))
            or len(context) != 4
            or any(type(value) is not int for value in context)
        ):
            return None
        source_sequence = []
        for entry in decision.get("planned_sequence") or []:
            if not isinstance(entry, dict):
                return None
            card_uuid = str(entry.get("card_uuid") or "").strip()
            card_id = str(entry.get("card_id") or "").strip()
            if not card_uuid or not card_id:
                return None
            source_sequence.append({
                "card_instance_id": card_uuid,
                "card_id": card_id,
            })
        if not source_sequence:
            return None
        visible_ids = [
            str(getattr(card, "uuid", "") or "").strip()
            for card in cards
        ]
        if (
            not visible_ids
            or any(not card_uuid for card_uuid in visible_ids)
            or len(set(visible_ids)) != len(visible_ids)
        ):
            return None
        visible = set(visible_ids)
        protected = sorted({
            entry["card_instance_id"]
            for entry in source_sequence
            if entry["card_instance_id"] in visible
        })
        if not protected:
            return None
        return {
            "schema_version": 1,
            "kind": "exact_combat_plan_card_preservation",
            "source_combat_context": list(context),
            "source_planned_sequence": source_sequence,
            "visible_card_instance_ids": sorted(visible),
            "protected_card_instance_ids": protected,
        }

    def _planned_hand_keep_uuids(self, cards):
        """Protect future cards in a multi-step line from discard screens."""
        evidence = self._planned_hand_keep_evidence(cards)
        if not isinstance(evidence, dict):
            return set()
        return set(evidence.get("protected_card_instance_ids") or [])

    def _choose_hand_select_cards(self):
        screen = self.game.screen
        selected = list(getattr(screen, "selected_cards", []) or [])
        remaining = max(0, int(getattr(screen, "num_cards", 0) or 0) - len(selected))
        num_cards = min(remaining, 3, len(getattr(screen, "cards", []) or []))
        if num_cards <= 0:
            return []

        cards = list(screen.cards)
        action = str(getattr(self.game, "current_action", "") or "")
        action_token = self._token(action)
        good_action = (
            action in self.priorities.GOOD_CARD_ACTIONS
            or any(marker in action_token for marker in (
                "retain", "seek", "putondeck", "hologram", "headbutt",
                "secrettechnique", "secretweapon", "exhume",
            ))
        )
        bad_action = (
            action in self.priorities.BAD_CARD_ACTIONS
            or any(marker in action_token for marker in (
                "discard", "exhaust", "putonbottom", "recycle", "gamblingchip",
            ))
        )
        if not good_action and not bad_action:
            self.pending_hand_selection = None
            return self.priorities.get_cards_for_action(action, cards, num_cards)

        hand_score_parts = {
            id(card): self._hand_card_keep_score_parts(card)
            for card in cards
        }
        if "armaments" in action_token:
            for card in cards:
                card_id = self._token(getattr(card, "card_id", ""))
                if card_id in self.INNATE_ONLY_UPGRADE_CARD_IDS:
                    hand_score_parts[id(card)] = {
                        "armaments_combat_upgrade_value": 0.0,
                        "armaments_innate_only_noop_penalty": -100.0,
                    }
                else:
                    hand_score_parts[id(card)] = {
                        "armaments_combat_upgrade_value": max(
                            -1000.0, float(self._upgrade_score(card))
                        ),
                        "armaments_innate_only_noop_penalty": 0.0,
                    }
        mandatory_exhaust = bool(
            bad_action
            and not getattr(screen, "can_pick_zero", False)
            and any(marker in action_token for marker in ("exhaust", "recycle"))
        )
        irreversible_core_uuids = set()
        if mandatory_exhaust:
            scaling_ids = self.SCALING_CARD_IDS.get(self.chosen_class, set())
            deck = list(getattr(self.game, "deck", []) or cards)
            scaling_copy_counts = {
                card_id: sum(
                    1
                    for deck_card in deck
                    if self._token(getattr(deck_card, "card_id", "")) == card_id
                )
                for card_id in scaling_ids
            }
            for card in cards:
                card_id = self._token(getattr(card, "card_id", ""))
                if (
                    card_id not in scaling_ids
                    or scaling_copy_counts.get(card_id, 0) != 1
                ):
                    continue
                card_uuid = str(getattr(card, "uuid", "") or "")
                if not card_uuid:
                    continue
                # Exhaust is permanent for the encounter.  Preserve a unique
                # scaling engine numerically even when every cheap card is in
                # the currently bound play sequence; invalidating that short
                # line is cheaper than deleting the run's long-fight answer.
                hand_score_parts[id(card)][
                    "irreversible_scaling_core_value"
                ] = 40.0
                irreversible_core_uuids.add(card_uuid)
        plan_protection_evidence = self._planned_hand_keep_evidence(cards)
        protected_uuids = {
            str(card_uuid)
            for card_uuid in (
                (plan_protection_evidence or {}).get(
                    "protected_card_instance_ids", []
                )
            )
            if card_uuid
        }
        if "putondeck" in action_token and protected_uuids:
            for card in cards:
                if str(getattr(card, "uuid", "") or "") in protected_uuids:
                    # Warcry-style selections are useful future-card setup but
                    # remove the selected card from the executable current
                    # hand.  Price that exact disruption before applying the
                    # ordinary keep-value sort so a weaker spare card is moved
                    # whenever it preserves the already-bound turn plan.
                    hand_score_parts[id(card)][
                        "bound_plan_disruption_penalty"
                    ] = -1000.0
        scored = [
            (sum(hand_score_parts[id(card)].values()), card)
            for card in cards
        ]
        scored.sort(key=lambda item: item[0], reverse=good_action)
        optional_remove = bool(
            bad_action and getattr(screen, "can_pick_zero", False)
        )
        exact_potion_filter = False
        exact_potion_targets = set()
        exact_potion_redraw = False
        potion_redraw_mode = ""
        potion_decision = {}
        exact_context = None
        protected_veto_uuids = set()
        exhaust_plan_reconsideration = None
        unprotected = []
        if bad_action and not optional_remove and protected_uuids:
            unprotected = [
                item for item in scored
                if str(getattr(item[1], "uuid", "") or "")
                not in protected_uuids
            ]
            expendable_unprotected = [
                item for item in unprotected
                if str(getattr(item[1], "uuid", "") or "")
                not in irreversible_core_uuids
            ]
            preserve_plan = True
            if mandatory_exhaust and expendable_unprotected:
                protected_scores = [
                    score for score, card in scored
                    if str(getattr(card, "uuid", "") or "") in protected_uuids
                ]
                loss = combat_predictor.projected_turn_hp_loss(self.game)
                hp = max(0, int(getattr(self.game.player, "current_hp", 0) or 0))
                source_search = (self.combat_planner.last_decision or {}).get("search") or {}
                # A short plan is not a hard reason to permanently consume a
                # more valuable card. Re-plan after the authoritative exhaust
                # when there is room to survive without its protected line.
                # Keep exact lethal and immediate survival lines protected.
                if (
                    protected_scores
                    and loss < hp
                    and not source_search.get("true_combat_end", False)
                    # No reason to break a line to retain a card whose
                    # standalone keep value is already non-positive.
                    and min(score for score, _ in expendable_unprotected) > 0.0
                    and min(score for score, _ in expendable_unprotected)
                    > min(protected_scores) + 1e-9
                ):
                    preserve_plan = False
                    exhaust_plan_reconsideration = {
                        "reason": "permanent_cost_exceeds_short_plan_preservation",
                        "baseline_projected_hp_loss": loss,
                        "player_hp": hp,
                        "lowest_protected_keep_score": min(protected_scores),
                        "lowest_unprotected_keep_score": min(
                            score for score, _ in expendable_unprotected
                        ),
                        "source_plan": plan_protection_evidence,
                    }
            if len(expendable_unprotected) >= num_cards and preserve_plan:
                # The exact remaining line is available in the immediately
                # preceding combat decision.  Mark these rows ineligible so
                # the audit compares only cards that can be removed without
                # invalidating that line.
                protected_veto_uuids = set(protected_uuids)
        if plan_protection_evidence is not None:
            if protected_veto_uuids:
                plan_protection_evidence = dict(
                    plan_protection_evidence
                )
                plan_protection_evidence[
                    "protected_card_instance_ids"
                ] = sorted(protected_veto_uuids)
            else:
                # Evidence describes an actual eligibility constraint, not
                # merely the existence of a prior plan. When preserving that
                # plan would force the only scaling core to be exhausted, the
                # candidates remain comparable and no veto is asserted.
                plan_protection_evidence = None
        if optional_remove:
            selection_key = (
                int(getattr(self.game, "act", 0) or 0),
                int(getattr(self.game, "floor", 0) or 0),
                int(getattr(self.game, "turn", 0) or 0),
                action,
                int(getattr(screen, "num_cards", 0) or 0),
            )
            context = self.pending_hand_selection or {}
            potion_decision = self.combat_planner.last_decision or {}
            potion_filter_source = potion_decision
            exact_context = potion_filter_source.get(
                "potion_hand_filter_selection_context"
            )
            try:
                exact_context_matches = (
                    tuple(exact_context) == self._combat_plan_context()
                )
            except (TypeError, ValueError):
                exact_context_matches = False
            if not exact_context_matches:
                pending_filter = self.pending_potion_hand_filter
                pending_filter = (
                    pending_filter
                    if isinstance(pending_filter, dict) else {}
                )
                pending_context = pending_filter.get(
                    "potion_hand_filter_selection_context"
                )
                try:
                    pending_context_matches = (
                        tuple(pending_context)
                        == self._combat_plan_context()
                    )
                except (TypeError, ValueError):
                    pending_context_matches = False
                if pending_context_matches:
                    potion_filter_source = pending_filter
                    exact_context = pending_context
                    exact_context_matches = True
            exact_potion_targets = {
                str(card_uuid)
                for card_uuid in potion_filter_source.get(
                    "potion_hand_filter_target_uuids", []
                )
                or []
                if card_uuid
            } if exact_context_matches else set()
            exact_potion_filter = bool(
                exact_potion_targets
                and any(
                    marker in action_token
                    for marker in ("discard", "exhaust", "gamblingchip")
                )
            )
            potion_redraw_mode = str(
                potion_filter_source.get(
                    "potion_hand_filter_draw_mode"
                ) or ""
            ).strip().casefold()
            redraw_gain = potion_filter_source.get(
                "potion_hand_filter_expected_redraw_gain"
            )
            exact_potion_redraw = bool(
                exact_potion_filter
                and potion_redraw_mode in {
                    "known_top", "reshuffle_expectation",
                }
                and isinstance(redraw_gain, (int, float))
                and not isinstance(redraw_gain, bool)
                and float(redraw_gain) > 0.0
            )
            if (
                context.get("selection_key") != selection_key
                or bool(context.get("exact_potion_filter"))
                != exact_potion_filter
            ):
                highest = max((score for score, _ in scored), default=0.0)
                # Gambling effects are optional filters.  Replace basic or
                # otherwise low-value cards while preserving draw, block and
                # setup cards that are materially better than the weakest
                # cards in this exact hand.  The UUID plan is frozen for the
                # whole selection overlay so later frames cannot expand it to
                # every card that remains visible.
                cutoff = min(8.0, highest - 4.0)
                planned = (
                    [
                        getattr(card, "uuid", None)
                        for card in cards
                        if getattr(card, "uuid", None)
                        in exact_potion_targets
                    ]
                    if exact_potion_filter
                    else [
                        getattr(card, "uuid", None)
                        for score, card in scored
                        if score <= cutoff and getattr(card, "uuid", None)
                    ]
                )
                context = {
                    "selection_key": selection_key,
                    "planned_uuids": planned,
                    "exact_potion_filter": exact_potion_filter,
                    # Elixir exhausts cards in place.  Only a replacement
                    # draw (Gambling Chip/Gambler's Brew) justifies adding a
                    # redraw value to the removal candidate score.
                    "redraw_keep_value": (
                        max(0.0, float(cutoff))
                        if not exact_potion_filter or exact_potion_redraw
                        else 0.0
                    ),
                }
                self.pending_hand_selection = context
            planned = set(context.get("planned_uuids") or [])
            optional_redraw_keep_value = float(
                context.get("redraw_keep_value") or 0.0
            )
            planned -= protected_uuids
            chosen = [
                card for _, card in scored
                if getattr(card, "uuid", None) in planned
            ][:3]
        else:
            self.pending_hand_selection = None
            if bad_action and protected_veto_uuids:
                # Preserve the future line whenever enough other cards can
                # satisfy this mandatory selection. If every visible card is
                # protected, use the normal score as the least-bad fallback.
                chosen = [card for _, card in unprotected[:num_cards]]
            elif good_action and getattr(screen, "can_pick_zero", False):
                # Optional retain/seek screens should be compared with their
                # explicit zero-value Proceed action; never retain a card
                # whose standalone value is negative.
                chosen = [
                    card for score, card in scored if score > 0.0
                ][:num_cards]
            else:
                chosen = [card for _, card in scored[:num_cards]]
        selection_semantics = (
            "remove_up_to_count" if optional_remove
            else "keep" if good_action else "remove"
        )
        if protected_veto_uuids:
            plan_protection_evidence = {
                **(plan_protection_evidence or {}),
                "selection_action": action,
                "selection_semantics": selection_semantics,
                "required_selection_count": num_cards,
            }
        else:
            plan_protection_evidence = None
        chosen_uuids = {
            getattr(card, "uuid", None) for card in chosen
        }
        hand_candidates = []
        for choice_index, card in enumerate(cards):
            card_uuid = getattr(card, "uuid", None)
            choice_id = f"grid:{card_uuid or choice_index}"
            is_selected = card_uuid in chosen_uuids
            protected_by_plan = (
                str(card_uuid or "") in protected_veto_uuids
            )
            direction = 1.0 if good_action else -1.0
            score_parts = dict(hand_score_parts[id(card)])
            score_coefficients = {
                name: direction for name in score_parts
            }
            if optional_remove:
                # An optional discard is exchanged for a fresh draw.  Score
                # that replacement explicitly so low-value starter cards can
                # beat Proceed while cards above the hand-relative cutoff do
                # not.  This also makes each step of the multi-card Gambling
                # Chip selection locally auditable instead of relying on a
                # hidden whole-batch exception.
                score_parts["expected_redraw_keep_value"] = max(
                    0.0, optional_redraw_keep_value
                )
                score_coefficients["expected_redraw_keep_value"] = 1.0
            if protected_by_plan:
                # A hard plan-preservation veto must also be visible in the
                # numeric comparison. Otherwise the trace can claim that a
                # higher-scored card was ignored even though exhausting it
                # would invalidate the already-bound combat line.
                score_parts["bound_plan_preservation_value"] = 1000.0
                score_coefficients["bound_plan_preservation_value"] = (
                    direction
                )
            base_candidate_score = float(
                sum(
                    score_coefficients[name] * value
                    for name, value in score_parts.items()
                )
            )
            exact_potion_non_target = bool(
                exact_potion_filter
                and str(card_uuid or "") not in exact_potion_targets
            )
            if exact_potion_non_target and base_candidate_score >= 0.0:
                # An exact Elixir/Gambler target UUID set is a frozen plan.
                # Cards outside that set must remain below Proceed even when
                # their generic status penalty would otherwise make removal
                # look attractive (for example Ethereal Dazed/Slimed).
                score_parts["exact_potion_non_target_guard"] = (
                    base_candidate_score + 1.0
                )
                score_coefficients["exact_potion_non_target_guard"] = -1.0
            candidate_score = float(
                sum(
                    score_coefficients[name] * value
                    for name, value in score_parts.items()
                )
            )
            selected_card = self._audit_card_instance_facts(card)
            hand_resolution = {
                "kind": "hand_select_action_resolution",
                "current_action": action,
                "max_cards": int(getattr(screen, "num_cards", 0) or 0),
                "can_pick_zero": bool(
                    getattr(screen, "can_pick_zero", False)
                ),
                "selected_card": selected_card,
                "timing": "after_hand_selection_confirmation",
            }
            hand_candidates.append({
                "id": choice_id,
                "choice_id": choice_id,
                "choice_index": choice_index,
                "action": "choose",
                "semantic_id": choice_id,
                "score": candidate_score,
                "label": getattr(card, "name", None),
                "legal": True,
                "visible": True,
                "selection_eligible": not protected_by_plan,
                "veto_reason": (
                    "exact_combat_plan_card_preservation"
                    if protected_by_plan else None
                ),
                "reason": (
                    "preserved_exact_combat_plan_card_instance"
                    if protected_by_plan else "selected_exact_hand_card_instance"
                    if is_selected else "visible_unchosen_hand_card_instance"
                ),
                "consequences": {
                    "operation": "hand_select_card",
                    "selected_card": selected_card,
                    "future_costs": [hand_resolution],
                },
                **self._linear_score_contract(
                    "hand_select_keep_or_remove_components_v1",
                    score_parts,
                    tuple(
                        (name, name, score_coefficients[name])
                        for name in score_parts
                    ),
                ),
            })
        if getattr(screen, "can_pick_zero", False):
            hand_candidates.append({
                "id": "action:proceed",
                "choice_id": "action:proceed",
                "choice_index": None,
                "action": "proceed",
                "semantic_id": "proceed",
                "score": 0.0,
                "label": "Done",
                "legal": True,
                "visible": True,
                "selection_eligible": True,
                "reason": (
                    "selected_optional_subset_complete"
                    if not chosen else "optional_subset_can_finish"
                ),
                "consequences": {
                    "operation": "hand_select_confirm_queued_action",
                },
                **self._linear_score_contract(
                    "hand_select_optional_proceed_v1",
                    {"proceed_value": 0.0},
                    (("proceed_value", "proceed_value", 1.0),),
                ),
            })
        self._record_noncombat_decision(
            "hand_select_context_score",
            hand_candidates,
            candidate_contract={
                "score_source": "hand_select_exact_instance_local_utility",
                "strategy_quality_auditable": all(
                    getattr(card, "uuid", None) for card in cards
                ),
                "all_visible_options_scored": True,
                "visible_option_count": len(hand_candidates),
                "identity_source": "card_instance_uuid_and_protocol_action",
                "plan_protection_authority": (
                    "prior_bound_combat_plan_v1"
                    if plan_protection_evidence else None
                ),
                "exact_potion_filter": (
                    {
                        "potion_id": potion_filter_source.get("potion_id"),
                        "selection_context": (
                            list(exact_context)
                            if exact_context_matches
                            and isinstance(exact_context, (list, tuple))
                            else None
                        ),
                        "target_card_instance_ids": sorted(
                            exact_potion_targets
                        ),
                        "replacement_draw": bool(exact_potion_redraw),
                        "draw_mode": potion_redraw_mode or None,
                    }
                    if exact_potion_filter else None
                ),
            },
            chosen=",".join(card.card_id for card in chosen),
            chosen_ids=(
                [f"grid:{getattr(card, 'uuid', None)}" for card in chosen]
                if chosen else ["action:proceed"]
            ),
            selection_action=action,
            selection_semantics=selection_semantics,
            combat_plan_protection=plan_protection_evidence,
            exhaust_plan_reconsideration=exhaust_plan_reconsideration,
            planned_selection_count=(
                len((self.pending_hand_selection or {}).get(
                    "planned_uuids", []
                ))
                if optional_remove else None
            ),
        )
        if optional_remove and not chosen:
            self.pending_hand_selection = None
            self.pending_potion_hand_filter = None
        return chosen

    def _combat_reward_audit_candidates(
        self, selected_reward=None, *, candidate_vetoes=None
    ):
        """Describe the complete visible reward surface for this click."""

        rewards = list(getattr(self.game.screen, "rewards", []) or [])
        rows = []
        candidate_vetoes = candidate_vetoes or {}
        sapphire_surface = any(
            str(
                getattr(
                    getattr(item, "reward_type", None),
                    "name", getattr(item, "reward_type", ""),
                )
            ).casefold() == "sapphire_key"
            for item in rewards
        )
        heart_plan = HeartPlan.from_game(self.game, self.goal_mode)
        sapphire_reward = next(
            (
                item for item in rewards
                if str(
                    getattr(
                        getattr(item, "reward_type", None),
                        "name", getattr(item, "reward_type", ""),
                    )
                ).casefold() == "sapphire_key"
            ),
            None,
        )
        sapphire_opportunity = (
            heart_plan.sapphire_opportunity_value()
            if sapphire_surface else None
        )
        linked_deadline_score = (
            float(self._relic_acquisition_score(sapphire_reward.link))
            if sapphire_reward is not None
            and getattr(sapphire_reward, "link", None) is not None
            else 0.0
        )
        sapphire_value = (
            float(sapphire_opportunity)
            if sapphire_opportunity is not None
            else max(30.0, linked_deadline_score + 1.0)
            if sapphire_surface and heart_plan.sapphire_missing
            else 0.0
        )
        # A full belt is not itself a reason to treat every visible potion
        # reward as impossible.  If one exact discard/use transition can make
        # room, preserve the single reward that justifies it as selectable so
        # the normal reward loop can emit its bound resource-preparation
        # action.  All other full-belt potion rows remain visible but vetoed.
        # This must be calculated from the same live reward surface used by
        # the action path below; otherwise a blanket full-belt veto silently
        # turns a beneficial bottle replacement into Proceed.
        replacement_target = None
        if (
            not self._has_relic("Sozu")
            and self.game.are_potions_full()
        ):
            replacement = self._potion_replacement([
                getattr(reward, "potion", None)
                for reward in rewards
                if str(
                    getattr(
                        getattr(reward, "reward_type", None),
                        "name", getattr(reward, "reward_type", ""),
                    )
                ).casefold() == "potion"
            ])
            if replacement is not None:
                _replacement_action, _old_potion, replacement_target, _gain = (
                    replacement
                )
        for choice_index, reward in enumerate(rewards):
            reward_type_value = getattr(reward, "reward_type", None)
            reward_type = str(
                getattr(reward_type_value, "name", reward_type_value or "unknown")
            ).casefold()
            relic = getattr(reward, "relic", None)
            potion = getattr(reward, "potion", None)
            if reward_type in {"emerald_key", "sapphire_key"}:
                base_score = (
                    sapphire_value
                    if reward_type == "sapphire_key" else 1000.0
                )
                score_evidence = self._linear_score_contract(
                    "combat_reward_key_opportunity_v2",
                    {"key_opportunity_value": base_score},
                    ((
                        "key_opportunity_value", "key_opportunity_value", 1.0,
                    ),),
                )
            elif reward_type in {"gold", "stolen_gold"}:
                gold_amount = float(getattr(reward, "gold", 0) or 0)
                bloody_idol_hp_gain = (
                    max(
                        0.0,
                        min(
                            5.0,
                            float(self.game.max_hp)
                            - float(self.game.current_hp),
                        ),
                    )
                    if self._has_relic("Bloody Idol")
                    and not self._has_relic("Mark of the Bloom")
                    and gold_amount > 0
                    else 0.0
                )
                base_score = gold_amount + bloody_idol_hp_gain
                score_evidence = self._linear_score_contract(
                    "combat_reward_gold_and_heal_v2",
                    {
                        "gold_amount": gold_amount,
                        "bloody_idol_hp_gain": bloody_idol_hp_gain,
                    },
                    (
                        ("gold_amount", "gold_amount", 1.0),
                        (
                            "bloody_idol_hp_gain",
                            "bloody_idol_hp_gain",
                            1.0,
                        ),
                    ),
                )
            elif reward_type == "relic" and relic is not None:
                relic_context_value = float(
                    self._relic_acquisition_score(relic)
                )
                free_collection_floor = max(0.0, 1.0 - relic_context_value)
                base_score = relic_context_value + free_collection_floor
                score_evidence = self._linear_score_contract(
                    "combat_reward_free_relic_collection_v2",
                    {
                        "relic_context_value": relic_context_value,
                        "free_collection_floor": free_collection_floor,
                    },
                    (
                        ("relic_context_value", "relic_context_value", 1.0),
                        (
                            "free_collection_floor",
                            "free_collection_floor",
                            1.0,
                        ),
                    ),
                )
            elif reward_type == "potion" and potion is not None:
                potion_keep_value = float(self._potion_keep_score(potion))
                free_collection_floor = max(0.0, 1.0 - potion_keep_value)
                base_score = potion_keep_value + free_collection_floor
                score_evidence = self._linear_score_contract(
                    "combat_reward_free_potion_collection_v2",
                    {
                        "potion_keep_value": potion_keep_value,
                        "free_collection_floor": free_collection_floor,
                    },
                    (
                        ("potion_keep_value", "potion_keep_value", 1.0),
                        (
                            "free_collection_floor",
                            "free_collection_floor",
                            1.0,
                        ),
                    ),
                )
            elif reward_type == "card":
                base_score = 12.0
                score_evidence = self._linear_score_contract(
                    "combat_reward_card_screen_priority_v1",
                    {"card_screen_priority": base_score},
                    (("card_screen_priority", "card_screen_priority", 1.0),),
                )
            else:
                base_score = 1.0
                score_evidence = self._linear_score_contract(
                    "combat_reward_other_collection_v1",
                    {"collection_priority": base_score},
                    (("collection_priority", "collection_priority", 1.0),),
                )
            veto_reason = candidate_vetoes.get(id(reward))
            if reward_type == "potion" and potion is not None:
                potion_token = self._token(
                    getattr(potion, "potion_id", "")
                )
                if veto_reason is not None:
                    pass
                elif self._has_relic("Sozu"):
                    veto_reason = "sozu_blocks_potions"
                elif (
                    self.game.are_potions_full()
                    and potion is not replacement_target
                ):
                    veto_reason = "potion_slots_full_requires_resource_preparation"
            mechanically_eligible = veto_reason is None
            choice_id = f"reward:{reward_type}:{choice_index}"
            consequences = {
                "operation": (
                    "gain_sapphire_key"
                    if reward_type == "sapphire_key"
                    else "gain_linked_relic"
                    if sapphire_surface and reward_type == "relic"
                    else "collect_independent_reward"
                    if sapphire_surface
                    else "collect_combat_reward"
                ),
                "reward_type": reward_type,
            }
            if reward_type in {"gold", "stolen_gold"}:
                consequences["gold_delta"] = int(
                    getattr(reward, "gold", 0) or 0
                )
                consequences["hp_delta"] = int(bloody_idol_hp_gain)
            if relic is not None:
                consequences["relic_id"] = getattr(
                    relic, "relic_id", None
                )
            if potion is not None:
                consequences["potion_id"] = getattr(
                    potion, "potion_id", None
                )
            rows.append({
                "id": choice_id,
                "choice_id": choice_id,
                "choice_index": choice_index,
                "action": "choose",
                "semantic_id": choice_id,
                "score": base_score,
                "raw_local_score": base_score,
                "label": (
                    getattr(relic, "name", None)
                    or getattr(potion, "name", None)
                    or reward_type.replace("_", " ").title()
                ),
                "legal": True,
                "visible": True,
                "selection_eligible": mechanically_eligible,
                "veto_reason": veto_reason,
                "reason": (
                    "selected_visible_combat_reward"
                    if reward is selected_reward
                    else "visible_unselected_combat_reward"
                ),
                "consequences": consequences,
                **score_evidence,
            })
        # ChoiceScreenUtils exposes Confirm on every COMBAT_REWARD frame,
        # including frames that still contain rewards.  Retain it in the
        # surface instead of treating it as an empty-screen special case.
        rows.append({
            "id": "action:proceed",
            "choice_id": "action:proceed",
            "choice_index": None,
            "action": "proceed",
            "semantic_id": "proceed",
            "score": 0.0,
            "raw_local_score": 0.0,
            "label": "Proceed",
            "legal": True,
            "visible": True,
            "selection_eligible": True,
            "veto_reason": None,
            "reason": (
                "selected_finish_reward_screen"
                if selected_reward is None and not rewards
                else "visible_reward_screen_confirm"
            ),
            "consequences": {"operation": "proceed"},
            **self._linear_score_contract(
                "combat_reward_proceed_priority_v1",
                {"proceed_priority": 0.0},
                (("proceed_priority", "proceed_priority", 1.0),),
            ),
        })
        return rows

    def _record_combat_reward_choice(
        self, reason, selected_reward, *, candidate_vetoes=None, **details
    ):
        rows = self._combat_reward_audit_candidates(
            selected_reward, candidate_vetoes=candidate_vetoes
        )
        key_value = details.get("key_value")
        if isinstance(key_value, (int, float)) and not isinstance(
            key_value, bool
        ):
            key_row = None
            for row in rows:
                consequences = row.get("consequences")
                consequences = (
                    consequences if isinstance(consequences, dict) else {}
                )
                if consequences.get("reward_type") != "sapphire_key":
                    continue
                key_row = row
                row["score"] = float(key_value)
                row["raw_local_score"] = float(key_value)
                row.update(self._linear_score_contract(
                    "sapphire_key_opportunity_value_v1",
                    {"key_opportunity_value": float(key_value)},
                    ((
                        "key_opportunity_value",
                        "key_opportunity_value",
                        1.0,
                    ),),
                ))
            if key_row is not None and selected_reward is not None:
                selected_type = str(
                    getattr(
                        getattr(selected_reward, "reward_type", None),
                        "name",
                        getattr(selected_reward, "reward_type", ""),
                    )
                ).casefold()
                if selected_type == "sapphire_key":
                    other_ceiling = max(
                        (
                            float(row.get("score"))
                            for row in rows
                            if row is not key_row
                            and row.get("selection_eligible") is True
                            and isinstance(row.get("score"), (int, float))
                            and not isinstance(row.get("score"), bool)
                        ),
                        default=float(key_value),
                    )
                    order_priority = max(
                        0.0, other_ceiling - float(key_value) + 1.0
                    )
                    if order_priority > 0:
                        ordered_score = float(key_value) + order_priority
                        key_row["score"] = ordered_score
                        key_row["raw_local_score"] = ordered_score
                        key_row.update(self._linear_score_contract(
                            "sapphire_key_first_collection_order_v1",
                            {
                                "key_opportunity_value": float(key_value),
                                "collection_order_priority": order_priority,
                            },
                            (
                                (
                                    "key_opportunity_value",
                                    "key_opportunity_value",
                                    1.0,
                                ),
                                (
                                    "collection_order_priority",
                                    "collection_order_priority",
                                    1.0,
                                ),
                            ),
                        ))
        self._bind_sapphire_macro_advice_to_reward_surface(rows)
        selected_index = next(
            index for index, reward in enumerate(self.game.screen.rewards)
            if reward is selected_reward
        )
        selected_id = rows[selected_index]["choice_id"]
        self._record_noncombat_decision(
            reason,
            rows,
            candidate_contract={
                "score_source": "combat_reward_effective_collection_priority",
                "strategy_quality_auditable": True,
                "all_visible_options_scored": True,
                "visible_option_count": len(rows),
                "filtered_options_retained": True,
                "identity_source": "protocol_choice_index_and_reward_type",
            },
            chosen=selected_id,
            chosen_id=selected_id,
            **details,
        )

    def _bind_sapphire_macro_advice_to_reward_surface(self, rows):
        """Replace abstract key/relic advice ids with exact visible choices."""

        advice = self._pending_macro_advice
        if not isinstance(advice, dict) or advice.get("decision_type") != "SAPPHIRE_KEY":
            return
        aliases = {}
        for row in rows or []:
            if not isinstance(row, dict):
                continue
            choice_id = str(row.get("choice_id") or "")
            consequences = row.get("consequences")
            consequences = consequences if isinstance(consequences, dict) else {}
            reward_type = str(consequences.get("reward_type") or "").casefold()
            if choice_id and reward_type == "sapphire_key":
                aliases["sapphire_key"] = choice_id
            relic_id = consequences.get("relic_id")
            if choice_id and relic_id:
                aliases[f"linked_relic:{relic_id}"] = choice_id
        if not aliases:
            return

        surface_scores = {
            str(row.get("choice_id")): row.get("score")
            for row in rows or []
            if isinstance(row, dict)
            and row.get("choice_id") is not None
            and isinstance(row.get("score"), (int, float))
            and not isinstance(row.get("score"), bool)
        }

        def remap(value):
            key = str(value or "")
            return aliases.get(key, value)

        for field in ("rule_choice_id", "model_choice_id"):
            if advice.get(field) is not None:
                advice[field] = remap(advice[field])
        if isinstance(advice.get("final_choice_ids"), list):
            advice["final_choice_ids"] = [
                remap(value) for value in advice["final_choice_ids"]
            ]
        for ranking in advice.get("rankings") or []:
            if isinstance(ranking, dict) and ranking.get("candidate_id") is not None:
                ranking["candidate_id"] = remap(ranking["candidate_id"])
        replay = advice.get("replay")
        if isinstance(replay, dict):
            if isinstance(replay.get("rule_choice_ids"), list):
                replay["rule_choice_ids"] = [
                    remap(value) for value in replay["rule_choice_ids"]
                ]
            for candidate in replay.get("candidates") or []:
                if isinstance(candidate, dict) and candidate.get("candidate_id") is not None:
                    candidate["candidate_id"] = remap(
                        candidate["candidate_id"]
                    )
                    surface_score = surface_scores.get(
                        str(candidate["candidate_id"])
                    )
                    if surface_score is not None:
                        # The replay's local score remains the exact adviser
                        # input. Cross-channel comparison must use the score
                        # after the abstract id is bound to this sequential
                        # reward surface and collection-order bonuses apply.
                        candidate["decision_surface_score"] = surface_score

    def handle_screen(self):
        if self.game.screen_type == ScreenType.EVENT:
            valid_options = [option for option in self.game.screen.options if not option.disabled and option.choice_index is not None]
            if self._is_match_game_event():
                # The event has ordinary one-button intro/exit screens before
                # and after the twelve-card board. Do not remember those
                # buttons as the first card flip, or the board will wait
                # forever for that nonexistent card to reveal.
                if len(valid_options) == 1:
                    value = self._token(
                        getattr(valid_options[0], "label", "")
                        or getattr(valid_options[0], "text", "")
                    )
                    if not (value.startswith("card") and value[4:].isdigit()):
                        self._reset_match_game()
                        return self.choose_event_action(valid_options)
                return self.choose_match_game_action(valid_options)
            self._reset_match_game()
            return self.choose_event_action(valid_options)
        elif self.game.screen_type == ScreenType.CHEST:
            chest_candidates = [
                {
                    "id": "chest:open",
                    "choice_id": "chest:open",
                    "choice_index": 0,
                    "action": "choose",
                    "semantic_id": "chest:0",
                    "score": 1.0,
                    "label": "Open chest",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": True,
                    "reason": "selected_open_visible_chest",
                    "consequences": {"operation": "open_chest"},
                    **self._linear_score_contract(
                        "chest_visible_action_priority_v1",
                        {"open_priority": 1.0},
                        (("open_priority", "open_priority", 1.0),),
                    ),
                },
                {
                    "id": "action:proceed",
                    "choice_id": "action:proceed",
                    "choice_index": None,
                    "action": "proceed",
                    "semantic_id": "proceed",
                    "score": 0.0,
                    "label": "Proceed",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": True,
                    "reason": "visible_chest_confirm_not_selected",
                    "consequences": {"operation": "proceed"},
                    **self._linear_score_contract(
                        "chest_visible_action_priority_v1",
                        {"proceed_priority": 0.0},
                        (("proceed_priority", "proceed_priority", 1.0),),
                    ),
                },
            ]
            self._record_noncombat_decision(
                "open_visible_chest",
                chest_candidates,
                candidate_contract={
                    "score_source": "single_protocol_visible_action",
                    "strategy_quality_auditable": True,
                    "all_visible_options_scored": True,
                    "visible_option_count": len(chest_candidates),
                    "return_command_included": True,
                    "identity_source": "protocol_choice_index_and_action",
                },
                chosen="Open chest",
                chosen_id="chest:open",
            )
            return OpenChestAction()
        elif self.game.screen_type == ScreenType.SHOP_ROOM:
            # Screen state is authoritative.  Mutating a local visited flag
            # before the click is acknowledged makes stale/rejected retries
            # skip the shop entirely.
            visit_key = (int(self.game.act), int(self.game.floor))
            shop_room_completed = self.shop_completed_visit_key == visit_key
            shop_room_candidates = [
                {
                    "id": "shop_room:enter",
                    "choice_id": "shop_room:enter",
                    "choice_index": 0,
                    "action": "choose",
                    "semantic_id": "shop_room:0",
                    "score": 0.0 if shop_room_completed else 1.0,
                    "label": "Shop",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": True,
                    "reason": (
                        "visible_shopkeeper_already_visited"
                        if shop_room_completed
                        else "selected_enter_visible_shop"
                    ),
                    "consequences": {"operation": "enter_shop"},
                    **self._linear_score_contract(
                        "shop_room_transition_priority_v1",
                        {
                            "enter_priority": (
                                0.0 if shop_room_completed else 1.0
                            ),
                        },
                        (("enter_priority", "enter_priority", 1.0),),
                    ),
                },
                {
                    "id": "action:proceed",
                    "choice_id": "action:proceed",
                    "choice_index": None,
                    "action": "proceed",
                    "semantic_id": "proceed",
                    "score": 1.0 if shop_room_completed else 0.0,
                    "label": "Proceed",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": True,
                    "reason": (
                        "selected_confirmed_shop_exit"
                        if shop_room_completed
                        else "visible_shop_room_confirm_not_selected"
                    ),
                    "consequences": {"operation": "proceed"},
                    **self._linear_score_contract(
                        "shop_room_transition_priority_v1",
                        {
                            "proceed_priority": (
                                1.0 if shop_room_completed else 0.0
                            ),
                        },
                        ((
                            "proceed_priority",
                            "proceed_priority",
                            1.0,
                        ),),
                    ),
                },
            ]
            if self.shop_completed_visit_key == visit_key:
                self._record_noncombat_decision(
                    "shop_room_proceed_after_confirmed_exit",
                    shop_room_candidates,
                    candidate_contract={
                        "score_source": "single_protocol_visible_action",
                        "strategy_quality_auditable": True,
                        "all_visible_options_scored": True,
                        "visible_option_count": len(shop_room_candidates),
                        "return_command_included": True,
                        "identity_source": "protocol_choice_index_and_action",
                    },
                    chosen="Proceed",
                    chosen_id="action:proceed",
                )
                return ProceedAction()
            self._record_noncombat_decision(
                "shop_room_enter_visible_shop",
                shop_room_candidates,
                candidate_contract={
                    "score_source": "single_protocol_visible_action",
                    "strategy_quality_auditable": True,
                    "all_visible_options_scored": True,
                    "visible_option_count": len(shop_room_candidates),
                    "return_command_included": True,
                    "identity_source": "protocol_choice_index_and_action",
                },
                chosen="Shop",
                chosen_id="shop_room:enter",
            )
            return ChooseShopkeeperAction()
        elif self.game.screen_type == ScreenType.REST:
            return self.choose_rest_option()
        elif self.game.screen_type == ScreenType.CARD_REWARD:
            return self.choose_card_reward()
        elif self.game.screen_type == ScreenType.COMBAT_REWARD:
            # A skipped CARD item is removed from the authoritative parent
            # reward list before this screen returns.  Never suppress another
            # visible CARD item: it may be Prayer Wheel's second reward.
            self.skipped_cards = False
            self.skipped_card_reward_key = None
            self.skipped_card_rewards_remaining = 0
            heart_plan = HeartPlan.from_game(self.game, self.goal_mode)
            deferred_reward_vetoes = {}
            if heart_plan.active:
                if heart_plan.emerald_missing:
                    emerald = next(
                        (item for item in self.game.screen.rewards if item.reward_type == RewardType.EMERALD_KEY),
                        None,
                    )
                    if emerald is not None:
                        self._record_combat_reward_choice(
                            "heart_plan_emerald_reward",
                            emerald,
                            heart_plan=heart_plan.snapshot(),
                        )
                        return CombatRewardAction(emerald)
                sapphire = next(
                    (item for item in self.game.screen.rewards if item.reward_type == RewardType.SAPPHIRE_KEY),
                    None,
                )
                if sapphire is not None:
                    heart_snapshot = heart_plan.snapshot()
                    key_value = heart_plan.sapphire_opportunity_value()
                    x_cost_card_count = self._x_cost_card_count()
                    linked_score = (
                        self._relic_acquisition_score(sapphire.link)
                        if getattr(sapphire, "link", None) is not None
                        else 0.0
                    )
                    take_sapphire = heart_plan.should_take_sapphire(
                        linked_score
                    )
                    if heart_plan.sapphire_missing and heart_plan.act < 3:
                        linked_id = "linked_relic:" + str(
                            getattr(sapphire.link, "relic_id", "unknown")
                        )
                        selected_id = self._macro_rank(
                            "SAPPHIRE_KEY",
                            [
                                {
                                    "candidate_id": "sapphire_key",
                                    "kind": "key",
                                    "label": "Sapphire Key",
                                    "local_score": key_value,
                                    "facts": {
                                        "target_act": heart_snapshot[
                                            "sapphire_target_act"
                                        ],
                                        "last_guaranteed_chest_act": 3,
                                    },
                                },
                                {
                                    "candidate_id": linked_id,
                                    "kind": "linked_relic",
                                    "label": getattr(
                                        sapphire.link, "name", None
                                    ),
                                    "local_score": linked_score,
                                    "facts": {
                                        "relic_id": getattr(
                                            sapphire.link, "relic_id", None
                                        ),
                                        "description": self._macro_description(
                                            getattr(
                                                sapphire.link,
                                                "description",
                                                "",
                                            )
                                        ),
                                    },
                                },
                            ],
                            (
                                "sapphire_key"
                                if take_sapphire else linked_id
                            ),
                            hard_constraints=[
                                "ACT3_SAPPHIRE_KEY_IS_MANDATORY",
                                "ONLY_CURRENT_LINKED_RELIC_MAY_BE_COMPARED",
                            ],
                            state_details={
                                "linked_relic_score": round(
                                    linked_score, 3
                                ),
                                "key_local_value": key_value,
                                "x_cost_card_count": x_cost_card_count,
                            },
                        )[0]
                        take_sapphire = selected_id == "sapphire_key"
                    if take_sapphire:
                        self._record_combat_reward_choice(
                            "heart_plan_sapphire_opportunity_cost",
                            sapphire,
                            linked_relic=(
                                getattr(sapphire.link, "relic_id", None)
                                if getattr(sapphire, "link", None) is not None
                                else None
                            ),
                            linked_relic_score=round(linked_score, 3),
                            key_value=key_value,
                            x_cost_card_count=x_cost_card_count,
                            heart_plan=heart_snapshot,
                        )
                        return CombatRewardAction(sapphire)
                    if heart_plan.sapphire_missing:
                        deferred_reward_vetoes[id(sapphire)] = (
                            "heart_plan_sapphire_deferred_for_linked_relic"
                        )
                        linked_relic_id = getattr(
                            sapphire.link, "relic_id", None
                        )
                        reward_candidates = []
                        linked_choice_id = None
                        for reward_index, reward in enumerate(
                            self.game.screen.rewards
                        ):
                            reward_type = str(
                                getattr(
                                    getattr(reward, "reward_type", None),
                                    "name",
                                    getattr(reward, "reward_type", "unknown"),
                                )
                            ).casefold()
                            semantic_id = (
                                f"reward:{reward_type}:{reward_index}"
                            )
                            reward_relic_id = getattr(
                                getattr(reward, "relic", None),
                                "relic_id",
                                None,
                            )
                            is_sapphire = reward is sapphire
                            is_linked = bool(
                                linked_relic_id
                                and reward_relic_id == linked_relic_id
                            )
                            if is_linked:
                                linked_choice_id = semantic_id
                            reward_candidates.append({
                                "id": semantic_id,
                                "choice_id": semantic_id,
                                "choice_index": reward_index,
                                "action": "choose",
                                "semantic_id": semantic_id,
                                "score": (
                                    key_value if is_sapphire
                                    else linked_score if is_linked else 0.0
                                ),
                                "label": (
                                    "Sapphire Key" if is_sapphire
                                    else getattr(
                                        getattr(reward, "relic", None),
                                        "name",
                                        reward_type,
                                    )
                                ),
                                "legal": True,
                                "visible": True,
                                "selection_eligible": (
                                    is_sapphire or is_linked
                                ),
                                "veto_reason": (
                                    None if is_sapphire or is_linked
                                    else "independent_reward_deferred"
                                ),
                                "reason": (
                                    "selected_linked_relic"
                                    if is_linked
                                    else "visible_sapphire_alternative"
                                    if is_sapphire
                                    else "independent_reward_deferred"
                                ),
                                "consequences": {
                                    "operation": (
                                        "gain_sapphire_key" if is_sapphire
                                        else "gain_linked_relic" if is_linked
                                        else "collect_independent_reward"
                                    ),
                                    "reward_type": reward_type,
                                    **(
                                        {"relic_id": reward_relic_id}
                                        if reward_relic_id is not None else {}
                                    ),
                                },
                                **self._linear_score_contract(
                                    "sapphire_linked_reward_opportunity_v1",
                                    {
                                        "opportunity_value": (
                                            key_value if is_sapphire
                                            else linked_score if is_linked
                                            else 0.0
                                        ),
                                    },
                                    ((
                                        "opportunity_value",
                                        "opportunity_value",
                                        1.0,
                                    ),),
                                ),
                            })
                        reward_candidates.append({
                            "id": "action:proceed",
                            "choice_id": "action:proceed",
                            "choice_index": None,
                            "action": "proceed",
                            "semantic_id": "proceed",
                            "score": 0.0,
                            "label": "Proceed",
                            "legal": True,
                            "visible": True,
                            "selection_eligible": True,
                            "reason": "visible_reward_screen_confirm",
                            "consequences": {"operation": "proceed"},
                            **self._linear_score_contract(
                                "combat_reward_proceed_priority_v1",
                                {"proceed_priority": 0.0},
                                ((
                                    "proceed_priority",
                                    "proceed_priority",
                                    1.0,
                                ),),
                            ),
                        })
                        self._bind_sapphire_macro_advice_to_reward_surface(
                            reward_candidates
                        )
                        self._record_noncombat_decision(
                            "heart_plan_sapphire_defer_for_linked_relic",
                            reward_candidates,
                            candidate_contract={
                                "score_source": (
                                    "sapphire_linked_relic_opportunity_cost"
                                ),
                                "strategy_quality_auditable": True,
                                "all_visible_options_scored": True,
                                "visible_option_count": (
                                    len(self.game.screen.rewards) + 1
                                ),
                                "return_command_included": True,
                                "filtered_options_retained": True,
                                "identity_source": (
                                    "protocol_choice_index_and_reward_type"
                                ),
                            },
                            chosen=getattr(
                                sapphire.link, "relic_id", "linked_relic"
                            ),
                            chosen_id=linked_choice_id,
                            linked_relic_score=round(linked_score, 3),
                            key_value=key_value,
                            x_cost_card_count=x_cost_card_count,
                            heart_plan=heart_snapshot,
                        )
            reward_potions = [
                item.potion for item in self.game.screen.rewards
                if item.reward_type == RewardType.POTION
                and item.potion is not None
            ]
            best_potion_reward = max(
                (
                    item for item in self.game.screen.rewards
                    if item.reward_type == RewardType.POTION
                    and item.potion is not None
                ),
                key=lambda item: self._potion_keep_score(item.potion),
                default=None,
            )
            reward_rows = self._combat_reward_audit_candidates(
                candidate_vetoes=deferred_reward_vetoes
            )
            ranked_rewards = sorted(
                zip(self.game.screen.rewards, reward_rows),
                key=lambda item: (
                    not bool(item[1].get("selection_eligible")),
                    -float(item[1].get("score", 0.0)),
                    str(item[1].get("choice_id", "")),
                ),
            )
            for reward_item, _reward_row in ranked_rewards:
                if not bool(_reward_row.get("selection_eligible")):
                    continue
                if reward_item.reward_type == RewardType.SAPPHIRE_KEY:
                    # HeartPlan already made the key/relic opportunity-cost
                    # decision above. Do not re-take a deferred key merely
                    # because the protocol serialized it before the relic.
                    continue
                if reward_item.reward_type == RewardType.POTION and self._has_relic("Sozu"):
                    continue
                if reward_item.reward_type == RewardType.POTION and self.game.are_potions_full():
                    replacement = self._potion_replacement(reward_potions)
                    if replacement is not None:
                        action, old, new, improvement = replacement
                        held_potions = list(
                            self.game.get_real_potions() or []
                        )
                        preparation_candidates, selected_preparation_id = (
                            self._potion_resource_preparation_candidates(
                                held_potions,
                                new,
                                action,
                                old,
                                parent_operation="reward_slot",
                            )
                        )
                        self._record_noncombat_decision(
                            "potion_reward_upgrade_full_belt",
                            preparation_candidates,
                            candidate_contract={
                                "score_source": (
                                    "bound_reward_potion_replacement_net_gain"
                                ),
                                "strategy_quality_auditable": True,
                                "all_visible_options_scored": True,
                                "visible_option_count": len(
                                    preparation_candidates
                                ),
                                "identity_source": (
                                    "potion_instance_slot_and_operation"
                                ),
                                "parent_screen_resolution_pending": True,
                            },
                            chosen=f"{'use' if action.use else 'discard'}:{old.potion_id}",
                            chosen_id=selected_preparation_id,
                            replacement=new.potion_id,
                            improvement=improvement,
                        )
                        return action
                    continue
                elif reward_item.reward_type == RewardType.POTION and best_potion_reward is not None:
                    # A mod can expose more than one potion reward.  After
                    # opening a slot, collect the exact potion that justified
                    # the replacement instead of blindly taking list item 0.
                    self._record_combat_reward_choice(
                        "collect_best_visible_potion_reward",
                        best_potion_reward,
                        candidate_vetoes=deferred_reward_vetoes,
                    )
                    return CombatRewardAction(best_potion_reward)
                else:
                    if not (
                        isinstance(self.last_noncombat_decision, dict)
                        and self.last_noncombat_decision.get("reason")
                        == "heart_plan_sapphire_defer_for_linked_relic"
                        and getattr(reward_item, "relic", None)
                        is getattr(sapphire, "link", None)
                    ):
                        self._record_combat_reward_choice(
                            "collect_visible_combat_reward",
                            reward_item,
                            candidate_vetoes=deferred_reward_vetoes,
                        )
                    self._bind_bottled_relic_reward_grid(reward_item)
                    return CombatRewardAction(reward_item)
            self.skipped_cards = False
            self.skipped_card_reward_key = None
            self.skipped_card_rewards_remaining = 0
            completed_reward_candidates = self._combat_reward_audit_candidates()
            self._record_noncombat_decision(
                "combat_reward_complete_proceed",
                completed_reward_candidates,
                candidate_contract={
                    "score_source": "single_protocol_visible_action",
                    "strategy_quality_auditable": True,
                    "all_visible_options_scored": True,
                    "visible_option_count": len(completed_reward_candidates),
                    "return_command_included": True,
                    "identity_source": "protocol_action",
                },
                chosen="Proceed",
                chosen_id="action:proceed",
            )
            return ProceedAction()
        elif self.game.screen_type == ScreenType.MAP:
            return self.make_map_choice()
        elif self.game.screen_type == ScreenType.BOSS_REWARD:
            relics = self.game.screen.relics
            best_boss_relic = self.choose_boss_relic(relics)
            return (
                BossRewardAction(best_boss_relic)
                if best_boss_relic is not None else CancelAction()
            )
        elif self.game.screen_type == ScreenType.SHOP_SCREEN:
            return self.choose_shop_action()
        elif self.game.screen_type == ScreenType.GRID:
            if not self.game.choice_available:
                return ProceedAction()
            return self.choose_grid_action()
        elif self.game.screen_type == ScreenType.HAND_SELECT:
            if not self.game.choice_available:
                return ProceedAction()
            chosen = self._choose_hand_select_cards()
            if not chosen and getattr(
                self.game.screen, "can_pick_zero", False
            ):
                self.pending_hand_selection = None
                return ProceedAction()
            return CardSelectAction(chosen)
        else:
            return ProceedAction()

    def _campfire_threshold(self, floor_in_act):
        threshold = {1: 0.72, 2: 0.80, 3: 0.84, 4: 0.90}.get(
            self.game.act, 0.82
        )
        floor_in_act = max(0, int(floor_in_act or 0))
        if floor_in_act >= 15:
            threshold = max(threshold, 0.90)
        boss_id = self._boss_id()
        if floor_in_act >= 13 and boss_id in {
            "champ", "automaton", "collector", "donuanddeca",
            "timeeater", "awakenedone",
        }:
            threshold = max(threshold, 0.92)
        if floor_in_act >= 13 and boss_id == "slimeboss":
            # Slime Boss is primarily a split-timing/frontload check.  At a
            # healthy HP total, one more meaningful upgrade is worth more
            # than healing toward the generic 90% final-fire threshold.
            threshold = min(threshold, 0.74)
        return threshold

    def _campfire_option_values(
        self,
        rest_options,
        hp,
        floor_in_act,
        projected_upgrade_ids=None,
    ):
        """Score every legal campfire action on one comparable scale."""

        rest_options = list(rest_options or [])
        projected_upgrade_ids = frozenset(projected_upgrade_ids or ())
        max_hp = max(1, int(getattr(self.game, "max_hp", 1) or 1))
        hp = max(0, min(max_hp, int(hp or 0)))
        hp_ratio = hp / max_hp
        threshold = self._campfire_threshold(floor_in_act)
        raw_absolute_floor = {1: 30, 2: 40, 3: 48, 4: 55}.get(
            self.game.act, 40
        )
        absolute_floor = min(
            raw_absolute_floor, int(max_hp * 0.72 + 0.999)
        )
        missing_hp = max(0, max_hp - hp)
        nominal_recovery = max(1, int(max_hp * 0.30))
        if self._has_relic("Regal Pillow"):
            nominal_recovery += 15
        healing_blocked = self._has_relic("Mark of the Bloom")
        actual_recovery = (
            0 if healing_blocked else min(missing_hp, nominal_recovery)
        )
        # Pantograph heals at the start of the immediately following boss
        # combat. At the final fire, count only the HP that Rest adds beyond
        # that already-guaranteed heal; otherwise a capped Pantograph can make
        # a nominal 20+ HP Rest worth literally zero at boss entry while the
        # controller still throws away a decisive Smith.
        pending_boss_healing = 0
        if (
            not healing_blocked
            and floor_in_act >= 15
            and self._has_relic("Pantograph")
        ):
            pending_boss_healing = (
                (25 * 3 + 1) // 2
                if self._has_relic("Magic Flower")
                else 25
            )
        boss_entry_hp_without_rest = min(
            max_hp, hp + pending_boss_healing
        )
        boss_entry_hp_with_rest = min(
            max_hp, hp + actual_recovery + pending_boss_healing
        )
        effective_recovery = max(
            0, boss_entry_hp_with_rest - boss_entry_hp_without_rest
        )
        pending_healing_overlap = max(
            0, actual_recovery - effective_recovery
        )
        divider_penalty = 0
        boss_id = self._boss_id()
        boss_risk = (
            "low"
            if boss_id == "slimeboss"
            else "hp_scaled"
            if boss_id == "hexaghost"
            else "high"
            if boss_id in {
                "champ", "automaton", "collector", "donuanddeca",
                "timeeater", "awakenedone",
            }
            else "standard"
        )
        if (
            not healing_blocked
            and self.game.act == 1
            and floor_in_act >= 15
            and boss_id == "hexaghost"
        ):
            # Hexaghost's six-hit Divider scales from HP on boss entry.  Rest
            # still grants the physical HP, but the extra Divider tier is an
            # immediate, deterministic offset to its survival value.
            divider_before = (boss_entry_hp_without_rest // 12 + 1) * 6
            divider_after = (boss_entry_hp_with_rest // 12 + 1) * 6
            divider_penalty = max(0, divider_after - divider_before)
            effective_recovery = max(
                0, effective_recovery - divider_penalty
            )
        meaningful_recovery = max(4, int(max_hp * 0.08 + 0.999))
        boss_survival_reserve = 0
        boss_survival_gap_closed = 0
        boss_survival_reserve_value = 0.0
        if floor_in_act >= 15 and boss_risk == "high":
            # Ratios alone make a low-max-HP character look deceptively safe:
            # 29/36 is 81%, but one Donu/Deca multi-hit turn can still leave
            # no margin for the following attack.  Price the amount by which
            # Rest crosses a boss-specific absolute entry-HP reserve.  The
            # reserve is capped at max HP, so this never invents unreachable
            # health and full-health characters receive no bonus.
            reserve_by_boss = {
                "automaton": 45,
                "collector": 40,
                "champ": 40,
                "donuanddeca": 40,
                "awakenedone": 40,
                "timeeater": 36,
            }
            boss_survival_reserve = min(
                max_hp, reserve_by_boss.get(boss_id, 40)
            )
            boss_survival_gap_closed = min(
                max(0, boss_survival_reserve - boss_entry_hp_without_rest),
                effective_recovery,
            )
            boss_survival_reserve_value = (
                boss_survival_gap_closed * 0.90
            )

        upgrade_candidates = (
            [
                (
                    self._upgrade_score(card),
                    card,
                    self._route_upgrade_projection_id(card, index),
                )
                for index, card in enumerate(self.game.deck)
                if int(getattr(card, "upgrades", 0) or 0) == 0
                and self._route_upgrade_projection_id(card, index)
                not in projected_upgrade_ids
            ]
            if RestOption.SMITH in rest_options
            else []
        )
        removal_candidates = (
            [(self._removal_score(card), card) for card in self.game.deck]
            if RestOption.TOKE in rest_options
            else []
        )
        best_upgrade, best_upgrade_card, best_upgrade_projection_id = max(
            upgrade_candidates,
            key=lambda item: item[0],
            default=(0.0, None, None),
        )
        top_upgrade_candidates = sorted(
            upgrade_candidates,
            key=lambda item: item[0],
            reverse=True,
        )[:3]
        best_removal, best_removal_card = max(
            removal_candidates,
            key=lambda item: item[0],
            default=(0.0, None),
        )
        boss_readiness = self._boss_entry_readiness()
        deck_readiness = self._deck_readiness()
        values = {}
        score_parts = {}
        if RestOption.SMITH in rest_options:
            # A Smith is more than a static card-priority operation when the
            # current boss exposes a concrete gap.  Keep the additive term
            # bounded so a healthy deck with no meaningful upgrade still
            # prefers Rest, while a low-scaling deck is prompted to fix its
            # missing block/scaling before the boss.
            readiness_gap = max(
                0.0, 1.0 - float(deck_readiness.get("score", 0.0))
            )
            boss_gap = max(0.0, 0.62 - float(boss_readiness.get("score", 0.0)))
            smith_readiness_bonus = min(
                10.0,
                readiness_gap * 4.0 + boss_gap * 8.0,
            )
            values[RestOption.SMITH] = float(best_upgrade) + smith_readiness_bonus
            score_parts[RestOption.SMITH] = {
                "best_upgrade_value": float(best_upgrade),
                "readiness_bonus": float(smith_readiness_bonus),
            }
        if RestOption.TOKE in rest_options:
            values[RestOption.TOKE] = min(38.0, best_removal * 0.30)
            score_parts[RestOption.TOKE] = {
                "bounded_removal_value": float(values[RestOption.TOKE]),
            }
        if RestOption.LIFT in rest_options:
            values[RestOption.LIFT] = 14.0
            score_parts[RestOption.LIFT] = {
                "permanent_strength_value": 14.0,
            }
        if RestOption.DIG in rest_options:
            values[RestOption.DIG] = 16.0
            score_parts[RestOption.DIG] = {
                "random_relic_value": 16.0,
            }
        if RestOption.REST in rest_options:
            if healing_blocked:
                values[RestOption.REST] = -1000.0
                score_parts[RestOption.REST] = {
                    "healing_blocked_penalty": -1000.0,
                }
            else:
                rest_value = effective_recovery * 0.45
                rest_parts = {
                    "effective_recovery_value": effective_recovery * 0.45,
                    "recovery_need_floor": 0.0,
                    "ratio_gap_value": 0.0,
                    "absolute_gap_value": 0.0,
                }
                needs_recovery = (
                    effective_recovery >= meaningful_recovery
                    and (hp_ratio < threshold or hp < absolute_floor)
                )
                if needs_recovery:
                    ratio_gap_closed = min(
                        max(0.0, threshold - hp_ratio),
                        effective_recovery / max_hp,
                    )
                    absolute_gap_closed = min(
                        max(0, absolute_floor - hp), effective_recovery
                    )
                    rest_value += (
                        4.0
                        + ratio_gap_closed * 80.0
                        + absolute_gap_closed * 1.5
                    )
                    rest_parts.update({
                        "recovery_need_floor": 4.0,
                        "ratio_gap_value": ratio_gap_closed * 80.0,
                        "absolute_gap_value": absolute_gap_closed * 1.5,
                    })
                rest_value += boss_survival_reserve_value
                rest_parts["boss_survival_reserve_value"] = (
                    boss_survival_reserve_value
                )
                values[RestOption.REST] = rest_value
                score_parts[RestOption.REST] = rest_parts

        heart_plan = HeartPlan.from_game(self.game, self.goal_mode)
        mandatory_recall = (
            RestOption.RECALL in rest_options
            and heart_plan.recall_is_mandatory(
                floor_in_act, hp_ratio=hp_ratio
            )
        )
        best_non_recall = max(
            (
                value for option, value in values.items()
                if option != RestOption.RECALL
            ),
            default=0.0,
        )
        can_recover = (
            RestOption.REST in rest_options
            and not healing_blocked
            and actual_recovery > 0
        )
        recovery_ratio = actual_recovery / max_hp
        act_one_recall_candidate = heart_plan.act_one_recall_is_candidate(
            hp_ratio,
            can_recover=can_recover,
            recovery_ratio=recovery_ratio,
            survival_ready=hp >= absolute_floor,
        )
        if RestOption.RECALL in rest_options and heart_plan.ruby_missing:
            values[RestOption.RECALL] = (
                heart_plan.recall_opportunity_value(
                    floor_in_act, hp_ratio=hp_ratio
                )
                if heart_plan.act > 1 or act_one_recall_candidate
                else -1000.0
            )
            score_parts[RestOption.RECALL] = {
                "ruby_key_opportunity_value": float(
                    values[RestOption.RECALL]
                ),
            }
        scheduled_recall = (
            RestOption.RECALL in rest_options
            and not mandatory_recall
            and heart_plan.should_recall(
                hp_ratio,
                best_non_recall,
                can_recover=can_recover,
                recovery_ratio=recovery_ratio,
                survival_ready=hp >= absolute_floor,
            )
        )
        if scheduled_recall:
            # Keep the score comparable with the exceptional-action cutoff
            # used by HeartPlan, even though the schedule is deterministic.
            values[RestOption.RECALL] = 30.0
            score_parts[RestOption.RECALL] = {
                "scheduled_recall_value": 30.0,
            }
        non_rest_values = [
            value for option, value in values.items()
            if option not in {RestOption.REST, RestOption.RECALL}
        ]
        best_non_rest = max(non_rest_values, default=None)
        rest_value = values.get(RestOption.REST)
        rest_is_local_best = (
            RestOption.REST in values
            and (
                best_non_rest is None
                or rest_value >= best_non_rest
            )
        )
        final_act_one_survival_rest = (
            int(getattr(self.game, "act", 0) or 0) == 1
            and floor_in_act >= 15
            and boss_id in {"guardian", "slimeboss"}
            and RestOption.REST in rest_options
            and not healing_blocked
            and effective_recovery >= meaningful_recovery
            and hp_ratio < 0.90
            and not bool(boss_readiness.get("ready"))
            and best_upgrade < 14.0
            # Three recent fixed-hash runs reached the final Act 1 fire at
            # 76-79% HP and were forced to Rest even though the auditable
            # local Smith value was 1.6-2.4x larger.  "Deck unready" should
            # increase the value of a useful upgrade, not silently override
            # the same comparable score.  Keep the survival label only when
            # Rest itself wins that comparison.
            and rest_is_local_best
        )
        mandatory_rest = (
            not mandatory_recall
            and not scheduled_recall
            and RestOption.REST in rest_options
            and not healing_blocked
            and effective_recovery >= meaningful_recovery
            and (
                (
                    hp_ratio < 0.45
                    # Low HP is a survival signal, not permission to discard a
                    # clearly better campfire investment.  In particular,
                    # Hexaghost can turn a nominal heal into little or no net
                    # survival while a high-value Smith/Toke is still
                    # available. Keep this generic emergency override only
                    # when Rest wins the same local comparison.
                    and rest_is_local_best
                )
                # Guardian and Slime Boss do not scale their opening attack
                # from entry HP.  At the final Act 1 fire, an unready deck with
                # no premium upgrade should bank meaningful guaranteed HP
                # instead of receiving a larger Smith bonus for being weak.
                or final_act_one_survival_rest
            )
        )
        details = {
            "hp_ratio": hp_ratio,
            "threshold": threshold,
            "absolute_floor": absolute_floor,
            "actual_recovery": actual_recovery,
            "effective_recovery": effective_recovery,
            "pending_boss_healing": pending_boss_healing,
            "pending_healing_overlap": pending_healing_overlap,
            "boss_entry_hp_without_rest": boss_entry_hp_without_rest,
            "boss_entry_hp_with_rest": boss_entry_hp_with_rest,
            "hexaghost_divider_penalty": divider_penalty,
            "meaningful_recovery": meaningful_recovery,
            "boss_survival_reserve": boss_survival_reserve,
            "boss_survival_gap_closed": boss_survival_gap_closed,
            "boss_survival_reserve_value": boss_survival_reserve_value,
            "best_upgrade": float(best_upgrade),
            "best_upgrade_card": (
                self._macro_card_facts(best_upgrade_card)
                if best_upgrade_card is not None else None
            ),
            "best_upgrade_projection_id": best_upgrade_projection_id,
            "upgrade_candidates": [
                {
                    "card": self._macro_card_facts(card),
                    "upgrade_delta_signal": round(float(score), 3),
                    # CommunicationMod does not serialize the upgraded copy
                    # on the REST screen. Say so explicitly instead of
                    # presenting a heuristic score as an exact projection.
                    "projection_available": False,
                }
                for score, card, _ in top_upgrade_candidates
            ],
            "best_removal": float(best_removal),
            "best_removal_card": (
                self._macro_card_facts(best_removal_card)
                if best_removal_card is not None else None
            ),
            "healing_blocked": healing_blocked,
            "mandatory_recall": mandatory_recall,
            "scheduled_recall": scheduled_recall,
            "best_non_rest": (
                float(best_non_rest) if best_non_rest is not None else None
            ),
            "rest_is_local_best": rest_is_local_best,
            "final_act_one_survival_rest": final_act_one_survival_rest,
            "mandatory_rest": mandatory_rest,
            "act_one_recall_candidate": act_one_recall_candidate,
            "best_non_recall": float(best_non_recall),
            "can_recover": can_recover,
            "heart_plan": heart_plan,
            "boss_id": boss_id,
            "boss_risk": boss_risk,
            "deck_readiness": deck_readiness,
            "boss_entry_readiness": boss_readiness,
            "score_parts": score_parts,
        }
        return values, details

    def _choose_campfire_option(
        self,
        rest_options,
        hp,
        floor_in_act,
        projected_upgrade_ids=None,
    ):
        values, details = self._campfire_option_values(
            rest_options,
            hp,
            floor_in_act,
            projected_upgrade_ids=projected_upgrade_ids,
        )
        if details["mandatory_recall"]:
            return RestOption.RECALL, values, details
        if details["mandatory_rest"]:
            return RestOption.REST, values, details
        if details["scheduled_recall"]:
            return RestOption.RECALL, values, details
        if values:
            chosen = max(
                values,
                key=lambda option: (values[option], -option.value),
            )
            return chosen, values, details
        rest_options = list(rest_options or [])
        return (rest_options[0] if rest_options else None), values, details

    def _route_upgrade_projection_id(self, card, deck_index):
        """Stable identity for upgrades consumed inside one route search."""

        instance_id = getattr(card, "uuid", None)
        if instance_id is None:
            instance_id = getattr(card, "card_id", None) or "unknown"
        return f"{int(deck_index)}:{instance_id}"

    def _route_campfire_options(self, projected_upgrade_ids=None):
        """Infer legal campfire actions before the future screen is open."""

        projected_upgrade_ids = frozenset(projected_upgrade_ids or ())
        options = []
        if not self._has_relic("Coffee Dripper"):
            options.append(RestOption.REST)
        if (
            not self._has_relic("Fusion Hammer")
            and any(
                int(getattr(card, "upgrades", 0) or 0) == 0
                and self._route_upgrade_projection_id(card, index)
                not in projected_upgrade_ids
                for index, card in enumerate(self.game.deck)
            )
        ):
            options.append(RestOption.SMITH)
        if self._has_relic("Peace Pipe") and self.game.deck:
            options.append(RestOption.TOKE)
        girya = next(
            (
                relic for relic in getattr(self.game, "relics", []) or []
                if self._token(getattr(relic, "relic_id", "")) == "girya"
            ),
            None,
        )
        if girya is not None and int(getattr(girya, "counter", 0) or 0) < 3:
            options.append(RestOption.LIFT)
        if self._has_relic("Shovel"):
            options.append(RestOption.DIG)
        heart_plan = HeartPlan.from_game(self.game, self.goal_mode)
        if heart_plan.ruby_missing:
            options.append(RestOption.RECALL)
        return options

    def _visible_future_campfire_rows(self, floor_in_act):
        """Return later map rows containing at least one visible campfire.

        The REST screen does not identify the current map-node x coordinate,
        so these rows are deliberately described to the model as occurring on
        *any* visible route, not as guaranteed reachable campfires.
        """

        rows = getattr(getattr(self.game, "map", None), "nodes", {}) or {}
        future = []
        for y, nodes in rows.items():
            try:
                row = int(y) + 1
            except (TypeError, ValueError, OverflowError):
                continue
            if row <= int(floor_in_act or 0):
                continue
            if any(
                getattr(node, "symbol", None) == "R"
                for node in (nodes or {}).values()
            ):
                future.append(row)
        return sorted(set(future))

    def _campfire_macro_facts(
        self, option, details, floor_in_act, future_campfire_rows
    ):
        effects = {
            RestOption.REST: "restore_hp",
            RestOption.SMITH: "upgrade_one_card",
            RestOption.TOKE: "remove_one_card",
            RestOption.LIFT: "gain_one_permanent_strength",
            RestOption.DIG: "gain_random_relic",
            RestOption.RECALL: "obtain_ruby_key",
        }
        facts = {
            "option_effect": effects.get(option, option.name.lower()),
            "boss_id": details["boss_id"],
            "boss_risk": details["boss_risk"],
            "boss_entry_readiness": details.get("boss_entry_readiness"),
            "deck_readiness": details.get("deck_readiness"),
        }
        if option == RestOption.REST:
            facts.update({
                "actual_recovery": details["actual_recovery"],
                "effective_recovery_after_boss_adjustment": details[
                    "effective_recovery"
                ],
                "pending_boss_healing": details[
                    "pending_boss_healing"
                ],
                "pending_healing_overlap": details[
                    "pending_healing_overlap"
                ],
            })
        elif option == RestOption.SMITH:
            facts.update({
                "best_upgrade_score": details["best_upgrade"],
                "best_upgrade_card": details["best_upgrade_card"],
                "top_upgrade_candidates": details["upgrade_candidates"],
                "projection_contract": (
                    "upgrade_delta_signal_is_controller_estimate; "
                    "projected_upgraded_card_unavailable"
                ),
            })
        elif option == RestOption.TOKE:
            facts.update({
                "best_removal_score": details["best_removal"],
                "best_removal_card": details["best_removal_card"],
            })
        elif option == RestOption.RECALL:
            facts.update({
                "key": "RUBY",
                "acquisition_method": "campfire_recall",
                "ruby_missing": details["heart_plan"].ruby_missing,
                "deadline": "before_act_3_boss",
                "current_act": int(getattr(self.game, "act", 0) or 0),
                "current_floor_in_act": int(floor_in_act or 0),
                "visible_future_campfire_rows_any_route": list(
                    future_campfire_rows
                ),
            })
        return facts

    def choose_rest_option(self):
        rest_options = list(self.game.screen.rest_options or [])
        if not rest_options or self.game.screen.has_rested:
            return ProceedAction()
        floor_in_act = max(0, int(getattr(self.game, "floor", 0) or 0) % 17)
        chosen, values, details = self._choose_campfire_option(
            rest_options,
            self.game.current_hp,
            floor_in_act,
        )
        if chosen is None:
            return ProceedAction()
        hard_decision = (
            details["mandatory_recall"]
            or details["scheduled_recall"]
            or details["mandatory_rest"]
        )
        if not hard_decision:
            future_campfire_rows = self._visible_future_campfire_rows(
                floor_in_act
            )
            rest_by_id = {
                f"rest:{option.name}": option
                for option in values
                if values[option] > -900
            }
            local_candidate_id = f"rest:{chosen.name}"
            if local_candidate_id in rest_by_id:
                campfire_constraints = [
                    "FINAL_RUBY_RECALL_DEADLINE_ENFORCED_OUTSIDE_MODEL",
                    "LOW_HP_MANDATORY_REST_ENFORCED_OUTSIDE_MODEL",
                    "RUBY_URGENCY_IS_INDEPENDENT_OF_SAPPHIRE_AND_EMERALD",
                    "HEALING_AND_RELIC_OPTION_RESTRICTIONS_ALREADY_APPLIED",
                ]
                campfire_constraints.append(
                    "OPTIONAL_RECALL_IS_A_LEGAL_RUBY_KEY_CANDIDATE"
                    if "rest:RECALL" in rest_by_id
                    else "RUBY_RECALL_IS_NOT_AVAILABLE_IN_THIS_CANDIDATE_SET"
                )
                selected_id = self._macro_rank(
                    "CAMPFIRE",
                    [
                        {
                            "candidate_id": candidate_id,
                            "kind": "campfire_option",
                            "label": option.name,
                            "local_score": values[option],
                            "facts": self._campfire_macro_facts(
                                option,
                                details,
                                floor_in_act,
                                future_campfire_rows,
                            ),
                        }
                        for candidate_id, option in rest_by_id.items()
                    ],
                    local_candidate_id,
                    hard_constraints=campfire_constraints,
                    state_details={
                        "hp_ratio": round(details["hp_ratio"], 3),
                        "actual_recovery": details["actual_recovery"],
                        "effective_recovery": details["effective_recovery"],
                        "healing_blocked": details["healing_blocked"],
                        "floor_in_act": floor_in_act,
                        "boss_id": details["boss_id"],
                        "boss_risk": details["boss_risk"],
                        "visible_future_campfire_rows_any_route": (
                            future_campfire_rows
                        ),
                        "ruby_missing": details["heart_plan"].ruby_missing,
                        "act_one_recall_candidate": details[
                            "act_one_recall_candidate"
                        ],
                    },
                )[0]
                # _macro_rank normally returns one of the supplied IDs. Keep
                # the deterministic local choice if an advisor/fallback ever
                # returns a stale or malformed ID instead of crashing the
                # live controller at the campfire.
                chosen = rest_by_id.get(selected_id, chosen)
        reason = (
            "heart_plan_ruby_deadline"
            if details["mandatory_recall"]
            else (
                "campfire_survival_rest_floor"
                if details["mandatory_rest"]
                else (
                    "heart_plan_ruby_safe_window"
                    if details["scheduled_recall"]
                    else "campfire_opportunity_cost"
                )
            )
        )
        rest_candidates = []
        visible_rest_options = list(
            getattr(self.game.screen, "rest_options", []) or []
        )
        for choice_index, option in enumerate(visible_rest_options):
            option_name = getattr(option, "name", str(option))
            consequences = {
                "operation": "campfire_" + option_name.casefold(),
                "rest_option": option_name,
            }
            if option == RestOption.REST:
                consequences["hp_delta"] = details["actual_recovery"]
            elif option == RestOption.RECALL:
                consequences["key_changes"] = {"gain": ["ruby_key"]}
            option_score_parts = dict(
                (details.get("score_parts") or {}).get(option) or {}
            )
            rest_candidates.append({
                "id": f"rest:{option_name}",
                "choice_id": f"rest:{option_name}",
                "choice_index": choice_index,
                "action": "choose",
                "semantic_id": f"rest:{choice_index}",
                "score": float(values[option]),
                "label": option_name,
                "legal": True,
                "visible": True,
                "selection_eligible": True,
                "reason": (
                    "selected_campfire_option"
                    if option == chosen else "visible_unchosen_campfire_option"
                ),
                "consequences": consequences,
                **self._linear_score_contract(
                    "campfire_option_components_v1",
                    option_score_parts,
                    tuple(
                        (name, name, 1.0) for name in option_score_parts
                    ),
                ),
            })
        self._record_noncombat_decision(
            reason,
            rest_candidates,
            candidate_contract={
                "score_source": "campfire_opportunity_cost_utility",
                "strategy_quality_auditable": True,
                "all_visible_options_scored": True,
                "visible_option_count": len(visible_rest_options),
                "identity_source": "protocol_choice_index_and_rest_option",
            },
            chosen=chosen.name,
            chosen_id=f"rest:{chosen.name}",
            hp_ratio=round(details["hp_ratio"], 3),
            threshold=round(details["threshold"], 3),
            actual_recovery=details["actual_recovery"],
            effective_recovery=details["effective_recovery"],
            pending_boss_healing=details["pending_boss_healing"],
            pending_healing_overlap=details["pending_healing_overlap"],
            hexaghost_divider_penalty=details[
                "hexaghost_divider_penalty"
            ],
            best_upgrade=round(details["best_upgrade"], 3),
            best_removal=round(details["best_removal"], 3),
            best_non_recall=round(details["best_non_recall"], 3),
            scheduled_recall=details["scheduled_recall"],
            mandatory_rest=details["mandatory_rest"],
            act_one_recall_candidate=details[
                "act_one_recall_candidate"
            ],
            healing_blocked=details["healing_blocked"],
            boss_id=details["boss_id"],
            boss_risk=details["boss_risk"],
            heart_plan=details["heart_plan"].snapshot(),
        )
        return RestAction(chosen)

    def count_copies_in_deck(self, card):
        count = 0
        for deck_card in self.game.deck:
            if deck_card.card_id == card.card_id:
                count += 1
        return count

    def _within_copy_limit(self, card):
        # Redundancy is a marginal-value question, not an eligibility rule.
        # _copy_saturation_penalty can push ordinary duplicates below Skip,
        # while an exceptional synergy remains comparable at any copy count.
        return True

    def _early_offense_value(self):
        return sum(
            self._early_offense_card_value(card)
            for card in self.game.deck
        )

    def _early_offense_card_value(self, card):
        """Value frontload without requiring every attack in a hand table."""

        values = self.EARLY_OFFENSE_VALUE.get(self.chosen_class, {})
        if card.card_id in values:
            return values[card.card_id] + (
                0.35 * int(getattr(card, "upgrades", 0) or 0)
            )
        if (
            getattr(card, "type", None) != spirecomm.spire.card.CardType.ATTACK
            or getattr(card, "rarity", None) in {
                spirecomm.spire.card.CardRarity.BASIC,
                spirecomm.spire.card.CardRarity.CURSE,
            }
        ):
            return 0.0
        damage = max(
            0,
            int(getattr(card, "base_damage", 0) or 0),
            int(getattr(card, "damage", 0) or 0),
        )
        if damage <= 6:
            return 0.0
        cost = self._card_cost(card)
        if cost < 0 or (cost >= 3 and damage < 20):
            return 0.0
        return min(1.25, max(0.5, (damage - 6) / 8.0))

    def _act1_elite_readiness(self, cards=None):
        """Continuous frontload readiness for an Act 1 elite."""

        individual = [
            self._early_offense_card_value(card)
            for card in (
                cards
                if cards is not None
                else getattr(self.game, "deck", []) or []
            )
        ]
        return min(
            1.0,
            max(
                max(individual, default=0.0) / 2.0,
                sum(individual) / 3.25,
            ),
        )

    def _act1_elite_ready(self):
        """Whether the deck has reached the established full-ready boundary."""

        return self._act1_elite_readiness() >= 1.0

    def _permanent_card_pick_hurdle(self):
        """Minimum marginal value required to enlarge the permanent deck."""

        deck_size = len(getattr(self.game, "deck", []) or [])
        act = max(1, int(getattr(self.game, "act", 1) or 1))
        base_hurdle = {
            1: 2.0,
            2: 3.5,
            3: 5.0,
            4: 7.0,
        }.get(act, 5.0)
        return min(
            14.0,
            base_hurdle + max(0, deck_size - 14) * 0.75,
        )

    def choose_card_reward(self):
        # A skip only suppresses the CARD item on the parent combat-reward
        # screen from this exact room.  Reset stale state on every newly
        # entered card screen so event rewards cannot poison the next fight.
        self.skipped_cards = False
        self.skipped_card_reward_key = None
        self.skipped_card_rewards_remaining = 0
        reward_cards = self.game.screen.cards
        # Contracts are scoped to this exact authoritative reward surface;
        # never reuse an object-id entry from an earlier screen.
        self._card_reward_score_contracts = {}
        deck_profile = self._deck_profile()
        deck_plan = self._deck_plan_summary(deck_profile)

        if self.game.in_combat:
            scored = [
                (self.combat_planner.score_temporary_card(self.game, card), card)
                for card in reward_cards
            ]
            if scored:
                best_score, best_card = max(scored, key=lambda item: item[0])
                can_return = bool(
                    getattr(self.game.screen, "can_skip", False)
                    or getattr(self.game, "cancel_available", False)
                )
                choose_return = bool(can_return and best_score <= 0)
                score_by_object = {
                    id(card): float(score) for score, card in scored
                }
                tactical_candidates = []
                for choice_index, card in enumerate(reward_cards):
                    choice_id = (
                        f"card:{getattr(card, 'uuid', '') or choice_index}"
                    )
                    tactical_candidates.append({
                        "id": choice_id,
                        "choice_id": choice_id,
                        "choice_index": choice_index,
                        "action": "choose",
                        "semantic_id": choice_id,
                        "score": score_by_object[id(card)],
                        "label": getattr(card, "name", None),
                        "legal": True,
                        "visible": True,
                        "selection_eligible": True,
                        "reason": (
                            "selected_tactical_card"
                            if card is best_card and not choose_return
                            else "visible_unchosen_tactical_card"
                        ),
                        "consequences": {
                            "operation": "add_temporary_combat_card",
                            "card_instance_id": getattr(card, "uuid", None),
                            "card_id": getattr(card, "card_id", None),
                        },
                        **self._linear_score_contract(
                            "temporary_card_tactical_utility_v1",
                            {
                                "tactical_utility": score_by_object[id(card)],
                            },
                            ((
                                "tactical_utility",
                                "tactical_utility",
                                1.0,
                            ),),
                        ),
                    })
                if can_return:
                    tactical_candidates.append({
                        "id": "action:return",
                        "choice_id": "action:return",
                        "choice_index": None,
                        "action": "return",
                        "operation": None,
                        "semantic_id": "return",
                        "score": 0.0,
                        "label": "Skip",
                        "legal": True,
                        "visible": True,
                        "selection_eligible": True,
                        "reason": (
                            "selected_skip" if choose_return
                            else "decline_temporary_card"
                        ),
                        "consequences": {
                            "operation": "return",
                            "card_changes": {
                                "gain": [], "remove": [],
                                "upgrade": [], "transform": [],
                            },
                        },
                        **self._linear_score_contract(
                            "temporary_card_skip_v1",
                            {"skip_value": 0.0},
                            (("skip_value", "skip_value", 1.0),),
                        ),
                    })
                self._record_noncombat_decision(
                    "card_reward_combat_tactical_score",
                    tactical_candidates,
                    candidate_contract={
                        "score_source": "combat_tactical_card_utility",
                        "strategy_quality_auditable": all(
                            getattr(card, "uuid", None) for card in reward_cards
                        ),
                        "all_visible_options_scored": True,
                        "visible_option_count": (
                            len(reward_cards) + int(can_return)
                        ),
                        "return_command_included": can_return,
                        "identity_source": "card_instance_uuid",
                    },
                    chosen=("Skip" if choose_return else best_card.card_id),
                    chosen_id=(
                        "action:return"
                        if choose_return else
                        f"card:{getattr(best_card, 'uuid', '') or reward_cards.index(best_card)}"
                    ),
                )
                if choose_return:
                    return CancelAction()
                return CardRewardAction(best_card)

        permanent_reward = self.game.screen.can_skip and not self.game.in_combat
        marginal_hurdle = (
            self._permanent_card_pick_hurdle() if permanent_reward else 0.0
        )
        pickable_cards = [
            card for card in reward_cards
            if not permanent_reward or self._within_copy_limit(card)
        ]
        scored = [(self._card_reward_score(card), card) for card in pickable_cards]

        def card_choice_id(card, index):
            return f"card:{getattr(card, 'uuid', '') or index}"

        def card_choice_id_for(card):
            return next(
                card_choice_id(item, index)
                for index, item in enumerate(reward_cards)
                if item is card
            )

        scored_by_object = {
            id(card): float(score) for score, card in scored
        }
        score_contracts = getattr(
            self, "_card_reward_score_contracts", {}
        )

        def card_reward_candidates(chosen_id=None):
            rows = []
            for index, card in enumerate(reward_cards):
                choice_id = card_choice_id(card, index)
                eligible = id(card) in scored_by_object
                rows.append({
                    "id": choice_id,
                    "choice_id": choice_id,
                    "choice_index": index,
                    "action": "choose",
                    "semantic_id": choice_id,
                    "score": scored_by_object.get(id(card), -1000.0),
                    "label": getattr(card, "name", None),
                    "legal": True,
                    "visible": True,
                    "selection_eligible": eligible,
                    "veto_reason": (
                        None if eligible else "copy_limit"
                    ),
                    "reason": (
                        "selected_card"
                        if choice_id == chosen_id
                        else "visible_card_candidate"
                    ),
                    "consequences": {
                        "card_changes": {
                            "gain": [{
                                "id": getattr(card, "card_id", None),
                                "name": getattr(card, "name", None),
                                "card_instance_id": getattr(
                                    card, "uuid", None
                                ),
                                "upgrades": int(
                                    getattr(card, "upgrades", 0) or 0
                                ),
                            }],
                        },
                        "deck_size_delta": 1,
                    },
                    **dict(score_contracts.get(id(card)) or {}),
                })
            if self.game.screen.can_bowl:
                bowl_index = len(reward_cards)
                rows.append({
                    "id": "bowl",
                    "choice_id": "bowl",
                    "choice_index": bowl_index,
                    "action": "choose",
                    "semantic_id": f"card:{bowl_index}",
                    "score": max(8.0, marginal_hurdle),
                    "label": "Singing Bowl",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": True,
                    "reason": (
                        "selected_bowl"
                        if chosen_id == "bowl" else "visible_bowl_candidate"
                    ),
                    "consequences": {
                        "hp_delta": 2,
                        "max_hp_delta": 2,
                    },
                    **self._linear_score_contract(
                        "card_reward_singing_bowl_v1",
                        {
                            "fixed_bowl_value": 8.0,
                            "marginal_hurdle_floor": max(
                                0.0, marginal_hurdle - 8.0
                            ),
                        },
                        (
                            ("fixed_bowl_value", "fixed_bowl_value", 1.0),
                            (
                                "marginal_hurdle_floor",
                                "marginal_hurdle_floor",
                                1.0,
                            ),
                        ),
                    ),
                })
            if self.game.screen.can_skip:
                rows.append({
                    "id": "skip",
                    "choice_id": "action:return",
                    "choice_index": None,
                    "action": "return",
                    "semantic_id": "return",
                    "score": marginal_hurdle,
                    "label": "Skip",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": True,
                    "reason": (
                        "selected_skip"
                        if chosen_id == "skip" else "preserve_deck"
                    ),
                    "consequences": {
                        "operation": "return",
                        "deck_size_delta": 0,
                        "card_changes": {
                            "gain": [], "remove": [],
                            "upgrade": [], "transform": [],
                        },
                    },
                    **self._linear_score_contract(
                        "card_reward_skip_hurdle_v1",
                        {"marginal_hurdle": marginal_hurdle},
                        (("marginal_hurdle", "marginal_hurdle", 1.0),),
                    ),
                })
            return rows

        card_candidate_contract = {
            "score_source": "card_reward_marginal_utility",
            "strategy_quality_auditable": True,
            "all_visible_options_scored": True,
            "return_command_included": bool(self.game.screen.can_skip),
            "identity_source": "card_instance_or_protocol_command",
        }
        if not self.game.in_combat:
            card_candidates = []
            card_by_candidate_id = {}
            for index, (card_score, card) in enumerate(scored):
                candidate_id = (
                    f"card:{getattr(card, 'uuid', '') or index}"
                )
                card_by_candidate_id[candidate_id] = card
                if card_score > -900:
                    card_candidates.append({
                        "candidate_id": candidate_id,
                        "kind": "card",
                        "label": getattr(card, "name", None),
                        "local_score": card_score,
                        "facts": self._macro_card_candidate_facts(
                            card, deck_profile
                        ),
                    })
            best_score, best_card = (
                max(scored, key=lambda item: item[0])
                if scored else (-1000.0, None)
            )
            rule_id = None
            if (
                permanent_reward
                and self.game.screen.can_bowl
                and best_score < max(8.0, marginal_hurdle)
            ):
                rule_id = "bowl"
            elif best_card is not None and (
                not permanent_reward or best_score > marginal_hurdle
            ):
                rule_id = next(
                    candidate_id
                    for candidate_id, card in card_by_candidate_id.items()
                    if card is best_card
                )
            elif self.game.screen.can_bowl:
                rule_id = "bowl"
            else:
                rule_id = "skip"
            if self.game.screen.can_bowl:
                card_candidates.append({
                    "candidate_id": "bowl",
                    "kind": "singing_bowl",
                    "label": "Singing Bowl",
                    "local_score": max(8.0, marginal_hurdle),
                    "facts": {
                        "current_hp_gain": 2,
                        "max_hp_gain": 2,
                    },
                })
            if self.game.screen.can_skip:
                card_candidates.append({
                    "candidate_id": "skip",
                    "kind": "skip",
                    "label": "Skip",
                    "local_score": marginal_hurdle,
                    "facts": {"deck_size_unchanged": True},
                })
            selected = self._macro_rank(
                "CARD_REWARD",
                card_candidates,
                rule_id,
                hard_constraints=[
                    "ONLY_EXACT_CARD_INSTANCES",
                    "CURSE_AND_ILLEGAL_CANDIDATES_EXCLUDED",
                ],
                state_details={
                    "marginal_hurdle": round(marginal_hurdle, 3),
                    "can_skip": bool(self.game.screen.can_skip),
                    "can_bowl": bool(self.game.screen.can_bowl),
                    "permanent_reward": bool(permanent_reward),
                    "source_room_type": str(
                        getattr(self.game, "room_type", "") or ""
                    ),
                    "floors_to_act_boss": max(
                        0,
                        16
                        - max(
                            0,
                            int(getattr(self.game, "floor", 0) or 0) % 17,
                        ),
                    ),
                    "need_horizons": dict(
                        deck_plan.get("need_horizons") or {}
                    ),
                    "boss_readiness": dict(
                        deck_plan.get("boss_readiness") or {}
                    ),
                },
            )[0]
            if selected != rule_id:
                if selected in card_by_candidate_id:
                    advised_card = card_by_candidate_id[selected]
                    self._record_noncombat_decision(
                        "card_reward_macro_rerank",
                        card_reward_candidates(selected),
                        candidate_contract=card_candidate_contract,
                        chosen=advised_card.card_id,
                        chosen_id=selected,
                        deck_plan=deck_plan,
                        marginal_hurdle=round(marginal_hurdle, 3),
                    )
                    return CardRewardAction(advised_card)
                if selected == "bowl":
                    self._record_noncombat_decision(
                        "card_reward_macro_rerank",
                        card_reward_candidates("bowl"),
                        candidate_contract=card_candidate_contract,
                        chosen="Singing Bowl",
                        chosen_id="bowl",
                        deck_plan=deck_plan,
                        marginal_hurdle=round(marginal_hurdle, 3),
                    )
                    return CardRewardAction(bowl=True)
                if selected == "skip":
                    self.skipped_cards = True
                    self.skipped_card_rewards_remaining = 1
                    self.skipped_card_reward_key = (
                        int(getattr(self.game, "act", 0) or 0),
                        int(getattr(self.game, "floor", 0) or 0),
                        str(getattr(self.game, "room_type", "") or ""),
                    )
                    self._record_noncombat_decision(
                        "card_reward_macro_rerank",
                        card_reward_candidates("skip"),
                        candidate_contract=card_candidate_contract,
                        chosen="Skip",
                        chosen_id="skip",
                        deck_plan=deck_plan,
                        marginal_hurdle=round(marginal_hurdle, 3),
                    )
                    return CancelAction()
        if scored:
            best_score, best_card = max(scored, key=lambda item: item[0])
            # Singing Bowl is worth more than a marginal filler card.  A plain
            # skip has zero value and should beat a negative deck addition.
            if (
                permanent_reward
                and self.game.screen.can_bowl
                and best_score < max(8.0, marginal_hurdle)
            ):
                self._record_noncombat_decision(
                    "card_reward_bowl_over_marginal_card",
                    card_reward_candidates("bowl"),
                    candidate_contract=card_candidate_contract,
                    chosen="Singing Bowl",
                    chosen_id="bowl",
                    deck_plan=deck_plan,
                    marginal_hurdle=round(marginal_hurdle, 3),
                )
                return CardRewardAction(bowl=True)
            if not permanent_reward or best_score > marginal_hurdle:
                self._record_noncombat_decision(
                    "card_reward_context_score",
                    card_reward_candidates(
                        card_choice_id_for(best_card)
                    ),
                    candidate_contract=card_candidate_contract,
                    chosen=best_card.card_id,
                    chosen_id=card_choice_id_for(best_card),
                    deck_plan=deck_plan,
                    marginal_hurdle=round(marginal_hurdle, 3),
                )
                return CardRewardAction(best_card)
        if self.game.screen.can_bowl:
            self._record_noncombat_decision(
                "card_reward_bowl_no_good_card",
                card_reward_candidates("bowl"),
                candidate_contract=card_candidate_contract,
                chosen="Singing Bowl",
                chosen_id="bowl",
                deck_plan=deck_plan,
            )
            return CardRewardAction(bowl=True)
        self.skipped_cards = True
        self.skipped_card_rewards_remaining = 1
        self.skipped_card_reward_key = (
            int(getattr(self.game, "act", 0) or 0),
            int(getattr(self.game, "floor", 0) or 0),
            str(getattr(self.game, "room_type", "") or ""),
        )
        skip_reason = (
            "card_reward_skip_nonpositive"
            if not scored or max(score for score, _ in scored) <= 0
            else "card_reward_skip_below_marginal_hurdle"
        )
        self._record_noncombat_decision(
            skip_reason,
            card_reward_candidates("skip"),
            candidate_contract=card_candidate_contract,
            chosen="Skip",
            chosen_id="skip",
            deck_plan=deck_plan,
            marginal_hurdle=round(marginal_hurdle, 3),
        )
        return CancelAction()

    def _route_campfire_choice(
        self, node, hp, projected_upgrade_ids=None, ruby_pending=None
    ):
        floor_in_act = max(1, int(getattr(node, "y", -1) or -1) + 1)
        # A projected fire must see its own floor/key state. Reusing the live
        # state schedules Recall repeatedly and withholds later recovery.
        projected = copy.copy(self)
        projected.game = copy.copy(self.game)
        projected.game.floor = (int(self.game.act) - 1) * 17 + floor_in_act
        if ruby_pending is not None:
            projected.game.has_ruby_key = not ruby_pending
        return projected._choose_campfire_option(
            projected._route_campfire_options(projected_upgrade_ids),
            hp,
            floor_in_act,
            projected_upgrade_ids=projected_upgrade_ids,
        )

    def _campfire_will_restore(self, node, hp):
        """Whether the shared campfire policy will actually choose REST."""

        chosen, _, details = self._route_campfire_choice(node, hp)
        return chosen == RestOption.REST and details["actual_recovery"] > 0

    def _estimated_map_room_cost(self, node, lament_combat=False):
        if lament_combat and node.symbol in {"M", "E"}:
            return 0.0
        cost = {
            "E": {1: 18.0, 2: 28.0, 3: 34.0, 4: 40.0}.get(
                self.game.act, 28.0
            ),
            "M": {1: 6.0, 2: 10.0, 3: 13.0, 4: 18.0}.get(
                self.game.act, 10.0
            ),
            "?": 3.0,
            "$": 0.0,
            "T": 0.0,
        }.get(node.symbol, 0.0)
        if getattr(node, "has_emerald_key", False):
            cost += {1: 6.0, 2: 9.0, 3: 12.0, 4: 14.0}.get(
                self.game.act, 9.0
            )
        return cost

    def _estimated_survival_room_cost(self, node, lament_combat=False):
        """Conservative peak loss for route viability, separate from EV.

        Expected attrition is appropriate for reward scoring, but a future
        campfire cannot refund HP if the current elite kills the run.  Use a
        calibrated upper-tail estimate for elite survival gates while keeping
        ordinary room values unchanged.
        """

        if lament_combat and node.symbol in {"M", "E"}:
            return 0.0
        if node.symbol != "E":
            return self._estimated_map_room_cost(
                node, lament_combat=lament_combat
            )
        return self._estimated_elite_survival_cost(
            burning=bool(getattr(node, "has_emerald_key", False))
        )

    def _estimated_elite_survival_cost(self, *, burning=False):
        """Shared conservative loss budget for map and optional elite fights."""
        peak = {1: 34.0, 2: 70.0, 3: 76.0, 4: 92.0}.get(
            int(self.game.act), 70.0
        )
        peak += {
            PlayerClass.IRONCLAD: -4.0,
            PlayerClass.THE_SILENT: 4.0,
            PlayerClass.DEFECT: 0.0,
        }.get(self.chosen_class, 0.0)
        if burning:
            peak += {1: 8.0, 2: 10.0, 3: 12.0, 4: 14.0}.get(
                int(self.game.act), 10.0
            )
        # The same elite can be survivable for one deck and a run-ending
        # gamble for another.  Add only a bounded upper-tail surcharge when
        # the current boss profile exposes a real block/scaling/frontload
        # hole; this keeps expected-value route ranking stable for healthy
        # decks while stopping underdeveloped branches from looking safe.
        boss_readiness = self._boss_entry_readiness()
        readiness_gap = max(
            0.0,
            0.55 - float(boss_readiness.get("score", 0.0) or 0.0),
        )
        peak += min(16.0, readiness_gap * 32.0)
        defensive_cards = sum(
            1
            for card in getattr(self.game, "deck", []) or []
            if self.priorities.is_card_defensive(card)
            and getattr(card, "rarity", None)
            != spirecomm.spire.card.CardRarity.BASIC
        )
        upgraded_defense = sum(
            1
            for card in getattr(self.game, "deck", []) or []
            if self.priorities.is_card_defensive(card)
            and int(getattr(card, "upgrades", 0) or 0) > 0
        )
        defensive_potions = sum(
            1
            for potion in self.game.get_real_potions()
            if self._token(getattr(potion, "potion_id", "")) in {
                "blockpotion", "fairypotion", "ghostinajar",
                "weakpotion", "dexteritypotion", "focuspotion",
            }
        )
        relief = min(
            10.0,
            defensive_cards * 1.25
            + upgraded_defense * 0.75
            + defensive_potions * 3.0,
        )
        return max(20.0, peak - relief)

    def _question_room_value_components(self, projected_hp=None):
        """State-dependent expected value for an unknown map room.

        A question mark is not merely a low-damage blank floor.  Base-game
        events can grant relics, remove/transform/upgrade cards, give gold, or
        replace a combat with a safer resource conversion.  Keep the estimate
        conservative because adverse events and event fights still exist.
        """

        hp = max(
            0,
            int(
                self.game.current_hp
                if projected_hp is None
                else projected_hp
            ),
        )
        max_hp = max(1, int(getattr(self.game, "max_hp", hp) or hp or 1))
        hp_ratio = min(1.0, hp / max_hp)
        act = max(1, int(getattr(self.game, "act", 1) or 1))
        deck = list(getattr(self.game, "deck", []) or [])
        curses = sum(
            1 for card in deck
            if getattr(card, "rarity", None)
            == spirecomm.spire.card.CardRarity.CURSE
        )
        starters = sum(
            1 for card in deck
            if getattr(card, "rarity", None)
            == spirecomm.spire.card.CardRarity.BASIC
        )
        base_event_value = {
            1: 24.0, 2: 40.0, 3: 38.0, 4: 15.0,
        }.get(act, 30.0)
        relic_opportunity_value = {
            1: 7.0, 2: 6.0, 3: 5.0, 4: 0.0,
        }.get(act, 4.0)
        deck_operation_value = min(
            10.0,
            curses * 4.0 + max(0, starters - 5) * 0.6,
        )
        combat_avoidance_value = max(0.0, 0.75 - hp_ratio) * 24.0
        uncertainty_risk = {
            1: 3.0, 2: 4.0, 3: 5.0, 4: 3.0,
        }.get(act, 4.0)
        return {
            "base_event_value": base_event_value,
            "relic_opportunity_value": relic_opportunity_value,
            "deck_operation_value": deck_operation_value,
            "combat_avoidance_value": combat_avoidance_value,
            "uncertainty_risk": -uncertainty_risk,
        }

    def score_map_node(
        self, node, projected_hp=None, projected_upgrade_ids=None
    ):
        current_hp = max(
            0,
            int(
                self.game.current_hp
                if projected_hp is None
                else projected_hp
            ),
        )
        hp_ratio = current_hp / max(1, self.game.max_hp)
        projected_floor = max(
            1,
            int(getattr(node, "y", -1) or -1) + 1,
        )
        potion_count = len(self.game.get_real_potions())
        upgraded = sum(1 for card in self.game.deck if card.upgrades > 0)
        non_basic = sum(1 for card in self.game.deck if card.rarity not in {spirecomm.spire.card.CardRarity.BASIC, spirecomm.spire.card.CardRarity.CURSE})
        deck_readiness = non_basic + upgraded * 0.5 + potion_count
        universal_readiness = self._deck_readiness()
        boss_entry = self._boss_entry_readiness()

        if node.symbol == "R":
            chosen, values, details = self._route_campfire_choice(
                node,
                current_hp,
                projected_upgrade_ids=projected_upgrade_ids,
            )
            if details["mandatory_recall"]:
                return 105
            if details["scheduled_recall"]:
                # Make a reachable safe Recall window visible to route
                # planning; otherwise it may prefer a generic event/shop and
                # recreate the final-fire key debt this policy prevents.
                return 80 if self.game.act == 2 else 90
            if (
                chosen == RestOption.REST
                and details["actual_recovery"] > 0
            ):
                return 120 if hp_ratio < 0.55 else 65 if hp_ratio < 0.8 else 20
            if chosen == RestOption.REST:
                return 0
            if chosen is None:
                return 0
            return 10 + max(0.0, values.get(chosen, 0.0))
        if node.symbol == "$":
            return 65 if self.game.gold >= 150 else 25 if self.game.gold >= 75 else -10
        if node.symbol == "?":
            return sum(
                self._question_room_value_components(
                    projected_hp=current_hp
                ).values()
            )
        if node.symbol == "M":
            if self.game.act == 1 and projected_floor < 8:
                # Guaranteed cards and gold are most valuable while the deck
                # still lacks an Act 1 damage plan.  Once that development gap
                # is closed, do not keep paying for hallway fights over events
                # solely because of the old unconditional 35-point constant.
                development_gap = max(
                    0.0,
                    1.0 - min(1.0, self._act1_elite_readiness()),
                )
                return 20.0 + 15.0 * development_gap
            if self.goal_mode == "HEART":
                # Heart attempts still need cards, gold, and potions after the
                # prerequisite flags are complete.  Value additional combats
                # by the deck's remaining development gap instead of applying
                # the old unlock-only blanket penalty.
                target_readiness = 8 + self.game.act * 2
                development_gap = max(0.0, target_readiness - deck_readiness)
                readiness_gap = max(
                    0.0,
                    1.0 - float(universal_readiness.get("score", 0.0) or 0.0),
                )
                return min(
                    34.0,
                    4.0 + development_gap * 2.4 + readiness_gap * 12.0,
                )
            # Unlock-only runs need no optional Act 2/3 combat rewards.  A
            # negative value makes the look-ahead prefer events, shops and
            # rest sites when a safer branch exists, while still accepting a
            # forced monster node.
            return -25 if self.game.act >= 3 else -5
        if node.symbol == "E":
            heart_plan = HeartPlan.from_game(self.game, self.goal_mode)
            class_threshold = {
                PlayerClass.IRONCLAD: 0.62,
                PlayerClass.THE_SILENT: 0.72,
                PlayerClass.DEFECT: 0.70,
            }.get(self.chosen_class, 0.72)
            absolute_threshold = {1: 30, 2: 40, 3: 48, 4: 55}.get(self.game.act, 40)
            healthy = (
                hp_ratio >= class_threshold + 0.06 * max(0, self.game.act - 1)
                and current_hp >= absolute_threshold
            )
            if self.game.act == 1:
                # Front-loaded damage is the actual Act 1 elite gate.  Counting
                # every non-basic card made healthy decks with three good
                # attacks look unready, while weak utility cards inflated it.
                act1_readiness = self._act1_elite_readiness()
                ready = act1_readiness >= 1.0
            else:
                defensive_count = sum(
                    1 for card in self.game.deck if self.priorities.is_card_defensive(card)
                )
                ready = (
                    deck_readiness >= 4 + self.game.act * 2
                    and defensive_count >= self.game.act
                )
                if self.goal_mode == "HEART" and self.game.act >= 2:
                    # A Heart run cannot spend every Act 2/3 branch on generic
                    # card count; require a minimally viable answer profile.
                    ready = ready and (
                        float(boss_entry.get("score", 0.0) or 0.0) >= 0.35
                    )
            if self.game.act == 1 and healthy:
                # Preserve the old endpoints (-100 fully unready, +70 fully
                # ready) while removing the cliff at the boolean boundary.
                # Survival remains governed by the independent HP/reserve
                # gates in make_map_choice.
                score = -100.0 + 170.0 * act1_readiness
                if 5 <= projected_floor <= 11:
                    score += 15.0 * act1_readiness
            else:
                score = 70 if healthy and ready else -100
            past_elites = len(self.elite_visits_by_act.get(int(self.game.act), set()))
            score -= past_elites * (35 if self.game.act == 1 else 50)
            score += heart_plan.emerald_bonus(
                burning=bool(getattr(node, "has_emerald_key", False)),
                healthy=healthy,
                ready=ready,
                floor_in_act=projected_floor,
            )
            return score
        return 0

    def _high_gold_shop_route_bonus(self):
        """Value the first reachable shop as a way to convert idle gold.

        Four of the six fixed-hash runs died holding 188--643 gold.  The old
        map search valued every shop at the same 65 points once gold reached
        150, so even a Neow-sized purse could bypass a nearby shop for one more
        reward room.  Apply a smooth, capped conversion bonus to the first
        safe shop in a look-ahead path; later shops do not repeatedly spend
        the same purse.
        """

        gold = max(0, int(getattr(self.game, "gold", 0) or 0))
        if gold < 150:
            return 0.0
        # At roughly one Neow gold reward, conversion is no longer a small
        # convenience: it is the main value of the route.  Keep the bonus
        # smooth below that point, but make a safe first shop strong enough to
        # beat an otherwise attractive extra hallway/event branch.
        return min(120.0, 20.0 + (gold - 150) * 0.80)

    def _shop_arrival_survival_floor(self, *, immediate_shop=False):
        """Return the arrival floor without charging untraversed combat risk.

        An immediately selectable shop has no intervening encounter, so any
        positive HP permits resource conversion. A future shop still needs a
        conservative reserve to survive the encounters before it. Neither
        case certifies survival of the route after buying unknown inventory.
        """

        if immediate_shop:
            return 1.0
        max_hp = max(
            1.0,
            float(getattr(self.game, "max_hp", 1) or 1),
        )
        critical_absolute_hp = {
            1: 22.0,
            2: 32.0,
            3: 38.0,
            4: 45.0,
        }.get(int(getattr(self.game, "act", 0) or 0), 32.0)
        # Keep the boundary proportional for unusually large/small max-HP
        # runs while retaining the act-specific emergency signal.
        return min(
            max_hp * 0.55,
            max(8.0, critical_absolute_hp * 0.75, max_hp * 0.35),
        )

    def _best_first_shop_arrival_hp(
        self,
        node,
        *,
        start_hp=None,
        depth=15,
        lament_charges=None,
        emerald_pending=None,
    ):
        """Best survivable HP on reaching the first shop in a route."""

        if start_hp is None:
            start_hp = max(
                0.0, float(getattr(self.game, "current_hp", 0) or 0)
            )
        if lament_charges is None:
            lament_charges = self._neow_lament_charges()
        if emerald_pending is None:
            emerald_pending = HeartPlan.from_game(
                self.game, self.goal_mode
            ).must_preserve_emerald_route()
        max_hp = max(
            1.0, float(getattr(self.game, "max_hp", start_hp) or start_hp)
        )

        def best_arrival(
            raw_node, hp, remaining_depth, charges, pending_emerald, seen,
        ):
            full_node = self._map_node(raw_node)
            key = (
                full_node.x,
                full_node.y,
                remaining_depth,
                charges,
                pending_emerald,
                int(hp),
            )
            if key in seen:
                return None
            if full_node.symbol == "$":
                return max(0.0, float(hp))
            if remaining_depth <= 0:
                return None
            next_seen = set(seen)
            next_seen.add(key)
            lament_combat = (
                full_node.symbol in {"M", "E"} and charges > 0
            )
            hp_after = float(hp) - self._estimated_survival_room_cost(
                full_node, lament_combat=lament_combat
            )
            if hp_after <= 0:
                return None
            if full_node.symbol == "R":
                chosen, _, details = self._route_campfire_choice(
                    full_node, hp_after
                )
                if chosen == RestOption.REST:
                    hp_after = min(
                        max_hp, hp_after + details["actual_recovery"]
                    )
            eligible_children, next_emerald_pending = (
                self._emerald_constrained_children(
                    full_node, pending_emerald
                )
            )
            next_charges = charges - 1 if lament_combat else charges
            arrivals = []
            for child in eligible_children:
                arrival = best_arrival(
                    child,
                    hp_after,
                    remaining_depth - 1,
                    next_charges,
                    next_emerald_pending,
                    next_seen,
                )
                if arrival is not None:
                    arrivals.append(arrival)
            return max(arrivals, default=None)

        return best_arrival(
            node,
            float(start_hp),
            depth,
            lament_charges,
            bool(emerald_pending),
            set(),
        )

    def _map_node(self, node):
        return self.game.map.get_node(node.x, node.y) or node

    def _path_survival_risk(
        self, node, depth=8, lament_charges=None, emerald_pending=None
    ):
        """Minimum projected HP attrition across the reachable subtree.

        A campfire restores HP but is not an absorbing endpoint: a forced
        elite immediately after Rest still contributes its expected cost.
        """

        if lament_charges is None:
            lament_charges = self._neow_lament_charges()
        start_hp = max(0.0, float(getattr(self.game, "current_hp", 0) or 0))
        max_hp = max(1.0, float(getattr(self.game, "max_hp", start_hp) or start_hp))
        if emerald_pending is None:
            emerald_pending = HeartPlan.from_game(
                self.game, self.goal_mode
            ).must_preserve_emerald_route()

        def best_remaining(
            raw_node,
            hp,
            remaining_depth,
            charges,
            pending_emerald,
            pending_ruby,
            seen,
        ):
            full_node = self._map_node(raw_node)
            key = (
                full_node.x,
                full_node.y,
                remaining_depth,
                charges,
                pending_emerald,
                pending_ruby,
                int(hp),
            )
            if key in seen:
                return hp
            next_seen = set(seen)
            next_seen.add(key)
            lament_combat = full_node.symbol in {"M", "E"} and charges > 0
            room_cost = self._estimated_survival_room_cost(
                full_node, lament_combat=lament_combat
            )
            next_charges = charges - 1 if lament_combat else charges
            # Preserve a negative death margin instead of clamping every
            # lethal branch to zero.  Otherwise a route that misses survival
            # by 2 HP is indistinguishable from one that misses by 40 HP, and
            # all mandatory-key routes collapse to the same risk score.
            hp_after = hp - room_cost
            next_ruby_pending = pending_ruby
            if full_node.symbol == "R":
                chosen, _, details = self._route_campfire_choice(
                    full_node, hp_after, ruby_pending=pending_ruby
                )
                if chosen == RestOption.RECALL:
                    next_ruby_pending = False
                if chosen == RestOption.REST:
                    hp_after = min(
                        max_hp, hp_after + details["actual_recovery"]
                    )
            if remaining_depth <= 0 or hp_after <= 0:
                return hp_after
            eligible_children, next_emerald_pending = (
                self._emerald_constrained_children(
                    full_node, pending_emerald
                )
            )
            if not eligible_children:
                # Ending a branch before the mandatory Act 3 burning elite is
                # not a survivable Heart route, even if it preserves more HP.
                return 0.0 if next_emerald_pending else hp_after
            return max(
                best_remaining(
                    child, hp_after, remaining_depth - 1,
                    next_charges, next_emerald_pending, next_ruby_pending, next_seen,
                )
                for child in eligible_children
            )

        remaining_hp = best_remaining(
            node,
            start_hp,
            depth,
            lament_charges,
            emerald_pending,
            HeartPlan.from_game(self.game, self.goal_mode).ruby_missing,
            set(),
        )
        return max(0.0, start_hp - remaining_hp)

    def _subtree_has_emerald_elite(self, node, depth=15, seen=None):
        full_node = self._map_node(node)
        if getattr(full_node, "has_emerald_key", False):
            return True
        if depth <= 0:
            return False
        seen = set() if seen is None else set(seen)
        key = (full_node.x, full_node.y)
        if key in seen:
            return False
        seen.add(key)
        return any(
            self._subtree_has_emerald_elite(child, depth - 1, seen)
            for child in full_node.children
        )


    def _emerald_constrained_children(self, node, emerald_pending):
        """Keep only branches that preserve a mandatory Emerald-key route."""

        full_node = self._map_node(node)
        next_pending = bool(
            emerald_pending
            and not getattr(full_node, "has_emerald_key", False)
        )
        children = list(full_node.children)
        if next_pending:
            children = [
                child
                for child in children
                if self._subtree_has_emerald_elite(child)
            ]
        return children, next_pending

    def generate_map_route(self):
        best_rewards = {0: {node.x: self.score_map_node(node) for node in self.game.map.nodes[0].values()}}
        best_parents = {0: {node.x: 0 for node in self.game.map.nodes[0].values()}}
        map_height = max(self.game.map.nodes.keys())
        for y in range(0, map_height):
            best_rewards[y+1] = {node.x: -10 ** 9 for node in self.game.map.nodes[y+1].values()}
            best_parents[y+1] = {node.x: -1 for node in self.game.map.nodes[y+1].values()}
            for x in best_rewards[y]:
                node = self.game.map.get_node(x, y)
                best_node_reward = best_rewards[y][x]
                for child in node.children:
                    test_child_reward = best_node_reward + self.score_map_node(child)
                    if test_child_reward > best_rewards[y+1][child.x]:
                        best_rewards[y+1][child.x] = test_child_reward
                        best_parents[y+1][child.x] = node.x
        best_path = [0] * (map_height + 1)
        best_path[map_height] = max(best_rewards[map_height].keys(), key=lambda x: best_rewards[map_height][x])
        for y in range(map_height, 0, -1):
            best_path[y - 1] = best_parents[y][best_path[y]]
        self.map_route = best_path

    def make_map_choice(self):
        if self.game.screen.boss_available:
            act = int(getattr(self.game, "act", 0) or 0)
            self._record_noncombat_decision(
                "map_forced_boss_entry",
                [{
                    "id": "map:boss",
                    "choice_id": "map:boss",
                    "choice_index": 0,
                    "action": "choose",
                    "operation": None,
                    "semantic_id": "map_boss:0",
                    "score": 0.0,
                    "label": f"Boss@Act{act}",
                    "legal": True,
                    "visible": True,
                    "selection_eligible": True,
                    "veto_reason": None,
                    "reason": "forced_boss_entry",
                    "consequences": {
                        "route": {"boss": True, "act": act},
                    },
                    **self._linear_score_contract(
                        "map_forced_boss_entry_v1",
                        {"forced_entry_value": 0.0},
                        ((
                            "forced_entry_value",
                            "forced_entry_value",
                            1.0,
                        ),),
                    ),
                }],
                candidate_contract={
                    "score_source": "forced_protocol_choice",
                    "strategy_quality_auditable": True,
                    "all_visible_options_scored": True,
                    "visible_option_count": 1,
                    "selection_eligible_count": 1,
                    "filtered_options_retained": True,
                    "identity_source": "protocol_choice_index_and_act",
                },
                chosen=f"Boss@Act{act}",
                chosen_id="map:boss",
            )
            return ChooseMapBossAction()
        if not self.game.screen.next_nodes:
            return ChooseAction(0)

        # Keep the complete protocol-visible surface immutable. Strategy
        # gates may make a node ineligible, but must never erase it from the
        # evidence supplied to the model/auditor.
        visible_nodes = sorted(
            list(self.game.screen.next_nodes),
            key=lambda node: (
                int(getattr(node, "y", 0) or 0),
                int(getattr(node, "x", 0) or 0),
                str(getattr(node, "symbol", "?")),
            ),
        )
        candidates = list(visible_nodes)
        visible_choice_indexes = {
            (node.x, node.y): index
            for index, node in enumerate(visible_nodes)
        }
        veto_reasons = {
            (node.x, node.y): [] for node in visible_nodes
        }

        def retain_nodes(kept, reason):
            """Apply a strategy veto while preserving visible candidates."""

            kept_keys = {(node.x, node.y) for node in kept}
            for node in candidates:
                key = (node.x, node.y)
                if key not in kept_keys:
                    veto_reasons[key].append(reason)
            return [
                node for node in candidates
                if (node.x, node.y) in kept_keys
            ]
        hp_ratio = self.game.current_hp / max(1, self.game.max_hp)
        current_hp = max(0, int(self.game.current_hp or 0))
        current_node = getattr(self.game.screen, "current_node", None)
        initial_lament_charges = self._neow_lament_charges()
        boss_entry = self._boss_entry_readiness()
        universal_readiness = self._deck_readiness()
        if current_node is not None and current_node.symbol == "E":
            self.elite_visits_by_act.setdefault(int(self.game.act), set()).add(
                (current_node.x, current_node.y)
            )
        heart_plan = HeartPlan.from_game(self.game, self.goal_mode)
        emerald_required = heart_plan.must_preserve_emerald_route()
        emerald_pending = emerald_required
        key_routes = []
        emerald_route_reachable = None
        emerald_route_safe = None
        emerald_route_reserve = None
        emerald_shop_bridge_admission = False
        if emerald_required:
            key_routes = [node for node in candidates if self._subtree_has_emerald_elite(node)]
            emerald_route_reachable = bool(key_routes)
            if key_routes:
                if int(self.game.act) == 2:
                    # Preserve the earlier key window only when its best
                    # reachable branch retains a real post-route HP reserve.
                    # This makes Act 2 the planning deadline without turning
                    # a visibly lethal burning elite into a forced loss.
                    ascension = max(
                        0,
                        int(
                            getattr(self.game, "ascension_level", 0)
                            or 0
                        ),
                    )
                    reserve = (
                        max(6.0, float(self.game.max_hp) * 0.075)
                        if ascension == 0
                        else max(10.0, float(self.game.max_hp) * 0.12)
                    )
                    emerald_route_reserve = reserve
                    safe_key_routes = [
                        node
                        for node in key_routes
                        if self._path_survival_risk(
                            node, emerald_pending=True
                        ) + reserve <= current_hp
                    ]
                    emerald_route_safe = bool(safe_key_routes)
                    shop_bridge_routes = []
                    if int(getattr(self.game, "gold", 0) or 0) >= 300:
                        shop_bridge_routes = [
                            node
                            for node in key_routes
                            if (
                                self._best_first_shop_arrival_hp(
                                    node,
                                    start_hp=current_hp,
                                    emerald_pending=True,
                                )
                                or -1
                            ) >= self._shop_arrival_survival_floor(
                                immediate_shop=node.symbol == "$"
                            )
                        ]
                    safe_keys = {
                        (node.x, node.y) for node in safe_key_routes
                    }
                    admitted_key_routes = list(safe_key_routes)
                    admitted_key_routes.extend(
                        node
                        for node in shop_bridge_routes
                        if (node.x, node.y) not in safe_keys
                    )
                    emerald_shop_bridge_admission = any(
                        (node.x, node.y) not in safe_keys
                        for node in shop_bridge_routes
                    )
                    if admitted_key_routes:
                        candidates = retain_nodes(
                            admitted_key_routes,
                            "emerald_route_reserve_or_safe_shop",
                        )
                    else:
                        # Survival fallback must use the same risk check for
                        # every entrance. Avoiding the burning elite alone
                        # does not make an immediate ordinary elite safe.
                        survival_fallback_routes = [
                            node for node in candidates
                            if self._path_survival_risk(
                                node, emerald_pending=False
                            ) + reserve <= current_hp
                        ]
                        if survival_fallback_routes:
                            emerald_pending = False
                            candidates = retain_nodes(
                                survival_fallback_routes,
                                "unsafe_emerald_route_reserve",
                            )
                        elif len(candidates) > 1:
                            # No route is certified safe. Keep all visible
                            # alternatives and let recovery/attrition scoring
                            # rank them without the Act 2 key deadline bonus.
                            emerald_pending = False
                else:
                    # In Act 3, a route that abandons the last burning elite
                    # cannot satisfy the objective and remains a hard bound.
                    # Keep that objective constraint separate from the
                    # truthful safety observation: a low-HP route can be
                    # mandatory for the Heart attempt without being safe.
                    reserve = max(
                        8.0, float(self.game.max_hp) * 0.10
                    )
                    emerald_route_reserve = reserve
                    emerald_route_safe = any(
                        self._path_survival_risk(
                            node, emerald_pending=True
                        ) + reserve <= current_hp
                        for node in key_routes
                    )
                    candidates = retain_nodes(
                        key_routes,
                        "act3_emerald_route_required",
                    )
            else:
                # The Heart objective is already impossible in this run.  Do
                # not disable ordinary survival guards or assign zero HP to
                # every remaining branch while chasing a key that no subtree
                # can reach; maximize the chance to win Act 3 instead.
                emerald_pending = False
                emerald_route_safe = False
        # Once the Emerald key is secured, late Act 3 elites add substantial
        # variance without advancing the Heart objective.  Preserve forced
        # elites, but take an available non-elite branch from floor 7 onward.
        if (
            heart_plan.active
            and int(self.game.act) == 3
            and not heart_plan.emerald_missing
            and any(int(getattr(node, "y", 0) or 0) >= 6 for node in candidates)
        ):
            non_elites = [node for node in candidates if node.symbol != "E"]
            if non_elites:
                candidates = retain_nodes(
                    non_elites,
                    "emerald_key_secured_avoid_late_elite",
                )
        # Neow's Lament is an authoritative combat guarantee, so preserve a
        # reachable one-HP elite before ordinary HP-based combat vetoes run.
        # In particular, with one charge left an immediately selectable elite
        # costs no normal elite attrition; applying the generic reserve gate
        # first wastes the final charge on the non-elite branch instead.
        lament_elite_routes = {
            (node.x, node.y): self._neow_lament_elite_route(
                node,
                initial_lament_charges,
                emerald_pending=emerald_pending,
            )
            for node in visible_nodes
        } if initial_lament_charges > 0 else {}
        lament_elite_candidates = [
            node for node in candidates
            if lament_elite_routes.get((node.x, node.y)) is not None
        ]
        lament_elite_route_forced = bool(
            lament_elite_candidates
            and len(lament_elite_candidates) < len(candidates)
        )
        if lament_elite_candidates:
            candidates = retain_nodes(
                lament_elite_candidates,
                "neow_lament_one_hp_elite_route",
            )

        # Future rests/rewards must never make an immediately dangerous elite
        # look acceptable while a non-elite entrance is available.  Lament
        # routes above are exempt because every combat through the guaranteed
        # elite is explicitly covered by a remaining one-HP charge.
        elite_absolute_floor = {1: 30, 2: 40, 3: 48, 4: 55}.get(self.game.act, 40)
        if not emerald_pending and not lament_elite_candidates:
            non_elites = [node for node in candidates if node.symbol != "E"]
            if non_elites:
                reserve = max(8.0, self.game.max_hp * 0.10)
                kept = [
                    node
                    for node in candidates
                    if node.symbol != "E"
                    or self._estimated_survival_room_cost(node) + reserve
                    < current_hp
                ] or non_elites
                candidates = retain_nodes(
                    kept, "elite_immediate_survival_reserve"
                )
        if (
            not emerald_pending
            and not lament_elite_candidates
            and (hp_ratio < 0.72 or current_hp < elite_absolute_floor)
        ):
            non_elites = [node for node in candidates if node.symbol != "E"]
            if non_elites:
                candidates = retain_nodes(
                    non_elites, "low_hp_voluntary_elite_veto"
                )
        # At critical HP, prefer any non-combat entrance over a voluntary
        # monster room.  Forced combats remain legal and are still handled.
        critical_absolute_hp = {1: 22, 2: 32, 3: 38, 4: 45}.get(self.game.act, 32)
        if (
            not emerald_pending
            and not lament_elite_candidates
            and (hp_ratio < 0.35 or current_hp < critical_absolute_hp)
        ):
            safe_nodes = [node for node in candidates if node.symbol not in {"M", "E"}]
            if safe_nodes:
                candidates = retain_nodes(
                    safe_nodes, "critical_hp_combat_entrance_veto"
                )

        safe_shop_arrivals = {}
        high_gold_shop_admission = False
        if int(getattr(self.game, "gold", 0) or 0) >= 300:
            for node in candidates:
                arrival_hp = self._best_first_shop_arrival_hp(
                    node,
                    start_hp=current_hp,
                    emerald_pending=emerald_pending,
                )
                if arrival_hp is not None:
                    safe_shop_arrivals[(node.x, node.y)] = arrival_hp
            safe_shop_roots = [
                node for node in candidates
                if safe_shop_arrivals.get((node.x, node.y), -1)
                >= self._shop_arrival_survival_floor(
                    immediate_shop=node.symbol == "$"
                )
            ]
            if safe_shop_roots:
                high_gold_shop_admission = True
                candidates = retain_nodes(
                    safe_shop_roots, "high_gold_safe_shop_conversion"
                )

        survival_risks = {(
            node.x, node.y
        ): self._path_survival_risk(
            node, emerald_pending=emerald_pending
        ) for node in visible_nodes}
        if (hp_ratio < 0.60 or current_hp < critical_absolute_hp + 10) and len(candidates) > 1:
            minimum_risk = min(survival_risks.values())
            tolerance = (
                0.0
                if emerald_pending
                else 0.25 if hp_ratio < 0.48 else 1.0
            )
            safer = [
                node for node in candidates
                if survival_risks[(node.x, node.y)] <= minimum_risk + tolerance
            ]
            if safer:
                candidates = retain_nodes(
                    safer, "path_survival_risk_tolerance"
                )

        memo = {}
        act1_elite_readiness = (
            self._act1_elite_readiness()
            if int(self.game.act) == 1 else 0.0
        )
        past_act1_elites = len(
            self.elite_visits_by_act.get(int(self.game.act), set())
        )
        first_act1_elite_development_bonus = (
            min(80.0, 160.0 * act1_elite_readiness)
            if int(self.game.act) == 1 and past_act1_elites == 0
            else 0.0
        )
        first_act1_elite_development_reserve = max(
            8.0, float(self.game.max_hp) * 0.10
        )
        boss_terminal_score_weight = 120.0

        def future_score(
            node,
            projected_hp,
            combat_streak=0,
            rooms_since_rest=0,
            future_elites=0,
            lament_charges=initial_lament_charges,
            pending_emerald=emerald_pending,
            shop_budget_available=True,
            projected_upgrade_ids=(),
        ):
            projected_upgrade_ids = tuple(sorted(projected_upgrade_ids))
            key = (
                node.x,
                node.y,
                combat_streak,
                min(rooms_since_rest, 6),
                future_elites,
                lament_charges,
                pending_emerald,
                shop_budget_available,
                projected_upgrade_ids,
                int(projected_hp),
            )
            if key in memo:
                return memo[key]
            full_node = self.game.map.get_node(node.x, node.y) or node
            lament_combat = (
                full_node.symbol in {"M", "E"} and lament_charges > 0
            )
            next_lament_charges = (
                lament_charges - 1 if lament_combat else lament_charges
            )
            arrival_hp = max(0.0, float(projected_hp))
            if full_node.symbol == "R" and projected_upgrade_ids:
                room_score = self.score_map_node(
                    full_node,
                    projected_hp=arrival_hp,
                    projected_upgrade_ids=projected_upgrade_ids,
                )
            else:
                room_score = self.score_map_node(
                    full_node, projected_hp=arrival_hp
                )
            shop_arrival_floor = self._shop_arrival_survival_floor(
                immediate_shop=(
                    full_node.symbol == "$"
                    and (full_node.x, full_node.y) in visible_choice_indexes
                )
            )
            shop_arrival_unsafe = bool(
                full_node.symbol == "$"
                and shop_budget_available
                and arrival_hp < shop_arrival_floor
            )
            if full_node.symbol == "$" and shop_budget_available:
                if not shop_arrival_unsafe:
                    room_score += self._high_gold_shop_route_bonus()
                else:
                    # A shop below the survival floor is not an actionable
                    # resource conversion; preserve the evidence but do not
                    # let idle gold outweigh a route that can still be lived.
                    room_score -= min(
                        80.0,
                        (shop_arrival_floor - arrival_hp) * 2.0,
                    )
            next_shop_budget_available = bool(
                shop_budget_available and full_node.symbol != "$"
            )
            hp_after = max(
                0.0,
                arrival_hp
                - self._estimated_map_room_cost(
                    full_node, lament_combat=lament_combat
                ),
            )
            campfire_restores = False
            next_projected_upgrade_ids = projected_upgrade_ids
            if full_node.symbol == "R":
                campfire_choice, _, campfire_details = (
                    self._route_campfire_choice(
                        full_node,
                        hp_after,
                        projected_upgrade_ids=projected_upgrade_ids,
                    )
                )
                if (
                    campfire_choice == RestOption.REST
                    and campfire_details["actual_recovery"] > 0
                ):
                    campfire_restores = True
                    hp_after = min(
                        float(self.game.max_hp),
                        hp_after + campfire_details["actual_recovery"],
                    )
                elif campfire_choice == RestOption.SMITH:
                    projection_id = campfire_details.get(
                        "best_upgrade_projection_id"
                    )
                    if projection_id is not None:
                        next_projected_upgrade_ids = tuple(sorted({
                            *projected_upgrade_ids,
                            projection_id,
                        }))
            if full_node.symbol in {"M", "E"}:
                next_streak = 0 if lament_combat else combat_streak + 1
                next_rooms_since_rest = rooms_since_rest + 1
            elif full_node.symbol == "R":
                next_streak = 0
                next_rooms_since_rest = (
                    0
                    if campfire_restores
                    else rooms_since_rest + 1
                )
            else:
                next_streak = 0
                next_rooms_since_rest = rooms_since_rest + 1
            next_future_elites = future_elites + (1 if full_node.symbol == "E" else 0)
            attrition_penalty = max(0, next_streak - 1) * (
                18 if self.game.act >= 2 else 10
            )
            if full_node.symbol == "E" and combat_streak > 0 and not lament_combat:
                attrition_penalty += 20
            if full_node.symbol == "E" and next_future_elites > 1:
                attrition_penalty += (next_future_elites - 1) * (55 if self.game.act == 1 else 75)
            if full_node.y >= 11 and next_rooms_since_rest >= 6:
                attrition_penalty += 15
            eligible_children, next_emerald_pending = (
                self._emerald_constrained_children(
                    full_node, pending_emerald
                )
            )
            if shop_arrival_unsafe and eligible_children:
                child_score = -1000.0
            elif next_emerald_pending and not eligible_children:
                child_score = -1000.0
            elif hp_after <= 0 and eligible_children:
                child_score = -1000.0
            else:
                if eligible_children:
                    child_score = max(
                        future_score(
                            child,
                            hp_after,
                            next_streak,
                            next_rooms_since_rest,
                            next_future_elites,
                            next_lament_charges,
                            next_emerald_pending,
                            next_shop_budget_available,
                            next_projected_upgrade_ids,
                        )
                        for child in eligible_children
                    )
                elif int(getattr(full_node, "y", -1) or -1) >= 14:
                    if hp_after <= 0:
                        child_score = -1000.0
                    else:
                        terminal_readiness = self._boss_entry_readiness(
                            projected_hp=hp_after
                        )
                        terminal_progress = terminal_readiness.get(
                            "progress_score"
                        )
                        if terminal_progress is None:
                            terminal_progress = terminal_readiness.get(
                                "score", 0.0
                            )
                        child_score = (
                            boss_terminal_score_weight
                            * float(terminal_progress or 0.0)
                        )
                else:
                    child_score = 0.0
            if lament_combat and full_node.symbol == "M":
                room_score = max(room_score, 45)
            elif lament_combat and full_node.symbol == "E":
                # A deterministic one-HP elite is worth routing toward even
                # before the ordinary damage-readiness gate is satisfied.
                room_score = max(room_score, 155)
            elif (
                full_node.symbol == "E"
                and int(self.game.act) == 1
                and past_act1_elites == 0
                and next_future_elites == 1
                and arrival_hp
                > self._estimated_survival_room_cost(
                    full_node, lament_combat=lament_combat
                ) + first_act1_elite_development_reserve
                and int(getattr(full_node, "y", -1) or -1) + 1 <= 11
            ):
                # The first safe elite is the main early relic/gold
                # development window.  Authorize that value only from the
                # projected HP arriving at this exact elite; a safe sibling
                # branch must not lend its reserve to an unsafe elite branch.
                # Never lift the room above the old fully-ready endpoint.
                room_score += min(
                    first_act1_elite_development_bonus,
                    max(0.0, 85.0 - room_score),
                )
            # Slight discount prevents a long chain of mediocre rooms from
            # outweighing an immediate survival-critical rest site.
            value = room_score - attrition_penalty + 0.92 * child_score
            memo[key] = value
            return value

        initial_streak = 1 if current_node is not None and current_node.symbol in {"M", "E"} else 0
        initial_rooms_since_rest = (
            0
            if current_node is not None
            and current_node.symbol == "R"
            and self._campfire_will_restore(current_node, self.game.current_hp)
            else 2
        )

        attrition_weight = 18 if hp_ratio < 0.48 else 8 if hp_ratio < 0.65 else 2
        eligible_keys = {(node.x, node.y) for node in candidates}
        raw_scored_candidates = [
            (
                future_score(
                    node,
                    current_hp,
                    initial_streak,
                    initial_rooms_since_rest,
                )
                - survival_risks.get(
                    (node.x, node.y),
                    self._path_survival_risk(
                        node, emerald_pending=emerald_pending
                    ),
                ) * attrition_weight,
                node,
            )
            for node in visible_nodes
        ]
        # A vetoed node remains visible and scored, but receives an effective
        # score that cannot be revived by model fusion. ``raw_local_score``
        # below preserves the independently recomputable route utility.
        all_scored_candidates = [
            (
                (
                    score
                    if (node.x, node.y) in eligible_keys
                    else min(float(score), -1000000.0)
                ),
                node,
                score,
            )
            for score, node in raw_scored_candidates
        ]
        scored_candidates = [
            (score, node)
            for score, node, _ in all_scored_candidates
            if (node.x, node.y) in eligible_keys
        ]
        _, chosen = max(scored_candidates, key=lambda item: (item[0], -item[1].x))
        map_by_id = {
            f"map:{node.x},{node.y}": node
            for _, node, _ in all_scored_candidates
        }

        def route_summary(entrance, depth_limit=8, path_limit=192):
            """Expose real connected paths, never a union of branches.

            The previous depth histogram could put a rest from one branch and
            an elite from a mutually exclusive branch into the same apparent
            route.  Three compact, diverse path sequences are both cheaper to
            reason about and factually executable.
            """

            completed = []
            depth_cutoff = False
            frontier = [(
                entrance, [], initial_lament_charges, emerald_pending
            )]
            while frontier and len(completed) < path_limit:
                node, prefix, lament_charges, path_emerald_pending = (
                    frontier.pop()
                )
                coord = (int(node.x), int(node.y))
                if coord in {
                    (step["x"], step["y"]) for step in prefix
                }:
                    continue
                symbol = str(getattr(node, "symbol", "?"))
                lament_combat = symbol in {"M", "E"} and lament_charges > 0
                full_node = self.game.map.get_node(*coord) or node
                children, next_emerald_pending = (
                    self._emerald_constrained_children(
                        full_node, path_emerald_pending
                    )
                )
                step = {
                    "symbol": symbol,
                    "x": coord[0],
                    "y": coord[1],
                    "neow_lament_one_hp": bool(lament_combat),
                    "burning_elite": bool(
                        getattr(node, "has_emerald_key", False)
                    ),
                    "estimated_cost": float(
                        self._estimated_map_room_cost(
                            node, lament_combat=lament_combat
                        )
                    ),
                    "emerald_pending_after_node": bool(
                        next_emerald_pending
                    ),
                }
                path = prefix + [step]
                if len(path) >= depth_limit:
                    depth_cutoff = depth_cutoff or bool(children)
                    completed.append(path)
                    continue
                if not children:
                    completed.append(path)
                    continue
                next_lament_charges = (
                    lament_charges - 1 if lament_combat else lament_charges
                )
                frontier.extend(
                    (
                        child,
                        path,
                        next_lament_charges,
                        next_emerald_pending,
                    )
                    for child in children
                )
            enumeration_truncated = bool(frontier) or depth_cutoff
            if not completed:
                entrance_symbol = str(getattr(entrance, "symbol", "?"))
                entrance_lament = (
                    entrance_symbol in {"M", "E"}
                    and initial_lament_charges > 0
                )
                completed = [[{
                    "symbol": entrance_symbol,
                    "x": int(entrance.x),
                    "y": int(entrance.y),
                    "neow_lament_one_hp": bool(entrance_lament),
                    "burning_elite": bool(
                        getattr(entrance, "has_emerald_key", False)
                    ),
                    "estimated_cost": float(
                        self._estimated_map_room_cost(
                            entrance, lament_combat=entrance_lament
                        )
                    ),
                    "emerald_pending_after_node": bool(
                        emerald_pending
                        and not getattr(entrance, "has_emerald_key", False)
                    ),
                }]]

            rows = []
            for path in completed:
                symbols = [step["symbol"] for step in path]
                elite_indexes = [
                    index for index, symbol in enumerate(symbols)
                    if symbol == "E"
                ]
                first_elite = min(elite_indexes, default=None)
                burning_depths = [
                    index
                    for index, step in enumerate(path)
                    if step["burning_elite"]
                ]
                lament_combat_depths = [
                    index
                    for index, step in enumerate(path)
                    if step["neow_lament_one_hp"]
                ]
                lament_elite_depths = [
                    index
                    for index in elite_indexes
                    if path[index]["neow_lament_one_hp"]
                ]
                attrition = sum(step["estimated_cost"] for step in path)
                rows.append({
                    "sequence": [
                        f'{step["symbol"]}@{step["x"]},{step["y"]}'
                        for step in path
                    ],
                    "estimated_attrition_without_healing": round(
                        float(attrition), 2
                    ),
                    "conservative_hp_without_healing": max(
                        0, int(round(current_hp - attrition))
                    ),
                    "rests": symbols.count("R"),
                    "shops": symbols.count("$"),
                    "elites": len(elite_indexes),
                    "neow_lament_one_hp_combat_depths": (
                        lament_combat_depths
                    ),
                    "neow_lament_one_hp_elite_depths": (
                        lament_elite_depths
                    ),
                    "burning_elite_depths": burning_depths,
                    "emerald_pending_after_window": bool(
                        path[-1]["emerald_pending_after_node"]
                    ),
                    "rest_before_first_elite": (
                        any(
                            symbol == "R"
                            for symbol in symbols[:first_elite]
                        )
                        if first_elite is not None else None
                    ),
                })

            selected = []

            def keep(row, basis):
                signature = tuple(row["sequence"])
                if any(tuple(item["sequence"]) == signature for item in selected):
                    return
                selected.append({**row, "selection_basis": basis})

            keep(min(
                rows,
                key=lambda row: (
                    row["estimated_attrition_without_healing"],
                    -row["rests"],
                    tuple(row["sequence"]),
                ),
            ), "lowest_attrition")
            burning_rows = [row for row in rows if row["burning_elite_depths"]]
            if burning_rows:
                keep(min(
                    burning_rows,
                    key=lambda row: (
                        min(row["burning_elite_depths"]),
                        row["estimated_attrition_without_healing"],
                    ),
                ), "earliest_burning_elite")
            lament_elite_rows = [
                row for row in rows
                if row["neow_lament_one_hp_elite_depths"]
            ]
            if lament_elite_rows:
                keep(min(
                    lament_elite_rows,
                    key=lambda row: (
                        min(row["neow_lament_one_hp_elite_depths"]),
                        row["estimated_attrition_without_healing"],
                    ),
                ), "earliest_neow_lament_elite")
            keep(max(
                rows,
                key=lambda row: (
                    3 * row["elites"] + row["rests"] + row["shops"],
                    -row["estimated_attrition_without_healing"],
                ),
            ), "highest_reward_access")
            if len(selected) < 3:
                for row in sorted(
                    rows,
                    key=lambda item: (
                        -item["rests"],
                        item["estimated_attrition_without_healing"],
                        tuple(item["sequence"]),
                    ),
                ):
                    keep(row, "diverse_legal_alternative")
                    if len(selected) >= 3:
                        break
            return {
                "depth_limit": depth_limit,
                "legal_path_options": selected[:3],
                "paths_enumerated": len(completed),
                "enumeration_truncated": enumeration_truncated,
                "earliest_neow_lament_elite": (
                    lament_elite_routes.get(
                        (entrance.x, entrance.y)
                    )
                ),
            }

        selected_id = self._macro_rank(
            "MAP",
            [
                {
                    "candidate_id": f"map:{node.x},{node.y}",
                    "kind": "map_node",
                    "label": f"{node.symbol}@{node.x},{node.y}",
                    "local_score": score,
                    "facts": {
                        "choice_index": visible_choice_indexes[
                            (node.x, node.y)
                        ],
                        "symbol": node.symbol,
                        "x": node.x,
                        "y": node.y,
                        "selection_eligible": (
                            (node.x, node.y) in eligible_keys
                        ),
                        "veto_reason": (
                            ";".join(veto_reasons[(node.x, node.y)])
                            or None
                        ),
                        "raw_local_score": round(float(raw_score), 3),
                        "burning_elite": bool(
                            getattr(node, "has_emerald_key", False)
                        ),
                        "path_survival_risk": round(
                            survival_risks.get((node.x, node.y), 0.0), 3
                        ),
                        "shop_arrival_survival_floor": round(
                            self._shop_arrival_survival_floor(
                                immediate_shop=node.symbol == "$"
                            ), 3
                        ),
                        "boss_entry_readiness": boss_entry,
                        "question_room_value_components": (
                            self._question_room_value_components(
                                projected_hp=current_hp
                            )
                            if node.symbol == "?" else None
                        ),
                        "route_summary": route_summary(node),
                        "consequences": {
                            "route": {
                                "symbol": node.symbol,
                                "x": int(node.x),
                                "y": int(node.y),
                            },
                            "path_survival_risk": round(
                                survival_risks.get(
                                    (node.x, node.y), 0.0
                                ),
                                3,
                            ),
                        },
                    },
                }
                for score, node, raw_score in all_scored_candidates
            ],
            f"map:{chosen.x},{chosen.y}",
            hard_constraints=[
                "ONLY_DETERMINISTICALLY_SAFE_REACHABLE_ENTRANCES",
                "EMERALD_KEY_REACHABILITY_FILTER_ALREADY_APPLIED",
                "DO_NOT_REINTRODUCE_FILTERED_ELITES",
            ],
            state_details={
                "hp_ratio": round(hp_ratio, 3),
                "emerald_required": emerald_required,
                "emerald_route_reachable": emerald_route_reachable,
                "emerald_route_safe": emerald_route_safe,
                "boss_entry_readiness": boss_entry,
                "deck_readiness": universal_readiness,
                "act1_elite_readiness": (
                    round(act1_elite_readiness, 3)
                    if int(self.game.act) == 1 else None
                ),
                "first_act1_elite_development_bonus": round(
                    first_act1_elite_development_bonus, 3
                ),
            },
        )[0]
        if (map_by_id[selected_id].x, map_by_id[selected_id].y) not in eligible_keys:
            # Fail closed if an adviser ever returns a strategy-vetoed route.
            selected_id = f"map:{chosen.x},{chosen.y}"
        chosen = map_by_id[selected_id]
        map_audit_candidates = [
            {
                "id": f"map:{node.x},{node.y}",
                "choice_id": f"map:{node.x},{node.y}",
                "choice_index": visible_choice_indexes[(node.x, node.y)],
                "action": "choose",
                "semantic_id": f"{node.symbol}@{node.x},{node.y}",
                "score": float(score),
                "raw_local_score": float(raw_score),
                "label": f"{node.symbol}@{node.x},{node.y}",
                "legal": True,
                "visible": True,
                "selection_eligible": (
                    (node.x, node.y) in eligible_keys
                ),
                "veto_reason": (
                    ";".join(veto_reasons[(node.x, node.y)]) or None
                ),
                "reason": (
                    "selected_route"
                    if node is chosen
                    else (
                        ";".join(veto_reasons[(node.x, node.y)])
                        or "lower_effective_route_utility"
                    )
                ),
                "consequences": {
                    "route": {
                        "symbol": node.symbol,
                        "x": int(node.x),
                        "y": int(node.y),
                    },
                    "path_survival_risk": round(
                        survival_risks.get((node.x, node.y), 0.0), 3
                    ),
                    "shop_arrival_survival_floor": round(
                        self._shop_arrival_survival_floor(
                            immediate_shop=node.symbol == "$"
                        ), 3
                    ),
                    "first_shop_arrival_hp": (
                        None
                        if (node.x, node.y) not in safe_shop_arrivals
                        else round(
                            safe_shop_arrivals[(node.x, node.y)], 3
                        )
                    ),
                    "route_summary": route_summary(node),
                    "question_room_value_components": (
                        self._question_room_value_components(
                            projected_hp=current_hp
                        )
                        if node.symbol == "?" else None
                    ),
                },
                "uncertainty": (
                    "future room outcomes remain probabilistic"
                ),
                **self._linear_score_contract(
                    "map_effective_route_utility_v1",
                    {
                        "raw_route_utility": raw_score,
                        "veto_adjustment": float(score) - float(raw_score),
                    },
                    (
                        ("raw_route_utility", "raw_route_utility", 1.0),
                        ("veto_adjustment", "veto_adjustment", 1.0),
                    ),
                ),
            }
            for score, node, raw_score in all_scored_candidates
        ]
        self._record_noncombat_decision(
            "map_lookahead_with_survival_constraints",
            map_audit_candidates,
            candidate_contract={
                "score_source": "map_lookahead_effective_utility",
                "strategy_quality_auditable": True,
                "all_visible_options_scored": True,
                "visible_option_count": len(visible_nodes),
                "selection_eligible_count": len(candidates),
                "filtered_options_retained": True,
                "identity_source": "map_coordinates",
            },
            chosen=f"{chosen.symbol}@{chosen.x},{chosen.y}",
            chosen_id=f"map:{chosen.x},{chosen.y}",
            hp_ratio=round(hp_ratio, 3),
            path_risk=round(survival_risks.get((chosen.x, chosen.y), 0), 3),
            shop_arrival_survival_floor=round(
                self._shop_arrival_survival_floor(), 3
            ),
            candidate_path_risks={
                f"{node.symbol}@{node.x},{node.y}": round(
                    survival_risks.get(
                        (node.x, node.y),
                        self._path_survival_risk(
                            node, emerald_pending=emerald_pending
                        ),
                    ), 3
                )
                for node in visible_nodes
            },
            emerald_required=emerald_required,
            emerald_route_reachable=emerald_route_reachable,
            emerald_route_safe=emerald_route_safe,
            emerald_route_reserve=(
                None
                if emerald_route_reserve is None
                else round(emerald_route_reserve, 3)
            ),
            emerald_survival_fallback=bool(
                emerald_required and not emerald_pending
            ),
            emerald_shop_bridge_admission=emerald_shop_bridge_admission,
            emerald_deadline_forced=bool(
                emerald_required
                and int(self.game.act) >= 3
                and emerald_route_reachable
            ),
            neow_lament_charges=initial_lament_charges,
            neow_lament_elite_route_forced=lament_elite_route_forced,
            early_offense_value=round(self._early_offense_value(), 3),
            act1_elite_readiness=(
                round(act1_elite_readiness, 3)
                if int(self.game.act) == 1 else None
            ),
            first_act1_elite_development_bonus=round(
                first_act1_elite_development_bonus, 3
            ),
            high_gold_shop_route_bonus=round(
                self._high_gold_shop_route_bonus(), 3
            ),
            boss_terminal_score_weight=boss_terminal_score_weight,
            high_gold_safe_shop_admission=high_gold_shop_admission,
            act1_elite_ready=(self._act1_elite_ready() if self.game.act == 1 else None),
        )
        return ChooseMapNodeAction(chosen)
